/* Pedidos repetidos reutilizam a operação em caso de falha ou demora. */
var IA_OPERACOES = new Map();
window.IA = {
  ativo: function () { return !!window.IDIOMAS_API && window.AUTH && AUTH.ready(); },
  pedir: function (tipo, dados) {
    var key=tipo+'|'+JSON.stringify(dados), previous=IA_OPERACOES.get(key), now=Date.now();
    if(previous&&previous.promise)return previous.promise;
    var operation=previous&&now-previous.at<5*60000?previous.id:crypto.randomUUID();
    if(tipo==='liveToken')operation=crypto.randomUUID();
    var entry={id:operation,at:now};IA_OPERACOES.set(key,entry);
    entry.promise=AUTH.post({ acao: 'ia', tipo: tipo, dados: dados, requestId:operation }).then(function(r){IA_OPERACOES.delete(key);return r;}).catch(function(e){entry.promise=null;throw e;});
    return entry.promise;
  },
  /* texto da IA para HTML seguro: escapa tudo e só permite **negrito** e quebras de linha */
  html: function (s) {
    return String(s || '').replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; })
      .replace(/^[ \t]*[*-][ \t]+/gm, '• ').replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>').replace(/\*([^*\n]+)\*/g, '<i>$1</i>').replace(/\n{2,}/g, '</p><p>').replace(/\n/g, '<br>');
  },
  erroTexto: function (e) {
    var m = String(e && e.message || e);
    if (/sem_chave/.test(m)) return 'A IA ainda não foi configurada no servidor.';
    if (/orcamento/.test(m)) return 'O limite de uso da IA deste mês foi atingido. Os exercícios, o áudio e a revisão continuam funcionando.';
    if (/^auth_/.test(m)) return 'Entre novamente com sua conta Google para usar a IA.';
    if (/quota|limite/.test(m)) return 'O limite de uso foi atingido por agora. Tente mais tarde.';
    if (/tempo|AbortError/i.test(m)) return 'A resposta demorou mais que o esperado. Tente novamente em instantes.';
    if (/indisponivel/.test(m)) return 'O serviço de IA está indisponível agora. Seu trabalho continua guardado.';
    if (/abort|Failed to fetch|NetworkError/i.test(m)) return 'Sem conexão com a IA agora. Confira a internet e tente de novo.';
    return 'Não consegui falar com a IA agora. Tente de novo.';
  }
};
var COURSE={"en":{"name":"Inglês","tts":"en-US","units":[{"title":"Hello!","goal":"Cumprimentar, dizer seu nome e de onde você é, e fazer as mesmas perguntas a outra pessoa.","speakers":{"Sarah":"f","Lucas":"m"},"setting":"Primeiro dia de um curso. Sarah, do Canadá, conhece Lucas, do Brasil.","lines":[["Sarah","Hi! I'm Sarah.","Oi! Eu sou a Sarah."],["Lucas","Hello, Sarah. My name's Lucas.","Olá, Sarah. Meu nome é Lucas."],["Sarah","Nice to meet you, Lucas.","Prazer em te conhecer, Lucas."],["Lucas","Nice to meet you, too.","Prazer em te conhecer também."],["Sarah","Where are you from?","De onde você é?"],["Lucas","I'm from Brazil. And you?","Eu sou do Brasil. E você?"],["Sarah","I'm from Canada.","Eu sou do Canadá."],["Lucas","Oh, cool!","Ah, que legal!"],["Sarah","See you later, Lucas!","Até mais, Lucas!"],["Lucas","Bye, Sarah!","Tchau, Sarah!"]],"grammar":[{"h":"I'm = I am: o verbo to be","p":["<i>To be</i> quer dizer ser e estar ao mesmo tempo. Nesta unidade você usa só duas formas: <b>I am</b> (eu sou, eu estou) e <b>you are</b> (você é, você está).","Na conversa quase sempre se usa a forma curta: <b>I'm</b> e <b>you're</b>."],"ex":[["I'm Sarah.","Eu sou a Sarah."],["I'm from Brazil.","Eu sou do Brasil."],["You're from Canada.","Você é do Canadá."]],"tip":"Em português dá para dizer só “Sou do Brasil”. Em inglês o sujeito é obrigatório: diga <b>I'm from Brazil</b>, nunca “Am from Brazil”."},{"h":"My name's… = My name is…","p":["<b>My name's</b> é a forma curta de <b>My name is</b>. As duas estão certas, e a curta soa mais natural. <b>I'm Lucas</b> e <b>My name's Lucas</b> dizem a mesma coisa."],"ex":[["My name's Lucas.","Meu nome é Lucas."],["What's your name?","Qual é o seu nome?"]]},{"h":"Where are you from? A preposição vai para o fim","p":["Em português a preposição vem antes: <i>De</i> onde você é? Em inglês, <b>from</b> fica no final da pergunta. Na resposta, <b>from</b> volta para antes do país."],"ex":[["Where are you from?","De onde você é?"],["I'm from Brazil.","Eu sou do Brasil."]],"tip":"Evite “From where are you?”. A frase é entendida, mas soa estranha para um nativo."},{"h":"And you? Devolvendo a pergunta","p":["Para fazer a mesma pergunta de volta, basta <b>And you?</b>. Para responder a <b>Nice to meet you</b>, acrescente <b>too</b> no fim."],"ex":[["I'm from Brazil. And you?","Eu sou do Brasil. E você?"],["Nice to meet you, too.","Prazer em te conhecer também."]]}],"vocab":[{"h":"Cumprimentos","items":[["Hi","oi (informal)"],["Hello","olá"],["Nice to meet you","prazer em te conhecer"],["See you later","até mais"],["Bye","tchau"],["Goodbye","tchau, adeus (mais formal)"]]},{"h":"Países","items":[["Brazil","Brasil"],["Canada","Canadá"],["the United States","os Estados Unidos (com the)"],["England","Inglaterra"],["Portugal","Portugal"],["France","França"],["Mexico","México"],["Japan","Japão"]]}],"numbers":["zero","one","two","three","four","five","six","seven","eight","nine","ten"],"pron":[{"h":"Sem vogal extra no fim","p":"Quem fala português costuma pôr um “i” no fim das palavras: “naici”, “fáivi”. Em inglês a palavra termina na consoante: <b>nice</b> acaba em s, <b>five</b> acaba em v.","w":["nice","five","name's"]},{"h":"Brazil tem a força no fim","p":"Diz-se algo como “br-ZIL”: o primeiro a quase some e a força cai em ZIL, com som de z. Já <b>Canada</b> tem a força no começo: CA-na-da.","w":["Brazil","Canada","Japan"]},{"h":"O th de three","p":"Ponha a ponta da língua entre os dentes e sopre o ar. Não é “tri” nem “fri”.","w":["three","thank you"]},{"h":"I'm soa “aim”","p":"A letra <b>I</b> sozinha soa como “ai”. O mesmo som aparece em <b>Hi</b>, <b>five</b> e <b>nine</b>.","w":["I'm","Hi","nine"]}],"mc":[{"q":"De onde a Sarah é?","o":["Brazil","Canada","England"],"a":1,"e":"Ela diz: I'm from Canada."},{"q":"Alguém diz “Nice to meet you.” O que você responde?","o":["Nice to meet you, too.","I'm from Brazil.","See you later."],"a":0,"e":"Acrescente too para devolver o “prazer”."},{"q":"Qual frase está certa?","o":["Am from Brazil.","I from Brazil.","I'm from Brazil."],"a":2,"e":"O sujeito I e o verbo am são obrigatórios: I'm."},{"q":"Como perguntar a origem de alguém?","o":["From where are you?","Where you are from?","Where are you from?"],"a":2,"e":"A pergunta começa com Where, o verbo are vem antes de you, e from fica no fim."}],"gaps":[{"s":"___ Lucas.","a":["I'm","I am"],"h":"Eu sou o Lucas."},{"s":"Where ___ you from?","a":["are"],"h":"De onde você é?"},{"s":"I'm ___ Brazil.","a":["from"],"h":"Eu sou do Brasil."},{"s":"Nice to ___ you.","a":["meet"],"h":"Prazer em te conhecer."},{"s":"My ___ Sarah.","a":["name's","name is"],"h":"Meu nome é Sarah."}],"order":[{"t":["Where","are","you","from?"],"h":"De onde você é?"},{"t":["My","name's","Lucas."],"h":"Meu nome é Lucas."},{"t":["Nice","to","meet","you,","too."],"h":"Prazer em te conhecer também."}],"dict":[{"t":"I'm from Brazil."},{"t":"Where are you from?"},{"t":"Nice to meet you."},{"t":"three"},{"t":"seven"}],"shadow":["Hi! I'm Sarah.","Nice to meet you, too.","Where are you from?","I'm from Brazil. And you?"],"write":{"task":"Apresente-se em inglês em 2 ou 3 frases: cumprimente, diga seu nome e de onde você é. Se quiser, termine com uma pergunta.","ph":"Hi! I'm …"},"cards":[["Meu nome é Lucas.","My name's Lucas."],["Qual é o seu nome?","What's your name?"],["De onde você é?","Where are you from?"],["Eu sou do Brasil.","I'm from Brazil."],["Eu sou dos Estados Unidos.","I'm from the United States."],["Prazer em te conhecer.","Nice to meet you."],["Prazer em te conhecer também.","Nice to meet you, too."],["E você?","And you?"],["Até mais!","See you later!"]]},{"title":"Countries and nationalities","goal":"Dizer a nacionalidade de alguém e falar de outras pessoas: ele, ela, nós e eles.","speakers":{"Sarah":"f","Lucas":"m"},"setting":"Depois da aula, Lucas mostra para a Sarah quem são os colegas da turma.","lines":[["Sarah","Who's that?","Quem é aquela?"],["Lucas","That's Ana. She's Brazilian, too.","Aquela é a Ana. Ela também é brasileira."],["Sarah","And who are they?","E quem são eles?"],["Lucas","They're Kenji and Yuki. They're Japanese.","São o Kenji e a Yuki. Eles são japoneses."],["Sarah","Are they students here?","Eles são alunos aqui?"],["Lucas","Yes, they are. We're all in the same class.","São, sim. Estamos todos na mesma turma."],["Sarah","And who's he?","E quem é ele?"],["Lucas","He's Tom, the teacher. He's from London.","É o Tom, o professor. Ele é de Londres."],["Sarah","Oh, he's British!","Ah, ele é britânico!"],["Lucas","Yes, and he's very nice.","É, e ele é muito legal."]],"grammar":[{"h":"O verbo to be completo","p":["Na Unidade 1 você viu <b>I am</b> e <b>you are</b>. Agora vêm as outras pessoas: <b>he is</b> (ele), <b>she is</b> (ela), <b>it is</b> (coisa ou animal), <b>we are</b> (nós), <b>they are</b> (eles, elas).","Na fala, use a forma curta: <b>he's</b>, <b>she's</b>, <b>it's</b>, <b>we're</b>, <b>they're</b>."],"ex":[["She's Brazilian.","Ela é brasileira."],["We're students.","Nós somos alunos."],["They're from Japan.","Eles são do Japão."]],"tip":"<b>They</b> serve para homens, mulheres ou grupos mistos. Não existe diferença entre “eles” e “elas”."},{"h":"Nacionalidade com letra maiúscula","p":["Em inglês, nacionalidades e idiomas sempre começam com maiúscula: <b>Brazilian</b>, <b>Japanese</b>, <b>English</b>. Em português é o contrário."],"ex":[["He's British.","Ele é britânico."],["I speak Portuguese.","Eu falo português."]]},{"h":"País ou nacionalidade?","p":["Para o país, use <b>from</b>: <b>I'm from Brazil</b>. Para a nacionalidade, use direto: <b>I'm Brazilian</b>. As duas dizem a mesma coisa.","A nacionalidade não muda com gênero nem número: <b>She's Japanese</b>, <b>They're Japanese</b>."],"ex":[["I'm from Mexico.","Eu sou do México."],["I'm Mexican.","Eu sou mexicano."]],"tip":"Nunca diga “Japaneses” ou “Brazilians” para descrever pessoas: <b>They're Brazilian</b>."},{"h":"Profissão pede a","p":["Antes de profissão no singular, o inglês usa <b>a</b>: <b>He's a teacher</b>. Em português não usamos artigo: “ele é professor”."],"ex":[["She's a student.","Ela é aluna."],["He's a teacher.","Ele é professor."]]}],"vocab":[{"h":"Nacionalidades","items":[["Brazilian","brasileiro"],["American","americano"],["Canadian","canadense"],["British","britânico"],["English","inglês (da Inglaterra)"],["French","francês"],["Portuguese","português"],["Japanese","japonês"],["Mexican","mexicano"],["Spanish","espanhol"]]},{"h":"Pessoas","items":[["friend","amigo, amiga"],["student","aluno, estudante"],["teacher","professor"],["classmate","colega de turma"],["class","turma, aula"]]}],"pron":[{"h":"-ese tem a força no fim","p":"Nacionalidades terminadas em <b>-ese</b> têm a força na última sílaba: ja-pa-NESE, por-tu-GUESE.","w":["Japanese","Portuguese","Chinese"]},{"h":"O th que vibra","p":"Em <b>they</b>, <b>that</b> e <b>the</b>, ponha a língua entre os dentes como em <b>three</b>, mas deixe a garganta vibrar, como num “d” suave.","w":["they","that","the"]},{"h":"he's e she's terminam em z","p":"O <b>'s</b> de <b>he's</b> e <b>she's</b> soa como “z”: “hiz”, “xiz”.","w":["he's","she's","Who's that?"]}],"mc":[{"q":"De onde o Tom é?","o":["Brazil","London","Japan"],"a":1,"e":"Lucas diz: He's from London."},{"q":"Qual é a nacionalidade da Ana?","o":["Japanese","British","Brazilian"],"a":2,"e":"She's Brazilian, too."},{"q":"Qual frase está certa?","o":["They're Japaneses.","They're Japanese.","They're japanese."],"a":1,"e":"A nacionalidade não vai para o plural e começa com maiúscula."},{"q":"Qual pronome usar para “Kenji e Yuki”?","o":["he","she","they"],"a":2,"e":"They serve para qualquer grupo."}],"gaps":[{"s":"She ___ Brazilian.","a":["is","'s"],"h":"Ela é brasileira."},{"s":"They ___ from Japan.","a":["are","'re"],"h":"Eles são do Japão."},{"s":"We ___ students.","a":["are","'re"],"h":"Nós somos alunos."},{"s":"He's ___ London.","a":["from"],"h":"Ele é de Londres."},{"s":"I'm from Mexico. I'm ___.","a":["Mexican"],"h":"Sou do México. Sou mexicano."}],"order":[{"t":["She's","from","Brazil."],"h":"Ela é do Brasil."},{"t":["We're","in","the","same","class."],"h":"Estamos na mesma turma."},{"t":["He's","a","teacher."],"h":"Ele é professor."}],"dict":[{"t":"She's Brazilian."},{"t":"They're from Japan."},{"t":"We're students."},{"t":"He's British."}],"shadow":["Who's that?","That's Ana. She's Brazilian, too.","They're Kenji and Yuki. They're Japanese.","He's Tom, the teacher. He's from London."],"write":{"task":"Escreva 3 frases sobre pessoas que você conhece: o nome, de onde são e a nacionalidade.","ph":"Carla is from Brazil. She's Brazilian …"},"cards":[["Ela é brasileira.","She's Brazilian."],["Eles são japoneses.","They're Japanese."],["Nós somos alunos.","We're students."],["Ele é de Londres.","He's from London."],["Quem é ele?","Who's he?"],["Quem são eles?","Who are they?"],["Ela é professora.","She's a teacher."],["Estamos na mesma turma.","We're in the same class."]]},{"title":"Questions and answers","goal":"Fazer e responder perguntas sobre dados pessoais, dizer a idade e negar informações.","speakers":{"Emma":"f","Lucas":"m"},"setting":"Lucas faz a matrícula numa academia. Emma, a recepcionista, preenche a ficha dele.","lines":[["Emma","Hi! Are you a new member?","Oi! Você é aluno novo?"],["Lucas","Yes, I am.","Sou, sim."],["Emma","What's your name?","Qual é o seu nome?"],["Lucas","Lucas Silva.","Lucas Silva."],["Emma","How old are you, Lucas?","Quantos anos você tem, Lucas?"],["Lucas","I'm twenty-five.","Tenho vinte e cinco."],["Emma","Are you American?","Você é americano?"],["Lucas","No, I'm not. I'm Brazilian.","Não. Sou brasileiro."],["Emma","What's your phone number?","Qual é o seu telefone?"],["Lucas","It's five five five, oh one nine three.","É cinco cinco cinco, zero um nove três."],["Emma","Great. You're all set!","Ótimo. Está tudo certo!"]],"grammar":[{"h":"Pergunta: o verbo vai para a frente","p":["Para perguntar com <b>to be</b>, troque a ordem: <b>You are</b> vira <b>Are you…?</b> e <b>She is</b> vira <b>Is she…?</b>"],"ex":[["Are you American?","Você é americano?"],["Is she a teacher?","Ela é professora?"],["Are they from Canada?","Eles são do Canadá?"]]},{"h":"Negativa: not depois do verbo","p":["Coloque <b>not</b> depois do verbo: <b>I'm not</b>, <b>you aren't</b>, <b>he isn't</b>, <b>we aren't</b>, <b>they aren't</b>."],"ex":[["I'm not American.","Não sou americano."],["She isn't a student.","Ela não é aluna."]],"tip":"Com <b>to be</b> não se usa <b>don't</b>. “I don't American” está errado: o certo é <b>I'm not American</b>."},{"h":"Respostas curtas","p":["Responda com <b>Yes</b> ou <b>No</b> + pronome + verbo: <b>Yes, I am.</b> <b>No, I'm not.</b> <b>Yes, she is.</b> <b>No, they aren't.</b>"],"ex":[["Are you Brazilian? — Yes, I am.","Você é brasileiro? — Sou."],["Is he a teacher? — No, he isn't.","Ele é professor? — Não."]],"tip":"Na resposta curta positiva não se contrai: diga <b>Yes, I am</b>, nunca “Yes, I'm”."},{"h":"Idade com to be","p":["Em inglês você <b>é</b> uma idade, não <b>tem</b>: <b>I'm 25</b> ou <b>I'm 25 years old</b>. Para perguntar: <b>How old are you?</b>"],"ex":[["I'm twenty-five.","Tenho vinte e cinco anos."],["How old is she?","Quantos anos ela tem?"]],"tip":"“I have 25 years” é o erro mais comum de brasileiros."}],"vocab":[{"h":"Perguntas pessoais","items":[["What's your name?","Qual é o seu nome?"],["How old are you?","Quantos anos você tem?"],["Where are you from?","De onde você é?"],["What's your phone number?","Qual é o seu telefone?"],["What's your email?","Qual é o seu e-mail?"]]},{"h":"Palavras úteis","items":[["member","sócio, membro"],["new","novo"],["years old","anos de idade"],["oh","zero (falando números)"]]}],"numbers":[["11","eleven"],["12","twelve"],["13","thirteen"],["14","fourteen"],["15","fifteen"],["20","twenty"],["21","twenty-one"],["30","thirty"],["40","forty"],["50","fifty"],["100","a hundred"]],"pron":[{"h":"thirteen ou thirty?","p":"Nos números de 13 a 19 a força cai no fim: thir-TEEN. Nas dezenas, cai no começo: THIR-ty. É assim que se diferenciam.","w":["thirteen","thirty","fifteen","fifty"]},{"h":"O zero vira “oh”","p":"Em telefones e números de quarto, o zero costuma ser dito como a letra O: “oh”.","w":["five five five, oh one nine three"]},{"h":"A pergunta sobe","p":"Em perguntas de sim ou não, a voz sobe no final.","w":["Are you American?","Is she a teacher?"]}],"mc":[{"q":"Quantos anos o Lucas tem?","o":["23","25","52"],"a":1,"e":"I'm twenty-five."},{"q":"Como dizer “Tenho 30 anos”?","o":["I have 30 years.","I'm 30.","I'm have 30."],"a":1,"e":"Em inglês a idade vem com to be."},{"q":"Qual negativa está certa?","o":["I don't American.","I'm not American.","I amn't American."],"a":1,"e":"Com to be, use not depois do verbo."},{"q":"“Are you Brazilian?” Qual resposta está certa?","o":["Yes, I'm.","Yes, I am.","Yes, I are."],"a":1,"e":"Na resposta curta positiva não se contrai."}],"gaps":[{"s":"___ you a new member?","a":["Are"],"h":"Você é aluno novo?"},{"s":"I'm ___ American.","a":["not"],"h":"Não sou americano."},{"s":"How ___ are you?","a":["old"],"h":"Quantos anos você tem?"},{"s":"She ___ British. She's Canadian.","a":["isn't","is not","'s not"],"h":"Ela não é britânica. É canadense."},{"s":"Are you Brazilian? — Yes, I ___.","a":["am"],"h":"Você é brasileiro? — Sou."}],"order":[{"t":["How","old","are","you?"],"h":"Quantos anos você tem?"},{"t":["Is","she","from","Canada?"],"h":"Ela é do Canadá?"},{"t":["I'm","not","a","teacher."],"h":"Não sou professor."}],"dict":[{"t":"How old are you?"},{"t":"I'm not American."},{"t":"thirteen"},{"t":"thirty"},{"t":"Is he Brazilian?"}],"shadow":["Are you a new member?","How old are you?","No, I'm not. I'm Brazilian.","What's your phone number?"],"write":{"task":"Responda em inglês: What's your name? How old are you? Where are you from? Are you a student?","ph":"My name's … I'm …"},"cards":[["Quantos anos você tem?","How old are you?"],["Tenho 25 anos.","I'm twenty-five."],["Não sou americano.","I'm not American."],["Você é brasileiro?","Are you Brazilian?"],["Sou, sim.","Yes, I am."],["Não, não sou.","No, I'm not."],["Ela não é professora.","She isn't a teacher."],["Qual é o seu telefone?","What's your phone number?"]]},{"title":"My family","goal":"Apresentar pessoas da família e dizer de quem é cada coisa.","speakers":{"Sarah":"f","Lucas":"m"},"setting":"Sarah mostra fotos da família no celular.","lines":[["Lucas","Is this your family?","Esta é a sua família?"],["Sarah","Yes! This is my mom, and this is my dad.","É! Esta é minha mãe, e este é meu pai."],["Lucas","What's your mom's name?","Qual é o nome da sua mãe?"],["Sarah","Her name's Linda. She's a nurse.","O nome dela é Linda. Ela é enfermeira."],["Lucas","And who's this?","E quem é este?"],["Sarah","That's my brother, Jake. His wife is Mexican.","Esse é meu irmão, Jake. A esposa dele é mexicana."],["Lucas","And the two kids?","E as duas crianças?"],["Sarah","They're Jake's kids. Their names are Mia and Leo.","São os filhos do Jake. Os nomes deles são Mia e Leo."],["Lucas","Your family is beautiful!","Sua família é linda!"],["Sarah","Thanks!","Obrigada!"]],"grammar":[{"h":"Possessivos","p":["<b>my</b> (meu, minha), <b>your</b> (seu, sua), <b>his</b> (dele), <b>her</b> (dela), <b>our</b> (nosso), <b>their</b> (deles, delas). Eles não mudam com gênero nem número: <b>my brother</b>, <b>my sisters</b>."],"ex":[["My mom is a nurse.","Minha mãe é enfermeira."],["Our parents are from Brazil.","Nossos pais são do Brasil."]],"tip":"<b>His</b> e <b>her</b> dependem de quem é o <b>dono</b>, não da coisa. “A esposa dele” é <b>his wife</b>; “o marido dela” é <b>her husband</b>."},{"h":"O 's de posse","p":["Para dizer “de alguém”, acrescente <b>'s</b> ao dono e inverta a ordem: “os filhos do Jake” vira <b>Jake's kids</b>."],"ex":[["Jake's kids","os filhos do Jake"],["my mom's name","o nome da minha mãe"]],"tip":"Evite “the kids of Jake”. Com pessoas, o natural é <b>Jake's kids</b>."},{"h":"This is… para apresentar","p":["Para apresentar alguém ou mostrar numa foto, use <b>This is…</b> (para quem está perto) e <b>That's…</b> (para quem está mais longe)."],"ex":[["This is my dad.","Este é meu pai."],["That's my brother.","Aquele é meu irmão."]]}],"vocab":[{"h":"Família","items":[["mom","mãe"],["dad","pai"],["parents","pais"],["brother","irmão"],["sister","irmã"],["husband","marido"],["wife","esposa"],["son","filho"],["daughter","filha"],["kids","filhos, crianças"],["grandmother","avó"],["grandfather","avô"]]},{"h":"Profissões da unidade","items":[["nurse","enfermeiro, enfermeira"],["doctor","médico, médica"]]}],"pron":[{"h":"O o que soa “â”","p":"Em <b>mother</b>, <b>brother</b>, <b>son</b> e <b>mom</b> (americano), a vogal soa parecida com o “â” de “câmara”, não com o “o” de “bola”.","w":["brother","mother","son"]},{"h":"daughter sem g","p":"O <b>gh</b> de <b>daughter</b> não é pronunciado: algo como “DÓ-ter”.","w":["daughter"]},{"h":"O 's soa s ou z","p":"Depois de som surdo, como em <b>Jake's</b>, soa “s”. Depois de som sonoro, como em <b>mom's</b>, soa “z”.","w":["Jake's","mom's"]}],"mc":[{"q":"Quem é a Linda?","o":["A mãe da Sarah","A irmã da Sarah","A esposa do Jake"],"a":0,"e":"Her name's Linda. She's a nurse."},{"q":"Como dizer “a esposa dele”?","o":["his wife","her wife"],"a":0,"e":"O dono é homem, então his."},{"q":"Como dizer “os filhos do Jake”?","o":["the kids of Jake","Jake's kids","Jake kids"],"a":1,"e":"Com pessoas, use 's."},{"q":"Qual é a profissão da mãe da Sarah?","o":["teacher","doctor","nurse"],"a":2,"e":"She's a nurse."}],"gaps":[{"s":"This is ___ sister.","a":["my"],"h":"Esta é minha irmã."},{"s":"___ name's Linda.","a":["Her"],"h":"O nome dela é Linda."},{"s":"___ wife is Mexican.","a":["His"],"h":"A esposa dele é mexicana."},{"s":"This is ___ car.","a":["Jake's"],"h":"Este é o carro do Jake."},{"s":"___ parents are from Canada.","a":["Our"],"h":"Nossos pais são do Canadá."}],"order":[{"t":["This","is","my","brother."],"h":"Este é meu irmão."},{"t":["Her","name's","Linda."],"h":"O nome dela é Linda."},{"t":["Their","names","are","Mia","and","Leo."],"h":"Os nomes deles são Mia e Leo."}],"dict":[{"t":"This is my dad."},{"t":"His wife is Mexican."},{"t":"Jake's kids"},{"t":"daughter"}],"shadow":["Is this your family?","This is my mom, and this is my dad.","Her name's Linda. She's a nurse.","They're Jake's kids."],"write":{"task":"Apresente 3 pessoas da sua família: quem são, o nome e a profissão ou de onde são.","ph":"This is my … Her name's …"},"cards":[["Esta é minha mãe.","This is my mom."],["O nome dele é Jake.","His name's Jake."],["A esposa dele é mexicana.","His wife is Mexican."],["O marido dela é médico.","Her husband is a doctor."],["Os filhos do Jake.","Jake's kids."],["Qual é o nome do seu pai?","What's your dad's name?"],["Nossos pais são do Brasil.","Our parents are from Brazil."],["Esta é a sua família?","Is this your family?"]]},{"title":"Things around me","goal":"Nomear objetos, perguntar o que é algo e quanto custa.","speakers":{"Sarah":"f","Seller":"m"},"setting":"Sarah está numa feira de rua em Londres e conversa com um vendedor.","lines":[["Sarah","Excuse me, what's this?","Com licença, o que é isto?"],["Seller","It's an umbrella. It's ten pounds.","É um guarda-chuva. Custa dez libras."],["Sarah","And what are those?","E o que são aquelas?"],["Seller","Those are bags. They're from Italy.","Aquelas são bolsas. São da Itália."],["Sarah","How much are these watches?","Quanto custam estes relógios?"],["Seller","They're twenty pounds each.","Custam vinte libras cada."],["Sarah","Is that a map of London?","Aquilo é um mapa de Londres?"],["Seller","Yes, it is. It's free!","É, sim. É de graça!"],["Sarah","Great! A map and an umbrella, please.","Ótimo! Um mapa e um guarda-chuva, por favor."]],"grammar":[{"h":"a ou an","p":["Use <b>a</b> antes de som de consoante e <b>an</b> antes de som de vogal: <b>a map</b>, <b>a bag</b>, <b>an umbrella</b>, <b>an apple</b>."],"ex":[["a watch","um relógio"],["an umbrella","um guarda-chuva"]],"tip":"Vale o <b>som</b>, não a letra: <b>a university</b> (começa com som de “iu”), <b>an hour</b> (o h é mudo)."},{"h":"Plural","p":["Em geral, acrescente <b>-s</b>: bag → <b>bags</b>. Depois de -ch, -sh, -s e -x, acrescente <b>-es</b>: watch → <b>watches</b>, box → <b>boxes</b>.","Alguns são irregulares: man → <b>men</b>, woman → <b>women</b>, child → <b>children</b>, person → <b>people</b>."],"ex":[["two bags","duas bolsas"],["three watches","três relógios"],["five people","cinco pessoas"]],"tip":"O adjetivo nunca vai para o plural: <b>big bags</b>, não “bigs bags”."},{"h":"this, that, these, those","p":["<b>this</b> (isto, este) e <b>these</b> (estes) para o que está perto. <b>that</b> (aquilo, aquele) e <b>those</b> (aqueles) para o que está longe."],"ex":[["What's this?","O que é isto?"],["What are those?","O que são aqueles?"],["How much are these?","Quanto custam estes?"]]},{"h":"Perguntando o preço","p":["Para uma coisa: <b>How much is it?</b> Para várias: <b>How much are they?</b>"],"ex":[["How much is it? — It's ten pounds.","Quanto custa? — Dez libras."]]}],"vocab":[{"h":"Objetos","items":[["bag","bolsa, sacola"],["umbrella","guarda-chuva"],["watch","relógio de pulso"],["phone","celular, telefone"],["key","chave"],["wallet","carteira"],["book","livro"],["pen","caneta"],["map","mapa"],["ticket","ingresso, passagem"]]},{"h":"Comprando","items":[["Excuse me","com licença"],["How much is it?","quanto custa?"],["each","cada"],["free","grátis"],["expensive","caro"],["cheap","barato"]]}],"pron":[{"h":"this ou these?","p":"<b>this</b> tem um i curto e termina em “s”. <b>these</b> tem um i longo e termina em “z”: “dhis” e “dhiiz”.","w":["this","these"]},{"h":"O -es do plural","p":"Depois de -ch, -sh, -s e -x, o plural ganha uma sílaba: <b>watches</b> soa “uó-tchiz”.","w":["watches","boxes","buses"]},{"h":"an se liga à palavra","p":"O n de <b>an</b> se junta à vogal seguinte: “a-nãm-BRÉ-la”.","w":["an umbrella","an apple"]}],"mc":[{"q":"Quanto custa o guarda-chuva?","o":["£10","£20","É grátis"],"a":0,"e":"It's ten pounds."},{"q":"___ umbrella","o":["a","an"],"a":1,"e":"umbrella começa com som de vogal."},{"q":"Qual é o plural de watch?","o":["watchs","watches","watch"],"a":1,"e":"Depois de -ch, acrescente -es."},{"q":"Como dizer “aquelas bolsas”?","o":["these bags","those bags"],"a":1,"e":"those = aqueles, longe e no plural."}],"gaps":[{"s":"It's ___ umbrella.","a":["an"],"h":"É um guarda-chuva."},{"s":"___ is a map.","a":["This"],"h":"Isto é um mapa."},{"s":"Those are ___.","a":["bags"],"h":"Aquelas são bolsas."},{"s":"These ___ are expensive.","a":["watches"],"h":"Estes relógios são caros."},{"s":"There are five ___ here.","a":["people"],"h":"Tem cinco pessoas aqui."}],"order":[{"t":["What","are","those?"],"h":"O que são aqueles?"},{"t":["This","is","a","map","of","London."],"h":"Isto é um mapa de Londres."},{"t":["How","much","is","it?"],"h":"Quanto custa?"}],"dict":[{"t":"What's this?"},{"t":"It's an umbrella."},{"t":"these watches"},{"t":"How much is it?"},{"t":"people"}],"shadow":["Excuse me, what's this?","It's an umbrella. It's ten pounds.","How much are these watches?","A map and an umbrella, please."],"write":{"task":"Descreva 4 objetos que estão perto de você agora, usando this, that, these ou those e a ou an.","ph":"This is a phone. Those are …"},"cards":[["O que é isto?","What's this?"],["É um guarda-chuva.","It's an umbrella."],["O que são aqueles?","What are those?"],["Quanto custa?","How much is it?"],["Estes relógios são da Itália.","These watches are from Italy."],["Com licença.","Excuse me."],["Duas pessoas.","Two people."],["É de graça!","It's free!"]]},{"title":"My day","goal":"Contar a sua rotina, dizer as horas e perguntar sobre o dia de outra pessoa.","speakers":{"Sarah":"f","Lucas":"m"},"setting":"Antes da aula, Sarah repara que o Lucas está com sono.","lines":[["Sarah","You look tired!","Você parece cansado!"],["Lucas","I get up at six every day.","Eu acordo às seis todo dia."],["Sarah","Six? Why?","Às seis? Por quê?"],["Lucas","I work in the morning and I study in the afternoon.","Trabalho de manhã e estudo à tarde."],["Sarah","What time do you have lunch?","A que horas você almoça?"],["Lucas","At half past twelve. And you?","Ao meio-dia e meia. E você?"],["Sarah","I don't work. I study in the morning and I go to the gym at night.","Eu não trabalho. Estudo de manhã e vou à academia à noite."],["Lucas","Do you go to bed late?","Você vai dormir tarde?"],["Sarah","No, I don't. I go to bed at ten.","Não. Vou dormir às dez."]],"grammar":[{"h":"Present simple para a rotina","p":["Para hábitos e rotina, use o verbo na forma básica: <b>I work</b>, <b>you study</b>, <b>we go</b>, <b>they get up</b>. Com I, you, we e they o verbo não muda."],"ex":[["I work in the morning.","Trabalho de manhã."],["We study English.","Estudamos inglês."]]},{"h":"Negativa com don't","p":["Coloque <b>don't</b> (do not) antes do verbo: <b>I don't work</b>."],"ex":[["I don't work on Sundays.","Não trabalho aos domingos."],["They don't eat meat.","Eles não comem carne."]],"tip":"“I no work” e “I not work” estão errados. Sempre <b>I don't work</b>."},{"h":"Pergunta com do","p":["Comece a pergunta com <b>Do</b>: <b>Do you work?</b> Respostas curtas: <b>Yes, I do.</b> <b>No, I don't.</b> Com palavras de pergunta: <b>What time do you get up?</b>"],"ex":[["Do you go to the gym?","Você vai à academia?"],["What time do you have lunch?","A que horas você almoça?"]]},{"h":"Horas e partes do dia","p":["<b>at</b> + hora: <b>at six</b>, <b>at half past twelve</b>. <b>in the morning</b>, <b>in the afternoon</b>, <b>in the evening</b>, mas <b>at night</b>."],"ex":[["at seven o'clock","às sete em ponto"],["at a quarter past eight","às oito e quinze"],["at a quarter to nine","às quinze para as nove"]],"tip":"Para perguntar as horas: <b>What time is it?</b> — <b>It's seven o'clock.</b>"}],"vocab":[{"h":"Rotina","items":[["get up","levantar, acordar"],["have breakfast","tomar café da manhã"],["go to work","ir para o trabalho"],["have lunch","almoçar"],["study","estudar"],["go home","ir para casa"],["have dinner","jantar"],["go to bed","ir dormir"]]},{"h":"Horas","items":[["seven o'clock","sete em ponto"],["half past seven","sete e meia"],["a quarter past seven","sete e quinze"],["a quarter to eight","quinze para as oito"],["every day","todo dia"],["late","tarde"],["early","cedo"]]}],"pron":[{"h":"work ou walk?","p":"<b>work</b> soa algo como “uârk”. <b>walk</b> soa “uók”, com o l mudo.","w":["work","walk"]},{"h":"o'clock","p":"Diz-se “ô-KLÓK”, com a força no fim.","w":["seven o'clock"]},{"h":"Do you vira “d'you”","p":"Na fala rápida, <b>do you</b> fica bem curto: “d'iu”.","w":["Do you work?","What time do you get up?"]}],"mc":[{"q":"A que horas o Lucas acorda?","o":["6h","7h","10h"],"a":0,"e":"I get up at six every day."},{"q":"A Sarah trabalha?","o":["Sim","Não, ela só estuda"],"a":1,"e":"I don't work."},{"q":"Qual negativa está certa?","o":["I no work.","I don't work.","I not work."],"a":1,"e":"Use don't antes do verbo."},{"q":"Como dizer “à noite”?","o":["in the night","at night"],"a":1,"e":"Diz-se at night."}],"gaps":[{"s":"I get ___ at six.","a":["up"],"h":"Eu acordo às seis."},{"s":"___ you work on Saturdays?","a":["Do"],"h":"Você trabalha aos sábados?"},{"s":"I ___ study at night.","a":["don't","do not"],"h":"Eu não estudo à noite."},{"s":"I have lunch ___ half past twelve.","a":["at"],"h":"Almoço ao meio-dia e meia."},{"s":"I study ___ the morning.","a":["in"],"h":"Estudo de manhã."}],"order":[{"t":["What","time","do","you","get","up?"],"h":"A que horas você acorda?"},{"t":["I","don't","work","on","Sundays."],"h":"Não trabalho aos domingos."},{"t":["We","go","to","bed","at","eleven."],"h":"Vamos dormir às onze."}],"dict":[{"t":"I get up at six."},{"t":"Do you work?"},{"t":"No, I don't."},{"t":"half past twelve"},{"t":"at night"}],"shadow":["I get up at six every day.","I work in the morning and I study in the afternoon.","What time do you have lunch?","I go to bed at ten."],"write":{"task":"Descreva sua rotina em 4 ou 5 frases: a que horas acorda, trabalha ou estuda, almoça e vai dormir.","ph":"I get up at …"},"cards":[["Eu acordo às seis.","I get up at six."],["Você trabalha?","Do you work?"],["Não, não trabalho.","No, I don't."],["Eu estudo à noite.","I study at night."],["A que horas você almoça?","What time do you have lunch?"],["Vou dormir às onze.","I go to bed at eleven."],["Ao meio-dia e meia.","At half past twelve."],["Que horas são?","What time is it?"]]},{"title":"Jobs","goal":"Falar da profissão e do trabalho de outras pessoas.","speakers":{"Sarah":"f","Lucas":"m"},"setting":"Sarah e Lucas conversam sobre os irmãos.","lines":[["Sarah","What does your sister do?","O que a sua irmã faz?"],["Lucas","She's a nurse. She works in a hospital.","Ela é enfermeira. Trabalha num hospital."],["Sarah","Does she work at night?","Ela trabalha à noite?"],["Lucas","Yes, she does. She starts at seven p.m.","Trabalha, sim. Começa às sete da noite."],["Sarah","Wow. My brother is a chef.","Nossa. Meu irmão é chef de cozinha."],["Lucas","Does he like his job?","Ele gosta do trabalho?"],["Sarah","Yes, he loves it! But he doesn't have much free time.","Gosta, ele adora! Mas não tem muito tempo livre."],["Lucas","Where does he work?","Onde ele trabalha?"],["Sarah","In a restaurant in Toronto.","Num restaurante em Toronto."]],"grammar":[{"h":"he, she, it: o verbo ganha -s","p":["No present simple, com <b>he</b>, <b>she</b> e <b>it</b> o verbo ganha <b>-s</b>: she <b>works</b>, he <b>likes</b>.","Alguns ganham <b>-es</b>: go → <b>goes</b>, watch → <b>watches</b>. Consoante + y vira <b>-ies</b>: study → <b>studies</b>. E have vira <b>has</b>."],"ex":[["She works in a hospital.","Ela trabalha num hospital."],["He goes to work by bus.","Ele vai ao trabalho de ônibus."],["My sister has two kids.","Minha irmã tem dois filhos."]],"tip":"Esquecer o -s é o erro mais comum do nível A1: “She work” está errado."},{"h":"Negativa com doesn't","p":["Com he, she e it, use <b>doesn't</b> e o verbo volta para a forma básica, sem -s."],"ex":[["He doesn't have free time.","Ele não tem tempo livre."],["She doesn't work on Sundays.","Ela não trabalha aos domingos."]],"tip":"“He doesn't works” está errado: o -s já está no <b>doesn't</b>."},{"h":"Pergunta com does","p":["<b>Does she work at night?</b> — <b>Yes, she does.</b> / <b>No, she doesn't.</b> Para perguntar a profissão: <b>What does he do?</b>"],"ex":[["What does your sister do?","O que a sua irmã faz?"],["Where does he work?","Onde ele trabalha?"]]},{"h":"a ou an antes da profissão","p":["Lembre-se: <b>She's a nurse</b>, <b>He's an engineer</b>. Use <b>an</b> quando a profissão começa com som de vogal."],"ex":[["He's an engineer.","Ele é engenheiro."],["She's a lawyer.","Ela é advogada."]]}],"vocab":[{"h":"Profissões","items":[["doctor","médico"],["nurse","enfermeiro"],["teacher","professor"],["engineer","engenheiro"],["lawyer","advogado"],["chef","chef de cozinha"],["salesperson","vendedor"],["developer","desenvolvedor"],["receptionist","recepcionista"]]},{"h":"Lugares de trabalho","items":[["hospital","hospital"],["school","escola"],["office","escritório"],["restaurant","restaurante"],["store","loja"],["at home","em casa"]]}],"pron":[{"h":"Três sons para o -s","p":"Depois de som surdo, soa “s”: <b>works</b>. Depois de som sonoro, “z”: <b>plays</b>. Depois de -ch, -sh, -s, ganha sílaba: <b>watches</b>.","w":["works","plays","watches"]},{"h":"does soa “dâz”","p":"O o de <b>does</b> soa como “â”: “dâz”. E <b>doesn't</b> é “DÂ-zent”.","w":["does","doesn't"]},{"h":"chef começa com “x”","p":"Em <b>chef</b>, o ch soa “x”, como em francês: “xéf”.","w":["chef"]}],"mc":[{"q":"Onde a irmã do Lucas trabalha?","o":["Num hospital","Num restaurante","Numa escola"],"a":0,"e":"She works in a hospital."},{"q":"Qual é a profissão do irmão da Sarah?","o":["nurse","chef","teacher"],"a":1,"e":"My brother is a chef."},{"q":"Qual frase está certa?","o":["She work in a hospital.","She works in a hospital.","She working in a hospital."],"a":1,"e":"Com she, o verbo ganha -s."},{"q":"Como dizer “Ele não tem tempo”?","o":["He doesn't has time.","He doesn't have time.","He don't have time."],"a":1,"e":"Depois de doesn't, o verbo fica sem -s."}],"gaps":[{"s":"She ___ in a hospital.","a":["works"],"h":"Ela trabalha num hospital."},{"s":"___ he like his job?","a":["Does"],"h":"Ele gosta do trabalho?"},{"s":"He ___ work on Sundays.","a":["doesn't","does not"],"h":"Ele não trabalha aos domingos."},{"s":"What ___ she do?","a":["does"],"h":"O que ela faz?"},{"s":"My brother ___ two kids.","a":["has"],"h":"Meu irmão tem dois filhos."}],"order":[{"t":["What","does","your","sister","do?"],"h":"O que a sua irmã faz?"},{"t":["He","doesn't","work","at","night."],"h":"Ele não trabalha à noite."},{"t":["She","is","an","engineer."],"h":"Ela é engenheira."}],"dict":[{"t":"She works in a hospital."},{"t":"Does he like his job?"},{"t":"He doesn't have much free time."},{"t":"an engineer"}],"shadow":["What does your sister do?","She's a nurse. She works in a hospital.","Does he like his job?","In a restaurant in Toronto."],"write":{"task":"Escreva sobre 2 pessoas da sua família: a profissão, onde trabalham e o que fazem no dia a dia.","ph":"My sister is a … She works …"},"cards":[["O que ela faz?","What does she do?"],["Ela é enfermeira.","She's a nurse."],["Ele trabalha num escritório.","He works in an office."],["Ela trabalha à noite?","Does she work at night?"],["Ele não gosta do trabalho.","He doesn't like his job."],["Minha irmã tem dois filhos.","My sister has two kids."],["Ele é engenheiro.","He's an engineer."],["Ela estuda inglês.","She studies English."]]},{"title":"Free time","goal":"Dizer do que você gosta e com que frequência faz cada coisa.","speakers":{"Sarah":"f","Lucas":"m"},"setting":"Sarah e Lucas conversam sobre o que fazem no tempo livre.","lines":[["Lucas","What do you do in your free time?","O que você faz no tempo livre?"],["Sarah","I love reading. I always read before bed.","Adoro ler. Sempre leio antes de dormir."],["Lucas","Cool. Do you like sports?","Legal. Você gosta de esportes?"],["Sarah","I like swimming, but I hate running!","Gosto de nadar, mas odeio correr!"],["Lucas","Me too! I never run.","Eu também! Nunca corro."],["Sarah","And you? What do you like doing?","E você? Do que você gosta de fazer?"],["Lucas","I usually play video games on weekends.","Normalmente jogo videogame nos fins de semana."],["Sarah","How often do you go to the movies?","Com que frequência você vai ao cinema?"],["Lucas","Sometimes. Maybe once a month.","Às vezes. Talvez uma vez por mês."]],"grammar":[{"h":"like, love, hate + -ing","p":["Depois de <b>like</b>, <b>love</b> e <b>hate</b>, o verbo costuma vir com <b>-ing</b>: <b>I like swimming</b>, <b>I hate running</b>."],"ex":[["I love reading.","Adoro ler."],["Do you like cooking?","Você gosta de cozinhar?"]],"tip":"Não existe o “de” do português: “I like of swimming” está errado."},{"h":"Palavras de frequência","p":["<b>always</b> (sempre), <b>usually</b> (normalmente), <b>often</b> (frequentemente), <b>sometimes</b> (às vezes), <b>never</b> (nunca).","Elas vêm <b>antes</b> do verbo principal, mas <b>depois</b> do to be."],"ex":[["I always read before bed.","Sempre leio antes de dormir."],["She's never late.","Ela nunca se atrasa."]],"tip":"“I read always” está errado. O certo é <b>I always read</b>."},{"h":"How often…?","p":["Para perguntar a frequência: <b>How often do you…?</b> Respostas: <b>every day</b>, <b>once a week</b> (uma vez por semana), <b>twice a month</b> (duas vezes por mês), <b>three times a year</b>."],"ex":[["How often do you go to the gym?","Com que frequência você vai à academia?"],["Twice a week.","Duas vezes por semana."]]},{"h":"Como escrever o -ing","p":["Em geral, só acrescente: read → <b>reading</b>. Se termina em -e, tire o e: dance → <b>dancing</b>. Se termina em consoante + vogal + consoante, dobre a última: run → <b>running</b>, swim → <b>swimming</b>."],"ex":[["dancing","dançar"],["swimming","nadar"]]}],"vocab":[{"h":"Atividades","items":[["reading","ler"],["swimming","nadar"],["running","correr"],["cooking","cozinhar"],["dancing","dançar"],["watching TV","ver TV"],["playing video games","jogar videogame"],["going to the movies","ir ao cinema"],["listening to music","ouvir música"]]},{"h":"Frequência","items":[["always","sempre"],["usually","normalmente"],["often","frequentemente"],["sometimes","às vezes"],["never","nunca"],["once a week","uma vez por semana"],["twice a month","duas vezes por mês"],["on weekends","nos fins de semana"]]}],"pron":[{"h":"O -ing não tem “gui”","p":"O final <b>-ing</b> é nasal, com o g quase mudo: “RÍ-din”, nunca “ríding-gui”.","w":["reading","swimming","running"]},{"h":"often sem t","p":"Na maior parte dos falantes, o t de <b>often</b> é mudo: “Ó-fen”.","w":["often"]},{"h":"usually","p":"Soa algo como “IÚ-ju-a-li”, com o s soando como o “j” de “jeito”.","w":["usually"]}],"mc":[{"q":"O que a Sarah odeia?","o":["reading","swimming","running"],"a":2,"e":"I hate running!"},{"q":"Com que frequência o Lucas vai ao cinema?","o":["Todo dia","Uma vez por mês","Nunca"],"a":1,"e":"Maybe once a month."},{"q":"Qual frase está certa?","o":["I like of swimming.","I like swimming.","I like swim."],"a":1,"e":"like + -ing, sem “of”."},{"q":"Qual frase está certa?","o":["I read always.","I always read."],"a":1,"e":"A frequência vem antes do verbo principal."}],"gaps":[{"s":"I love ___.","a":["reading"],"h":"Adoro ler."},{"s":"I ___ run.","a":["never"],"h":"Eu nunca corro."},{"s":"How ___ do you go to the gym?","a":["often"],"h":"Com que frequência você vai à academia?"},{"s":"She ___ cooks.","a":["sometimes"],"h":"Ela às vezes cozinha."},{"s":"I go swimming ___ a week.","a":["once"],"h":"Nado uma vez por semana."}],"order":[{"t":["I","always","read","before","bed."],"h":"Sempre leio antes de dormir."},{"t":["Do","you","like","dancing?"],"h":"Você gosta de dançar?"},{"t":["We","sometimes","go","to","the","movies."],"h":"Às vezes vamos ao cinema."}],"dict":[{"t":"I love reading."},{"t":"I hate running."},{"t":"How often?"},{"t":"once a month"},{"t":"I usually play video games."}],"shadow":["What do you do in your free time?","I like swimming, but I hate running!","How often do you go to the movies?","Sometimes. Maybe once a month."],"write":{"task":"Conte do que você gosta e não gosta de fazer no tempo livre, e com que frequência faz cada coisa.","ph":"I love … I usually …"},"cards":[["O que você faz no tempo livre?","What do you do in your free time?"],["Adoro ler.","I love reading."],["Odeio correr.","I hate running."],["Nunca vou à academia.","I never go to the gym."],["Com que frequência?","How often?"],["Uma vez por semana.","Once a week."],["Às vezes cozinho.","I sometimes cook."],["Eu também!","Me too!"]]},{"title":"Food and drink","goal":"Pedir comida e bebida num café ou restaurante com educação.","speakers":{"Waiter":"m","Sarah":"f"},"setting":"Sarah está num café em Toronto.","lines":[["Waiter","Hi! Are you ready to order?","Oi! Já quer pedir?"],["Sarah","Yes. Can I have a coffee, please?","Quero. Pode me ver um café, por favor?"],["Waiter","Sure. With milk?","Claro. Com leite?"],["Sarah","Yes, a little milk, please.","Sim, um pouco de leite, por favor."],["Waiter","Anything to eat?","Algo para comer?"],["Sarah","Do you have any sandwiches?","Vocês têm sanduíches?"],["Waiter","Yes, we have some cheese sandwiches and some chicken sandwiches.","Temos, sim: sanduíches de queijo e de frango."],["Sarah","I'd like a chicken sandwich, please.","Eu queria um sanduíche de frango, por favor."],["Waiter","Here you are. That's eight dollars.","Aqui está. São oito dólares."],["Sarah","Thanks!","Obrigada!"]],"grammar":[{"h":"Contáveis e incontáveis","p":["Algumas coisas se contam: <b>a sandwich</b>, <b>two sandwiches</b>. Outras não: <b>milk</b>, <b>water</b>, <b>bread</b>, <b>cheese</b>. As incontáveis não têm plural nem <b>a</b>."],"ex":[["an egg, two eggs","um ovo, dois ovos"],["some bread","pão (um pouco)"]],"tip":"No café, <b>a coffee</b> e <b>two coffees</b> são normais: quer dizer uma xícara, duas xícaras."},{"h":"some e any","p":["<b>some</b> em frases afirmativas: <b>We have some sandwiches</b>. <b>any</b> em perguntas e negativas: <b>Do you have any juice?</b> <b>We don't have any milk.</b>"],"ex":[["I'd like some water.","Eu queria água."],["Do you have any tea?","Vocês têm chá?"]],"tip":"Para oferecer ou pedir algo, também se usa <b>some</b> na pergunta: <b>Would you like some coffee?</b>"},{"h":"Pedindo com educação","p":["<b>Can I have…, please?</b> e <b>I'd like…</b> (I would like) são as formas normais de pedir."],"ex":[["Can I have the check, please?","Pode me trazer a conta, por favor?"],["I'd like a tea.","Eu queria um chá."]],"tip":"<b>I want a coffee</b> soa seco e mal-educado num restaurante."}],"vocab":[{"h":"Comida","items":[["bread","pão"],["cheese","queijo"],["chicken","frango"],["salad","salada"],["sandwich","sanduíche"],["egg","ovo"],["rice","arroz"],["beans","feijão"],["fruit","fruta"]]},{"h":"Bebidas e frases","items":[["water","água"],["coffee","café"],["tea","chá"],["milk","leite"],["juice","suco"],["Can I have…?","pode me ver…?"],["I'd like…","eu queria…"],["The check, please.","a conta, por favor"],["Here you are.","aqui está"]]}],"pron":[{"h":"I'd like","p":"O d de <b>I'd</b> quase some: “aid laik”.","w":["I'd like a coffee"]},{"h":"water americano","p":"No inglês americano, o t entre vogais vira um “r” rápido, como em “caro”: “UÓ-rer”.","w":["water","better"]},{"h":"chicken e cheese","p":"O ch soa “tch”. <b>chicken</b> tem i curto; <b>cheese</b> tem i longo e termina em “z”.","w":["chicken","cheese"]}],"mc":[{"q":"O que a Sarah pede para comer?","o":["Sanduíche de queijo","Sanduíche de frango","Salada"],"a":1,"e":"I'd like a chicken sandwich."},{"q":"Quanto ela paga?","o":["$8","$18","$80"],"a":0,"e":"That's eight dollars."},{"q":"Qual pergunta está certa?","o":["Do you have some sandwiches?","Do you have any sandwiches?"],"a":1,"e":"Em perguntas, use any."},{"q":"Qual pedido é mais educado?","o":["I want a coffee.","Can I have a coffee, please?"],"a":1,"e":"Can I have…, please? é o padrão."}],"gaps":[{"s":"Can I ___ a coffee, please?","a":["have"],"h":"Pode me ver um café, por favor?"},{"s":"Do you have ___ sandwiches?","a":["any"],"h":"Vocês têm sanduíches?"},{"s":"We have ___ cheese sandwiches.","a":["some"],"h":"Temos sanduíches de queijo."},{"s":"I'd ___ a tea, please.","a":["like"],"h":"Eu queria um chá, por favor."},{"s":"___ you are.","a":["Here"],"h":"Aqui está."}],"order":[{"t":["Can","I","have","a","coffee,","please?"],"h":"Pode me ver um café, por favor?"},{"t":["I'd","like","a","chicken","sandwich."],"h":"Eu queria um sanduíche de frango."},{"t":["We","don't","have","any","milk."],"h":"Não temos leite."}],"dict":[{"t":"Can I have a coffee, please?"},{"t":"I'd like some water."},{"t":"Do you have any juice?"},{"t":"Here you are."}],"shadow":["Are you ready to order?","Can I have a coffee, please?","Do you have any sandwiches?","I'd like a chicken sandwich, please."],"write":{"task":"Você está num café. Escreva o seu lado do diálogo: o que quer beber e comer, e peça a conta.","ph":"Can I have …"},"cards":[["Pode me ver um café, por favor?","Can I have a coffee, please?"],["Eu queria um sanduíche.","I'd like a sandwich."],["Vocês têm suco?","Do you have any juice?"],["Não temos leite.","We don't have any milk."],["Aqui está.","Here you are."],["A conta, por favor.","The check, please."],["Um pouco de água.","Some water."],["Algo para comer?","Anything to eat?"]]},{"title":"My city","goal":"Perguntar o que tem num lugar, descrever onde fica e entender direções.","speakers":{"Lucas":"m","Kate":"f"},"setting":"Lucas precisa de uma farmácia e pede ajuda a uma moradora, a Kate.","lines":[["Lucas","Excuse me. Is there a pharmacy near here?","Com licença. Tem uma farmácia aqui perto?"],["Kate","Yes, there is. It's on Main Street.","Tem, sim. Fica na Main Street."],["Lucas","How do I get there?","Como eu chego lá?"],["Kate","Go straight and turn left at the bank.","Siga reto e vire à esquerda no banco."],["Lucas","Turn left at the bank. OK.","À esquerda no banco. Certo."],["Kate","The pharmacy is next to a café, opposite the park.","A farmácia fica ao lado de um café, em frente ao parque."],["Lucas","Are there any supermarkets on that street?","Tem supermercados nessa rua?"],["Kate","Yes, there are two.","Tem, sim, dois."],["Lucas","Great, thank you!","Ótimo, obrigado!"],["Kate","You're welcome!","De nada!"]],"grammar":[{"h":"There is e there are","p":["Para dizer que algo existe num lugar, use <b>there is</b> (singular) e <b>there are</b> (plural). É o “tem” e o “há” do português."],"ex":[["There's a park near my house.","Tem um parque perto da minha casa."],["There are two banks.","Tem dois bancos."]],"tip":"“Have a park here” está errado. O certo é <b>There's a park here</b>."},{"h":"Perguntas e negativas","p":["Pergunta: <b>Is there…?</b> / <b>Are there any…?</b> Negativa: <b>There isn't…</b> / <b>There aren't any…</b>"],"ex":[["Is there a bank near here?","Tem um banco aqui perto?"],["There aren't any hotels.","Não tem hotéis."]]},{"h":"Onde fica","p":["<b>next to</b> (ao lado de), <b>opposite</b> (em frente a), <b>between</b> (entre), <b>near</b> (perto de), <b>on the corner</b> (na esquina). Para ruas, <b>on</b>: on Main Street. Para cidades, <b>in</b>: in London."],"ex":[["It's next to the bank.","Fica ao lado do banco."],["It's between the café and the hotel.","Fica entre o café e o hotel."]]},{"h":"Dando direções","p":["<b>Go straight</b> (siga reto), <b>turn left</b> (vire à esquerda), <b>turn right</b> (vire à direita), <b>it's on the left</b> (fica à esquerda)."],"ex":[["Turn right at the park.","Vire à direita no parque."],["It's on the left.","Fica à esquerda."]]}],"vocab":[{"h":"Lugares","items":[["bank","banco"],["pharmacy","farmácia"],["supermarket","supermercado"],["park","parque"],["bus stop","ponto de ônibus"],["subway station","estação de metrô"],["hotel","hotel"],["museum","museu"],["street","rua"]]},{"h":"Direções","items":[["go straight","siga reto"],["turn left","vire à esquerda"],["turn right","vire à direita"],["next to","ao lado de"],["opposite","em frente a"],["between","entre"],["near","perto de"],["far","longe"]]}],"pron":[{"h":"there's e there are","p":"O th vibra, como em <b>the</b>. Em <b>there are</b>, as palavras se ligam: “dhé-rar”.","w":["there's","there are"]},{"h":"straight sem g","p":"<b>straight</b> soa “strêit”: o gh é mudo.","w":["straight"]},{"h":"O r inglês","p":"Em <b>right</b>, a língua não toca o céu da boca: ela se curva um pouco para trás.","w":["right","street"]}],"mc":[{"q":"Onde fica a farmácia?","o":["Ao lado de um café","Ao lado do banco","Entre dois parques"],"a":0,"e":"next to a café, opposite the park."},{"q":"Onde o Lucas deve virar?","o":["À esquerda no banco","À direita no parque"],"a":0,"e":"turn left at the bank."},{"q":"Como dizer “Tem um parque aqui?”","o":["Have a park here?","Is there a park here?"],"a":1,"e":"Use Is there…?"},{"q":"Como dizer “Tem dois bancos”?","o":["There is two banks.","There are two banks."],"a":1,"e":"No plural, there are."}],"gaps":[{"s":"___ there a bank near here?","a":["Is"],"h":"Tem um banco aqui perto?"},{"s":"There ___ two supermarkets.","a":["are"],"h":"Tem dois supermercados."},{"s":"Turn ___ at the bank.","a":["left"],"h":"Vire à esquerda no banco."},{"s":"It's next ___ the café.","a":["to"],"h":"Fica ao lado do café."},{"s":"Go ___.","a":["straight"],"h":"Siga reto."}],"order":[{"t":["Is","there","a","pharmacy","near","here?"],"h":"Tem uma farmácia aqui perto?"},{"t":["Turn","right","at","the","park."],"h":"Vire à direita no parque."},{"t":["The","bank","is","opposite","the","hotel."],"h":"O banco fica em frente ao hotel."}],"dict":[{"t":"Is there a bank near here?"},{"t":"Turn left."},{"t":"Go straight."},{"t":"next to the café"},{"t":"You're welcome."}],"shadow":["Is there a pharmacy near here?","How do I get there?","Go straight and turn left at the bank.","You're welcome!"],"write":{"task":"Descreva o seu bairro: o que tem perto da sua casa e onde fica cada lugar.","ph":"There's a … near my house. It's next to …"},"cards":[["Tem uma farmácia aqui perto?","Is there a pharmacy near here?"],["Como eu chego lá?","How do I get there?"],["Siga reto.","Go straight."],["Vire à esquerda.","Turn left."],["Fica ao lado do banco.","It's next to the bank."],["Em frente ao parque.","Opposite the park."],["Tem dois supermercados.","There are two supermarkets."],["De nada.","You're welcome."]]},{"title":"I can do it","goal":"Dizer o que você sabe e não sabe fazer, e pedir permissão ou ajuda.","speakers":{"Emma":"f","Lucas":"m"},"setting":"Lucas quer ser voluntário num festival. Emma, a organizadora, faz algumas perguntas.","lines":[["Emma","So, Lucas, can you speak Spanish?","Então, Lucas, você fala espanhol?"],["Lucas","Yes, I can. A little.","Falo, sim. Um pouco."],["Emma","Can you drive?","Você sabe dirigir?"],["Lucas","No, I can't. But I can ride a bike.","Não sei. Mas sei andar de bicicleta."],["Emma","That's fine. Can you work on Saturday?","Tudo bem. Você pode trabalhar no sábado?"],["Lucas","Yes, I can. Can I bring a friend?","Posso, sim. Posso levar um amigo?"],["Emma","Of course! Can he cook?","Claro! Ele sabe cozinhar?"],["Lucas","Yes, he can. He's a great cook!","Sabe, sim. Ele cozinha muito bem!"],["Emma","Perfect. See you on Saturday!","Perfeito. Até sábado!"]],"grammar":[{"h":"can: saber, conseguir, poder","p":["<b>can</b> serve para habilidade (saber, conseguir) e para possibilidade ou permissão (poder). Depois dele vem o verbo na forma básica, sem <b>to</b>.","<b>can</b> nunca muda: <b>I can</b>, <b>she can</b>, <b>they can</b>."],"ex":[["I can swim.","Eu sei nadar."],["She can speak three languages.","Ela fala três línguas."]],"tip":"“She cans” e “I can to swim” estão errados."},{"h":"Negativa e pergunta","p":["Negativa: <b>can't</b> (cannot). Pergunta: <b>Can you…?</b> Respostas curtas: <b>Yes, I can.</b> <b>No, I can't.</b>"],"ex":[["I can't drive.","Não sei dirigir."],["Can he cook? — Yes, he can.","Ele sabe cozinhar? — Sabe."]]},{"h":"Pedidos e permissão","p":["<b>Can I…?</b> pede permissão. <b>Can you…?</b> pede um favor."],"ex":[["Can I come in?","Posso entrar?"],["Can you help me?","Você pode me ajudar?"],["Can you speak slowly, please?","Pode falar devagar, por favor?"]]}],"vocab":[{"h":"Habilidades","items":[["speak English","falar inglês"],["drive","dirigir"],["cook","cozinhar"],["swim","nadar"],["dance","dançar"],["sing","cantar"],["play the guitar","tocar violão"],["ride a bike","andar de bicicleta"],["use a computer","usar o computador"]]},{"h":"Pedidos úteis","items":[["Can I come in?","posso entrar?"],["Can you help me?","pode me ajudar?"],["Can you repeat, please?","pode repetir, por favor?"],["Can you speak slowly, please?","pode falar devagar, por favor?"],["Of course!","claro!"]]}],"pron":[{"h":"can ou can't?","p":"Na frase, <b>can</b> é fraco e rápido: “kãn”. <b>can't</b> é forte, com vogal aberta, e o t final quase some. A diferença está na força, não no t.","w":["I can swim.","I can't swim."]},{"h":"guitar","p":"A força cai no fim: gi-TAR.","w":["guitar"]}],"mc":[{"q":"O Lucas sabe dirigir?","o":["Sim","Não"],"a":1,"e":"No, I can't."},{"q":"O que o amigo do Lucas sabe fazer bem?","o":["Dirigir","Cozinhar","Dançar"],"a":1,"e":"He's a great cook!"},{"q":"Qual frase está certa?","o":["She can to swim.","She can swim.","She cans swim."],"a":1,"e":"can + verbo básico, sem to e sem -s."},{"q":"Como pedir para alguém falar devagar?","o":["Can you speak slowly, please?","You can speak slowly?"],"a":0,"e":"Pergunta com can: Can you…?"}],"gaps":[{"s":"___ you drive?","a":["Can"],"h":"Você sabe dirigir?"},{"s":"I ___ swim.","a":["can't","cannot","can not"],"h":"Não sei nadar."},{"s":"He can ___ very well.","a":["cook"],"h":"Ele cozinha muito bem."},{"s":"___ I come in?","a":["Can"],"h":"Posso entrar?"},{"s":"Can you ___, please?","a":["repeat"],"h":"Pode repetir, por favor?"}],"order":[{"t":["Can","you","help","me?"],"h":"Você pode me ajudar?"},{"t":["I","can't","drive."],"h":"Não sei dirigir."},{"t":["She","can","speak","three","languages."],"h":"Ela fala três línguas."}],"dict":[{"t":"Can you drive?"},{"t":"No, I can't."},{"t":"Can I come in?"},{"t":"Can you speak slowly, please?"},{"t":"He can cook."}],"shadow":["Can you speak Spanish?","No, I can't. But I can ride a bike.","Can I bring a friend?","Can you speak slowly, please?"],"write":{"task":"Escreva o que você sabe e não sabe fazer: pelo menos 3 de cada.","ph":"I can … I can't …"},"cards":[["Você sabe dirigir?","Can you drive?"],["Não sei nadar.","I can't swim."],["Posso entrar?","Can I come in?"],["Você pode me ajudar?","Can you help me?"],["Pode repetir, por favor?","Can you repeat, please?"],["Pode falar devagar?","Can you speak slowly, please?"],["Ela fala três línguas.","She can speak three languages."],["Sei tocar violão.","I can play the guitar."]]},{"title":"Right now","goal":"Contar o que está acontecendo agora, falar do tempo e das roupas.","speakers":{"Sarah":"f","Lucas":"m"},"setting":"Sarah faz uma chamada de vídeo para o Lucas.","lines":[["Sarah","Hi, Lucas! What are you doing?","Oi, Lucas! O que você está fazendo?"],["Lucas","I'm cooking dinner. What about you?","Estou fazendo o jantar. E você?"],["Sarah","I'm walking in the park. It's sunny today!","Estou caminhando no parque. Está sol hoje!"],["Lucas","Lucky you! It's raining here.","Que sorte! Aqui está chovendo."],["Sarah","Oh no! Is it cold?","Ah, não! Está frio?"],["Lucas","Yes, it is. I'm wearing a big sweater.","Está. Estou com um suéter grosso."],["Sarah","Are your roommates home?","Seus colegas de apartamento estão em casa?"],["Lucas","Yes, they're watching a movie in the living room.","Estão, estão vendo um filme na sala."],["Sarah","OK, have fun. Talk to you later!","Beleza, divirta-se. Falo com você depois!"]],"grammar":[{"h":"Present continuous: o que acontece agora","p":["Para o que está acontecendo neste momento, use <b>am, is, are</b> + verbo com <b>-ing</b>: <b>I'm cooking</b>, <b>she's walking</b>, <b>they're watching</b>."],"ex":[["I'm cooking dinner.","Estou fazendo o jantar."],["They're watching a movie.","Eles estão vendo um filme."]],"tip":"Não esqueça o verbo to be: “I cooking” está errado."},{"h":"Pergunta e negativa","p":["Pergunta: troque a ordem: <b>What are you doing?</b> <b>Is she working?</b> Negativa: <b>I'm not</b>, <b>she isn't</b>, <b>they aren't</b> + -ing."],"ex":[["Is it raining?","Está chovendo?"],["She isn't working today.","Ela não está trabalhando hoje."]]},{"h":"Rotina ou agora?","p":["Present simple para hábitos: <b>I work every day</b>. Present continuous para agora: <b>I'm working now</b>."],"ex":[["I usually walk to work.","Normalmente vou a pé ao trabalho."],["I'm taking the bus today.","Hoje estou indo de ônibus."]]},{"h":"Falando do tempo","p":["O tempo sempre começa com <b>It's</b>: <b>It's sunny</b>, <b>It's cold</b>, <b>It's raining</b>."],"ex":[["It's hot today.","Está quente hoje."],["It's snowing!","Está nevando!"]],"tip":"“Is raining” está errado: o inglês exige o <b>it</b>."}],"vocab":[{"h":"Tempo","items":[["sunny","ensolarado"],["cloudy","nublado"],["raining","chovendo"],["snowing","nevando"],["windy","ventando"],["hot","quente"],["cold","frio"],["warm","morno, agradável"]]},{"h":"Roupas","items":[["T-shirt","camiseta"],["jeans","calça jeans"],["sweater","suéter, blusa de frio"],["jacket","jaqueta"],["dress","vestido"],["shoes","sapatos"],["sneakers","tênis"],["coat","casaco"]]}],"pron":[{"h":"sweater","p":"O <b>ea</b> soa “é”: “SUÉ-ter” (no americano, “SUÉ-rer”).","w":["sweater"]},{"h":"clothes","p":"Palavra difícil até para nativos: soa quase “clouz”.","w":["clothes"]},{"h":"cold ou called?","p":"<b>cold</b> tem um “ou” fechado: “kould”. <b>called</b> tem um “ó” aberto: “kóld”.","w":["cold","called"]}],"mc":[{"q":"O que o Lucas está fazendo?","o":["Cozinhando","Caminhando","Vendo um filme"],"a":0,"e":"I'm cooking dinner."},{"q":"Como está o tempo onde a Sarah está?","o":["Ensolarado","Chuvoso","Nevando"],"a":0,"e":"It's sunny today!"},{"q":"Qual frase está certa?","o":["I cooking dinner.","I'm cooking dinner."],"a":1,"e":"Precisa do to be: I'm."},{"q":"Como dizer “Está chovendo”?","o":["Is raining.","It's raining."],"a":1,"e":"O tempo sempre usa it."}],"gaps":[{"s":"What are you ___?","a":["doing"],"h":"O que você está fazendo?"},{"s":"It's ___ here.","a":["raining"],"h":"Aqui está chovendo."},{"s":"She ___ working now.","a":["is","'s"],"h":"Ela está trabalhando agora."},{"s":"They ___ watching a movie.","a":["are","'re"],"h":"Eles estão vendo um filme."},{"s":"I'm ___ a sweater.","a":["wearing"],"h":"Estou usando um suéter."}],"order":[{"t":["What","are","you","doing?"],"h":"O que você está fazendo?"},{"t":["It's","raining","here."],"h":"Aqui está chovendo."},{"t":["She's","wearing","a","jacket."],"h":"Ela está usando uma jaqueta."}],"dict":[{"t":"What are you doing?"},{"t":"It's sunny today."},{"t":"I'm cooking dinner."},{"t":"They're watching a movie."},{"t":"sweater"}],"shadow":["What are you doing?","I'm walking in the park. It's sunny today!","It's raining here.","Talk to you later!"],"write":{"task":"Descreva este momento: o que você está fazendo, como está o tempo e que roupa está usando.","ph":"Right now I'm … It's …"},"cards":[["O que você está fazendo?","What are you doing?"],["Estou fazendo o jantar.","I'm cooking dinner."],["Está chovendo.","It's raining."],["Está sol hoje.","It's sunny today."],["Está frio?","Is it cold?"],["Estou usando um suéter.","I'm wearing a sweater."],["Eles estão vendo um filme.","They're watching a movie."],["Falo com você depois!","Talk to you later!"]]},{"title":"Last weekend","goal":"Contar o que aconteceu no fim de semana, dizer onde você estava e como se sentiu, usando was/were e verbos regulares no passado.","speakers":{"Sarah":"f","Lucas":"m"},"setting":"Na segunda-feira, Sarah e Lucas conversam durante o intervalo do trabalho sobre o fim de semana.","lines":[["Sarah","Hey, Lucas! How was your weekend?","Oi, Lucas! Como foi seu fim de semana?"],["Lucas","It was great! I visited my sister on Saturday.","Foi ótimo! Visitei minha irmã no sábado."],["Sarah","Nice! Was she happy to see you?","Que legal! Ela ficou feliz em te ver?"],["Lucas","Yes, she was. We cooked dinner and watched a movie.","Ficou, sim. Fizemos o jantar e assistimos a um filme."],["Sarah","Sounds fun! What about Sunday?","Parece divertido! E no domingo?"],["Lucas","I stayed home and cleaned my apartment.","Fiquei em casa e limpei meu apartamento."],["Sarah","A busy weekend! Were you tired?","Um fim de semana cheio! Você estava cansado?"],["Lucas","A little, but I was happy. How was yours?","Um pouco, mas eu estava feliz. E como foi o seu?"],["Sarah","It was good! I walked in the park with Emma.","Foi bom! Caminhei no parque com a Emma."],["Lucas","Was the weather nice?","O tempo estava bom?"],["Sarah","Yes, it was sunny. Later, I called my parents.","Sim, estava ensolarado. Depois, liguei para os meus pais."],["Lucas","That's a nice weekend!","Esse foi um fim de semana legal!"]],"grammar":[{"h":"Was e were: o passado de to be","p":["Para falar de como alguém estava, onde estava ou como alguma coisa era no passado, usamos <b>was</b> ou <b>were</b>. Os dois significam “era”, “estava” ou “foi”, dependendo da frase.","Use <b>was</b> com I, he, she e it. Use <b>were</b> com you, we e they. No passado, não usamos am, is ou are."],"ex":[["I was tired on Sunday.","Eu estava cansado no domingo."],["She was at home yesterday.","Ela estava em casa ontem."],["We were at the park last weekend.","Estávamos no parque no fim de semana passado."],["They were happy after the concert.","Eles estavam felizes depois do show."]],"tip":"Mesmo com I, usamos <b>was</b>: I was happy. Com you, sempre usamos <b>were</b>: You were happy."},{"h":"Perguntas e negativas com was/were","p":["Para fazer perguntas, coloque <b>was</b> ou <b>were</b> antes da pessoa: <b>Was she happy?</b> (Ela estava feliz?). Para responder, use Yes, she was ou No, she wasn't.","Na negativa, use <b>wasn't</b> (was not) ou <b>weren't</b> (were not). Não precisamos de outro verbo auxiliar."],"ex":[["Was your weekend busy?","Seu fim de semana foi corrido?"],["Were you at home last night?","Você estava em casa ontem à noite?"],["He wasn't tired after work.","Ele não estava cansado depois do trabalho."],["They weren't at the party.","Eles não estavam na festa."]],"tip":"Atenção: <b>Were you tired?</b> está certo. Não use “Did you were tired?”."},{"h":"Past simple: verbos regulares com -ed","p":["Para contar ações concluídas no passado, muitos verbos recebem <b>-ed</b>. Por exemplo, visit vira visited, watch vira watched e clean vira cleaned.","O passado é igual para todas as pessoas: I visited, she visited, we visited. É comum usar expressões como yesterday, last weekend e last night para indicar quando algo aconteceu."],"ex":[["I visited my sister on Saturday.","Visitei minha irmã no sábado."],["We watched a movie at home.","Assistimos a um filme em casa."],["She cleaned her apartment yesterday.","Ela limpou o apartamento ontem."],["They relaxed all afternoon.","Eles descansaram a tarde inteira."]],"tip":"O verbo não muda com he, she ou it: <b>She worked</b>, e não “She workeds”."},{"h":"Como escrever o passado regular","p":["A regra geral é acrescentar <b>-ed</b>: work → worked. Se o verbo já termina em e, acrescente apenas <b>-d</b>: like → liked.","Se termina em consoante + y, troque y por <b>-ied</b>: study → studied. Alguns verbos curtos dobram a consoante final: stop → stopped."],"ex":[["I worked on Friday.","Trabalhei na sexta-feira."],["She liked the movie.","Ela gostou do filme."],["He studied English last night.","Ele estudou inglês ontem à noite."],["We stopped for coffee.","Paramos para tomar café."]],"tip":"Nem todo verbo segue essas regras. Verbos como go e eat são irregulares e serão estudados na próxima unidade."}],"vocab":[{"h":"Atividades no fim de semana","items":[["visited","visitou, visitei"],["cooked","cozinhou, cozinhei"],["watched","assistiu, assisti"],["walked","caminhou, caminhei"],["cleaned","limpou, limpei"],["called","ligou, liguei"],["stayed","ficou, fiquei"],["relaxed","descansou, descansei"]]},{"h":"Expressões de tempo e sentimentos","items":[["last weekend","fim de semana passado"],["on Saturday","no sábado"],["on Sunday","no domingo"],["yesterday","ontem"],["last night","ontem à noite"],["in the afternoon","à tarde"],["great","ótimo"],["tired","cansado"]]}],"pron":[{"h":"-ed com som de T","p":"Depois de sons surdos, como K, P e CH, o final <b>-ed</b> tem som de T. Por exemplo, watched soa aproximadamente “uótcht” e walked soa “uókt”. Não acrescente uma sílaba extra.","w":["watched","walked","cooked","worked"]},{"h":"-ed com som de D","p":"Depois de sons sonoros, exceto D, o <b>-ed</b> soa como D. Cleaned soa aproximadamente “klínd”, e stayed soa “stêid”. O final não forma uma sílaba separada.","w":["cleaned","called","stayed","played"]},{"h":"-ed com uma sílaba extra","p":"Quando o verbo termina com som de T ou D, o <b>-ed</b> cria uma sílaba extra, com som de “id”. Wanted soa aproximadamente “uón-tid”, e needed soa “ní-did”.","w":["wanted","needed","visited","started"]}],"mc":[{"q":"O que o Lucas fez no sábado?","o":["Visitou a irmã","Limpou o apartamento","Caminhou no parque"],"a":0,"e":"I visited my sister on Saturday."},{"q":"Como Lucas passou o domingo?","o":["Visitou os pais","Ficou em casa e limpou o apartamento","Foi ao cinema"],"a":1,"e":"I stayed home and cleaned my apartment."},{"q":"Com quem Sarah caminhou no parque?","o":["Com Emma","Com a irmã","Com os pais"],"a":0,"e":"I walked in the park with Emma."},{"q":"Como estava o tempo no domingo da Sarah?","o":["Nevando","Chuvoso","Ensolarado"],"a":2,"e":"Yes, it was sunny. Later, I called my parents."}],"gaps":[{"s":"Last weekend, I ___ at home.","a":["was"],"h":"No fim de semana passado, eu estava em casa."},{"s":"___ you tired on Sunday?","a":["Were"],"h":"Você estava cansado no domingo?"},{"s":"She ___ happy to see me yesterday.","a":["was"],"h":"Ela estava feliz em me ver ontem."},{"s":"I ___ my sister on Saturday.","a":["visited"],"h":"Visitei minha irmã no sábado."},{"s":"We ___ a movie last night.","a":["watched"],"h":"Assistimos a um filme ontem à noite."},{"s":"I ___ my apartment yesterday.","a":["cleaned"],"h":"Limpei meu apartamento ontem."}],"order":[{"t":["My","weekend","was","really","good."],"h":"Meu fim de semana foi muito bom."},{"t":["We","watched","a","movie","on","Saturday."],"h":"Assistimos a um filme no sábado."},{"t":["Were","you","tired","last","night?"],"h":"Você estava cansado ontem à noite?"}],"dict":[{"t":"How was your weekend?"},{"t":"I visited my sister on Saturday."},{"t":"We cooked dinner and watched a movie."},{"t":"I stayed home and cleaned my apartment."},{"t":"Were you tired?"}],"shadow":["How was your weekend?","It was great! I visited my sister on Saturday.","I stayed home and cleaned my apartment.","A little, but I was happy. How was yours?"],"write":{"task":"Conte como foi seu último fim de semana em 3 ou 4 frases. Diga como ele foi, onde você estava e duas atividades que fez. Use was/were e verbos regulares no passado.","ph":"Last weekend was … I was … On Saturday, I … On Sunday, I …"},"cards":[["Eu estava cansado depois do trabalho ontem.","I was tired after work yesterday."],["O filme foi ótimo ontem à noite.","The movie was great last night."],["Estávamos em casa no domingo.","We were at home on Sunday."],["Ela não estava ocupada ontem à tarde.","She wasn't busy yesterday afternoon."],["Você estava no parque no sábado?","Were you at the park on Saturday?"],["Visitei meus avós no fim de semana passado.","I visited my grandparents last weekend."],["Jogamos tênis no domingo à tarde.","We played tennis on Sunday afternoon."],["Ele trabalhou até tarde na sexta-feira.","He worked late on Friday night."],["Fiquei em casa e descansei a noite inteira.","I stayed home and relaxed all evening."],["Ela estudou inglês por uma hora ontem à noite.","She studied English for an hour last night."]]},{"title":"A trip","goal":"Contar como foi uma viagem, falar sobre transporte, passeios e experiências no passado, usando verbos irregulares e fazendo perguntas e negativas com did.","speakers":{"Emma":"f","Daniel":"m"},"setting":"Na segunda-feira, Emma e Daniel conversam durante o almoço sobre a viagem que Daniel fez a Chicago no fim de semana.","lines":[["Emma","Hey, Daniel! How was your trip to Chicago?","Oi, Daniel! Como foi sua viagem a Chicago?"],["Daniel","It was amazing! I went there with my brother.","Foi incrível! Fui para lá com meu irmão."],["Emma","Nice! Did you fly or take the train?","Que legal! Vocês foram de avião ou de trem?"],["Daniel","We flew on Friday morning. The flight was short.","Fomos de avião na sexta de manhã. O voo foi curto."],["Emma","What did you do on Saturday?","O que vocês fizeram no sábado?"],["Daniel","We took a boat tour and saw the city from the river.","Fizemos um passeio de barco e vimos a cidade do rio."],["Emma","That sounds great! Did you eat anything special?","Parece ótimo! Vocês comeram alguma coisa diferente?"],["Daniel","Yes, we ate deep-dish pizza. It was delicious!","Sim, comemos pizza de massa grossa. Estava deliciosa!"],["Emma","Did you buy any souvenirs?","Vocês compraram alguma lembrancinha?"],["Daniel","No, I didn't. I didn't have much time.","Não, eu não comprei. Não tive muito tempo."],["Emma","Where did you stay?","Onde vocês ficaram hospedados?"],["Daniel","We stayed at a small hotel downtown.","Ficamos em um hotel pequeno no centro."],["Emma","When did you come back?","Quando vocês voltaram?"],["Daniel","We came back on Sunday night. I was tired, but happy.","Voltamos no domingo à noite. Eu estava cansado, mas feliz."]],"grammar":[{"h":"Past simple: verbos irregulares","p":["Na unidade anterior, vimos verbos regulares, que geralmente recebem <b>-ed</b> no passado: work → worked, visit → visited. Mas muitos verbos comuns são <b>irregulares</b> e mudam de forma.","Por exemplo, go vira <b>went</b>, see vira <b>saw</b> e eat vira <b>ate</b>. Não existe uma regra única para essas mudanças: você precisa aprender as formas mais frequentes.","Assim como nos verbos regulares, a forma do passado é igual para todas as pessoas: I went, she went, we went."],"ex":[["I went to Chicago last weekend.","Fui a Chicago no fim de semana passado."],["We saw the city from the river.","Vimos a cidade do rio."],["She ate pizza for dinner.","Ela comeu pizza no jantar."],["They took the train yesterday.","Eles pegaram o trem ontem."]],"tip":"Não acrescente <b>-ed</b> a um verbo que já tem forma irregular. O passado de go é went, nunca “goed”."},{"h":"Perguntas no passado com did","p":["Para fazer perguntas sobre ações no passado, use <b>did</b> antes da pessoa e coloque o verbo principal na <b>forma base</b>, sem to.","A estrutura é: <b>Did + pessoa + verbo base?</b> Para perguntas com what, where, when ou how, coloque essa palavra no começo.","O did já indica o passado. Por isso, o verbo principal volta à forma base: <b>Did you go?</b>, e não “Did you went?”."],"ex":[["Did you fly to Chicago?","Você foi de avião para Chicago?"],["What did you do on Saturday?","O que você fez no sábado?"],["Where did she stay?","Onde ela ficou hospedada?"],["When did they come back?","Quando eles voltaram?"]],"tip":"Com <b>did</b>, use sempre a forma base do verbo: did + go, did + eat, did + see."},{"h":"Negativas e respostas curtas com didn't","p":["Para dizer que uma ação não aconteceu, usamos <b>did not</b>, geralmente contraído para <b>didn't</b>, seguido do verbo na forma base.","A estrutura é: <b>Pessoa + didn't + verbo base</b>. Por exemplo, I didn't go significa “Eu não fui”.","Para responder a perguntas com did, use <b>Yes, I did</b> ou <b>No, I didn't</b>, ajustando a pessoa conforme necessário."],"ex":[["I didn't buy any souvenirs.","Não comprei nenhuma lembrancinha."],["We didn't go by bus.","Não fomos de ônibus."],["Did you eat breakfast? Yes, I did.","Você tomou café da manhã? Sim."],["Did she fly? No, she didn't.","Ela foi de avião? Não."]],"tip":"Não diga “I didn't bought”. O correto é <b>I didn't buy</b>. O didn't já coloca a frase no passado."},{"h":"Did ou was/were?","p":["Use <b>did</b> para fazer perguntas sobre ações, como go, eat, buy e visit. Use <b>was/were</b> quando o verbo principal da frase for to be.","Compare: <b>Did you visit Chicago?</b> pergunta se a pessoa visitou a cidade. <b>Were you in Chicago?</b> pergunta se ela estava lá.","Nas negativas, a diferença continua: I didn't visit Chicago e I wasn't in Chicago."],"ex":[["Did you enjoy the trip?","Você gostou da viagem?"],["Was the hotel comfortable?","O hotel era confortável?"],["We didn't visit the museum.","Não visitamos o museu."],["The flight wasn't long.","O voo não foi longo."]],"tip":"Nunca misture did com was ou were na mesma estrutura: <b>Were you tired?</b>, e não “Did you were tired?”."}],"vocab":[{"h":"Verbos irregulares: presente e passado","items":[["go → went","ir → foi, fui"],["fly → flew","voar → voou, voei"],["take → took","pegar, levar → pegou, levou"],["see → saw","ver → viu, vi"],["eat → ate","comer → comeu, comi"],["buy → bought","comprar → comprou, comprei"],["have → had","ter → teve, tive"],["come → came","vir, voltar → veio, voltou"],["get → got","conseguir, chegar → conseguiu, chegou"],["make → made","fazer, criar → fez, criou"]]},{"h":"Viagens, transporte e passeios","items":[["trip","viagem"],["flight","voo"],["train","trem"],["boat tour","passeio de barco"],["river","rio"],["hotel","hotel"],["downtown","centro da cidade"],["souvenir","lembrancinha de viagem"],["airport","aeroporto"],["ticket","passagem, ingresso"]]}],"pron":[{"h":"Did you: a pronúncia natural","p":"Na fala rápida, <b>did you</b> costuma soar como “dídju”. Isso acontece porque o D final de did se junta ao som de Y em you. Em <b>Did you go?</b>, você pode ouvir algo próximo de “dídju gôu?”.","w":["did you","Did you go?","Did you eat?"]},{"h":"Flew e flight","p":"<b>Flew</b>, passado de fly, soa aproximadamente “flú”, com um U longo. Já <b>flight</b> tem o som de “ai”: “fláit”. São palavras relacionadas, mas com sons diferentes.","w":["fly","flew","flight"]},{"h":"Ate e eight","p":"No inglês americano, <b>ate</b>, passado de eat, geralmente soa “êit”. Tem a mesma pronúncia de <b>eight</b>, o número oito. Já <b>eat</b> soa aproximadamente “íit”, com um I longo.","w":["eat","ate","eight"]}],"mc":[{"q":"Como Daniel e o irmão viajaram para Chicago?","o":["De trem","De ônibus","De avião"],"a":2,"e":"We flew on Friday morning. The flight was short."},{"q":"O que Daniel e o irmão fizeram no sábado?","o":["Um passeio de barco","Uma visita a um museu","Um passeio de trem"],"a":0,"e":"We took a boat tour and saw the city from the river."},{"q":"O que Daniel comeu durante a viagem?","o":["Hambúrguer","Pizza de massa grossa","Sanduíche de frango"],"a":1,"e":"Yes, we ate deep-dish pizza. It was delicious!"},{"q":"Por que Daniel não comprou lembrancinhas?","o":["Porque eram muito caras","Porque não encontrou nenhuma","Porque não teve muito tempo"],"a":2,"e":"No, I didn't. I didn't have much time."}],"gaps":[{"s":"Last weekend, I ___ to Chicago.","a":["went"],"h":"No fim de semana passado, fui a Chicago."},{"s":"Did you ___ any souvenirs?","a":["buy"],"h":"Você comprou alguma lembrancinha?"},{"s":"We ___ a boat tour on Saturday.","a":["took"],"h":"Fizemos um passeio de barco no sábado."},{"s":"I didn't ___ much time to shop.","a":["have"],"h":"Não tive muito tempo para fazer compras."},{"s":"What ___ you do on Saturday?","a":["did"],"h":"O que você fez no sábado?"},{"s":"She didn't ___ to Chicago last year.","a":["go"],"h":"Ela não foi a Chicago no ano passado."}],"order":[{"t":["Did","you","take","the","train?"],"h":"Você pegou o trem?"},{"t":["We","ate","pizza","on","Saturday","night."],"h":"Comemos pizza no sábado à noite."},{"t":["I","didn't","buy","any","souvenirs."],"h":"Não comprei nenhuma lembrancinha."}],"dict":[{"t":"I went there with my brother."},{"t":"Did you fly or take the train?"},{"t":"We took a boat tour.","note":"Atenção ao passado irregular de take."},{"t":"I didn't have much time.","alt":["I did not have much time."]},{"t":"We came back on Sunday night."}],"shadow":["Hey, Daniel! How was your trip to Chicago?","We took a boat tour and saw the city from the river.","Did you buy any souvenirs?","We came back on Sunday night. I was tired, but happy."],"write":{"task":"Conte sobre uma viagem que você fez. Escreva de 4 a 5 frases dizendo para onde foi, como viajou, o que viu ou comeu e se gostou da experiência. Use pelo menos três verbos irregulares no passado e uma frase negativa com didn't.","ph":"Last year, I went to … I traveled by … I saw … I ate … I didn't …"},"cards":[["Fui a Chicago no mês passado.","I went to Chicago last month."],["Fomos de avião na sexta-feira.","We flew on Friday."],["Você pegou o trem?","Did you take the train?"],["Vimos a cidade do barco.","We saw the city from the boat."],["Comi pizza no jantar.","I ate pizza for dinner."],["Onde você ficou hospedado?","Where did you stay?"],["Não compramos nenhuma lembrancinha.","We didn't buy any souvenirs."],["Você gostou da viagem?","Did you enjoy the trip?"],["Voltei para casa no domingo.","I came home on Sunday."],["Não tive muito tempo.","I didn't have much time."]]},{"title":"Life stories","goal":"Contar uma biografia curta, falar sobre acontecimentos importantes da vida e dizer quando algo aconteceu usando ago, when, in + ano e verbos no passado.","speakers":{"Sarah":"f","Emma":"f"},"setting":"Sarah visita Emma em uma tarde de sábado. Enquanto olham um álbum de fotos, Emma conta a história de vida de sua avó.","lines":[["Sarah","Who's that in the old photo?","Quem é aquela na foto antiga?"],["Emma","That's my grandma. She was born in 1958.","É minha avó. Ela nasceu em 1958."],["Sarah","Really? Where did she grow up?","Sério? Onde ela cresceu?"],["Emma","She grew up in a small town in Ohio.","Ela cresceu em uma cidade pequena em Ohio."],["Sarah","When did she move to Boston?","Quando ela se mudou para Boston?"],["Emma","She moved there in 1980, when she was 22.","Ela se mudou para lá em 1980, quando tinha 22 anos."],["Sarah","What did she do in Boston?","O que ela fez em Boston?"],["Emma","She studied nursing and started working at a hospital.","Ela estudou enfermagem e começou a trabalhar em um hospital."],["Sarah","Did she meet your grandpa there?","Ela conheceu seu avô lá?"],["Emma","Yes, they met in 1983 and got married two years later.","Sim, eles se conheceram em 1983 e se casaram dois anos depois."],["Sarah","Did she work there for a long time?","Ela trabalhou lá por muito tempo?"],["Emma","Yes, for 35 years. She retired five years ago.","Sim, por 35 anos. Ela se aposentou há cinco anos."],["Sarah","Does she still live in Boston?","Ela ainda mora em Boston?"],["Emma","No, she moved to Florida last year. She loves the beach.","Não, ela se mudou para a Flórida no ano passado. Ela adora a praia."]],"grammar":[{"h":"In + ano: quando algo aconteceu","p":["Para dizer em que ano um acontecimento ocorreu, usamos <b>in + ano</b>. Essa estrutura é muito comum ao contar histórias de vida.","Use o verbo no passado para ações concluídas: <b>She moved in 1980</b> (Ela se mudou em 1980).","Para dizer quando alguém nasceu, usamos <b>was born</b> ou <b>were born</b>. A expressão born não muda."],"ex":[["My mother was born in 1965.","Minha mãe nasceu em 1965."],["He moved to New York in 2010.","Ele se mudou para Nova York em 2010."],["They met in 1998.","Eles se conheceram em 1998."],["We were born in 2001.","Nós nascemos em 2001."]],"tip":"Use <b>in</b> com anos: in 1990, in 2015. Não use on ou at antes de um ano isolado."},{"h":"Ago: há quanto tempo","p":["Usamos <b>ago</b> para dizer quanto tempo se passou desde um acontecimento. Em português, geralmente corresponde a “há” ou “atrás”.","A estrutura é <b>quantidade de tempo + ago</b>: two days ago, five years ago, a month ago.","O ago aparece depois da expressão de tempo. Ele conta o tempo para trás a partir de agora e costuma acompanhar o past simple."],"ex":[["I started this job three years ago.","Comecei neste emprego há três anos."],["She called me two hours ago.","Ela me ligou há duas horas."],["We moved here a month ago.","Nós nos mudamos para cá há um mês."],["He retired ten years ago.","Ele se aposentou há dez anos."]],"tip":"Não confunda <b>ago</b> com <b>for</b>: three years ago indica quando algo aconteceu; for three years indica uma duração."},{"h":"When: quando aconteceu?","p":["Usamos <b>when</b> para perguntar quando um acontecimento ocorreu. No past simple, a estrutura é <b>When + did + pessoa + verbo base?</b>.","Também usamos when para conectar dois fatos do passado. Nesse caso, significa “quando” e pode aparecer no meio ou no começo da frase.","Para indicar a idade em que algo aconteceu, use <b>when I was</b>, <b>when she was</b> ou <b>when they were</b>."],"ex":[["When did you finish school?","Quando você terminou a escola?"],["When did they get married?","Quando eles se casaram?"],["I moved when I was 20.","Eu me mudei quando tinha 20 anos."],["When she was young, she lived in Ohio.","Quando era jovem, ela morava em Ohio."]],"tip":"Em perguntas, use <b>When did she move?</b>. Em frases afirmativas, não use did: <b>She moved when she was 22.</b>"},{"h":"Contando uma biografia em ordem","p":["Para contar uma história de vida, organize os fatos do mais antigo para o mais recente. Você pode começar com <b>was born</b> (nasceu) e <b>grew up</b> (cresceu).","Depois, conte os acontecimentos importantes com verbos no passado, como studied, moved, met, started e worked.","Use <b>then</b> (então, depois), <b>later</b> (mais tarde) e <b>after that</b> (depois disso) para organizar a sequência. A expressão two years later significa “dois anos depois” de um acontecimento já mencionado."],"ex":[["She was born in a small town.","Ela nasceu em uma cidade pequena."],["He grew up near the beach.","Ele cresceu perto da praia."],["She studied English and then moved abroad.","Ela estudou inglês e depois se mudou para o exterior."],["They met in 2005 and married three years later.","Eles se conheceram em 2005 e se casaram três anos depois."]],"tip":"<b>Ago</b> conta o tempo a partir de agora. <b>Later</b> indica um momento posterior a outro acontecimento da história."}],"vocab":[{"h":"Acontecimentos importantes da vida","items":[["be born → was/were born","nascer → nasceu, nasci"],["grow up → grew up","crescer → cresceu, cresci"],["move → moved","mudar-se → mudou-se"],["study → studied","estudar → estudou"],["meet → met","conhecer alguém → conheceu"],["get married → got married","casar-se → casou-se"],["start → started","começar → começou"],["retire → retired","aposentar-se → aposentou-se"],["graduate → graduated","formar-se → formou-se"],["live → lived","morar → morou"]]},{"h":"Tempo e fases da vida","items":[["a year ago","há um ano"],["five years ago","há cinco anos"],["two years later","dois anos depois"],["when I was young","quando eu era jovem"],["in 1995","em 1995"],["childhood","infância"],["teenager","adolescente"],["adult","adulto"],["after that","depois disso"],["a long time ago","há muito tempo"]]}],"pron":[{"h":"Born","p":"Em <b>born</b>, o R é pronunciado no inglês americano. A palavra soa aproximadamente “bórn”, com a língua se curvando para produzir o R. Não pronuncie como “bón”.","w":["born","was born","were born"]},{"h":"Grew up","p":"<b>Grew</b>, passado de grow, soa aproximadamente “grú”, com U longo. Na expressão <b>grew up</b>, as duas palavras se conectam naturalmente na fala: “grú-âp”.","w":["grow","grew","grew up"]},{"h":"Ago: a sílaba forte","p":"Em <b>ago</b>, a segunda sílaba é a mais forte: “a-GÔU”. A primeira é curta e fraca. Em <b>years ago</b>, a expressão soa aproximadamente “yírz a-GÔU”.","w":["ago","years ago","a month ago"]}],"mc":[{"q":"Em que ano a avó de Emma nasceu?","o":["Em 1980","Em 1958","Em 1983"],"a":1,"e":"That's my grandma. She was born in 1958."},{"q":"Onde a avó de Emma cresceu?","o":["Em uma cidade pequena em Ohio","No centro de Boston","Na Flórida"],"a":0,"e":"She grew up in a small town in Ohio."},{"q":"Quando os avós de Emma se conheceram?","o":["Em 1980","Em 1985","Em 1983"],"a":2,"e":"Yes, they met in 1983 and got married two years later."},{"q":"Há quanto tempo a avó de Emma se aposentou?","o":["Há 35 anos","Há cinco anos","Há um ano"],"a":1,"e":"Yes, for 35 years. She retired five years ago."}],"gaps":[{"s":"My grandfather was born ___ 1948.","a":["in"],"h":"Meu avô nasceu em 1948."},{"s":"She retired five years ___.","a":["ago"],"h":"Ela se aposentou há cinco anos."},{"s":"___ did your parents get married?","a":["When"],"h":"Quando seus pais se casaram?"},{"s":"He ___ up in a small town.","a":["grew"],"h":"Ele cresceu em uma cidade pequena."},{"s":"I moved to Boston when I ___ 20.","a":["was"],"h":"Eu me mudei para Boston quando tinha 20 anos."},{"s":"They met in 2000 and married two years ___.","a":["later"],"h":"Eles se conheceram em 2000 e se casaram dois anos depois."}],"order":[{"t":["She","was","born","in","1985."],"h":"Ela nasceu em 1985."},{"t":["When","did","you","move","here?"],"h":"Quando você se mudou para cá?"},{"t":["He","retired","five","years","ago."],"h":"Ele se aposentou há cinco anos."}],"dict":[{"t":"She was born in 1958."},{"t":"She grew up in a small town in Ohio.","note":"Atenção à forma irregular grew, passado de grow."},{"t":"When did she move to Boston?"},{"t":"They met in 1983 and got married two years later."},{"t":"She retired five years ago."}],"shadow":["That's my grandma. She was born in 1958.","She moved there in 1980, when she was 22.","Yes, they met in 1983 and got married two years later.","No, she moved to Florida last year. She loves the beach."],"write":{"task":"Escreva uma biografia curta de alguém da sua família ou de uma pessoa que você admira. Use de 4 a 5 frases. Conte quando e onde a pessoa nasceu, onde cresceu e dois acontecimentos importantes da vida dela. Inclua in + ano, when e ago, se possível.","ph":"My … was born in … in … She/He grew up in … When she/he was …, … A few years ago, …"},"cards":[["Meu pai nasceu em 1970.","My father was born in 1970."],["Ela cresceu perto do mar.","She grew up near the ocean."],["Meus pais se conheceram em 1995.","My parents met in 1995."],["Quando você terminou a escola?","When did you finish school?"],["Comecei meu primeiro emprego em 2019.","I started my first job in 2019."],["Ele se mudou para cá há seis meses.","He moved here six months ago."],["Conheci minha melhor amiga há três anos.","I met my best friend three years ago."],["Eles se casaram em 2010.","They got married in 2010."],["Ela se aposentou no ano passado.","She retired last year."],["Nós nos mudamos para outra cidade quando eu tinha dez anos.","We moved to another city when I was ten."]]},{"title":"Shopping","goal":"Comparar roupas, preços e tamanhos, dizer quando algo é grande ou pequeno demais e explicar se uma peça é confortável ou adequada usando comparativos, as...as, too e enough.","speakers":{"Sarah":"f","Emma":"f"},"setting":"Sarah e Emma estão em uma loja de roupas no shopping, em uma tarde de sábado. Sarah procura uma jaqueta nova e aproveita para experimentar algumas peças.","lines":[["Sarah","Hey, Emma! What do you think of this blue jacket?","Ei, Emma! O que você acha desta jaqueta azul?"],["Emma","It looks nice, but is it the right size?","Ela é bonita, mas é do tamanho certo?"],["Sarah","No, it's too small. The black one is bigger.","Não, é pequena demais. A preta é maior."],["Emma","Try it on. It looks more comfortable, too.","Experimenta. Ela também parece mais confortável."],["Sarah","It is, but it's more expensive than the blue one.","É mesmo, mas é mais cara que a azul."],["Emma","How much are they?","Quanto custam?"],["Sarah","The black one is $85, and the blue one is $60.","A preta custa 85 dólares, e a azul custa 60."],["Emma","Is the black one warmer?","A preta é mais quente?"],["Sarah","Yes, but it isn't as light as the blue one.","Sim, mas não é tão leve quanto a azul."],["Emma","Your old jacket isn't warm enough, right?","Sua jaqueta antiga não esquenta o suficiente, né?"],["Sarah","Right. The black one is better for winter.","Isso. A preta é melhor para o inverno."],["Emma","What about these jeans? They're cheaper than those.","E esta calça jeans? É mais barata que aquela."],["Sarah","They're nice, but they're too long for me.","É bonita, mas é comprida demais para mim."],["Emma","Let's find a shorter pair in your size.","Vamos procurar uma calça mais curta do seu tamanho."]],"grammar":[{"h":"Comparativos com -er","p":["Para comparar duas coisas, usamos o <b>comparativo</b>. Com adjetivos curtos, geralmente acrescentamos <b>-er</b>: cheap → cheaper (mais barato), small → smaller (menor), warm → warmer (mais quente).","Para dizer com o que estamos comparando, usamos <b>than</b> (do que): This jacket is cheaper than that one.","Alguns adjetivos mudam a escrita: big → bigger (dobra a consoante final), nice → nicer (só acrescenta -r) e easy → easier (troca y por -ier)."],"ex":[["The black jacket is bigger.","A jaqueta preta é maior."],["These jeans are shorter than those.","Esta calça jeans é mais curta que aquela."],["This T-shirt is cheaper than that one.","Esta camiseta é mais barata que aquela."],["The blue shirt is nicer than the green one.","A camisa azul é mais bonita que a verde."]],"tip":"Para comparar duas peças, use <b>than</b>, não then. Than significa “do que”; then significa “então” ou “depois”."},{"h":"More + adjetivo e comparativos irregulares","p":["Com adjetivos mais longos, normalmente usamos <b>more + adjetivo</b>: more expensive (mais caro), more comfortable (mais confortável). Não acrescentamos -er nesses casos.","Alguns comparativos são irregulares: <b>good → better</b> (bom → melhor) e <b>bad → worse</b> (ruim → pior).","Para não repetir o nome de uma peça, podemos usar <b>one</b> no singular e <b>ones</b> no plural: the black one (a preta), the cheaper ones (os mais baratos)."],"ex":[["This coat is more expensive than that one.","Este casaco é mais caro que aquele."],["These shoes are more comfortable.","Estes sapatos são mais confortáveis."],["The black jacket is better for winter.","A jaqueta preta é melhor para o inverno."],["These jeans are worse than my old ones.","Esta calça jeans é pior que a minha antiga."]],"tip":"Não diga “more cheaper” nem “more better”. Use apenas <b>cheaper</b> e <b>better</b>."},{"h":"As...as: tão...quanto","p":["Para dizer que duas coisas têm a mesma característica, usamos <b>as + adjetivo + as</b>. Essa estrutura corresponde a “tão...quanto”.","Para dizer que uma coisa não tem a mesma característica da outra, usamos <b>not as + adjetivo + as</b>: It isn't as light as the blue one (Não é tão leve quanto a azul).","Podemos acrescentar <b>just</b> antes do primeiro as para reforçar a igualdade: just as comfortable (tão confortável quanto)."],"ex":[["This shirt is as nice as that one.","Esta camisa é tão bonita quanto aquela."],["The black jacket isn't as light as the blue one.","A jaqueta preta não é tão leve quanto a azul."],["These shoes are just as comfortable as those.","Estes sapatos são tão confortáveis quanto aqueles."]],"tip":"Na estrutura <b>as...as</b>, o adjetivo fica na forma normal: as cheap as, não “as cheaper as”."},{"h":"Too e enough: demais ou suficiente","p":["Usamos <b>too + adjetivo</b> quando algo ultrapassa o limite desejado: too small (pequeno demais), too expensive (caro demais). Geralmente indica um problema.","Usamos <b>adjetivo + enough</b> para dizer que algo tem uma característica na medida necessária: warm enough (quente o suficiente). Na negativa, indica que não é suficiente.","Com substantivos, a ordem muda: <b>enough + substantivo</b>, como enough money (dinheiro suficiente) ou enough time (tempo suficiente)."],"ex":[["These jeans are too long.","Esta calça jeans é comprida demais."],["My jacket isn't warm enough.","Minha jaqueta não esquenta o suficiente."],["These shoes are comfortable enough.","Estes sapatos são confortáveis o suficiente."],["I don't have enough money for that coat.","Não tenho dinheiro suficiente para aquele casaco."]],"tip":"A posição importa: <b>too small</b>, mas <b>small enough</b>. Enough vem depois do adjetivo e antes do substantivo."}],"vocab":[{"h":"Roupas e acessórios","items":[["jacket","jaqueta"],["coat","casaco"],["sweater","suéter, blusa de frio"],["T-shirt","camiseta"],["shirt","camisa"],["jeans","calça jeans"],["pants","calça"],["dress","vestido"],["sneakers","tênis"],["fitting room","provador"]]},{"h":"Tamanhos, caimento e compras","items":[["size","tamanho"],["small","pequeno, tamanho P"],["medium","médio, tamanho M"],["large","grande, tamanho G"],["tight","apertado, justo"],["loose","folgado, largo"],["long","comprido"],["short","curto"],["on sale","em promoção"],["try on","experimentar uma roupa"]]}],"pron":[{"h":"Than: o som do TH","p":"Em <b>than</b>, o TH é sonoro: coloque a ponta da língua levemente entre os dentes e produza o som com a voz. Em uma fala cuidadosa, a palavra soa aproximadamente “dhén”; na fala rápida, a vogal costuma ficar mais fraca, como em “dhân”.","w":["than","cheaper than","bigger than","better than"]},{"h":"Comfortable","p":"No inglês americano, <b>comfortable</b> costuma ter três sílabas na fala natural, aproximadamente “CÂMF-ter-bol”. A primeira sílaba é a mais forte. Evite pronunciar todas as letras separadamente.","w":["comfortable","more comfortable","comfortable enough"]},{"h":"Size e sizes","p":"<b>Size</b> soa aproximadamente “sáiz”, com Z no final. No plural, <b>sizes</b> soa “SÁI-ziz”, com uma sílaba extra. Lembre que o S entre vogais costuma ter som de Z nessas palavras.","w":["size","sizes","right size","larger size"]}],"mc":[{"q":"Por que Sarah não quer a jaqueta azul?","o":["Porque é cara demais","Porque é pequena demais","Porque não gosta da cor"],"a":1,"e":"No, it's too small. The black one is bigger."},{"q":"Quanto custa a jaqueta preta?","o":["60 dólares","75 dólares","85 dólares"],"a":2,"e":"The black one is $85, and the blue one is $60."},{"q":"Por que Sarah considera a jaqueta preta melhor para o inverno?","o":["Porque ela é mais quente","Porque ela é mais leve","Porque ela é mais barata"],"a":0,"e":"Yes, but it isn't as light as the blue one."},{"q":"Qual é o problema com a calça jeans que Sarah experimenta?","o":["É apertada demais","É comprida demais","É pequena demais"],"a":1,"e":"They're nice, but they're too long for me."}],"gaps":[{"s":"These jeans are ___ than those.","a":["shorter"],"h":"Esta calça jeans é mais curta que aquela."},{"s":"The black jacket is ___ expensive than the blue one.","a":["more"],"h":"A jaqueta preta é mais cara que a azul."},{"s":"This sweater isn't as warm ___ that coat.","a":["as"],"h":"Este suéter não é tão quente quanto aquele casaco."},{"s":"This shirt is ___ tight for me.","a":["too"],"h":"Esta camisa é apertada demais para mim."},{"s":"My old jacket isn't warm ___.","a":["enough"],"h":"Minha jaqueta antiga não esquenta o suficiente."},{"s":"This dress is ___ than that one.","a":["better"],"h":"Este vestido é melhor que aquele."}],"order":[{"t":["This","jacket","is","cheaper","than","that","one."],"h":"Esta jaqueta é mais barata que aquela."},{"t":["These","pants","are","too","tight."],"h":"Esta calça é apertada demais."},{"t":["My","coat","isn't","warm","enough."],"h":"Meu casaco não esquenta o suficiente."}],"dict":[{"t":"The black one is bigger."},{"t":"It looks more comfortable, too."},{"t":"The black jacket is more expensive than the blue one."},{"t":"Your old jacket isn't warm enough, right?","alt":["Your old jacket is not warm enough, right?"]},{"t":"Let's find a shorter pair in your size."}],"shadow":["No, it's too small. The black one is bigger.","It is, but it's more expensive than the blue one.","Yes, but it isn't as light as the blue one.","Let's find a shorter pair in your size."],"write":{"task":"Imagine que você está comprando roupas. Compare duas peças em 4 ou 5 frases. Diga qual é mais barata, mais confortável e melhor para você. Inclua uma comparação com as...as e uma frase com too ou enough.","ph":"I'm looking for a … The blue one is … than the black one. It's as … as … But it's too … I think …"},"cards":[["Você tem esta camiseta no tamanho M?","Do you have this T-shirt in a medium?"],["Estou procurando um tamanho menor.","I'm looking for a smaller size."],["Este vestido é mais barato que aquele.","This dress is cheaper than that one."],["Onde fica o provador?","Where is the fitting room?"],["Esta calça é apertada demais.","These pants are too tight."],["Este vestido não é comprido o suficiente.","This dress isn't long enough."],["O suéter verde é tão quente quanto o cinza.","The green sweater is as warm as the gray one."],["Posso experimentar estes?","Can I try these on?"],["Esta jaqueta é mais confortável.","This jacket is more comfortable."],["Você tem um tamanho maior?","Do you have a larger size?"]]},{"title":"The best","goal":"Descrever e comparar cidades, bairros e lugares, usando superlativos para falar do maior, do mais bonito, do melhor e do pior. Aprender a usar -est, most, the best e the worst.","speakers":{"Emma":"f","Daniel":"m"},"setting":"Na segunda-feira, Emma conversa com Daniel durante o intervalo do trabalho. Ele acabou de voltar de uma viagem a Nova York e Boston e conta quais lugares mais gostou de visitar.","lines":[["Emma","How was your trip to New York and Boston?","Como foi sua viagem a Nova York e Boston?"],["Daniel","Great! New York was the most exciting city on our trip.","Ótima! Nova York foi a cidade mais empolgante da nossa viagem."],["Emma","What was the best part of New York?","Qual foi a melhor parte de Nova York?"],["Daniel","Central Park. It was the most beautiful place we saw.","O Central Park. Foi o lugar mais bonito que vimos."],["Emma","Was it bigger than the parks in Boston?","Era maior que os parques de Boston?"],["Daniel","Yes! It was also one of the quietest places we visited.","Sim! Também foi um dos lugares mais tranquilos que visitamos."],["Emma","And what about Times Square?","E a Times Square?"],["Daniel","That was the busiest place. There were so many people!","Foi o lugar mais movimentado. Tinha muita gente!"],["Emma","Did you find a good place to eat?","Você encontrou um lugar bom para comer?"],["Daniel","Yes! A small pizza place had the best food.","Sim! Uma pizzaria pequena tinha a melhor comida."],["Emma","Was it expensive?","Era caro?"],["Daniel","No, it was the cheapest meal of the trip.","Não, foi a refeição mais barata da viagem."],["Emma","What was the worst part?","Qual foi a pior parte?"],["Daniel","The subway. It was crowded, and we waited a long time.","O metrô. Estava lotado, e esperamos muito tempo."]],"grammar":[{"h":"Superlativos com -est","p":["Na unidade anterior, aprendemos a comparar duas coisas usando <b>-er</b>: bigger (maior), cheaper (mais barato). Agora, usamos o <b>superlativo</b> para destacar uma coisa entre todas as outras de um grupo.","Com adjetivos curtos, normalmente usamos <b>the + adjetivo + -est</b>: small → the smallest (o menor), tall → the tallest (o mais alto).","As regras de escrita são parecidas com as dos comparativos: big → biggest (dobra a consoante), nice → nicest (acrescenta -st) e busy → busiest (troca y por -iest)."],"ex":[["This is the tallest building in town.","Este é o prédio mais alto da cidade."],["It's the cheapest restaurant on this street.","É o restaurante mais barato desta rua."],["Times Square was the busiest place.","A Times Square foi o lugar mais movimentado."]],"tip":"Na maioria das frases, o superlativo vem acompanhado de <b>the</b>: the biggest, the cheapest, the oldest."},{"h":"Superlativos com the most","p":["Com adjetivos mais longos, geralmente usamos <b>the most + adjetivo</b>. Não acrescentamos -est.","Por exemplo: beautiful → the most beautiful (o mais bonito), expensive → the most expensive (o mais caro), exciting → the most exciting (o mais empolgante).","O superlativo pode descrever lugares, pessoas ou experiências. O adjetivo continua na forma normal depois de most."],"ex":[["It's the most beautiful park in the city.","É o parque mais bonito da cidade."],["That was the most exciting trip of my life.","Aquela foi a viagem mais empolgante da minha vida."],["This is the most expensive hotel downtown.","Este é o hotel mais caro do centro."]],"tip":"Não diga “the most beautifulest”. Use apenas <b>the most beautiful</b>."},{"h":"The best e the worst","p":["Alguns adjetivos têm formas irregulares. O superlativo de <b>good</b> (bom) é <b>the best</b> (o melhor). O de <b>bad</b> (ruim) é <b>the worst</b> (o pior).","Compare as três formas: good → better → the best; bad → worse → the worst.","Usamos essas expressões para falar de experiências, hotéis, comidas, lugares e muito mais."],"ex":[["This is the best pizza in town.","Esta é a melhor pizza da cidade."],["That was the worst day of our trip.","Aquele foi o pior dia da nossa viagem."],["What's the best place to visit here?","Qual é o melhor lugar para visitar aqui?"]],"tip":"Não use “the goodest” nem “the baddest” como superlativos comuns. As formas corretas são <b>the best</b> e <b>the worst</b>."},{"h":"Comparativo ou superlativo?","p":["Use o <b>comparativo</b> para comparar duas coisas: Boston is smaller than New York (Boston é menor que Nova York).","Use o <b>superlativo</b> para destacar uma coisa dentro de um grupo: It's the biggest city on our trip (É a maior cidade da nossa viagem).","Depois do superlativo, usamos frequentemente <b>in</b> para indicar um lugar ou grupo e <b>of</b> para indicar um conjunto ou período. Também podemos usar <b>one of the + superlativo + substantivo plural</b> para dizer “um dos mais...”."],"ex":[["This park is bigger than that one.","Este parque é maior que aquele."],["It's the biggest park in the city.","É o maior parque da cidade."],["It was the best day of the trip.","Foi o melhor dia da viagem."],["It's one of the oldest buildings here.","É um dos prédios mais antigos daqui."]],"tip":"Lembre-se: <b>bigger than</b> compara duas coisas; <b>the biggest</b> destaca uma entre várias."}],"vocab":[{"h":"Lugares e pontos da cidade","items":[["neighborhood","bairro"],["square","praça"],["bridge","ponte"],["museum","museu"],["building","prédio, edifício"],["subway","metrô"],["downtown","centro da cidade"],["view","vista, paisagem"],["street","rua"],["tourist attraction","atração turística"]]},{"h":"Adjetivos para descrever cidades","items":[["busy","movimentado"],["crowded","lotado, cheio de gente"],["quiet","tranquilo, silencioso"],["noisy","barulhento"],["exciting","empolgante"],["peaceful","tranquilo, sossegado"],["popular","popular"],["beautiful","bonito"],["modern","moderno"],["safe","seguro"]]}],"pron":[{"h":"O final -est","p":"Nos superlativos curtos, o final <b>-est</b> geralmente acrescenta uma sílaba, com som próximo de “ist”. Tallest soa aproximadamente “TÓ-list”, e biggest soa “BÍ-guist”.","w":["tallest","biggest","smallest","cheapest"]},{"h":"Busy e busiest","p":"<b>Busy</b> soa aproximadamente “BÍ-zi”. Já <b>busiest</b> tem três sílabas e soa “BÍ-zi-ist”. A primeira sílaba continua sendo a mais forte.","w":["busy","busier","busiest"]},{"h":"Best e worst","p":"<b>Best</b> soa aproximadamente “bést”, com E aberto. <b>Worst</b> soa “uârst”, com o R americano bem marcado. Não confunda worst (o pior) com first (primeiro).","w":["best","worst","first","the best","the worst"]}],"mc":[{"q":"Qual cidade Daniel considerou a mais empolgante da viagem?","o":["Boston","Nova York","Chicago"],"a":1,"e":"Great! New York was the most exciting city on our trip."},{"q":"Qual foi o lugar mais bonito que Daniel visitou?","o":["Central Park","Times Square","O metrô"],"a":0,"e":"Central Park. It was the most beautiful place we saw."},{"q":"Como Daniel descreveu a Times Square?","o":["O lugar mais tranquilo","O lugar mais barato","O lugar mais movimentado"],"a":2,"e":"That was the busiest place. There were so many people!"},{"q":"Qual foi a pior parte da viagem para Daniel?","o":["A comida","O metrô","O parque"],"a":1,"e":"The subway. It was crowded, and we waited a long time."}],"gaps":[{"s":"This is the ___ (tall) building in town.","a":["tallest"],"h":"Este é o prédio mais alto da cidade."},{"s":"It's the ___ beautiful park in the city.","a":["most"],"h":"É o parque mais bonito da cidade."},{"s":"That was the ___ (good) day of our trip.","a":["best"],"h":"Aquele foi o melhor dia da nossa viagem."},{"s":"The subway was the ___ (bad) part of the trip.","a":["worst"],"h":"O metrô foi a pior parte da viagem."},{"s":"This is the ___ (big) square in town.","a":["biggest"],"h":"Esta é a maior praça da cidade."},{"s":"It's one of the ___ popular museums here.","a":["most"],"h":"É um dos museus mais populares daqui."}],"order":[{"t":["It's","the","oldest","building","here."],"h":"É o prédio mais antigo daqui."},{"t":["What's","the","best","restaurant","in","town?"],"h":"Qual é o melhor restaurante da cidade?"},{"t":["This","is","the","most","beautiful","view."],"h":"Esta é a vista mais bonita."}],"dict":[{"t":"New York was the most exciting city on our trip."},{"t":"It was the most beautiful place we saw."},{"t":"That was the busiest place.","note":"Atenção à escrita de busiest: busy perde o Y e recebe -iest."},{"t":"It was the cheapest meal of the trip."},{"t":"What was the worst part?"}],"shadow":["Great! New York was the most exciting city on our trip.","Yes! It was also one of the quietest places we visited.","No, it was the cheapest meal of the trip.","The subway. It was crowded, and we waited a long time."],"write":{"task":"Descreva uma cidade que você conhece em 4 ou 5 frases. Diga qual é o lugar mais bonito, o bairro mais movimentado, a melhor atração e algo de que você não gosta. Use pelo menos três superlativos diferentes.","ph":"I think … is a great city. The most beautiful place is … The busiest area is … The best thing about this city is …"},"cards":[["Este é o maior parque da região.","This is the biggest park in the area."],["Qual é o bairro mais tranquilo?","What's the quietest neighborhood?"],["É a rua mais movimentada da cidade.","It's the busiest street in the city."],["Este é o prédio mais antigo daqui.","This is the oldest building here."],["Foi o hotel mais confortável da viagem.","It was the most comfortable hotel on our trip."],["Qual é o melhor lugar para tirar fotos?","What's the best place to take pictures?"],["Essa foi a pior parte do passeio.","That was the worst part of the tour."],["É a atração mais popular da cidade.","It's the most popular attraction in the city."],["Este é um dos museus mais interessantes daqui.","This is one of the most interesting museums here."],["Aquela foi a vista mais incrível da viagem.","That was the most amazing view of the trip."]]},{"title":"Plans","goal":"Falar sobre planos e intenções para o futuro, contar o que pretende fazer e conversar sobre compromissos já marcados, usando be going to, present continuous e expressões de tempo futuro.","speakers":{"Sarah":"f","Lucas":"m"},"setting":"Na sexta-feira, Sarah e Lucas conversam durante o intervalo do trabalho sobre seus planos para o fim de semana.","lines":[["Sarah","Hey, Lucas! What are you doing this weekend?","Oi, Lucas! O que você vai fazer neste fim de semana?"],["Lucas","I'm going to visit my cousin in Boston.","Vou visitar minha prima em Boston."],["Sarah","Nice! When are you leaving?","Que legal! Quando você vai partir?"],["Lucas","I'm taking the train on Saturday morning.","Vou pegar o trem no sábado de manhã."],["Sarah","Are you staying with your cousin?","Você vai ficar na casa da sua prima?"],["Lucas","Yes, and we're having dinner with some friends on Saturday.","Sim, e vamos jantar com alguns amigos no sábado."],["Sarah","Sounds fun! What are you going to do on Sunday?","Parece divertido! O que você pretende fazer no domingo?"],["Lucas","We're going to explore the city and visit a museum.","Vamos explorar a cidade e visitar um museu."],["Sarah","Are you coming back on Sunday night?","Você vai voltar no domingo à noite?"],["Lucas","No, I'm coming back on Monday morning. What about you?","Não, vou voltar na segunda de manhã. E você?"],["Sarah","I'm going to relax, but I'm meeting Emma for coffee on Sunday.","Vou descansar, mas marquei de tomar café com a Emma no domingo."],["Lucas","Where are you meeting?","Onde vocês vão se encontrar?"],["Sarah","At the cafe near the park, at 10 a.m.","No café perto do parque, às dez da manhã."],["Lucas","Sounds great! Enjoy your weekend!","Parece ótimo! Aproveite seu fim de semana!"]],"grammar":[{"h":"Be going to: planos e intenções","p":["Usamos <b>be going to</b> para falar de algo que já temos a intenção de fazer no futuro. É muito comum ao conversar sobre viagens, estudos e planos para o fim de semana.","A estrutura é <b>am/is/are + going to + verbo base</b>. A forma de to be muda conforme a pessoa: I'm going to, she's going to, we're going to.","Na fala e na escrita informal, é natural contrair o verbo to be: <b>I'm</b>, <b>he's</b>, <b>they're</b>."],"ex":[["I'm going to visit my cousin tomorrow.","Vou visitar minha prima amanhã."],["She's going to study tonight.","Ela vai estudar hoje à noite."],["We're going to explore the city.","Vamos explorar a cidade."]],"tip":"Depois de <b>going to</b>, use o verbo na forma base: going to visit, going to study. Não diga “going to visiting”."},{"h":"Perguntas e negativas com going to","p":["Para fazer perguntas, coloque <b>am, is ou are</b> antes da pessoa: <b>Are you going to travel?</b> (Você vai viajar?).","Para formar a negativa, use <b>am not, isn't ou aren't + going to</b>. Por exemplo: I'm not going to work tomorrow (Não vou trabalhar amanhã).","Para perguntar sobre planos específicos, use expressões como <b>What are you going to do?</b> e <b>Where are you going to stay?</b>."],"ex":[["Are you going to travel next month?","Você vai viajar no mês que vem?"],["What are they going to do tomorrow?","O que eles vão fazer amanhã?"],["He isn't going to work on Sunday.","Ele não vai trabalhar no domingo."],["No, I'm not going to buy tickets.","Não, não vou comprar ingressos."]],"tip":"Não use do ou does com going to. O próprio <b>am/is/are</b> forma perguntas e negativas."},{"h":"Present continuous para compromissos marcados","p":["Na unidade A1, aprendemos que o present continuous descreve ações acontecendo agora. Ele também pode falar do futuro quando existe um <b>compromisso ou plano já combinado</b>.","A estrutura continua igual: <b>am/is/are + verbo com -ing</b>. Normalmente, acrescentamos uma expressão de tempo futuro para deixar claro quando a ação acontecerá.","Compare: <b>I'm going to visit Boston</b> apresenta uma intenção. <b>I'm taking the train at 8 a.m.</b> apresenta um plano específico, com horário definido."],"ex":[["I'm meeting Emma on Sunday.","Vou encontrar a Emma no domingo."],["We're having dinner with friends tonight.","Vamos jantar com amigos hoje à noite."],["She's leaving on Friday morning.","Ela vai partir na sexta de manhã."],["Are you coming back on Monday?","Você vai voltar na segunda-feira?"]],"tip":"O contexto indica o tempo: <b>I'm meeting her now</b> é uma ação atual; <b>I'm meeting her tomorrow</b> é um compromisso futuro."},{"h":"Expressões de futuro e escolha da estrutura","p":["Para indicar quando algo acontecerá, usamos expressões como <b>tomorrow</b> (amanhã), <b>this weekend</b> (neste fim de semana), <b>next week</b> (na próxima semana) e <b>next month</b> (no próximo mês).","Com dias específicos, use <b>on</b>: on Saturday, on Monday morning. Com horários, use <b>at</b>: at 10 a.m., at 7 p.m.","Tanto going to quanto present continuous podem descrever planos futuros. Em geral, <b>going to</b> destaca a intenção e <b>present continuous</b> destaca algo já organizado ou combinado."],"ex":[["I'm going to relax this weekend.","Vou descansar neste fim de semana."],["We're visiting our friends next week.","Vamos visitar nossos amigos na próxima semana."],["I'm meeting Daniel at 6 p.m.","Vou encontrar o Daniel às seis da tarde."]],"tip":"Não use in antes de <b>next week</b> ou <b>tomorrow</b>. Diga simplesmente next week e tomorrow."}],"vocab":[{"h":"Planos e atividades","items":[["make plans","fazer planos"],["visit relatives","visitar parentes"],["explore the city","explorar a cidade"],["book tickets","reservar passagens ou ingressos"],["take the train","pegar o trem"],["meet friends","encontrar amigos"],["have dinner","jantar"],["relax","descansar, relaxar"],["leave","partir, sair"],["come back","voltar"],["tomorrow","amanhã"],["this weekend","neste fim de semana"]]},{"h":"Expressões de tempo futuro","items":[["tomorrow","amanhã"],["tomorrow morning","amanhã de manhã"],["tomorrow night","amanhã à noite"],["this weekend","neste fim de semana"],["next weekend","no próximo fim de semana"],["next week","na próxima semana"],["next month","no próximo mês"],["on Saturday morning","no sábado de manhã"],["on Monday night","na segunda-feira à noite"],["at 10 a.m.","às dez da manhã"]]}],"pron":[{"h":"Going to e gonna","p":"Na fala informal, <b>going to</b> frequentemente soa como “GÂ-na”, escrito <b>gonna</b> em contextos informais. Por exemplo, I'm going to visit pode soar “aim GÂ-na ví-zit”. Em exercícios de escrita, prefira going to.","w":["going to","I'm going to visit","We're going to explore"]},{"h":"What are you e are you","p":"Na fala natural, as palavras se conectam. <b>What are you</b> pode soar aproximadamente “uó-der-yu”, enquanto <b>are you</b> frequentemente soa “ar-yu”. Não é necessário pronunciar cada palavra separadamente.","w":["What are you doing?","Are you leaving?","Where are you staying?"]},{"h":"Leaving e living","p":"<b>Leaving</b> (partindo) tem um I longo, aproximadamente “LÍI-ving”. Já <b>living</b> (morando) tem um I curto, “LÍ-ving”. Alongar um pouco a vogal ajuda a diferenciar as palavras.","w":["leaving","living","I'm leaving","I'm living"]}],"mc":[{"q":"Como Lucas pretende viajar para Boston?","o":["De trem","De avião","De ônibus"],"a":0,"e":"I'm taking the train on Saturday morning."},{"q":"Quando Lucas vai voltar da viagem?","o":["No sábado à noite","No domingo à noite","Na segunda de manhã"],"a":2,"e":"No, I'm coming back on Monday morning. What about you?"},{"q":"Qual compromisso Sarah tem no domingo?","o":["Visitar um museu","Encontrar Emma para tomar café","Pegar um trem"],"a":1,"e":"I'm going to relax, but I'm meeting Emma for coffee on Sunday."},{"q":"Onde Sarah vai encontrar Emma?","o":["No café perto do parque","Na estação de trem","No shopping"],"a":0,"e":"At the cafe near the park, at 10 a.m."}],"gaps":[{"s":"I'm ___ to visit my cousin tomorrow.","a":["going"],"h":"Vou visitar minha prima amanhã."},{"s":"___ you taking the train on Saturday?","a":["Are"],"h":"Você vai pegar o trem no sábado?"},{"s":"We're ___ (have) dinner with friends tonight.","a":["having"],"h":"Vamos jantar com amigos hoje à noite."},{"s":"I'm ___ going to work tomorrow.","a":["not"],"h":"Não vou trabalhar amanhã."},{"s":"What are you going ___ do on Sunday?","a":["to"],"h":"O que você vai fazer no domingo?"},{"s":"She's ___ (leave) on Friday morning.","a":["leaving"],"h":"Ela vai partir na sexta de manhã."}],"order":[{"t":["I'm","taking","the","train","on","Saturday."],"h":"Vou pegar o trem no sábado."},{"t":["What","are","you","going","to","do?"],"h":"O que você vai fazer?"},{"t":["We're","meeting","at","the","cafe","tomorrow."],"h":"Vamos nos encontrar no café amanhã."}],"dict":[{"t":"I'm going to visit my cousin in Boston."},{"t":"I'm taking the train on Saturday morning."},{"t":"We're having dinner with some friends on Saturday."},{"t":"I'm coming back on Monday morning."},{"t":"I'm meeting Emma for coffee on Sunday."}],"shadow":["Hey, Lucas! What are you doing this weekend?","I'm taking the train on Saturday morning.","We're going to explore the city and visit a museum.","I'm going to relax, but I'm meeting Emma for coffee on Sunday."],"write":{"task":"Conte seus planos para o próximo fim de semana em 4 ou 5 frases. Diga o que pretende fazer, se tem algum compromisso marcado, com quem vai se encontrar e quando. Use going to e present continuous pelo menos uma vez cada.","ph":"Next weekend, I'm going to … On Saturday, I'm … I'm meeting … at … On Sunday, I'm going to …"},"cards":[["Vou visitar minha tia no próximo fim de semana.","I'm going to visit my aunt next weekend."],["Não vou trabalhar amanhã.","I'm not going to work tomorrow."],["Você vai viajar no mês que vem?","Are you going to travel next month?"],["Vamos passar o domingo em casa.","We're going to spend Sunday at home."],["Tenho uma consulta no dentista na terça-feira.","I'm seeing the dentist on Tuesday."],["Vou almoçar com a Emma amanhã.","I'm having lunch with Emma tomorrow."],["Que horas você vai sair?","What time are you leaving?"],["Vou voltar na segunda à noite.","I'm coming back on Monday night."],["Eles vão ficar em um hotel.","They're going to stay at a hotel."],["Vamos ao cinema na sexta-feira.","We're going to the movies on Friday."]]},{"title":"Predictions and offers","goal":"Fazer previsões sobre o futuro, falar de possibilidades, tomar decisões na hora e oferecer ajuda usando will, won't, I'll e might.","speakers":{"Sarah":"f","Daniel":"m"},"setting":"Na sexta-feira à tarde, Sarah e Daniel conversam no escritório sobre um piquenique que estão organizando para o dia seguinte. O tempo parece mudar, e eles precisam decidir alguns detalhes.","lines":[["Sarah","The sky looks dark. Do you think it'll rain tomorrow?","O céu está escuro. Você acha que vai chover amanhã?"],["Daniel","It might. I think the morning will be cloudy.","Talvez. Acho que a manhã vai ser nublada."],["Sarah","Oh no! Our picnic is at the park.","Ah, não! Nosso piquenique é no parque."],["Daniel","Don't worry. We can have it at my place.","Não se preocupe. Podemos fazer lá em casa."],["Sarah","Good idea! I'll text Emma and Lucas now.","Boa ideia! Vou mandar mensagem para a Emma e o Lucas agora."],["Daniel","Great. I'll buy some drinks after work.","Ótimo. Vou comprar algumas bebidas depois do trabalho."],["Sarah","That's a lot to carry. I'll help you.","É muita coisa para carregar. Eu te ajudo."],["Daniel","Thanks! Can you also bring some cups?","Obrigado! Você também pode levar alguns copos?"],["Sarah","Sure. I'll bring cups and napkins.","Claro. Vou levar copos e guardanapos."],["Daniel","I think everyone will enjoy the picnic.","Acho que todo mundo vai gostar do piquenique."],["Sarah","Maybe! But we might need more chairs.","Talvez! Mas pode ser que precisemos de mais cadeiras."],["Daniel","You're right. I'll ask my neighbor.","Você tem razão. Vou perguntar ao meu vizinho."],["Sarah","Do you think it'll be cold tomorrow evening?","Você acha que vai fazer frio amanhã à noite?"],["Daniel","I don't think so. But I won't forget the blankets!","Acho que não. Mas não vou esquecer os cobertores!"]],"grammar":[{"h":"Will e won't: previsões sobre o futuro","p":["Usamos <b>will</b> para fazer previsões sobre o futuro, ou seja, dizer o que achamos que vai acontecer. É comum usar expressões como <b>I think</b> (acho que) e <b>I don't think</b> (acho que não).","A estrutura é <b>pessoa + will + verbo base</b>. Will não muda com a pessoa: I will, she will, they will. A forma contraída é <b>'ll</b>: I'll, she'll, they'll.","A negativa é <b>will not</b>, geralmente contraída para <b>won't</b>. Para fazer perguntas, coloque will antes da pessoa: Will it rain?"],"ex":[["I think it'll rain tomorrow.","Acho que vai chover amanhã."],["Everyone will enjoy the party.","Todo mundo vai gostar da festa."],["It won't be cold tonight.","Não vai fazer frio hoje à noite."],["Will the weather improve?","O tempo vai melhorar?"]],"tip":"Depois de <b>will</b> ou <b>won't</b>, use o verbo base: will rain, won't rain. Não diga “will rains” nem “will to rain”."},{"h":"I'll: decisões tomadas na hora","p":["Também usamos <b>will</b> quando decidimos fazer alguma coisa no momento em que estamos falando, sem ter planejado isso antes.","Nessas situações, a contração <b>I'll</b> (I will) é muito comum na fala. Por exemplo, alguém diz que precisa de bebidas e você decide naquele instante: I'll buy some.","Compare com <b>going to</b>, estudado na unidade anterior: I'm going to buy a jacket indica uma intenção anterior. I'll take this jacket pode indicar uma decisão tomada naquele momento."],"ex":[["I'll text her now.","Vou mandar mensagem para ela agora."],["The phone's ringing. I'll answer it.","O telefone está tocando. Eu atendo."],["I'll take the blue one.","Vou ficar com a azul."]],"tip":"Uma diferença útil: <b>going to</b> costuma destacar uma intenção já existente; <b>I'll</b> é muito usado para uma decisão tomada na hora."},{"h":"I'll para oferecer ajuda","p":["Usamos <b>I'll + verbo base</b> para oferecer ajuda ou fazer algo por outra pessoa. É uma maneira natural e educada de se oferecer para uma tarefa.","Por exemplo, se alguém está carregando muitas sacolas, você pode dizer <b>I'll help you</b> (Eu te ajudo).","Também usamos will e won't para fazer promessas: I'll be there (Vou estar lá) ou I won't forget (Não vou esquecer)."],"ex":[["I'll help you with the bags.","Eu te ajudo com as sacolas."],["I'll carry the chairs.","Eu carrego as cadeiras."],["I'll get you some water.","Vou pegar um pouco de água para você."],["I won't forget your book.","Não vou esquecer seu livro."]],"tip":"<b>I'll</b> pode significar “eu vou” ou “eu faço”, dependendo do contexto. Nem sempre precisamos traduzir literalmente."},{"h":"Might: talvez, pode ser que","p":["Usamos <b>might</b> quando algo é possível, mas não temos certeza de que vai acontecer. Em português, pode significar “talvez”, “pode ser que” ou “é possível que”.","A estrutura é <b>pessoa + might + verbo base</b>. Assim como will, might não muda com he, she ou it e não exige to antes do verbo.","Na negativa, usamos <b>might not</b> para indicar que algo talvez não aconteça. Compare: It won't rain expressa uma previsão negativa; It might not rain indica apenas uma possibilidade."],"ex":[["It might rain this afternoon.","Talvez chova hoje à tarde."],["We might need more chairs.","Pode ser que precisemos de mais cadeiras."],["She might come to the party.","Talvez ela venha à festa."],["He might not be home tonight.","Talvez ele não esteja em casa hoje à noite."]],"tip":"Não use to depois de <b>might</b>. Diga <b>might rain</b>, nunca “might to rain”."}],"vocab":[{"h":"Previsões e possibilidades","items":[["I think","acho que"],["I don't think so","acho que não"],["maybe","talvez"],["probably","provavelmente"],["might","talvez, pode ser que"],["definitely","com certeza"],["I'm not sure","não tenho certeza"],["weather forecast","previsão do tempo"],["improve","melhorar"],["happen","acontecer"]]},{"h":"Organizando um encontro","items":[["picnic","piquenique"],["drinks","bebidas"],["cups","copos"],["napkins","guardanapos"],["blanket","cobertor, manta"],["chairs","cadeiras"],["carry","carregar"],["bring","trazer, levar"],["neighbor","vizinho"],["cancel","cancelar"]]}],"pron":[{"h":"Will e I'll","p":"<b>Will</b> soa aproximadamente “uíl”. A contração <b>I'll</b> soa como “áil”, juntando o som de I com o L final. Em I'll help you, as palavras se conectam naturalmente: “áil hélp yu”.","w":["will","I'll","I'll help","I'll bring"]},{"h":"Won't e want","p":"<b>Won't</b> tem um som de OU, aproximadamente “uôunt”. Já <b>want</b> tem uma vogal mais aberta, próxima de “uánt” no inglês americano. É importante diferenciá-las porque won't significa “não vai”, enquanto want significa “querer”.","w":["won't","want","I won't","I want"]},{"h":"Might: GH silencioso","p":"Em <b>might</b>, as letras GH não são pronunciadas. A palavra soa aproximadamente “máit”, rimando com night e right. O T final é curto, sem acrescentar uma vogal depois dele.","w":["might","night","right","might rain"]}],"mc":[{"q":"O que preocupa Sarah sobre o piquenique?","o":["O preço das bebidas","A possibilidade de chuva","A falta de comida"],"a":1,"e":"The sky looks dark. Do you think it'll rain tomorrow?"},{"q":"Onde Daniel sugere fazer o piquenique?","o":["No escritório","No parque","Na casa dele"],"a":2,"e":"Don't worry. We can have it at my place."},{"q":"O que Sarah oferece quando Daniel fala das bebidas?","o":["Ajudar a carregar","Comprar um bolo","Ligar para o vizinho"],"a":0,"e":"That's a lot to carry. I'll help you."},{"q":"O que Sarah diz que vai levar para o piquenique?","o":["Cobertores e cadeiras","Copos e guardanapos","Sanduíches e frutas"],"a":1,"e":"Sure. I'll bring cups and napkins."}],"gaps":[{"s":"I think it ___ be sunny tomorrow.","a":["will","'ll"],"h":"Acho que vai fazer sol amanhã."},{"s":"I ___ forget the blankets. I promise!","a":["won't","will not"],"h":"Não vou esquecer os cobertores. Eu prometo!"},{"s":"We ___ need more chairs. (Use might para expressar possibilidade.)","a":["might"],"h":"Talvez precisemos de mais cadeiras."},{"s":"I'll ___ you carry those bags.","a":["help"],"h":"Eu te ajudo a carregar aquelas sacolas."},{"s":"She ___ be late tonight, but she isn't sure. (Use might.)","a":["might"],"h":"Talvez ela se atrase hoje à noite, mas não tem certeza."},{"s":"I don't think it ___ rain tomorrow.","a":["will","'ll"],"h":"Acho que não vai chover amanhã."}],"order":[{"t":["I","think","it'll","rain","tomorrow."],"h":"Acho que vai chover amanhã."},{"t":["I'll","help","you","carry","the","bags."],"h":"Eu te ajudo a carregar as sacolas."},{"t":["We","might","need","more","chairs."],"h":"Talvez precisemos de mais cadeiras."}],"dict":[{"t":"Do you think it'll rain tomorrow?","alt":["Do you think it will rain tomorrow?"]},{"t":"I'll text Emma and Lucas now.","alt":["I will text Emma and Lucas now."]},{"t":"I think everyone will enjoy the picnic."},{"t":"We might need more chairs.","note":"Atenção: might tem GH silencioso."},{"t":"I won't forget the blankets!","alt":["I will not forget the blankets!"]}],"shadow":["It might. I think the morning will be cloudy.","Good idea! I'll text Emma and Lucas now.","That's a lot to carry. I'll help you.","I don't think so. But I won't forget the blankets!"],"write":{"task":"Imagine que você vai organizar um encontro com amigos. Escreva 4 ou 5 frases. Faça uma previsão sobre o encontro, diga algo que talvez aconteça, ofereça ajuda e faça uma promessa. Use will, won't, I'll e might.","ph":"I think the party will … It might … I'll help with … I won't forget …"},"cards":[["Acho que vai chover hoje à noite.","I think it'll rain tonight."],["Não vai ser difícil.","It won't be difficult."],["Talvez a Emma chegue mais tarde.","Emma might arrive later."],["Eu carrego as sacolas.","I'll carry the bags."],["Eu te ajudo com as cadeiras.","I'll help you with the chairs."],["Você acha que vai fazer frio?","Do you think it'll be cold?"],["Talvez precisemos de mais tempo.","We might need more time."],["Não vou esquecer os ingressos.","I won't forget the tickets."],["Eu atendo o telefone.","I'll answer the phone."],["Acho que todo mundo vai gostar.","I think everyone will like it."]]},{"title":"Experiences","goal":"Falar sobre experiências de vida, perguntar se alguém já fez alguma coisa e contar o que nunca fez, usando present perfect com ever e never. Entender a diferença entre been e gone e saber quando usar o past simple.","speakers":{"Sarah":"f","Lucas":"m"},"setting":"Sarah e Lucas conversam em uma cafeteria sobre viagens, lugares que conheceram e experiências que tiveram. Durante a conversa, Lucas comenta sobre uma viagem recente de sua irmã.","lines":[["Sarah","Have you ever been to California, Lucas?","Você já foi à Califórnia, Lucas?"],["Lucas","Yes, I have. I went to San Diego with my parents last summer.","Já. Fui a San Diego com meus pais no verão passado."],["Sarah","Nice! Did you go to the beach?","Que legal! Você foi à praia?"],["Lucas","Yes, I did. I swam in the ocean for the first time, and it was great!","Fui, sim. Nadei no mar pela primeira vez, e foi ótimo!"],["Sarah","I've never swum in the ocean. Was the water cold?","Nunca nadei no mar. A água estava fria?"],["Lucas","A little! Have you ever tried surfing?","Um pouco! Você já experimentou surfar?"],["Sarah","No, I haven't, but I've tried kayaking.","Não, mas já experimentei andar de caiaque."],["Lucas","Really? When did you try it?","Sério? Quando você experimentou?"],["Sarah","I tried it in Florida two years ago.","Experimentei na Flórida há dois anos."],["Lucas","Was it difficult?","Foi difícil?"],["Sarah","At first, yes, but I loved it. The weather was perfect.","No começo, sim, mas adorei. O tempo estava perfeito."],["Lucas","By the way, my sister Emma has gone to Florida for a few days.","A propósito, minha irmã Emma foi para a Flórida passar alguns dias."],["Sarah","Oh, so she's there now?","Ah, então ela está lá agora?"],["Lucas","Exactly. She's never been there before.","Exatamente. Ela nunca tinha ido lá antes."]],"grammar":[{"h":"Present perfect: experiências de vida","p":["Usamos o <b>present perfect</b> para falar de experiências que tivemos ou não tivemos até agora, sem dizer exatamente quando aconteceram.","A estrutura é <b>have/has + past participle</b> (particípio passado). Use <b>have</b> com I, you, we e they. Use <b>has</b> com he, she e it.","Nos verbos regulares, o particípio geralmente termina em <b>-ed</b>: visit → visited, try → tried. Nos irregulares, precisamos aprender a forma: eat → eaten, see → seen, swim → swum.","Na fala, usamos frequentemente as contrações <b>I've</b>, <b>you've</b>, <b>we've</b>, <b>he's</b> e <b>she's</b>."],"ex":[["I've visited California.","Já visitei a Califórnia."],["She's tried surfing.","Ela já experimentou surfar."],["We've eaten sushi.","Já comemos sushi."],["He's seen that movie.","Ele já viu aquele filme."]],"tip":"O particípio nem sempre é igual ao passado simples: swim → <b>swam</b> (passado simples) → <b>swum</b> (particípio)."},{"h":"Ever e never: já fez ou nunca fez?","p":["Usamos <b>ever</b> em perguntas sobre experiências. Ele corresponde a “já” em frases como <b>Have you ever tried surfing?</b> (Você já experimentou surfar?).","Para fazer perguntas, coloque <b>have/has</b> antes da pessoa. Nas respostas curtas, use <b>Yes, I have</b> ou <b>No, I haven't</b>.","Usamos <b>never</b> para dizer que nunca tivemos uma experiência. Ele aparece depois de have/has e antes do particípio: <b>I've never traveled alone</b>.","Como never já tem sentido negativo, não precisamos acrescentar not."],"ex":[["Have you ever tried surfing?","Você já experimentou surfar?"],["No, I haven't.","Não, nunca experimentei."],["I've never traveled alone.","Nunca viajei sozinho."],["She has never eaten sushi.","Ela nunca comeu sushi."]],"tip":"Diga <b>I've never been there</b>, não “I haven't never been there”. Evite usar duas negativas na mesma estrutura."},{"h":"Been e gone: qual é a diferença?","p":["As duas palavras são particípios e aparecem frequentemente com lugares, mas têm sentidos diferentes.","Usamos <b>have/has been to</b> quando alguém foi a um lugar e já voltou. É muito comum para falar de experiências de viagem.","Usamos <b>have/has gone to</b> quando alguém foi para um lugar e ainda está lá ou continua fora, sem ter retornado.","Por exemplo, se Emma has been to Florida, ela já visitou a Flórida. Se Emma has gone to Florida, ela foi para lá e ainda não voltou."],"ex":[["Emma has gone to Florida.","Emma foi para a Flórida e ainda está lá."],["Emma has been to Florida.","Emma já foi à Flórida e voltou."],["Have you ever been to New York?","Você já foi a Nova York?"],["Our friends have gone to the beach.","Nossos amigos foram à praia e ainda não voltaram."]],"tip":"Para perguntar se alguém já visitou um lugar, normalmente usamos <b>Have you ever been to...?</b>, e não gone to."},{"h":"Present perfect ou past simple?","p":["O <b>present perfect</b> é usado quando queremos saber se uma experiência aconteceu em algum momento da vida, sem indicar uma data específica.","O <b>past simple</b> é usado quando falamos de uma ação concluída em um momento definido do passado: yesterday, last summer, in 2020 ou two years ago.","É muito natural começar uma conversa com present perfect e depois usar past simple para pedir detalhes.","Compare: <b>Have you ever been to San Diego?</b> pergunta sobre a experiência. <b>When did you go?</b> pergunta quando a viagem aconteceu."],"ex":[["I've been to San Diego.","Já fui a San Diego."],["I went there last summer.","Fui para lá no verão passado."],["When did you go?","Quando você foi?"],["I swam in the ocean last year.","Nadei no mar no ano passado."]],"tip":"Para uma experiência sem data, use <b>I've been there</b>. Com um momento passado definido, use <b>I went there in 2022</b>, não “I've been there in 2022”."}],"vocab":[{"h":"Experiências e aventuras","items":[["try surfing","experimentar surfar"],["go kayaking","andar de caiaque"],["swim in the ocean","nadar no mar"],["travel alone","viajar sozinho"],["go abroad","viajar para o exterior"],["visit another country","visitar outro país"],["stay in a hostel","ficar hospedado em um hostel"],["go camping","acampar"],["for the first time","pela primeira vez"]]},{"h":"Particípios importantes","items":[["be → been","ser, estar → sido, estado"],["go → gone","ir → ido"],["do → done","fazer → feito"],["see → seen","ver → visto"],["eat → eaten","comer → comido"],["swim → swum","nadar → nadado"],["take → taken","pegar, levar → pego, levado"],["fly → flown","voar → voado"],["write → written","escrever → escrito"],["try → tried","experimentar → experimentado"]]}],"pron":[{"h":"Been","p":"No inglês americano, <b>been</b> geralmente soa como “bin”, com um I curto. Não confunda com bean, que tem um I mais longo. Em <b>I've been</b>, as palavras se conectam naturalmente: “áiv bin”.","w":["been","I've been","Have you been?","never been"]},{"h":"Swam e swum","p":"<b>Swam</b>, passado de swim, tem uma vogal aberta, próxima de “suém”. Já <b>swum</b>, o particípio, soa aproximadamente “suâm”, com uma vogal curta. Essa diferença ajuda a identificar os dois tempos verbais.","w":["swim","swam","swum","I've swum"]},{"h":"Ever e never","p":"<b>Ever</b> soa aproximadamente “É-ver”, com a primeira sílaba forte e o R americano no final. <b>Never</b> segue o mesmo padrão: “NÉ-ver”. Em <b>Have you ever...?</b>, a fala costuma ligar as palavras naturalmente.","w":["ever","never","Have you ever?","I've never"]}],"mc":[{"q":"Qual cidade Lucas visitou no verão passado?","o":["Los Angeles","San Diego","Miami"],"a":1,"e":"Yes, I have. I went to San Diego with my parents last summer."},{"q":"O que Lucas fez pela primeira vez nessa viagem?","o":["Nadou no mar","Andou de caiaque","Experimentou surfar"],"a":0,"e":"Yes, I did. I swam in the ocean for the first time, and it was great!"},{"q":"Qual atividade Sarah já experimentou?","o":["Surfar","Mergulhar","Andar de caiaque"],"a":2,"e":"No, I haven't, but I've tried kayaking."},{"q":"Onde Emma está no momento da conversa?","o":["Em San Diego","Na Flórida","Na casa de Lucas"],"a":1,"e":"By the way, my sister Emma has gone to Florida for a few days."}],"gaps":[{"s":"Have you ___ been to California?","a":["ever"],"h":"Você já foi à Califórnia?"},{"s":"I've never ___ in the ocean. (Particípio de swim.)","a":["swum"],"h":"Nunca nadei no mar."},{"s":"She ___ gone to Florida, and she's still there.","a":["has","'s"],"h":"Ela foi para a Flórida e ainda está lá."},{"s":"Lucas has ___ to San Diego, and he's back home now.","a":["been"],"h":"Lucas já foi a San Diego e agora está de volta em casa."},{"s":"Have you ever ___ surfing? (Particípio de try.)","a":["tried"],"h":"Você já experimentou surfar?"},{"s":"I ___ kayaking two years ago. (Passado de try.)","a":["tried"],"h":"Experimentei andar de caiaque há dois anos."}],"order":[{"t":["Have","you","ever","tried","surfing?"],"h":"Você já experimentou surfar?"},{"t":["I've","never","been","to","Florida."],"h":"Nunca fui à Flórida."},{"t":["She","has","gone","to","California."],"h":"Ela foi para a Califórnia e ainda está lá."}],"dict":[{"t":"Have you ever been to California?"},{"t":"I've never swum in the ocean.","alt":["I have never swum in the ocean."],"note":"Atenção: swum é o particípio de swim."},{"t":"No, I haven't, but I've tried kayaking.","alt":["No, I have not, but I have tried kayaking."]},{"t":"When did you try it?"},{"t":"My sister Emma has gone to Florida for a few days.","note":"Gone indica que Emma ainda não voltou."}],"shadow":["Have you ever been to California, Lucas?","I've never swum in the ocean. Was the water cold?","No, I haven't, but I've tried kayaking.","Exactly. She's never been there before."],"write":{"task":"Escreva 4 ou 5 frases sobre suas experiências de vida. Conte duas coisas que você já fez, uma que nunca fez e quando aconteceu uma dessas experiências. Use present perfect com ever ou never e past simple para indicar um momento específico.","ph":"I've been to … I've tried … I've never … I went to … in …"},"cards":[["Você já fez uma viagem sozinho?","Have you ever taken a trip alone?"],["Nunca comi comida tailandesa.","I've never eaten Thai food."],["Ela já foi ao Canadá.","She's been to Canada."],["Meu irmão foi para o Japão e ainda está lá.","My brother has gone to Japan, and he's still there."],["Você já viu neve?","Have you ever seen snow?"],["Já tentei surfar uma vez, mas foi difícil.","I've tried surfing once, but it was difficult."],["Quando você visitou o México?","When did you visit Mexico?"],["Fui para lá com meus pais em 2021.","I went there with my parents in 2021."],["Eles nunca viajaram de avião.","They've never flown on a plane before."],["Ela já esteve em Nova York duas vezes.","She's been to New York twice."]]},{"title":"Health","goal":"Explicar sintomas em uma consulta, falar sobre obrigações e ausência de obrigação com have to e don't have to e dar conselhos simples usando should e shouldn't.","speakers":{"Sarah":"f","Daniel":"m"},"setting":"Na terça-feira de manhã, Sarah vai a uma clínica porque não está se sentindo bem. Daniel é o médico que a atende.","lines":[["Daniel","Good morning, Sarah. What's wrong?","Bom dia, Sarah. O que houve?"],["Sarah","I have a headache and a sore throat.","Estou com dor de cabeça e dor de garganta."],["Daniel","Do you have a fever?","Você está com febre?"],["Sarah","Yes, and my back hurts a little.","Sim, e minhas costas também doem um pouco."],["Daniel","Let me check your temperature. It's a little high.","Vou medir sua temperatura. Está um pouco alta."],["Sarah","Do I have to take any medicine?","Preciso tomar algum remédio?"],["Daniel","Not right now. You should rest and drink plenty of water.","Agora não. Você deve descansar e beber bastante água."],["Sarah","Do I have to stay in bed all day?","Preciso ficar na cama o dia inteiro?"],["Daniel","No, you don't have to. But you shouldn't exercise today.","Não precisa. Mas você não deveria fazer exercícios hoje."],["Sarah","I have an important meeting tomorrow.","Tenho uma reunião importante amanhã."],["Daniel","You should stay home if you still have a fever.","Você deveria ficar em casa se ainda estiver com febre."],["Sarah","Should I call the clinic if I feel worse?","Devo ligar para a clínica se eu piorar?"],["Daniel","Yes, please. And you have to get enough sleep.","Sim, por favor. E você precisa dormir o suficiente."],["Sarah","Okay, thank you. I'll take it easy today.","Certo, obrigada. Vou pegar leve hoje."]],"grammar":[{"h":"Have to: obrigação ou necessidade","p":["Use <b>have to + verbo base</b> para falar de algo necessário ou obrigatório. Muitas vezes corresponde a “ter que” ou “precisar”.","No presente, usamos <b>have to</b> com I, you, we e they; com he, she e it, usamos <b>has to</b>.","Para perguntas, use <b>Do/Does + pessoa + have to + verbo base?</b>. Mesmo com he ou she, depois de does a forma é have to."],"ex":[["I have to get enough sleep.","Preciso dormir o suficiente."],["She has to take her medicine.","Ela tem que tomar o remédio dela."],["Do you have to stay in bed?","Você precisa ficar na cama?"],["Does he have to see a doctor?","Ele precisa ir ao médico?"]],"tip":"Diga <b>Does she have to rest?</b>, não “Does she has to rest?”."},{"h":"Don't have to: não é necessário","p":["Use <b>don't have to</b> ou <b>doesn't have to</b> quando algo <b>não é obrigatório</b>. Isso não significa que a ação é proibida; significa que a pessoa pode escolher.","Na negativa, a estrutura é <b>don't/doesn't have to + verbo base</b>. A forma have não muda depois de doesn't.","É diferente de um conselho negativo: <b>You don't have to stay home</b> significa que ficar em casa não é obrigatório; <b>You shouldn't go out</b> é um conselho para não sair."],"ex":[["You don't have to stay in bed all day.","Você não precisa ficar na cama o dia inteiro."],["He doesn't have to work tomorrow.","Ele não precisa trabalhar amanhã."],["We don't have to leave now.","Não precisamos sair agora."]],"tip":"<b>Don't have to</b> significa “não precisa”. Não significa “não pode”."},{"h":"Should e shouldn't: conselhos","p":["Usamos <b>should + verbo base</b> para dar recomendações: You should rest (Você deveria descansar). Para aconselhar alguém a evitar algo, usamos <b>shouldn't + verbo base</b>.","Should é igual para todas as pessoas: I should, she should, they should. Não usamos to nem acrescentamos -s ao verbo seguinte.","São conselhos, não ordens. Em situações de saúde, o contexto importa: recomendações gerais não substituem a orientação de um profissional que examinou a pessoa."],"ex":[["You should drink more water.","Você deveria beber mais água."],["She should get some rest.","Ela deveria descansar um pouco."],["You shouldn't exercise with a fever.","Você não deveria fazer exercícios com febre."],["He shouldn't skip meals.","Ele não deveria pular refeições."]],"tip":"O correto é <b>She should rest</b>, e não “She should rests” ou “She should to rest”."},{"h":"Perguntas com should e diferença de sentido","p":["Para pedir conselho, colocamos <b>should</b> antes da pessoa: <b>Should I call the clinic?</b> (Devo ligar para a clínica?). Respostas curtas são Yes, you should e No, you shouldn't.","Compare: <b>Do I have to go?</b> pergunta se existe necessidade ou obrigação. <b>Should I go?</b> pergunta se é uma boa ideia.","Para descrever sintomas, você pode usar <b>I have a...</b> para algumas queixas e <b>My ... hurts</b> para uma parte do corpo que dói."],"ex":[["Should I see a doctor?","Eu deveria ir ao médico?"],["Should we leave early?","Deveríamos sair cedo?"],["I have a sore throat.","Estou com dor de garganta."],["My stomach hurts.","Estou com dor de estômago."]],"tip":"Lembre: <b>have to</b> expressa necessidade; <b>should</b> apresenta uma recomendação."}],"vocab":[{"h":"Partes do corpo","items":[["head","cabeça"],["throat","garganta"],["back","costas"],["stomach","estômago, barriga"],["arm","braço"],["leg","perna"],["knee","joelho"],["shoulder","ombro"],["neck","pescoço"],["eye","olho"]]},{"h":"Sintomas e cuidados","items":[["headache","dor de cabeça"],["sore throat","dor de garganta"],["fever","febre"],["cough","tosse"],["cold","resfriado"],["dizzy","tonto"],["medicine","remédio, medicamento"],["rest","descansar"],["appointment","consulta marcada"],["clinic","clínica"]]}],"pron":[{"h":"Should e shouldn't","p":"<b>Should</b> soa aproximadamente “shud”, com uma vogal curta e L silencioso. <b>Shouldn't</b> soa perto de “SHUD-ent”; a primeira sílaba é mais forte.","w":["should","shouldn't","You should rest"]},{"h":"Have to e has to","p":"Em uma fala natural, <b>have to</b> costuma soar “HÉF-tu”, com som de F. <b>Has to</b> frequentemente soa “HÉS-tu”, com S. Isso é diferente de have isolado.","w":["have to","has to","Do I have to?"]},{"h":"Throat e headache","p":"<b>Throat</b> começa com TH sem voz, com a língua entre os dentes, e soa aproximadamente “thRÔUT”. <b>Headache</b> soa “HÉD-eik”; o final ache tem som de “eik”.","w":["throat","sore throat","headache"]}],"mc":[{"q":"Quais são as principais queixas de Sarah?","o":["Dor de cabeça e dor de garganta","Dor no joelho e tosse","Dor de ouvido e enjoo"],"a":0,"e":"I have a headache and a sore throat."},{"q":"O que Daniel diz sobre a temperatura de Sarah?","o":["Está normal","Está um pouco alta","Está muito baixa"],"a":1,"e":"Let me check your temperature. It's a little high."},{"q":"O que Sarah não deveria fazer hoje?","o":["Beber água","Dormir cedo","Fazer exercícios"],"a":2,"e":"No, you don't have to. But you shouldn't exercise today."},{"q":"Qual é a orientação de Daniel se Sarah ainda estiver com febre?","o":["Ir à reunião normalmente","Ficar em casa","Tomar café forte"],"a":1,"e":"You should stay home if you still have a fever."}],"gaps":[{"s":"She ___ to take her medicine every morning.","a":["has"],"h":"Ela precisa tomar o remédio toda manhã."},{"s":"Do I ___ to stay in bed all day?","a":["have"],"h":"Preciso ficar na cama o dia inteiro?"},{"s":"You ___ have to work tomorrow. (Não é obrigatório.)","a":["don't","do not"],"h":"Você não precisa trabalhar amanhã."},{"s":"You ___ drink plenty of water. (Conselho.)","a":["should"],"h":"Você deveria beber bastante água."},{"s":"You ___ exercise when you have a fever. (Conselho negativo.)","a":["shouldn't","should not"],"h":"Você não deveria fazer exercícios quando está com febre."},{"s":"___ I call the clinic? (Pedido de conselho.)","a":["Should"],"h":"Devo ligar para a clínica?"}],"order":[{"t":["You","should","get","some","rest."],"h":"Você deveria descansar um pouco."},{"t":["He","doesn't","have","to","work","today."],"h":"Ele não precisa trabalhar hoje."},{"t":["Should","I","see","a","doctor?"],"h":"Devo ir ao médico?"}],"dict":[{"t":"I have a headache and a sore throat."},{"t":"Do I have to take any medicine?"},{"t":"You should rest and drink plenty of water."},{"t":"No, you don't have to.","alt":["No, you do not have to."]},{"t":"You shouldn't exercise today.","alt":["You should not exercise today."]}],"shadow":["I have a headache and a sore throat.","Do I have to take any medicine?","No, you don't have to. But you shouldn't exercise today.","Should I call the clinic if I feel worse?"],"write":{"task":"Imagine uma consulta médica. Escreva 4 ou 5 frases dizendo como você se sente, um sintoma que tem, uma obrigação e dois conselhos para descansar ou se cuidar. Use have to, don't have to, should ou shouldn't.","ph":"I have a … My … hurts. I have to … I don't have to … I should …"},"cards":[["Estou com muita dor de cabeça.","I have a terrible headache."],["Minha garganta dói quando falo.","My throat hurts when I talk."],["Você está com febre?","Do you have a fever?"],["Você deveria dormir um pouco.","You should get some sleep."],["Preciso ir ao médico amanhã.","I have to see the doctor tomorrow."],["Você não precisa chegar cedo.","You don't have to come early."],["Eu deveria tirar um dia de folga?","Should I take a day off?"],["Meu joelho dói depois de caminhar.","My knee hurts after walking."],["Ela não deveria pular o café da manhã.","She shouldn't skip breakfast."],["Ele precisa marcar uma consulta?","Does he have to make an appointment?"]]},{"title":"Around the house","goal":"Explicar regras dentro de casa e do prédio com must, mustn't e can't, localizar objetos com preposições de lugar e falar sobre tarefas domésticas.","speakers":{"Sarah":"f","Lucas":"m"},"setting":"No sábado de manhã, Sarah ajuda Lucas a organizar o apartamento novo. Eles conferem onde colocar os objetos e as regras do prédio antes de começar a limpeza.","lines":[["Sarah","Your new apartment looks great, Lucas!","Seu apartamento novo está ótimo, Lucas!"],["Lucas","Thanks! But we have to clean the kitchen today.","Obrigado! Mas precisamos limpar a cozinha hoje."],["Sarah","Where should I put these boxes?","Onde eu deveria colocar estas caixas?"],["Lucas","Put them next to the sofa, behind the table.","Coloque-as ao lado do sofá, atrás da mesa."],["Sarah","Okay. Is the broom in the closet?","Certo. A vassoura está no armário?"],["Lucas","No, it's between the fridge and the wall.","Não, está entre a geladeira e a parede."],["Sarah","And where are the cleaning supplies?","E onde estão os produtos de limpeza?"],["Lucas","They're under the sink, below the shelf.","Estão embaixo da pia, abaixo da prateleira."],["Sarah","Can we leave these boxes in the hallway?","Podemos deixar estas caixas no corredor?"],["Lucas","No, we can't. We must keep the hallway clear.","Não podemos. Precisamos manter o corredor livre."],["Sarah","There's a sign near the elevator, too.","Também tem uma placa perto do elevador."],["Lucas","Yes. We mustn't leave trash outside our door.","Sim. Não podemos deixar lixo do lado de fora da nossa porta."],["Sarah","Got it. I'll take out the trash, then.","Entendi. Então vou levar o lixo para fora."],["Lucas","Great! I'll wash the dishes and mop the floor.","Ótimo! Vou lavar a louça e passar pano no chão."]],"grammar":[{"h":"Must: regras e obrigações fortes","p":["Usamos <b>must + verbo base</b> quando uma regra exige alguma coisa ou quando é muito importante fazer algo. Em português, muitas vezes corresponde a “deve”, “precisa” ou “tem que”.","Must não muda com a pessoa: I must, she must, we must. Não usamos to depois de must e não acrescentamos -s ao verbo seguinte.","Em avisos de condomínio ou instruções, must pode soar mais formal e firme do que have to, visto na unidade anterior."],"ex":[["We must keep the hallway clear.","Precisamos manter o corredor livre."],["You must close the door at night.","Você deve fechar a porta à noite."],["Residents must use the trash bins.","Os moradores devem usar as lixeiras."]],"tip":"Diga <b>She must clean</b>, não “She must cleans” ou “She must to clean”."},{"h":"Mustn't e can't: o que é proibido","p":["<b>Mustn't</b> (must not) indica uma proibição ou regra negativa. <b>Can't</b> também pode indicar que algo não é permitido, especialmente em conversas do dia a dia.","Por exemplo, <b>We mustn't leave trash here</b> e <b>We can't leave trash here</b> comunicam que não é permitido deixar lixo naquele lugar.","Compare com <b>don't have to</b> da unidade anterior: essa expressão significa “não é necessário”, enquanto mustn't e can't podem significar “é proibido”."],"ex":[["You mustn't leave boxes in the hallway.","Você não pode deixar caixas no corredor."],["We can't park bikes here.","Não podemos estacionar bicicletas aqui."],["Visitors mustn't use this entrance.","Visitantes não podem usar esta entrada."]],"tip":"<b>Mustn't</b> é proibição; <b>don't have to</b> é ausência de obrigação. Não confunda."},{"h":"Preposições de lugar","p":["Para localizar objetos, use <b>next to</b> (ao lado de), <b>between</b> (entre dois elementos), <b>behind</b> (atrás de), <b>in front of</b> (na frente de) e <b>under</b> (embaixo de).","<b>Above</b> e <b>below</b> indicam posições mais altas ou mais baixas. <b>On</b> geralmente indica contato com uma superfície; under indica posição inferior.","As preposições geralmente aparecem depois de is ou are: The keys are on the table. Para dar instruções, use um verbo como put: Put the box under the desk."],"ex":[["The broom is behind the door.","A vassoura está atrás da porta."],["The boxes are next to the sofa.","As caixas estão ao lado do sofá."],["The lamp is above the table.","A luminária está acima da mesa."],["The trash can is between the sink and the fridge.","A lixeira está entre a pia e a geladeira."]],"tip":"<b>Between</b> normalmente aparece com os dois elementos: between the sofa and the table."},{"h":"Tarefas domésticas e regras na prática","p":["Para descrever tarefas domésticas, use verbos como <b>wash</b>, <b>clean</b>, <b>mop</b> e <b>take out</b>. Com tarefas habituais, o present simple também é útil.","Você pode combinar obrigações e localizações na mesma frase: We must put the bins outside (Precisamos colocar as lixeiras lá fora).","Para oferecer ajuda imediatamente, use <b>I'll</b>, estudado na Unidade 7: I'll wash the dishes. E para fazer pedidos educados, use Can you...?"],"ex":[["I wash the dishes after dinner.","Lavo a louça depois do jantar."],["We must take out the trash tonight.","Precisamos levar o lixo para fora hoje à noite."],["I'll mop the kitchen floor.","Vou passar pano no chão da cozinha."],["Can you put the towels on the shelf?","Você pode colocar as toalhas na prateleira?"]],"tip":"<b>Take out the trash</b> significa “levar o lixo para fora”; <b>do the laundry</b> significa “lavar roupa”."}],"vocab":[{"h":"Tarefas de casa","items":[["wash the dishes","lavar a louça"],["mop the floor","passar pano no chão"],["sweep the floor","varrer o chão"],["take out the trash","levar o lixo para fora"],["do the laundry","lavar roupa"],["make the bed","arrumar a cama"],["clean the kitchen","limpar a cozinha"],["dust the shelves","tirar o pó das prateleiras"],["vacuum the carpet","aspirar o tapete"],["put things away","guardar as coisas"]]},{"h":"Cômodos e posições","items":[["hallway","corredor"],["closet","armário embutido"],["shelf","prateleira"],["sink","pia"],["broom","vassoura"],["next to","ao lado de"],["between","entre"],["behind","atrás de"],["in front of","na frente de"],["under","embaixo de"]]}],"pron":[{"h":"Must e mustn't","p":"<b>Must</b> soa aproximadamente “mâst”, com uma vogal curta. <b>Mustn't</b> pode soar “MÂS-ent” na fala americana; o T pode quase desaparecer antes do N.","w":["must","mustn't","We must clean"]},{"h":"Closet","p":"<b>Closet</b> soa aproximadamente “KLÓ-zit”, com S de som Z na primeira sílaba. Não confunda com close, usado para “fechar”.","w":["closet","in the closet","clean the closet"]},{"h":"Under e behind","p":"<b>Under</b> soa aproximadamente “ÂN-der”, com a primeira sílaba forte. <b>Behind</b> soa “bi-HÁIND”, com a segunda sílaba forte e som de AI.","w":["under","under the sink","behind","behind the door"]}],"mc":[{"q":"Onde Lucas pede que Sarah coloque as caixas?","o":["Embaixo da pia","Ao lado do sofá, atrás da mesa","Dentro do armário"],"a":1,"e":"Put them next to the sofa, behind the table."},{"q":"Onde está a vassoura?","o":["Entre a geladeira e a parede","Atrás da porta","Ao lado do elevador"],"a":0,"e":"No, it's between the fridge and the wall."},{"q":"Por que não podem deixar as caixas no corredor?","o":["Porque vão pintar o corredor","Porque as caixas estão molhadas","Porque o corredor precisa ficar livre"],"a":2,"e":"No, we can't. We must keep the hallway clear."},{"q":"Qual tarefa Lucas diz que vai fazer?","o":["Arrumar a cama e varrer","Lavar a louça e passar pano","Lavar roupa e tirar pó"],"a":1,"e":"Great! I'll wash the dishes and mop the floor."}],"gaps":[{"s":"Residents ___ keep the hallway clear. (Obrigação forte.)","a":["must"],"h":"Os moradores devem manter o corredor livre."},{"s":"You ___ leave trash here. It's prohibited. (Use mustn't.)","a":["mustn't","must not"],"h":"Você não pode deixar lixo aqui. É proibido."},{"s":"We ___ park our bikes here. The sign says no bikes. (Use can't.)","a":["can't","cannot"],"h":"Não podemos estacionar nossas bicicletas aqui. A placa proíbe bicicletas."},{"s":"The broom is ___ the door. (Atrás da porta.)","a":["behind"],"h":"A vassoura está atrás da porta."},{"s":"The keys are ___ the table and the lamp. (Entre.)","a":["between"],"h":"As chaves estão entre a mesa e a luminária."},{"s":"Put the towels ___ the shelf. (Em cima da prateleira.)","a":["on"],"h":"Coloque as toalhas sobre a prateleira."}],"order":[{"t":["We","must","keep","the","hallway","clear."],"h":"Precisamos manter o corredor livre."},{"t":["You","can't","leave","boxes","in","the","hallway."],"h":"Você não pode deixar caixas no corredor."},{"t":["The","broom","is","behind","the","door."],"h":"A vassoura está atrás da porta."}],"dict":[{"t":"Put them next to the sofa, behind the table."},{"t":"It's between the fridge and the wall."},{"t":"We must keep the hallway clear."},{"t":"We mustn't leave trash outside our door.","alt":["We must not leave trash outside our door."]},{"t":"I'll wash the dishes and mop the floor."}],"shadow":["Put them next to the sofa, behind the table.","No, it's between the fridge and the wall.","No, we can't. We must keep the hallway clear.","Great! I'll wash the dishes and mop the floor."],"write":{"task":"Descreva regras e tarefas da sua casa em 4 ou 5 frases. Inclua uma regra obrigatória, uma proibição e a posição de dois objetos. Use must, mustn't ou can't e preposições de lugar.","ph":"At home, we must … We mustn't … The … is next to … I usually …"},"cards":[["Precisamos fechar o portão à noite.","We must close the gate at night."],["Você não pode deixar sapatos no corredor.","You can't leave shoes in the hallway."],["O aspirador de pó está no armário.","The vacuum cleaner is in the closet."],["Coloque a bolsa embaixo da cadeira.","Put the bag under the chair."],["O espelho fica acima da pia.","The mirror is above the sink."],["O cesto de roupa está atrás da porta.","The laundry basket is behind the door."],["Preciso lavar roupa hoje.","I have to do the laundry today."],["Não podemos bloquear as escadas.","We mustn't block the stairs."],["A mesa está na frente da janela.","The table is in front of the window."],["Você pode levar o lixo para fora hoje à noite?","Can you take out the trash tonight?"]]},{"title":"What were you doing?","goal":"Descrever ações em andamento no passado com was/were + -ing e contar imprevistos, relacionando acontecimentos com when e while.","speakers":{"Emma":"f","Lucas":"m"},"setting":"Na manhã seguinte a uma queda de energia no prédio, Emma encontra Lucas em uma cafeteria. Ele conta como uma noite tranquila acabou se tornando confusa.","lines":[["Emma","You look tired, Lucas. What happened last night?","Você parece cansado, Lucas. O que aconteceu ontem à noite?"],["Lucas","I was cooking dinner when the lights went out.","Eu estava fazendo o jantar quando a luz acabou."],["Emma","Oh no! What were you making?","Nossa! O que você estava preparando?"],["Lucas","I was making pasta, and my roommate was working in the living room.","Eu estava fazendo macarrão, e meu colega de apartamento estava trabalhando na sala."],["Emma","Did you have a flashlight?","Você tinha uma lanterna?"],["Lucas","No. While I was looking for my phone, I dropped a glass.","Não. Enquanto procurava meu celular, deixei um copo cair."],["Emma","Were you hurt?","Você se machucou?"],["Lucas","No, but I was cleaning the floor when my neighbor knocked on the door.","Não, mas eu estava limpando o chão quando minha vizinha bateu à porta."],["Emma","What did she want?","O que ela queria?"],["Lucas","She said the whole building was dark.","Ela disse que o prédio inteiro estava sem luz."],["Emma","What happened to your dinner?","E o que aconteceu com seu jantar?"],["Lucas","We were waiting for the power to come back, but it didn't.","Estávamos esperando a energia voltar, mas ela não voltou."],["Emma","So what did you eat?","Então o que vocês comeram?"],["Lucas","We ordered pizza. The lights came back at ten.","Pedimos pizza. A luz voltou às dez."]],"grammar":[{"h":"Past continuous: ações em andamento no passado","p":["Usamos o <b>past continuous</b> para mostrar que uma ação estava acontecendo em determinado momento do passado. A estrutura é <b>was/were + verbo com -ing</b>.","Use <b>was</b> com I, he, she e it; use <b>were</b> com you, we e they. A terminação -ing segue as regras já vistas no present continuous.","O past simple apresenta uma ação concluída; o past continuous destaca o que estava em andamento naquele momento."],"ex":[["I was cooking dinner at eight.","Eu estava fazendo o jantar às oito."],["She was studying last night.","Ela estava estudando ontem à noite."],["We were waiting outside.","Estávamos esperando lá fora."],["They were watching TV at nine.","Eles estavam vendo TV às nove."]],"tip":"Não diga “I were cooking”. Com I, use <b>was</b>: I was cooking."},{"h":"Perguntas e negativas no past continuous","p":["Para fazer perguntas, coloque <b>was</b> ou <b>were</b> antes da pessoa: <b>Were you sleeping?</b>. Com palavras como what e where, coloque-as no início.","Para formar a negativa, use <b>wasn't</b> ou <b>weren't</b> antes do verbo com -ing.","Nas respostas curtas, não repita o verbo principal: Yes, I was ou No, I wasn't."],"ex":[["What were you doing at nine?","O que você estava fazendo às nove?"],["Was he working last night?","Ele estava trabalhando ontem à noite?"],["I wasn't sleeping at that time.","Eu não estava dormindo naquela hora."],["They weren't watching the game.","Eles não estavam assistindo ao jogo."]],"tip":"Para perguntas sobre uma ação em andamento, use <b>Were you cooking?</b>, não “Did you were cooking?”."},{"h":"When: uma ação interrompe outra","p":["Usamos <b>when</b> (quando) para ligar uma ação que estava acontecendo a um acontecimento mais curto que ocorreu naquele momento.","Um padrão muito frequente é <b>past continuous + when + past simple</b>. Por exemplo: I was cooking when the phone rang. A ação de cozinhar já estava em andamento; o telefone tocou depois.","Também podemos começar a frase com when, sem mudar a ideia principal."],"ex":[["I was walking home when it started raining.","Eu estava voltando a pé para casa quando começou a chover."],["She was sleeping when the phone rang.","Ela estava dormindo quando o telefone tocou."],["When the lights went out, we were eating.","Quando a luz acabou, estávamos comendo."]],"tip":"O verbo depois de <b>when</b> costuma aparecer no past simple quando indica a interrupção."},{"h":"While: enquanto duas ações aconteciam","p":["<b>While</b> significa “enquanto” e frequentemente introduz uma ação em andamento no passado. É muito útil para descrever o contexto de um imprevisto.","Podemos combinar <b>while + past continuous</b> com um acontecimento no past simple ou com outra ação também em andamento.","Compare: While I was cooking, he was cleaning descreve duas ações simultâneas; While I was cooking, the lights went out apresenta um imprevisto."],"ex":[["While I was cooking, Lucas was setting the table.","Enquanto eu cozinhava, Lucas estava arrumando a mesa."],["While she was walking, her phone rang.","Enquanto ela caminhava, o celular tocou."],["He was reading while I was studying.","Ele estava lendo enquanto eu estudava."]],"tip":"<b>When</b> destaca frequentemente o acontecimento pontual; <b>while</b> destaca a atividade que estava em andamento."}],"vocab":[{"h":"Imprevistos do dia a dia","items":[["power outage","queda de energia"],["lights went out","a luz acabou"],["flashlight","lanterna"],["phone rang","o telefone tocou"],["drop a glass","deixar um copo cair"],["knock on the door","bater à porta"],["get hurt","se machucar"],["come back","voltar"],["wait","esperar"],["order pizza","pedir pizza"]]},{"h":"Atividades em andamento","items":[["cook dinner","fazer o jantar"],["make pasta","fazer macarrão"],["look for","procurar"],["clean the floor","limpar o chão"],["work from home","trabalhar de casa"],["read a book","ler um livro"],["watch TV","assistir à televisão"],["sleep","dormir"],["take a shower","tomar banho"],["walk home","voltar para casa a pé"]]}],"pron":[{"h":"Was e were na fala","p":"<b>Was</b> normalmente soa “uâz” em uma fala cuidadosa e fica mais fraco quando não recebe ênfase. <b>Were</b> tem o R americano, aproximadamente “uâr”.","w":["was","were","I was cooking","We were waiting"]},{"h":"While e when","p":"<b>While</b> soa aproximadamente “uáil”, com som de AI. <b>When</b> soa “uén”, com E aberto. As duas começam com o mesmo som de W, mas têm vogais diferentes.","w":["while","when","while I was walking"]},{"h":"Cooking e looking","p":"O final <b>-ing</b> termina com um som nasal posterior, sem pronunciar um G forte separado. <b>Cooking</b> soa aproximadamente “KÚ-king” e <b>looking</b> soa “LÚ-king”.","w":["cooking","looking","waiting","working"]}],"mc":[{"q":"O que Lucas estava fazendo quando a luz acabou?","o":["Dormindo","Fazendo o jantar","Lendo um livro"],"a":1,"e":"I was cooking dinner when the lights went out."},{"q":"O que Lucas derrubou enquanto procurava o celular?","o":["Um copo","Uma lanterna","Um prato"],"a":0,"e":"No. While I was looking for my phone, I dropped a glass."},{"q":"Quem bateu à porta enquanto Lucas limpava o chão?","o":["Seu colega de apartamento","O entregador de pizza","Sua vizinha"],"a":2,"e":"No, but I was cleaning the floor when my neighbor knocked on the door."},{"q":"Como Lucas resolveu o problema do jantar?","o":["Cozinhou no escuro","Pediu pizza","Foi a um restaurante"],"a":1,"e":"We ordered pizza. The lights came back at ten."}],"gaps":[{"s":"I ___ cooking when the lights went out.","a":["was"],"h":"Eu estava cozinhando quando a luz acabou."},{"s":"They ___ watching TV at nine.","a":["were"],"h":"Eles estavam assistindo à TV às nove."},{"s":"What ___ you doing at eight?","a":["were"],"h":"O que você estava fazendo às oito?"},{"s":"She ___ sleeping at that time. (Use wasn't.)","a":["wasn't","was not"],"h":"Ela não estava dormindo naquela hora."},{"s":"I was walking home ___ it started raining.","a":["when"],"h":"Eu estava voltando para casa quando começou a chover."},{"s":"___ I was cooking, Daniel was cleaning.","a":["While"],"h":"Enquanto eu cozinhava, Daniel estava limpando."}],"order":[{"t":["I","was","cooking","when","you","called."],"h":"Eu estava cozinhando quando você ligou."},{"t":["What","were","you","doing","last","night?"],"h":"O que você estava fazendo ontem à noite?"},{"t":["I","was","working","while","she","was","reading."],"h":"Eu estava trabalhando enquanto ela lia."}],"dict":[{"t":"I was cooking dinner when the lights went out."},{"t":"What were you making?"},{"t":"While I was looking for my phone, I dropped a glass."},{"t":"We were waiting for the power to come back."},{"t":"I wasn't sleeping when you called.","alt":["I was not sleeping when you called."]}],"shadow":["I was cooking dinner when the lights went out.","No. While I was looking for my phone, I dropped a glass.","No, but I was cleaning the floor when my neighbor knocked on the door.","We were waiting for the power to come back, but it didn't."],"write":{"task":"Conte um pequeno imprevisto que aconteceu enquanto você fazia alguma coisa. Escreva 4 ou 5 frases dizendo o que estava fazendo, o que aconteceu e como terminou. Use past continuous, past simple, when e while.","ph":"Yesterday, I was … when … While I was …, … After that, I …"},"cards":[["Eu estava tomando banho quando o telefone tocou.","I was taking a shower when the phone rang."],["O que você estava fazendo às sete?","What were you doing at seven?"],["Estávamos jantando quando ela chegou.","We were having dinner when she arrived."],["Enquanto eu dirigia, começou a chover.","While I was driving, it started raining."],["Ele não estava prestando atenção quando o chamei.","He wasn't listening when I called him."],["Eles estavam dormindo durante a tempestade.","They were sleeping during the storm."],["A luz acabou enquanto eu estudava.","The lights went out while I was studying."],["Eu estava procurando minhas chaves quando você chegou.","I was looking for my keys when you arrived."],["Você estava trabalhando quando mandei mensagem?","Were you working when I texted you?"],["Meu café derramou enquanto eu caminhava.","My coffee spilled while I was walking."]]},{"title":"Keeping in touch","goal":"Falar sobre mensagens, telefonemas e e-mails recentes com present perfect, usando just para algo que acabou de acontecer, already para algo que já foi feito e yet em perguntas e negativas.","speakers":{"Sarah":"f","Emma":"f"},"setting":"Na quinta-feira à tarde, Sarah e Emma organizam um jantar entre amigos pelo celular. Elas conferem convites, respostas e informações que ainda precisam enviar.","lines":[["Sarah","Have you sent the invitation to Daniel yet?","Você já mandou o convite para o Daniel?"],["Emma","Yes, I've just emailed it to him.","Sim, acabei de mandar por e-mail para ele."],["Sarah","Great. Has he replied yet?","Ótimo. Ele já respondeu?"],["Emma","Not yet, but Lucas has already confirmed.","Ainda não, mas o Lucas já confirmou."],["Sarah","Did you check the group chat?","Você olhou a conversa do grupo?"],["Emma","Yes, I've already read all the messages.","Sim, já li todas as mensagens."],["Sarah","I haven't seen the new address yet.","Ainda não vi o endereço novo."],["Emma","I've just sent it to you. Check your phone.","Acabei de mandar para você. Olhe o celular."],["Sarah","Got it! Have you called the restaurant yet?","Recebi! Você já ligou para o restaurante?"],["Emma","Yes, I have. I called this morning.","Já. Liguei hoje de manhã."],["Sarah","And have you shared the meeting time?","E você já compartilhou o horário do encontro?"],["Emma","Not yet. I'll post it in the group now.","Ainda não. Vou postar no grupo agora."],["Sarah","Perfect. Daniel has just replied!","Perfeito. O Daniel acabou de responder!"],["Emma","Great! Now everyone has the details.","Ótimo! Agora todo mundo tem as informações."]],"grammar":[{"h":"Present perfect com just: acabou de acontecer","p":["Usamos <b>have/has + just + particípio passado</b> para falar de algo que aconteceu há pouquíssimo tempo e é importante agora. <b>Just</b> costuma significar “acabei de” ou “acabou de”.","A posição mais comum é entre have/has e o particípio: <b>I've just sent</b>, <b>she's just called</b>.","O particípio dos verbos regulares termina geralmente em -ed, como replied e emailed; alguns irregulares são sent (send), read (read) e written (write)."],"ex":[["I've just sent the address.","Acabei de mandar o endereço."],["She's just called me.","Ela acabou de me ligar."],["Daniel has just replied.","Daniel acabou de responder."]],"tip":"Não diga “I have sent just the email” quando quiser dizer “acabei de enviar”. Prefira <b>I've just sent the email</b>."},{"h":"Already: algo que já foi feito","p":["Usamos <b>already</b> para mostrar que algo já aconteceu, muitas vezes antes do esperado ou antes de outra pessoa perguntar.","No present perfect, already geralmente fica <b>entre have/has e o particípio</b>: I've already read it (Já li). Também pode aparecer no fim em linguagem informal.","Em conversas, a resposta com already pode indicar que uma tarefa está concluída e não precisa ser repetida."],"ex":[["I've already read your message.","Já li sua mensagem."],["He's already confirmed the time.","Ele já confirmou o horário."],["We've already emailed the details.","Já enviamos as informações por e-mail."]],"tip":"A ordem mais comum é <b>have/has + already + particípio</b>: She has already replied."},{"h":"Yet: já? e ainda não","p":["Usamos <b>yet</b> principalmente no final de perguntas e negativas com present perfect. Nas perguntas, pode significar “já”; nas negativas, significa “ainda não”.","Para perguntar, use <b>Have/Has + pessoa + particípio + yet?</b>. Na negativa, use <b>haven't/hasn't + particípio + yet</b>.","A resposta curta <b>Not yet</b> significa “Ainda não”. Compare: Have you called yet? / No, I haven't called yet."],"ex":[["Have you sent the email yet?","Você já enviou o e-mail?"],["He hasn't replied yet.","Ele ainda não respondeu."],["I haven't checked my inbox yet.","Ainda não olhei minha caixa de entrada."],["Not yet. I'll send it now.","Ainda não. Vou mandar agora."]],"tip":"Não coloque yet entre have e o particípio nesse uso. Diga <b>I haven't sent it yet</b>."},{"h":"Just, already, yet e past simple na conversa","p":["As três palavras ajudam a situar uma ação recente: <b>just</b> destaca algo que acabou de acontecer, <b>already</b> destaca que já foi feito e <b>yet</b> pergunta ou indica que ainda não foi feito.","Use o <b>past simple</b> quando disser exatamente quando uma ação terminou: <b>I called this morning</b>. Use o present perfect quando o foco está na informação atual, sem mencionar um momento passado concluído: <b>I've already called</b>.","Para não repetir uma frase inteira, responda com <b>Yes, I have</b> ou <b>No, I haven't</b>."],"ex":[["I've just emailed Daniel.","Acabei de mandar e-mail para Daniel."],["I've already called the restaurant.","Já liguei para o restaurante."],["Have you checked the address yet?","Você já conferiu o endereço?"],["I called at nine this morning.","Liguei às nove de hoje de manhã."]],"tip":"Com um horário passado definido, prefira <b>I called at nine</b>, não “I've called at nine”."}],"vocab":[{"h":"Mensagens e e-mails","items":[["send a message","mandar uma mensagem"],["reply","responder"],["forward an email","encaminhar um e-mail"],["attachment","anexo"],["inbox","caixa de entrada"],["subject line","assunto do e-mail"],["group chat","conversa em grupo"],["notification","notificação"],["confirm","confirmar"],["share a link","compartilhar um link"]]},{"h":"Telefone e contato","items":[["missed call","chamada perdida"],["voicemail","correio de voz"],["call back","retornar a ligação"],["text someone","mandar mensagem para alguém"],["contact","contato"],["phone number","número de telefone"],["address","endereço"],["meeting time","horário do encontro"],["read a message","ler uma mensagem"],["post in the group","publicar no grupo"]]}],"pron":[{"h":"Just e yet","p":"<b>Just</b> soa aproximadamente “djâst”, com o J de “dj”. <b>Yet</b> soa “iét”, com E aberto. Em frases rápidas, o T final pode ser bem curto.","w":["just","yet","just sent","not yet"]},{"h":"Already","p":"<b>Already</b> costuma ter três sílabas: “ól-RÉ-di”, com a segunda mais forte. O R americano aparece claramente. Evite separar em “all” e “ready” na fala.","w":["already","already sent","I've already read it"]},{"h":"Replied e emailed","p":"<b>Replied</b> soa aproximadamente “ri-PLÁID”, com ênfase na última sílaba. <b>Emailed</b> soa “Í-meild”, com duas sílabas. O final -ed de emailed tem som de D, sem sílaba extra.","w":["replied","emailed","I've replied"]}],"mc":[{"q":"O que Emma acabou de fazer no início do diálogo?","o":["Ligou para o restaurante","Mandou o convite a Daniel por e-mail","Enviou fotos para Lucas"],"a":1,"e":"Yes, I've just emailed it to him."},{"q":"Quem já confirmou presença?","o":["Lucas","Daniel","Sarah"],"a":0,"e":"Not yet, but Lucas has already confirmed."},{"q":"Qual informação Sarah ainda não tinha visto?","o":["O cardápio","O horário do jantar","O endereço novo"],"a":2,"e":"I haven't seen the new address yet."},{"q":"O que Emma ainda precisava fazer?","o":["Ligar para o restaurante","Publicar o horário no grupo","Ler as mensagens antigas"],"a":1,"e":"Not yet. I'll post it in the group now."}],"gaps":[{"s":"I've ___ sent the address. (Acabei de enviar.)","a":["just"],"h":"Acabei de enviar o endereço."},{"s":"She's ___ read your message. (Ela já leu.)","a":["already"],"h":"Ela já leu sua mensagem."},{"s":"Have you called him ___?","a":["yet"],"h":"Você já ligou para ele?"},{"s":"I haven't checked my inbox ___.","a":["yet"],"h":"Ainda não olhei minha caixa de entrada."},{"s":"He ___ just replied to the email.","a":["has","'s"],"h":"Ele acabou de responder ao e-mail."},{"s":"We ___ already sent the invitation.","a":["have","'ve"],"h":"Já enviamos o convite."}],"order":[{"t":["I've","just","sent","the","email."],"h":"Acabei de enviar o e-mail."},{"t":["Have","you","checked","the","address","yet?"],"h":"Você já conferiu o endereço?"},{"t":["She","hasn't","called","me","yet."],"h":"Ela ainda não me ligou."}],"dict":[{"t":"Have you sent the invitation to Daniel yet?"},{"t":"I've just emailed it to him.","alt":["I have just emailed it to him."]},{"t":"Lucas has already confirmed."},{"t":"I haven't seen the new address yet.","alt":["I have not seen the new address yet."]},{"t":"Daniel has just replied!"}],"shadow":["Have you sent the invitation to Daniel yet?","Not yet, but Lucas has already confirmed.","I've just sent it to you. Check your phone.","Perfect. Daniel has just replied!"],"write":{"task":"Imagine que você está organizando um encontro por mensagem. Escreva 4 ou 5 frases dizendo o que acabou de enviar, o que já confirmou e o que ainda não fez. Inclua just, already e yet.","ph":"I've just … I've already … I haven't … yet. Have you … yet?"},"cards":[["Acabei de receber seu e-mail.","I've just received your email."],["Você já abriu o anexo?","Have you opened the attachment yet?"],["Ela ainda não respondeu à minha mensagem.","She hasn't answered my message yet."],["Já compartilhamos o link.","We've already shared the link."],["Acabei de perder sua ligação.","I've just missed your call."],["O Daniel já olhou o grupo?","Has Daniel checked the group chat yet?"],["As informações do encontro já chegaram.","The meeting details have already arrived."],["Ainda não salvei seu número.","I haven't saved your number yet."],["Ele acabou de deixar uma mensagem de voz.","He's just left a voicemail."],["Eles já confirmaram o endereço?","Have they confirmed the address yet?"]]},{"title":"Since Then","goal":"Falar sobre situações que começaram no passado e continuam até hoje, indicar há quanto tempo algo acontece usando for e since, descrever atividades em andamento com o present perfect continuous e perguntar sobre sua duração com How long have you been...?","speakers":{"Sarah":"f","Emma":"f"},"setting":"Em uma cafeteria do bairro, Sarah encontra Emma depois de algumas semanas sem se verem. Elas conversam sobre mudanças na rotina, amizades, trabalho e atividades que Emma começou desde que se mudou.","lines":[["Sarah","You seem really happy with your new apartment. How long have you lived there?","Você parece muito feliz com seu apartamento novo. Há quanto tempo mora lá?"],["Emma","I've lived there for almost two years, but I've only worked from home since March.","Moro lá há quase dois anos, mas só trabalho de casa desde março."],["Sarah","Has it been easy to make friends in the neighborhood?","Foi fácil fazer amigos no bairro?"],["Emma","It was hard at first. Since then, I've met some great people at the community garden.","Foi difícil no começo. De lá para cá, conheci pessoas incríveis na horta comunitária."],["Sarah","I didn't know you were into gardening. How long have you been doing that?","Eu não sabia que você gostava de jardinagem. Há quanto tempo você faz isso?"],["Emma","I've been helping there for six months. We grow vegetables and share them with our neighbors.","Estou ajudando lá há seis meses. Cultivamos verduras e legumes e dividimos com nossos vizinhos."],["Sarah","That sounds nice. Have you been spending a lot of time there lately?","Que legal. Você tem passado bastante tempo lá ultimamente?"],["Emma","Yes, I've been going every Saturday morning, even when I'm tired.","Sim, tenho ido todos os sábados de manhã, mesmo quando estou cansada."],["Sarah","And what about your English classes? Are you still taking them?","E suas aulas de inglês? Você ainda está fazendo?"],["Emma","I am. I've been studying twice a week since January, and I can finally follow podcasts.","Estou, sim. Estudo duas vezes por semana desde janeiro e finalmente consigo acompanhar podcasts."],["Sarah","Wow, you've made a lot of changes since you moved.","Nossa, você fez muitas mudanças desde que se mudou."],["Emma","I have, but I still miss my old friends. I've known some of them since college.","Fiz mesmo, mas ainda sinto falta dos meus amigos antigos. Conheço alguns deles desde a faculdade."],["Sarah","We should visit the garden together one weekend.","A gente devia visitar a horta juntas em algum fim de semana."],["Emma","I'd love that. I've been looking for someone to go with me.","Eu adoraria. Estou procurando alguém para ir comigo."]],"grammar":[{"h":"Present perfect com for e since","p":["Usamos o <b>present perfect</b> para falar de situações que começaram no passado e continuam no presente. A estrutura é <b>have/has + particípio passado</b>. Em português, frequentemente traduzimos essas situações usando o presente.","<b>For</b> indica a duração: for two years (há dois anos), for six months (há seis meses). <b>Since</b> indica o ponto de partida: since March (desde março), since 2020 (desde 2020).","Observe a diferença: <b>I've lived here for two years</b> informa quanto tempo moro aqui. <b>I've lived here since 2024</b> informa quando comecei a morar aqui.","Também usamos o present perfect na negativa para situações que não aconteceram durante determinado período."],"ex":[["I've lived here for two years.","Moro aqui há dois anos."],["She has worked here since May.","Ela trabalha aqui desde maio."],["We've known each other for a long time.","Nós nos conhecemos há muito tempo."],["I haven't visited my hometown for several months.","Não visito minha cidade natal há vários meses."]],"tip":"Use <b>for + duração</b> e <b>since + ponto de partida</b>. Não diga “since three years” para expressar uma duração."},{"h":"Present perfect continuous: atividades que vêm acontecendo","p":["O <b>present perfect continuous</b> destaca uma atividade que começou no passado e vem acontecendo até agora, de maneira contínua ou repetida. A estrutura é <b>have/has + been + verbo com -ing</b>.","Compare: <b>I've worked here for two years</b> apresenta uma situação que continua. <b>I've been working on this project for two hours</b> destaca a atividade e o tempo dedicado a ela.","Também usamos essa estrutura para falar de atividades recentes, especialmente com expressões como <b>lately</b> (ultimamente) e <b>recently</b> (recentemente)."],"ex":[["I've been learning English since January.","Estou aprendendo inglês desde janeiro."],["He's been working all morning.","Ele está trabalhando a manhã inteira."],["They've been waiting for half an hour.","Eles estão esperando há meia hora."],["We've been preparing the garden for a few weeks.","Estamos preparando a horta há algumas semanas."]],"tip":"O <b>been</b> é obrigatório: I've been studying. Não diga “I've studying”."},{"h":"How long have you been...?: perguntar há quanto tempo","p":["Para perguntar há quanto tempo uma atividade acontece, usamos <b>How long + have/has + pessoa + been + verbo com -ing?</b>.","Em respostas, podemos usar <b>for</b> ou <b>since</b>. Por exemplo, à pergunta How long have you been studying?, podemos responder For six months ou Since January.","Também é possível perguntar sobre situações duradouras com o present perfect simples: <b>How long have you lived here?</b> é natural e frequente.","Em perguntas que começam diretamente com Have ou Has, podemos usar <b>long</b> no final para perguntar se a atividade já dura bastante tempo."],"ex":[["How long have you been living here?","Há quanto tempo você mora aqui?"],["How long has she been studying?","Há quanto tempo ela está estudando?"],["Have you been working here long?","Você trabalha aqui há muito tempo?"],["How long have they been waiting for the bus?","Há quanto tempo eles estão esperando o ônibus?"]],"tip":"Depois de <b>How long have you been</b>, use o verbo com <b>-ing</b> quando estiver perguntando sobre uma atividade."},{"h":"Present perfect ou past simple? E os verbos de estado","p":["Use o <b>past simple</b> para ações concluídas em um momento definido do passado. Use o <b>present perfect</b> para situações que começaram antes e continuam agora ou para experiências ligadas ao presente.","Compare: <b>I moved here two years ago</b> informa quando a mudança aconteceu. <b>I've lived here for two years</b> mostra que ainda moro aqui.","Alguns verbos, como <b>know, like, believe</b> e <b>have</b> no sentido de possuir, normalmente não aparecem no continuous quando expressam estados. Dizemos <b>I've known her for years</b>, e não “I've been knowing her for years”.","Com <b>since</b> seguido de uma oração que identifica o início da situação, geralmente usamos o past simple nessa oração: since I moved, since we met."],"ex":[["I moved here two years ago.","Eu me mudei para cá há dois anos."],["I've lived here since 2024.","Moro aqui desde 2024."],["I've known Sarah since college.","Conheço Sarah desde a faculdade."],["I haven't seen Lucas since last summer.","Não vejo Lucas desde o verão passado."]],"tip":"Para dizer há quanto tempo conhece alguém, use <b>I've known</b>, não “I've been knowing”."}],"vocab":[{"h":"Mudanças e vida no bairro","items":[["neighborhood","bairro"],["community garden","horta comunitária"],["neighbor","vizinho"],["move","mudar de casa"],["grow vegetables","cultivar verduras e legumes"],["make friends","fazer amigos"],["share","compartilhar"],["work from home","trabalhar de casa"],["miss someone","sentir falta de alguém"],["be into something","gostar muito de alguma coisa"]]},{"h":"Duração e atividades recentes","items":[["for","há; durante; por"],["since","desde"],["since then","desde então; de lá para cá"],["lately","ultimamente"],["recently","recentemente"],["all morning","a manhã inteira"],["for a while","há algum tempo; por algum tempo"],["almost","quase"],["keep doing something","continuar fazendo alguma coisa"],["follow a podcast","acompanhar um podcast"]]}],"pron":[{"h":"Have e has nas contrações","p":"No present perfect, <b>I have</b> frequentemente vira <b>I've</b>, aproximadamente “áiv”. <b>She has</b> vira <b>she's</b>, aproximadamente “shíz”. Essas contrações são comuns na fala americana. A forma she's também pode significar she is; o contexto e o verbo seguinte ajudam a identificar.","w":["I've lived","You've changed","She's worked","We've known"]},{"h":"Been e o som curto de I","p":"No inglês americano, <b>been</b> costuma soar aproximadamente “bin”, com uma vogal curta. Em <b>I've been working</b>, as palavras são pronunciadas de maneira conectada, sem uma pausa forte depois de been.","w":["been","I've been studying","She's been waiting","We've been working"]},{"h":"For e since na fala natural","p":"<b>For</b> muitas vezes tem uma pronúncia reduzida, aproximadamente “fâr”, com R americano suave. <b>Since</b> soa aproximadamente “sins”, com S no começo e no final. Em uma conversa, for geralmente recebe menos destaque que a duração que vem depois.","w":["for two years","for six months","since January","since last week"]}],"mc":[{"q":"Há quanto tempo Emma mora no apartamento atual?","o":["Desde março","Há quase dois anos","Há seis meses"],"a":1,"e":"I've lived there for almost two years, but I've only worked from home since March."},{"q":"Onde Emma conheceu novas pessoas no bairro?","o":["Na horta comunitária","Nas aulas de inglês","Na empresa onde trabalha"],"a":0,"e":"It was hard at first. Since then, I've met some great people at the community garden."},{"q":"Com que frequência Emma tem ido à horta?","o":["Todas as tardes","Duas vezes por semana","Todos os sábados de manhã"],"a":2,"e":"Yes, I've been going every Saturday morning, even when I'm tired."},{"q":"O que Emma já consegue fazer melhor graças às aulas de inglês?","o":["Dar aulas de inglês","Acompanhar podcasts","Escrever livros em inglês"],"a":1,"e":"I am. I've been studying twice a week since January, and I can finally follow podcasts."}],"gaps":[{"s":"She's lived in this neighborhood ___ last July.","a":["since"],"h":"Ela mora neste bairro desde julho do ano passado."},{"s":"We've known each other ___ six years.","a":["for"],"h":"Nós nos conhecemos há seis anos."},{"s":"How long have you ___ working here?","a":["been"],"h":"Há quanto tempo você está trabalhando aqui?"},{"s":"He ___ been studying all morning.","a":["has","'s"],"h":"Ele está estudando a manhã inteira."},{"s":"I've ___ Sarah since college.","a":["known"],"h":"Conheço Sarah desde a faculdade."},{"s":"She moved here two years ___.","a":["ago"],"h":"Ela se mudou para cá há dois anos."}],"order":[{"t":["How","long","have","you","been","studying?"],"h":"Há quanto tempo você está estudando?"},{"t":["We've","known","each","other","since","college."],"h":"Nós nos conhecemos desde a faculdade."},{"t":["She's","lived","here","for","three","years."],"h":"Ela mora aqui há três anos."}],"dict":[{"t":"I've been studying English twice a week since January.","alt":["I have been studying English twice a week since January."]},{"t":"How long have you been living in this neighborhood?"},{"t":"We've known each other for more than ten years.","alt":["We have known each other for more than ten years."]},{"t":"She's been working from home since last spring.","alt":["She has been working from home since last spring."]},{"t":"I moved here two years ago, and I still like it."}],"shadow":["It was hard at first. Since then, I've met some great people at the community garden.","I've been helping there for six months. We grow vegetables and share them with our neighbors.","I am. I've been studying twice a week since January, and I can finally follow podcasts.","I have, but I still miss my old friends. I've known some of them since college."],"write":{"task":"Escreva de 5 a 7 frases contando o que mudou na sua vida nos últimos anos. Diga há quanto tempo mora onde mora, quanto tempo faz que estuda inglês e uma atividade que vem praticando recentemente. Use present perfect, present perfect continuous, for e since.","ph":"I've lived in … for … I've been studying English since … Recently, I've been …"},"cards":[["Moro aqui há quase três anos.","I've lived here for almost three years."],["Ela trabalha nessa empresa desde abril.","She's worked at that company since April."],["Há quanto tempo você está esperando?","How long have you been waiting?"],["Estou aprendendo inglês há seis meses.","I've been learning English for six months."],["Nós nos conhecemos desde a faculdade.","We've known each other since college."],["Ele está trabalhando nisso a manhã toda.","He's been working on it all morning."],["Faz tempo que você mora neste bairro?","Have you lived in this neighborhood long?"],["Eles estão tentando resolver isso desde ontem.","They've been trying to fix it since yesterday."],["Não vejo meus primos há semanas.","I haven't seen my cousins for weeks."],["Ela já está aqui há uma hora.","She's been here for an hour."]]},{"title":"Used To","goal":"Descrever hábitos e situações do passado que mudaram, usar used to em frases afirmativas, negativas e perguntas, empregar would para ações repetidas no passado e reconhecer get used to ao falar sobre adaptação a novas rotinas.","speakers":{"Lucas":"m","Daniel":"m"},"setting":"Em uma cafeteria, cedo pela manhã, Lucas encontra Daniel antes do trabalho. Os dois conversam sobre suas antigas rotinas, o transporte até o emprego, hábitos da juventude e a adaptação a novos horários.","lines":[["Lucas","You're up early today. I thought you hated getting out of bed before nine.","Você acordou cedo hoje. Achei que odiasse sair da cama antes das nove."],["Daniel","I did. I used to sleep until ten on weekends, but my new job starts at seven every morning.","Eu odiava mesmo. Antes, costumava dormir até as dez nos fins de semana, mas meu emprego novo começa às sete todas as manhãs."],["Lucas","Did you use to live far from work, before you moved?","Você morava longe do trabalho antes de se mudar?"],["Daniel","Yes. I used to live across town, and the bus ride took almost an hour on busy days.","Sim. Eu morava do outro lado da cidade, e o trajeto de ônibus levava quase uma hora nos dias movimentados."],["Lucas","How did you spend your mornings back then, before that long bus ride?","Como você passava suas manhãs naquela época, antes daquele longo trajeto de ônibus?"],["Daniel","My dad would make coffee, and we'd listen to the radio while we ate breakfast.","Meu pai costumava fazer café, e nós ouvíamos rádio enquanto tomávamos o café da manhã."],["Lucas","That sounds peaceful. Did you use to drive to work when the weather was bad?","Parece tranquilo. Você costumava ir de carro para o trabalho quando o tempo estava ruim?"],["Daniel","No, I didn't use to have a car. I took the bus every day, even when it rained.","Não, eu não tinha carro naquela época. Pegava ônibus todos os dias, mesmo quando chovia."],["Lucas","What changed when you moved closer to the office last month?","O que mudou quando você se mudou para mais perto do escritório no mês passado?"],["Daniel","Now I can walk to work. I'm still getting used to waking up before sunrise, though.","Agora posso ir a pé para o trabalho. Mas ainda estou me acostumando a acordar antes do nascer do sol."],["Lucas","I used to be a night owl too. I would stay up reading until midnight when I was in college.","Eu também era uma pessoa noturna. Costumava ficar acordado lendo até meia-noite quando estava na faculdade."],["Daniel","Do you miss those late nights, or do you prefer your routine now?","Você sente falta daquelas noites acordado até tarde ou prefere sua rotina atual?"],["Lucas","Sometimes, but I like having time for breakfast and a short walk before things get busy.","Às vezes, mas gosto de ter tempo para tomar café da manhã e dar uma caminhada antes de o dia ficar corrido."],["Daniel","Same here. I never thought I'd enjoy quiet mornings this much, but they help me feel ready for the day.","Eu também. Nunca pensei que fosse gostar tanto de manhãs tranquilas, mas elas me ajudam a começar o dia com disposição."]],"grammar":[{"h":"Used to: hábitos e situações que mudaram","p":["Usamos <b>used to + verbo na forma base</b> para falar de hábitos ou situações que existiam no passado, mas que já não fazem parte da realidade atual.","Essa estrutura é útil para comparar o passado com o presente. <b>I used to take the bus</b> indica que eu costumava pegar ônibus, mas isso mudou.","Também usamos used to para estados do passado, como morar em determinado lugar, gostar de alguma coisa ou ter certa característica. A estrutura não muda conforme a pessoa: I used to, she used to, they used to.","Em frases afirmativas, não colocamos o verbo principal no passado depois de used to."],"ex":[["I used to take the bus every day.","Eu costumava pegar ônibus todos os dias."],["She used to live near the train station.","Ela morava perto da estação de trem."],["We used to meet at the same café.","Nós costumávamos nos encontrar no mesmo café."],["I used to be very shy in high school.","Eu era muito tímido no ensino médio."]],"tip":"Diga <b>I used to live</b>, não “I used to lived”. Depois de used to, use a forma base do verbo."},{"h":"Perguntas e negativas com used to","p":["Para fazer perguntas, usamos <b>Did + pessoa + use to + verbo?</b>. Como did já indica o passado, escrevemos <b>use to</b>, sem D.","Na negativa, a forma é <b>didn't use to + verbo</b>. Ela significa que determinado hábito ou situação não existia no passado.","Compare: <b>I used to drink coffee</b> (eu costumava tomar café) e <b>I didn't use to drink coffee</b> (eu não costumava tomar café).","Nas respostas curtas, usamos did ou didn't: Yes, I did; No, I didn't."],"ex":[["Did you use to work on Saturdays?","Você costumava trabalhar aos sábados?"],["I didn't use to drink coffee.","Eu não costumava tomar café."],["He didn't use to like mornings.","Ele não gostava de manhãs antigamente."],["Where did they use to spend their summers?","Onde eles costumavam passar os verões?"]],"tip":"Em perguntas e negativas, escreva <b>use to</b>: Did you use to...? e didn't use to..."},{"h":"Would: ações que se repetiam no passado","p":["Usamos <b>would + verbo na forma base</b> para descrever ações que aconteciam repetidamente no passado, especialmente quando estamos contando lembranças.","Por exemplo, <b>My grandfather would tell us stories</b> descreve uma ação habitual. Nesse contexto, would não significa uma condição imaginária: ele indica repetição no passado.","A diferença importante é que <b>used to</b> também descreve estados antigos, enquanto <b>would</b>, com esse significado, é usado para ações repetidas.","Dizemos <b>I used to have long hair</b>, mas normalmente não usamos would para falar dessa característica. Em narrativas, would fica mais natural quando o período passado já está claro."],"ex":[["My grandfather would tell us stories after dinner.","Meu avô costumava nos contar histórias depois do jantar."],["Every summer, we'd visit our cousins by the lake.","Todo verão, visitávamos nossos primos perto do lago."],["On cold nights, we'd sit by the fire.","Nas noites frias, costumávamos sentar perto da lareira."],["I used to have long hair when I was younger.","Eu tinha cabelo comprido quando era mais jovem."]],"tip":"<b>Used to</b> serve para hábitos e estados antigos. <b>Would</b>, nesse uso, serve para ações que se repetiam."},{"h":"Get used to: reconhecer a ideia de adaptação","p":["Existe outra expressão parecida, mas com significado diferente: <b>get used to</b>. Ela significa acostumar-se a alguma coisa.","Quando alguém diz <b>I'm getting used to my new schedule</b>, quer dizer que está em processo de adaptação a um horário novo.","Depois de get used to, podemos encontrar um substantivo ou um verbo com <b>-ing</b>. Isso acontece porque o to dessa expressão é uma preposição, e não o início de um infinitivo.","Neste momento, o objetivo é reconhecer a expressão quando ela aparecer em conversas. O foco principal de produção da unidade continua sendo used to e would para hábitos antigos."],"ex":[["I'm getting used to my new schedule.","Estou me acostumando ao meu novo horário."],["It took me a while to get used to the noise.","Demorei um tempo para me acostumar com o barulho."],["She's used to getting up early.","Ela está acostumada a acordar cedo."],["We're slowly getting used to the colder weather.","Estamos nos acostumando aos poucos com o clima mais frio."]],"tip":"<b>Used to do</b> fala de um hábito antigo. <b>Get used to doing</b> significa acostumar-se a fazer alguma coisa."}],"vocab":[{"h":"Hábitos e lembranças do passado","items":[["back then","naquela época"],["in those days","naqueles tempos"],["night owl","pessoa que gosta de ficar acordada até tarde"],["stay up late","ficar acordado até tarde"],["sleep in","acordar mais tarde que o habitual"],["childhood","infância"],["old habit","hábito antigo"],["remember","lembrar-se"],["miss","sentir falta"],["high school","ensino médio"]]},{"h":"Rotina, trabalho e adaptação","items":[["routine","rotina"],["schedule","horário; programação"],["bus ride","trajeto de ônibus"],["across town","do outro lado da cidade"],["walk to work","ir a pé para o trabalho"],["before sunrise","antes do nascer do sol"],["get used to","acostumar-se a"],["get out of bed","sair da cama"],["quiet morning","manhã tranquila"],["feel ready","sentir-se preparado"]]}],"pron":[{"h":"Used to na fala americana","p":"Em <b>used to</b>, os sons se conectam, e a expressão costuma soar aproximadamente “IÚS-tâ”, com o T bem próximo da sílaba anterior. Em uma frase como I used to work here, não é necessário separar used e to ao falar.","w":["used to","I used to work","She used to live here","We used to meet"]},{"h":"Would e a contração 'd","p":"<b>Would</b> soa aproximadamente “uúd”, com o som curto de U. Na fala, pode aparecer contraído como <b>'d</b>: we'd soa aproximadamente “uíd”. O significado depende do contexto. Em lembranças, essa contração pode indicar um hábito do passado.","w":["would","we'd visit","he'd call","would make coffee"]},{"h":"Used to e use to nas perguntas","p":"Apesar da diferença na escrita, <b>used to</b> e <b>use to</b> depois de did costumam soar praticamente iguais na fala natural, aproximadamente “IÚS-tâ”. Para distinguir perguntas e afirmações, preste atenção ao auxiliar did e à ordem das palavras.","w":["I used to drive","Did you use to drive?","I didn't use to drive","Did she use to work here?"]}],"mc":[{"q":"A que horas Daniel costumava acordar nos fins de semana?","o":["Às sete da manhã","Às nove da manhã","Às dez da manhã"],"a":2,"e":"I did. I used to sleep until ten on weekends, but my new job starts at seven every morning."},{"q":"Como Daniel costumava ir para o trabalho?","o":["De ônibus","De carro","A pé"],"a":0,"e":"No, I didn't use to have a car. I took the bus every day, even when it rained."},{"q":"O que Lucas costumava fazer até meia-noite quando estava na faculdade?","o":["Assistir a filmes","Ficar acordado lendo","Conversar com os amigos"],"a":1,"e":"I used to be a night owl too. I would stay up reading until midnight when I was in college."},{"q":"A que Daniel ainda está se acostumando?","o":["Ao trajeto longo de ônibus","A trabalhar de casa","A acordar antes do nascer do sol"],"a":2,"e":"Now I can walk to work. I'm still getting used to waking up before sunrise, though."}],"gaps":[{"s":"I ___ to sleep until ten on weekends.","a":["used"],"h":"Eu costumava dormir até as dez nos fins de semana."},{"s":"Did you ___ to live across town?","a":["use"],"h":"Você morava do outro lado da cidade antigamente?"},{"s":"She didn't ___ to drink coffee.","a":["use"],"h":"Ela não costumava tomar café."},{"s":"Every summer, my grandmother ___ tell us stories. (Use would.)","a":["would"],"h":"Todo verão, minha avó costumava nos contar histórias."},{"s":"I ___ use to enjoy early mornings. (Use the negative with did.)","a":["didn't","did not"],"h":"Eu não costumava gostar de acordar cedo."},{"s":"___ you use to take the train?","a":["Did"],"h":"Você costumava pegar o trem?"}],"order":[{"t":["I","used","to","skip","breakfast","before","work."],"h":"Eu costumava pular o café da manhã antes do trabalho."},{"t":["Did","you","use","to","live","downtown?"],"h":"Você morava no centro antigamente?"},{"t":["My","grandfather","would","tell","funny","stories."],"h":"Meu avô costumava contar histórias engraçadas."}],"dict":[{"t":"I used to take the bus, but now I walk to work."},{"t":"Did you use to live far from the city center?"},{"t":"My grandfather would tell us stories after dinner."},{"t":"I didn't use to enjoy waking up so early.","alt":["I did not use to enjoy waking up so early."]},{"t":"I'm still getting used to my new routine.","alt":["I am still getting used to my new routine."]}],"shadow":["I did. I used to sleep until ten on weekends, but my new job starts at seven every morning.","My dad would make coffee, and we'd listen to the radio while we ate breakfast.","Now I can walk to work. I'm still getting used to waking up before sunrise, though.","I used to be a night owl too. I would stay up reading until midnight when I was in college."],"write":{"task":"Escreva de 5 a 7 frases comparando sua rotina atual com a de cinco ou dez anos atrás. Conte onde morava, quais hábitos tinha e o que costumava fazer nos fins de semana. Use used to pelo menos três vezes e would para descrever uma ação que se repetia.","ph":"Five years ago, I used to … I didn't use to … On weekends, I would … But now, I …"},"cards":[["Eu costumava pular o café da manhã, mas não faço mais isso.","I used to skip breakfast, but not anymore."],["Você costumava trabalhar nos fins de semana?","Did you use to work on weekends?"],["Nós morávamos em um apartamento bem menor.","We used to live in a much smaller apartment."],["Minha tia costumava fazer pão todo domingo.","My aunt would bake bread every Sunday."],["Eu não costumava gostar de caminhadas longas.","I didn't use to enjoy long walks."],["Ele tinha medo de cachorros antigamente.","He used to be afraid of dogs."],["Todo inverno, visitávamos meus avós.","Every winter, we'd visit my grandparents."],["Eu costumava ir dormir depois da meia-noite.","I used to go to bed after midnight."],["Ela não costumava pegar o trem.","She didn't use to take the train."],["Estou me acostumando às reuniões de manhã cedo.","I'm getting used to the early meetings."]]},{"title":"Before That","goal":"Contar acontecimentos do passado em sequência, indicar o que já havia acontecido antes de outro evento usando past perfect, formular perguntas e negativas com had e organizar relatos com before, after e by the time.","speakers":{"Emma":"f","Lucas":"m"},"setting":"Durante o intervalo do almoço no escritório, Emma pergunta a Lucas como foi uma apresentação importante realizada no dia anterior. Ele conta como um carregador esquecido quase causou problemas e explica o que a equipe havia preparado para evitar imprevistos.","lines":[["Emma","How did your presentation go yesterday afternoon? You seemed pretty worried about it when we talked.","Como foi sua apresentação ontem à tarde? Você parecia bastante preocupado quando conversamos."],["Lucas","Better than I expected, but the morning was a mess from the moment I left home.","Melhor do que eu esperava, mas a manhã foi uma confusão desde o momento em que saí de casa."],["Emma","What happened? Had you finished the slides the night before, like you planned?","O que aconteceu? Você tinha terminado os slides na noite anterior, como planejou?"],["Lucas","Yes, I'd saved them on my laptop, but I'd forgotten the charger at home.","Sim, eu tinha salvado os slides no notebook, mas havia esquecido o carregador em casa."],["Emma","Oh no. Did you notice before you left, or only when you got to work?","Nossa. Você percebeu antes de sair ou só quando chegou ao trabalho?"],["Lucas","No. By the time I got to the office, my battery had almost died, and I started to panic.","Não. Quando cheguei ao escritório, minha bateria já estava quase acabando, e comecei a entrar em pânico."],["Emma","So how did you give the presentation without your own computer?","Então como você fez a apresentação sem seu próprio computador?"],["Lucas","Luckily, Daniel had already emailed a copy of the slides to our manager the previous evening.","Por sorte, Daniel já tinha enviado uma cópia dos slides por e-mail ao nosso gerente na noite anterior."],["Emma","Good thinking. Had you asked him to do that, just in case?","Boa ideia. Você tinha pedido para ele fazer isso por precaução?"],["Lucas","I had. After we'd checked everything together, I asked him to send a backup to our manager.","Sim. Depois que tínhamos conferido tudo juntos, pedi que ele enviasse uma cópia de segurança ao nosso gerente."],["Emma","And did the meeting start on time, or did you have to delay it?","E a reunião começou na hora ou vocês precisaram adiá-la?"],["Lucas","It did. By the time everyone arrived, we'd connected another laptop and opened the file.","Começou na hora. Quando todo mundo chegou, já tínhamos conectado outro notebook e aberto o arquivo."],["Emma","So all that preparation paid off. I bet you felt relieved.","Então toda aquela preparação valeu a pena. Aposto que você ficou aliviado."],["Lucas","Definitely. Before that morning, I'd never understood why backups matter so much.","Com certeza. Antes daquela manhã, eu nunca tinha entendido por que cópias de segurança são tão importantes."]],"grammar":[{"h":"Past perfect: o passado anterior a outro passado","p":["Usamos o <b>past perfect</b> para mostrar que uma ação aconteceu antes de outra ação ou momento no passado. A estrutura é <b>had + particípio passado</b>.","Imagine dois acontecimentos: primeiro Lucas salvou os slides; depois saiu de casa. Ao contar a história a partir do momento em que saiu, podemos dizer: <b>He had saved the slides before he left</b>.","O past perfect ajuda a esclarecer a ordem dos acontecimentos. O past simple normalmente apresenta o acontecimento principal, enquanto o past perfect identifica o que já havia acontecido.","O auxiliar <b>had</b> é igual para todas as pessoas: I had, she had, we had. Na fala, frequentemente aparece contraído como <b>'d</b>."],"ex":[["I had saved the file before I left.","Eu tinha salvado o arquivo antes de sair."],["She'd already checked the room when I arrived.","Ela já tinha conferido a sala quando cheguei."],["They hadn't finished the report by noon.","Eles não tinham terminado o relatório até o meio-dia."],["We had forgotten the keys at home.","Nós tínhamos esquecido as chaves em casa."]],"tip":"A estrutura é <b>had + particípio passado</b>. Não diga “I had forgot”; use <b>I had forgotten</b>."},{"h":"Perguntas e negativas com had","p":["Para fazer perguntas no past perfect, colocamos <b>had</b> antes da pessoa: Had you finished?, Had she left?","Para formar a negativa, usamos <b>had not</b> ou a contração <b>hadn't</b>, seguidas do particípio passado.","Nas respostas curtas, podemos usar Yes, I had ou No, I hadn't. Não é necessário repetir o verbo principal.","É comum encontrar <b>already</b> (já), <b>never</b> (nunca) e <b>yet</b> (ainda) com o past perfect. Already e never normalmente ficam entre had e o particípio; yet costuma aparecer no final de negativas e perguntas."],"ex":[["Had you printed the documents before the meeting?","Você tinha impresso os documentos antes da reunião?"],["Yes, I had. I'd printed them the night before.","Sim. Eu tinha impresso na noite anterior."],["Had she left when you called?","Ela já tinha saído quando você ligou?"],["No, she hadn't left yet.","Não, ela ainda não tinha saído."]],"tip":"Nas perguntas com past perfect, use <b>Had you finished?</b>, não “Did you had finished?”."},{"h":"Before e after: organizar a sequência","p":["<b>Before</b> significa antes de ou antes que. <b>After</b> significa depois de ou depois que. Essas palavras ajudam a organizar os acontecimentos de uma história.","Podemos usar o past perfect para destacar qual ação aconteceu primeiro: <b>After we'd checked the slides, we went home</b>. Primeiro conferimos os slides; depois fomos para casa.","Quando before ou after já deixa a ordem dos acontecimentos clara, também é possível usar o past simple nas duas partes. O past perfect é especialmente útil quando queremos enfatizar que uma ação já estava concluída.","Podemos começar a frase por before ou after, usando vírgula para separar a oração inicial da principal, ou colocar essas palavras no meio da frase."],"ex":[["After we'd checked the slides, we went home.","Depois que tínhamos conferido os slides, fomos para casa."],["Before the meeting started, I'd read the report.","Antes de a reunião começar, eu já tinha lido o relatório."],["He called me after he'd seen the message.","Ele me ligou depois de ter visto a mensagem."],["We left before the rain started.","Saímos antes de a chuva começar."]],"tip":"O past perfect deixa a ação anterior mais explícita, mas <b>before</b> e <b>after</b> também podem aparecer com past simple."},{"h":"By the time: quando algo já tinha acontecido","p":["<b>By the time</b> significa quando ou até o momento em que. Usamos essa expressão para indicar que uma ação já havia acontecido até determinado momento.","Um padrão muito frequente é <b>By the time + past simple, past perfect</b>. Por exemplo: By the time I arrived, the meeting had started.","Nesse exemplo, a reunião começou primeiro. Depois, eu cheguei. O past perfect destaca que o início da reunião já estava no passado quando cheguei.","A ordem das partes pode mudar: <b>The meeting had started by the time I arrived</b> mantém o mesmo significado.","Não confunda by the time com at the time. By the time destaca um limite temporal; at the time significa naquela época ou naquele momento."],"ex":[["By the time I arrived, the meeting had started.","Quando cheguei, a reunião já tinha começado."],["By the time she got home, we'd finished dinner.","Quando ela chegou em casa, já tínhamos terminado o jantar."],["They had left by the time we reached the station.","Eles já tinham saído quando chegamos à estação."],["By the time the store opened, a line had formed.","Quando a loja abriu, já havia se formado uma fila."]],"tip":"Com <b>by the time</b>, pergunte-se: o que já tinha acontecido naquele momento? Essa ação frequentemente aparece no past perfect."}],"vocab":[{"h":"Problemas e preparação no trabalho","items":[["presentation","apresentação"],["slide","slide; página de apresentação"],["laptop","notebook; computador portátil"],["charger","carregador"],["battery","bateria"],["backup","cópia de segurança"],["save a file","salvar um arquivo"],["check","verificar; conferir"],["delay a meeting","adiar uma reunião"],["manager","gerente"]]},{"h":"Sequência e acontecimentos","items":[["before","antes de; antes que"],["after","depois de; depois que"],["by the time","quando; até o momento em que"],["already","já"],["the night before","na noite anterior"],["the previous evening","na noite anterior"],["just in case","por precaução; para garantir"],["luckily","por sorte"],["on time","na hora; pontualmente"],["pay off","valer a pena; dar resultado"]]},{"h":"Reações e imprevistos","items":[["panic","entrar em pânico; pânico"],["feel relieved","sentir-se aliviado"],["a mess","uma confusão; uma bagunça"],["matter","ser importante; fazer diferença"],["notice","perceber"],["expect","esperar; ter expectativa"]]}],"pron":[{"h":"Had e a contração 'd","p":"O auxiliar <b>had</b> frequentemente vira <b>'d</b> na fala. <b>I'd saved</b> soa aproximadamente “áid sêivd”, com um D final ligado à palavra seguinte. O contexto e o particípio passado ajudam a reconhecer o past perfect.","w":["I'd saved","She'd checked","We'd finished","They'd left"]},{"h":"Hadn't e as negativas","p":"<b>Hadn't</b> soa aproximadamente “HÉ-dânt”, com a primeira sílaba mais forte e o T final muitas vezes pouco destacado na fala americana. Ao praticar, mantenha a negativa clara para não confundir had com hadn't.","w":["hadn't","I hadn't finished","She hadn't left","We hadn't noticed"]},{"h":"By the time e a ligação entre palavras","p":"Em <b>by the time</b>, a pronúncia aproximada é “bái dhâ táim”. O TH de the é produzido com a língua perto dos dentes superiores. As três palavras se conectam naturalmente, e time costuma receber mais destaque.","w":["by the time","by the time I arrived","before the meeting","after we'd finished"]}],"mc":[{"q":"O que Lucas havia esquecido em casa?","o":["O carregador do notebook","Os slides da apresentação","Os documentos da reunião"],"a":0,"e":"Yes, I'd saved them on my laptop, but I'd forgotten the charger at home."},{"q":"Como estava a bateria quando Lucas chegou ao escritório?","o":["Totalmente carregada","Quase acabando","Carregando normalmente"],"a":1,"e":"No. By the time I got to the office, my battery had almost died, and I started to panic."},{"q":"O que Daniel já havia feito na noite anterior?","o":["Comprado um carregador novo","Adiado a reunião","Enviado uma cópia dos slides ao gerente"],"a":2,"e":"Luckily, Daniel had already emailed a copy of the slides to our manager the previous evening."},{"q":"O que já estava pronto quando todos chegaram à reunião?","o":["Outro notebook estava conectado e o arquivo aberto","Uma nova apresentação havia sido escrita","O notebook de Lucas estava totalmente carregado"],"a":0,"e":"It did. By the time everyone arrived, we'd connected another laptop and opened the file."}],"gaps":[{"s":"I ___ saved the file before I left.","a":["had","'d"],"h":"Eu tinha salvado o arquivo antes de sair."},{"s":"She ___ finished the report by noon. (Use the negative.)","a":["hadn't","had not"],"h":"Ela não tinha terminado o relatório até o meio-dia."},{"s":"___ you printed the documents before the meeting?","a":["Had"],"h":"Você tinha impresso os documentos antes da reunião?"},{"s":"By the ___ we arrived, the meeting had started.","a":["time"],"h":"Quando chegamos, a reunião já tinha começado."},{"s":"After we'd checked the slides, we ___ home.","a":["went"],"h":"Depois que tínhamos conferido os slides, fomos para casa."},{"s":"He had ___ his keys on the kitchen table.","a":["left"],"h":"Ele tinha deixado as chaves sobre a mesa da cozinha."}],"order":[{"t":["I","had","finished","before","you","arrived."],"h":"Eu tinha terminado antes de você chegar."},{"t":["Had","she","already","left","the","office?"],"h":"Ela já tinha saído do escritório?"},{"t":["After","we'd","eaten,","we","went","home."],"h":"Depois que tínhamos comido, fomos para casa."}],"dict":[{"t":"I had forgotten my charger at home.","alt":["I'd forgotten my charger at home."]},{"t":"Had you checked the slides before the meeting?"},{"t":"By the time we arrived, the movie had started."},{"t":"She hadn't saved the file before the computer shut down.","alt":["She had not saved the file before the computer shut down."]},{"t":"After we'd finished our work, we went out for lunch.","alt":["After we had finished our work, we went out for lunch."]}],"shadow":["Yes, I'd saved them on my laptop, but I'd forgotten the charger at home.","No. By the time I got to the office, my battery had almost died, and I started to panic.","I had. After we'd checked everything together, I asked him to send a backup to our manager.","Definitely. Before that morning, I'd never understood why backups matter so much."],"write":{"task":"Conte um imprevisto que aconteceu em um dia de trabalho, estudo ou viagem. Escreva de 6 a 8 frases explicando o que você já tinha preparado, o que esqueceu ou deixou de fazer, o que aconteceu depois e como resolveu a situação. Use past perfect pelo menos três vezes e inclua before, after e by the time.","ph":"Last week, I had … before … Unfortunately, I hadn't … By the time I arrived, … After I'd …, I …"},"cards":[["Eu já tinha comido quando você ligou.","I had already eaten when you called."],["Ela tinha saído antes de a reunião começar.","She'd left before the meeting started."],["Você tinha lido o e-mail antes do almoço?","Had you read the email before lunch?"],["Nós não tínhamos reservado uma mesa com antecedência.","We hadn't booked a table in advance."],["Quando cheguei lá, todo mundo já tinha ido embora.","By the time I got there, everyone had left."],["Depois que conversamos, me senti melhor.","After we'd talked, I felt better."],["Ele tinha esquecido de trazer a carteira.","He'd forgotten to bring his wallet."],["Antes daquela viagem, eu nunca tinha voado sozinho.","Before that trip, I'd never flown alone."],["Eles tinham terminado antes do prazo.","They had finished before the deadline."],["Quando ela acordou, já tinha parado de chover.","By the time she woke up, it had stopped raining."]]},{"title":"If I Had More Time","goal":"Distinguir possibilidades reais de situações imaginárias, revisar o first conditional, usar o second conditional para falar de desejos e dar conselhos e expressar condições com unless.","speakers":{"Sarah":"f","Lucas":"m"},"setting":"Na sexta-feira à tarde, Sarah e Lucas planejam uma feira comunitária para o sábado. Eles conversam sobre a previsão do tempo, o orçamento e o que fariam se tivessem mais recursos.","lines":[["Sarah","Have you checked the weather for tomorrow's community fair?","Você conferiu a previsão do tempo para a feira comunitária de amanhã?"],["Lucas","Yes. If it rains, we'll move the tables into the community center.","Sim. Se chover, vamos levar as mesas para o centro comunitário."],["Sarah","Good plan. But what if the center is already booked?","Boa ideia. Mas e se o centro já estiver reservado?"],["Lucas","Unless it's booked, we can use the main room. I've already called the manager.","A menos que esteja reservado, podemos usar o salão principal. Já liguei para o responsável."],["Sarah","Great. If I had more time, I'd make signs for every food stand.","Ótimo. Se eu tivesse mais tempo, faria placas para todas as barracas de comida."],["Lucas","I'd help you, but I have to pick up the chairs after work.","Eu ajudaria, mas preciso buscar as cadeiras depois do trabalho."],["Sarah","If we had a bigger budget, we could hire a local band, too.","Se tivéssemos um orçamento maior, também poderíamos contratar uma banda local."],["Lucas","True, but people will still have fun if we play music ourselves.","Verdade, mas as pessoas ainda vão se divertir se nós mesmos colocarmos música."],["Sarah","What would you do if you were in charge of the whole event?","O que você faria se fosse responsável pelo evento inteiro?"],["Lucas","I'd invite more volunteers and start planning a month earlier.","Eu convidaria mais voluntários e começaria a planejar um mês antes."],["Sarah","Four neighbors said they might come, but only two have confirmed so far.","Quatro vizinhos disseram que talvez venham, mas só dois confirmaram até agora."],["Lucas","If the others reply tonight, I'll give everyone a clear task list tomorrow.","Se os outros responderem hoje à noite, vou passar uma lista clara de tarefas para todos amanhã."],["Sarah","That makes sense. We won't finish on time unless everyone arrives by eight.","Faz sentido. Não vamos terminar a tempo se todo mundo não chegar até as oito."],["Lucas","I'll send a reminder tonight. If everyone helps, we'll be ready before ten.","Vou mandar um lembrete hoje à noite. Se todos ajudarem, estaremos prontos antes das dez."],["Sarah","And if I were you, I'd bring an extra umbrella, just in case.","E, se eu fosse você, levaria um guarda-chuva extra, por precaução."],["Lucas","Good idea! Even if it rains, I think tomorrow will be a great day.","Boa ideia! Mesmo que chova, acho que amanhã vai ser um ótimo dia."]],"grammar":[{"h":"First conditional: uma possibilidade real","p":["O <b>first conditional</b> fala de uma condição possível no presente ou no futuro e de seu resultado provável. A estrutura mais comum é <b>if + present simple, will + verbo na forma base</b>.","A condição aparece no presente mesmo quando se refere ao futuro: <b>If it rains tomorrow</b>, e não “If it will rain tomorrow”. O resultado pode vir com will, ou com outro verbo modal adequado ao contexto.","Podemos inverter a ordem: <b>We'll move inside if it rains</b>. Quando a oração com if vem primeiro, normalmente usamos vírgula para separar as duas partes."],"ex":[["If it rains, we'll move inside.","Se chover, vamos para um lugar coberto."],["You'll feel better if you get some rest.","Você vai se sentir melhor se descansar um pouco."],["If Sarah calls, I'll answer right away.","Se Sarah ligar, vou atender na hora."],["If the volunteers arrive early, we'll have time to decorate.","Se os voluntários chegarem cedo, teremos tempo para decorar."]],"tip":"Para um futuro possível, use <b>if + presente</b>; normalmente não coloque will depois de if."},{"h":"Second conditional: situações imaginárias","p":["O <b>second conditional</b> descreve situações imaginárias, improváveis ou diferentes da realidade atual. A estrutura é <b>if + past simple, would + verbo na forma base</b>.","Apesar da forma de passado depois de if, a frase geralmente fala do presente ou do futuro imaginado. <b>If I had more time, I'd volunteer</b> indica que, na realidade, não tenho tempo suficiente.","<b>Would</b> pode virar <b>'d</b>. Para falar de uma possibilidade, também podemos usar <b>could</b>: If we had more money, we could hire a band."],"ex":[["If I had a car, I'd drive there.","Se eu tivesse carro, iria para lá dirigindo."],["She would travel more if she had free time.","Ela viajaria mais se tivesse tempo livre."],["If we lived closer, we could meet every week.","Se morássemos mais perto, poderíamos nos encontrar toda semana."],["If I knew her number, I'd call her myself.","Se eu soubesse o número dela, ligaria pessoalmente."]],"tip":"<b>If I have time, I'll help</b> é uma possibilidade real; <b>If I had time, I'd help</b> imagina uma situação diferente da atual."},{"h":"If I were you: conselhos e perguntas hipotéticas","p":["A expressão <b>If I were you, I'd...</b> é uma forma comum e educada de aconselhar alguém: “Se eu fosse você, eu...”. Em situações hipotéticas, <b>were</b> é a forma tradicional com I, he e she.","Para perguntar o que outra pessoa faria numa situação imaginária, use <b>What would you do if...?</b>.","No second conditional, a pergunta conserva a forma de passado na oração com if e usa would na oração principal."],"ex":[["If I were you, I'd check the forecast.","Se eu fosse você, conferiria a previsão."],["What would you do if you lost your phone?","O que você faria se perdesse seu celular?"],["If he were here, he'd know what to do.","Se ele estivesse aqui, saberia o que fazer."],["If I were in charge, I'd ask for more help.","Se eu estivesse no comando, pediria mais ajuda."]],"tip":"Para dar conselhos, prefira a fórmula <b>If I were you, I'd...</b>."},{"h":"Unless: a menos que","p":["<b>Unless</b> significa <b>a menos que</b> e equivale, em muitos contextos, a <b>if... not</b>. É útil para explicar a condição que pode impedir um resultado.","Compare: <b>We won't finish unless everyone helps</b> e <b>We won't finish if everyone doesn't help</b>. A primeira opção costuma ser mais natural para expressar essa ideia.","Como nas condições reais com if, depois de unless usamos normalmente o presente para falar de uma condição futura. Evite acrescentar outra negativa à oração com unless se ela inverter o sentido desejado."],"ex":[["We won't go unless the weather improves.","Não vamos sair a menos que o tempo melhore."],["Unless you hurry, you'll miss the bus.","Se você não se apressar, vai perder o ônibus."],["I'll bring the chairs unless you already have some.","Vou levar as cadeiras, a menos que você já tenha algumas."],["Unless the organizer agrees, we can't change the schedule.","A menos que o organizador concorde, não podemos mudar o horário."]],"tip":"<b>Unless</b> já traz a ideia de “se não”: unless it rains = se não chover."}],"vocab":[{"h":"Eventos e organização","items":[["community fair","feira comunitária"],["food stand","barraca de comida"],["volunteer","voluntário; fazer trabalho voluntário"],["budget","orçamento"],["hire a band","contratar uma banda"],["be in charge of","ser responsável por"],["community center","centro comunitário"],["reminder","lembrete"],["sign","placa; cartaz"],["book a room","reservar uma sala"]]},{"h":"Condições e decisões","items":[["if","se"],["unless","a menos que"],["even if","mesmo que"],["in case","caso; para o caso de"],["just in case","por precaução"],["forecast","previsão do tempo"],["extra","extra; adicional"],["on time","na hora certa; dentro do prazo"],["make sense","fazer sentido"]]}],"pron":[{"h":"Would e I'd","p":"<b>Would</b> soa aproximadamente “uúd”. Em <b>I'd</b>, contração de I would, ouvimos aproximadamente “áid”. O D se conecta à palavra seguinte: I'd help soa parecido com “áid hélp”.","w":["would","I'd help","we'd organize","she'd join"]},{"h":"If I were you","p":"Na expressão <b>If I were you</b>, o R de were é pronunciado no inglês americano: aproximadamente “if ai uâr iú”. Pratique a frase inteira, sem separar demais as palavras.","w":["were","If I were you","If I were there"]},{"h":"Unless e o som inicial","p":"<b>Unless</b> soa aproximadamente “ân-LÉS”, com a segunda sílaba mais forte. O começo é uma vogal fraca, não o som de U de “uva” em português.","w":["unless","unless it rains","unless you call","unless everyone helps"]}],"mc":[{"q":"O que Lucas planeja fazer se chover durante a feira?","o":["Cancelar o evento","Levar as mesas para o centro comunitário","Alugar uma tenda"],"a":1,"e":"Yes. If it rains, we'll move the tables into the community center."},{"q":"O que Sarah faria se tivesse mais tempo?","o":["Prepararia placas para as barracas","Compraria mais cadeiras","Convidaria uma banda"],"a":0,"e":"Great. If I had more time, I'd make signs for every food stand."},{"q":"O que Lucas faria se fosse responsável por todo o evento?","o":["Mudaria o evento de cidade","Cobraria entrada","Convidaria mais voluntários e planejaria antes"],"a":2,"e":"I'd invite more volunteers and start planning a month earlier."},{"q":"Até que horas os voluntários precisam chegar para terminarem a tempo?","o":["Até as dez","Até as oito","Até as nove"],"a":1,"e":"That makes sense. We won't finish on time unless everyone arrives by eight."}],"gaps":[{"s":"If I ___ more free time, I'd volunteer every weekend.","a":["had"],"h":"Se eu tivesse mais tempo livre, faria trabalho voluntário todo fim de semana."},{"s":"If it ___ tomorrow, we'll move the event indoors. (Use rain.)","a":["rains"],"h":"Se chover amanhã, levaremos o evento para um lugar fechado."},{"s":"If I were you, I ___ bring a jacket. (Use would.)","a":["would","'d"],"h":"Se eu fosse você, levaria uma jaqueta."},{"s":"We won't cancel the fair ___ the organizer tells us to.","a":["unless"],"h":"Não cancelaremos a feira a menos que o organizador peça."},{"s":"What ___ you do if you won a free trip?","a":["would"],"h":"O que você faria se ganhasse uma viagem grátis?"},{"s":"If everyone helps, we ___ finish before noon. (Use will.)","a":["will","'ll"],"h":"Se todos ajudarem, terminaremos antes do meio-dia."}],"order":[{"t":["If","it","rains,","we'll","stay","inside."],"h":"Se chover, vamos ficar em um lugar fechado."},{"t":["If","I","had","time,","I'd","help."],"h":"Se eu tivesse tempo, ajudaria."},{"t":["Unless","you","hurry,","you'll","be","late."],"h":"Se você não se apressar, vai se atrasar."}],"dict":[{"t":"If it rains tomorrow, we'll move the tables inside.","alt":["If it rains tomorrow, we will move the tables inside."]},{"t":"If I had more time, I'd organize another event.","alt":["If I had more time, I would organize another event."]},{"t":"What would you do if you were in charge?"},{"t":"We won't finish unless everyone helps.","alt":["We will not finish unless everyone helps."]},{"t":"If I were you, I'd check the weather forecast.","alt":["If I were you, I would check the weather forecast."]}],"shadow":["Yes. If it rains, we'll move the tables into the community center.","Great. If I had more time, I'd make signs for every food stand.","What would you do if you were in charge of the whole event?","That makes sense. We won't finish on time unless everyone arrives by eight."],"write":{"task":"Escreva de 5 a 7 frases sobre um projeto que você gostaria de realizar. Diga o que fará se tiver a oportunidade, o que faria se tivesse mais tempo ou dinheiro e o que não fará a menos que uma condição seja atendida. Use first conditional, second conditional e unless.","ph":"If I have time next month, I'll … If I had more money, I'd … I won't … unless …"},"cards":[["Se estiver frio, vamos ficar em casa.","If it's cold, we'll stay home."],["Se eu ganhasse mais, viajaria todo ano.","If I earned more, I'd travel every year."],["O que você faria no meu lugar?","What would you do in my situation?"],["Se eu fosse você, pediria ajuda.","If I were you, I'd ask for help."],["Não vou comprar os ingressos a menos que você confirme.","I won't buy the tickets unless you confirm."],["Se tivéssemos um jardim, cultivaríamos tomates.","If we had a garden, we'd grow tomatoes."],["Eu te aviso se a reunião mudar.","I'll let you know if the meeting changes."],["Ele aceitaria se o horário fosse melhor.","He'd accept if the schedule were better."],["Você vai perder a promoção se não se inscrever.","You'll miss the discount if you don't sign up."],["A menos que seja urgente, podemos conversar amanhã.","Unless it's urgent, we can talk tomorrow."]]},{"title":"Made in Brazil","goal":"Descrever como e onde produtos são feitos, identificar informações importantes em etiquetas e reportagens, usar a voz passiva no presente e no passado e indicar quem realizou uma ação com by.","speakers":{"Emma":"f","Daniel":"m"},"setting":"Em uma feira de design local, Emma visita a barraca de Daniel, que vende bolsas de tecido produzidas por uma pequena oficina brasileira. Ela pergunta sobre a fabricação, os materiais e a origem dos desenhos.","lines":[["Emma","These bags look great. Are they made here in Brazil?","Essas bolsas são lindas. Elas são feitas aqui no Brasil?"],["Daniel","Yes, they're made in Brazil, and the fabric is dyed by a small team in Minas Gerais.","Sim, são feitas no Brasil, e o tecido é tingido por uma pequena equipe em Minas Gerais."],["Emma","That's interesting. Are the bags sewn by hand or by machine?","Que interessante. As bolsas são costuradas à mão ou à máquina?"],["Daniel","The pieces are cut by hand, but they're sewn with machines in our workshop.","As peças são cortadas à mão, mas são costuradas com máquinas na nossa oficina."],["Emma","I love this blue one. Was it made recently?","Adorei esta azul. Ela foi feita recentemente?"],["Daniel","It was finished last week, and every seam was checked before the fair.","Ela foi finalizada na semana passada, e cada costura foi conferida antes da feira."],["Emma","Who designed the pattern? The colors work really well together.","Quem criou a estampa? As cores combinam muito bem."],["Daniel","The pattern was designed by my sister. She gets ideas from places we visit.","A estampa foi criada pela minha irmã. Ela tira ideias dos lugares que visitamos."],["Emma","And are these tags printed locally, too?","E essas etiquetas também são impressas aqui na região?"],["Daniel","They are. They're printed nearby and made from recycled paper.","Sim. Elas são impressas aqui perto e feitas de papel reciclado."],["Emma","Are the bags packaged here, or is that done somewhere else?","As bolsas são embaladas aqui ou isso é feito em outro lugar?"],["Daniel","They're wrapped at the workshop, and the boxes were designed by a local artist.","Elas são embaladas na oficina, e as caixas foram criadas por uma artista local."],["Emma","I bought a bag online once, but its strap broke after two days.","Uma vez comprei uma bolsa pela internet, mas a alça quebrou depois de dois dias."],["Daniel","That's frustrating. Here, each strap is tested before a bag is sold.","Que chato. Aqui, cada alça é testada antes de a bolsa ser vendida."],["Emma","Good to know. Is the care information included with the bag?","Bom saber. As instruções de cuidado vêm junto com a bolsa?"],["Daniel","Yes, it's printed inside. And if you have a problem, just contact us.","Sim, elas estão impressas na parte de dentro. E, se tiver algum problema, é só falar com a gente."]],"grammar":[{"h":"Voz ativa e passiva: mudar o foco da frase","p":["Na <b>voz ativa</b>, normalmente destacamos quem faz a ação: <b>My sister designed the pattern</b>. Na <b>voz passiva</b>, destacamos a pessoa ou coisa que recebe a ação: <b>The pattern was designed by my sister</b>.","A estrutura básica da voz passiva é <b>be + particípio passado</b>. O verbo be muda de acordo com o tempo verbal e o sujeito: is made, are made, was made, were made.","A voz passiva é comum para falar de fabricação, processos, notícias e serviços, especialmente quando o resultado é mais importante do que a pessoa que fez a ação."],"ex":[["My sister designed the pattern.","Minha irmã criou a estampa."],["The pattern was designed by my sister.","A estampa foi criada pela minha irmã."],["Workers make these bags in Brazil.","Trabalhadores fazem essas bolsas no Brasil."],["These bags are made in Brazil.","Essas bolsas são feitas no Brasil."]],"tip":"Depois de <b>be</b>, use o particípio: made, written, built, sold. Quando as formas forem diferentes, não use o passado simples."},{"h":"Passiva no presente: am, is, are + particípio","p":["Usamos <b>am/is/are + particípio passado</b> quando descrevemos processos, características de produção ou ações habituais no presente.","Com sujeito singular, geralmente usamos <b>is</b>: The fabric is dyed locally. Com sujeito plural, usamos <b>are</b>: The bags are sold online.","Nas perguntas, invertemos o verbo be e o sujeito: <b>Are these bags made here?</b>. Nas negativas, usamos isn't ou aren't antes do particípio."],"ex":[["The fabric is dyed locally.","O tecido é tingido na região."],["These bags are sold online.","Essas bolsas são vendidas pela internet."],["Are the labels printed here?","As etiquetas são impressas aqui?"],["The handles aren't made of leather.","As alças não são feitas de couro."]],"tip":"Não diga “These bags are make”. O correto é <b>are made</b>, com particípio."},{"h":"Passiva no passado: was, were + particípio","p":["Para ações concluídas no passado, formamos a passiva com <b>was/were + particípio passado</b>.","Use <b>was</b> com sujeito singular (the bag was finished) e <b>were</b> com sujeito plural (the bags were checked).","Nas perguntas, coloque was ou were antes do sujeito. Para negar, use wasn't ou weren't. Marcadores como yesterday e last week ajudam a situar a ação no passado."],"ex":[["The bag was finished last week.","A bolsa foi finalizada na semana passada."],["The seams were checked yesterday.","As costuras foram conferidas ontem."],["Was the order shipped on Monday?","O pedido foi enviado na segunda-feira?"],["The boxes weren't damaged during delivery.","As caixas não foram danificadas durante a entrega."]],"tip":"Não misture presente e passado: <b>is made</b> = é feito; <b>was made</b> = foi feito."},{"h":"By + agente: dizer quem fez a ação","p":["Usamos <b>by + agente</b> quando queremos informar quem realizou a ação na voz passiva: The pattern was designed <b>by my sister</b>.","Muitas frases passivas não mencionam o agente, porque ele é desconhecido, evidente ou pouco importante. <b>The bags are made in Brazil</b> já informa o principal sobre a origem.","Não confunda <b>by</b> (por quem a ação foi feita) com <b>in</b> (lugar onde algo é feito) e <b>with</b> (instrumento ou recurso usado)."],"ex":[["The logo was created by a local artist.","O logotipo foi criado por uma artista local."],["The bags are made in a small workshop.","As bolsas são feitas em uma oficina pequena."],["The material is cut with special tools.","O material é cortado com ferramentas especiais."],["The instructions were written by Daniel.","As instruções foram escritas por Daniel."]],"tip":"Use <b>by</b> para o responsável, <b>in</b> para o lugar e <b>with</b> para ferramentas e instrumentos."}],"vocab":[{"h":"Produtos e produção","items":[["workshop","oficina; ateliê"],["fabric","tecido"],["pattern","estampa; padrão"],["seam","costura"],["strap","alça"],["label","etiqueta"],["recycled paper","papel reciclado"],["material","material"],["handmade","feito à mão"],["leather","couro"]]},{"h":"Processos e controle de qualidade","items":[["make / made / made","fazer / fez / feito"],["sew / sewed / sewn","costurar / costurou / costurado"],["cut / cut / cut","cortar / cortou / cortado"],["dye / dyed / dyed","tingir / tingiu / tingido"],["design / designed / designed","criar um desenho / criou / criado"],["print / printed / printed","imprimir / imprimiu / impresso"],["check / checked / checked","conferir / conferiu / conferido"],["test / tested / tested","testar / testou / testado"],["ship / shipped / shipped","enviar / enviou / enviado"],["sell / sold / sold","vender / vendeu / vendido"]]}],"pron":[{"h":"Is made e was made","p":"Na fala americana, <b>is made</b> soa aproximadamente “iz mêid” e <b>was made</b> soa “uâz mêid”. Ouça principalmente a primeira palavra: ela informa se a frase está no presente ou no passado.","w":["is made","was made","is sold","was sold"]},{"h":"Were e are nas formas plurais","p":"<b>Are</b> tem R americano, aproximadamente “âr”; <b>were</b> soa “uâr”. Em <b>are printed</b> e <b>were printed</b>, procure ouvir essa diferença para identificar o tempo verbal.","w":["are made","were made","are printed","were printed"]},{"h":"Particípios terminados em -ed","p":"O final <b>-ed</b> não é sempre pronunciado como uma sílaba extra. <b>Checked</b> termina com som de T, aproximadamente “tchékt”; <b>designed</b> termina com D, aproximadamente “di-ZÁIND”.","w":["checked","designed","finished","printed"]}],"mc":[{"q":"Onde as bolsas de Daniel são feitas?","o":["Nos Estados Unidos","Na Europa","No Brasil"],"a":2,"e":"Yes, they're made in Brazil, and the fabric is dyed by a small team in Minas Gerais."},{"q":"Como as peças das bolsas são cortadas?","o":["À mão","Com laser","Com uma máquina automática"],"a":0,"e":"The pieces are cut by hand, but they're sewn with machines in our workshop."},{"q":"Quem criou a estampa da bolsa azul?","o":["Uma equipe internacional","A irmã de Daniel","A própria Emma"],"a":1,"e":"The pattern was designed by my sister. She gets ideas from places we visit."},{"q":"O que acontece com cada alça antes da venda?","o":["Ela é pintada de azul","Ela é trocada por uma nova","Ela é testada"],"a":2,"e":"That's frustrating. Here, each strap is tested before a bag is sold."}],"gaps":[{"s":"These bags ___ made in Brazil.","a":["are"],"h":"Essas bolsas são feitas no Brasil."},{"s":"The fabric is ___ locally. (Use dye.)","a":["dyed"],"h":"O tecido é tingido na região."},{"s":"The bag ___ finished last week.","a":["was"],"h":"A bolsa foi finalizada na semana passada."},{"s":"The seams ___ checked yesterday.","a":["were"],"h":"As costuras foram conferidas ontem."},{"s":"The pattern was designed ___ Daniel's sister.","a":["by"],"h":"A estampa foi criada pela irmã do Daniel."},{"s":"___ these labels printed nearby?","a":["Are"],"h":"Essas etiquetas são impressas aqui perto?"}],"order":[{"t":["These","bags","are","made","in","Brazil."],"h":"Essas bolsas são feitas no Brasil."},{"t":["The","logo","was","designed","by","Emma."],"h":"O logotipo foi criado por Emma."},{"t":["Were","the","packages","checked","yesterday?"],"h":"As embalagens foram conferidas ontem?"}],"dict":[{"t":"These bags are made in a small workshop in Brazil."},{"t":"The pattern was designed by my sister."},{"t":"Are the labels printed on recycled paper or on regular paper?"},{"t":"Every seam was carefully checked before the fair opened."},{"t":"The boxes weren't damaged during delivery.","alt":["The boxes were not damaged during delivery."]}],"shadow":["Yes, they're made in Brazil, and the fabric is dyed by a small team in Minas Gerais.","The pieces are cut by hand, but they're sewn with machines in our workshop.","It was finished last week, and every seam was checked before the fair.","The pattern was designed by my sister. She gets ideas from places we visit."],"write":{"task":"Escolha um objeto que você usa todos os dias e escreva de 5 a 7 frases sobre onde ele é produzido, de que material é feito e como foi fabricado. Use pelo menos três passivas no presente, duas no passado e um exemplo de by + agente. Se não souber um fato, imagine um produto fictício.","ph":"My favorite … is made in … It is made from … The design was created by …"},"cards":[["Este café é produzido no Brasil.","This coffee is produced in Brazil."],["As peças são montadas manualmente.","The parts are assembled by hand."],["O vestido foi feito no mês passado por um estilista da minha cidade.","The dress was made last month by a designer from my hometown."],["A embalagem é feita de papel reciclado.","The packaging is made from recycled paper."],["O cartaz foi criado por uma artista local.","The poster was created by a local artist."],["Esses produtos são vendidos pela internet.","These products are sold online."],["A entrega foi confirmada ontem.","The delivery was confirmed yesterday."],["As instruções estão impressas na caixa.","The instructions are printed on the box."],["As janelas foram limpas esta manhã.","The windows were cleaned this morning."],["Essas máquinas são verificadas todos os meses.","These machines are checked every month."]]},{"title":"The Person Who...","goal":"Identificar pessoas, objetos e lugares com informações essenciais, ligar ideias usando who, which, that, where e whose e evitar a repetição de frases curtas ao descrever alguém ou alguma coisa.","speakers":{"Sarah":"f","Daniel":"m"},"setting":"Em uma cafeteria, Sarah e Daniel organizam uma oficina gratuita de informática para adultos. Eles procuram uma professora, uma sala adequada e voluntários, descrevendo as pessoas e os lugares para ter certeza de quem estão falando.","lines":[["Sarah","We're still looking for someone who can teach the computer workshop next month.","Ainda estamos procurando alguém que possa dar a oficina de informática no mês que vem."],["Daniel","I know a woman who helps people learn basic computer skills at the library.","Conheço uma mulher que ajuda as pessoas a aprender noções básicas de informática na biblioteca."],["Sarah","Is she the teacher whose class you took last year?","Ela é a professora de quem você fez o curso no ano passado?"],["Daniel","Yes, that's Emma. She's the person who helped me build my first website.","Sim, é a Emma. Ela é a pessoa que me ajudou a criar meu primeiro site."],["Sarah","That's exactly the experience we need. Where does she work now?","É exatamente a experiência de que precisamos. Onde ela trabalha agora?"],["Daniel","At a community center where adults can take free evening classes.","Em um centro comunitário onde adultos podem fazer cursos noturnos gratuitos."],["Sarah","Would she be interested in a workshop that focuses on job applications?","Será que ela se interessaria por uma oficina voltada a candidaturas de emprego?"],["Daniel","Probably. She created a guide that explains how to write a simple resume.","Provavelmente. Ela criou um guia que explica como escrever um currículo simples."],["Sarah","We also need a room where everyone can use a computer.","Também precisamos de uma sala onde todo mundo possa usar um computador."],["Daniel","The library has computers which were donated last year and a room that we can book on Saturdays.","A biblioteca tem computadores que foram doados no ano passado e uma sala que podemos reservar aos sábados."],["Sarah","Perfect. What about the volunteer whose laptop stopped working last month?","Perfeito. E o voluntário cujo notebook parou de funcionar no mês passado?"],["Daniel","That's Lucas. His laptop was repaired, and he offered to help with registration.","É o Lucas. O notebook dele foi consertado, e ele se ofereceu para ajudar com as inscrições."],["Sarah","Great. Could you introduce me to Emma before Friday?","Ótimo. Você pode me apresentar à Emma antes de sexta-feira?"],["Daniel","Of course. I'll send you the email address that she shared with me.","Claro. Vou te mandar o endereço de e-mail que ela compartilhou comigo."]],"grammar":[{"h":"Orações relativas definidoras: identificar exatamente quem ou o quê","p":["Uma <b>oração relativa definidora</b> acrescenta uma informação essencial para identificar uma pessoa ou coisa: <b>The woman who teaches here is Emma</b>. A parte who teaches here explica de qual mulher estamos falando.","Em vez de dizer “I know a woman. She teaches here”, podemos unir as ideias: <b>I know a woman who teaches here</b>.","Como a informação é necessária para identificar o referente, normalmente <b>não usamos vírgulas</b> para separar esse tipo de oração relativa."],"ex":[["The woman who teaches here is Emma.","A mulher que dá aulas aqui é a Emma."],["I know a man who repairs computers.","Conheço um homem que conserta computadores."],["The student that arrived first is Lucas.","O aluno que chegou primeiro é o Lucas."]],"tip":"Use <b>who</b> ou <b>that</b> para identificar pessoas. O trecho relativo ajuda a dizer exatamente de quem se trata."},{"h":"Which e that para identificar coisas","p":["Usamos <b>which</b> ou <b>that</b> para acrescentar uma informação essencial sobre um objeto, documento, ideia ou outra coisa.","Compare: <b>The guide is free</b> e <b>The guide that explains the process is free</b>. Na segunda frase, identificamos o guia específico.","Quando which ou that funciona como objeto da oração relativa, pode ser omitido em muitos casos: <b>The room that we booked</b> também pode ser <b>The room we booked</b>. Quando é o sujeito da oração, não o omitimos: The guide that explains the process."],"ex":[["The guide that explains the process is free.","O guia que explica o processo é gratuito."],["The computers which were donated still work.","Os computadores que foram doados ainda funcionam."],["I found the file that you sent me.","Encontrei o arquivo que você me enviou."],["The room we booked is on the second floor.","A sala que reservamos fica no segundo andar."]],"tip":"Para coisas, <b>which</b> e <b>that</b> são opções comuns. Não use who para identificar objetos."},{"h":"Where para lugares","p":["Usamos <b>where</b> para indicar o lugar em que algo acontece. Ele evita repetir expressões como in that place ou at that place.","Por exemplo, <b>The library where I study</b> identifica a biblioteca em que estudo. A oração relativa está ligada ao lugar, não a uma pessoa.","Use <b>which</b> ou <b>that</b> quando o próprio lugar funciona como sujeito da oração relativa: The library that offers free classes is downtown."],"ex":[["This is the library where I study.","Esta é a biblioteca onde estudo."],["We found a café where we can work quietly.","Encontramos um café onde podemos trabalhar em silêncio."],["The community center where she works is nearby.","O centro comunitário onde ela trabalha fica perto."],["The library that offers free classes is downtown.","A biblioteca que oferece cursos gratuitos fica no centro."]],"tip":"<b>Where</b> indica “onde”; <b>that/which</b> pode indicar “que” ao descrever uma característica do lugar."},{"h":"Whose: indicar de quem é alguma coisa","p":["Usamos <b>whose</b> em uma oração relativa para indicar posse ou relação de pertencimento. Ele equivale a cujo, cuja, cujos ou cujas em português, embora a tradução natural muitas vezes seja “de quem”.","A estrutura é <b>pessoa + whose + coisa possuída + verbo</b>: <b>The volunteer whose laptop broke</b>. A informação identifica o voluntário pelo notebook que quebrou.","Não confunda <b>whose</b> com <b>who's</b>. Who's é contração de who is ou who has; whose indica posse."],"ex":[["The volunteer whose laptop broke is Lucas.","O voluntário cujo notebook quebrou é o Lucas."],["I met a designer whose work I really like.","Conheci uma designer de cujo trabalho gosto muito."],["She's the teacher whose class we attended.","Ela é a professora de quem fizemos o curso."],["Do you know the man whose bike was stolen?","Você conhece o homem cuja bicicleta foi roubada?"]],"tip":"Depois de <b>whose</b>, normalmente aparece o objeto ou a pessoa com quem existe a relação: whose laptop, whose class, whose sister."}],"vocab":[{"h":"Oficinas e aprendizagem","items":[["workshop","oficina; curso prático"],["computer skills","habilidades de informática"],["basic","básico"],["evening class","aula noturna"],["guide","guia; manual"],["resume","currículo"],["job application","candidatura a emprego"],["registration","inscrição; cadastro"],["donate","doar"],["book a room","reservar uma sala"]]},{"h":"Pessoas, lugares e relações","items":[["volunteer","voluntário"],["community center","centro comunitário"],["introduce someone","apresentar alguém"],["offer to help","oferecer-se para ajudar"],["repair","consertar; reparo"],["share","compartilhar"],["be interested in","ter interesse em"],["experience","experiência"],["nearby","por perto"],["website","site; página na internet"]]}],"pron":[{"h":"Who e whose","p":"O pronome <b>who</b> soa aproximadamente “hú”, com H soprado no início; não pronunciamos a letra W. <b>Whose</b> soa “húz”, terminando com som de Z. Pratique ouvindo a diferença no final das duas palavras.","w":["who","whose","the person who helped","the teacher whose class"]},{"h":"Which e o final CH","p":"<b>Which</b> soa aproximadamente “uítch”, com som de TCH no final. <b>That</b> soa aproximadamente “dhét”, começando com o TH sonoro do inglês, produzido com a língua próxima aos dentes.","w":["which","that","computers which work","a guide that helps"]},{"h":"Where e o R americano","p":"<b>Where</b> soa aproximadamente “uér”, com o R americano no fim. Compare <b>where</b> (onde), <b>were</b> (forma passada de be) e <b>wear</b> (vestir), que podem confundir pela grafia e, em alguns sotaques, pelo som.","w":["where","where she works","a place where we meet","the room where we study"]}],"mc":[{"q":"Quem é a mulher que Daniel sugere para dar a oficina?","o":["Sarah","Emma","Uma funcionária desconhecida"],"a":1,"e":"Yes, that's Emma. She's the person who helped me build my first website."},{"q":"Onde Emma trabalha atualmente?","o":["Em uma escola particular","Em uma loja de computadores","Em um centro comunitário"],"a":2,"e":"At a community center where adults can take free evening classes."},{"q":"O que existe na biblioteca, segundo Daniel?","o":["Computadores doados e uma sala que pode ser reservada","Um laboratório que só abre aos domingos","Um estúdio de gravação particular"],"a":0,"e":"The library has computers which were donated last year and a room that we can book on Saturdays."},{"q":"Com o que Lucas se ofereceu para ajudar?","o":["Com a impressão dos currículos","Com as inscrições","Com a compra de computadores"],"a":1,"e":"That's Lucas. His laptop was repaired, and he offered to help with registration."}],"gaps":[{"s":"The woman ___ teaches here is Emma.","a":["who","that"],"h":"A mulher que dá aulas aqui é a Emma."},{"s":"The computers ___ were donated still work.","a":["which","that"],"h":"Os computadores que foram doados ainda funcionam."},{"s":"The volunteer ___ laptop broke is Lucas.","a":["whose"],"h":"O voluntário cujo notebook quebrou é o Lucas."},{"s":"This is the library ___ I study every Saturday.","a":["where","in which","at which"],"h":"Esta é a biblioteca onde estudo todo sábado."},{"s":"The guide ___ explains the process is free.","a":["that","which"],"h":"O guia que explica o processo é gratuito."},{"s":"She's the teacher ___ class we attended last year.","a":["whose"],"h":"Ela é a professora de quem fizemos o curso no ano passado."}],"order":[{"t":["She's","the","person","who","helped","me."],"h":"Ela é a pessoa que me ajudou."},{"t":["This","is","the","room","where","we","meet."],"h":"Esta é a sala onde nos encontramos."},{"t":["The","man","whose","car","broke","down","called."],"h":"O homem cujo carro quebrou ligou."}],"dict":[{"t":"She's the person who helped me build my first website.","alt":["She is the person who helped me build my first website."]},{"t":"We need a room where everyone can use a computer."},{"t":"The guide that explains the process is free."},{"t":"I met a designer whose work I really like."},{"t":"The computers which were donated last year still work.","alt":["The computers that were donated last year still work."]}],"shadow":["I know a woman who helps people learn basic computer skills at the library.","Yes, that's Emma. She's the person who helped me build my first website.","The library has computers which were donated last year and a room that we can book on Saturdays.","Perfect. What about the volunteer whose laptop stopped working last month?"],"write":{"task":"Descreva, em 5 a 7 frases, uma pessoa que admira, um lugar importante para você e um objeto útil no seu dia a dia. Identifique cada um usando who, which ou that, where e whose pelo menos uma vez. Dê informações que ajudem outra pessoa a saber exatamente de quem ou do que você está falando.","ph":"I admire someone who … The place where I … is … I use a … that … I know a person whose …"},"cards":[["Essa é a pessoa que me indicou a vaga.","That's the person who told me about the job opening."],["Conheço um aplicativo que ajuda a estudar.","I know an app that helps you study."],["Esta é a loja onde comprei meu celular.","This is the store where I bought my phone."],["Ela é a mulher cujo filho mora no Canadá.","She's the woman whose son lives in Canada."],["O livro que você recomendou é excelente.","The book you recommended is excellent."],["Precisamos de uma mesa que caiba na cozinha.","We need a table that fits in the kitchen."],["O rapaz que me atendeu foi muito gentil.","The guy who helped me was very kind."],["É o restaurante onde comemoramos meu aniversário.","It's the restaurant where we celebrated my birthday."],["Conheço uma fotógrafa cujas fotos são incríveis.","I know a photographer whose pictures are amazing."],["O arquivo que contém as instruções está aqui.","The file which contains the instructions is here."]]},{"title":"She Said That...","goal":"Relatar o que outras pessoas disseram usando say e tell, adaptar tempos verbais e referências de tempo no discurso indireto e transmitir perguntas com asked, if e palavras interrogativas sem inverter a ordem das palavras.","speakers":{"Sarah":"f","Emma":"f"},"setting":"Na sexta-feira à tarde, Sarah encontra Emma na entrada de um centro comunitário. As duas conferem informações desencontradas sobre uma oficina que mudou de dia e combinam como avisar os participantes.","lines":[["Sarah","Did you hear that Saturday's workshop was moved? I already made plans for the weekend.","Você soube que a oficina de sábado foi transferida? Eu já tinha feito planos para o fim de semana."],["Emma","Yes. Lucas told me that the main room was closed for repairs, so they had to change the date.","Sim. Lucas me contou que a sala principal estava fechada para reparos, então precisaram mudar a data."],["Sarah","That's strange. I thought Daniel said the workshop was still on Saturday.","Que estranho. Achei que Daniel tivesse dito que a oficina continuaria no sábado."],["Emma","He did, but that was before the building manager called him yesterday morning.","Ele disse, mas isso foi antes de o responsável pelo prédio ligar para ele ontem de manhã."],["Sarah","What did Daniel say after that call? Did he explain the new plan?","O que Daniel disse depois daquela ligação? Ele explicou o novo plano?"],["Emma","He said they were moving it to Sunday, and he told us that it would start at ten.","Ele disse que estavam transferindo para domingo e nos avisou que começaria às dez."],["Sarah","Did he say why they couldn't use the smaller room on Saturday?","Ele disse por que não podiam usar a sala menor no sábado?"],["Emma","He explained that another group had already booked it for the whole morning.","Ele explicou que outro grupo já havia reservado a sala pela manhã inteira."],["Sarah","So how did the volunteers find out? Not everyone checks their email every day.","Então como os voluntários ficaram sabendo? Nem todo mundo olha o e-mail todos os dias."],["Emma","Daniel sent a message. He told everyone to check the updated schedule online.","Daniel mandou uma mensagem. Ele pediu a todos que conferissem o cronograma atualizado na internet."],["Sarah","Did anyone ask about the materials? We usually need to bring our own notebooks.","Alguém perguntou sobre os materiais? Geralmente precisamos levar nossos próprios cadernos."],["Emma","Lucas asked if we needed to bring anything, and Daniel said the center would provide everything.","Lucas perguntou se precisávamos levar alguma coisa, e Daniel disse que o centro forneceria tudo."],["Sarah","Good. Did he ask what time the volunteers could arrive to help set up?","Ótimo. Ele perguntou a que horas os voluntários poderiam chegar para ajudar a preparar tudo?"],["Emma","He did. I told him I could be there by nine thirty, before the first visitors arrived.","Perguntou. Eu disse a ele que poderia estar lá até as nove e meia, antes de chegarem os primeiros visitantes."],["Sarah","I'll tell Lucas that I'm coming too. He might have missed the latest message.","Vou avisar Lucas que também vou. Talvez ele não tenha visto a mensagem mais recente."],["Emma","Perfect. Please remind him that the workshop is on Sunday now, not Saturday.","Perfeito. Lembre a ele que a oficina agora é no domingo, não no sábado."]],"grammar":[{"h":"Say e tell: contar o que alguém falou","p":["Para relatar o que alguém disse, usamos o <b>reported speech</b> (discurso indireto). Não é preciso reproduzir a fala palavra por palavra. O verbo <b>said</b> é o passado de say; <b>told</b> é o passado de tell.","Com <b>say</b>, normalmente não colocamos a pessoa diretamente depois do verbo: <b>She said that she was busy</b>. Para indicar a quem ela falou, usamos <b>said to me</b>.","Com <b>tell</b>, normalmente indicamos quem recebeu a informação: <b>She told me that she was busy</b>. A palavra <b>that</b> pode ser omitida sem mudar o sentido.","Também usamos <b>tell + pessoa + to + verbo</b> para transmitir instruções e pedidos: He told us to wait."],"ex":[["Daniel said that the room was closed.","Daniel disse que a sala estava fechada."],["Emma told Sarah that the date had changed.","Emma contou a Sarah que a data tinha mudado."],["He said he was tired.","Ele disse que estava cansado."],["She told us to check the schedule.","Ela pediu que conferíssemos o cronograma."]],"tip":"Evite <b>said me</b>. Use <b>told me</b> ou <b>said to me</b>."},{"h":"Mudança dos tempos verbais no discurso indireto","p":["Quando o verbo que introduz a fala está no passado, é comum recuar o tempo verbal da informação relatada. Chamamos essa mudança de <b>backshift</b>.","As mudanças mais frequentes são: <b>am/is → was</b>, <b>are → were</b>, <b>present simple → past simple</b>, <b>will → would</b> e <b>can → could</b>.","Se a fala original estava no <b>past simple</b>, ao relatá-la podemos usar o <b>past perfect</b> para deixar claro que aconteceu antes: He said he had booked the room.","O recuo não é obrigatório em todas as situações, especialmente quando a informação continua verdadeira. Nesta unidade, pratique primeiro a forma com recuo ao relatar falas passadas."],"ex":[["She said she worked on Sundays.","Ela disse que trabalhava aos domingos."],["He told me he was waiting outside.","Ele me disse que estava esperando lá fora."],["Daniel said the class would start at ten.","Daniel disse que a aula começaria às dez."],["Lucas said he had sent the email.","Lucas disse que tinha enviado o e-mail."]],"tip":"No relato de uma fala passada, <b>will</b> costuma virar <b>would</b>, e <b>can</b> costuma virar <b>could</b>."},{"h":"Mudanças de tempo e lugar","p":["Ao contar uma fala em outro momento ou lugar, algumas expressões precisam ser adaptadas para fazer sentido no novo contexto.","Entre as mudanças comuns estão <b>today → that day</b>, <b>tomorrow → the next day</b>, <b>yesterday → the day before</b>, <b>now → then</b> e <b>here → there</b>.","Essas trocas dependem da situação. Se ainda estamos no mesmo dia, por exemplo, today pode continuar today. O mais importante é manter clara a referência de tempo e lugar.","Também ajustamos os pronomes conforme quem fala: <b>I</b> na fala original pode virar <b>he</b> ou <b>she</b> no relato."],"ex":[["He said he was busy that day.","Ele disse que estava ocupado naquele dia."],["She told me she would call the next day.","Ela me disse que ligaria no dia seguinte."],["Lucas said he had seen Emma the day before.","Lucas disse que tinha visto Emma no dia anterior."],["They said they couldn't wait there.","Eles disseram que não podiam esperar lá."]],"tip":"Não troque marcadores de tempo automaticamente: pense em <b>quando</b> e <b>onde</b> o relato está sendo feito."},{"h":"Perguntas indiretas com asked, if e palavras interrogativas","p":["Para relatar perguntas, usamos frequentemente <b>asked</b>. Se a pergunta original admite yes ou no, introduzimos o relato com <b>if</b> ou <b>whether</b>, ambos com sentido de se.","Em perguntas que começam com what, where, when, why ou how, mantemos a palavra interrogativa. A ordem depois dela passa a ser a de uma afirmação, sem inversão entre sujeito e verbo.","Compare <b>Where are you going?</b> com <b>He asked where I was going</b>. Observe também que não usamos do ou did para manter a estrutura da pergunta original.","Ao relatar uma pergunta, a frase completa geralmente termina com ponto final, pois agora estamos afirmando que alguém fez uma pergunta."],"ex":[["Lucas asked if we needed help.","Lucas perguntou se precisávamos de ajuda."],["She asked whether I could come early.","Ela perguntou se eu poderia chegar cedo."],["Daniel asked what time we were arriving.","Daniel perguntou a que horas estávamos chegando."],["Emma asked where the meeting was.","Emma perguntou onde era a reunião."]],"tip":"Diga <b>He asked where I was</b>, não “He asked where was I”."}],"vocab":[{"h":"Avisos e alterações de planos","items":[["workshop","oficina; atividade prática"],["updated schedule","cronograma atualizado"],["change the date","mudar a data"],["move an event","transferir um evento"],["main room","sala principal"],["closed for repairs","fechado para reparos"],["volunteer","voluntário"],["set up","preparar; montar"],["provide","fornecer"],["miss a message","não ver uma mensagem"]]},{"h":"Comunicar e relatar","items":[["say","dizer"],["tell","contar; avisar"],["ask","perguntar; pedir"],["explain","explicar"],["remind","lembrar alguém"],["find out","descobrir; ficar sabendo"],["report","relatar"],["mention","mencionar"],["the day before","no dia anterior"],["the next day","no dia seguinte"]]}],"pron":[{"h":"Said e tell no passado","p":"<b>Said</b> é pronunciado aproximadamente “séd”, e não como say com um D. <b>Told</b> soa aproximadamente “tôuld”, com o L audível. São formas muito frequentes ao relatar conversas.","w":["said","told","she said","he told me"]},{"h":"Would e could na fala","p":"O L não é pronunciado em <b>would</b> nem em <b>could</b>. As pronúncias aproximadas são “uúd” e “kúd”. Em <b>he would</b>, é comum a contração <b>he'd</b>, aproximadamente “híd”.","w":["would","could","he'd arrive","we could help"]},{"h":"Asked e a junção de sons","p":"<b>Asked</b> termina com uma sequência de sons consonantais, aproximadamente “éskt”. Na fala rápida, o grupo de consoantes pode ficar reduzido. Treine primeiro com calma e depois ligue à palavra seguinte.","w":["asked","asked if","she asked me","asked what time"]}],"mc":[{"q":"Por que a oficina precisou mudar de dia?","o":["O professor estava doente","A sala principal estava fechada para reparos","Não havia voluntários suficientes"],"a":1,"e":"Yes. Lucas told me that the main room was closed for repairs, so they had to change the date."},{"q":"Para quando a oficina foi transferida?","o":["Domingo, às dez","Sábado, às nove e meia","Segunda-feira, às dez"],"a":0,"e":"He said they were moving it to Sunday, and he told us that it would start at ten."},{"q":"O que Lucas perguntou a Daniel?","o":["Se poderia dirigir a oficina","Se o horário mudaria novamente","Se precisavam levar algum material"],"a":2,"e":"Lucas asked if we needed to bring anything, and Daniel said the center would provide everything."},{"q":"Que horas Emma disse que poderia chegar?","o":["Dez e meia","Até nove e meia","Oito em ponto"],"a":1,"e":"He did. I told him I could be there by nine thirty, before the first visitors arrived."}],"gaps":[{"s":"Daniel ___ that the room was closed. (Use say in the past.)","a":["said"],"h":"Daniel disse que a sala estava fechada."},{"s":"Lucas ___ me that the event had moved. (Use tell in the past.)","a":["told"],"h":"Lucas me contou que o evento tinha mudado."},{"s":"He said the class ___ start at ten. (Report will.)","a":["would","'d"],"h":"Ele disse que a aula começaria às dez."},{"s":"She said she ___ busy that day. (Report is.)","a":["was"],"h":"Ela disse que estava ocupada naquele dia."},{"s":"Emma asked ___ I could arrive early. (Report a yes/no question; use if.)","a":["if","whether"],"h":"Emma perguntou se eu poderia chegar cedo."},{"s":"Daniel asked where the meeting ___. (Use be in the past.)","a":["was"],"h":"Daniel perguntou onde era a reunião."}],"order":[{"t":["She","told","me","the","date","had","changed."],"h":"Ela me contou que a data tinha mudado."},{"t":["He","asked","if","we","needed","help."],"h":"Ele perguntou se precisávamos de ajuda."},{"t":["Emma","asked","where","the","meeting","was."],"h":"Emma perguntou onde era a reunião."}],"dict":[{"t":"Lucas said he had already sent the message."},{"t":"She told me that the workshop was on Sunday."},{"t":"Daniel asked if we could arrive early."},{"t":"He said he would call the next day."},{"t":"Emma asked what time the volunteers were arriving."}],"shadow":["Yes. Lucas told me that the main room was closed for repairs, so they had to change the date.","He said they were moving it to Sunday, and he told us that it would start at ten.","Lucas asked if we needed to bring anything, and Daniel said the center would provide everything.","He did. I told him I could be there by nine thirty, before the first visitors arrived."],"write":{"task":"Escreva de 5 a 7 frases contando a alguém uma conversa recente sobre trabalho, estudo ou planos. Diga o que duas pessoas falaram e relate pelo menos uma pergunta. Use said, told, asked, um recuo de tempo verbal e uma referência de tempo adaptada.","ph":"Yesterday, … told me that … She said … Then I asked if … He explained that …"},"cards":[["Ela disse que estava ocupada naquela tarde.","She said she was busy that afternoon."],["Ele me contou que havia perdido o ônibus.","He told me he had missed the bus."],["Lucas perguntou se eu precisava de ajuda.","Lucas asked if I needed help."],["Ela perguntou onde ficava a sala.","She asked where the room was."],["Daniel disse que ligaria no dia seguinte.","Daniel said he would call the next day."],["Eles disseram que não podiam ficar.","They said they couldn't stay."],["Avise a Emma que o horário mudou.","Tell Emma that the time has changed."],["Ela pediu que eu conferisse o e-mail.","She told me to check my email."],["Ele disse que tinha enviado o formulário.","He said he had sent the form."],["Sarah perguntou por que a loja estava fechada.","Sarah asked why the store was closed."]]},{"title":"It Must Be...","goal":"Fazer suposições sobre situações do presente com diferentes graus de certeza, usando must para deduções fortes, might e could para possibilidades, e can't para conclusões consideradas impossíveis diante dos indícios.","speakers":{"Lucas":"m","Daniel":"m"},"setting":"Em uma manhã de domingo, Lucas encontra água no chão da cozinha do apartamento que divide com Daniel. Os dois observam pistas, levantam hipóteses sobre a origem da água e escolhem uma forma segura de verificar o problema.","lines":[["Lucas","Daniel, there's water all over the kitchen floor. Did you spill something?","Daniel, tem água espalhada pelo chão da cozinha. Você derramou alguma coisa?"],["Daniel","No. It must be the dishwasher. It's been making strange noises all week.","Não. Deve ser a lava-louças. Ela vem fazendo barulhos estranhos a semana inteira."],["Lucas","It can't be the dishwasher. We haven't used it since Tuesday, and the inside is completely dry.","Não pode ser a lava-louças. Não usamos desde terça-feira, e ela está completamente seca por dentro."],["Daniel","Then a pipe might be leaking under the sink. Can you check the cabinet?","Então talvez um cano esteja vazando embaixo da pia. Você consegue olhar o armário?"],["Lucas","Could be, but the cabinet feels dry. I can't see any drops near the pipes.","Pode ser, mas o armário parece seco. Não vejo nenhuma gota perto dos canos."],["Daniel","Look at the ceiling. There's a small stain above the window. The neighbors might have a leak.","Olhe para o teto. Tem uma pequena mancha acima da janela. Talvez os vizinhos estejam com um vazamento."],["Lucas","They could be washing clothes upstairs. I can hear a machine running somewhere.","Eles podem estar lavando roupa lá em cima. Consigo ouvir uma máquina funcionando em algum lugar."],["Daniel","Maybe, but that sound could be coming from the apartment next door.","Talvez, mas esse som pode estar vindo do apartamento ao lado."],["Lucas","You're right. We shouldn't guess without checking. Let's find where the water starts.","Você tem razão. Não devemos adivinhar sem verificar. Vamos descobrir onde a água começa."],["Daniel","The water is deeper near the fridge. Could it be coming from behind it?","A água está mais acumulada perto da geladeira. Será que pode estar vindo de trás dela?"],["Lucas","Wait, the freezer door isn't closed all the way, and there's water under it.","Espera, a porta do freezer não está totalmente fechada, e tem água embaixo dele."],["Daniel","That must be the problem! Some ice probably melted while we were asleep.","Esse deve ser o problema! Provavelmente um pouco de gelo derreteu enquanto dormíamos."],["Lucas","It can't be a broken pipe, then. The water is only around the fridge, not the sink.","Então não pode ser um cano quebrado. A água está só ao redor da geladeira, não da pia."],["Daniel","Still, the floor might be slippery. I'll get some towels before anyone walks in.","Mesmo assim, o chão pode estar escorregadio. Vou pegar umas toalhas antes que alguém entre."],["Lucas","Let's dry everything and check again later. If the water comes back, we'll call someone.","Vamos secar tudo e verificar novamente mais tarde. Se a água voltar, vamos chamar alguém."],["Daniel","Good plan. I was worried, but the cause seems much clearer now.","Boa ideia. Eu estava preocupado, mas agora a causa parece bem mais clara."]],"grammar":[{"h":"Must: dedução com muita certeza","p":["Usamos <b>must</b> para fazer uma dedução que consideramos muito provável a partir de pistas ou informações disponíveis. Não é uma certeza absoluta, mas há bons motivos para acreditar na conclusão.","A estrutura é <b>must + verbo na forma base</b>. Para falar de uma condição, usamos <b>must be</b>: The floor must be wet. Para uma atividade em andamento, podemos usar <b>must be + -ing</b>.","Nesse uso, must não expressa obrigação. A frase <b>It must be the freezer</b> significa que os indícios apontam para o freezer como a causa provável.","Os modais não recebem -s com he, she ou it e não precisam de do ou does para formar perguntas e negativas."],"ex":[["The door is open. Someone must be home.","A porta está aberta. Deve ter alguém em casa."],["He's wearing a coat. He must be cold.","Ele está de casaco. Deve estar com frio."],["That noise must be coming from the kitchen.","Aquele barulho deve estar vindo da cozinha."],["The keys must be in my bag.","As chaves devem estar na minha bolsa."]],"tip":"Neste sentido, <b>must</b> indica uma dedução forte, não uma ordem."},{"h":"Might e could: possibilidades, não certezas","p":["Usamos <b>might</b> e <b>could</b> para apresentar explicações possíveis quando ainda não temos evidências suficientes para ter certeza.","Com esse significado, as duas formas são próximas: <b>It might be the fridge</b> e <b>It could be the fridge</b> indicam que a geladeira é uma possibilidade.","A estrutura continua sendo <b>modal + verbo na forma base</b>. Podemos dizer <b>might be leaking</b> ou <b>could be leaking</b> quando suspeitamos de uma atividade em andamento.","Para fazer uma pergunta sobre uma possibilidade, <b>Could it be...?</b> é muito natural. Em um palpite, não é preciso escolher uma resposta definitiva antes de investigar."],"ex":[["The pipe might be leaking.","Talvez o cano esteja vazando."],["This could be the right address.","Este pode ser o endereço certo."],["She might be working from home today.","Talvez ela esteja trabalhando de casa hoje."],["Could that sound be coming from upstairs?","Será que esse som pode estar vindo de cima?"]],"tip":"Para um palpite incerto, prefira <b>might</b> ou <b>could</b>, não must."},{"h":"Can't: uma conclusão considerada impossível","p":["Usamos <b>can't</b> para dizer que uma hipótese não faz sentido diante das evidências disponíveis. É uma dedução negativa forte.","Por exemplo, se a máquina está seca e ninguém a usou, podemos dizer <b>It can't be the dishwasher</b>. Não estamos apenas dizendo que não sabemos; estamos descartando aquela explicação.","Compare os graus de certeza: <b>must be</b> indica conclusão muito provável; <b>might/could be</b> indica possibilidade; <b>can't be</b> indica algo considerado impossível.","Atenção: <b>mustn't</b> costuma expressar proibição, como You mustn't touch that wire. Para deduzir que algo não pode ser verdade, use can't."],"ex":[["It can't be Lucas. He's out of town.","Não pode ser Lucas. Ele está fora da cidade."],["That can't be the answer. The numbers don't match.","Essa não pode ser a resposta. Os números não batem."],["She can't be asleep. I can hear her talking.","Ela não pode estar dormindo. Consigo ouvi-la falando."],["This can't be my jacket. Mine is blue.","Esta não pode ser minha jaqueta. A minha é azul."]],"tip":"<b>Can't be</b> expressa dedução negativa; <b>mustn't</b> normalmente significa que algo é proibido."},{"h":"Pistas e graus de certeza na conversa","p":["Escolha o modal com base nas evidências, e não apenas na sua preferência. Se há uma pista forte, <b>must</b> pode funcionar. Se há várias explicações possíveis, use <b>might</b> ou <b>could</b>.","Se uma informação contradiz uma explicação, use <b>can't</b>. É comum apresentar o motivo com <b>because</b>, ou mencionar a pista em outra frase.","Expressões como <b>maybe</b> e <b>probably</b> também aparecem ao fazer suposições. Maybe costuma apresentar uma possibilidade; probably sugere que consideramos algo provável.","Nesta unidade, fazemos deduções sobre o <b>presente</b>. Não confunda essas formas com estruturas usadas para deduzir acontecimentos concluídos no passado."],"ex":[["The lights are on. They must be inside.","As luzes estão acesas. Eles devem estar lá dentro."],["Maybe the package belongs to Sarah.","Talvez o pacote seja da Sarah."],["He could be in a meeting right now.","Ele pode estar em uma reunião agora."],["It can't be the heater because it's turned off.","Não pode ser o aquecedor porque ele está desligado."]],"tip":"Pergunte-se: há <b>provas fortes</b>, apenas uma <b>possibilidade</b> ou uma <b>contradição</b>?"}],"vocab":[{"h":"Casa e pequenos problemas","items":[["dishwasher","lava-louças"],["freezer","freezer; congelador"],["fridge","geladeira"],["pipe","cano"],["leak","vazamento; vazar"],["sink","pia"],["cabinet","armário"],["stain","mancha"],["puddle","poça"],["slippery","escorregadio"]]},{"h":"Investigar e levantar hipóteses","items":[["clue","pista"],["guess","adivinhar; supor"],["check","verificar"],["probably","provavelmente"],["maybe","talvez"],["be possible","ser possível"],["be likely","ser provável"],["come from","vir de"],["make sense","fazer sentido"],["figure out","descobrir; entender"]]}],"pron":[{"h":"Must be na fala conectada","p":"Em <b>must be</b>, o T final de must pode ficar pouco perceptível antes de B. A expressão costuma soar aproximadamente “mâs(t) bí”. A sílaba forte geralmente recai no verbo ou na informação nova.","w":["must","must be","It must be cold","It must be the fridge"]},{"h":"Might e could","p":"<b>Might</b> soa aproximadamente “máit”, com o encontro consonantal no fim; <b>could</b> soa “kúd”, sem pronunciar o L. Treine as duas formas junto de be para ganhar fluidez.","w":["might","could","might be leaking","could be upstairs"]},{"h":"Can't no inglês americano","p":"No inglês americano, <b>can't</b> tem a vogal aberta de cat, aproximadamente “kênt” para muitos falantes brasileiros, com o T final frequentemente discreto. Compare com <b>can</b>, que costuma ser reduzido em frases afirmativas. O ritmo e o contexto ajudam a diferenciar.","w":["can","can't","It can't be","She can't be asleep"]}],"mc":[{"q":"Por que Lucas descarta a lava-louças como causa do problema?","o":["Ela não foi usada desde terça e está seca por dentro","Ela foi consertada na semana anterior","Ela está na lavanderia"],"a":0,"e":"It can't be the dishwasher. We haven't used it since Tuesday, and the inside is completely dry."},{"q":"Que problema Daniel considera possível embaixo da pia?","o":["Um vidro quebrado","Um cano vazando","Uma máquina ligada"],"a":1,"e":"Then a pipe might be leaking under the sink. Can you check the cabinet?"},{"q":"Qual detalhe perto da geladeira ajuda a explicar a água no chão?","o":["A tomada está desligada","O motor parou de funcionar","A porta do freezer não está totalmente fechada"],"a":2,"e":"Wait, the freezer door isn't closed all the way, and there's water under it."},{"q":"O que Lucas propõe fazer depois de secar o chão?","o":["Comprar uma geladeira nova imediatamente","Verificar novamente mais tarde e chamar alguém se a água voltar","Sair do apartamento sem conferir nada"],"a":1,"e":"Let's dry everything and check again later. If the water comes back, we'll call someone."}],"gaps":[{"s":"The lights are on. Someone ___ be home. (Strong deduction.)","a":["must"],"h":"As luzes estão acesas. Deve ter alguém em casa."},{"s":"The pipe ___ be leaking, but we aren't sure. (Use might.)","a":["might","could"],"h":"Talvez o cano esteja vazando, mas não temos certeza."},{"s":"It ___ be Lucas. He's out of town. (Strong negative deduction.)","a":["can't","cannot"],"h":"Não pode ser Lucas. Ele está fora da cidade."},{"s":"___ that sound be coming from upstairs? (Use could.)","a":["Could"],"h":"Será que aquele som pode estar vindo de cima?"},{"s":"She must ___ tired after working all day.","a":["be"],"h":"Ela deve estar cansada depois de trabalhar o dia todo."},{"s":"They could be ___ upstairs. (Use the -ing form of work.)","a":["working"],"h":"Talvez eles estejam trabalhando lá em cima."}],"order":[{"t":["The","noise","must","be","coming","from","upstairs."],"h":"O barulho deve estar vindo do andar de cima."},{"t":["It","can't","be","his","jacket."],"h":"Não pode ser a jaqueta dele."},{"t":["Could","the","pipe","be","leaking?"],"h":"Será que o cano pode estar vazando?"}],"dict":[{"t":"It must be the freezer. The door is still open."},{"t":"The pipe might be leaking under the sink."},{"t":"It can't be the dishwasher because it's dry inside.","alt":["It cannot be the dishwasher because it's dry inside.","It can't be the dishwasher because it is dry inside."]},{"t":"Could that noise be coming from the apartment upstairs?"},{"t":"She must be working late. Her office light is on."}],"shadow":["It can't be the dishwasher. We haven't used it since Tuesday, and the inside is completely dry.","Then a pipe might be leaking under the sink. Can you check the cabinet?","The water is deeper near the fridge. Could it be coming from behind it?","That must be the problem! Some ice probably melted while we were asleep."],"write":{"task":"Descreva um pequeno mistério do dia a dia, como um objeto desaparecido, um barulho estranho ou um problema em casa. Escreva de 5 a 7 frases com pistas e hipóteses. Use must, might, could e can't para indicar graus diferentes de certeza.","ph":"I noticed … It must be … because … It might be … But it can't be … Could it be …?"},"cards":[["A luz está acesa. Ela deve estar em casa.","The light is on. She must be home."],["Talvez ele esteja esperando lá fora.","He might be waiting outside."],["Não pode ser o Daniel. Ele está viajando.","It can't be Daniel. He's traveling."],["Será que a chave está na minha mochila?","Could the key be in my backpack?"],["Eles devem estar presos no trânsito.","They must be stuck in traffic."],["Esse cheiro pode estar vindo da cozinha.","That smell could be coming from the kitchen."],["Esse não pode ser o número certo.","That can't be the right number."],["Talvez ela esteja trabalhando até tarde.","She might be working late."],["A reunião deve ser importante.","The meeting must be important."],["Será que ele está usando o computador?","Could he be using the computer?"]]},{"title":"I Enjoy Cooking","goal":"Falar sobre gostos, decisões, planos e hábitos usando verbo + -ing ou verbo + to, empregar enjoy, avoid, decide e want corretamente e distinguir os significados de stop e remember conforme a estrutura que vem depois.","speakers":{"Sarah":"f","Daniel":"m"},"setting":"Em uma feira de produtores locais no sábado, Sarah encontra Daniel, que começou um curso de culinária. Os dois conversam sobre aprender a cozinhar, fazer compras, criar hábitos e se inscrever na próxima aula.","lines":[["Sarah","I saw your pictures from the cooking class. Are you enjoying the lessons so far?","Vi suas fotos do curso de culinária. Está gostando das aulas até agora?"],["Daniel","I love them. I used to avoid cooking after work, but now I enjoy making dinner at home.","Estou adorando. Antes, eu evitava cozinhar depois do trabalho, mas agora gosto de preparar o jantar em casa."],["Sarah","I keep thinking about taking a class, but I never decide which one to choose.","Eu vivo pensando em fazer um curso, mas nunca decido qual escolher."],["Daniel","I decided to sign up after I tried a free lesson. The teacher explains everything clearly.","Decidi me inscrever depois de experimentar uma aula gratuita. O professor explica tudo com clareza."],["Sarah","Is it hard to follow the recipes? I sometimes forget important ingredients.","É difícil seguir as receitas? Às vezes esqueço ingredientes importantes."],["Daniel","Not really. We learn to prepare simple meals, and we practice cutting vegetables safely.","Na verdade, não. Aprendemos a preparar refeições simples e praticamos cortar legumes com segurança."],["Sarah","I always forget to buy something on my shopping list. It's a bad habit.","Eu sempre esqueço de comprar alguma coisa da lista de compras. É um hábito ruim."],["Daniel","I try to remember to check the list before leaving home. That helps me avoid wasting food.","Eu tento me lembrar de conferir a lista antes de sair de casa. Isso me ajuda a evitar o desperdício de comida."],["Sarah","Have you stopped ordering takeout during the week, or do you still get it sometimes?","Você parou de pedir comida por delivery durante a semana ou ainda pede às vezes?"],["Daniel","I've stopped ordering it on weekdays. I save money, and I feel better too.","Parei de pedir durante a semana. Economizo dinheiro e também me sinto melhor."],["Sarah","Do you ever stop to get coffee on your way to class? There's a good place nearby.","Você às vezes para para tomar café no caminho para a aula? Tem um lugar bom por perto."],["Daniel","Sometimes. Last Saturday, I stopped to buy fresh bread, and I arrived a little late.","Às vezes. Sábado passado, parei para comprar pão fresco e cheguei um pouco atrasado."],["Sarah","I remember making bread with my grandmother when I was little. I loved that.","Lembro de fazer pão com minha avó quando era pequena. Eu adorava aquilo."],["Daniel","Then you'll enjoy our next lesson. We're planning to bake bread together next week.","Então você vai gostar da nossa próxima aula. Estamos planejando fazer pão juntos na semana que vem."],["Sarah","I'd like to join. Could you send me the link so I can register tonight?","Eu gostaria de participar. Pode me mandar o link para eu me inscrever hoje à noite?"],["Daniel","Of course. Don't forget to register before Friday. The class usually fills up quickly.","Claro. Não se esqueça de se inscrever antes de sexta-feira. As vagas da turma costumam acabar rápido."]],"grammar":[{"h":"Verbos seguidos de -ing: enjoy, avoid e outros","p":["Depois de alguns verbos, usamos outro verbo com a terminação <b>-ing</b>. Entre os mais úteis estão <b>enjoy</b> (gostar de), <b>avoid</b> (evitar), <b>finish</b> (terminar) e <b>keep</b> (continuar).","A estrutura é <b>enjoy/avoid/finish/keep + verbo com -ing</b>. Por exemplo: I enjoy cooking. Isso significa que gosto da atividade de cozinhar.","Não usamos to antes do segundo verbo nessas combinações. <b>I enjoy cooking</b> é correto; “I enjoy to cook” não é a estrutura padrão.","Após preposições comuns, como before e after, também podemos encontrar -ing: before leaving home, after finishing work."],"ex":[["I enjoy cooking for my friends.","Gosto de cozinhar para meus amigos."],["She avoids eating too much sugar.","Ela evita consumir açúcar demais."],["We finished preparing the vegetables.","Terminamos de preparar os legumes."],["He keeps forgetting his shopping list.","Ele vive esquecendo a lista de compras."]],"tip":"Depois de <b>enjoy</b> e <b>avoid</b>, use <b>-ing</b>: enjoy reading, avoid driving."},{"h":"Verbos seguidos de to + infinitivo: decide, want e plan","p":["Outros verbos normalmente são seguidos de <b>to + verbo na forma base</b>. É o caso de <b>decide</b> (decidir), <b>want</b> (querer), <b>plan</b> (planejar), <b>hope</b> (esperar) e <b>need</b> (precisar).","A estrutura é <b>verbo + to + forma base</b>. Exemplos: I want to learn, She decided to join, We plan to cook.","Não coloque -ing depois desses verbos quando estiver usando as estruturas ensinadas aqui. Diga <b>We decided to stay</b>, não “We decided staying”.","Em uma frase com dois verbos, vale memorizar a combinação completa. Isso facilita escolher a forma certa sem traduzir palavra por palavra do português."],"ex":[["I decided to take a cooking class.","Decidi fazer um curso de culinária."],["She wants to learn new recipes.","Ela quer aprender receitas novas."],["We plan to make pasta tonight.","Planejamos fazer macarrão hoje à noite."],["They hope to open a small café.","Eles esperam abrir uma cafeteria pequena."]],"tip":"Diga <b>want to go</b>, <b>decide to start</b> e <b>plan to study</b>."},{"h":"Stop doing e stop to do: sentidos diferentes","p":["O verbo <b>stop</b> pode vir antes de -ing ou de to + infinitivo, mas a escolha muda o significado da frase.","<b>Stop + -ing</b> significa parar de realizar uma atividade. Em <b>I stopped ordering takeout</b>, parei com o hábito de pedir comida por delivery.","<b>Stop + to + verbo</b> significa interromper outra atividade para fazer alguma coisa. Em <b>I stopped to buy bread</b>, fiz uma parada com o objetivo de comprar pão.","Observe o contexto e pergunte: a pessoa <b>abandonou uma ação</b> ou <b>fez uma pausa para outra ação</b>? Essa diferença define a construção."],"ex":[["I stopped drinking soda last month.","Parei de tomar refrigerante no mês passado."],["She stopped to drink some water.","Ela parou para beber um pouco de água."],["They stopped talking when the teacher arrived.","Eles pararam de conversar quando o professor chegou."],["We stopped to ask for directions.","Paramos para pedir informações sobre o caminho."]],"tip":"<b>Stopped smoking</b> = parou de fumar; <b>stopped to smoke</b> = parou para fumar."},{"h":"Remember doing e remember to do","p":["O verbo <b>remember</b> também aceita as duas estruturas, com significados diferentes. <b>Remember + -ing</b> indica ter a lembrança de algo que já aconteceu.","Por outro lado, <b>remember + to + verbo</b> significa lembrar-se de fazer algo, sem esquecer uma tarefa ou compromisso.","Compare: <b>I remember making bread with my grandmother</b> (tenho essa lembrança) e <b>Remember to buy bread</b> (não se esqueça dessa tarefa).","Na negativa, <b>Don't forget to...</b> é muito útil para lembretes e funciona de modo semelhante a remember to nas instruções do dia a dia."],"ex":[["I remember meeting her at the market.","Lembro de conhecê-la na feira."],["Remember to bring your notebook.","Lembre-se de levar seu caderno."],["She remembered turning off the stove.","Ela se lembrava de ter desligado o fogão."],["I remembered to call my mother.","Lembrei de ligar para minha mãe."]],"tip":"<b>Remember doing</b> fala de uma lembrança; <b>remember to do</b> fala de uma tarefa que não deve ser esquecida."}],"vocab":[{"h":"Cozinha e alimentação","items":[["cooking class","curso de culinária"],["recipe","receita"],["ingredient","ingrediente"],["shopping list","lista de compras"],["meal","refeição"],["fresh bread","pão fresco"],["cut vegetables","cortar legumes"],["bake","assar; fazer no forno"],["takeout","comida para viagem; delivery"],["waste food","desperdiçar comida"]]},{"h":"Planos, decisões e hábitos","items":[["enjoy","gostar de uma atividade"],["avoid","evitar"],["decide","decidir"],["plan","planejar"],["keep","continuar; viver fazendo"],["stop","parar"],["remember","lembrar-se"],["forget","esquecer"],["sign up","inscrever-se"],["fill up","lotar; ficar sem vagas"]]}],"pron":[{"h":"A terminação -ing","p":"O final <b>-ing</b> tem um som nasal feito mais ao fundo da boca, sem pronunciar um G separado. <b>Cooking</b> soa aproximadamente “KÚ-king”, e <b>making</b>, “MÊI-king”. Evite acrescentar uma vogal depois do final nasal.","w":["cooking","making","ordering","remembering"]},{"h":"To reduzido em want to e decide to","p":"Em frases naturais, o <b>to</b> de <b>want to</b> e <b>decide to</b> costuma ter uma vogal fraca, próxima de “tâ”. Em fala informal, want to pode soar como “uâna”, mas mantenha a escrita <b>want to</b>.","w":["want to learn","decide to join","plan to cook","remember to check"]},{"h":"Stopped e remembered","p":"Na terminação <b>-ed</b>, <b>stopped</b> termina com som de T, aproximadamente “stápt”. <b>Remembered</b> termina com som de D, aproximadamente “ri-MÉM-bârd”. A pronúncia depende do som final do verbo, não só das letras.","w":["stopped","remembered","decided","finished"]}],"mc":[{"q":"O que Daniel costumava evitar depois do trabalho?","o":["Cozinhar","Fazer compras","Comer em casa"],"a":0,"e":"I love them. I used to avoid cooking after work, but now I enjoy making dinner at home."},{"q":"O que fez Daniel decidir se inscrever no curso?","o":["Uma indicação do chefe","Uma aula gratuita que experimentou","Uma promoção no mercado"],"a":1,"e":"I decided to sign up after I tried a free lesson. The teacher explains everything clearly."},{"q":"Qual hábito Daniel parou de ter durante a semana?","o":["Tomar café","Comprar pão fresco","Pedir comida por delivery"],"a":2,"e":"I've stopped ordering it on weekdays. I save money, and I feel better too."},{"q":"O que Sarah lembra de fazer com a avó na infância?","o":["Plantar tomates","Fazer pão","Preparar café"],"a":1,"e":"I remember making bread with my grandmother when I was little. I loved that."}],"gaps":[{"s":"I enjoy ___ meals for my friends. (Use cook.)","a":["cooking"],"h":"Gosto de cozinhar para meus amigos."},{"s":"She decided to ___ the class. (Use join.)","a":["join"],"h":"Ela decidiu entrar para a turma."},{"s":"He stopped ___ takeout during the week. (Use order.)","a":["ordering"],"h":"Ele parou de pedir delivery durante a semana."},{"s":"We stopped ___ buy fresh bread on the way home.","a":["to"],"h":"Paramos para comprar pão fresco no caminho de casa."},{"s":"Don't forget ___ register before Friday.","a":["to"],"h":"Não se esqueça de se inscrever antes de sexta-feira."},{"s":"I remember ___ bread with my grandmother. (Use make.)","a":["making"],"h":"Lembro de fazer pão com minha avó."}],"order":[{"t":["I","enjoy","trying","new","recipes","on","weekends."],"h":"Gosto de experimentar receitas novas nos fins de semana."},{"t":["She","decided","to","join","the","class."],"h":"Ela decidiu entrar para a turma."},{"t":["Remember","to","bring","your","shopping","list."],"h":"Lembre-se de levar sua lista de compras."}],"dict":[{"t":"I enjoy cooking, but I avoid wasting food."},{"t":"She decided to sign up for the cooking class."},{"t":"I stopped ordering takeout during the week."},{"t":"We stopped to buy fresh bread on the way home."},{"t":"Don't forget to check the recipe before you start.","alt":["Do not forget to check the recipe before you start."]}],"shadow":["I love them. I used to avoid cooking after work, but now I enjoy making dinner at home.","I try to remember to check the list before leaving home. That helps me avoid wasting food.","I've stopped ordering it on weekdays. I save money, and I feel better too.","I remember making bread with my grandmother when I was little. I loved that."],"write":{"task":"Escreva de 5 a 7 frases sobre algo que gosta de fazer, uma atividade que evita, uma decisão recente e um hábito que quer mudar. Use enjoy, avoid, decide e want. Inclua ainda um exemplo de stop doing ou stop to do e uma frase com remember.","ph":"I enjoy …, but I avoid … Last month, I decided to … I want to … I stopped … I always remember to …"},"cards":[["Gosto de experimentar pratos novos.","I enjoy trying new dishes."],["Ela evita comprar comida que não vai usar.","She avoids buying food she won't use."],["Decidimos fazer um curso juntos.","We decided to take a class together."],["Quero aprender a fazer pão.","I want to learn to bake bread."],["Ele parou de beber refrigerante.","He stopped drinking soda."],["Paramos para tomar um café.","We stopped to get some coffee."],["Lembro de visitar aquela feira quando era criança.","I remember visiting that market as a child."],["Lembre-se de desligar o forno.","Remember to turn off the oven."],["Ela planeja cozinhar para a família no domingo.","She plans to cook for her family on Sunday."],["Terminei de cortar os legumes.","I finished cutting the vegetables."]]},{"title":"At Work","goal":"Participar de uma entrevista de emprego, falar sobre experiências profissionais, perguntas e oportunidades, e usar os verbos frasais look for, give up, set up, find out, take off e turn down em situações reais de trabalho.","speakers":{"Sarah":"f","Daniel":"m"},"setting":"Em uma entrevista de emprego numa empresa de tecnologia, Daniel conversa com Sarah sobre sua experiência com clientes, projetos anteriores, mudanças de carreira e o que ela espera encontrar na nova função.","lines":[["Daniel","Thanks for coming in, Sarah. What made you apply for this customer support position?","Obrigado por vir, Sarah. O que fez você se candidatar a esta vaga de atendimento ao cliente?"],["Sarah","I've been looking for a job where I can solve problems and learn new skills every day.","Estou procurando um emprego em que possa resolver problemas e aprender novas habilidades todos os dias."],["Daniel","Your resume says you helped set up a support team at your last company. How did that go?","Seu currículo diz que você ajudou a montar uma equipe de atendimento na última empresa. Como foi?"],["Sarah","We started with three people. I set up a weekly meeting so we could share difficult cases.","Começamos com três pessoas. Organizei uma reunião semanal para podermos compartilhar casos difíceis."],["Daniel","Can you tell me about a problem you couldn't solve right away?","Pode me contar sobre um problema que você não conseguiu resolver de imediato?"],["Sarah","A customer couldn't log in. I didn't give up; I kept checking until I found out what was wrong.","Um cliente não conseguia entrar na conta. Não desisti; continuei verificando até descobrir o que estava errado."],["Daniel","What was the problem, and how did you explain the solution to the customer?","Qual era o problema e como você explicou a solução ao cliente?"],["Sarah","The email address was incorrect. I walked him through the steps, and he thanked me afterward.","O endereço de e-mail estava incorreto. Expliquei o passo a passo, e ele me agradeceu depois."],["Daniel","I also see that you worked on a small online shop. Did that business take off?","Também vejo que você trabalhou em uma lojinha virtual. O negócio deu certo e começou a crescer?"],["Sarah","It did for a while. Orders took off after we posted a helpful video, but I wanted a steadier job.","Por um tempo, sim. Os pedidos dispararam depois que publicamos um vídeo útil, mas eu queria um trabalho mais estável."],["Daniel","Have you ever turned down a job offer? I'm curious about what matters most to you.","Você já recusou uma proposta de emprego? Quero entender o que é mais importante para você."],["Sarah","Yes, I turned down one offer because the hours were too unpredictable. I value a clear schedule.","Sim, recusei uma proposta porque os horários eram imprevisíveis demais. Valorizo uma rotina bem definida."],["Daniel","That makes sense. We offer training, and the team meets in person twice a week.","Faz sentido. Oferecemos treinamento, e a equipe se reúne presencialmente duas vezes por semana."],["Sarah","That sounds promising. Could you tell me how new employees find out about changes to their shifts?","Parece promissor. Você poderia me dizer como os novos funcionários ficam sabendo das mudanças nos turnos?"],["Daniel","We send an email and update the team calendar. We'll set up a second interview next week.","Enviamos um e-mail e atualizamos o calendário da equipe. Vamos marcar uma segunda entrevista na semana que vem."],["Sarah","Great, thank you. I'm excited to learn more about the role and meet the rest of the team.","Ótimo, obrigada. Estou animada para saber mais sobre a função e conhecer o restante da equipe."]],"grammar":[{"h":"O que são phrasal verbs? Look for e find out","p":["Um <b>phrasal verb</b> combina um verbo com uma partícula, como <b>for</b>, <b>out</b> ou <b>up</b>. O sentido da combinação pode ser diferente do sentido do verbo sozinho.","<b>Look for</b> significa procurar alguém ou alguma coisa: I'm looking for a job. Depois dele, colocamos diretamente aquilo que procuramos.","<b>Find out</b> significa descobrir uma informação: We found out why the system stopped. É diferente de find, que pode indicar encontrar um objeto ou uma pessoa.","Com find out, também podemos dizer <b>find out about</b> quando queremos saber mais a respeito de um assunto."],"ex":[["I'm looking for a position with flexible hours.","Estou procurando uma vaga com horários flexíveis."],["Are you looking for a new apartment?","Você está procurando um apartamento novo?"],["We found out why the website wasn't working.","Descobrimos por que o site não estava funcionando."],["I want to find out more about the company.","Quero descobrir mais sobre a empresa."]],"tip":"<b>Look for</b> é procurar; <b>find out</b> é descobrir uma informação. Não confunda as duas ideias."},{"h":"Set up e give up: organizar e desistir","p":["<b>Set up</b> pode significar organizar, preparar ou montar algo, como uma reunião, uma conta ou uma equipe. O contexto mostra o sentido exato.","<b>Give up</b> significa desistir. Podemos dizer give up ou give up on something quando queremos falar de abandonar uma tentativa ou objetivo.","Alguns phrasal verbs permitem colocar um objeto entre o verbo e a partícula. Com <b>set up</b>, podemos dizer set up a meeting ou set a meeting up.","Se o objeto é um pronome, ele precisa ficar no meio de set up: <b>set it up</b>. Já em <b>give up on a goal</b>, a expressão on a goal fica depois do phrasal verb."],"ex":[["Let's set up a call for Thursday.","Vamos marcar uma ligação para quinta-feira."],["I'll set it up after lunch.","Vou organizar isso depois do almoço."],["Don't give up after one difficult interview.","Não desista depois de uma entrevista difícil."],["She refused to give up on her goal.","Ela se recusou a desistir do objetivo dela."]],"tip":"Com pronome, diga <b>set it up</b>, não “set up it”."},{"h":"Take off e turn down: crescer e recusar","p":["<b>Take off</b> pode significar decolar, tirar uma peça de roupa ou começar a fazer muito sucesso. Em uma conversa sobre negócios, <b>sales took off</b> significa que as vendas cresceram rapidamente.","<b>Turn down</b> significa recusar uma oferta, convite ou pedido. Em contextos profissionais, podemos turn down an offer quando uma proposta não combina com nossos objetivos.","A expressão <b>turn down</b> também pode significar diminuir o volume de algo. O contexto determina o significado.","Com um pronome como it, usamos <b>turn it down</b>; não colocamos o pronome depois da partícula."],"ex":[["Orders took off after the new campaign.","Os pedidos dispararam depois da nova campanha."],["The plane took off on time.","O avião decolou na hora."],["He turned down the job offer.","Ele recusou a proposta de emprego."],["I turned it down because of the schedule.","Recusei a proposta por causa dos horários."]],"tip":"<b>Take off</b> tem diferentes sentidos. No diálogo, é o crescimento rápido de um negócio."},{"h":"Entrevista de emprego: experiência e perguntas educadas","p":["Em entrevistas, usamos o <b>present perfect</b> para perguntar sobre experiências até hoje: Have you ever turned down a job offer? Ele não informa quando a experiência aconteceu.","O <b>past simple</b> ajuda a contar os detalhes de uma experiência passada: I turned down one offer last year. Também podemos usar o past simple para explicar problemas resolvidos no trabalho.","Para pedir informações com educação, usamos <b>Could you tell me...?</b> ou <b>I'd like to know...</b>. Em perguntas indiretas, a ordem das palavras depois de what, how ou when é a de uma afirmação.","Ao falar de qualidades pessoais, prefira exemplos concretos: I kept checking until I found out what was wrong mostra persistência, em vez de apenas dizer I'm hardworking."],"ex":[["Have you ever worked with international customers?","Você já trabalhou com clientes internacionais?"],["I helped solve a difficult problem last month.","Ajudei a resolver um problema difícil no mês passado."],["Could you tell me how the training works?","Você poderia me dizer como funciona o treinamento?"],["I'd like to know when the next interview is.","Gostaria de saber quando será a próxima entrevista."]],"tip":"Após <b>Could you tell me how...</b>, diga <b>how the training works</b>, não “how does the training work”."}],"vocab":[{"h":"Candidatura e vida profissional","items":[["job opening","vaga de emprego"],["apply for a job","candidatar-se a um emprego"],["resume","currículo"],["job offer","proposta de emprego"],["work experience","experiência profissional"],["customer support","atendimento ao cliente"],["shift","turno de trabalho"],["training","treinamento"],["steady job","emprego estável"],["unpredictable hours","horários imprevisíveis"]]},{"h":"Ações comuns no trabalho","items":[["look for","procurar"],["find out","descobrir; ficar sabendo"],["set up","organizar; montar; configurar"],["give up","desistir"],["give up on","desistir de"],["take off","decolar; começar a crescer rapidamente"],["turn down","recusar; abaixar o volume"],["walk someone through","orientar alguém passo a passo"],["solve a problem","resolver um problema"],["team calendar","calendário da equipe"]]}],"pron":[{"h":"Look for e find out na fala conectada","p":"Em <b>look for</b>, for pode soar aproximadamente “fâr”, com vogal reduzida e R americano. Em <b>find out</b>, o D final de find se conecta à vogal de out: algo próximo de “fáind-áut”.","w":["look for work","looking for a job","find out","found out why"]},{"h":"Set up e take off: ligação com vogal","p":"Quando uma palavra termina em consoante e a seguinte começa com vogal, os sons podem se unir. <b>Set up</b> soa aproximadamente “sét-âp”; <b>take off</b>, “têik-óf”. Fale as combinações como uma unidade de sentido.","w":["set up a meeting","set it up","take off","orders took off"]},{"h":"Turn down e give up","p":"Em <b>turn down</b>, o R americano de turn deve ser audível: aproximadamente “târn dáun”. <b>Give up</b> soa aproximadamente “guív-âp”, com ligação entre o V final e a vogal seguinte.","w":["turn down","turned down","give up","never give up"]}],"mc":[{"q":"Por que Sarah se candidatou à vaga?","o":["Porque queria trabalhar exclusivamente em casa","Porque buscava resolver problemas e aprender novas habilidades","Porque já conhecia todos na empresa"],"a":1,"e":"I've been looking for a job where I can solve problems and learn new skills every day."},{"q":"O que Sarah organizou na antiga equipe de atendimento?","o":["Uma reunião semanal","Uma viagem de treinamento","Um evento para clientes"],"a":0,"e":"We started with three people. I set up a weekly meeting so we could share difficult cases."},{"q":"O que fez os pedidos da loja virtual crescerem rapidamente?","o":["Uma mudança de endereço","Uma parceria com uma empresa grande","Um vídeo útil publicado pela equipe"],"a":2,"e":"It did for a while. Orders took off after we posted a helpful video, but I wanted a steadier job."},{"q":"Por que Sarah recusou uma proposta de emprego?","o":["Porque o local era muito distante","Porque os horários eram imprevisíveis","Porque não havia treinamento"],"a":1,"e":"Yes, I turned down one offer because the hours were too unpredictable. I value a clear schedule."}],"gaps":[{"s":"I'm looking ___ a customer support job.","a":["for"],"h":"Estou procurando um emprego em atendimento ao cliente."},{"s":"We finally found ___ why the app wasn't working.","a":["out"],"h":"Finalmente descobrimos por que o aplicativo não estava funcionando."},{"s":"Let's set ___ a meeting for Monday.","a":["up"],"h":"Vamos marcar uma reunião para segunda-feira."},{"s":"Don't give ___ when the first interview goes badly.","a":["up"],"h":"Não desista quando a primeira entrevista for ruim."},{"s":"Sales took ___ after the online campaign.","a":["off"],"h":"As vendas dispararam depois da campanha on-line."},{"s":"She turned ___ the offer because of the hours.","a":["down"],"h":"Ela recusou a proposta por causa dos horários."}],"order":[{"t":["I'm","looking","for","a","new","job."],"h":"Estou procurando um emprego novo."},{"t":["Can","we","set","up","a","call?"],"h":"Podemos marcar uma ligação?"},{"t":["She","turned","down","the","job","offer."],"h":"Ela recusou a proposta de emprego."}],"dict":[{"t":"I've been looking for a job with a clear schedule.","alt":["I have been looking for a job with a clear schedule."]},{"t":"We set up a weekly meeting to discuss difficult cases."},{"t":"Don't give up when you face a problem.","alt":["Do not give up when you face a problem."]},{"t":"Orders took off after we posted the video."},{"t":"Could you tell me how new employees find out about changes?"}],"shadow":["I've been looking for a job where I can solve problems and learn new skills every day.","A customer couldn't log in. I didn't give up; I kept checking until I found out what was wrong.","Yes, I turned down one offer because the hours were too unpredictable. I value a clear schedule.","We send an email and update the team calendar. We'll set up a second interview next week."],"write":{"task":"Imagine que você está participando de uma entrevista de emprego para uma vaga que deseja. Escreva de 6 a 8 frases explicando o tipo de trabalho que procura, uma situação difícil que resolveu, como organizou uma atividade e uma pergunta educada para o entrevistador. Use pelo menos três phrasal verbs da unidade.","ph":"I'm looking for … At my last job, I … I didn't give up when … Could you tell me …?"},"cards":[["Estou procurando uma vaga com bons horários.","I'm looking for a job with good hours."],["Você descobriu qual era o problema?","Did you find out what the problem was?"],["Vamos organizar uma chamada de vídeo.","Let's set up a video call."],["Não desista depois de uma resposta negativa.","Don't give up after one rejection."],["As vendas começaram a crescer muito rápido.","Sales really took off."],["Ele recusou a oferta ontem.","He turned down the offer yesterday."],["Vou configurar a conta para você.","I'll set up the account for you."],["Quero saber mais sobre o treinamento.","I'd like to find out more about the training."],["Ela está procurando trabalho desde maio.","She's been looking for work since May."],["Por que você recusou a proposta?","Why did you turn down the offer?"]]},{"title":"So and Such","goal":"Descrever intensidade com so e such, distinguir excesso e suficiência usando too e enough, explicar consequências e expressar opiniões, concordância e discordância de forma clara e educada.","speakers":{"Emma":"f","Lucas":"m"},"setting":"No fim da tarde, Emma e Lucas visitam possíveis locais para uma noite de cinema organizada por amigos do bairro. Eles comparam preço, espaço, conforto e equipamentos antes de decidir onde realizar o evento.","lines":[["Emma","I've visited three places for our movie night. The rooftop is so beautiful at sunset.","Visitei três lugares para nossa noite de cinema. O terraço é tão bonito ao pôr do sol."],["Lucas","I agree, but it's too expensive for our budget. We can't spend that much on one night.","Concordo, mas é caro demais para nosso orçamento. Não podemos gastar tanto em uma única noite."],["Emma","That's true. And it's such a popular place that Saturday is already fully booked.","É verdade. E é um lugar tão popular que sábado já está totalmente reservado."],["Lucas","What about the community room? It's big enough for thirty people, isn't it?","E a sala comunitária? É grande o suficiente para trinta pessoas, não é?"],["Emma","It is, and there are enough chairs, but the projector isn't bright enough for a clear picture.","É, e há cadeiras suficientes, mas o projetor não tem brilho suficiente para uma imagem nítida."],["Lucas","I see your point. Still, we could borrow another projector instead of paying for the rooftop.","Entendo seu ponto. Mesmo assim, poderíamos pegar outro projetor emprestado em vez de pagar pelo terraço."],["Emma","Maybe, but the room gets so noisy when people arrive that it's hard to hear anything.","Talvez, mas a sala fica tão barulhenta quando as pessoas chegam que é difícil ouvir qualquer coisa."],["Lucas","Fair enough. Did you like the small theater we saw near the train station?","Justo. Você gostou do pequeno cinema que vimos perto da estação de trem?"],["Emma","I loved it! It has such comfortable seats, and the staff were so helpful during the tour.","Adorei! Tem poltronas muito confortáveis, e a equipe foi muito prestativa durante a visita."],["Lucas","I agree about the seats, but isn't the screen too small for people in the back row?","Concordo quanto às poltronas, mas a tela não é pequena demais para quem fica na última fileira?"],["Emma","I don't think so. I sat at the back, and the screen was large enough to see everything.","Acho que não. Sentei no fundo, e a tela era grande o suficiente para ver tudo."],["Lucas","Good to know. Do we have enough money to rent it and provide some snacks?","Bom saber. Temos dinheiro suficiente para alugá-lo e oferecer alguns lanches?"],["Emma","Yes, if we keep the snacks simple. It's such a good deal that we should reserve it today.","Sim, se mantivermos os lanches simples. É um negócio tão bom que deveríamos reservar hoje."],["Lucas","I mostly agree, although I'd like to check the sound system before we pay anything.","Concordo em grande parte, embora eu queira conferir o sistema de som antes de pagarmos qualquer coisa."],["Emma","That's reasonable. Let's ask for a short sound test and make the final decision tomorrow.","É razoável. Vamos pedir um teste rápido de som e tomar a decisão final amanhã."],["Lucas","Perfect. We disagree on a few details, but I think our plan is good enough for everyone to enjoy.","Perfeito. Discordamos em alguns detalhes, mas acho que nosso plano é bom o suficiente para todos aproveitarem."]],"grammar":[{"h":"So: intensificar adjetivos e advérbios","p":["Usamos <b>so + adjetivo ou advérbio</b> para intensificar uma característica: so beautiful (tão bonito), so quickly (tão rapidamente). A palavra so vem antes da característica.","Quando queremos mostrar uma consequência, podemos usar <b>so + adjetivo/advérbio + that + oração</b>. Na conversa, the rooftop is so popular that Saturday is fully booked relaciona a popularidade ao resultado.","Não coloque so diretamente antes de um substantivo singular com adjetivo. Para isso, normalmente usamos such a: such a nice place.","So pode aparecer sozinho como resposta em outras construções, mas aqui o foco é seu uso para expressar intensidade."],"ex":[["The rooftop is so beautiful at sunset.","O terraço é tão bonito ao pôr do sol."],["The staff explained everything so clearly.","A equipe explicou tudo com tanta clareza."],["The room was so noisy that we left early.","A sala estava tão barulhenta que saímos cedo."],["The movie was so good that I watched it twice.","O filme era tão bom que assisti a ele duas vezes."]],"tip":"Use <b>so + adjetivo</b>: so expensive. Não diga “so an expensive place”."},{"h":"Such: destacar uma coisa ou situação","p":["Usamos <b>such</b> diante de um grupo com substantivo para dar ênfase. Com substantivo contável no singular, a ordem comum é <b>such + a/an + adjetivo + substantivo</b>.","Com substantivos no plural ou incontáveis, não usamos a/an: such comfortable seats, such good advice. Em frases simples, such também pode aparecer sem adjetivo: such a surprise.","Assim como so, <b>such ... that</b> pode introduzir uma consequência: It was such a good deal that we booked it immediately.","Compare <b>so helpful</b> (tão prestativo) com <b>such a helpful person</b> (uma pessoa tão prestativa). O que vem depois da expressão determina a escolha."],"ex":[["It's such a lovely place for a party.","É um lugar tão agradável para uma festa."],["They have such comfortable chairs.","Eles têm cadeiras tão confortáveis."],["That was such useful advice.","Aquele conselho foi tão útil."],["It was such a great show that we stayed until the end.","Foi um espetáculo tão bom que ficamos até o final."]],"tip":"No singular contável, lembre-se de <b>such a/an</b>; no plural e com incontáveis, não use o artigo."},{"h":"Too e enough: excesso e suficiência","p":["<b>Too + adjetivo</b> indica que algo ultrapassa um limite desejável: too expensive (caro demais), too small (pequeno demais). Frequentemente aponta um problema.","<b>Adjetivo + enough</b> indica que uma característica chega ao nível necessário: big enough, bright enough. A palavra enough vem <b>depois</b> do adjetivo.","Com substantivos, a ordem muda para <b>enough + substantivo</b>: enough chairs, enough money, enough time. Podemos usar not ... enough para mostrar falta de algo.","Compare: <b>not big enough</b> significa não ser grande o suficiente; <b>too small</b> significa ser pequeno demais. As duas ideias podem descrever o mesmo problema."],"ex":[["The tickets are too expensive for us.","Os ingressos são caros demais para nós."],["The room is quiet enough for a meeting.","A sala é silenciosa o suficiente para uma reunião."],["We don't have enough time to prepare.","Não temos tempo suficiente para preparar tudo."],["The screen isn't large enough for the back row.","A tela não é grande o suficiente para a última fileira."]],"tip":"A posição é importante: <b>enough money</b>, mas <b>big enough</b>."},{"h":"Opinar, concordar e discordar sem soar rude","p":["Para dar uma opinião, usamos expressões como <b>I think...</b>, <b>In my opinion...</b> e <b>I don't think so</b>. Em situações de decisão, é útil dar um motivo concreto.","Para concordar, podemos dizer <b>I agree</b>, <b>That's true</b> ou <b>Exactly</b>. <b>Fair enough</b> mostra que aceitamos ou entendemos o argumento do outro.","Para discordar com educação, reconheça primeiro o ponto de vista da pessoa: <b>I see your point, but...</b> ou <b>I agree about the seats, but...</b>.","Expressões como <b>although</b> e <b>however</b> ajudam a contrastar ideias: I like the place, although it's expensive. Isso torna a opinião mais clara e equilibrada."],"ex":[["In my opinion, the theater is the best choice.","Na minha opinião, o cinema é a melhor opção."],["I agree that the seats are comfortable.","Concordo que as poltronas são confortáveis."],["I see your point, but the room is too noisy.","Entendo seu ponto, mas a sala é barulhenta demais."],["I like the location, although parking is difficult.","Gosto da localização, embora seja difícil estacionar."]],"tip":"<b>I see your point, but...</b> é uma maneira natural e educada de apresentar discordância."}],"vocab":[{"h":"Comparação de espaços e eventos","items":[["rooftop","terraço"],["budget","orçamento"],["fully booked","com todas as vagas ou datas reservadas"],["community room","sala comunitária"],["projector","projetor"],["bright","claro; com bastante brilho"],["back row","última fileira"],["sound system","sistema de som"],["rent a space","alugar um espaço"],["a good deal","um bom negócio; uma boa oferta"]]},{"h":"Intensidade, opiniões e negociação","items":[["so","tão; muito, antes de adjetivo ou advérbio"],["such","tão; tamanho, com substantivo"],["too","demais; excessivamente"],["enough","suficiente"],["I agree","eu concordo"],["I see your point","entendo seu ponto"],["fair enough","justo; faz sentido"],["I don't think so","acho que não"],["although","embora; apesar de"],["reasonable","razoável"]]}],"pron":[{"h":"So e such: vogais diferentes","p":"<b>So</b> tem uma vogal que desliza, aproximadamente “sôu”. <b>Such</b> soa aproximadamente “sâtch”, com som de TCH no fim. Ouça essa diferença para reconhecer se a expressão vem antes de um adjetivo ou de um substantivo.","w":["so beautiful","so noisy","such a nice place","such comfortable seats"]},{"h":"Too e to na fala","p":"Quando indica excesso, <b>too</b> soa aproximadamente “tú”, com vogal longa e frequentemente com destaque. Já o <b>to</b> de expressões como to leave pode ter som reduzido, parecido com “tâ”, quando não recebe ênfase.","w":["too expensive","too small","too late to leave","too loud to hear"]},{"h":"Enough: som final de F","p":"<b>Enough</b> soa aproximadamente “i-NÂF”, com a segunda sílaba mais forte. A escrita gh representa o som de F nessa palavra. Em big enough, a consoante final de big se liga à vogal seguinte.","w":["enough","good enough","enough money","bright enough"]}],"mc":[{"q":"Por que Emma e Lucas não escolheram o terraço imediatamente?","o":["Porque não havia cadeiras","Porque era caro demais para o orçamento","Porque era longe da estação"],"a":1,"e":"I agree, but it's too expensive for our budget. We can't spend that much on one night."},{"q":"Qual é o problema do projetor da sala comunitária?","o":["Não tem brilho suficiente","Está quebrado e não liga","É grande demais para a sala"],"a":0,"e":"It is, and there are enough chairs, but the projector isn't bright enough for a clear picture."},{"q":"O que Emma verificou sentando na última fileira do pequeno cinema?","o":["Se as poltronas estavam numeradas","Se a sala tinha ar-condicionado","Se a tela podia ser vista com clareza"],"a":2,"e":"I don't think so. I sat at the back, and the screen was large enough to see everything."},{"q":"O que Lucas quer conferir antes de pagar pelo aluguel?","o":["O sistema de som","A lista de convidados","As opções de transporte"],"a":0,"e":"I mostly agree, although I'd like to check the sound system before we pay anything."}],"gaps":[{"s":"The theater was ___ comfortable that we stayed longer.","a":["so"],"h":"O cinema era tão confortável que ficamos mais tempo."},{"s":"It was ___ a good deal that we booked it immediately.","a":["such"],"h":"Era uma oferta tão boa que reservamos imediatamente."},{"s":"The tickets are ___ expensive for our budget. (Use too.)","a":["too"],"h":"Os ingressos são caros demais para nosso orçamento."},{"s":"The screen isn't large ___ for the back row.","a":["enough"],"h":"A tela não é grande o suficiente para a última fileira."},{"s":"Do we have ___ chairs for everybody?","a":["enough"],"h":"Temos cadeiras suficientes para todo mundo?"},{"s":"They have ___ helpful staff at that theater. (Use such.)","a":["such"],"h":"Aquele cinema tem uma equipe tão prestativa."}],"order":[{"t":["The","room","is","too","small","for","us."],"h":"A sala é pequena demais para nós."},{"t":["We","have","enough","chairs","for","everyone."],"h":"Temos cadeiras suficientes para todos."},{"t":["It's","such","a","good","idea!"],"h":"É uma ideia tão boa!"}],"dict":[{"t":"The rooftop is so beautiful at sunset."},{"t":"It's such a popular place that Saturday is fully booked.","alt":["It is such a popular place that Saturday is fully booked."]},{"t":"We don't have enough money to rent the rooftop.","alt":["We do not have enough money to rent the rooftop."]},{"t":"The projector isn't bright enough for the room.","alt":["The projector is not bright enough for the room."]},{"t":"I see your point, but I don't think so.","alt":["I see your point, but I do not think so."]}],"shadow":["I agree, but it's too expensive for our budget. We can't spend that much on one night.","It is, and there are enough chairs, but the projector isn't bright enough for a clear picture.","I loved it! It has such comfortable seats, and the staff were so helpful during the tour.","I mostly agree, although I'd like to check the sound system before we pay anything."],"write":{"task":"Compare dois lugares onde você poderia reunir amigos: um restaurante, um cinema, um parque ou outro local. Escreva de 6 a 8 frases sobre preço, conforto, tamanho e atendimento. Use so, such, too e enough e apresente pelo menos uma opinião com concordância ou discordância educada.","ph":"In my opinion, … is so … It's such a … However, … is too … I see your point, but …"},"cards":[["O quarto é pequeno demais para quatro pessoas.","The room is too small for four people."],["Foi um dia tão cansativo!","It was such a tiring day!"],["Ela fala tão rápido que não consigo acompanhar.","She speaks so fast that I can't keep up."],["Temos comida suficiente para todos.","We have enough food for everyone."],["O som não está alto o suficiente.","The sound isn't loud enough."],["É um restaurante tão aconchegante.","It's such a cozy restaurant."],["Essa mochila é pesada demais para mim.","This backpack is too heavy for me."],["Concordo com você quanto ao preço.","I agree with you about the price."],["Entendo seu ponto, mas prefiro a outra opção.","I see your point, but I prefer the other option."],["A apresentação foi tão boa que todos aplaudiram.","The presentation was so good that everyone applauded."]]},{"title":"Looking Ahead","goal":"Conversar sobre planos de estudo, carreira e vida pessoal, fazer previsões com will e going to, distinguir intenções de compromissos marcados no present continuous e descrever ações que estarão acontecendo no futuro com future continuous.","speakers":{"Sarah":"f","Emma":"f"},"setting":"Num parque, em um domingo à tarde, Sarah e Emma fazem uma pausa depois de caminhar. Elas conversam sobre cursos, trabalho, viagens e o que imaginam estar fazendo nos próximos meses e anos.","lines":[["Sarah","This year has gone by so quickly. Have you thought about what you want to do next year?","Este ano passou tão rápido. Você já pensou no que quer fazer no ano que vem?"],["Emma","I have. I'm going to take an online course in data analysis because I want to change careers.","Já. Vou fazer um curso on-line de análise de dados porque quero mudar de carreira."],["Sarah","That sounds exciting. Have you decided when you're going to start studying?","Parece empolgante. Você já decidiu quando vai começar a estudar?"],["Emma","I'm meeting a course advisor on Tuesday at four. I've already booked the appointment.","Vou me encontrar com uma orientadora do curso na terça-feira às quatro. Já marquei o horário."],["Sarah","Great! I'm starting a new job in November, so I'll have a lot to learn too.","Ótimo! Vou começar um emprego novo em novembro, então também vou ter muita coisa para aprender."],["Emma","Congratulations! Are you going to move closer to the office, or will you keep your apartment?","Parabéns! Você pretende se mudar para mais perto do escritório ou vai continuar no seu apartamento?"],["Sarah","I'm going to stay where I am for now. I can work from home three days a week.","Pretendo ficar onde estou por enquanto. Posso trabalhar de casa três dias por semana."],["Emma","That should make things easier. What will you be doing at this time next year?","Isso deve facilitar as coisas. O que você vai estar fazendo nesta época do ano que vem?"],["Sarah","I hope I'll be leading small projects and helping new people on the team.","Espero estar liderando projetos pequenos e ajudando pessoas novas na equipe."],["Emma","I'd like that too. I'll be studying in the evenings while I work during the day.","Eu também gostaria disso. Vou estar estudando à noite enquanto trabalho durante o dia."],["Sarah","I think more companies will offer flexible schedules in the future. That could help you.","Acho que mais empresas vão oferecer horários flexíveis no futuro. Isso poderia ajudar você."],["Emma","I hope so. By the way, I'm visiting my sister next weekend. We're having dinner on Saturday.","Tomara. Aliás, vou visitar minha irmã no próximo fim de semana. Vamos jantar no sábado."],["Sarah","That sounds fun. Oh, look at those dark clouds! It's going to rain soon.","Que legal. Ah, olha aquelas nuvens escuras! Vai chover logo."],["Emma","You're right. I didn't bring an umbrella, and we're still a long way from home.","Você tem razão. Não trouxe guarda-chuva, e ainda estamos longe de casa."],["Sarah","Don't worry. I'll call a ride for us now, and I'll send you that job website tonight.","Não se preocupe. Vou chamar um carro para nós agora e enviar aquele site de empregos para você à noite."],["Emma","Thanks! Whatever happens, I think we'll both be learning a lot over the next year.","Obrigada! Aconteça o que acontecer, acho que nós duas vamos aprender muito no próximo ano."]],"grammar":[{"h":"Will: decisões no momento e previsões","p":["Usamos <b>will + verbo na forma base</b> para decisões tomadas no momento da fala, promessas, ofertas e previsões. A forma é a mesma para todas as pessoas: I will, she will, they will.","Em uma decisão espontânea, é comum dizer <b>I'll call a ride now</b> quando acabamos de perceber que precisamos de transporte.","Para previsões baseadas em opinião, usamos frequentemente <b>I think</b>, <b>I believe</b> ou <b>probably</b>: I think remote work will grow.","A negativa é <b>won't</b> ou will not; na pergunta, colocamos will antes da pessoa. Após will, não usamos to."],"ex":[["I'll call a ride for us now.","Vou chamar um carro para nós agora."],["I think more people will work remotely.","Acho que mais pessoas vão trabalhar remotamente."],["She won't forget the appointment.","Ela não vai esquecer o compromisso."],["Will you send me the link later?","Você vai me enviar o link depois?"]],"tip":"Depois de <b>will</b>, use a forma base: will start, não “will to start”."},{"h":"Going to: intenções e sinais no presente","p":["Usamos <b>be going to + verbo na forma base</b> para falar de intenções que já existiam antes do momento da conversa: I'm going to take a course.","Também usamos going to quando há <b>sinais no presente</b> que apoiam uma previsão: Look at those clouds. It's going to rain.","A estrutura muda de acordo com a pessoa: <b>am going to</b>, <b>is going to</b> e <b>are going to</b>. Na negativa, acrescentamos not ao verbo be.","Compare <b>I'll call now</b>, decisão naquele momento, e <b>I'm going to call tonight</b>, intenção já planejada. Na vida real, alguns usos se sobrepõem, mas a diferença ajuda a escolher."],"ex":[["I'm going to study data analysis next year.","Vou estudar análise de dados no ano que vem."],["We're going to save money for a trip.","Vamos economizar dinheiro para uma viagem."],["Look at the sky. It's going to rain.","Olha o céu. Vai chover."],["He isn't going to change jobs this month.","Ele não pretende mudar de emprego neste mês."]],"tip":"Não esqueça o verbo <b>be</b>: I'm going to, she's going to, we're going to."},{"h":"Present continuous: compromissos já marcados","p":["O <b>present continuous</b> também pode falar de futuro quando descreve um compromisso ou plano já combinado: I'm meeting an advisor on Tuesday.","Nesses casos, costumamos incluir uma expressão de tempo futuro, como tomorrow, next week ou on Friday, para deixar claro que não falamos de uma atividade acontecendo agora.","O present continuous indica frequentemente que detalhes práticos já estão definidos, como hora, local ou pessoa envolvida. <b>I'm starting a new job in November</b> sugere uma data estabelecida.","Com horários fixos de serviços e transportes, também é comum usar o <b>present simple</b> aprendido no A2: The train leaves at eight. Aqui praticamos sobretudo compromissos pessoais."],"ex":[["I'm meeting the advisor at four on Tuesday.","Vou me encontrar com a orientadora às quatro na terça-feira."],["We're having dinner with Emma on Saturday.","Vamos jantar com Emma no sábado."],["Sarah is starting her new job next month.","Sarah vai começar o emprego novo no mês que vem."],["Are you visiting your family this weekend?","Você vai visitar sua família neste fim de semana?"]],"tip":"Em <b>I'm meeting her tomorrow</b>, a expressão tomorrow mostra que o present continuous indica futuro."},{"h":"Future continuous: ações em andamento no futuro","p":["O <b>future continuous</b> usa <b>will be + verbo com -ing</b>. Ele mostra uma atividade que estará acontecendo em determinado momento do futuro.","Podemos perguntar <b>What will you be doing this time next year?</b> para imaginar o que alguém estará fazendo naquela época.","Também usamos a estrutura para falar de atividades esperadas em horários futuros: At nine tomorrow, I'll be working. Ela destaca a atividade em andamento, não sua conclusão.","Para a negativa, usamos <b>won't be + -ing</b>. Para perguntas, começamos com will: Will you be working tomorrow morning?"],"ex":[["I'll be studying tomorrow evening.","Vou estar estudando amanhã à noite."],["This time next year, she'll be working abroad.","Nesta época do ano que vem, ela estará trabalhando no exterior."],["We won't be traveling during the holidays.","Não estaremos viajando durante as férias."],["Will you be using your laptop at six?","Você vai estar usando o notebook às seis?"]],"tip":"No future continuous, mantenha <b>will be + -ing</b>. Não diga “will working”."}],"vocab":[{"h":"Estudo, carreira e projetos","items":[["look ahead","olhar para o futuro"],["change careers","mudar de carreira"],["online course","curso on-line"],["data analysis","análise de dados"],["course advisor","orientador de curso"],["book an appointment","marcar um horário"],["lead a project","liderar um projeto"],["flexible schedule","horário flexível"],["remote work","trabalho remoto"],["save money","economizar dinheiro"]]},{"h":"Planos, previsões e tempo futuro","items":[["next year","no ano que vem"],["this time next year","nesta época do ano que vem"],["in the future","no futuro"],["soon","em breve"],["for now","por enquanto"],["probably","provavelmente"],["make a plan","fazer um plano"],["keep an appointment","comparecer a um compromisso"],["dark clouds","nuvens escuras"],["whatever happens","aconteça o que acontecer"]]}],"pron":[{"h":"Will e a contração 'll","p":"Na conversa, <b>I will</b> normalmente aparece como <b>I'll</b>, aproximadamente “áil”, e <b>we will</b> como <b>we'll</b>, aproximadamente “uíl”. O <b>'ll</b> se liga à palavra anterior, sem pausa.","w":["I'll call","we'll learn","she'll start","they'll arrive"]},{"h":"Going to e a redução gonna","p":"Na fala informal americana, <b>going to</b> antes de um verbo pode soar aproximadamente “GÂ-nâ”, frequentemente representado como <b>gonna</b>. É importante reconhecer esse som, mas em escrita padrão de atividades e textos prefira going to.","w":["I'm going to study","she's going to move","we're going to start","it's going to rain"]},{"h":"Will be e o ritmo do future continuous","p":"Em <b>I'll be working</b>, o auxiliar be geralmente recebe menos destaque que o verbo principal. A expressão soa aproximadamente “áil bi UÂR-king”, sem separar muito as palavras. O final -ing não tem um G forte separado.","w":["I'll be working","she'll be studying","we'll be traveling","will you be using"]}],"mc":[{"q":"Qual é o principal motivo de Emma querer fazer um curso on-line?","o":["Preparar uma viagem","Mudar de carreira","Aprender a ensinar inglês"],"a":1,"e":"I have. I'm going to take an online course in data analysis because I want to change careers."},{"q":"Quando Emma vai se encontrar com a orientadora do curso?","o":["Na terça-feira às quatro","Na segunda-feira às nove","No sábado à noite"],"a":0,"e":"I'm meeting a course advisor on Tuesday at four. I've already booked the appointment."},{"q":"Quantos dias por semana Sarah poderá trabalhar de casa?","o":["Um dia","Cinco dias","Três dias"],"a":2,"e":"I'm going to stay where I am for now. I can work from home three days a week."},{"q":"Por que Sarah decide chamar um carro na hora?","o":["Porque está atrasada para uma reunião","Porque parece que vai chover e elas estão longe de casa","Porque o parque vai fechar"],"a":1,"e":"Don't worry. I'll call a ride for us now, and I'll send you that job website tonight."}],"gaps":[{"s":"I think more people ___ work remotely in the future. (Use will.)","a":["will","'ll"],"h":"Acho que mais pessoas vão trabalhar remotamente no futuro."},{"s":"Look at those clouds. It's ___ to rain.","a":["going"],"h":"Olha aquelas nuvens. Vai chover."},{"s":"We're ___ our advisor tomorrow at four. (Use meet in the present continuous.)","a":["meeting"],"h":"Vamos nos encontrar com nossa orientadora amanhã às quatro."},{"s":"At eight tomorrow evening, I'll be ___ for my test. (Use study.)","a":["studying"],"h":"Amanhã às oito da noite, vou estar estudando para minha prova."},{"s":"She isn't going ___ move next month.","a":["to"],"h":"Ela não pretende se mudar no mês que vem."},{"s":"Will you ___ working from home on Friday?","a":["be"],"h":"Você vai estar trabalhando de casa na sexta-feira?"}],"order":[{"t":["I'm","meeting","Daniel","on","Tuesday","afternoon."],"h":"Vou me encontrar com Daniel na terça-feira à tarde."},{"t":["It's","going","to","rain","very","soon."],"h":"Vai chover muito em breve."},{"t":["I'll","be","studying","at","eight","tonight."],"h":"Vou estar estudando às oito hoje à noite."}],"dict":[{"t":"I'm going to take an online course next year.","alt":["I am going to take an online course next year."]},{"t":"We're meeting a course advisor on Tuesday at four.","alt":["We are meeting a course advisor on Tuesday at four."]},{"t":"I think more companies will offer flexible schedules."},{"t":"At this time next year, I'll be working on new projects.","alt":["At this time next year, I will be working on new projects."]},{"t":"Look at those dark clouds. It's going to rain soon.","alt":["Look at those dark clouds. It is going to rain soon."]}],"shadow":["I have. I'm going to take an online course in data analysis because I want to change careers.","I'm meeting a course advisor on Tuesday at four. I've already booked the appointment.","I hope I'll be leading small projects and helping new people on the team.","Don't worry. I'll call a ride for us now, and I'll send you that job website tonight."],"write":{"task":"Escreva de 6 a 8 frases sobre os próximos 12 meses. Inclua uma intenção de estudo ou trabalho, um compromisso já marcado, uma previsão e o que imagina estar fazendo nesta época do próximo ano. Use will, going to, present continuous com sentido de futuro e future continuous.","ph":"Next year, I'm going to … On Friday, I'm meeting … I think … will … This time next year, I'll be …"},"cards":[["Vou começar um curso novo no ano que vem.","I'm going to start a new course next year."],["Estou me encontrando com o recrutador na sexta-feira.","I'm meeting the recruiter on Friday."],["Acho que a tecnologia vai mudar esse trabalho.","I think technology will change this job."],["Às nove amanhã, estarei trabalhando.","At nine tomorrow, I'll be working."],["Olha aquele céu! Vai chover.","Look at that sky! It's going to rain."],["Não se preocupe, vou ajudar você.","Don't worry, I'll help you."],["Ela vai visitar os pais neste fim de semana.","She's visiting her parents this weekend."],["Vamos economizar para comprar um carro.","We're going to save money for a car."],["Você vai estar usando o computador à tarde?","Will you be using the computer this afternoon?"],["Não vou trabalhar no sábado de manhã.","I won't be working on Saturday morning."]]},{"title":"What Had Happened?","goal":"Contar histórias com os quatro tempos narrativos: past simple, past continuous, past perfect e past perfect continuous, organizando acontecimentos anteriores, simultâneos e suas consequências.","speakers":{"Emma":"f","Lucas":"m"},"setting":"Na segunda-feira, Lucas conta a Emma como uma queda de energia quase comprometeu a abertura de uma exposição fotográfica no sábado.","lines":[["Emma","You said Saturday's opening was chaotic. What actually happened before the guests arrived?","Você disse que a abertura de sábado foi caótica. O que aconteceu antes de os convidados chegarem?"],["Lucas","It started around six thirty. We were hanging the last photos when the lights suddenly went out.","Começou por volta das seis e meia. Estávamos pendurando as últimas fotos quando as luzes se apagaram de repente."],["Emma","Seriously? I thought the gallery had checked the electrical system earlier that week.","Sério? Achei que a galeria tivesse verificado o sistema elétrico no começo daquela semana."],["Lucas","They had, and we'd tested every lamp on Friday. That's why nobody expected a problem.","Tinha verificado, sim, e tínhamos testado todas as lâmpadas na sexta-feira. Por isso ninguém esperava um problema."],["Emma","Were people already lining up outside, or did you still have time to fix it?","As pessoas já estavam formando fila lá fora ou vocês ainda tinham tempo para resolver?"],["Lucas","A few guests were waiting. Sarah had been greeting early arrivals for twenty minutes when the power failed.","Alguns convidados estavam esperando. Sarah recebia os primeiros visitantes havia vinte minutos quando a energia caiu."],["Emma","Had anyone figured out what caused the outage, or were you completely in the dark?","Alguém tinha descoberto a causa da queda de energia ou vocês estavam totalmente no escuro?"],["Lucas","An electrician had been working next door since five, and he'd accidentally disconnected our power.","Um eletricista estava trabalhando no prédio ao lado desde as cinco e havia desligado nossa energia por acidente."],["Emma","That explains it. I bet Daniel was trying to keep everyone calm while you called for help.","Isso explica. Aposto que Daniel tentava acalmar todo mundo enquanto você pedia ajuda."],["Lucas","Exactly. I was speaking to the building manager when Daniel found a box of battery-powered lights.","Exatamente. Eu falava com o responsável pelo prédio quando Daniel encontrou uma caixa de luzes a bateria."],["Emma","At least someone had a backup plan. Had you already decided to cancel the opening?","Pelo menos alguém tinha um plano B. Vocês já tinham decidido cancelar a abertura?"],["Lucas","Almost. We'd been preparing the exhibit for three months, so canceling felt like the worst option.","Quase. Estávamos preparando a exposição havia três meses, então cancelar parecia a pior opção."],["Emma","What changed your mind? I heard the event went ahead, just a little later than planned.","O que fez vocês mudarem de ideia? Ouvi dizer que o evento aconteceu, só um pouco mais tarde."],["Lucas","The electrician reconnected the power at seven fifteen. By then, the guests had moved into the lobby.","O eletricista restabeleceu a energia às sete e quinze. A essa altura, os convidados tinham ido para o saguão."],["Emma","And the photos? Were any damaged while you were moving things around in the dark?","E as fotos? Alguma foi danificada enquanto vocês mexiam nas coisas no escuro?"],["Lucas","Luckily, no. We kept them covered, and Sarah had already printed signs explaining the delay.","Felizmente, não. Nós as mantivemos cobertas, e Sarah já tinha impresso avisos explicando o atraso."],["Emma","So the opening wasn't perfect, but it sounds as if everyone pulled together.","A abertura não foi perfeita, mas parece que todos se uniram para resolver a situação."],["Lucas","They did. When the lights came back, people actually cheered. I'd never felt so relieved at an event.","Foi isso mesmo. Quando a energia voltou, as pessoas comemoraram. Nunca tinha sentido tanto alívio em um evento."]],"grammar":[{"h":"Past simple e past continuous: acontecimento e contexto","p":["O <b>past simple</b> apresenta acontecimentos concluídos que fazem a narrativa avançar.","O <b>past continuous</b> usa was/were + -ing para ações em andamento num momento do passado.","Juntos, indicam que algo aconteceu enquanto outra ação se desenrolava. <b>When</b> costuma introduzir o evento pontual; <b>while</b> destaca uma atividade em andamento."],"ex":[["I was checking the guest list when the lights went out.","Eu conferia a lista de convidados quando as luzes se apagaram."],["While Daniel was calling for help, Sarah was talking to the guests.","Enquanto Daniel pedia ajuda, Sarah conversava com os convidados."],["The electrician arrived, checked the cables, and restored the power.","O eletricista chegou, verificou os cabos e restabeleceu a energia."]],"tip":"Use <b>past continuous</b> para o cenário e <b>past simple</b> para o que aconteceu."},{"h":"Past perfect: um acontecimento anterior","p":["O <b>past perfect</b> é formado por had + particípio passado e ajuda a indicar o que já havia ocorrido antes de outro evento passado.","A contração 'd significa had antes de um particípio: we'd tested equivale a we had tested.","Palavras como already, never e by the time podem tornar a sequência mais clara, mas nem toda ação anterior exige past perfect."],"ex":[["We had tested the equipment before the guests arrived.","Tínhamos testado o equipamento antes de os convidados chegarem."],["By the time I called, Daniel had already found a solution.","Quando liguei, Daniel já tinha encontrado uma solução."],["I'd never experienced such a stressful opening before.","Eu nunca tinha passado por uma abertura tão estressante antes."]],"tip":"Pergunte qual dos dois acontecimentos ocorreu primeiro."},{"h":"Past perfect continuous: duração anterior","p":["O <b>past perfect continuous</b> usa had been + -ing para destacar uma atividade que vinha acontecendo antes de outro momento passado.","<b>For</b> indica duração, como for two hours; <b>since</b> indica o início, como since five.","Compare had prepared, que destaca a preparação concluída, com had been preparing, que enfatiza a atividade e sua duração."],"ex":[["They had been preparing the gallery for several weeks.","Eles vinham preparando a galeria havia várias semanas."],["Sarah had been answering questions since the doors opened.","Sarah vinha respondendo a perguntas desde que as portas abriram."],["Everyone was exhausted because they had been working all afternoon.","Todos estavam exaustos porque vinham trabalhando a tarde inteira."]],"tip":"<b>Had done</b> destaca o resultado; <b>had been doing</b> enfatiza o processo."},{"h":"Organizadores de narrativas","p":["É possível começar pelo acontecimento mais interessante e depois explicar o que havia ocorrido anteriormente.","<b>At first</b> apresenta a situação inicial, <b>meanwhile</b> mostra simultaneidade, <b>by then</b> indica o que já era verdade e <b>eventually</b> introduz o desfecho.","Com <b>by the time</b>, o past perfect frequentemente esclarece qual ação se concluiu primeiro."],"ex":[["At first, nobody knew why the building was dark.","No início, ninguém sabia por que o prédio estava escuro."],["Meanwhile, the volunteers were organizing the waiting area.","Enquanto isso, os voluntários organizavam a área de espera."],["Eventually, the lights came back and the exhibition began.","Por fim, a energia voltou e a exposição começou."]],"tip":"Alterne eventos, contexto e consequências para evitar uma sequência repetitiva de then."}],"vocab":[{"h":"Eventos e imprevistos","items":[["opening","abertura; inauguração"],["exhibit","exposição"],["outage","interrupção de energia"],["power failure","falha de energia"],["backup plan","plano B"],["battery-powered","movido a bateria"],["building manager","responsável pelo prédio"],["lobby","saguão"],["delay","atraso"]]},{"h":"Narrar e explicar consequências","items":[["figure out","descobrir; compreender"],["go out","apagar; deixar de funcionar"],["go ahead","acontecer; prosseguir"],["pull together","unir esforços"],["keep someone calm","manter alguém calmo"],["earlier that week","no começo daquela semana"],["by then","a essa altura"],["eventually","por fim"],["feel relieved","sentir alívio"]]}],"pron":[{"h":"Had e a contração 'd","p":"O auxiliar <b>had</b> frequentemente vira 'd: we'd tested soa aproximadamente “uíd téstid”. Em I'd never, o início soa “áid”.","w":["had tested","we'd tested","I'd never","they'd already left"]},{"h":"Was e were conectados","p":"Em frases rápidas, <b>was</b> pode soar “uəz” e <b>were</b> pode soar “uər”. As palavras se conectam sem pausas artificiais.","w":["was working","were waiting","I was checking","we were preparing"]},{"h":"Três pronúncias de -ed","p":"A terminação -ed soa /t/ em <b>checked</b>, /d/ em <b>called</b> e /ɪd/ em <b>tested</b>, aproximadamente “téstid”.","w":["checked","called","tested","prepared"]}],"mc":[{"q":"O que Lucas fazia quando as luzes se apagaram?","o":["Ligava para o gerente","Recebia convidados na entrada","Pendurava as últimas fotografias"],"a":2,"e":"It started around six thirty. We were hanging the last photos when the lights suddenly went out."},{"q":"Por que ninguém esperava falha nas luzes?","o":["As lâmpadas tinham sido testadas","O prédio tinha gerador novo","Não haveria visitantes"],"a":0,"e":"They had, and we'd tested every lamp on Friday. That's why nobody expected a problem."},{"q":"O que provocou a queda de energia?","o":["Uma tempestade","Um eletricista desligou a energia sem querer","Os computadores superaqueceram"],"a":1,"e":"An electrician had been working next door since five, and he'd accidentally disconnected our power."},{"q":"Como os convidados reagiram à volta da energia?","o":["Saíram imediatamente","Exigiram reembolso","Comemoraram"],"a":2,"e":"They did. When the lights came back, people actually cheered. I'd never felt so relieved at an event."}],"gaps":[{"s":"We ___ the photos when the lights went out. (Use hang in the past continuous.)","a":["were hanging"],"h":"Estávamos pendurando as fotos quando as luzes se apagaram."},{"s":"We ___ every lamp before the opening. (Use test in the past perfect.)","a":["had tested","'d tested"],"h":"Nós tínhamos testado todas as lâmpadas antes da abertura."},{"s":"Sarah had been ___ guests for twenty minutes. (Use greet in the -ing form.)","a":["greeting"],"h":"Sarah recebia convidados havia vinte minutos."},{"s":"The electrician ___ the power at seven fifteen. (Use restore in the past simple.)","a":["restored"],"h":"O eletricista restabeleceu a energia às sete e quinze."},{"s":"By the time the lights came back, Sarah ___ the signs. (Use print in the past perfect.)","a":["had printed","'d printed"],"h":"Quando a energia voltou, Sarah já tinha impresso os avisos."},{"s":"They had been working ___ five o'clock. (Use the starting-point preposition.)","a":["since"],"h":"Eles estavam trabalhando desde as cinco horas."}],"order":[{"t":["The","lights","went","out","without","warning."],"h":"As luzes se apagaram sem aviso."},{"t":["We","had","already","checked","the","equipment."],"h":"Já tínhamos verificado os equipamentos."},{"t":["They","had","been","waiting","for","hours."],"h":"Eles estavam esperando havia horas."}],"dict":[{"t":"I was talking to the manager when the electrician arrived to check the cables."},{"t":"We had already tested the equipment, so the sudden power failure surprised everyone."},{"t":"Sarah had been helping the guests for nearly half an hour before the lights came back."},{"t":"By the time we found a solution, several visitors had already entered the lobby."},{"t":"Eventually, the exhibition went ahead, and everyone felt relieved after a stressful evening."}],"shadow":["It started around six thirty. We were hanging the last photos when the lights suddenly went out.","An electrician had been working next door since five, and he'd accidentally disconnected our power.","Almost. We'd been preparing the exhibit for three months, so canceling felt like the worst option.","They did. When the lights came back, people actually cheered. I'd never felt so relieved at an event."],"write":{"task":"Escreva de 7 a 9 frases sobre um imprevisto numa viagem, evento ou dia de trabalho. Use os quatro tempos narrativos, indique ações anteriores e atividades em andamento e inclua três marcadores de sequência.","ph":"Last weekend, something unexpected happened when … I was … Before that, I had already … We had been … for … Eventually, …"},"cards":[["Eu estava dirigindo quando começou a chover.","I was driving when it started raining."],["Eles já tinham saído quando chegamos.","They had already left when we arrived."],["Ela estava esperando havia mais de uma hora.","She had been waiting for over an hour."],["Ninguém sabia o que tinha acontecido.","Nobody knew what had happened."],["A reunião começou mais tarde que o previsto.","The meeting started later than planned."],["Enquanto isso, tentávamos encontrar uma solução.","Meanwhile, we were trying to find a solution."],["Nunca tinha visto algo assim antes.","I'd never seen anything like that before."],["Por fim, tudo voltou ao normal.","Eventually, everything returned to normal."],["Tínhamos trabalhado no projeto durante meses.","We had worked on the project for months."],["Quando ela ligou, eu já tinha resolvido o problema.","By the time she called, I'd already solved the problem."]]},{"title":"By This Time Next Year","goal":"Usar future continuous para atividades em andamento no futuro e future perfect para entregas concluídas até determinado prazo, estabelecendo metas e cronogramas.","speakers":{"Sarah":"f","Daniel":"m"},"setting":"Em outubro, Sarah e Daniel planejam o lançamento de uma plataforma comunitária de mentoria, incluindo piloto em janeiro e metas para o ano seguinte.","lines":[["Daniel","The pilot starts in January, but I'm worried our schedule is too optimistic. What will we be working on next month?","O projeto-piloto começa em janeiro, mas receio que nosso cronograma seja otimista demais. Em que estaremos trabalhando no mês que vem?"],["Sarah","In November, we'll be interviewing mentors and testing the sign-up page with a small group of volunteers.","Em novembro, estaremos entrevistando mentores e testando a página de inscrição com alguns voluntários."],["Daniel","And by the end of November, will we have collected enough feedback to redesign the registration form?","E até o fim de novembro, teremos recebido opiniões suficientes para reformular o formulário de inscrição?"],["Sarah","Yes, if everyone replies on time, we'll have reviewed at least forty responses before December begins.","Sim, se todos responderem no prazo, teremos analisado pelo menos quarenta respostas antes de dezembro."],["Daniel","Great. At this time in December, I hope we won't still be fixing the same basic problems.","Ótimo. A esta altura de dezembro, espero que não estejamos corrigindo os mesmos problemas básicos."],["Sarah","We won't. By December fifteenth, the developers will have finished the main features and checked accessibility.","Não estaremos. Até quinze de dezembro, os desenvolvedores terão concluído as principais funções e verificado a acessibilidade."],["Daniel","What about the training sessions? Will you be running those during the first week of January?","E as sessões de treinamento? Você estará conduzindo essas sessões na primeira semana de janeiro?"],["Sarah","I will. I'll be meeting new mentors every afternoon while Lucas handles questions from participants.","Sim. Estarei me reunindo com novos mentores todas as tardes enquanto Lucas atende às dúvidas dos participantes."],["Daniel","That sounds manageable, but we need to be honest about how much support the pilot will require.","Parece viável, mas precisamos ser realistas quanto ao suporte que o piloto exigirá."],["Sarah","Agreed. By the time the first group meets, we'll have prepared a guide and recorded short tutorials.","Concordo. Quando o primeiro grupo se reunir, já teremos preparado um guia e gravado tutoriais curtos."],["Daniel","In March, will people still be using the pilot version, or will we have switched to the full platform?","Em março, as pessoas ainda usarão a versão piloto ou já teremos migrado para a plataforma completa?"],["Sarah","We'll still be gathering data in March. We won't have launched the full platform until we've tested it properly.","Ainda estaremos coletando dados em março. Não teremos lançado a plataforma completa até testá-la adequadamente."],["Daniel","And by June, how many mentoring groups do you think we'll have created across the city?","E até junho, quantos grupos de mentoria você acha que teremos criado pela cidade?"],["Sarah","If things go well, we'll have formed ten groups, and we'll be supporting the first volunteer coordinators.","Se tudo correr bem, teremos formado dez grupos e estaremos apoiando os primeiros coordenadores voluntários."],["Daniel","By this time next year, I imagine the project will look completely different from what it is today.","A esta altura do ano que vem, imagino que o projeto estará completamente diferente do atual."],["Sarah","Definitely. We'll have expanded to more neighborhoods, and I'll be training a second team of mentors.","Com certeza. Teremos expandido para mais bairros e estarei treinando uma segunda equipe de mentores."],["Daniel","I like that. Let's put every milestone on the calendar so no deadline catches us by surprise.","Gostei. Vamos colocar cada etapa importante no calendário para que nenhum prazo nos pegue de surpresa."],["Sarah","Good idea. Tomorrow I'll be checking the budget, and by Friday I'll have sent you a revised timeline.","Boa ideia. Amanhã estarei conferindo o orçamento e, até sexta-feira, já terei enviado um cronograma revisado."]],"grammar":[{"h":"Future continuous: ações em andamento no futuro","p":["O <b>future continuous</b> usa will be + verbo com -ing para apresentar o que estará acontecendo em um momento ou período futuro.","Também descreve atividades já previstas como parte de um cronograma, sem exigir uma decisão tomada naquele instante.","A negativa é won't be + -ing; em perguntas, usamos Will + sujeito + be + -ing?"],"ex":[["This time tomorrow, I'll be reviewing the project budget.","A esta hora amanhã, estarei revisando o orçamento do projeto."],["Next week, we'll be training the first group of volunteers.","Na próxima semana, estaremos treinando o primeiro grupo de voluntários."],["Will you be attending the planning meeting on Friday?","Você estará participando da reunião de planejamento na sexta-feira?"]],"tip":"<b>Will be doing</b> destaca a atividade futura, não sua conclusão."},{"h":"Future perfect: resultados concluídos até um prazo","p":["O <b>future perfect</b> usa will have + particípio para apresentar uma ação que terá sido concluída antes de um prazo futuro.","É frequente em planejamentos, previsões e metas: By Friday, I'll have finished the report.","A forma negativa é won't have + particípio; a pergunta usa Will + sujeito + have + particípio?"],"ex":[["By December, we'll have completed the first development phase.","Até dezembro, teremos concluído a primeira fase de desenvolvimento."],["She won't have finished the training before the launch.","Ela não terá concluído o treinamento antes do lançamento."],["Will they have approved the proposal by Monday?","Eles terão aprovado a proposta até segunda-feira?"]],"tip":"Use <b>will have done</b> para destacar a entrega já realizada até um prazo."},{"h":"By e at: limite e momento específico","p":["<b>By</b> introduz um prazo-limite: a tarefa deve estar concluída até esse momento ou antes.","<b>At</b> destaca um instante, muitas vezes usado com future continuous.","<b>By this time next year</b> significa até esta época do próximo ano; <b>this time next year</b> localiza algo nessa época futura, sem destacar sua conclusão."],"ex":[["By five o'clock, I'll have sent the documents.","Até as cinco, já terei enviado os documentos."],["At five o'clock, I'll be speaking to the design team.","Às cinco, estarei conversando com a equipe de design."],["By this time next year, we'll have opened three new locations.","Até esta época do ano que vem, teremos inaugurado três unidades."]],"tip":"Compare <b>by six</b> (até as seis) e <b>at six</b> (às seis)."},{"h":"By the time, before e until","p":["<b>By the time</b> relaciona um resultado concluído com outro evento futuro. A oração principal pode estar no future perfect.","Depois de when, before e by the time, usamos normalmente um tempo presente para nos referirmos a acontecimentos futuros.","<b>Won't ... until</b> indica que algo só ocorrerá após uma condição ser atendida."],"ex":[["By the time the course starts, we'll have trained every instructor.","Quando o curso começar, já teremos treinado todos os instrutores."],["We'll have checked the system before the first users log in.","Teremos verificado o sistema antes de os primeiros usuários entrarem."],["We won't release the update until the tests are complete.","Não lançaremos a atualização até os testes estarem concluídos."]],"tip":"Diga <b>when the project starts</b>, não when the project will start, nessa construção."}],"vocab":[{"h":"Planejamento e cronogramas","items":[["milestone","marco importante"],["deadline","prazo final"],["timeline","cronograma"],["revised timeline","cronograma revisado"],["launch","lançamento; lançar"],["pilot project","projeto-piloto"],["rollout","implantação gradual"],["main features","funcionalidades principais"],["on schedule","dentro do cronograma"]]},{"h":"Resultados e execução","items":[["gather data","coletar dados"],["collect feedback","coletar avaliações"],["redesign","reformular"],["sign-up page","página de inscrição"],["training session","sessão de treinamento"],["mentor","mentor"],["volunteer coordinator","coordenador voluntário"],["accessibility","acessibilidade"],["require support","exigir suporte"]]}],"pron":[{"h":"Will e a contração 'll","p":"Will frequentemente vira <b>'ll</b>. I'll be working soa aproximadamente “áil bi uârkin”, com palavras conectadas.","w":["I'll be working","we'll be meeting","they'll have finished","she'll have sent it"]},{"h":"Have reduzido no future perfect","p":"Em will have + particípio, have costuma ser reduzido a “həv” ou “əv”. Destaque a palavra que expressa o resultado.","w":["will have finished","we'll have completed","they'll have received","I'll have checked"]},{"h":"Won't e want","p":"Won't contém um ditongo, aproximadamente “uôunt”, enquanto want no inglês americano costuma soar como “uánt”.","w":["won't","want","won't be working","won't have finished"]}],"mc":[{"q":"O que a equipe fará em novembro?","o":["Entrevistará mentores e testará inscrições","Lançará a versão final","Treinará a segunda equipe"],"a":0,"e":"In November, we'll be interviewing mentors and testing the sign-up page with a small group of volunteers."},{"q":"O que os desenvolvedores terão concluído até 15 de dezembro?","o":["Dez grupos de mentoria","A expansão total","Funções principais e verificação de acessibilidade"],"a":2,"e":"We won't. By December fifteenth, the developers will have finished the main features and checked accessibility."},{"q":"O que acontecerá em março?","o":["O piloto estará encerrado","Ainda estarão coletando dados","A segunda equipe estará completa"],"a":1,"e":"We'll still be gathering data in March. We won't have launched the full platform until we've tested it properly."},{"q":"Qual é a meta para junho?","o":["Ter dez grupos e apoiar coordenadores","Abrir dez escritórios","Encerrar o suporte"],"a":0,"e":"If things go well, we'll have formed ten groups, and we'll be supporting the first volunteer coordinators."}],"gaps":[{"s":"This time tomorrow, I'll ___ reviewing the budget. (Complete the future continuous.)","a":["be"],"h":"A esta hora amanhã, estarei revisando o orçamento."},{"s":"By December, they will have ___ the main features. (Use finish in the past participle.)","a":["finished"],"h":"Até dezembro, eles terão concluído as funções principais."},{"s":"___ Friday, we'll have sent the revised timeline. (Use the deadline preposition.)","a":["By"],"h":"Até sexta-feira, teremos enviado o cronograma revisado."},{"s":"Will you ___ meeting the team in January? (Complete the future continuous.)","a":["be"],"h":"Você estará se reunindo com a equipe em janeiro?"},{"s":"We won't release the platform ___ the tests are complete. (Use until.)","a":["until"],"h":"Não lançaremos a plataforma até a conclusão dos testes."},{"s":"By the time the course ___, we'll have trained the mentors. (Use start in the present simple.)","a":["starts"],"h":"Quando o curso começar, já teremos treinado os mentores."}],"order":[{"t":["We'll","be","working","all","afternoon."],"h":"Estaremos trabalhando a tarde inteira."},{"t":["They'll","have","finished","by","Friday."],"h":"Eles terão terminado até sexta-feira."},{"t":["Will","you","have","completed","the","training?"],"h":"Você terá concluído o treinamento?"}],"dict":[{"t":"This time next month, we'll be testing the new platform with a group of volunteers."},{"t":"By the end of December, the developers will have completed the most important features."},{"t":"Will you be working with the new mentors during the first week of January?"},{"t":"We won't have released the final version until we've checked every major issue."},{"t":"By this time next year, we'll have reached our main goals and expanded the project."}],"shadow":["In November, we'll be interviewing mentors and testing the sign-up page with a small group of volunteers.","Yes, if everyone replies on time, we'll have reviewed at least forty responses before December begins.","We'll still be gathering data in March. We won't have launched the full platform until we've tested it properly.","Definitely. We'll have expanded to more neighborhoods, and I'll be training a second team of mentors."],"write":{"task":"Escreva de 7 a 9 frases sobre trabalho ou estudo nos próximos doze meses, com três atividades futuras e três resultados concluídos até certos prazos. Use future continuous, future perfect e by the time.","ph":"This time next month, I'll be … By the end of the year, I'll have … At this time next year, I'll be …"},"cards":[["Amanhã a esta hora, estarei estudando.","This time tomorrow, I'll be studying."],["Até sexta-feira, terei terminado o relatório.","By Friday, I'll have finished the report."],["Estaremos trabalhando em um novo projeto.","We'll be working on a new project."],["Ela terá enviado os documentos até lá.","She'll have sent the documents by then."],["Você estará usando o computador à noite?","Will you be using the computer tonight?"],["Eles ainda não terão concluído os testes.","They won't have completed the tests yet."],["Até o próximo mês, teremos contratado mais pessoas.","By next month, we'll have hired more people."],["Estarei viajando durante a primeira semana.","I'll be traveling during the first week."],["Quando você chegar, já teremos começado.","By the time you arrive, we'll have started."],["Nesta época do ano que vem, estarei morando sozinho.","This time next year, I'll be living on my own."]]},{"title":"If I Had Known...","goal":"Usar third conditional e condicionais mistas para falar de arrependimentos, oportunidades perdidas, características atuais e resultados hipotéticos no passado e no presente.","speakers":{"Sarah":"f","Lucas":"m"},"setting":"Após perderem o prazo de uma inscrição para financiar uma horta comunitária, Sarah e Lucas analisam o que poderiam ter feito de outra forma.","lines":[["Lucas","I heard the garden project didn't get into this year's grant round. Did something go wrong with the application?","Ouvi que a horta ficou fora da rodada de financiamento deste ano. Algo deu errado na inscrição?"],["Sarah","We missed the deadline by twenty minutes. If I'd checked the submission rules earlier, I wouldn't have made that mistake.","Perdemos o prazo por vinte minutos. Se eu tivesse conferido as regras antes, não teria cometido esse erro."],["Lucas","Ouch. Had the website closed before you finished uploading the budget and the volunteer plan?","Nossa. O site fechou antes de você terminar de enviar o orçamento e o plano de voluntários?"],["Sarah","Yes. I'd assumed midnight meant our time zone, but the portal closed at eleven here.","Sim. Presumi que meia-noite fosse no nosso fuso horário, mas o portal fechou às onze aqui."],["Lucas","If they'd written the time zone more clearly, you might have noticed the difference sooner.","Se tivessem explicado o fuso com mais clareza, talvez você tivesse percebido antes."],["Sarah","Maybe, but I should have read the instructions twice. If I'd done that, we could have submitted everything on Friday.","Talvez, mas eu deveria ter lido as instruções duas vezes. Assim, poderíamos ter enviado tudo na sexta."],["Lucas","You were handling a lot. If I were better at spotting deadlines, I would've reminded you myself.","Você cuidava de muita coisa. Se eu fosse melhor para perceber prazos, teria lembrado você."],["Sarah","Thanks. If I hadn't agreed to organize two other events last week, I wouldn't be so exhausted now.","Obrigada. Se eu não tivesse aceitado organizar outros dois eventos na semana passada, não estaria tão exausta agora."],["Lucas","And if you weren't always trying to do everything alone, you'd have asked for help before the last day.","E se você não estivesse sempre tentando fazer tudo sozinha, teria pedido ajuda antes do último dia."],["Sarah","You're right. I kept telling myself I could finish it, even though the budget took longer than I expected.","Você tem razão. Eu dizia a mim mesma que conseguiria terminar, embora o orçamento tenha demorado mais que o esperado."],["Lucas","Would the committee have accepted a draft budget, or did every document need to be final?","A comissão teria aceitado um orçamento provisório ou tudo precisava ser definitivo?"],["Sarah","Everything had to be final. If we'd sent the incomplete version, they would have rejected it anyway.","Tudo precisava ser definitivo. Se enviássemos uma versão incompleta, eles teriam rejeitado de qualquer modo."],["Lucas","So it wasn't just about the clock. Does missing the grant mean the garden has to wait another year?","Não era só a questão do horário. Perder o financiamento significa esperar mais um ano?"],["Sarah","Not necessarily. If I'd contacted local businesses sooner, we might have some sponsorship now.","Não necessariamente. Se eu tivesse procurado empresas locais antes, talvez tivéssemos patrocínio agora."],["Lucas","We still can. If you had more confidence in your plan, you might have approached them months ago.","Ainda podemos. Se você confiasse mais no seu plano, talvez tivesse procurado as empresas meses atrás."],["Sarah","That's fair. Still, I would've felt worse if we'd given up on the garden altogether.","Justo. Ainda assim, eu teria me sentido pior se tivéssemos desistido da horta por completo."],["Lucas","Then let's split the work next time. If we'd made a checklist together, we wouldn't have missed the final step.","Vamos dividir o trabalho da próxima vez. Se tivéssemos feito uma lista juntos, não teríamos esquecido a última etapa."],["Sarah","Deal. The deadline is gone, but the project isn't. We'll keep going and apply again in the spring.","Combinado. O prazo acabou, mas o projeto não. Vamos continuar e nos inscrever na primavera."]],"grammar":[{"h":"Third conditional: imaginar outro passado","p":["O <b>third conditional</b> imagina uma situação que não aconteceu no passado e seu resultado alternativo.","Estrutura: <b>If + past perfect, would have + particípio</b>. A condição não se realizou, por isso seu resultado também é hipotético.","Podemos inverter as orações; quando if vem no início, normalmente usamos vírgula para separá-las."],"ex":[["If I'd left earlier, I would have arrived on time.","Se eu tivesse saído antes, teria chegado na hora."],["We wouldn't have lost the files if we'd saved a backup.","Não teríamos perdido os arquivos se tivéssemos feito backup."],["If she'd known about the deadline, she would've applied.","Se ela soubesse do prazo, teria se inscrito."]],"tip":"Diga <b>If I had known</b>, não If I would have known."},{"h":"Would, could e might have","p":["<b>Would have + particípio</b> apresenta a consequência esperada da hipótese.","<b>Could have</b> destaca possibilidade ou capacidade que teria existido; <b>might have</b> indica uma consequência possível, mas incerta.","Contrações como would've, could've e might've são comuns na fala e em mensagens informais."],"ex":[["If I'd studied harder, I would have passed the exam.","Se tivesse estudado mais, teria passado na prova."],["If we'd had more time, we could have improved the proposal.","Com mais tempo, poderíamos ter melhorado a proposta."],["If she'd checked her email, she might have seen the warning.","Se ela tivesse conferido o e-mail, talvez tivesse visto o aviso."]],"tip":"<b>Would have</b> é mais assertivo; <b>might have</b> é mais cauteloso."},{"h":"Passado diferente, presente diferente","p":["Uma condicional mista combina períodos: uma condição passada que não ocorreu e uma consequência imaginada no presente.","Estrutura frequente: <b>If + past perfect, would + verbo base</b>. Também podemos usar would be + -ing para uma situação atual em andamento.","O contraste temporal fica claro por expressões como now e today."],"ex":[["If I'd saved more money, I'd have less debt now.","Se eu tivesse economizado mais, teria menos dívidas agora."],["If she'd taken that job, she'd be living abroad today.","Se tivesse aceitado o emprego, estaria morando no exterior hoje."],["If we hadn't missed the deadline, we might have funding now.","Se não tivéssemos perdido o prazo, talvez tivéssemos financiamento agora."]],"tip":"A condição refere-se ao <b>passado</b> e o resultado ao <b>presente</b>."},{"h":"Característica atual, resultado passado","p":["Outra condicional mista usa <b>If + past simple, would have + particípio</b> quando uma característica atual ou geral poderia ter modificado um acontecimento anterior.","Embora a condição esteja gramaticalmente no passado, descreve uma situação hipotética atual.","Para hipóteses, were é uma escolha segura com todos os sujeitos; was também aparece na fala informal."],"ex":[["If I were more patient, I wouldn't have argued with him yesterday.","Se eu fosse mais paciente, não teria discutido com ele ontem."],["If she spoke French, she could have helped us during the trip.","Se ela falasse francês, poderia ter nos ajudado na viagem."],["If we had a bigger team, we might have finished sooner.","Com uma equipe maior, talvez tivéssemos terminado antes."]],"tip":"Identifique os dois momentos: <b>característica atual</b> e <b>resultado passado</b>."}],"vocab":[{"h":"Prazos e inscrições","items":[["miss a deadline","perder um prazo"],["grant","financiamento; verba"],["grant round","rodada de financiamento"],["application","inscrição; candidatura"],["submission rules","regras de envio"],["time zone","fuso horário"],["draft budget","orçamento provisório"],["apply for funding","solicitar financiamento"],["checklist","lista de verificação"]]},{"h":"Arrependimento e oportunidades","items":[["regret","arrependimento; arrepender-se"],["make a mistake","cometer um erro"],["take responsibility","assumir a responsabilidade"],["give up","desistir"],["handle a lot","lidar com muita coisa"],["spot a problem","identificar problema"],["approach a business","procurar uma empresa"],["sponsorship","patrocínio"],["split the work","dividir o trabalho"]]}],"pron":[{"h":"Would've, could've e might've","p":"As terminações de <b>would've</b>, <b>could've</b> e <b>might've</b> soam aproximadamente “əv”. Não escreva of no lugar de have.","w":["would've","could've","might've","I would've called"]},{"h":"Had abreviado nas condições","p":"Em <b>If I'd known</b>, had vira 'd e a sequência soa aproximadamente “if aid nôun”. O particípio indica o significado de 'd.","w":["If I'd known","If we'd checked","If she'd arrived","If they hadn't left"]},{"h":"Wouldn't have na fala rápida","p":"Em <b>wouldn't have</b>, have costuma ficar reduzido; a sequência soa aproximadamente “uúdnt-əv”.","w":["wouldn't have","couldn't have","wouldn't have missed","I wouldn't have agreed"]}],"mc":[{"q":"Por quanto Sarah perdeu o prazo?","o":["Duas horas","Vinte minutos","Um dia"],"a":1,"e":"We missed the deadline by twenty minutes. If I'd checked the submission rules earlier, I wouldn't have made that mistake."},{"q":"Que interpretação causou o erro?","o":["Pensou que faltasse um documento","Achou que o prazo fosse amanhã","Presumiu que o horário era do seu fuso"],"a":2,"e":"Yes. I'd assumed midnight meant our time zone, but the portal closed at eleven here."},{"q":"Por que Sarah está tão cansada?","o":["Aceitou outros dois eventos","Passou a noite viajando","Perdeu todos os arquivos"],"a":0,"e":"Thanks. If I hadn't agreed to organize two other events last week, I wouldn't be so exhausted now."},{"q":"O que decidiram ao final?","o":["Abandonar a horta","Continuar e tentar novamente na primavera","Enviar uma versão incompleta"],"a":1,"e":"Deal. The deadline is gone, but the project isn't. We'll keep going and apply again in the spring."}],"gaps":[{"s":"If I'd checked the rules, I ___ have missed the deadline. (Use the negative of would.)","a":["wouldn't","would not"],"h":"Se eu tivesse conferido as regras, não teria perdido o prazo."},{"s":"If we'd ___ earlier, we would have arrived on time. (Use leave in the past participle.)","a":["left"],"h":"Se tivéssemos saído antes, teríamos chegado no horário."},{"s":"If she'd known, she ___ have applied. (Use might for uncertainty.)","a":["might"],"h":"Se ela soubesse, talvez tivesse se inscrito."},{"s":"If I hadn't accepted so much work, I ___ be exhausted now. (Use the negative of would.)","a":["wouldn't","would not"],"h":"Se eu não tivesse aceitado tanto trabalho, não estaria exausto agora."},{"s":"If I ___ more organized, I would've finished yesterday. (Use were.)","a":["were"],"h":"Se eu fosse mais organizado, teria terminado ontem."},{"s":"If we'd made a checklist, we could have ___ the mistake. (Use avoid in the past participle.)","a":["avoided"],"h":"Se tivéssemos feito uma lista, poderíamos ter evitado o erro."}],"order":[{"t":["If","I'd","known,","I","would've","helped."],"h":"Se eu soubesse, teria ajudado."},{"t":["We","could","have","finished","much","earlier."],"h":"Poderíamos ter terminado muito antes."},{"t":["If","I'd","practiced,","I'd","feel","confident","now."],"h":"Se eu tivesse praticado, estaria confiante agora."}],"dict":[{"t":"If I'd checked the deadline more carefully, I wouldn't have missed the opportunity."},{"t":"We could have submitted the application earlier if we'd completed the budget on Friday."},{"t":"If she had more confidence, she might have spoken to the committee yesterday."},{"t":"If I hadn't accepted so many responsibilities, I wouldn't be feeling so tired today."},{"t":"I would've asked for help if I'd realized how complicated the process was going to be."}],"shadow":["We missed the deadline by twenty minutes. If I'd checked the submission rules earlier, I wouldn't have made that mistake.","Maybe, but I should have read the instructions twice. If I'd done that, we could have submitted everything on Friday.","Thanks. If I hadn't agreed to organize two other events last week, I wouldn't be so exhausted now.","Not necessarily. If I'd contacted local businesses sooner, we might have some sponsorship now."],"write":{"task":"Escreva de 7 a 9 frases sobre uma decisão passada que faria de outra maneira. Use duas third conditionals, duas condicionais mistas, would have, could have e might have.","ph":"A few months ago, I … If I'd known …, I would've … If I'd prepared better, I could've … Things might be different now if …"},"cards":[["Se eu soubesse, teria ligado para você.","If I'd known, I would've called you."],["Eu não teria aceitado aquela proposta.","I wouldn't have accepted that offer."],["Poderíamos ter evitado o problema.","We could have avoided the problem."],["Talvez ela tivesse mudado de ideia.","She might have changed her mind."],["Se eu tivesse estudado mais, estaria preparado agora.","If I'd studied more, I'd be prepared now."],["Se ele fosse mais cuidadoso, teria percebido o erro.","If he were more careful, he would've noticed the mistake."],["Eu teria saído mais cedo se soubesse do trânsito.","I'd have left earlier if I'd known about the traffic."],["Se tivéssemos economizado, teríamos mais dinheiro agora.","If we'd saved money, we'd have more now."],["Eles teriam ajudado se você tivesse pedido.","They would've helped if you'd asked."],["Se eu tivesse mais experiência, poderia ter conseguido o emprego.","If I had more experience, I could've gotten the job."]]},{"title":"I Wish Things Were Different","goal":"Expressar desejos presentes, arrependimentos passados, incômodos e preferências com wish, if only, would rather e it's time.","speakers":{"Sarah":"f","Emma":"f"},"setting":"Na quinta-feira, Sarah conversa com Emma, que está frustrada com o deslocamento e os horários imprevisíveis de seu novo emprego.","lines":[["Sarah","You looked exhausted when you got off the train. Is the new job still taking up most of your day?","Você parecia exausta quando saiu do trem. O novo trabalho ainda toma quase todo seu dia?"],["Emma","Unfortunately, yes. I wish I didn't spend nearly two hours commuting every day. It's wearing me out.","Infelizmente, sim. Queria não gastar quase duas horas no deslocamento diário. Isso está me esgotando."],["Sarah","Two hours? That's rough. If only you lived a little closer to the office, you'd have more free time.","Duas horas? Que difícil. Se morasse mais perto do escritório, teria mais tempo livre."],["Emma","Exactly. I'd rather work from home a couple of days a week, but my manager isn't very flexible.","Exatamente. Preferia trabalhar de casa alguns dias por semana, mas minha gerente é pouco flexível."],["Sarah","Didn't you discuss the remote work policy before accepting the offer? I thought flexibility mattered to you.","Vocês não discutiram a política de trabalho remoto antes da proposta? Achei que flexibilidade importasse para você."],["Emma","I wish I'd asked more questions during the interview. I was so excited about the salary that I overlooked the details.","Queria ter perguntado mais durante a entrevista. Fiquei tão animada com o salário que ignorei detalhes."],["Sarah","Well, you couldn't have predicted everything. Has the situation changed since your first week?","Você não poderia ter previsto tudo. A situação mudou desde a primeira semana?"],["Emma","It has. If only I hadn't assumed the schedule would stay the same. They keep changing our shifts at the last minute.","Mudou. Se eu não tivesse presumido que os turnos continuariam iguais! Eles vivem mudando tudo de última hora."],["Sarah","I imagine you'd rather your manager gave everyone more notice before changing shifts.","Imagino que você preferisse que a gerente avisasse as mudanças com mais antecedência."],["Emma","Absolutely. And I wish the trains would run on time for once. Yesterday I missed dinner with my family again.","Com certeza. E queria que os trens chegassem no horário ao menos uma vez. Ontem perdi outro jantar com a família."],["Sarah","Maybe it's time you had an honest conversation with your manager. She might not realize how much this affects you.","Talvez esteja na hora de uma conversa franca com sua gerente. Talvez ela não perceba o quanto isso afeta você."],["Emma","You're right. It's high time we sorted out the schedule. Everyone on the team has been complaining about it.","Tem razão. Já passou da hora de resolver os horários. Toda a equipe está reclamando."],["Sarah","Would you rather talk to her privately or bring it up during the team meeting next Monday?","Você preferiria falar em particular ou abordar isso na reunião da equipe na segunda?"],["Emma","I'd rather speak to her privately first. I don't want her to feel like we're putting her on the spot.","Preferia falar em particular primeiro. Não quero colocá-la contra a parede."],["Sarah","That makes sense. Just explain what you need instead of focusing only on what's going wrong.","Faz sentido. Explique o que precisa, em vez de focar só no que está errado."],["Emma","I wish I could leave the office a little earlier on Fridays. Even that would make a difference.","Queria poder sair um pouco mais cedo às sextas. Até isso faria diferença."],["Sarah","And if nothing changes, would you rather stay and adapt or start looking for another position?","E, se nada mudar, prefere ficar e se adaptar ou procurar outro emprego?"],["Emma","I'd rather give this job another chance. I like the work itself. I just wish I'd spoken up sooner.","Prefiro dar outra chance ao emprego. Gosto do trabalho em si. Só queria ter me manifestado antes."]],"grammar":[{"h":"Wish e if only + past simple","p":["<b>Wish + past simple</b> expressa um desejo contrário à realidade presente, apesar de usar uma forma do passado.","<b>If only</b> tem significado parecido, mas frequentemente expressa um sentimento mais intenso ou uma frustração.","Com be, were é tradicional em hipóteses com todas as pessoas; was também ocorre informalmente."],"ex":[["I wish I had more time to spend with my family.","Queria ter mais tempo para minha família."],["If only my apartment were closer to the office.","Se pelo menos meu apartamento fosse mais perto do escritório."],["She wishes she didn't have to work every weekend.","Ela queria não precisar trabalhar todo fim de semana."]],"tip":"Para um desejo sobre hoje, diga <b>I wish I had</b>, não I wish I have."},{"h":"Wish e if only + past perfect","p":["<b>Wish + had + particípio</b> expressa arrependimento por decisões ou acontecimentos passados que não podem ser modificados.","Compare I wish I knew (gostaria de saber agora) com I wish I'd known (gostaria de ter sabido antes).","If only intensifica a emoção e pode indicar tristeza, frustração ou arrependimento."],"ex":[["I wish I'd read the contract more carefully.","Queria ter lido o contrato com mais cuidado."],["If only we hadn't booked such an early flight.","Se pelo menos não tivéssemos reservado um voo tão cedo."],["He wishes he'd accepted the opportunity last year.","Ele queria ter aceitado a oportunidade no ano passado."]],"tip":"<b>Wish + past perfect</b> olha para trás; wish + past simple fala normalmente do presente."},{"h":"Wish + would: incômodos e mudanças desejadas","p":["<b>Wish + would + verbo base</b> destaca a vontade de que outra pessoa ou situação mude seu comportamento.","É comum expressar impaciência com ações repetidas, como atrasos, interrupções ou barulho.","Para mudanças que dependem diretamente da nossa própria decisão, I wish I could ou I wish I were costuma ser mais natural do que I wish I would."],"ex":[["I wish the buses would arrive on time.","Queria que os ônibus chegassem no horário."],["She wishes her coworkers would stop interrupting her.","Ela queria que os colegas parassem de interrompê-la."],["If only the company would listen to our suggestions.","Se pelo menos a empresa ouvisse nossas sugestões."]],"tip":"Use <b>wish + would</b> principalmente para desejar mudança de comportamento."},{"h":"Would rather e it's time","p":["<b>Would rather + verbo base</b> expressa preferência pessoal e permite comparações com than.","Para indicar o que preferimos que outra pessoa faça, use <b>would rather + pessoa + past simple</b>.","<b>It's time + sujeito + past simple</b> indica que algo já deveria acontecer; <b>it's high time</b> é uma versão mais enfática.","Também podemos usar it's time to + verbo."],"ex":[["I'd rather stay home than go out tonight.","Preferia ficar em casa a sair hoje."],["I'd rather you told me about changes in advance.","Preferia que você me avisasse antes sobre as mudanças."],["It's high time we discussed the working conditions.","Já passou da hora de discutirmos as condições de trabalho."]],"tip":"Compare <b>I'd rather leave</b> e <b>I'd rather you left</b>."}],"vocab":[{"h":"Trabalho e flexibilidade","items":[["commute","deslocamento casa-trabalho"],["remote work policy","política de trabalho remoto"],["shift","turno"],["flexible schedule","horário flexível"],["job offer","proposta de emprego"],["working conditions","condições de trabalho"],["give notice","avisar com antecedência"],["bring something up","tocar em um assunto"],["speak up","manifestar-se"]]},{"h":"Frustração e decisões","items":[["wear someone out","esgotar alguém"],["overlook","deixar passar"],["put someone on the spot","colocar alguém contra a parede"],["sort something out","resolver uma questão"],["make a difference","fazer diferença"],["give something another chance","dar outra chance"],["at the last minute","em cima da hora"],["predict","prever"],["adapt","adaptar-se"]]}],"pron":[{"h":"Wish e wishes","p":"Wish termina no som /ʃ/, como “ch”. Wishes acrescenta uma sílaba, aproximadamente “uí-shiz”.","w":["wish","wishes","I wish","she wishes"]},{"h":"Would rather","p":"O L é mudo em would; I'd rather começa aproximadamente como “áid”. O TH de rather é sonoro /ð/.","w":["would","wouldn't","I'd rather","would rather stay"]},{"h":"If only conectado","p":"If only soa aproximadamente “if ôunli”. Em if only I'd known, a contração 'd fica ligada à palavra seguinte.","w":["if only","if only I knew","if only I'd known","if only we lived closer"]}],"mc":[{"q":"O que esgota Emma?","o":["A viagem de trabalho","O deslocamento diário longo","As tarefas que ela não gosta"],"a":1,"e":"Unfortunately, yes. I wish I didn't spend nearly two hours commuting every day. It's wearing me out."},{"q":"Do que ela se arrepende sobre a entrevista?","o":["De pedir salário baixo","De recusar férias","De não perguntar mais sobre as condições"],"a":2,"e":"I wish I'd asked more questions during the interview. I was so excited about the salary that I overlooked the details."},{"q":"Como prefere conversar com a gerente?","o":["Em particular","Numa reclamação anônima","Durante uma reunião pública"],"a":0,"e":"I'd rather speak to her privately first. I don't want her to feel like we're putting her on the spot."},{"q":"O que fará com o emprego?","o":["Pedirá demissão amanhã","Dará outra chance","Aceitará os problemas para sempre"],"a":1,"e":"I'd rather give this job another chance. I like the work itself. I just wish I'd spoken up sooner."}],"gaps":[{"s":"I wish I ___ closer to the office. (Use live in the past simple.)","a":["lived"],"h":"Queria morar mais perto do escritório."},{"s":"I wish I'd ___ more questions during the interview. (Use ask in the participle.)","a":["asked"],"h":"Queria ter feito mais perguntas na entrevista."},{"s":"I wish the trains ___ arrive on time. (Use would.)","a":["would","'d"],"h":"Queria que os trens chegassem no horário."},{"s":"I'd rather ___ from home twice a week. (Use work in the base form.)","a":["work"],"h":"Preferia trabalhar de casa duas vezes por semana."},{"s":"I'd rather you ___ me earlier. (Use tell in the past simple.)","a":["told"],"h":"Preferia que você me avisasse antes."},{"s":"It's high time we ___ the schedule. (Use review in the past simple.)","a":["reviewed"],"h":"Já passou da hora de revisarmos os horários."}],"order":[{"t":["I","wish","I","had","more","free","time."],"h":"Queria ter mais tempo livre."},{"t":["I'd","rather","work","from","home","tomorrow."],"h":"Preferia trabalhar de casa amanhã."},{"t":["It's","time","we","made","a","decision."],"h":"Já está na hora de tomarmos uma decisão."}],"dict":[{"t":"I wish I'd asked about the working conditions before I accepted the job."},{"t":"If only the company would give us more notice before changing our shifts."},{"t":"I'd rather speak to my manager privately than complain during the team meeting."},{"t":"It's high time we found a better solution to these scheduling problems."},{"t":"She wishes she could spend more time with her family instead of commuting every day."}],"shadow":["Unfortunately, yes. I wish I didn't spend nearly two hours commuting every day. It's wearing me out.","I wish I'd asked more questions during the interview. I was so excited about the salary that I overlooked the details.","Absolutely. And I wish the trains would run on time for once. Yesterday I missed dinner with my family again.","I'd rather speak to her privately first. I don't want her to feel like we're putting her on the spot."],"write":{"task":"Escreva de 7 a 9 frases sobre aspectos da sua rotina que gostaria de mudar, com dois desejos presentes, dois arrependimentos, wish + would, would rather e it's time.","ph":"I wish I had more time to … If only I didn't have to … I wish I'd … I'd rather … It's time I …"},"cards":[["Queria ter mais confiança ao falar inglês.","I wish I were more confident speaking English."],["Se pelo menos eu tivesse aceitado aquele convite.","If only I'd accepted that invitation."],["Queria que eles parassem de fazer barulho.","I wish they'd stop making so much noise."],["Preferia não trabalhar neste sábado.","I'd rather not work this Saturday."],["Já está na hora de procurarmos uma solução.","It's time we looked for a solution."],["Preferia que você ficasse aqui.","I'd rather you stayed here."],["Ela queria ter estudado outro curso.","She wishes she'd studied a different course."],["Se pelo menos o tempo estivesse melhor.","If only the weather were better."],["Já passou da hora de mudarmos nossos hábitos.","It's high time we changed our habits."],["Queria poder tirar alguns dias de folga.","I wish I could take a few days off."]]},{"title":"Getting Things Done","goal":"Descrever serviços contratados usando have/get something done e relatar informações atribuídas a fontes por meio da passiva impessoal.","speakers":{"Lucas":"m","Daniel":"m"},"setting":"Lucas visita o espaço comunitário que Daniel está reformando e conhece os serviços contratados e a história do prédio.","lines":[["Lucas","Wow, this place looks completely different from last month. Did you and your team do all the renovations yourselves?","Nossa, o lugar parece completamente diferente. Vocês mesmos fizeram toda a reforma?"],["Daniel","Not at all. We had the walls repainted last week, and we're getting the floors polished tomorrow morning.","De jeito nenhum. Mandamos repintar as paredes e amanhã mandaremos polir os pisos."],["Lucas","That makes sense. The lighting looks much better too. Did you have the old fixtures replaced?","Faz sentido. A iluminação também melhorou. Mandou trocar as luminárias antigas?"],["Daniel","Yes. We had a local electrician install new lights, and we got a specialist to check the wiring.","Sim. Pedimos a um eletricista para instalar luzes novas e contratamos um especialista para verificar a fiação."],["Lucas","Smart move. What about the entrance? Are you planning to have the old sign removed?","Boa decisão. E a entrada? Pretende mandar retirar a placa antiga?"],["Daniel","We've already had it removed. We're getting a new sign made, but the designer needs another three days.","Já mandamos retirá-la. Estamos encomendando uma placa nova, mas o designer precisa de três dias."],["Lucas","I noticed the air conditioning is running quietly. Have you had the system serviced recently?","Notei que o ar-condicionado está silencioso. Mandou fazer manutenção recentemente?"],["Daniel","We had it checked on Monday. Luckily, nothing needed replacing, so the technician just cleaned the filters.","Mandamos verificar na segunda. Felizmente, nada precisava de troca e o técnico só limpou os filtros."],["Lucas","Someone told me this building used to be a publishing house. Is that actually true?","Ouvi dizer que o prédio abrigava uma editora. É verdade?"],["Daniel","It is said that the building was used for printing and publishing decades ago. We found some old records.","Dizem que o prédio era usado para impressão e publicação décadas atrás. Encontramos registros antigos."],["Lucas","Interesting. And that wooden staircase looks original. Is it part of the building's history?","Interessante. E aquela escada de madeira parece original. Faz parte da história do prédio?"],["Daniel","Yes. The staircase is believed to date back to the 1930s, so we're having the wood carefully restored.","Sim. Acredita-se que seja da década de 1930, então estamos mandando restaurar a madeira."],["Lucas","I'm glad you're keeping those details. Are you building the new website yourselves, or hiring someone?","Que bom que estão preservando os detalhes. Vocês mesmos farão o site ou contratarão alguém?"],["Daniel","We're getting Emma to update the website. We'll also have professional photos taken once the rooms are ready.","Vamos pedir a Emma que atualize o site. Também mandaremos tirar fotos profissionais quando as salas estiverem prontas."],["Lucas","Good idea. What still needs to be done before you can officially open the space?","Boa ideia. O que ainda precisa ser feito antes de abrir oficialmente?"],["Daniel","We need to have the fire alarms tested and the entrance inspected by Friday. Safety comes first.","Precisamos mandar testar os alarmes e inspecionar a entrada até sexta. Segurança em primeiro lugar."],["Lucas","Absolutely. It's reassuring to see that you're getting qualified people to handle the technical work.","Com certeza. É tranquilizador ver profissionais qualificados cuidando da parte técnica."],["Daniel","Thanks. We could've tried to do everything ourselves, but I'd rather have the important work done properly.","Obrigado. Poderíamos ter tentado fazer tudo, mas prefiro mandar executar corretamente os serviços importantes."]],"grammar":[{"h":"Have something done: providenciar um serviço","p":["A estrutura <b>have + objeto + particípio</b> indica que providenciamos para outra pessoa realizar um serviço.","Compare I repaired my laptop (eu fiz o conserto) com I had my laptop repaired (mandei consertar).","Have muda com o tempo verbal, mas o particípio do serviço continua: had my car washed, will have it repaired, have had it fixed."],"ex":[["I had my laptop repaired last Friday.","Mandei consertar o notebook na sexta."],["We're having the office painted this week.","Estamos mandando pintar o escritório."],["She'll have the documents translated before the meeting.","Ela mandará traduzir os documentos antes da reunião."]],"tip":"<b>Had something done</b> não significa necessariamente que você fez pessoalmente."},{"h":"Get something done: conseguir que um serviço seja feito","p":["<b>Get + objeto + particípio</b> geralmente também indica que conseguimos ou providenciamos um serviço, sendo frequente na fala.","Podemos dizer got my phone fixed, am getting the windows cleaned ou will get it repaired.","Em certos contextos have/get something done descreve um acontecimento involuntário, como He had his wallet stolen."],"ex":[["I'm getting my phone screen replaced tomorrow.","Vou mandar trocar a tela do celular amanhã."],["We got the conference room cleaned before the event.","Mandamos limpar a sala de conferências antes do evento."],["They've finally gotten their heating system repaired.","Finalmente conseguiram mandar consertar o aquecimento."]],"tip":"<b>Gotten</b> é particípio de get comum em inglês americano."},{"h":"Have someone do e get someone to do","p":["Podemos mencionar diretamente o profissional contratado ou encarregado do serviço.","Com <b>have + pessoa + verbo base</b>, indicamos que pedimos ou organizamos a ação.","Com <b>get + pessoa + to + verbo</b>, frequentemente destacamos que conseguimos que alguém agisse. Compare com have/get + objeto + particípio."],"ex":[["We had the electrician install new lights.","Pedimos ao eletricista que instalasse novas luzes."],["I got my colleague to review the proposal.","Consegui que meu colega revisasse a proposta."],["She had her assistant arrange the appointments.","Ela pediu ao assistente que organizasse os compromissos."]],"tip":"Decore <b>have someone do</b>, <b>get someone to do</b> e <b>get something done</b>."},{"h":"Passiva impessoal: it is said that e is believed to","p":["Notícias e comunicações formais apresentam informações sem especificar a fonte por meio de <b>It is said that...</b> ou <b>It is believed that...</b>.","Outra estrutura inicia com o assunto: <b>The building is said to be...</b>, <b>She is believed to...</b>.","São relatos atribuídos a terceiros, não necessariamente fatos verificados. Também usamos is thought to, is reported to e is expected to."],"ex":[["It is said that the building is over eighty years old.","Dizem que o prédio tem mais de oitenta anos."],["The architect is believed to work with sustainable materials.","Acredita-se que o arquiteto trabalhe com materiais sustentáveis."],["The new center is expected to open next month.","Espera-se que o centro inaugure no mês que vem."]],"tip":"<b>It is said that...</b> e <b>He is said to...</b> expressam relatos sem nomear a fonte."}],"vocab":[{"h":"Reformas e instalações","items":[["renovation","reforma"],["fixture","peça fixa; luminária"],["wiring","fiação elétrica"],["polish","polir"],["restore","restaurar"],["replace","substituir"],["service","fazer manutenção"],["inspection","vistoria"],["fire alarm","alarme de incêndio"]]},{"h":"Serviços e profissionais","items":[["hire a specialist","contratar um especialista"],["qualified professional","profissional qualificado"],["handle technical work","cuidar dos serviços técnicos"],["get something fixed","mandar consertar"],["have something installed","mandar instalar"],["have something inspected","mandar inspecionar"],["have photos taken","mandar tirar fotos"],["in advance","com antecedência"],["properly","corretamente"]]}],"pron":[{"h":"Have e had conectados","p":"Have pode ter uma vogal reduzida em fala rápida. Em had it checked, o D de had se liga a it.","w":["have it repaired","had it checked","have the walls painted","had the lights installed"]},{"h":"Get e gotten americanos","p":"No inglês americano, o T de <b>gotten</b> frequentemente soa como D rápido; a pronúncia aproximada é “gá-dən”.","w":["get","got","gotten","get it done"]},{"h":"Said e believed","p":"Said soa “séd”, believed soa “bilíivd” e expected soa “ikspéktid”. A sequência is believed to não exige pausa.","w":["is said to","is believed to","is expected to","is reported to"]}],"mc":[{"q":"Quem fez a maior parte das reformas?","o":["Apenas a equipe interna","Profissionais contratados","Os moradores do bairro"],"a":1,"e":"Not at all. We had the walls repainted last week, and we're getting the floors polished tomorrow morning."},{"q":"O que aconteceu com o ar-condicionado?","o":["Foi verificado e limpo","Foi inteiramente substituído","Foi retirado do local"],"a":0,"e":"We had it checked on Monday. Luckily, nothing needed replacing, so the technician just cleaned the filters."},{"q":"Qual a época provável da escada?","o":["Reforma atual","Depois de 2000","Década de 1930"],"a":2,"e":"Yes. The staircase is believed to date back to the 1930s, so we're having the wood carefully restored."},{"q":"O que precisa ser feito até sexta?","o":["Tirar fotos e lançar o site","Testar alarmes e inspecionar entrada","Instalar todos os móveis"],"a":1,"e":"We need to have the fire alarms tested and the entrance inspected by Friday. Safety comes first."}],"gaps":[{"s":"We had the walls ___ last week. (Use repaint in the past participle.)","a":["repainted"],"h":"Mandamos repintar as paredes na semana passada."},{"s":"I'm getting my laptop ___ tomorrow. (Use repair in the participle.)","a":["repaired"],"h":"Vou mandar consertar o notebook amanhã."},{"s":"We had the electrician ___ the lights. (Use install in the base form.)","a":["install"],"h":"Pedimos ao eletricista que instalasse as luzes."},{"s":"I got a specialist ___ inspect the wiring. (Complete get + person.)","a":["to"],"h":"Consegui que um especialista verificasse a fiação."},{"s":"It is ___ that the building is old. (Use say in the participle.)","a":["said"],"h":"Dizem que o prédio é antigo."},{"s":"The center is believed ___ have excellent facilities. (Complete the passive structure.)","a":["to"],"h":"Acredita-se que o centro tenha ótimas instalações."}],"order":[{"t":["We","had","the","windows","cleaned","yesterday."],"h":"Mandamos limpar as janelas ontem."},{"t":["She","got","her","phone","screen","replaced."],"h":"Ela mandou trocar a tela do celular."},{"t":["The","building","is","believed","to","be","historic."],"h":"Acredita-se que o prédio seja histórico."}],"dict":[{"t":"We had the walls repainted and the electrical system checked before the opening."},{"t":"I'm getting my laptop repaired because the screen stopped working last night."},{"t":"They had a professional photographer take pictures of the renovated meeting rooms."},{"t":"It is believed that the old staircase is one of the building's original features."},{"t":"The new community center is expected to open as soon as the final inspections are complete."}],"shadow":["Not at all. We had the walls repainted last week, and we're getting the floors polished tomorrow morning.","Yes. We had a local electrician install new lights, and we got a specialist to check the wiring.","Yes. The staircase is believed to date back to the 1930s, so we're having the wood carefully restored.","We're getting Emma to update the website. We'll also have professional photos taken once the rooms are ready."],"write":{"task":"Escreva de 7 a 9 frases sobre a reforma de uma casa ou escritório. Explique serviços já realizados, próximos serviços e profissionais responsáveis, usando have/get something done e uma passiva impessoal.","ph":"I'm renovating … Last week, I had … I'm getting … done next week. I got a specialist to … The building is said to …"},"cards":[["Mandei cortar meu cabelo ontem.","I had my hair cut yesterday."],["Vou mandar consertar meu celular.","I'm going to get my phone fixed."],["Mandamos instalar um sistema de segurança.","We had a security system installed."],["Ela vai mandar pintar o quarto.","She'll have her bedroom painted."],["Preciso mandar revisar meu carro.","I need to have my car serviced."],["Conseguimos que um técnico verificasse o equipamento.","We got a technician to check the equipment."],["Pedi ao assistente que reservasse a sala.","I had my assistant book the room."],["Dizem que o restaurante é muito popular.","It is said that the restaurant is very popular."],["Acredita-se que ela seja excelente profissional.","She is believed to be an excellent professional."],["Espera-se que o projeto termine em dezembro.","The project is expected to finish in December."]]},{"title":"He Denied It","goal":"Relatar sugestões, avisos, negativas, confissões, recusas e promessas usando suggest, warn, deny, admit, refuse e promise com as estruturas apropriadas.","speakers":{"Sarah":"f","Daniel":"m"},"setting":"Sarah e Daniel resolvem mensagens desencontradas antes de uma oficina comunitária, revisando comunicação e responsabilidades.","lines":[["Sarah","Have you heard that several volunteers were given the wrong starting time for tomorrow's workshop?","Você soube que vários voluntários receberam o horário errado para a oficina de amanhã?"],["Daniel","Yes. Lucas admitted sending the old schedule, but he denied ignoring the update on purpose.","Sim. Lucas admitiu enviar o cronograma antigo, mas negou ignorar a atualização de propósito."],["Sarah","Did he explain why he hadn't checked the shared calendar before sending the file?","Ele explicou por que não tinha conferido o calendário compartilhado antes de enviar?"],["Daniel","He said he'd been working offline and promised to double-check everything before sending another message.","Ele disse que trabalhava sem internet e prometeu conferir tudo duas vezes antes de enviar outra mensagem."],["Sarah","I suggested adding a date to every email subject line so people can identify the latest version.","Sugeri colocar a data no assunto de cada e-mail para identificarem a última versão."],["Daniel","Good idea. Emma also suggested that we keep one master schedule instead of making separate copies.","Boa ideia. Emma também sugeriu mantermos um só cronograma principal, sem cópias."],["Sarah","Exactly. I warned the team not to forward screenshots because the information could become outdated.","Exatamente. Avisei a equipe para não encaminhar capturas de tela que poderiam ficar desatualizadas."],["Daniel","Emma warned us that some participants might arrive early if we didn't correct the message immediately.","Emma alertou que alguns participantes poderiam chegar cedo se não corrigíssemos a mensagem imediatamente."],["Sarah","Did anyone refuse to change their shift after finding out about the correct starting time?","Alguém se recusou a trocar de turno depois de conhecer o horário correto?"],["Daniel","Two volunteers refused to switch, but they offered to stay later and help clean up after the workshop.","Dois voluntários se recusaram a trocar, mas ofereceram ajuda na limpeza após a oficina."],["Sarah","That's reasonable. Did Lucas admit making the mistake in the group chat, or did he tell people privately?","Compreensível. Lucas admitiu o erro no grupo ou falou em particular?"],["Daniel","He admitted that he'd attached the wrong file and apologized without blaming anyone else.","Ele admitiu ter anexado o arquivo errado e pediu desculpas sem culpar ninguém."],["Sarah","I appreciate that. We should avoid turning a simple communication mistake into a personal argument.","Valorizo isso. Devemos evitar transformar um erro simples de comunicação numa briga pessoal."],["Daniel","Agreed. I suggested reviewing our communication process after the workshop instead of discussing it now.","Concordo. Sugeri revisar nosso processo de comunicação depois da oficina em vez de discutir agora."],["Sarah","And what did Emma say about contacting the volunteers who still haven't confirmed their attendance?","E o que Emma disse sobre procurar os voluntários que ainda não confirmaram presença?"],["Daniel","She promised to call them personally, and she warned me to keep the correction message short and clear.","Ela prometeu ligar pessoalmente e me recomendou manter a correção curta e clara."],["Sarah","Perfect. I'll suggest using a checklist at our next meeting and remind everyone to check the shared calendar.","Perfeito. Vou sugerir uma lista de verificação na próxima reunião e lembrar todos do calendário."],["Daniel","Thanks. If we stick to one schedule and communicate clearly, we won't spend another morning fixing mixed messages.","Obrigado. Se seguirmos um cronograma e falarmos claramente, não perderemos outra manhã corrigindo desencontros."]],"grammar":[{"h":"Suggest + -ing ou oração com that","p":["<b>Suggest + -ing</b> introduz uma ação sugerida sem to: I suggested checking.","Também podemos usar <b>suggest that + sujeito + verbo</b>. No inglês americano, o verbo na forma base é frequente, sobretudo formalmente: I suggest that he check.","Para mencionar o destinatário, use suggest something to someone; a estrutura suggest someone to do não é padrão para esse sentido."],"ex":[["I suggested checking the schedule before sending it.","Sugeri conferir o cronograma antes do envio."],["Emma suggested that we use a single shared document.","Emma sugeriu que usássemos um documento compartilhado."],["The manager suggested a different approach to the team.","A gerente sugeriu outra abordagem à equipe."]],"tip":"Prefira <b>suggest doing</b> ou <b>suggest that someone do</b>."},{"h":"Warn: avisos, orientações e consequências","p":["<b>Warn + pessoa + (not) to + verbo</b> alerta ou aconselha diretamente sobre uma ação.","Com <b>warn someone that + oração</b>, explicamos a situação ou a consequência possível.","Também podemos usar warn someone about/of something para indicar o assunto do aviso."],"ex":[["She warned us not to share outdated information.","Ela nos alertou para não compartilhar informações antigas."],["Daniel warned me that the meeting might start late.","Daniel avisou que a reunião poderia atrasar."],["The coordinator warned everyone about possible delays.","O coordenador alertou todos sobre possíveis atrasos."]],"tip":"<b>Warn someone not to do</b> é útil para advertências negativas."},{"h":"Deny e admit: negar e reconhecer","p":["<b>Deny</b> e <b>admit</b> podem ser seguidos por <b>-ing</b>, indicando a ação negada ou reconhecida: denied sending, admitted forgetting.","Também podemos usar <b>deny that...</b> e <b>admit that...</b> com uma oração completa.","Para detalhar um fato anterior, use o past perfect dentro da oração: She admitted that she'd made a mistake."],"ex":[["He denied deleting the document.","Ele negou ter excluído o documento."],["She admitted making a mistake.","Ela admitiu ter cometido um erro."],["Lucas admitted that he'd attached the wrong file.","Lucas admitiu que tinha anexado o arquivo errado."]],"tip":"Evite <b>deny to do</b> e <b>admit to do</b> para esse sentido."},{"h":"Refuse e promise: infinitivo com to","p":["<b>Refuse + to + verbo</b> expressa recusa de fazer algo; <b>promise + to + verbo</b> apresenta um compromisso.","Promise pode ainda ser seguido por <b>that + oração</b> para destacar o conteúdo da promessa.","Compare os padrões dos seis verbos: suggest doing; warn someone to do; deny/admit doing; refuse/promise to do."],"ex":[["Two volunteers refused to change their shifts.","Dois voluntários se recusaram a trocar de turno."],["She promised to send the corrected schedule.","Ela prometeu enviar o cronograma corrigido."],["He promised that he would check the details again.","Ele prometeu que verificaria os detalhes novamente."]],"tip":"Memorize <b>refuse to do</b> e <b>promise to do</b>, não formas com -ing."}],"vocab":[{"h":"Comunicação e documentos","items":[["shared calendar","calendário compartilhado"],["master schedule","cronograma principal"],["outdated information","informação desatualizada"],["subject line","linha de assunto"],["attachment","anexo"],["screenshot","captura de tela"],["confirmation","confirmação"],["group chat","grupo de mensagens"],["mixed messages","informações desencontradas"]]},{"h":"Responsabilidade e compromissos","items":[["admit a mistake","admitir erro"],["deny responsibility","negar responsabilidade"],["refuse a request","recusar pedido"],["keep a promise","cumprir promessa"],["warn someone","alertar alguém"],["blame someone","culpar alguém"],["apologize","pedir desculpas"],["double-check","conferir com atenção"],["stick to a plan","seguir o plano"]]}],"pron":[{"h":"Admitted e suggested","p":"Admitted e suggested terminam em /ɪd/, acrescentando uma sílaba, aproximadamente “admítid” e “sagdjéstid”.","w":["admitted","suggested","admitted making","suggested checking"]},{"h":"Warned e promised","p":"Warned termina com som de D; promised termina com som de T. Não acrescente uma sílaba inteira de ID.","w":["warned","promised","warned us","promised to call"]},{"h":"Refused e denied","p":"Refused termina em ZD, aproximadamente “rifíuzd”; denied soa “dináid”. Em refused to, to fica reduzido a “tə”.","w":["refused","denied","refused to help","denied sending"]}],"mc":[{"q":"O que Lucas admitiu?","o":["Cancelar a oficina","Trocar os turnos","Enviar cronograma antigo"],"a":2,"e":"Yes. Lucas admitted sending the old schedule, but he denied ignoring the update on purpose."},{"q":"Qual solução Emma sugeriu?","o":["Um cronograma principal único","Capturas de tela diárias","Um calendário por pessoa"],"a":0,"e":"Good idea. Emma also suggested that we keep one master schedule instead of making separate copies."},{"q":"Como reagiram dois voluntários?","o":["Desistiram da oficina","Recusaram troca mas ofereceram ajuda depois","Trocaram de turno sem condições"],"a":1,"e":"Two volunteers refused to switch, but they offered to stay later and help clean up after the workshop."},{"q":"O que Emma prometeu?","o":["Organizar outra oficina","Reescrever todos os materiais","Ligar para quem ainda não confirmou"],"a":2,"e":"She promised to call them personally, and she warned me to keep the correction message short and clear."}],"gaps":[{"s":"Emma suggested ___ one shared calendar. (Use create in the -ing form.)","a":["creating"],"h":"Emma sugeriu criar um calendário compartilhado."},{"s":"She warned us ___ to share screenshots. (Complete the negative warning.)","a":["not"],"h":"Ela nos alertou para não compartilhar capturas de tela."},{"s":"Lucas denied ___ the update deliberately. (Use ignore in the -ing form.)","a":["ignoring"],"h":"Lucas negou ignorar a atualização deliberadamente."},{"s":"He admitted ___ the wrong attachment. (Use send in the -ing form.)","a":["sending"],"h":"Ele admitiu enviar o anexo errado."},{"s":"Two volunteers refused ___ switch shifts. (Complete refuse + infinitive.)","a":["to"],"h":"Dois voluntários se recusaram a trocar de turno."},{"s":"She promised ___ check the schedule again. (Complete promise + infinitive.)","a":["to"],"h":"Ela prometeu conferir o cronograma novamente."}],"order":[{"t":["She","suggested","checking","the","schedule","again."],"h":"Ela sugeriu conferir o cronograma novamente."},{"t":["He","denied","sending","the","wrong","file."],"h":"Ele negou ter enviado o arquivo errado."},{"t":["They","promised","to","correct","the","mistake."],"h":"Eles prometeram corrigir o erro."}],"dict":[{"t":"Emma suggested keeping one shared calendar instead of sending different copies to everyone."},{"t":"The coordinator warned us not to share any outdated information with the participants."},{"t":"Lucas admitted attaching the wrong file, but he denied doing it on purpose."},{"t":"Two volunteers refused to change their shifts, although they offered to help later."},{"t":"She promised to contact everyone personally and double-check the schedule before sending another email."}],"shadow":["Yes. Lucas admitted sending the old schedule, but he denied ignoring the update on purpose.","I suggested adding a date to every email subject line so people can identify the latest version.","He admitted that he'd attached the wrong file and apologized without blaming anyone else.","She promised to call them personally, and she warned me to keep the correction message short and clear."],"write":{"task":"Escreva de 7 a 9 frases sobre um erro de comunicação. Relate sugestão, aviso, admissão, negativa, recusa e promessa usando corretamente os seis verbos principais.","ph":"Last week, we had a problem with … I suggested … Someone warned us not to … Later, … admitted … but denied … Finally, … promised to …"},"cards":[["Ela sugeriu fazer uma pausa.","She suggested taking a break."],["Sugeri que começássemos mais cedo.","I suggested that we start earlier."],["Ele nos alertou sobre os riscos.","He warned us about the risks."],["Ela me avisou para não abrir o arquivo.","She warned me not to open the file."],["Ele negou ter recebido a mensagem.","He denied receiving the message."],["Ela admitiu ter esquecido o compromisso.","She admitted forgetting the appointment."],["Eles se recusaram a participar da reunião.","They refused to attend the meeting."],["Prometi entregar o relatório amanhã.","I promised to deliver the report tomorrow."],["Ele admitiu que tinha cometido um erro.","He admitted that he'd made a mistake."],["Ela prometeu que chegaria na hora.","She promised that she would arrive on time."]]},{"title":"She Must Have Forgotten","goal":"Fazer deduções e especulações sobre o passado com must have, might/may/could have e can't have; expressar críticas, arrependimentos e expectativas com should have.","speakers":{"Sarah":"f","Daniel":"m"},"setting":"Após um evento beneficente, Sarah e Daniel procuram um tablet de inscrições desaparecido e avaliam hipóteses para explicar o ocorrido.","lines":[["Sarah","Have you seen the registration tablet? I can't find it anywhere, and we need the attendance records.","Você viu o tablet de inscrições? Não encontro em lugar nenhum e precisamos dos registros de presença."],["Daniel","It must have been packed with the sound equipment. We were clearing the hall in a hurry on Saturday.","Ele deve ter sido guardado com o som. Estávamos esvaziando o salão às pressas no sábado."],["Sarah","Possibly, but I checked the equipment closet this morning. Someone might have taken it home by mistake.","Talvez, mas verifiquei o depósito de manhã. Alguém pode tê-lo levado por engano."],["Daniel","Emma could have put it in her bag. She was collecting the registration materials before everyone left.","Emma pode ter colocado na bolsa. Ela recolhia os materiais antes de todos saírem."],["Sarah","She can't have taken it after eight. She left at seven thirty, and I remember using it later that evening.","Ela não pode tê-lo levado depois das oito. Saiu às sete e meia, e lembro de usá-lo mais tarde."],["Daniel","You're right. Then I must have moved it myself. I was organizing the projector cables near the entrance.","Tem razão. Devo ter mudado de lugar. Estava organizando os cabos do projetor perto da entrada."],["Sarah","You should have labeled the storage boxes. We spent half an hour looking for the microphones last time.","Você deveria ter identificado as caixas. Da última vez, levamos meia hora procurando microfones."],["Daniel","I know. I should have made an inventory before we locked up. We were both exhausted after the event.","Sei. Eu deveria ter feito um inventário antes de trancar tudo. Estávamos exaustos depois do evento."],["Sarah","What about the attendance data? The tablet should have synchronized everything by now, but the dashboard is empty.","E os dados de presença? O tablet já deveria ter sincronizado tudo, mas o painel está vazio."],["Daniel","The Wi-Fi may have stopped working during cleanup. That could explain why the records haven't appeared.","O Wi-Fi pode ter parado durante a limpeza. Isso explicaria por que os registros não apareceram."],["Sarah","Maybe. I also found the charging cable on the reception desk. We might have forgotten to pack it.","Talvez. Encontrei o carregador na recepção. Podemos ter esquecido de guardá-lo."],["Daniel","Wait, the projector case was unusually heavy when I carried it downstairs. The tablet could be inside.","Espere, a maleta do projetor estava muito pesada quando a levei para baixo. O tablet pode estar dentro."],["Sarah","That would make sense. It can't have disappeared completely. Nobody reported seeing it outside the building.","Faz sentido. Não pode ter simplesmente desaparecido. Ninguém disse tê-lo visto fora do prédio."],["Daniel","Found it! It was under the cables. It must have slipped into the case while we were packing everything.","Achei! Estava sob os cabos. Deve ter escorregado para a maleta enquanto guardávamos tudo."],["Sarah","What a relief! We could have saved ourselves a lot of stress if we'd checked that case first.","Que alívio! Poderíamos ter evitado estresse se tivéssemos visto aquela maleta primeiro."],["Daniel","Absolutely. At least the battery isn't dead. The records may have been saved locally despite the connection problem.","Com certeza. Pelo menos há bateria. Os registros podem ter sido salvos no aparelho apesar da conexão."],["Sarah","Great. Let's connect it to the network and check. We should have backed up the data immediately after the event.","Ótimo. Vamos conectá-lo e verificar. Deveríamos ter feito backup logo depois do evento."],["Daniel","Agreed. Next time, we'll use a checklist. I can't believe we spent the whole morning searching for something I packed myself.","Concordo. Na próxima vez teremos uma lista. Não acredito que perdemos a manhã procurando algo que eu guardei."]],"grammar":[{"h":"Must have: dedução forte no passado","p":["<b>Must have + particípio</b> indica uma conclusão que o falante considera muito provável com base em evidências.","Must não significa obrigação nesse uso: she must have forgotten quer dizer que ela provavelmente esqueceu.","Para uma atividade em andamento no passado, usamos <b>must have been + -ing</b>. A conclusão é forte, mas não equivale a prova."],"ex":[["She must have forgotten about our meeting.","Ela deve ter esquecido nossa reunião."],["They must have left early because the office is empty.","Devem ter saído cedo porque o escritório está vazio."],["He must have been working late when you called.","Ele provavelmente estava trabalhando até tarde quando você ligou."]],"tip":"O padrão é <b>must have + particípio</b>, não must had."},{"h":"Might, may e could have: hipóteses","p":["<b>Might/may/could have + particípio</b> apresentam possibilidades sobre fatos passados sem certeza suficiente para concluir.","Might costuma soar mais cauteloso e may é frequente em registros formais.","Could have pode indicar uma hipótese ou uma capacidade/oportunidade que existiu; o contexto esclarece o significado."],"ex":[["She might have left her keys at the restaurant.","Talvez ela tenha deixado as chaves no restaurante."],["The message may have gone to your spam folder.","A mensagem pode ter ido para a pasta de spam."],["Someone could have moved the documents.","Alguém pode ter mudado os documentos de lugar."]],"tip":"Compare <b>must have</b>, dedução forte, com <b>might have</b>, possibilidade."},{"h":"Can't have e couldn't have: dedução negativa","p":["<b>Can't have</b> e <b>couldn't have + particípio</b> indicam que algo não pode ter acontecido segundo as evidências.","É útil para descartar explicações incompatíveis com os fatos conhecidos.","Couldn't have também pode expressar impossibilidade real; o contexto revela se estamos deduzindo ou descrevendo limitações."],"ex":[["She can't have sent the email yesterday. She was offline all day.","Ela não pode ter enviado o e-mail ontem; ficou sem internet."],["They couldn't have arrived before us. Their flight was delayed.","Não podem ter chegado antes; o voo atrasou."],["He can't have understood the instructions correctly.","Ele não pode ter entendido corretamente as instruções."]],"tip":"Na dedução negativa, prefira <b>can't have</b>, não mustn't have."},{"h":"Should have: crítica, arrependimento e expectativa","p":["<b>Should have + particípio</b> pode criticar ou lamentar uma ação passada: I should have checked.","Também expressa a expectativa de que algo já tenha ocorrido: The package should have arrived by now.","A negativa <b>shouldn't have</b> indica que uma ação passada foi inadequada. Não confunda com can't have, que expressa impossibilidade deduzida."],"ex":[["I should have saved a backup copy.","Eu deveria ter salvo uma cópia de segurança."],["You shouldn't have shared that information.","Você não deveria ter compartilhado essa informação."],["The technician should have finished the repair by now.","O técnico já deveria ter concluído o conserto."]],"tip":"Observe se <b>should have</b> significa arrependimento ou expectativa sobre algo já esperado."}],"vocab":[{"h":"Pistas e hipóteses","items":[["evidence","evidência"],["clue","pista"],["assumption","suposição"],["draw a conclusion","chegar a uma conclusão"],["rule out","descartar"],["by mistake","por engano"],["on purpose","de propósito"],["disappear","desaparecer"],["slip into","escorregar para dentro"]]},{"h":"Equipamentos e organização","items":[["registration tablet","tablet de inscrições"],["attendance records","registros de presença"],["equipment closet","depósito de equipamentos"],["storage box","caixa de armazenamento"],["charging cable","cabo de carregamento"],["projector case","maleta do projetor"],["synchronize","sincronizar"],["backup","cópia de segurança"],["lock up","trancar o local"]]}],"pron":[{"h":"Must have e might have","p":"Depois dos modais, have costuma ficar reduzido a “əv”. Must have soa aproximadamente “mâst əv” e might have “máit əv”.","w":["must have","might have","must have forgotten","might have left"]},{"h":"Can't have e couldn't have","p":"O L em could é mudo. Can't no inglês americano tem a vogal de cat e o T final pode ficar pouco audível.","w":["can't have","couldn't have","can't have known","couldn't have arrived"]},{"h":"Should've e could've","p":"As contrações terminam com som reduzido de have, “əv”. Na escrita, use should've, nunca should of.","w":["should've","could've","should've checked","could've helped"]}],"mc":[{"q":"Qual a primeira hipótese de Daniel?","o":["Foi roubado","Estava com equipamentos de som","Emma levou para casa"],"a":1,"e":"It must have been packed with the sound equipment. We were clearing the hall in a hurry on Saturday."},{"q":"Por que Emma não poderia tê-lo levado depois das oito?","o":["Não foi ao evento","O tablet foi achado às sete","Ela saiu antes e Sarah usou o aparelho depois"],"a":2,"e":"She can't have taken it after eight. She left at seven thirty, and I remember using it later that evening."},{"q":"Qual hipótese sobre a falta de sincronização?","o":["O Wi-Fi parou durante a limpeza","Emma apagou os dados","A bateria acabou antes do evento"],"a":0,"e":"The Wi-Fi may have stopped working during cleanup. That could explain why the records haven't appeared."},{"q":"Onde encontraram o tablet?","o":["Na bolsa de Emma","Sob cabos na maleta do projetor","Na recepção com o carregador"],"a":1,"e":"Found it! It was under the cables. It must have slipped into the case while we were packing everything."}],"gaps":[{"s":"She ___ have forgotten the meeting. Her calendar was empty and she never arrived. (Use must.)","a":["must"],"h":"Ela deve ter esquecido da reunião."},{"s":"He ___ have left his wallet at the office, but we're not sure. (Use might.)","a":["might"],"h":"Talvez ele tenha deixado a carteira no escritório."},{"s":"They ___ have attended in person. They were abroad. (Use can't.)","a":["can't","cannot"],"h":"Eles não podem ter participado presencialmente; estavam no exterior."},{"s":"I ___ have checked the address before leaving. Now I'm lost. (Use should.)","a":["should"],"h":"Eu deveria ter conferido o endereço antes de sair."},{"s":"The files must have been ___ accidentally. (Use delete in the participle.)","a":["deleted"],"h":"Os arquivos devem ter sido apagados por acidente."},{"s":"The delivery should have ___ by now. (Use arrive in the participle.)","a":["arrived"],"h":"A entrega já deveria ter chegado."}],"order":[{"t":["She","must","have","forgotten","her","password."],"h":"Ela deve ter esquecido a senha."},{"t":["They","can't","have","left","already."],"h":"Eles não podem já ter ido embora."},{"t":["I","should","have","called","you","earlier."],"h":"Eu deveria ter ligado para você antes."}],"dict":[{"t":"She must have forgotten to send the updated schedule because nobody received the email."},{"t":"The documents might have been placed in a different folder during the meeting."},{"t":"He can't have finished the entire report in twenty minutes without any help."},{"t":"We should have checked the equipment before everyone left the building on Saturday."},{"t":"The information may have been saved locally even though the internet connection stopped working."}],"shadow":["It must have been packed with the sound equipment. We were clearing the hall in a hurry on Saturday.","She can't have taken it after eight. She left at seven thirty, and I remember using it later that evening.","The Wi-Fi may have stopped working during cleanup. That could explain why the records haven't appeared.","Absolutely. At least the battery isn't dead. The records may have been saved locally despite the connection problem."],"write":{"task":"Escreva de 7 a 9 frases sobre algo perdido ou um acontecimento misterioso, com três hipóteses, uma dedução forte, uma descartada e um arrependimento ou expectativa.","ph":"Yesterday, something strange happened … Someone might have … It must have … It can't have … I should have …"},"cards":[["Ela deve ter perdido o ônibus.","She must have missed the bus."],["Talvez eles tenham mudado de ideia.","They might have changed their minds."],["O e-mail pode ter ido para o spam.","The email may have gone to spam."],["Ele não pode ter terminado tão rápido.","He can't have finished that quickly."],["Você deveria ter me avisado.","You should have warned me."],["Eu não deveria ter dito aquilo.","I shouldn't have said that."],["Alguém pode ter deixado a porta aberta.","Someone could have left the door open."],["Eles devem ter entendido errado.","They must have misunderstood."],["O pacote já deveria ter chegado.","The package should have arrived by now."],["Ela não pode ter visto a mensagem.","She can't have seen the message."]]},{"title":"My Sister, Who Lives in Lisbon","goal":"Acrescentar informações sobre pessoas, lugares e objetos com orações relativas explicativas e condensar descrições com particípios presentes e passados.","speakers":{"Sarah":"f","Emma":"f"},"setting":"Emma e Sarah selecionam fotografias e cartas históricas de moradores para uma exposição e discutem como apresentá-las.","lines":[["Sarah","These old photographs are incredible. Where did you find the ones showing the neighborhood fifty years ago?","Essas fotografias são incríveis. Onde encontrou as que mostram o bairro cinquenta anos atrás?"],["Emma","My sister, who lives in Lisbon, found them while organizing our grandfather's personal collection.","Minha irmã, que mora em Lisboa, encontrou as fotos organizando o acervo do nosso avô."],["Sarah","That's amazing. Your grandfather, who worked as a photographer, must have documented some important changes.","Que incrível. Seu avô, que era fotógrafo, deve ter documentado mudanças importantes."],["Emma","He did. The photos taken in the 1970s show the main square before the old market was demolished.","Sim. As fotos dos anos 1970 mostram a praça principal antes da demolição do mercado antigo."],["Sarah","I recognize that bakery! The woman standing outside looks just like the person in our newspaper clipping.","Reconheço aquela padaria! A mulher na entrada parece a pessoa do recorte de jornal."],["Emma","That's Mrs. Miller, whose family owned the bakery for three generations. She was well known around here.","É a senhora Miller, cuja família foi dona da padaria por três gerações. Era conhecida por aqui."],["Sarah","We should include her story. The people visiting the exhibition will appreciate the personal details.","Deveríamos incluir a história dela. Os visitantes vão gostar dos detalhes pessoais."],["Emma","Agreed. The original bakery, which closed in 1998, is now a bookstore with a small café.","Concordo. A padaria original, que fechou em 1998, hoje é uma livraria com café."],["Sarah","Let's photograph the building as it looks today. We could display both pictures next to each other.","Vamos fotografar o prédio atualmente. Poderíamos exibir as duas imagens lado a lado."],["Emma","Good idea. The bookstore, where we held our first reading event, still has the original wooden entrance.","Boa ideia. A livraria, onde realizamos o primeiro evento de leitura, mantém a entrada de madeira original."],["Sarah","What about the letters you mentioned? Are they part of the collection donated by your sister?","E as cartas? Fazem parte do acervo doado por sua irmã?"],["Emma","Yes. The letters written by local residents describe how the neighborhood changed during the 1980s.","Sim. As cartas escritas por moradores descrevem como o bairro mudou nos anos 1980."],["Sarah","I'd love to feature a few. We should ask for permission before displaying documents containing personal information.","Adoraria destacar algumas. Devemos pedir autorização para exibir documentos com dados pessoais."],["Emma","Absolutely. Daniel, whose aunt used to live on this street, is helping us contact the families.","Com certeza. Daniel, cuja tia morava nesta rua, está nos ajudando a procurar as famílias."],["Sarah","That's helpful. The volunteers working on the archive have already scanned most of the photographs.","Isso ajuda. Os voluntários do arquivo já digitalizaram a maioria das fotos."],["Emma","Great. The scanned images, which are stored in a shared folder, should be ready for printing by Friday.","Ótimo. As imagens digitalizadas, que ficam numa pasta compartilhada, devem estar prontas para impressão até sexta."],["Sarah","This exhibition is becoming much more personal than I expected. It's really about the people who lived here.","A exposição está ficando mais pessoal que imaginei. É sobre as pessoas que moravam aqui."],["Emma","Exactly. By combining photographs, letters, and memories shared by residents, we can bring the neighborhood's history to life.","Exatamente. Com fotos, cartas e memórias dos moradores, podemos dar vida à história do bairro."]],"grammar":[{"h":"Orações relativas explicativas","p":["Uma <b>non-defining relative clause</b> acrescenta informação extra sobre algo já identificado, sem ser essencial para saber a quem ou a que nos referimos.","Use vírgulas para separar essa informação; no meio da frase, normalmente há uma antes e outra depois.","Use <b>who</b> para pessoas e <b>which</b> para coisas. Nesse tipo de oração, não substitua por that nem omita o relativo."],"ex":[["My brother, who works in Chicago, is visiting next week.","Meu irmão, que trabalha em Chicago, vem nos visitar."],["The gallery, which opened last year, is very popular.","A galeria, que abriu no ano passado, é popular."],["Emma, who organized the exhibition, gave us a tour.","Emma, que organizou a exposição, nos mostrou o espaço."]],"tip":"Uma relativa explicativa é isolada por <b>vírgulas</b>."},{"h":"Who, whose e where","p":["<b>Whose</b> introduz uma relação de posse ou pertencimento: whose family, whose paintings. Pode referir-se a pessoas e organizações.","<b>Where</b> acrescenta informação sobre um lugar já identificado.","Relativas restritivas sem vírgulas ajudam a identificar a pessoa ou coisa; explicativas com vírgulas acrescentam detalhes sobre algo que já sabemos qual é."],"ex":[["Sarah, whose mother is an architect, loves historic buildings.","Sarah, cuja mãe é arquiteta, adora prédios históricos."],["The bookstore, where we held the event, has a beautiful garden.","A livraria, onde fizemos o evento, tem um jardim lindo."],["Daniel, whose family lived nearby, recognized the old street.","Daniel, cuja família morava perto, reconheceu a rua antiga."]],"tip":"<b>Whose</b> não é who's, contração de who is ou who has."},{"h":"Orações reduzidas com -ing: sentido ativo","p":["Algumas orações relativas podem ser encurtadas com <b>verbo + -ing</b> quando o substantivo descrito realiza uma ação.","The people who live nearby pode ficar The people living nearby.","Frases participiais também podem acrescentar informação, desde que o sujeito implícito seja claro. Nem toda oração relativa admite redução automática."],"ex":[["The volunteers working on the project are experienced.","Os voluntários que trabalham no projeto têm experiência."],["The woman standing near the entrance is our guide.","A mulher que está perto da entrada é nossa guia."],["Students interested in photography can join the workshop.","Alunos interessados em fotografia podem participar da oficina."]],"tip":"<b>Working</b> e <b>standing</b> descrevem quem pratica a ação."},{"h":"Orações reduzidas com particípio passado","p":["Se uma relativa tem sentido passivo, muitas vezes podemos reduzi-la ao <b>particípio passado</b>: the photos that were taken in 1975 → the photos taken in 1975.","É comum em descrições de documentos, fotografias, produtos e arquivos.","O particípio, sozinho, não indica quando algo aconteceu; contexto e marcadores temporais esclarecem."],"ex":[["The documents signed yesterday are on my desk.","Os documentos assinados ontem estão na mesa."],["The pictures displayed in the gallery belong to local artists.","As imagens expostas na galeria são de artistas locais."],["The reports prepared by Emma contain useful information.","Os relatórios feitos por Emma contêm informações úteis."]],"tip":"<b>-ing</b> costuma dar sentido ativo; o <b>particípio passado</b>, passivo."}],"vocab":[{"h":"História e memória","items":[["archive","arquivo; acervo"],["personal collection","coleção pessoal"],["newspaper clipping","recorte de jornal"],["historic building","prédio histórico"],["local resident","morador da região"],["document","registrar; documento"],["demolish","demolir"],["preserve","preservar"],["bring history to life","dar vida à história"]]},{"h":"Exposição e organização","items":[["display","exibir"],["feature","destacar"],["donate","doar"],["scan","digitalizar"],["shared folder","pasta compartilhada"],["original entrance","entrada original"],["ask for permission","pedir autorização"],["personal details","detalhes pessoais"],["side by side","lado a lado"]]}],"pron":[{"h":"Who e whose","p":"Who começa com H e soa aproximadamente “hú”; whose termina em Z, “húz”.","w":["who","whose","who lives","whose family"]},{"h":"Which conectado","p":"Which termina no som /tʃ/, semelhante a “tch”. Uma pequena pausa nas vírgulas destaca a oração explicativa.","w":["which","which opened","which closed","which is located"]},{"h":"Written, taken e displayed","p":"Written soa “rítn”, taken “têikən”, e displayed termina com som de D sem sílaba extra.","w":["written","taken","displayed","photos taken yesterday"]}],"mc":[{"q":"Onde a irmã de Emma encontrou as fotos?","o":["Na coleção do avô","Numa livraria","No arquivo digital"],"a":0,"e":"My sister, who lives in Lisbon, found them while organizing our grandfather's personal collection."},{"q":"O que mostram as fotos dos anos 1970?","o":["Novo centro cultural","Praça antes da demolição do mercado","Construção da livraria"],"a":1,"e":"He did. The photos taken in the 1970s show the main square before the old market was demolished."},{"q":"Quem era a senhora Miller?","o":["Uma fotógrafa portuguesa","A arquivista do centro","Uma mulher de família proprietária da padaria"],"a":2,"e":"That's Mrs. Miller, whose family owned the bakery for three generations. She was well known around here."},{"q":"Por que pedir autorização para mostrar cartas?","o":["Elas podem conter dados pessoais","Estão em outro idioma","Não foram digitalizadas"],"a":0,"e":"I'd love to feature a few. We should ask for permission before displaying documents containing personal information."}],"gaps":[{"s":"My sister, ___ lives in Lisbon, is visiting next month. (Relative pronoun for a person.)","a":["who"],"h":"Minha irmã, que mora em Lisboa, vem visitar mês que vem."},{"s":"The museum, ___ opened in 1985, has been renovated. (Relative pronoun for a thing.)","a":["which"],"h":"O museu, que abriu em 1985, foi reformado."},{"s":"Daniel, ___ father is a photographer, helped us. (Relative pronoun for possession.)","a":["whose"],"h":"Daniel, cujo pai é fotógrafo, nos ajudou."},{"s":"The café, ___ we first met, has closed. (Relative word for place.)","a":["where"],"h":"O café onde nos conhecemos fechou."},{"s":"The volunteers ___ on the project are experienced. (Use work in -ing.)","a":["working"],"h":"Os voluntários que trabalham no projeto são experientes."},{"s":"The photos ___ in 1975 are on display. (Use take in the participle.)","a":["taken"],"h":"As fotos tiradas em 1975 estão em exposição."}],"order":[{"t":["Sarah,","who","lives","nearby,","knows","the","area."],"h":"Sarah, que mora perto, conhece a região."},{"t":["The","documents","signed","yesterday","are","ready."],"h":"Os documentos assinados ontem estão prontos."},{"t":["The","people","waiting","outside","need","tickets."],"h":"As pessoas na fila lá fora precisam de ingressos."}],"dict":[{"t":"My sister, who lives in Lisbon, discovered some valuable photographs in our grandfather's collection."},{"t":"The old bakery, which closed many years ago, has become a small neighborhood bookstore."},{"t":"Daniel, whose family lived on this street, recognized several buildings in the photographs."},{"t":"The volunteers working on the exhibition have already organized most of the historic documents."},{"t":"The letters written by local residents describe important changes in the neighborhood's history."}],"shadow":["My sister, who lives in Lisbon, found them while organizing our grandfather's personal collection.","That's Mrs. Miller, whose family owned the bakery for three generations. She was well known around here.","Good idea. The bookstore, where we held our first reading event, still has the original wooden entrance.","Great. The scanned images, which are stored in a shared folder, should be ready for printing by Friday."],"write":{"task":"Escreva 7 a 9 frases descrevendo pessoas, lugares e objetos importantes para você. Inclua três relativas explicativas, whose, where e duas relativas reduzidas com particípios.","ph":"My friend, who …, lives in … The neighborhood, which …, is … I know someone whose … The photos taken …"},"cards":[["Minha mãe, que é professora, mora perto daqui.","My mother, who is a teacher, lives nearby."],["O prédio, que foi reformado, parece novo.","The building, which was renovated, looks new."],["Emma, cuja irmã é médica, trabalha conosco.","Emma, whose sister is a doctor, works with us."],["O restaurante, onde comemoramos, fechou.","The restaurant, where we celebrated, has closed."],["Os alunos que esperam lá fora estão animados.","The students waiting outside are excited."],["Os arquivos enviados ontem estão disponíveis.","The files sent yesterday are available."],["Meu irmão, que mora no Canadá, vem nos visitar.","My brother, who lives in Canada, is coming to visit."],["A mulher falando com Lucas é minha chefe.","The woman speaking to Lucas is my boss."],["O relatório preparado por Sarah está completo.","The report prepared by Sarah is complete."],["A empresa, cujo escritório fica aqui, está crescendo.","The company, whose office is here, is growing."]]},{"title":"Remember to Call","goal":"Diferenciar remember, forget, stop, try e regret seguidos por -ing ou infinitivo, explicando lembranças, tarefas, interrupções, tentativas e arrependimentos.","speakers":{"Emma":"f","Lucas":"m"},"setting":"Na sexta-feira, Emma e Lucas preparam uma oficina de desenvolvimento profissional e resolvem problemas de inscrição e comunicação.","lines":[["Emma","Before we finish, did you remember to email the updated schedule to everyone who registered?","Antes de terminarmos, lembrou-se de enviar o cronograma atualizado a todos os inscritos?"],["Lucas","Yes, I remember sending it this morning. I even checked the recipient list before clicking send.","Sim, lembro de enviá-lo de manhã. Conferi até os destinatários antes de clicar em enviar."],["Emma","Good. I forgot to attach the parking map, though. I'll send another message with the missing information.","Ótimo. Mas esqueci de anexar o mapa do estacionamento. Enviarei outra mensagem."],["Lucas","Don't worry. I still remember getting lost the first time I came here. That map would've helped a lot.","Não se preocupe. Lembro de me perder na primeira vez que vim aqui. Esse mapa teria ajudado muito."],["Emma","By the way, the registration form kept freezing yesterday. Did you manage to fix it?","Aliás, o formulário de inscrição travava ontem. Você conseguiu consertá-lo?"],["Lucas","I tried restarting the browser, but that didn't work. Then I tried to upload the data manually.","Experimentei reiniciar o navegador, mas não funcionou. Depois tentei enviar os dados manualmente."],["Emma","And did the manual upload work, or did you have to contact technical support?","E o envio manual funcionou ou precisou de suporte técnico?"],["Lucas","The server rejected the file twice. Eventually, I stopped trying to upload it and called the support team.","O servidor rejeitou o arquivo duas vezes. Por fim, parei de tentar enviá-lo e liguei para o suporte."],["Emma","That was sensible. Sometimes it's better to ask for help instead of wasting another hour on the same problem.","Foi sensato. Às vezes é melhor pedir ajuda a perder mais uma hora com o problema."],["Lucas","Exactly. On my way back from lunch, I stopped to check the printed signs. One of them had the wrong room number.","Exatamente. Na volta do almoço, parei para ver os avisos impressos. Um tinha o número da sala errado."],["Emma","Oh no. I regret approving the design without checking every detail. We should have reviewed it together.","Ah, não. Arrependo-me de aprovar o design sem conferir detalhes. Deveríamos tê-lo revisado juntos."],["Lucas","It's fixed now. But we should stop making last-minute changes unless they're absolutely necessary.","Agora foi corrigido. Devemos parar de fazer alterações de última hora, salvo se forem necessárias."],["Emma","Agreed. Also, remember to bring the name tags tomorrow. We don't have time to print another set.","Concordo. Lembre de trazer os crachás amanhã. Não temos tempo para imprimir novos."],["Lucas","I won't forget. They're already in my bag. Did you hear back from the people on the waiting list?","Não vou esquecer. Já estão na bolsa. Você recebeu resposta das pessoas na lista de espera?"],["Emma","Yes. Unfortunately, I regret to inform you that the workshop is completely full. That's what I told them.","Sim. Infelizmente, lamento informar que a oficina está lotada. Foi o que disse a eles."],["Lucas","That's a pretty formal way to say it! Did you offer to notify them if someone cancels?","Que jeito formal de falar! Você ofereceu avisá-los caso alguém cancele?"],["Emma","Of course. I also suggested trying a second session next month if there's enough interest.","Claro. Sugeri também experimentar uma segunda turma no próximo mês se houver interesse."],["Lucas","Good plan. And let's not forget to thank the volunteers. I still remember how much they helped us last year.","Bom plano. E não vamos esquecer de agradecer aos voluntários. Lembro de quanto nos ajudaram ano passado."]],"grammar":[{"h":"Remember e forget: tarefa ou lembrança","p":["<b>Remember to do</b> significa lembrar de realizar uma tarefa: lembramos antes de agir. <b>Forget to do</b> indica não se lembrar de executar algo.","<b>Remember doing</b> é recordar uma experiência já vivida; <b>forget doing</b> é não se lembrar de ter realizado uma ação.","Compare I remembered to call (lembrei e liguei) com I remember calling (tenho a lembrança de ter ligado)."],"ex":[["Remember to lock the door before leaving.","Lembre de trancar a porta antes de sair."],["I remember meeting her at a conference.","Lembro de conhecê-la numa conferência."],["He forgot to attach the document.","Ele esqueceu de anexar o documento."],["I'll never forget visiting that city for the first time.","Nunca esquecerei a primeira visita àquela cidade."]],"tip":"<b>To do</b> aponta para uma tarefa; <b>doing</b> aponta para memória de uma ação."},{"h":"Stop: interromper atividade ou parar para outra","p":["<b>Stop doing</b> significa deixar de fazer a atividade mencionada.","<b>Stop to do</b> indica interromper outra ação com a finalidade de fazer o que vem depois de to.","He stopped talking significa que parou de falar; he stopped to talk significa que parou o que fazia para conversar."],"ex":[["She stopped checking her phone during meetings.","Ela parou de olhar o celular nas reuniões."],["We stopped to get some coffee on the way.","Paramos para tomar café no caminho."],["He stopped working at six and went home.","Ele parou de trabalhar às seis e foi para casa."],["I stopped to answer an important call.","Parei para atender uma ligação importante."]],"tip":"<b>Stop doing</b> interrompe a atividade nomeada; <b>stop to do</b> indica a finalidade da pausa."},{"h":"Try: esforço ou solução experimental","p":["<b>Try to do</b> enfatiza o esforço para alcançar um objetivo que pode ou não ter êxito.","<b>Try doing</b> sugere experimentar um método para ver se funciona.","É possível tentar alcançar uma meta por meio de vários métodos experimentais; o contexto define qual aspecto está em destaque."],"ex":[["I tried to contact the manager, but she was unavailable.","Tentei procurar a gerente, mas ela estava indisponível."],["Try restarting your phone if the app freezes.","Experimente reiniciar o celular se o aplicativo travar."],["They tried to finish the project before Friday.","Eles tentaram concluir o projeto antes de sexta."],["Have you tried changing your password?","Já experimentou mudar a senha?"]],"tip":"<b>Try to do</b> destaca esforço; <b>try doing</b> apresenta uma alternativa a testar."},{"h":"Regret: arrependimento ou anúncio formal","p":["<b>Regret doing</b> significa arrepender-se de uma ação passada, como regret sending the email.","<b>Regret to inform/say/announce</b> é uma estrutura formal usada para transmitir notícia desagradável.","A diferença está no foco: ação concluída e lamentada, ou anúncio feito agora."],"ex":[["I regret accepting that offer without reading the contract.","Arrependo-me de aceitar a proposta sem ler o contrato."],["We regret to inform you that your application was unsuccessful.","Lamentamos informar que sua candidatura não foi aprovada."],["She regrets not asking for help sooner.","Ela se arrepende de não ter pedido ajuda antes."],["I regret to say that we cannot extend the deadline.","Lamento dizer que não podemos ampliar o prazo."]],"tip":"<b>Regret doing</b> lamenta o passado; <b>regret to inform</b> introduz notícia ruim."}],"vocab":[{"h":"Oficinas e inscrições","items":[["recipient list","lista de destinatários"],["attachment","anexo"],["parking map","mapa do estacionamento"],["registration form","formulário de inscrição"],["waiting list","lista de espera"],["name tag","crachá"],["printed sign","aviso impresso"],["last-minute change","alteração de última hora"],["workshop session","turma de oficina"]]},{"h":"Tecnologia e solução","items":[["freeze","travar"],["restart","reiniciar"],["upload","enviar para o sistema"],["manually","manualmente"],["reject a file","rejeitar arquivo"],["technical support","suporte técnico"],["fix an issue","resolver problema"],["click send","clicar em enviar"],["hear back from someone","receber resposta de alguém"]]}],"pron":[{"h":"Remember e remembered","p":"Remember tem sílaba central tônica, aproximadamente “rimémber”. Remembered termina com som de D sem sílaba extra.","w":["remember","remembered","remember to call","remember sending"]},{"h":"Stopped e tried","p":"Stopped termina em T; tried termina em D. Stopped trying e stopped to try têm significados diferentes.","w":["stopped","tried","stopped working","stopped to check"]},{"h":"Regret e regretted","p":"Regret tem a segunda sílaba tônica, “rigrét”; regretted ganha uma sílaba em -ed, “rigrétid”.","w":["regret","regretted","regret doing","regret to inform"]}],"mc":[{"q":"O que Lucas lembra de fazer?","o":["Enviar cronograma e conferir destinatários","Mandar o mapa de estacionamento","Ligar para quem está na espera"],"a":0,"e":"Yes, I remember sending it this morning. I even checked the recipient list before clicking send."},{"q":"Qual tentativa veio primeiro para o formulário travado?","o":["Substituir o servidor","Reiniciar o navegador","Enviar os dados manualmente"],"a":1,"e":"I tried restarting the browser, but that didn't work. Then I tried to upload the data manually."},{"q":"Do que Emma se arrepende no design?","o":["Do preço","Da falta de material impresso","De aprovar sem conferir o número da sala"],"a":2,"e":"Oh no. I regret approving the design without checking every detail. We should have reviewed it together."},{"q":"O que sugeriu para o próximo mês?","o":["Testar uma segunda turma","Cancelar atividades","Dar vagas apenas a antigos inscritos"],"a":0,"e":"Of course. I also suggested trying a second session next month if there's enough interest."}],"gaps":[{"s":"Remember ___ lock the door before leaving. (Complete remembering a future task.)","a":["to"],"h":"Lembre de trancar a porta antes de sair."},{"s":"I remember ___ her at the conference last year. (Use meet in -ing for memory.)","a":["meeting"],"h":"Lembro de conhecê-la na conferência."},{"s":"He stopped ___ his phone during meetings. (Use check in -ing for ending a habit.)","a":["checking"],"h":"Ele parou de olhar o celular nas reuniões."},{"s":"We stopped ___ get some water on the way home. (Use purpose infinitive.)","a":["to"],"h":"Paramos para pegar água no caminho de casa."},{"s":"Try ___ the app if it keeps freezing. (Use restart in -ing for an experiment.)","a":["restarting"],"h":"Experimente reiniciar o aplicativo se ele continuar travando."},{"s":"We regret ___ inform you that the event has been canceled. (Formal announcement.)","a":["to"],"h":"Lamentamos informar que o evento foi cancelado."}],"order":[{"t":["Don't","forget","to","send","the","email."],"h":"Não esqueça de enviar o e-mail."},{"t":["I","remember","meeting","her","last","year."],"h":"Lembro de conhecê-la ano passado."},{"t":["Try","restarting","the","computer","first."],"h":"Experimente reiniciar o computador primeiro."}],"dict":[{"t":"I remembered to send the invitation, but I forgot to attach the updated schedule."},{"t":"She clearly remembers visiting the community center for the first time several years ago."},{"t":"We stopped to check the registration numbers before going back to the office."},{"t":"I tried restarting the browser, but eventually I had to contact technical support."},{"t":"We regret to inform you that registration has closed and no additional places are available."}],"shadow":["Yes, I remember sending it this morning. I even checked the recipient list before clicking send.","I tried restarting the browser, but that didn't work. Then I tried to upload the data manually.","Exactly. On my way back from lunch, I stopped to check the printed signs. One of them had the wrong room number.","Yes. Unfortunately, I regret to inform you that the workshop is completely full. That's what I told them."],"write":{"task":"Escreva de 7 a 9 frases sobre preparar um evento ou viagem. Distinga lembranças e tarefas, interrupção e pausa, esforço e método experimental, arrependimento e uma notícia formal.","ph":"Last week, I was organizing … I remembered to … I still remember … I forgot to … I stopped … Then I tried … I regret …"},"cards":[["Lembre-se de enviar a mensagem.","Remember to send the message."],["Lembro de ter visitado aquele lugar.","I remember visiting that place."],["Esqueci de salvar o arquivo.","I forgot to save the file."],["Nunca esquecerei de ter conhecido você.","I'll never forget meeting you."],["Ela parou de trabalhar aos domingos.","She stopped working on Sundays."],["Paramos para comprar alguma coisa.","We stopped to buy something."],["Tentei abrir o documento, mas não consegui.","I tried to open the document, but I couldn't."],["Experimente mudar as configurações.","Try changing the settings."],["Arrependo-me de ter recusado a proposta.","I regret refusing the offer."],["Lamentamos informar que a reunião foi adiada.","We regret to inform you that the meeting has been postponed."]]},{"title":"Although, Despite, So That","goal":"Contrastar e comparar situações, reconhecer obstáculos e explicar finalidades usando although, even though, despite, in spite of, whereas, so that e in order to.","speakers":{"Sarah":"f","Daniel":"m"},"setting":"Sarah e Daniel planejam uma feira comunitária ameaçada pela previsão de chuva, equilibrando opiniões e adaptando atividades.","lines":[["Sarah","Although the weather forecast looks terrible, I still think we should go ahead with Saturday's community fair.","Embora a previsão esteja péssima, acho que devemos realizar a feira comunitária de sábado."],["Daniel","I agree, but we need a backup plan. Even though most activities are outdoors, we could move some inside.","Concordo, mas precisamos de plano B. Embora a maioria das atividades seja ao ar livre, podemos levar algumas para dentro."],["Sarah","Despite the risk of rain, several local businesses have confirmed their participation. We shouldn't disappoint them.","Apesar do risco de chuva, várias empresas confirmaram presença. Não devemos decepcioná-las."],["Daniel","True. The food vendors need outdoor space, whereas the workshop organizers can use the rooms upstairs.","Verdade. Os vendedores de comida precisam da área externa, enquanto oficinas podem usar as salas de cima."],["Sarah","Let's put up covered areas so that visitors can enjoy the food without getting completely soaked.","Vamos montar áreas cobertas para que os visitantes comam sem ficar encharcados."],["Daniel","Good idea. We should also move the information desk closer to the entrance in order to make it easier to find.","Boa ideia. Vamos aproximar o balcão de informações da entrada para facilitar sua localização."],["Sarah","In spite of having a limited budget, we've managed to organize something much bigger than last year's event.","Apesar do orçamento limitado, conseguimos organizar algo muito maior do que no ano passado."],["Daniel","That's true. While some volunteers prefer working outdoors, others feel more comfortable helping inside.","É verdade. Enquanto alguns voluntários preferem trabalhar fora, outros se sentem melhor dentro."],["Sarah","We can let people choose their stations so that everyone feels comfortable with their responsibilities.","Podemos deixar cada um escolher sua área para que todos fiquem confortáveis com as tarefas."],["Daniel","Although that sounds fair, we still need enough people at the entrance to manage the queues.","Embora pareça justo, ainda precisamos de gente na entrada para organizar as filas."],["Sarah","I'll ask Emma to prepare a revised schedule in order to avoid confusion on Saturday morning.","Pedirei à Emma para preparar um cronograma revisado e evitar confusão no sábado."],["Daniel","What about the live music? Despite the weather warnings, the musicians still want to perform outside.","E a música ao vivo? Apesar dos alertas, os músicos ainda querem se apresentar fora."],["Sarah","I'd rather move the stage indoors. Even though the hall is smaller, it's safer for the electrical equipment.","Prefiro levar o palco para dentro. Embora o salão seja menor, é mais seguro para os aparelhos elétricos."],["Daniel","Agreed. The musicians can use the main hall, whereas the children's activities can take place in the library.","Concordo. Os músicos usarão o salão, enquanto as atividades infantis ficarão na biblioteca."],["Sarah","Let's update the website tonight so that families know where each activity will be held.","Vamos atualizar o site hoje para que as famílias saibam onde cada atividade acontecerá."],["Daniel","I'll also send the volunteers a short message. In spite of all these changes, the main schedule will remain the same.","Também enviarei um aviso aos voluntários. Apesar das mudanças, a programação principal permanecerá igual."],["Sarah","We should make the announcement clear and positive. After all, people are coming to support the community.","Devemos fazer um aviso claro e positivo. Afinal, as pessoas vêm apoiar a comunidade."],["Daniel","Exactly. Although the weather isn't ideal, the fair can still be a success if we prepare carefully.","Exatamente. Embora o tempo não seja ideal, a feira pode dar certo se nos prepararmos."]],"grammar":[{"h":"Although e even though: contraste com oração completa","p":["<b>Although</b> e <b>even though</b> introduzem contraste ou concessão e são seguidos de <b>sujeito + verbo</b>.","Even though costuma enfatizar mais a surpresa da situação contrastante.","A oração pode aparecer antes ou depois da principal; normalmente colocamos vírgula depois dela quando aparece no início. Não acrescente but para conectar a mesma oração principal."],"ex":[["Although it was raining, the event continued as planned.","Embora chovesse, o evento continuou conforme o plano."],["Even though she was exhausted, she stayed until the end.","Mesmo exausta, ela ficou até o final."],["We accepted the proposal although it was more expensive.","Aceitamos a proposta, embora fosse mais cara."]],"tip":"Depois de <b>although</b>, use uma oração completa."},{"h":"Despite e in spite of: contraste com substantivo ou -ing","p":["<b>Despite</b> e <b>in spite of</b> significam apesar de e são geralmente seguidos de substantivo, pronome ou verbo com -ing.","Não diga despite of nem despite there was a problem.","Para uma oração completa, use <b>despite the fact that</b> ou <b>in spite of the fact that</b>."],"ex":[["Despite the delay, everyone remained calm.","Apesar do atraso, todos ficaram calmos."],["In spite of working late, he couldn't finish the report.","Apesar de trabalhar até tarde, não terminou o relatório."],["Despite the fact that it was expensive, we bought it.","Apesar de ser caro, compramos."],["She succeeded in spite of several difficulties.","Ela teve sucesso apesar de várias dificuldades."]],"tip":"Compare <b>despite the problem</b> com <b>although there was a problem</b>."},{"h":"Whereas e while: comparação e contraste","p":["<b>Whereas</b> compara diretamente duas situações, características ou opiniões.","<b>While</b> pode igualmente marcar contraste, mas também significa enquanto no sentido de simultaneidade.","Para frases profissionais, whereas deixa o contraste explícito. Ambas costumam unir duas orações completas."],"ex":[["Sarah prefers working in a team, whereas Daniel works better alone.","Sarah prefere equipe, enquanto Daniel rende mais sozinho."],["The first option is cheaper, while the second offers more features.","A primeira opção custa menos, enquanto a segunda oferece mais funções."],["While some people enjoy busy cities, others prefer quieter places.","Enquanto alguns gostam de cidades movimentadas, outros preferem tranquilidade."]],"tip":"<b>Whereas</b> marca contraste; <b>while</b> também pode marcar simultaneidade."},{"h":"So that e in order to: finalidade","p":["<b>So that + sujeito + verbo</b> explica para que fazemos algo; é frequente com can, could, will e would.","<b>In order to + verbo base</b> indica diretamente um objetivo e soa um pouco mais formal do que o simples to.","A negativa formal é <b>in order not to + verbo</b>. As duas estruturas permitem organizar motivos e resultados pretendidos."],"ex":[["We sent a reminder so that everyone could arrive on time.","Enviamos lembrete para que todos chegassem no horário."],["She took notes in order to remember the main points.","Ela anotou para lembrar os pontos principais."],["We left early in order not to miss the train.","Saímos cedo para não perder o trem."],["I'll explain it again so that you can understand.","Explicarei de novo para que você entenda."]],"tip":"<b>In order to</b> + verbo; <b>so that</b> + sujeito e verbo."}],"vocab":[{"h":"Eventos e imprevistos","items":[["weather forecast","previsão do tempo"],["backup plan","plano B"],["food vendor","vendedor de comida"],["covered area","área coberta"],["information desk","balcão de informações"],["queue","fila"],["weather warning","alerta meteorológico"],["revised schedule","cronograma revisado"],["go ahead with","prosseguir com"]]},{"h":"Contraste e finalidade","items":[["although","embora"],["even though","mesmo que; embora"],["despite","apesar de"],["in spite of","apesar de"],["whereas","ao passo que"],["while","enquanto; embora"],["so that","para que"],["in order to","a fim de"],["regardless of","independentemente de"]]}],"pron":[{"h":"Although e even though","p":"O TH em although e though é sonoro /ð/, parecido com um D suave, com a língua próxima dos dentes.","w":["although","even though","although it rained","even though we tried"]},{"h":"Despite e in spite of","p":"Despite tem segunda sílaba forte, “dispáit”; in spite of costuma soar “in spáit əv”.","w":["despite","despite the rain","in spite of","in spite of everything"]},{"h":"Whereas e so that","p":"Whereas soa aproximadamente “uér-áz”; so that soa “sôu dhət”, com that reduzido.","w":["whereas","whereas others","so that","so that we can"]}],"mc":[{"q":"Por que montar áreas cobertas?","o":["Para comer sem se molhar muito","Para fechar as salas internas","Para impedir a música"],"a":0,"e":"Let's put up covered areas so that visitors can enjoy the food without getting completely soaked."},{"q":"Por que aproximar o balcão da entrada?","o":["Para usar menos voluntários","Para facilitar sua localização","Para aumentar a área dos vendedores"],"a":1,"e":"Good idea. We should also move the information desk closer to the entrance in order to make it easier to find."},{"q":"Por que mudar o palco para dentro?","o":["Público prefere ambiente interno","Salão é maior","É mais seguro para os equipamentos elétricos"],"a":2,"e":"I'd rather move the stage indoors. Even though the hall is smaller, it's safer for the electrical equipment."},{"q":"O que Daniel comunica?","o":["Programação principal será mantida","Feira cancelada","Evento transferido ao domingo"],"a":0,"e":"I'll also send the volunteers a short message. In spite of all these changes, the main schedule will remain the same."}],"gaps":[{"s":"___ it was raining, the fair continued as planned. (Use although.)","a":["Although"],"h":"Embora estivesse chovendo, a feira continuou conforme previsto."},{"s":"___ the bad weather, everyone arrived on time. (Use despite.)","a":["Despite"],"h":"Apesar do mau tempo, todos chegaram na hora."},{"s":"Sarah prefers working indoors, ___ Daniel likes outdoor activities. (Use whereas.)","a":["whereas"],"h":"Sarah prefere trabalhar dentro, enquanto Daniel gosta das atividades externas."},{"s":"We sent instructions so ___ everyone could find the entrance. (Complete so that.)","a":["that"],"h":"Enviamos instruções para que todos encontrassem a entrada."},{"s":"We moved the equipment in order ___ protect it from the rain. (Complete the purpose structure.)","a":["to"],"h":"Movemos os equipamentos para protegê-los da chuva."},{"s":"___ spite of having little time, we finished everything. (Complete in spite of.)","a":["In"],"h":"Apesar do pouco tempo, concluímos tudo."}],"order":[{"t":["Although","it","rained,","we","continued","working."],"h":"Embora tenha chovido, continuamos trabalhando."},{"t":["Despite","the","difficulties,","they","succeeded."],"h":"Apesar das dificuldades, eles tiveram sucesso."},{"t":["We","left","early","to","avoid","traffic."],"h":"Saímos cedo para evitar o trânsito."}],"dict":[{"t":"Although the weather forecast was disappointing, we decided to continue preparing the community fair."},{"t":"Despite having a limited budget, the organizers managed to provide activities for all ages."},{"t":"Some volunteers preferred working indoors, whereas others wanted to help outside."},{"t":"We moved the information desk closer to the entrance so that visitors could find it more easily."},{"t":"The team revised the schedule in order to avoid confusion and keep everyone informed."}],"shadow":["Although the weather forecast looks terrible, I still think we should go ahead with Saturday's community fair.","In spite of having a limited budget, we've managed to organize something much bigger than last year's event.","Agreed. The musicians can use the main hall, whereas the children's activities can take place in the library.","Exactly. Although the weather isn't ideal, the fair can still be a success if we prepare carefully."],"write":{"task":"Escreva 7 a 9 frases sobre um evento ou projeto com problemas, contrastando obstáculos e resultados, comparando opiniões e explicando duas decisões com so that e in order to.","ph":"Although …, we decided to … Despite …, we managed to … Some people preferred …, whereas others … We changed our plans so that …"},"cards":[["Embora estivesse cansada, ela continuou trabalhando.","Although she was tired, she kept working."],["Apesar do atraso, chegamos a tempo.","Despite the delay, we arrived on time."],["Mesmo sendo difícil, valeu a pena.","Even though it was difficult, it was worth it."],["Apesar de trabalhar muito, ele ganha pouco.","In spite of working hard, he earns very little."],["Gosto de chá, enquanto ela prefere café.","I like tea, whereas she prefers coffee."],["Saímos cedo para evitar trânsito.","We left early in order to avoid traffic."],["Vou explicar novamente para que você entenda.","I'll explain it again so that you can understand."],["Apesar dos problemas, não desistimos.","Despite the problems, we didn't give up."],["Ele fala pouco, enquanto o irmão é comunicativo.","He doesn't talk much, whereas his brother is very outgoing."],["Ela economizou para comprar um carro.","She saved money in order to buy a car."]]},{"title":"Getting Used to It","goal":"Comparar hábitos antigos com a rotina atual e descrever familiaridade e adaptação usando used to, be used to e get used to.","speakers":{"Emma":"f","Lucas":"m"},"setting":"Lucas visita Emma em seu novo apartamento em Chicago, três meses depois de ela sair de uma cidade pequena para trabalhar em tecnologia.","lines":[["Lucas","So, you've been living in Chicago for three months now. Are you finally getting used to the city?","Então já está há três meses em Chicago. Finalmente está se acostumando com a cidade?"],["Emma","Slowly! I used to live in a quiet town where everyone knew each other. Everything here moves much faster.","Aos poucos! Eu morava numa cidade tranquila onde todos se conheciam. Aqui tudo é mais rápido."],["Lucas","I can imagine. You used to drive everywhere, didn't you? Now you take the train almost every day.","Imagino. Você costumava dirigir para todo lado, não é? Agora pega o trem quase todo dia."],["Emma","Exactly. At first, I wasn't used to taking public transportation during rush hour. The crowds were overwhelming.","Exatamente. No começo, eu não estava acostumada com o transporte público no horário de pico. A multidão assustava."],["Lucas","Has that gotten easier? You seem pretty relaxed about the commute compared with your first week.","Isso ficou mais fácil? Você parece bem mais tranquila com o deslocamento do que na primeira semana."],["Emma","Definitely. I'm getting used to the trains, and I've learned which stations are less crowded in the morning.","Com certeza. Estou me acostumando com os trens e aprendi quais estações são menos lotadas de manhã."],["Lucas","What about work? You told me your old company didn't use to organize so many video meetings.","E o trabalho? Você contou que sua empresa antiga não costumava organizar tantas videochamadas."],["Emma","That's right. I'm used to working independently, but this team expects everyone to collaborate throughout the day.","Isso. Estou acostumada a trabalhar sozinha, mas essa equipe espera colaboração ao longo do dia."],["Lucas","That must have been difficult initially. Are you getting used to sharing your progress with the team?","Deve ter sido difícil no início. Está se acostumando a compartilhar seu progresso com a equipe?"],["Emma","Yes. I used to find daily updates unnecessary, but now I understand why they help us avoid misunderstandings.","Sim. Antes eu achava atualizações diárias desnecessárias, mas agora vejo como evitam mal-entendidos."],["Lucas","And how are you sleeping? Last time we talked, you said you weren't used to the noise outside.","E o sono? Na última conversa, disse que não estava acostumada ao barulho da rua."],["Emma","I'm sleeping better. It took me a few weeks to get used to hearing traffic at night, but it barely bothers me now.","Durmo melhor. Levei semanas para me acostumar ao trânsito noturno, mas agora quase não incomoda."],["Lucas","That's progress. Do you miss your old routine, or are you beginning to enjoy the changes?","É progresso. Sente falta da rotina antiga ou já está gostando das mudanças?"],["Emma","A bit of both. I used to have dinner with my family every Sunday, and I really miss those evenings.","Um pouco de ambos. Eu jantava com minha família aos domingos e sinto falta dessas noites."],["Lucas","Have you met many people here? Getting used to a new city must be easier when you have friends nearby.","Conheceu bastante gente? Adaptar-se a uma nova cidade deve ser mais fácil com amigos perto."],["Emma","I've joined a running club. I'm not used to exercising so early, but the people are friendly and welcoming.","Entrei num clube de corrida. Não estou acostumada a me exercitar tão cedo, mas todos são acolhedores."],["Lucas","Sounds promising. By this time next year, you'll probably be completely used to your new lifestyle.","Parece promissor. A esta altura do ano que vem, provavelmente estará acostumada com o novo estilo de vida."],["Emma","I hope so. Moving here was challenging, but I'm getting used to being more independent, and that's a good thing.","Espero. Mudar para cá foi difícil, mas estou me acostumando a ser mais independente, e isso é bom."]],"grammar":[{"h":"Used to + verbo: hábitos e situações anteriores","p":["<b>Used to + verbo base</b> descreve algo habitual ou verdadeiro no passado que já não faz parte da situação atual.","Na negativa, prefira <b>didn't use to</b>; nas perguntas, <b>Did + sujeito + use to + verbo?</b>. O auxiliar did já indica passado, por isso use fica sem D.","A estrutura destaca o contraste entre antes e agora."],"ex":[["I used to walk to school when I was younger.","Eu costumava ir a pé para a escola quando era mais novo."],["She didn't use to enjoy working from home.","Ela não costumava gostar de trabalhar em casa."],["Did you use to live near the beach?","Você morava perto da praia antigamente?"],["We used to meet every Friday after work.","Costumávamos nos encontrar toda sexta após o trabalho."]],"tip":"Com <b>did</b>, escreva use to, não used to."},{"h":"Be used to: já estar acostumado","p":["<b>Be used to + substantivo ou -ing</b> indica que algo já é familiar e não costuma causar estranhamento.","O verbo be muda com sujeito e tempo: am, is, were, will be used to.","O <b>to</b> aqui é uma preposição, não um marcador de infinitivo: por isso usamos verbo com -ing, como I'm used to waking up early."],"ex":[["I'm used to working under pressure.","Estou acostumado a trabalhar sob pressão."],["She's used to the cold weather.","Ela está acostumada com o frio."],["We weren't used to such a busy schedule.","Não estávamos acostumados com uma rotina tão cheia."],["Are you used to waking up early?","Você está acostumado a acordar cedo?"]],"tip":"Diga <b>I'm used to driving</b>, não I'm used to drive."},{"h":"Get used to: processo de adaptação","p":["<b>Get used to + substantivo ou -ing</b> destaca o processo de adaptação: algo inicialmente estranho está se tornando familiar.","Pode aparecer em diferentes tempos: I'm getting used to, I got used to, I'll get used to.","Também podemos indicar a duração com It took me weeks to get used to..., seguida de substantivo ou -ing."],"ex":[["I'm getting used to living alone.","Estou me acostumando a morar sozinho."],["She got used to taking the train every morning.","Ela se acostumou a pegar o trem pela manhã."],["You'll get used to the new software eventually.","Você acabará se acostumando ao programa."],["It took me months to get used to my new job.","Levei meses para me adaptar ao novo emprego."]],"tip":"<b>Be used to</b> indica familiaridade; <b>get used to</b>, adaptação."},{"h":"Comparar used to, be used to e get used to","p":["As três expressões parecem semelhantes, mas não são intercambiáveis.","<b>I used to work at night</b> é hábito antigo; <b>I'm used to working at night</b> significa que isso já é familiar; <b>I'm getting used to working at night</b> indica que ainda estou me adaptando.","Uma descrição de mudança pessoal pode usar as três para contar o passado, o processo e a situação presente."],"ex":[["I used to drive to work, but now I take the subway.","Eu costumava ir de carro, mas hoje pego o metrô."],["I'm used to taking the subway every morning.","Estou acostumado a pegar o metrô toda manhã."],["It was difficult at first, but I'm getting used to the commute.","Foi difícil no início, mas estou me acostumando com o deslocamento."]],"tip":"Identifique se fala de <b>antigamente</b>, <b>familiaridade atual</b> ou <b>adaptação em andamento</b>."}],"vocab":[{"h":"Mudança de cidade","items":[["commute","deslocamento ao trabalho"],["rush hour","horário de pico"],["public transportation","transporte público"],["crowded","lotado"],["overwhelming","intenso e difícil de lidar"],["neighborhood","bairro"],["traffic noise","barulho do trânsito"],["lifestyle","estilo de vida"],["settle in","adaptar-se a um lugar"]]},{"h":"Trabalho e adaptação","items":[["collaborate","colaborar"],["work independently","trabalhar de forma independente"],["share progress","compartilhar progresso"],["daily update","atualização diária"],["misunderstanding","mal-entendido"],["get the hang of something","pegar o jeito de algo"],["adjust to","adaptar-se a"],["feel at home","sentir-se em casa"],["welcoming","acolhedor"]]}],"pron":[{"h":"Used to para hábito antigo","p":"Na expressão de hábito antigo, used to costuma soar “iústə”, com to reduzido e D pouco perceptível.","w":["used to work","used to live","I used to drive","we used to meet"]},{"h":"Be used to: final sonoro","p":"Em be used to, used termina num grupo consonantal com ZD: I'm used to it soa aproximadamente “aim iúzd tə it”.","w":["I'm used to it","she's used to working","we're used to the noise","are you used to it?"]},{"h":"Getting used to","p":"No inglês americano, o T de getting frequentemente soa como D rápido, aproximadamente “gué-ding”.","w":["getting used to","I'm getting used to it","getting used to working","you'll get used to it"]}],"mc":[{"q":"Como era a cidade anterior de Emma?","o":["Grande e movimentada","Pequena e tranquila","Muito turística"],"a":1,"e":"Slowly! I used to live in a quiet town where everyone knew each other. Everything here moves much faster."},{"q":"Que dificuldade tinha com transporte?","o":["Multidão no horário de pico","Não havia estação perto","Dirigia três horas todo dia"],"a":0,"e":"Exactly. At first, I wasn't used to taking public transportation during rush hour. The crowds were overwhelming."},{"q":"Qual é a diferença no trabalho?","o":["Nova empresa não colabora","Antiga fazia atualizações diárias","Nova equipe exige colaboração constante"],"a":2,"e":"That's right. I'm used to working independently, but this team expects everyone to collaborate throughout the day."},{"q":"O que ela fez para conhecer pessoas?","o":["Entrou num clube de corrida","Começou curso de culinária","Virou voluntária de biblioteca"],"a":0,"e":"I've joined a running club. I'm not used to exercising so early, but the people are friendly and welcoming."}],"gaps":[{"s":"I ___ to live in a small town, but now I live in Chicago. (Past-habit structure.)","a":["used"],"h":"Eu morava numa cidade pequena, mas agora moro em Chicago."},{"s":"She didn't ___ to take the train to work. (Base form after did.)","a":["use"],"h":"Ela não costumava pegar o trem para trabalhar."},{"s":"I'm used to ___ early every morning. (Use wake up in -ing.)","a":["waking up"],"h":"Estou acostumado a acordar cedo todo dia."},{"s":"She's getting used ___ her new job. (Complete adaptation structure.)","a":["to"],"h":"Ela está se acostumando com o emprego novo."},{"s":"It took me a month to get used to ___ alone. (Use live in -ing.)","a":["living"],"h":"Levei um mês para me acostumar a morar sozinho."},{"s":"___ you use to work on weekends? (Past-habit question.)","a":["Did"],"h":"Você costumava trabalhar nos fins de semana?"}],"order":[{"t":["I","used","to","live","near","the","beach."],"h":"Eu morava perto da praia antigamente."},{"t":["She's","used","to","working","from","home."],"h":"Ela está acostumada a trabalhar de casa."},{"t":["You'll","get","used","to","it","eventually."],"h":"Você acabará se acostumando com isso."}],"dict":[{"t":"I used to live in a quiet town, but now I'm surrounded by traffic and crowded streets."},{"t":"She didn't use to enjoy public transportation, although she's getting used to taking the train."},{"t":"I'm used to working independently, but my new position requires more collaboration."},{"t":"It took me several weeks to get used to waking up early and commuting every morning."},{"t":"By this time next year, I'll probably be completely used to living in a bigger city."}],"shadow":["Slowly! I used to live in a quiet town where everyone knew each other. Everything here moves much faster.","Exactly. At first, I wasn't used to taking public transportation during rush hour. The crowds were overwhelming.","That's right. I'm used to working independently, but this team expects everyone to collaborate throughout the day.","I hope so. Moving here was challenging, but I'm getting used to being more independent, and that's a good thing."],"write":{"task":"Escreva 7 a 9 frases comparando sua rotina atual e a de anos atrás com used to, be used to e get used to, incluindo negativas e uma expectativa futura.","ph":"A few years ago, I used to … I didn't use to … Nowadays, I'm used to … I'm still getting used to …"},"cards":[["Eu costumava morar perto do trabalho.","I used to live near my workplace."],["Ela não costumava acordar tão cedo.","She didn't use to wake up so early."],["Você costumava trabalhar aos sábados?","Did you use to work on Saturdays?"],["Estou acostumado a trabalhar sob pressão.","I'm used to working under pressure."],["Ela está acostumada com o frio.","She's used to the cold weather."],["Ainda não estou acostumado com essa rotina.","I'm not used to this routine yet."],["Estou me acostumando a morar sozinho.","I'm getting used to living alone."],["Você vai se acostumar com o novo horário.","You'll get used to the new schedule."],["Demorei para me acostumar com o barulho.","It took me a while to get used to the noise."],["Costumávamos nos encontrar toda semana.","We used to meet every week."]]},{"title":"Formal or Informal?","goal":"Adaptar inglês ao registro formal, neutro ou informal em e-mails, reuniões e apresentações, distinguindo verbos frasais de equivalentes mais formais.","speakers":{"Sarah":"f","Emma":"f"},"setting":"Sarah e Emma preparam uma proposta de parceria e patrocínio: um e-mail formal, mensagens para voluntários e uma apresentação.","lines":[["Sarah","I've drafted an email to the potential sponsor, but I'm not sure the tone is professional enough. Could you review it?","Fiz um rascunho de e-mail para um possível patrocinador, mas não sei se está profissional. Pode revisar?"],["Emma","Of course. What's the opening line? Remember, we're contacting someone we've never worked with before.","Claro. Como começa? Lembre que estamos contatando alguém com quem nunca trabalhamos."],["Sarah","I wrote, Hi there, we're looking for some money to get our project going. It sounds a little too casual, doesn't it?","Escrevi algo como: Olá, procuramos dinheiro para começar o projeto. Soa informal demais, não?"],["Emma","A little. I'd start with Dear Ms. Parker and say, I'm writing to inquire about potential sponsorship opportunities.","Um pouco. Eu começaria com Prezada Sra. Parker e diria: Escrevo para consultar possíveis patrocínios."],["Sarah","That sounds better. Should I say we want to set up a meeting, or would arrange a meeting be more appropriate?","Melhor. Devo dizer set up a meeting ou arrange a meeting seria mais apropriado?"],["Emma","Arrange a meeting is more formal. You could write, We would appreciate the opportunity to discuss our proposal.","Arrange a meeting é mais formal. Poderia escrever: Agradeceríamos a chance de discutir a proposta."],["Sarah","Great. I also need to explain that we're looking into different ways to fund the project.","Ótimo. Também preciso explicar que estamos analisando formas de financiar o projeto."],["Emma","In that context, you could replace looking into with exploring or investigating. Both sound more professional.","Nesse contexto, substitua looking into por exploring ou investigating. Ambos soam profissionais."],["Sarah","And how should I close the email? I usually write Thanks! Talk soon! when I'm messaging the volunteers.","E como termino? Com os voluntários geralmente escrevo Obrigada! Até breve!"],["Emma","For the sponsor, I'd use Thank you for your consideration, followed by Best regards and your full name.","Para o patrocinador, usaria Agradeço sua consideração, seguido de Atenciosamente e seu nome completo."],["Sarah","Perfect. Now, about next week's presentation. Should we go over the main figures before discussing the budget?","Perfeito. E a apresentação da próxima semana? Devemos revisar os números antes do orçamento?"],["Emma","Definitely. During the presentation, say, Let's review the key figures, instead of let's go over the numbers.","Com certeza. Na apresentação diga Let's review the key figures em vez de let's go over the numbers."],["Sarah","I also want to bring up our expansion plans, but I don't want to overwhelm the audience with too much information.","Também quero abordar a expansão, mas não quero sobrecarregar o público com detalhes."],["Emma","You could say, I'd like to address our plans for expansion. Then explain the main benefits briefly.","Poderia dizer: Gostaria de abordar os planos de expansão. Depois explique os benefícios brevemente."],["Sarah","Good point. What if someone asks a question we can't answer immediately? I don't want to seem unprepared.","Boa observação. E se perguntarem algo que não sabemos responder na hora? Não quero parecer despreparada."],["Emma","Say, That's an important question. We'll look into it and get back to you. It's polite and sounds natural.","Diga: É uma pergunta importante. Vamos analisar e retornar com a resposta. É educado e natural."],["Sarah","So formal language isn't necessarily about using complicated words. It's more about choosing the right tone.","Então linguagem formal não é necessariamente usar palavras difíceis, mas escolher o tom certo."],["Emma","Exactly. A professional message should be clear, respectful, and easy to understand. The audience matters more than fancy vocabulary.","Exatamente. Uma mensagem profissional deve ser clara, respeitosa e fácil de entender. O público importa mais que vocabulário rebuscado."]],"grammar":[{"h":"Registro formal, neutro e informal","p":["O registro depende do interlocutor, da relação entre as pessoas e do objetivo da mensagem.","Linguagem informal é frequente com amigos e colegas próximos; pode incluir contrações e expressões conversacionais.","Linguagem formal é comum em propostas e contatos institucionais. O registro neutro costuma funcionar muito bem no trabalho: clareza e respeito importam mais do que palavras difíceis."],"ex":[["Hi, can you send me the details?","Oi, pode mandar os detalhes? — Informal."],["Could you please send me the details?","Poderia me enviar os detalhes, por favor? — Neutro."],["I would appreciate it if you could provide the requested information.","Agradeceria se pudesse fornecer as informações solicitadas. — Formal."]],"tip":"Considere <b>destinatário, objetivo e relação</b> antes de escolher as palavras."},{"h":"E-mails profissionais","p":["Comece explicando o motivo do contato com expressões como <b>I'm writing to inquire about</b> ou <b>I'm contacting you regarding</b>.","Para pedidos educados, use Could you please...?, Would it be possible to...? e I would appreciate it if....","Dear Ms. Parker funciona num primeiro contato mais formal, enquanto Hi Emma é adequado entre colegas próximos.","Para encerrar, use Best regards, Kind regards ou Thank you for your consideration, conforme o contexto."],"ex":[["I'm writing to inquire about your training program.","Escrevo para solicitar informações sobre o treinamento."],["I would appreciate it if you could confirm your availability.","Agradeceria se pudesse confirmar sua disponibilidade."],["Please let me know if you require any further information.","Informe-me se precisar de informações adicionais."],["Thank you for your consideration. Best regards, Sarah.","Agradeço a consideração. Atenciosamente, Sarah."]],"tip":"Prefira e-mails <b>educados, objetivos e naturais</b>, sem formalidade artificial."},{"h":"Phrasal verbs e sinônimos mais formais","p":["Phrasal verbs combinam verbo e partícula e são comuns na conversa cotidiana, mas alguns podem ser substituídos por verbos mais formais.","<b>Set up → arrange</b>, <b>look into → investigate</b>, <b>put off → postpone</b>, <b>go over → review</b> e <b>bring up → raise/address</b>.","A troca não é sempre necessária: follow up e carry out, por exemplo, aparecem no trabalho. Escolha a expressão mais clara para o contexto."],"ex":[["We need to set up a meeting.","Precisamos marcar uma reunião. — Informal."],["We would like to arrange a meeting.","Gostaríamos de agendar uma reunião. — Formal."],["We decided to postpone the discussion.","Decidimos adiar a discussão."],["The team will investigate the issue.","A equipe investigará a questão."]],"tip":"Um sinônimo formal deve melhorar a <b>precisão</b>, não só soar mais complicado."},{"h":"Reuniões e apresentações","p":["Organize apresentações com frases como <b>Today, I'd like to discuss...</b>, <b>First, I'll outline...</b>, <b>Moving on to...</b> e <b>Finally...</b>.","Discorde com educação: I see your point, but..., One concern might be... ou Could we consider...?.","Se não souber uma resposta, reconheça a pergunta e proponha verificar: I'll check the details and get back to you. Não invente informações para parecer preparado."],"ex":[["Today, I'd like to outline the main goals of our project.","Hoje, gostaria de apresentar os objetivos do projeto."],["Moving on to the budget, let's review the key figures.","Passando ao orçamento, vamos analisar os principais números."],["I see your point, but we should consider the long-term costs.","Entendo seu ponto, mas devemos considerar os custos de longo prazo."],["I'll check that information and get back to you.","Vou verificar e depois retorno com uma resposta."]],"tip":"Faça transições claras e expresse discordância sem hostilidade."}],"vocab":[{"h":"E-mails profissionais","items":[["inquire about","solicitar informação sobre"],["regarding","referente a"],["potential sponsor","possível patrocinador"],["consideration","consideração"],["availability","disponibilidade"],["further information","informações adicionais"],["Best regards","atenciosamente"],["follow up","acompanhar; retomar contato"],["get back to someone","retornar contato"]]},{"h":"Expressões e equivalentes","items":[["set up / arrange","marcar; organizar"],["look into / investigate","investigar"],["put off / postpone","adiar"],["go over / review","revisar"],["bring up / raise","levantar um tema"],["find out / determine","descobrir; determinar"],["help out / assist","ajudar"],["deal with / address","lidar com um problema"]]},{"h":"Reuniões e apresentações","items":[["outline","apresentar pontos principais"],["key figures","principais indicadores"],["raise a concern","levantar preocupação"],["long-term costs","custos de longo prazo"],["moving on to","passando para"],["address a question","tratar de uma pergunta"],["main takeaway","principal conclusão"],["proposal","proposta"],["audience","público"]]}],"pron":[{"h":"Could you e would you","p":"Na fala, could you se conecta e pode soar “kúdju”; would you soa “uúdju”. O L é mudo em ambos.","w":["Could you help me?","Would you mind?","Could you please confirm?","Would you be available?"]},{"h":"Appreciate e consideration","p":"Appreciate soa aproximadamente “aprí-shi-eit”; consideration tem a sílaba próxima do final tônica, “kənsidərêishən”.","w":["appreciate","consideration","I would appreciate it","Thank you for your consideration"]},{"h":"Entonação para apresentar","p":"Em apresentações, faça pequenas pausas depois de First e Moving on to, sinalizando claramente a transição.","w":["First, I'd like to...","Moving on to...","I'd like to address...","Finally, let's consider..."]}],"mc":[{"q":"Por que a primeira versão do e-mail era informal?","o":["Cumprimento e pedido muito casuais","Faltava nome da empresa","Informações financeiras incorretas"],"a":0,"e":"I wrote, Hi there, we're looking for some money to get our project going. It sounds a little too casual, doesn't it?"},{"q":"Que termo substitui set up a meeting formalmente?","o":["Put off a meeting","Get into a meeting","Arrange a meeting"],"a":2,"e":"Arrange a meeting is more formal. You could write, We would appreciate the opportunity to discuss our proposal."},{"q":"Como Emma sugere falar da expansão?","o":["Começar com piada","Abordar planos e explicar brevemente benefícios","Exibir toda a informação técnica"],"a":1,"e":"You could say, I'd like to address our plans for expansion. Then explain the main benefits briefly."},{"q":"Como uma mensagem profissional deve ser?","o":["Usar palavras rebuscadas","Conter todos os detalhes","Clara, respeitosa e compreensível"],"a":2,"e":"Exactly. A professional message should be clear, respectful, and easy to understand. The audience matters more than fancy vocabulary."}],"gaps":[{"s":"I'm writing to ___ about potential sponsorship opportunities. (Use inquire.)","a":["inquire"],"h":"Escrevo para solicitar informações sobre possíveis patrocínios."},{"s":"We would like to ___ a meeting next week. (Formal synonym of set up.)","a":["arrange"],"h":"Gostaríamos de marcar uma reunião na semana que vem."},{"s":"The team will ___ the issue before deciding. (Formal synonym of look into.)","a":["investigate"],"h":"A equipe investigará a questão antes de decidir."},{"s":"We decided to ___ the meeting until Friday. (Formal synonym of put off.)","a":["postpone"],"h":"Decidimos adiar a reunião para sexta."},{"s":"I would ___ it if you could confirm your availability. (Use appreciate.)","a":["appreciate"],"h":"Agradeceria se pudesse confirmar sua disponibilidade."},{"s":"Moving ___ to the budget, let's review the key figures. (Presentation transition.)","a":["on"],"h":"Passando ao orçamento, vamos analisar os principais números."}],"order":[{"t":["Could","you","please","confirm","your","availability?"],"h":"Poderia confirmar sua disponibilidade, por favor?"},{"t":["We","would","like","to","arrange","a","meeting."],"h":"Gostaríamos de agendar uma reunião."},{"t":["Let's","review","the","main","points","first."],"h":"Vamos revisar os pontos principais primeiro."}],"dict":[{"t":"I'm writing to inquire about potential opportunities for collaboration between our organizations."},{"t":"We would appreciate the opportunity to arrange a meeting and discuss our proposal."},{"t":"The team has decided to postpone the launch in order to review the remaining technical issues."},{"t":"Moving on to the budget, I'd like to highlight the main figures and address our expansion plans."},{"t":"Thank you for your consideration. Please let me know if you require any further information."}],"shadow":["A little. I'd start with Dear Ms. Parker and say, I'm writing to inquire about potential sponsorship opportunities.","Arrange a meeting is more formal. You could write, We would appreciate the opportunity to discuss our proposal.","For the sponsor, I'd use Thank you for your consideration, followed by Best regards and your full name.","Exactly. A professional message should be clear, respectful, and easy to understand. The audience matters more than fancy vocabulary."],"write":{"task":"Escreva dois textos sobre a mesma situação: um e-mail profissional de 100 a 130 palavras solicitando reunião de projeto e uma mensagem informal de 40 a 60 palavras a um colega. Use três phrasal verbs e equivalentes formais.","ph":"Dear …, I'm writing to inquire about … We would appreciate the opportunity to … Best regards, … / Hi …! Just wanted to let you know that …"},"cards":[["Escrevo para solicitar informações sobre o projeto.","I'm writing to inquire about the project."],["Você poderia confirmar sua disponibilidade?","Could you please confirm your availability?"],["Gostaríamos de agendar uma reunião.","We would like to arrange a meeting."],["A equipe decidiu adiar a apresentação.","The team decided to postpone the presentation."],["Precisamos investigar essa questão.","We need to investigate this issue."],["Vamos analisar os principais resultados.","Let's review the key results."],["Gostaria de abordar uma preocupação.","I'd like to address a concern."],["Entendo seu ponto, mas tenho uma sugestão.","I see your point, but I have a suggestion."],["Agradeço sua consideração.","Thank you for your consideration."],["Vou verificar e retornar com uma resposta.","I'll check and get back to you."]]},{"title":"Had I Known","goal":"Usar inversões formais e enfáticas com Never have I, Not only, Rarely, Had I known, Should you need e Were it not for para discutir problemas e formular hipóteses.","speakers":{"Emma":"f","Daniel":"m"},"setting":"Emma e Daniel conversam no escritório sobre uma mudança inesperada nas exigências de um cliente, pouco antes da apresentação.","lines":[["Emma","The client called again this morning. Apparently, they've moved the final review to Thursday, and now they want a completely different presentation.","O cliente ligou novamente hoje de manhã. Pelo visto, anteciparam a revisão final para quinta-feira e agora querem uma apresentação completamente diferente."],["Daniel","Thursday? Had I known they were considering that, I would've warned the team yesterday. We've already spent two weeks preparing the original version.","Quinta-feira? Se eu soubesse que estavam considerando isso, teria avisado a equipe ontem. Já passamos duas semanas preparando a versão original."],["Emma","Wasn't the deadline supposed to be next Monday? I distinctly remember them confirming it during our last planning meeting.","O prazo não deveria ser na próxima segunda-feira? Lembro claramente de eles terem confirmado isso na nossa última reunião de planejamento."],["Daniel","It was. Not only did they move the deadline, but they also changed the requirements without consulting anyone on our side.","Era, sim. Eles não apenas anteciparam o prazo, como também mudaram as exigências sem consultar ninguém da nossa equipe."],["Emma","That's frustrating. Did they at least explain why the changes were suddenly so urgent, or are we supposed to figure that out ourselves?","Que frustração. Pelo menos explicaram por que as mudanças ficaram tão urgentes de repente, ou esperam que a gente descubra sozinho?"],["Daniel","Not really. Never have I seen a client change direction this dramatically so close to a deadline, and I've dealt with some demanding clients.","Não exatamente. Nunca vi um cliente mudar tanto de direção tão perto de um prazo, e já lidei com alguns clientes exigentes."],["Emma","That's saying something. Still, we should focus on what we can actually deliver rather than waste more time complaining about their decisions.","Isso diz muita coisa. Mesmo assim, devemos nos concentrar no que conseguimos entregar, em vez de perder mais tempo reclamando das decisões deles."],["Daniel","Agreed. Rarely do we get such little notice for a major revision, though. I'll need to rearrange the entire production schedule.","Concordo. Mas raramente recebemos tão pouco aviso para uma revisão importante. Vou precisar reorganizar todo o cronograma de produção."],["Emma","Could we reuse some of the research? Starting everything from scratch would be a terrible use of the time we have left.","Será que podemos reaproveitar parte da pesquisa? Começar tudo do zero seria um péssimo uso do tempo que nos resta."],["Daniel","Definitely. Had we received the updated requirements earlier, we could've incorporated them gradually. Now we'll have to prioritize the essentials.","Com certeza. Se tivéssemos recebido as exigências atualizadas antes, poderíamos tê-las incorporado aos poucos. Agora teremos que priorizar o essencial."],["Emma","I'll handle the revised outline and speak to Sarah about the visuals. Can you clarify which sections the client considers essential?","Vou cuidar do roteiro revisado e conversar com Sarah sobre os elementos visuais. Você consegue esclarecer quais partes o cliente considera essenciais?"],["Daniel","Of course. Should you need additional support, please don't hesitate to contact me. That's what I'll put in the follow-up email.","Claro. Caso precise de apoio adicional, não hesite em entrar em contato comigo. É isso que vou escrever no e-mail de acompanhamento."],["Emma","That's impressively formal. You sound like you're drafting a contract instead of offering to help someone you've worked with for years.","Isso é impressionantemente formal. Parece que você está redigindo um contrato em vez de oferecer ajuda a alguém com quem trabalha há anos."],["Daniel","Fair point. Between us, I'd just say to text me if anything comes up. But the client's management team expects a more polished tone.","Justo. Entre nós, eu diria simplesmente para me mandar mensagem se surgisse alguma coisa. Mas a diretoria do cliente espera um tom mais elaborado."],["Emma","Speaking of preparation, who noticed the contradiction between the new requirements and the budget they'd previously approved?","Falando em preparação, quem percebeu a contradição entre as novas exigências e o orçamento que eles tinham aprovado anteriormente?"],["Daniel","Sarah did. Were it not for her detailed checklist, we'd probably have agreed to deliver extra work without discussing the additional cost.","Foi a Sarah. Se não fosse pela lista detalhada dela, provavelmente teríamos concordado em entregar trabalho extra sem discutir o custo adicional."],["Emma","She deserves some serious recognition. I sometimes wonder whether the client realizes how much effort goes into preventing these problems.","Ela merece muito reconhecimento. Às vezes me pergunto se o cliente percebe quanto esforço é necessário para evitar esses problemas."],["Daniel","Absolutely. Not only did she catch the budget issue, but she also proposed a workable alternative. Without her, we'd be in a much worse position.","Com certeza. Ela não apenas identificou o problema do orçamento, como também propôs uma alternativa viável. Sem ela, estaríamos numa situação muito pior."]],"grammar":[{"h":"Inversão com expressões negativas","p":["Com Never, Rarely e outras expressões restritivas no início, colocamos o auxiliar antes do sujeito.","A inversão dá ênfase e costuma soar mais formal que a ordem comum."],"ex":[["Never have I encountered such resistance to a reasonable proposal.","Nunca encontrei tanta resistência a uma proposta razoável."],["Rarely do employees receive such detailed feedback.","Raramente funcionários recebem comentários tão detalhados."],["Under no circumstances should we share confidential information.","Em nenhuma circunstância devemos compartilhar informações confidenciais."]],"tip":"Não use Never I have seen: a forma enfática é <b>Never have I seen</b>."},{"h":"Not only... but also","p":["Quando Not only inicia a oração, invertemos auxiliar e sujeito na primeira oração.","Na segunda parte, a ordem permanece normal; also pode às vezes ser omitido."],"ex":[["Not only did we finish on time, but we also reduced costs.","Não apenas terminamos no prazo, como também reduzimos custos."],["Not only has she completed the research, but she has also prepared a summary.","Ela não apenas concluiu a pesquisa, como também preparou um resumo."],["The proposal not only addresses the problem but also offers a lasting solution.","A proposta não apenas resolve o problema, como oferece uma solução duradoura."]],"tip":"A inversão depende da posição: <b>Not only did...</b> e <b>We not only...</b>."},{"h":"Had I known: condicional sem if","p":["Em hipóteses contrárias ao passado, Had I known equivale a If I had known.","A oração principal frequentemente utiliza would have, could have ou might have mais particípio."],"ex":[["Had I known about the conflict, I would have suggested another date.","Se eu soubesse do conflito, teria sugerido outra data."],["Had they checked the contract, they might have avoided the dispute.","Se tivessem verificado o contrato, talvez tivessem evitado o conflito."],["Had we anticipated demand, we could have hired more staff.","Se tivéssemos previsto a demanda, poderíamos ter contratado mais funcionários."]],"tip":"Had I known é mais formal, mas tem o mesmo sentido hipotético de If I had known."},{"h":"Should you need e Were it not for","p":["Should you need introduz uma condição futura de maneira educada e formal.","Were it not for significa If it were not for em situações presentes; Had it not been for remete ao passado."],"ex":[["Should you require clarification, please contact us.","Caso precise de esclarecimentos, entre em contato conosco."],["Were it not for her support, the project would fail.","Se não fosse pelo apoio dela, o projeto fracassaria."],["Had it not been for their quick response, the disruption would have lasted longer.","Se não fosse pela resposta rápida deles, a interrupção teria durado mais."]],"tip":"Na conversa, if you need é mais comum do que should you need."}],"vocab":[{"h":"Prazos e mudanças","items":[["final review","revisão final"],["move the deadline","alterar o prazo"],["updated requirements","exigências atualizadas"],["short notice","pouca antecedência"],["major revision","revisão importante"],["production schedule","cronograma de produção"],["revised outline","roteiro revisado"],["workable alternative","alternativa viável"]]},{"h":"Colaboração e formalidade","items":[["figure something out","descobrir ou resolver algo"],["start from scratch","começar do zero"],["prioritize the essentials","priorizar o essencial"],["follow-up email","e-mail de acompanhamento"],["don't hesitate to","não hesite em"],["polished tone","tom profissional elaborado"],["catch an issue","identificar um problema"],["under no circumstances","em nenhuma circunstância"]]}],"pron":[{"h":"Never have I","p":"Em fala conectada, have pode ser reduzido; a sequência soa aproximadamente “néver həv ái”.","w":["Never have I","Rarely do we","Not only did we"]},{"h":"Had I e Should you","p":"Had I pode soar aproximadamente “hédai”; should you pode soar “shúdju”.","w":["Had I known","Had we received","Should you need"]},{"h":"Would have e Were it","p":"Would have frequentemente reduz para would've, aproximadamente “wúdəv”.","w":["I would've warned","Were it not for","They could've avoided"]}],"mc":[{"q":"O que o cliente mudou?","o":["Cancelou o projeto","Antecipou a revisão e pediu outra apresentação","Aumentou o prazo"],"a":1,"e":"The client called again this morning. Apparently, they've moved the final review to Thursday, and now they want a completely different presentation."},{"q":"O que Daniel critica?","o":["Mudança sem consultar a equipe","Ausência de orçamento anterior","Falta de pesquisa"],"a":0,"e":"It was. Not only did they move the deadline, but they also changed the requirements without consulting anyone on our side."},{"q":"O que Daniel pretende priorizar?","o":["Redesenhar toda a pesquisa","Adiar indefinidamente","Os elementos essenciais"],"a":2,"e":"Definitely. Had we received the updated requirements earlier, we could've incorporated them gradually. Now we'll have to prioritize the essentials."},{"q":"O que Sarah identificou?","o":["Um defeito técnico","Um problema de orçamento","Um erro na tradução"],"a":1,"e":"Absolutely. Not only did she catch the budget issue, but she also proposed a workable alternative. Without her, we'd be in a much worse position."}],"gaps":[{"s":"___ I known about the deadline, I would have called sooner.","a":["Had"],"h":"Se soubesse do prazo, teria ligado antes."},{"s":"Not only ___ they change the schedule, but they also added tasks.","a":["did"],"h":"Eles não apenas mudaram o cronograma, como também acrescentaram tarefas."},{"s":"Rarely ___ we receive such little notice.","a":["do"],"h":"Raramente recebemos tão pouco aviso."},{"s":"Never ___ I experienced such a delay.","a":["have"],"h":"Nunca passei por um atraso assim."},{"s":"___ you require assistance, contact us.","a":["Should"],"h":"Caso precise de ajuda, entre em contato."},{"s":"___ it not for Sarah, we would be struggling.","a":["Were"],"h":"Se não fosse pela Sarah, estaríamos enfrentando dificuldades."}],"order":[{"t":["Had","I","known,","I","would","have","called."],"h":"Se eu soubesse, teria ligado."},{"t":["Rarely","do","we","see","results","like","these."],"h":"Raramente vemos resultados como esses."},{"t":["Should","you","need","help,","contact","me."],"h":"Caso precise de ajuda, entre em contato comigo."}],"dict":[{"t":"Never have I worked with a client who changed the requirements so dramatically at the last minute."},{"t":"Not only did the team complete the project on time, but they also managed to reduce the overall cost."},{"t":"Had we received the correct information earlier, we could have avoided several unnecessary meetings."},{"t":"Should you encounter any technical difficulties during the presentation, please notify the support team immediately."},{"t":"Were it not for Sarah's careful planning, we would be facing a far more complicated situation."}],"shadow":["Thursday? Had I known they were considering that, I would've warned the team yesterday. We've already spent two weeks preparing the original version.","It was. Not only did they move the deadline, but they also changed the requirements without consulting anyone on our side.","Agreed. Rarely do we get such little notice for a major revision, though. I'll need to rearrange the entire production schedule.","Sarah did. Were it not for her detailed checklist, we'd probably have agreed to deliver extra work without discussing the additional cost."],"write":{"task":"Escreva de 100 a 130 palavras sobre uma mudança inesperada em um projeto. Use três inversões diferentes e proponha uma solução.","ph":"Had we known about …, we would have … Not only did …, but … Should you need …"},"cards":[["Nunca testemunhei uma mudança tão repentina.","Never have I witnessed such a sudden change."],["Raramente recebemos reclamações tão detalhadas.","Rarely do we receive such detailed complaints."],["Eles não apenas discordaram, mas apresentaram outra proposta.","Not only did they disagree, but they also presented another proposal."],["Se eu soubesse do problema, teria agido antes.","Had I known about the problem, I would have acted sooner."],["Caso precise de informações, entre em contato.","Should you need further information, please get in touch."],["Se não fosse pela experiência dela, estaríamos perdidos.","Were it not for her experience, we'd be lost."],["Em nenhuma circunstância devemos ignorar essa orientação.","Under no circumstances should we ignore this guidance."],["Se tivéssemos planejado melhor, teríamos economizado tempo.","Had we planned more carefully, we would have saved time."],["Poucas vezes vi uma equipe trabalhar tão bem sob pressão.","Seldom have I seen a team work so well under pressure."],["Se não fosse pela ajuda deles, não teríamos conseguido.","Had it not been for their help, we wouldn't have succeeded."]]},{"title":"What I Need Is...","goal":"Usar frases clivadas para destacar informações, corrigir interpretações e explicar prioridades com It was... that, What... is, All I..., The thing is e The reason why.","speakers":{"Emma":"f","Lucas":"m"},"setting":"Emma e Lucas analisam comentários de usuários sobre a configuração inicial de uma nova plataforma digital.","lines":[["Emma","I've gone through the feedback from our beta testers, and something doesn't add up. People like the platform, but a surprising number never finish setting up their accounts.","Analisei os comentários dos usuários beta, e tem algo que não faz sentido. As pessoas gostam da plataforma, mas muitas nunca terminam de configurar a conta."],["Lucas","I noticed that too. What concerns me is the gap between what users say they want and what they actually do during the setup process.","Também percebi. O que me preocupa é a diferença entre o que os usuários dizem querer e o que realmente fazem durante a configuração."],["Emma","Exactly. It was the onboarding process that received the most negative comments, not the platform's actual features. That's an important distinction.","Exatamente. Foi o processo inicial de configuração que recebeu mais comentários negativos, não os recursos da plataforma. É uma distinção importante."],["Lucas","So what we need is a clearer introduction, rather than another set of features nobody has asked for. We've been approaching this from the wrong angle.","Então o que precisamos é de uma introdução mais clara, e não de recursos que ninguém pediu. Estamos abordando isso do jeito errado."],["Emma","I agree, but the design team thinks we should add more instructions. I'm not convinced that giving users even more text will solve anything.","Concordo, mas a equipe de design acha que deveríamos acrescentar instruções. Não estou convencida de que mais texto vá resolver alguma coisa."],["Lucas","The thing is, people don't necessarily want more explanations. They want to understand what to do next without having to think too hard about it.","A questão é que as pessoas não querem necessariamente mais explicações. Querem entender o próximo passo sem precisar pensar demais."],["Emma","That's precisely what I've been trying to explain. All I'm asking for is a simpler first screen and some clearer guidance during registration.","É exatamente isso que venho tentando explicar. Tudo o que peço é uma primeira tela mais simples e orientações mais claras durante o cadastro."],["Lucas","And it isn't the amount of information that's necessarily causing the problem. It's how that information is presented and when users encounter it.","E não é necessariamente a quantidade de informações que está causando o problema. É como elas são apresentadas e quando os usuários as encontram."],["Emma","Right. The reason why so many people abandon the process is that they don't understand why we're requesting certain details so early.","Exato. O motivo de tantas pessoas desistirem é que não entendem por que pedimos determinados dados tão cedo."],["Lucas","That's interesting. Was it the request for a phone number that triggered most of those complaints, or was it something else entirely?","Interessante. Foi a solicitação do telefone que provocou a maioria das reclamações ou foi algo completamente diferente?"],["Emma","It was the identity verification step that caused the biggest drop-off. People were asked to upload documents before they'd even explored the platform.","Foi a verificação de identidade que provocou a maior desistência. Pediam documentos antes mesmo de as pessoas explorarem a plataforma."],["Lucas","That explains a lot. What surprises me is that nobody questioned the order of those steps during our internal testing.","Isso explica muita coisa. O que me surpreende é ninguém ter questionado a ordem dessas etapas nos testes internos."],["Emma","To be fair, our internal testers already knew how everything worked. It's new users who struggle because they have no context for those requests.","Para ser justa, nossos testadores internos já sabiam como tudo funcionava. São os usuários novos que têm dificuldades por não entenderem essas solicitações."],["Lucas","So all we really need to do is postpone verification until it's actually required and give people a chance to explore first.","Então tudo o que realmente precisamos fazer é adiar a verificação até ser necessária e permitir que as pessoas explorem primeiro."],["Emma","Possibly, although I'd rather test that assumption. What matters most is whether the change improves completion rates without creating security risks.","Possivelmente, mas prefiro testar essa hipótese. O que importa é se a mudança aumenta a taxa de conclusão sem criar riscos de segurança."],["Lucas","Fair enough. We could run a small experiment with two versions. That way, we're making the decision based on evidence instead of personal preferences.","Justo. Podemos testar duas versões. Assim, decidiremos com base em evidências, não em preferências pessoais."],["Emma","Perfect. When we present the results, let's emphasize that it's the user experience we're trying to improve, not simply the number of registrations.","Perfeito. Ao apresentar os resultados, vamos destacar que queremos melhorar a experiência do usuário, não apenas o número de cadastros."],["Lucas","Exactly. The reason I'm optimistic is that the feedback points to a specific problem we can address. That's far better than having no idea why people are leaving.","Exatamente. Estou otimista porque os comentários apontam para um problema específico que podemos resolver. Muito melhor do que não saber por que desistem."]],"grammar":[{"h":"It is/was... that: destacar um elemento","p":["Frases clivadas dividem uma informação para enfatizar uma pessoa, causa, momento ou objeto.","A estrutura é It + be + elemento destacado + that + oração; para pessoas, who também é possível."],"ex":[["It was Sarah who identified the financial inconsistency.","Foi Sarah quem identificou a inconsistência financeira."],["It wasn't the price that bothered them; it was the lack of transparency.","Não foi o preço que os incomodou; foi a falta de transparência."],["It was during the interview that we discovered the problem.","Foi durante a entrevista que descobrimos o problema."]],"tip":"Use essa forma para corrigir uma interpretação ou enfatizar a causa exata."},{"h":"What... is: apresentar prioridades","p":["What + oração pode funcionar como sujeito e introduzir aquilo que merece destaque.","Essa estrutura é frequente em conversas e reuniões para explicar necessidades e avaliações."],"ex":[["What concerns me is the lack of accountability.","O que me preocupa é a falta de responsabilização."],["What we should focus on is improving customer support.","O que deveríamos priorizar é melhorar o atendimento ao cliente."],["What surprised everyone was the speed of the change.","O que surpreendeu todos foi a rapidez da mudança."]],"tip":"What I need is... é natural e direto, não necessariamente formal."},{"h":"All I... e The thing is","p":["All I want ou All I am asking for delimita uma exigência ou expectativa.","The thing is introduz uma ressalva, explicação ou dificuldade; tem tom conversacional."],"ex":[["All I'm asking for is a little more flexibility.","Tudo o que estou pedindo é um pouco mais de flexibilidade."],["All we need to do is review the instructions.","Tudo o que precisamos fazer é revisar as instruções."],["The thing is, we can't guarantee immediate results.","A questão é que não podemos garantir resultados imediatos."],["The thing is, we can't guarantee immediate results.","A questão é que não podemos garantir resultados imediatos."]],"tip":"Em contextos formais, The main issue is pode substituir The thing is."},{"h":"The reason why... is that","p":["The reason why introduz a causa de uma situação; why pode ser omitido.","Depois de the reason... is, that é uma forma clara e frequente de introduzir a explicação."],"ex":[["The reason why customers hesitate is that the terms are unclear.","A razão pela qual os clientes hesitam é que os termos são pouco claros."],["The reason the launch was postponed is that important issues remain unresolved.","O lançamento foi adiado porque questões importantes continuam sem solução."],["The reason I'm concerned is that we haven't tested the assumption.","Estou preocupado porque ainda não testamos a hipótese."]],"tip":"Na redação formal, prefira the reason is that em vez de the reason is because."}],"vocab":[{"h":"Experiência do usuário","items":[["beta tester","usuário de teste beta"],["user feedback","comentários de usuários"],["onboarding process","processo inicial de configuração"],["setup process","processo de configuração"],["completion rate","taxa de conclusão"],["drop-off","abandono de uma etapa"],["identity verification","verificação de identidade"],["registration","cadastro"],["user experience","experiência do usuário"]]},{"h":"Argumentação e foco","items":[["something doesn't add up","tem algo que não faz sentido"],["make a distinction","fazer uma distinção"],["underlying problem","problema fundamental"],["question an assumption","questionar uma hipótese"],["make a decision based on evidence","decidir com base em evidências"],["what matters most is","o que mais importa é"],["all I'm asking for is","tudo o que estou pedindo é"],["the thing is","a questão é que"]]}],"pron":[{"h":"What I e What we","p":"What I se conecta e pode soar “uótai”; what we, “uót-uí”.","w":["What I need","What we want","What concerns me"]},{"h":"It was... that","p":"O destaque recai no elemento enfatizado, como Sarah em It was Sarah that noticed.","w":["It was Sarah","It was the timing","It was the process"]},{"h":"The thing is","p":"Thing e is se conectam, aproximadamente “thíngiz”.","w":["The thing is","The reason why","All I want"]}],"mc":[{"q":"O que preocupa Lucas?","o":["A falta de recursos","A diferença entre o que dizem e fazem","A quantidade de senhas"],"a":1,"e":"I noticed that too. What concerns me is the gap between what users say they want and what they actually do during the setup process."},{"q":"Qual parte recebeu críticas?","o":["O processo inicial","Os recursos principais","O aplicativo móvel"],"a":0,"e":"Exactly. It was the onboarding process that received the most negative comments, not the platform's actual features. That's an important distinction."},{"q":"O que provocou maior abandono?","o":["Os planos de pagamento","As preferências de idioma","A verificação de identidade"],"a":2,"e":"It was the identity verification step that caused the biggest drop-off. People were asked to upload documents before they'd even explored the platform."},{"q":"Qual prioridade Emma destaca?","o":["Eliminar cadastros","Melhorar a experiência","Criar mais textos"],"a":1,"e":"Perfect. When we present the results, let's emphasize that it's the user experience we're trying to improve, not simply the number of registrations."}],"gaps":[{"s":"It ___ the onboarding process that caused the complaints.","a":["was"],"h":"Foi o processo de configuração que causou as reclamações."},{"s":"___ we need is a clearer explanation.","a":["What"],"h":"O que precisamos é de uma explicação mais clara."},{"s":"All I am asking ___ is a little flexibility.","a":["for"],"h":"Tudo o que peço é um pouco de flexibilidade."},{"s":"The reason ___ people leave is that the instructions are unclear.","a":["why"],"h":"As pessoas desistem porque as instruções são pouco claras."},{"s":"It is the lack of communication ___ creates confusion.","a":["that"],"h":"É a falta de comunicação que gera confusão."},{"s":"The ___ is, we still lack enough evidence.","a":["thing"],"h":"A questão é que ainda não temos evidências suficientes."}],"order":[{"t":["What","we","need","is","better","communication."],"h":"O que precisamos é de uma comunicação melhor."},{"t":["It","was","Sarah","who","noticed","the","mistake."],"h":"Foi Sarah quem percebeu o erro."},{"t":["All","I","want","is","a","fair","opportunity."],"h":"Tudo o que quero é uma oportunidade justa."}],"dict":[{"t":"What concerns me most is that we are making decisions without understanding what our users actually need."},{"t":"It was not the cost that discouraged customers; it was the lack of transparency in the subscription terms."},{"t":"All I am asking for is an opportunity to test the proposal before we commit additional resources."},{"t":"The reason why the previous strategy failed is that nobody considered how inexperienced users might respond."},{"t":"The thing is, we need reliable evidence rather than assumptions if we want to make meaningful improvements."}],"shadow":["I noticed that too. What concerns me is the gap between what users say they want and what they actually do during the setup process.","Exactly. It was the onboarding process that received the most negative comments, not the platform's actual features. That's an important distinction.","That's precisely what I've been trying to explain. All I'm asking for is a simpler first screen and some clearer guidance during registration.","Exactly. The reason I'm optimistic is that the feedback points to a specific problem we can address. That's far better than having no idea why people are leaving."],"write":{"task":"Escreva 100 a 130 palavras sobre uma melhoria no trabalho ou em um aplicativo. Destaque o problema e a prioridade com quatro frases clivadas.","ph":"What concerns me most is … It is … that … All I am asking for is … The reason why …"},"cards":[["O que realmente precisamos é de mais transparência.","What we really need is greater transparency."],["Foi a falta de planejamento que causou o atraso.","It was the lack of planning that caused the delay."],["Tudo o que estou pedindo é uma explicação razoável.","All I'm asking for is a reasonable explanation."],["A questão é que ainda não temos dados suficientes.","The thing is, we still don't have enough data."],["O que mais me surpreendeu foi a reação da equipe.","What surprised me most was the team's reaction."],["Não foi o resultado que me incomodou, foi o processo.","It wasn't the result that bothered me; it was the process."],["O motivo da discordância é que a proposta ignora os riscos.","The reason why I disagree is that the proposal overlooks the risks."],["O mais importante é encontrar uma solução sustentável.","What matters most is finding a sustainable solution."],["É a comunicação que precisamos melhorar primeiro.","It's communication that we need to improve first."],["Tudo o que queremos é evitar o mesmo erro.","All we want is to avoid making the same mistake."]]},{"title":"It Would Appear That","goal":"Interpretar evidências e expressar graus de certeza com hedging: it would appear, tend to, arguably, seemingly, to some extent e is said to have.","speakers":{"Sarah":"f","Lucas":"m"},"setting":"Sarah e Lucas analisam resultados preliminares de um programa experimental de trabalho híbrido para apresentar à direção.","lines":[["Sarah","I've reviewed the results of our hybrid work pilot, and the initial findings look encouraging. Still, I'm hesitant to call it an unquestionable success.","Analisei os resultados do projeto experimental de trabalho híbrido, e eles parecem animadores. Mesmo assim, hesito em chamá-lo de um sucesso indiscutível."],["Lucas","That's reasonable. It would appear that employee satisfaction has improved, but we shouldn't assume the new arrangement is the only reason.","É razoável. Ao que tudo indica, a satisfação melhorou, mas não devemos presumir que o novo modelo seja a única razão."],["Sarah","Exactly. Productivity also seems to have increased slightly, although the difference is less significant than some managers initially suggested.","Exatamente. A produtividade também parece ter aumentado um pouco, embora menos do que alguns gestores sugeriram inicialmente."],["Lucas","The teams with more flexibility tend to report better work-life balance. That suggests a pattern, but it doesn't establish a direct causal relationship.","Equipes com mais flexibilidade tendem a relatar melhor equilíbrio entre vida pessoal e profissional. Isso sugere um padrão, não prova uma relação causal."],["Sarah","Right. And the figures are somewhat misleading if we ignore the fact that participation was voluntary. Our sample might not represent the entire company.","Certo. Os números são um tanto enganosos se ignorarmos que a participação foi voluntária. Nossa amostra talvez não represente toda a empresa."],["Lucas","Arguably, that's the biggest limitation of the study. People who already preferred working remotely were probably more likely to participate.","Pode-se argumentar que essa é a maior limitação do estudo. Quem já preferia trabalhar remotamente provavelmente tinha mais chance de participar."],["Sarah","There's also the issue of collaboration. Some employees reported fewer interruptions, whereas others seemingly struggled with spontaneous communication.","Também existe a questão da colaboração. Alguns funcionários relataram menos interrupções, enquanto outros aparentemente tiveram dificuldades para se comunicar espontaneamente."],["Lucas","It would seem that the arrangement works better for tasks requiring concentration than for projects that depend heavily on immediate feedback.","Tudo leva a crer que o modelo funciona melhor para tarefas que exigem concentração do que para projetos que dependem de comentários imediatos."],["Sarah","That's a fair interpretation, although I'd be careful with that wording. We haven't actually measured the quality of collaboration in a consistent way.","É uma interpretação razoável, mas eu teria cuidado com essa formulação. Ainda não medimos a qualidade da colaboração de maneira consistente."],["Lucas","True. Perhaps we could say the current findings suggest a potential benefit for independent work, while the impact on collaboration remains unclear.","Verdade. Talvez possamos dizer que os resultados sugerem benefício para o trabalho independente, enquanto o impacto na colaboração continua incerto."],["Sarah","Much better. To some extent, the pilot has demonstrated that greater flexibility is feasible. Whether it's sustainable in the long term is another question.","Muito melhor. Até certo ponto, o projeto demonstrou que mais flexibilidade é viável. Saber se isso é sustentável a longo prazo é outra questão."],["Lucas","I've also heard that a competing company adopted a similar policy last year. They're said to have reduced office expenses quite substantially.","Também ouvi dizer que uma concorrente adotou política semelhante no ano passado. Dizem que reduziu consideravelmente as despesas com escritórios."],["Sarah","That's worth investigating, but I'd avoid presenting it as a verified fact. We don't know whether those savings came directly from the policy.","Vale investigar, mas evitaria apresentar isso como fato comprovado. Não sabemos se a economia veio diretamente da política."],["Lucas","Agreed. Their approach is reportedly successful, but until we examine the underlying figures, it's little more than an interesting comparison.","Concordo. Segundo relatos, a abordagem é bem-sucedida, mas sem examinar os números não passa de uma comparação interessante."],["Sarah","Another concern is that newer employees appear to need more structured support. The interviews suggest they sometimes feel disconnected from experienced colleagues.","Outra preocupação é que funcionários novos parecem precisar de apoio mais estruturado. As entrevistas sugerem que às vezes se sentem distantes dos colegas experientes."],["Lucas","That makes sense. We could potentially address that through mentoring sessions, although we'd need further evidence before recommending a company-wide change.","Faz sentido. Poderíamos enfrentar isso com mentorias, mas precisaríamos de mais evidências antes de recomendar uma mudança para toda a empresa."],["Sarah","So our conclusion should be cautious but constructive. The results suggest some promising benefits, yet several important questions remain unanswered.","Nossa conclusão deve ser cautelosa, mas construtiva. Os resultados sugerem benefícios promissores, porém muitas questões continuam sem resposta."],["Lucas","Exactly. A credible report doesn't need to pretend we know everything. Sometimes acknowledging uncertainty is precisely what makes an argument more convincing.","Exatamente. Um relatório confiável não precisa fingir que sabemos tudo. Às vezes, reconhecer a incerteza torna o argumento mais convincente."]],"grammar":[{"h":"It would appear/seem","p":["Hedging ajusta o grau de certeza ao nível das evidências disponíveis.","It would appear/seem that expressa uma interpretação cautelosa, não uma certeza demonstrada."],"ex":[["It would appear that the changes have improved employee engagement.","Ao que tudo indica, as mudanças melhoraram o envolvimento dos funcionários."],["It would seem that the estimates were overly optimistic.","Tudo leva a crer que as estimativas foram excessivamente otimistas."],["Several participants seem to have misunderstood the instructions.","Vários participantes parecem ter entendido mal as instruções."]],"tip":"Seem to have + particípio permite inferir uma ação anterior."},{"h":"Tend to e to some extent","p":["Tend to descreve padrões frequentes sem generalizar para todos os casos.","To some extent limita a abrangência ou intensidade da avaliação."],"ex":[["New employees tend to benefit from frequent feedback.","Funcionários novos tendem a se beneficiar de comentários frequentes."],["To some extent, the changes addressed the concerns.","Até certo ponto, as mudanças resolveram as preocupações."],["The findings are somewhat encouraging but remain limited.","Os resultados são razoavelmente animadores, mas continuam limitados."]],"tip":"Tendência não é regra universal."},{"h":"Arguably e seemingly","p":["Arguably indica uma avaliação defensável, mas discutível.","Seemingly indica aparência, que pode não corresponder à realidade."],"ex":[["Arguably, this is the proposal's greatest weakness.","Pode-se argumentar que essa é a maior fraqueza da proposta."],["The approaches produced seemingly identical results.","As abordagens produziram resultados aparentemente idênticos."],["A seemingly minor change caused unexpected difficulties.","Uma mudança aparentemente pequena causou dificuldades inesperadas."]],"tip":"Arguably não significa simplesmente talvez."},{"h":"Is said to have: informações atribuídas","p":["Be said to + infinitivo atribui informação a terceiros; be said to have + particípio indica algo anterior.","Reportedly e is believed to também atribuem alegações, mas não provam a veracidade delas."],"ex":[["The company is said to have reduced office expenses.","Dizem que a empresa reduziu as despesas com escritórios."],["The policy is believed to have improved retention.","Acredita-se que a política tenha melhorado a retenção."],["The initiative reportedly attracted considerable interest.","Segundo relatos, a iniciativa despertou bastante interesse."]],"tip":"Em relatórios, atribuição vaga não substitui fontes verificáveis."}],"vocab":[{"h":"Evidências e pesquisa","items":[["initial findings","resultados iniciais"],["pilot program","programa experimental"],["underlying figures","números por trás da afirmação"],["causal relationship","relação de causa e efeito"],["misleading figures","números que podem induzir ao erro"],["representative sample","amostra representativa"],["verified fact","fato comprovado"],["further evidence","evidências adicionais"]]},{"h":"Cautela e trabalho híbrido","items":[["work-life balance","equilíbrio entre trabalho e vida pessoal"],["to some extent","até certo ponto"],["arguably","pode-se argumentar que"],["seemingly","aparentemente"],["reportedly","segundo relatos"],["is said to have","dizem que fez ou aconteceu"],["remain unclear","continuar incerto"],["structured support","apoio estruturado"],["long-term sustainability","sustentabilidade a longo prazo"]]}],"pron":[{"h":"Would appear","p":"Would costuma ter vogal reduzida, aproximadamente “uəd”; o destaque recai em appear.","w":["It would appear","It would seem","appear to be"]},{"h":"Arguably e seemingly","p":"Arguably soa “ár-gyu-ə-bli”; seemingly soa “síi-ming-li”.","w":["arguably","seemingly","seemingly identical"]},{"h":"Said to have","p":"To e have podem ser reduzidos: “iz séd tə həv”.","w":["is said to have","is believed to have","tend to report"]}],"mc":[{"q":"Por que Sarah é cautelosa?","o":["Não houve pesquisa","Os resultados são apenas iniciais","O projeto foi cancelado"],"a":1,"e":"I've reviewed the results of our hybrid work pilot, and the initial findings look encouraging. Still, I'm hesitant to call it an unquestionable success."},{"q":"Qual possível viés Lucas identifica?","o":["Voluntários já preferiam trabalhar remotamente","Participaram apenas diretores","Os custos não foram registrados"],"a":0,"e":"Arguably, that's the biggest limitation of the study. People who already preferred working remotely were probably more likely to participate."},{"q":"Por que a economia da concorrente não é fato comprovado?","o":["Não há concorrentes","Os números foram destruídos","A relação com a política não foi verificada"],"a":2,"e":"That's worth investigating, but I'd avoid presenting it as a verified fact. We don't know whether those savings came directly from the policy."},{"q":"Qual deve ser a conclusão do relatório?","o":["Certeza absoluta","Cautela e reconhecimento das limitações","A rejeição de toda evidência"],"a":1,"e":"So our conclusion should be cautious but constructive. The results suggest some promising benefits, yet several important questions remain unanswered."}],"gaps":[{"s":"It would ___ that satisfaction has improved.","a":["appear"],"h":"Ao que tudo indica, a satisfação melhorou."},{"s":"Employees ___ to prefer greater flexibility.","a":["tend","seem","appear"],"h":"Funcionários tendem a preferir mais flexibilidade."},{"s":"To some ___, the policy has addressed the concerns.","a":["extent"],"h":"Até certo ponto, a política resolveu as preocupações."},{"s":"___, the main weakness is the small sample.","a":["Arguably"],"h":"Pode-se argumentar que a principal fraqueza é a amostra pequena."},{"s":"The company is said to ___ reduced costs.","a":["have"],"h":"Dizem que a empresa reduziu custos."},{"s":"The two methods produced ___ identical results.","a":["seemingly"],"h":"Os dois métodos produziram resultados aparentemente idênticos."}],"order":[{"t":["It","would","appear","that","productivity","has","improved."],"h":"Ao que tudo indica, a produtividade melhorou."},{"t":["Employees","tend","to","prefer","greater","flexibility."],"h":"Funcionários tendem a preferir mais flexibilidade."},{"t":["The","company","is","said","to","have","expanded."],"h":"Dizem que a empresa se expandiu."}],"dict":[{"t":"It would appear that the new arrangement has improved employee satisfaction, although the available evidence remains limited."},{"t":"People often perform better when expectations are clear and feedback is constructive."},{"t":"Arguably, the greatest challenge is determining whether the improvements will remain sustainable over time."},{"t":"The organization is said to have introduced significant changes, but the financial consequences remain unclear."},{"t":"To some extent, the findings support our assumptions, although further research is needed before drawing firm conclusions."}],"shadow":["That's reasonable. It would appear that employee satisfaction has improved, but we shouldn't assume the new arrangement is the only reason.","Arguably, that's the biggest limitation of the study. People who already preferred working remotely were probably more likely to participate.","Much better. To some extent, the pilot has demonstrated that greater flexibility is feasible. Whether it's sustainable in the long term is another question.","Exactly. A credible report doesn't need to pretend we know everything. Sometimes acknowledging uncertainty is precisely what makes an argument more convincing."],"write":{"task":"Escreva 110 a 140 palavras analisando uma tendência e distinguindo observações de hipóteses. Use cinco expressões de cautela e atribuição.","ph":"It would appear that … People tend to … Arguably, … To some extent, … Further evidence is needed …"},"cards":[["Ao que tudo indica, a situação está melhorando.","It would appear that the situation is improving."],["As pessoas tendem a resistir a mudanças inesperadas.","People tend to resist unexpected changes."],["Até certo ponto, concordo com essa interpretação.","To some extent, I agree with that interpretation."],["Pode-se argumentar que essa é a opção mais equilibrada.","Arguably, this is the most balanced option."],["Uma mudança aparentemente simples pode trazer consequências.","A seemingly simple change can have consequences."],["Dizem que a empresa investiu muito em pesquisa.","The company is said to have invested heavily in research."],["Os resultados parecem ter melhorado desde janeiro.","The results appear to have improved since January."],["Segundo relatos, o projeto enfrentou dificuldades.","The project reportedly encountered difficulties."],["A relação entre esses fatores continua incerta.","The relationship between these factors remains unclear."],["Precisamos de mais evidências antes de concluir.","Further evidence is needed before drawing conclusions."]]},{"title":"But for That","goal":"Expressar condições e consequências usando but for, supposing, provided that, as long as, otherwise, or else e if it weren't for.","speakers":{"Sarah":"f","Daniel":"m"},"setting":"Sarah e Daniel negociam ajustes na conferência após uma redução inesperada do patrocínio.","lines":[["Sarah","I've just spoken to our main sponsor. They've decided to reduce their contribution by nearly thirty percent, which puts us in a rather difficult position.","Acabei de falar com o patrocinador principal. Ele decidiu reduzir a contribuição em quase trinta por cento, o que nos deixa numa situação difícil."],["Daniel","That's a substantial cut. But for the additional funding we secured last month, we'd probably have to cancel part of the conference altogether.","É um corte considerável. Se não fosse pelo financiamento adicional do mês passado, provavelmente teríamos que cancelar parte da conferência."],["Sarah","Exactly. The question is whether we can reorganize the budget without compromising the experience we've promised our participants.","Exatamente. A questão é se conseguimos reorganizar o orçamento sem comprometer a experiência prometida aos participantes."],["Daniel","We could reduce the catering expenses, provided that the venue allows us to bring in an external supplier. Have you checked their contract?","Poderíamos reduzir os gastos com alimentação, desde que o local permita um fornecedor externo. Você verificou o contrato?"],["Sarah","I have. They're willing to make an exception as long as we notify them at least ten days in advance and meet their safety requirements.","Verifiquei. Aceitam uma exceção contanto que avisemos com dez dias de antecedência e cumpramos as exigências de segurança."],["Daniel","Good. Supposing we manage to negotiate a better catering deal, would that leave enough money to cover the speakers' travel expenses?","Ótimo. Supondo que consigamos negociar um contrato de alimentação melhor, sobraria dinheiro para cobrir as viagens dos palestrantes?"],["Sarah","Possibly, although we'd still be cutting it close. We'd need to confirm the revised costs by Wednesday; otherwise, we risk missing the payment deadline.","Possivelmente, mas ainda ficaríamos no limite. Precisamos confirmar os custos até quarta; caso contrário, arriscamos perder o prazo de pagamento."],["Daniel","Then we should contact the suppliers today. We can't afford to leave everything until the last minute, or else we'll lose whatever flexibility we still have.","Então devemos falar com os fornecedores hoje. Não podemos deixar tudo para a última hora, senão perderemos a flexibilidade que resta."],["Sarah","Agreed. Another possibility would be moving one workshop online, but only if the speaker agrees and we can guarantee reliable technical support.","Concordo. Outra opção é transferir uma oficina para o formato online, mas só se o palestrante concordar e garantirmos suporte técnico confiável."],["Daniel","I'm not against it, but supposing the connection fails halfway through the session? We'd have disappointed participants and no straightforward way to compensate them.","Não sou contra, mas e se a conexão falhar no meio da sessão? Teríamos participantes decepcionados sem maneira simples de compensá-los."],["Sarah","That's a fair concern. We could record a backup presentation beforehand, provided that the speaker gives us permission to distribute it if necessary.","É uma preocupação válida. Podemos gravar uma apresentação reserva, desde que o palestrante permita distribuí-la se necessário."],["Daniel","That could work. If it weren't for Emma's technical expertise, I'd be much less confident about handling a hybrid event at such short notice.","Isso pode funcionar. Se não fosse pela experiência técnica da Emma, eu teria bem menos confiança num evento híbrido com tão pouca antecedência."],["Sarah","She's already offered to coordinate the equipment. As long as we don't add any unnecessary features, she thinks the existing setup should be sufficient.","Ela já se ofereceu para coordenar os equipamentos. Contanto que não acrescentemos recursos desnecessários, acha que a estrutura atual basta."],["Daniel","There's one more issue. The sponsor wants greater visibility in exchange for maintaining the remaining funding. Are we comfortable with that arrangement?","Mais uma questão: o patrocinador quer mais visibilidade em troca de manter o financiamento restante. Concordamos com isso?"],["Sarah","Provided that they don't influence the content of the presentations, I wouldn't necessarily object. We should make those boundaries explicit in writing, though.","Desde que não influenciem o conteúdo das apresentações, eu não seria necessariamente contra. Mas devemos deixar os limites por escrito."],["Daniel","Absolutely. But for our agreement with the independent speakers, the sponsor might have had considerably more influence over the program.","Com certeza. Se não fosse pelo nosso acordo com os palestrantes independentes, o patrocinador poderia ter tido mais influência."],["Sarah","So let's revise the budget, confirm the supplier's conditions, and document the sponsorship terms. We can still deliver a successful event if we're disciplined.","Vamos revisar o orçamento, confirmar as condições e documentar o patrocínio. Ainda podemos realizar um bom evento com disciplina."],["Daniel","Agreed. The situation isn't ideal, but it isn't hopeless either. Provided everyone follows through on their commitments, we should be able to make it work.","Concordo. A situação não é ideal, mas também não é desesperadora. Desde que todos cumpram seus compromissos, conseguiremos resolver."]],"grammar":[{"h":"But for: condição implícita","p":["But for + substantivo equivale a if it weren't for ou if it hadn't been for.","Pode apresentar consequências hipotéticas presentes ou resultados contrários ao passado."],"ex":[["But for your intervention, the negotiation would have collapsed.","Se não fosse sua intervenção, a negociação teria fracassado."],["But for the support we receive, the initiative would be impossible.","Se não fosse pelo apoio que recebemos, a iniciativa seria impossível."],["But for a minor issue, the presentation would have gone as planned.","Se não fosse um pequeno problema, a presentation teria ocorrido conforme planejado."]],"tip":"But for normalmente é seguido de expressão nominal, não de oração completa."},{"h":"Supposing: explorar cenários","p":["Supposing introduz cenários hipotéticos, semelhante a what if.","Use presente para hipóteses futuras; passado para hipóteses remotas; past perfect para contrafactuais."],"ex":[["Supposing the negotiations fail, what should we do?","Supondo que as negociações fracassem, o que fazemos?"],["Supposing you were offered a job abroad, would you go?","Supondo que lhe oferecessem um emprego no exterior, você iria?"],["Supposing we had invested earlier, could we have saved money?","Supondo que tivéssemos investido antes, poderíamos ter economizado?"]],"tip":"Supposing apresenta uma possibilidade, não uma previsão."},{"h":"Provided that e as long as","p":["Ambos introduzem requisitos para que algo aconteça.","Provided that costuma ser mais formal; as long as é comum também na conversa.","Em condições futuras, usamos normalmente o presente simples, não will, na oração condicional."],"ex":[["We'll approve the plan provided that all requirements are met.","Aprovaremos o plano desde que todos os requisitos sejam cumpridos."],["You can adjust the schedule as long as you meet the deadlines.","Você pode ajustar o horário contanto que cumpra os prazos."],["We'll proceed provided that both parties accept the revised terms.","Prosseguiremos desde que as duas partes aceitem os termos revisados."]],"tip":"As long as pode enfatizar uma condição contínua."},{"h":"Otherwise, or else e if it weren't for","p":["Otherwise expressa uma consequência caso a condição anterior não seja cumprida.","Or else também pode indicar consequência, com tom mais urgente.","If it weren't for expressa hipótese presente; if it hadn't been for expressa hipótese passada."],"ex":[["Confirm the booking today; otherwise, you might lose it.","Confirme a reserva hoje; caso contrário, você pode perdê-la."],["Back up the files, or else you could lose your work.","Faça backup dos arquivos, senão poderá perder seu trabalho."],["If it weren't for her help, I wouldn't be considering this opportunity.","Se não fosse pela ajuda dela, eu não consideraria esta oportunidade."]],"tip":"Or else pode soar como advertência dependendo da entonação."}],"vocab":[{"h":"Financiamento e eventos","items":[["main sponsor","patrocinador principal"],["financial contribution","contribuição financeira"],["substantial cut","corte considerável"],["catering expenses","despesas com alimentação"],["external supplier","fornecedor externo"],["revised costs","custos revisados"],["backup presentation","apresentação reserva"],["sponsorship terms","termos do patrocínio"]]},{"h":"Condições e riscos","items":[["but for","se não fosse por"],["supposing","supondo que"],["provided that","desde que"],["as long as","contanto que"],["otherwise","caso contrário"],["or else","senão"],["cut it close","ficar no limite"],["make an exception","abrir uma exceção"],["follow through on a commitment","cumprir um compromisso"]]}],"pron":[{"h":"Provided that","p":"Aproximadamente “prə-vái-did dhət”, com destaque em vi.","w":["provided that","provided that we agree","provided that it works"]},{"h":"Supposing e otherwise","p":"Supposing soa “sə-pôu-zing”; otherwise, “â-dhər-uáiz”.","w":["supposing","otherwise","supposing we agree"]},{"h":"As long as e or else","p":"As long as pode soar “əz lóng əz”; or else conecta as palavras.","w":["as long as","or else","as long as we agree"]}],"mc":[{"q":"O que mudou no orçamento?","o":["Patrocínio foi reduzido","A prefeitura aumentou fundos","O local ficou gratuito"],"a":0,"e":"I've just spoken to our main sponsor. They've decided to reduce their contribution by nearly thirty percent, which puts us in a rather difficult position."},{"q":"Quando o local permite fornecedor externo?","o":["Sem aviso","Se forem cumpridos aviso e segurança","Apenas com pagamento integral"],"a":1,"e":"I have. They're willing to make an exception as long as we notify them at least ten days in advance and meet their safety requirements."},{"q":"Qual risco existe na oficina online?","o":["Ninguém fala inglês","Falta de inscrições","A conexão pode falhar"],"a":2,"e":"I'm not against it, but supposing the connection fails halfway through the session? We'd have disappointed participants and no straightforward way to compensate them."},{"q":"Qual limite ao patrocinador?","o":["Não deve influenciar as apresentações","Pode editar o conteúdo","Deve escolher os palestrantes"],"a":0,"e":"Provided that they don't influence the content of the presentations, I wouldn't necessarily object. We should make those boundaries explicit in writing, though."}],"gaps":[{"s":"___ for the funding, we would have canceled the event.","a":["But"],"h":"Se não fosse pelo financiamento, teríamos cancelado o evento."},{"s":"___ the supplier refuses, what will we do?","a":["Supposing","If"],"h":"Supondo que o fornecedor recuse, o que faremos?"},{"s":"We will proceed ___ that all costs are documented.","a":["provided"],"h":"Prosseguiremos desde que todos os custos sejam documentados."},{"s":"You may adjust the schedule as ___ as you meet the deadline.","a":["long"],"h":"Você pode ajustar o cronograma contanto que cumpra o prazo."},{"s":"Confirm the booking; ___, we may lose it.","a":["otherwise"],"h":"Confirme a reserva; caso contrário, podemos perdê-la."},{"s":"If it ___ for her expertise, we would be struggling.","a":["weren't","were not"],"h":"Se não fosse pela experiência dela, teríamos dificuldades."}],"order":[{"t":["Supposing","the","venue","closes,","what","then?"],"h":"Supondo que o local feche, e então?"},{"t":["Provided","we","receive","approval,","we","can","proceed."],"h":"Desde que recebamos aprovação, podemos continuar."},{"t":["Confirm","the","booking","or","else","we'll","lose","it."],"h":"Confirme a reserva, senão vamos perdê-la."}],"dict":[{"t":"But for the additional financial support, we would have had to cancel several important activities."},{"t":"Supposing the supplier refuses to negotiate, what alternative arrangements could we realistically make?"},{"t":"The organization will approve the proposal provided that all safety requirements are met."},{"t":"We need to finalize the agreement before Friday; otherwise, we risk losing the remaining funding."},{"t":"If it weren't for the dedication of our volunteers, organizing an event of this scale would be impossible."}],"shadow":["That's a substantial cut. But for the additional funding we secured last month, we'd probably have to cancel part of the conference altogether.","Good. Supposing we manage to negotiate a better catering deal, would that leave enough money to cover the speakers' travel expenses?","Possibly, although we'd still be cutting it close. We'd need to confirm the revised costs by Wednesday; otherwise, we risk missing the payment deadline.","Agreed. The situation isn't ideal, but it isn't hopeless either. Provided everyone follows through on their commitments, we should be able to make it work."],"write":{"task":"Escreva 100 a 130 palavras sobre um projeto com orçamento apertado, explorando hipóteses, três requisitos e duas consequências.","ph":"But for …, we would … Supposing …, we could … Provided that … Otherwise …"},"cards":[["Se não fosse pelo apoio deles, teríamos fracassado.","But for their support, we would have failed."],["Supondo que o cliente recuse, qual é o plano B?","Supposing the client refuses, what's our backup plan?"],["Podemos continuar desde que o orçamento seja aprovado.","We can proceed provided that the budget is approved."],["Você pode participar contanto que se inscreva antes.","You can participate as long as you register in advance."],["Precisamos agir agora; caso contrário, perderemos a chance.","We need to act now; otherwise, we'll miss the opportunity."],["Confirme os detalhes, senão teremos problemas.","Confirm the details, or else we'll run into problems."],["Se não fosse pela ajuda dela, eu estaria perdido.","If it weren't for her help, I'd be lost."],["Supondo que você pudesse escolher, o que faria?","Supposing you could choose, what would you do?"],["O acordo vale desde que as partes concordem.","The agreement is valid provided that both parties agree."],["Se não fosse pelo atraso, teríamos chegado cedo.","But for the delay, we would have arrived early."]]},{"title":"All Things Considered","goal":"Usar orações reduzidas de particípio e construções absolutas para apresentar causas, ações anteriores e circunstâncias sem ambiguidade.","speakers":{"Emma":"f","Lucas":"m"},"setting":"Emma e Lucas organizam um festival de cinema ao ar livre que enfrenta dificuldades com autorizações e clima.","lines":[["Emma","Having reviewed the updated schedule, I'm reasonably confident we can still open the festival on Saturday. A few details remain unresolved, though.","Depois de revisar o cronograma atualizado, estou confiante de que ainda podemos abrir o festival no sábado, embora restem detalhes pendentes."],["Lucas","That's encouraging. Having been told that the permits were already approved, I assumed we wouldn't have to deal with any further administrative problems.","É animador. Como me disseram que as autorizações estavam aprovadas, achei que não enfrentaríamos mais problemas administrativos."],["Emma","Unfortunately, the situation changed yesterday. The city requested an additional safety inspection, leaving us with barely enough time to make the necessary arrangements.","Infelizmente, a situação mudou ontem. A prefeitura pediu outra inspeção de segurança, deixando pouco tempo para os preparativos."],["Lucas","Not knowing about that requirement, I'd already confirmed the equipment delivery. Should we postpone it until the inspection has been completed?","Sem saber dessa exigência, já tinha confirmado a entrega do equipamento. Devemos adiá-la até o fim da inspeção?"],["Emma","I wouldn't postpone anything just yet. The inspection scheduled for tomorrow, we should still have time to address any minor concerns before the opening.","Eu não adiaria nada ainda. Com a inspeção marcada para amanhã, devemos ter tempo de resolver pequenas questões antes da abertura."],["Lucas","Fair enough. Weather permitting, the outdoor screenings will go ahead as planned. But have you considered what happens if it rains heavily?","Justo. Se o tempo permitir, as sessões ao ar livre ocorrerão como planejado. E se chover muito?"],["Emma","Yes. Having anticipated that possibility, we've arranged access to the community theater, which can accommodate roughly two hundred people.","Sim. Como previmos essa possibilidade, conseguimos acesso ao teatro comunitário, que comporta cerca de duzentas pessoas."],["Lucas","That's a relief. With the indoor venue secured, we won't have to cancel the entire program, although seating capacity could become an issue.","Que alívio. Com o espaço interno garantido, não precisaremos cancelar tudo, embora a capacidade de público possa ser um problema."],["Emma","Exactly. Taking the limited seating into account, we should prioritize people who registered in advance and explain the situation transparently.","Exatamente. Levando em conta os assentos limitados, devemos priorizar os inscritos e explicar a situação com transparência."],["Lucas","Having worked on public events, I've learned that people are understanding when organizers communicate early and offer alternatives.","Como já trabalhei em vários eventos públicos, aprendi que as pessoas geralmente entendem quando recebem avisos cedo e alternativas razoáveis."],["Emma","I agree. One concern is the accessibility of the theater. Designed decades ago, the building doesn't fully meet modern accessibility standards.","Concordo. Preocupa-me a acessibilidade do teatro. Construído há décadas, o prédio não atende totalmente às normas atuais."],["Lucas","That's important. We should verify which entrances are accessible rather than make assumptions. Being aware of a limitation isn't the same as addressing it.","Isso importa. Devemos verificar quais entradas são acessíveis em vez de presumir. Conhecer uma limitação não equivale a resolvê-la."],["Emma","Agreed. With several volunteers already assigned to visitor assistance, we have some support available, but the physical access itself must be confirmed.","Concordo. Com voluntários designados para ajudar, temos apoio, mas o acesso físico precisa ser confirmado."],["Lucas","The deadline approaching, let's decide tomorrow afternoon. Waiting until Saturday would cause confusion.","Com o prazo se aproximando, acho melhor decidir amanhã à tarde. Esperar até sábado causaria confusão desnecessária."],["Emma","All things considered, we're in a better position than we were earlier this week. The contingency plan isn't perfect, but it's becoming much more realistic.","Considerando tudo, estamos melhor do que no começo da semana. O plano de contingência não é perfeito, mas está mais viável."],["Lucas","I agree. Having dealt with unexpected setbacks before, we're better prepared to distinguish between problems that require immediate action and those that can wait.","Concordo. Como já enfrentamos contratempos, sabemos distinguir melhor os problemas urgentes dos que podem esperar."],["Emma","Then let's confirm the inspection, contact the theater, and update the volunteers. With those arrangements completed, we can concentrate on the actual experience.","Então vamos confirmar a inspeção, falar com o teatro e avisar os voluntários. Com isso resolvido, focaremos na experiência do público."],["Lucas","Sounds good. All things considered, a successful festival isn't one without difficulties. It's one where the organizers anticipate problems and respond responsibly.","Parece ótimo. Considerando tudo, um festival bem-sucedido não é aquele sem dificuldades, mas aquele em que os organizadores as antecipam e reagem bem."]],"grammar":[{"h":"Participle clauses com -ing","p":["Orações reduzidas com -ing podem indicar causa ou circunstância.","O sujeito implícito normalmente é o mesmo da oração principal; erros de associação provocam ambiguidade."],"ex":[["Not realizing the seriousness, I underestimated the risk.","Sem perceber a gravidade, subestimei o risco."],["Working under pressure, the team met the deadline.","Trabalhando sob pressão, a equipe cumpriu o prazo."],["Recognizing the concern, the organization published an explanation.","Reconhecendo a preocupação, a organização publicou uma explicação."]],"tip":"Confira quem executa o verbo reduzido."},{"h":"Having done e Having been told","p":["Having + particípio destaca uma ação concluída antes de outra.","Having been + particípio apresenta ação anterior passiva."],"ex":[["Having completed the assessment, the researchers submitted a report.","Depois de concluir a avaliação, os pesquisadores apresentaram um relatório."],["Having been warned about delays, we revised the schedule.","Como tínhamos sido alertados sobre atrasos, revisamos o cronograma."],["Having considered several alternatives, we chose the safer one.","Depois de considerar alternativas, escolhemos a mais segura."]],"tip":"Having done é ativo; having been told é passivo."},{"h":"Construções absolutas","p":["Uma construção absoluta apresenta seu próprio sujeito e uma circunstância independente.","Weather permitting é uma expressão fixa que equivale a if the weather permits."],"ex":[["Weather permitting, the exhibition will remain outdoors.","Se o tempo permitir, a exposição ficará ao ar livre."],["The deadline approaching, the team intensified preparations.","Com o prazo se aproximando, a equipe intensificou os preparativos."],["The documents approved, the project could move forward.","Com os documentos aprovados, o projeto pôde avançar."]],"tip":"A estrutura absoluta não precisa compartilhar o sujeito da oração principal."},{"h":"All things considered e with","p":["All things considered introduz uma avaliação final equilibrada.","With + substantivo + particípio apresenta uma circunstância concluída ou em andamento."],"ex":[["All things considered, the benefits outweigh the risks.","Considerando tudo, os benefícios superam os riscos."],["With the permissions secured, the organization can begin.","Com as autorizações garantidas, a organização pode começar."],["With operating costs increasing, we must reconsider the budget.","Com os custos aumentando, devemos rever o orçamento."]],"tip":"Use essas estruturas quando melhorarem a clareza, não apenas para parecer formal."}],"vocab":[{"h":"Eventos e planejamento","items":[["updated schedule","cronograma atualizado"],["safety inspection","inspeção de segurança"],["administrative requirement","exigência administrativa"],["equipment delivery","entrega de equipamentos"],["outdoor screening","sessão ao ar livre"],["community theater","teatro comunitário"],["contingency plan","plano de contingência"],["seating capacity","capacidade de assentos"]]},{"h":"Circunstâncias e decisões","items":[["having reviewed","depois de revisar"],["having been told","depois de ser informado"],["not knowing","sem saber"],["weather permitting","se o tempo permitir"],["all things considered","considerando tudo"],["with the arrangements completed","com as providências concluídas"],["take into account","levar em conta"],["unexpected setback","contratempo inesperado"]]}],"pron":[{"h":"Having been","p":"Having soa aproximadamente “hé-ving”; been pode reduzir para “bin”.","w":["having reviewed","having been told","having been informed"]},{"h":"Weather permitting","p":"Weather soa “ué-dhər”; permitting tem destaque na segunda sílaba.","w":["weather permitting","weather","permitting"]},{"h":"All things considered","p":"A expressão soa aproximadamente “ól thíngz kən-sí-dərd”.","w":["all things considered","taking into account","considered"]}],"mc":[{"q":"O que a prefeitura solicitou?","o":["Novo estacionamento","Inspeção adicional","Troca dos filmes"],"a":1,"e":"Unfortunately, the situation changed yesterday. The city requested an additional safety inspection, leaving us with barely enough time to make the necessary arrangements."},{"q":"Qual é o plano para chuva?","o":["Usar teatro comunitário","Cancelar tudo","Reduzir ingressos"],"a":0,"e":"Yes. Having anticipated that possibility, we've arranged access to the community theater, which can accommodate roughly two hundred people."},{"q":"Qual limitação do teatro?","o":["Não há palco","Não possui funcionários","Acessibilidade insuficiente"],"a":2,"e":"I agree. One concern is the accessibility of the theater. Designed decades ago, the building doesn't fully meet modern accessibility standards."},{"q":"Quando decidirão?","o":["Na segunda-feira","Na sexta à tarde","Depois do evento"],"a":1,"e":"The deadline approaching, let's decide tomorrow afternoon. Waiting until Saturday would cause confusion."}],"gaps":[{"s":"___ reviewed the schedule, we approved the date.","a":["Having"],"h":"Depois de revisar o cronograma, aprovamos a data."},{"s":"Having been ___ about the delay, Sarah called the supplier.","a":["informed"],"h":"Após ser informada do atraso, Sarah ligou ao fornecedor."},{"s":"Not ___ the requirement, I confirmed delivery.","a":["knowing","realizing"],"h":"Sem conhecer a exigência, confirmei a entrega."},{"s":"Weather ___, the event will proceed.","a":["permitting"],"h":"Se o tempo permitir, o evento ocorrerá."},{"s":"All things ___, postponing would be worse.","a":["considered"],"h":"Considerando tudo, adiar seria pior."},{"s":"With the documents finally ___, we can proceed.","a":["approved"],"h":"Com os documentos aprovados, podemos continuar."}],"order":[{"t":["Having","reviewed","the","proposal,","we","approved","it."],"h":"Depois de revisar a proposta, nós a aprovamos."},{"t":["Weather","permitting,","the","event","will","proceed."],"h":"Se o tempo permitir, o evento ocorrerá."},{"t":["All","things","considered,","we","made","the","right","decision."],"h":"Considerando tudo, tomamos a decisão certa."}],"dict":[{"t":"Having reviewed the available evidence, the committee decided that additional testing would be necessary."},{"t":"Having been informed about the unexpected restrictions, we immediately revised our original plans."},{"t":"Not knowing whether the necessary permits had been approved, I contacted the city administration directly."},{"t":"Weather permitting, the outdoor activities will continue throughout the weekend without significant changes."},{"t":"All things considered, the team responded well to unexpected challenges during preparation."}],"shadow":["Having reviewed the updated schedule, I'm reasonably confident we can still open the festival on Saturday. A few details remain unresolved, though.","Not knowing about that requirement, I'd already confirmed the equipment delivery. Should we postpone it until the inspection has been completed?","Yes. Having anticipated that possibility, we've arranged access to the community theater, which can accommodate roughly two hundred people.","All things considered, we're in a better position than we were earlier this week. The contingency plan isn't perfect, but it's becoming much more realistic."],"write":{"task":"Escreva 100 a 130 palavras narrando imprevistos em um evento. Use duas orações com having, uma com not knowing e uma conclusão com all things considered.","ph":"Having reviewed …, I realized … Not knowing …, I … All things considered, …"},"cards":[["Depois de revisar os documentos, enviei a resposta.","Having reviewed the documents, I sent my response."],["Como fui informado do atraso, alterei meus planos.","Having been informed of the delay, I changed my plans."],["Sem conhecer os fatos, evitei tirar conclusões.","Not knowing all the facts, I avoided drawing conclusions."],["Se o tempo permitir, faremos a reunião ao ar livre.","Weather permitting, we'll hold the meeting outdoors."],["Considerando tudo, tivemos bons resultados.","All things considered, we achieved positive results."],["Com as autorizações garantidas, podemos começar.","With the permits secured, we can begin."],["Depois de considerar as alternativas, escolhemos a mais segura.","Having considered the alternatives, we chose the safest one."],["Com os custos aumentando, precisamos rever o orçamento.","With costs increasing, we need to review the budget."],["Sem perceber o erro, continuei a apresentação.","Not realizing my mistake, I continued the presentation."],["Com os preparativos concluídos, pudemos descansar.","The preparations completed, we could finally rest."]]},{"title":"The Implementation Of...","goal":"Usar nominalização e estilo formal em relatórios e e-mails, com implementation, introduction, decline in e failure to, preservando clareza e responsabilidade.","speakers":{"Emma":"f","Daniel":"m"},"setting":"Emma e Daniel redigem um relatório trimestral após implementar uma nova plataforma de atendimento.","lines":[["Emma","I've finished the first draft of our quarterly report. The implementation of the new support platform seems to have improved response times considerably.","Terminei o primeiro rascunho do relatório trimestral. A implementação da nova plataforma parece ter melhorado bastante os tempos de resposta."],["Daniel","That's encouraging. Have you included the decline in unresolved requests? Management specifically asked us to explain whether the improvement has been consistent.","Isso é animador. Você incluiu a queda nas solicitações não resolvidas? A direção pediu especificamente que explicássemos se a melhora foi consistente."],["Emma","Yes. There's been a twenty percent reduction in the number of requests remaining open after forty-eight hours, compared with the previous quarter.","Sim. Houve redução de vinte por cento nas solicitações abertas após quarenta e oito horas, em comparação ao trimestre anterior."],["Daniel","Good. Instead of writing that we reduced outstanding requests, we could say the reduction in outstanding requests reflects improvements in workflow efficiency.","Ótimo. Em vez de dizer que reduzimos as solicitações pendentes, podemos dizer que a redução delas reflete melhorias no fluxo de trabalho."],["Emma","That sounds more appropriate for a report. However, I'm concerned that we're making the findings sound more definitive than the available evidence justifies.","Isso parece adequado ao relatório. Mas receio que estejamos tratando as conclusões como mais definitivas do que as evidências permitem."],["Daniel","Fair point. The introduction of automated responses may have contributed to the improvement, but we shouldn't describe it as the sole cause.","Justo. A introdução de respostas automatizadas pode ter ajudado, mas não devemos descrevê-la como única causa."],["Emma","Exactly. We also reorganized the support team and revised several procedures. The evaluation of those changes should be included before drawing conclusions.","Exatamente. Também reorganizamos a equipe e revisamos procedimentos. A avaliação dessas mudanças deve fazer parte das conclusões."],["Daniel","Agreed. There's also a less encouraging finding: the failure to provide adequate training initially led to confusion among some newer employees.","Concordo. Há também um dado menos positivo: a falta de treinamento adequado no começo confundiu alguns funcionários novos."],["Emma","I've addressed that in the challenges section. The delay in delivering training materials affected the first two weeks of the transition.","Abordei isso na seção de desafios. O atraso dos materiais de treinamento afetou as primeiras duas semanas da transição."],["Daniel","We should be transparent about it. Acknowledging an initial difficulty doesn't weaken a report when corrective measures have been taken.","Devemos ser transparentes. Reconhecer uma dificuldade inicial não enfraquece necessariamente o relatório, sobretudo quando já tomamos medidas corretivas."],["Emma","Agreed. I've also written a paragraph about the improvement in customer satisfaction following the introduction of a clearer complaint-handling procedure.","Concordo. Também escrevi sobre a melhora na satisfação dos clientes após um procedimento mais claro para reclamações."],["Daniel","That works, but the sentence is getting rather dense. Sometimes saying we introduced a clearer procedure is easier to understand than describing its introduction.","Funciona, mas a frase está ficando pesada. Às vezes, dizer que introduzimos um procedimento é mais claro do que descrever sua introdução."],["Emma","You're right. I suppose formal writing isn't about turning every verb into a noun. It's about choosing structures that make the information precise and accessible.","Você tem razão. Escrita formal não é transformar todos os verbos em substantivos, e sim escolher estruturas precisas e compreensíveis."],["Daniel","Exactly. The expansion of the customer support team is worth mentioning, but we should also state clearly who approved it and when.","Exatamente. A ampliação da equipe merece menção, mas devemos indicar quem a aprovou e quando."],["Emma","I'll add that detail. What about the recommendation section? I was thinking of proposing the development of a more comprehensive training program.","Vou acrescentar. E quanto às recomendações? Eu pensava em propor o desenvolvimento de um treinamento mais abrangente."],["Daniel","That's reasonable. I'd also recommend a regular review of response times and the establishment of clear performance indicators for each department.","É razoável. Eu também recomendaria revisões periódicas dos tempos de resposta e indicadores claros de desempenho por departamento."],["Emma","Good idea. I'll revise the report this afternoon and send you the final version for approval before sharing it with senior management.","Boa ideia. Revisarei o relatório hoje à tarde e enviarei a versão final para sua aprovação antes de compartilhar com a direção."],["Daniel","Perfect. The report should demonstrate measurable progress, acknowledge the remaining weaknesses, and explain the actions required for further improvement.","Perfeito. O relatório deve demonstrar progresso mensurável, reconhecer fragilidades e explicar as ações necessárias para novas melhorias."]],"grammar":[{"h":"Nominalização: ações como substantivos","p":["Nominalização transforma ações em conceitos: implement → implementation, improve → improvement.","É comum em relatórios por permitir foco nos processos, mas o excesso pode esconder quem agiu."],"ex":[["The implementation of the strategy resulted in improvements.","A implementação da estratégia resultou em melhorias."],["The introduction of new procedures increased efficiency.","A introdução de novos procedimentos aumentou a eficiência."],["The development of a training program remains a priority.","O desenvolvimento de um programa de treinamento continua prioridade."]],"tip":"Compare We implemented the system e The implementation of the system."},{"h":"Decline in e reduction in","p":["Para identificar o indicador que mudou, use in: a decline in costs, an improvement in performance.","Use of para a magnitude: a reduction of twenty percent."],"ex":[["The company reported a decline in customer complaints.","A empresa registrou queda nas reclamações."],["There was a fifteen percent increase in registrations.","Houve aumento de quinze por cento nos cadastros."],["We observed a reduction of twenty percent in processing errors.","Observamos redução de vinte por cento nos erros de processamento."]],"tip":"A reduction in costs identifica o indicador; of twenty percent, a magnitude."},{"h":"The failure to e the decision to","p":["Substantivos como failure, decision, attempt e ability podem vir com to + infinitivo.","Essas estruturas descrevem omissões, decisões ou capacidades, mas precisam de agentes claros quando a responsabilidade importa."],"ex":[["The failure to communicate the change caused confusion.","A falha em comunicar a mudança causou confusão."],["The decision to postpone the launch was approved.","A decisão de adiar o lançamento foi aprovada."],["The attempt to simplify registration produced mixed results.","A tentativa de simplificar o cadastro produziu resultados variados."]],"tip":"Depois de failure, decision e attempt, use to + infinitivo."},{"h":"Estilo formal versus estilo direto","p":["O estilo nominal destaca processos e resultados; o verbal destaca ações e responsáveis.","Em e-mails de tarefas, verbos diretos muitas vezes são melhores que nominalizações longas."],"ex":[["The completion of the review is required before approval.","A conclusão da revisão é exigida antes da aprovação."],["We must complete the review before approving the proposal.","Precisamos concluir a revisão antes de aprovar a proposta."],["Additional controls helped reduce operational risks.","Controles adicionais ajudaram a reduzir riscos operacionais."]],"tip":"Formalidade não exige frases compridas: clareza e precisão são prioritárias."}],"vocab":[{"h":"Nominalizações formais","items":[["implementation","implementação"],["introduction","introdução"],["evaluation","avaliação"],["development","desenvolvimento"],["establishment","estabelecimento"],["expansion","ampliação"],["approval","aprovação"],["acknowledgment","reconhecimento"],["assessment","avaliação"]]},{"h":"Resultados e relatórios","items":[["decline in","queda em"],["increase in","aumento de"],["reduction in","redução de"],["improvement in","melhora em"],["response time","tempo de resposta"],["performance indicator","indicador de desempenho"],["quarterly report","relatório trimestral"],["corrective measures","medidas corretivas"],["senior management","alta direção"]]}],"pron":[{"h":"Implementation","p":"Implementation apresenta destaque em men: “im-plə-men-têi-shən”.","w":["implementation","the implementation of","introduction"]},{"h":"Evaluation","p":"Evaluation tem destaque na penúltima parte; development, na segunda sílaba.","w":["evaluation","development","performance evaluation"]},{"h":"Reduction","p":"Reduction soa aproximadamente “ri-dâk-shən”; decline termina com som de ai.","w":["reduction","decline","a reduction in costs"]}],"mc":[{"q":"Qual indicador melhorou?","o":["O valor das vendas","Tempo de resposta","Número de lojas"],"a":1,"e":"I've finished the first draft of our quarterly report. The implementation of the new support platform seems to have improved response times considerably."},{"q":"Qual redução foi observada?","o":["Vinte por cento de solicitações pendentes","Metade dos funcionários","Trinta por cento no faturamento"],"a":0,"e":"Yes. There's been a twenty percent reduction in the number of requests remaining open after forty-eight hours, compared with the previous quarter."},{"q":"Qual problema surgiu?","o":["Falta de clientes","Falta de documentos fiscais","Treinamento inicial insuficiente"],"a":2,"e":"Agreed. There's also a less encouraging finding: the failure to provide adequate training initially led to confusion among some newer employees."},{"q":"O que é prioritário na escrita formal?","o":["Usar apenas substantivos","Precisão e clareza","Evitar todas as pessoas"],"a":1,"e":"You're right. I suppose formal writing isn't about turning every verb into a noun. It's about choosing structures that make the information precise and accessible."}],"gaps":[{"s":"The ___ of the system required planning.","a":["implementation"],"h":"A implementação do sistema exigiu planejamento."},{"s":"There was a decline ___ customer complaints.","a":["in"],"h":"Houve uma queda nas reclamações."},{"s":"The failure ___ provide training caused confusion.","a":["to"],"h":"A falta de treinamento causou confusão."},{"s":"The ___ of new procedures improved efficiency.","a":["introduction"],"h":"A introdução de novos procedimentos melhorou a eficiência."},{"s":"There was a significant ___ in errors.","a":["reduction"],"h":"Houve uma redução significativa nos erros."},{"s":"The ___ to postpone the launch was approved.","a":["decision"],"h":"A decisão de adiar o lançamento foi aprovada."}],"order":[{"t":["The","implementation","of","the","system","improved","efficiency."],"h":"A implementação do sistema melhorou a eficiência."},{"t":["We","observed","a","decline","in","customer","complaints."],"h":"Observamos queda nas reclamações."},{"t":["The","failure","to","communicate","caused","unnecessary","confusion."],"h":"A falha na comunicação causou confusão desnecessária."}],"dict":[{"t":"The implementation of the platform resulted in a measurable improvement in response times."},{"t":"The company reported a substantial decline in customer complaints following the introduction of revised procedures."},{"t":"The failure to provide adequate training initially contributed to several avoidable operational difficulties."},{"t":"The evaluation of employee performance identified opportunities for further improvement and professional development."},{"t":"The report recommends clear performance indicators and regular reviews of operational results."}],"shadow":["I've finished the first draft of our quarterly report. The implementation of the new support platform seems to have improved response times considerably.","Fair point. The introduction of automated responses may have contributed to the improvement, but we shouldn't describe it as the sole cause.","Agreed. There's also a less encouraging finding: the failure to provide adequate training initially led to confusion among some newer employees.","You're right. I suppose formal writing isn't about turning every verb into a noun. It's about choosing structures that make the information precise and accessible."],"write":{"task":"Elabore um relatório de 120 a 150 palavras sobre a implantação de um processo. Apresente resultados, uma falha e duas recomendações; equilibre nominalizações e verbos.","ph":"The implementation of … resulted in … A reduction in … However, the failure to … We recommend …"},"cards":[["A implementação do sistema melhorou a produtividade.","The implementation of the system improved productivity."],["Houve uma queda significativa na demanda.","There was a significant decline in demand."],["A introdução das novas regras provocou dúvidas.","The introduction of the new rules raised questions."],["A falha em cumprir o prazo causou atrasos adicionais.","The failure to meet the deadline caused additional delays."],["Observamos uma melhora no desempenho da equipe.","We observed an improvement in team performance."],["A avaliação dos resultados será concluída amanhã.","The evaluation of the results will be completed tomorrow."],["A decisão de ampliar o projeto foi aprovada.","The decision to expand the project was approved."],["Recomendamos o desenvolvimento de um novo programa.","We recommend the development of a new program."],["O relatório demonstra uma redução nos custos operacionais.","The report demonstrates a reduction in operating costs."],["O estabelecimento de prioridades claras é essencial.","The establishment of clear priorities is essential."]]},{"title":"It's High Time","goal":"Usar subjuntivo americano formal, recomendações, urgência com it's high time, comparações com as if e preferências com would rather.","speakers":{"Sarah":"f","Lucas":"m"},"setting":"Sarah e Lucas analisam uma pesquisa interna sobre divisão de tarefas e comunicação na empresa.","lines":[["Sarah","I've finished reviewing the employee survey, and some of the findings are more concerning than I expected. We need to address them before morale deteriorates further.","Terminei a pesquisa com os funcionários. Alguns resultados preocupam mais do que eu esperava. Precisamos agir antes que o ânimo piore."],["Lucas","I agree. It's high time we reconsidered how responsibilities are distributed. Several employees feel they're constantly picking up other people's work.","Concordo. Já passou da hora de rever a distribuição das responsabilidades. Vários funcionários sentem que assumem o trabalho de outros."],["Sarah","Exactly. One employee mentioned that the project coordinator behaves as if he were personally responsible for every decision, regardless of its importance.","Exatamente. Um funcionário comentou que o coordenador age como se fosse responsável por todas as decisões, independentemente da importância."],["Lucas","That sounds exhausting for everyone involved. I suggest that he be given additional management training before we consider more drastic measures.","Isso parece desgastante. Sugiro que ele receba treinamento de gestão antes de considerarmos medidas mais drásticas."],["Sarah","That's reasonable, but it's essential that his supervisor understand the seriousness of the situation. We can't keep treating these complaints as isolated incidents.","É razoável, mas é essencial que o supervisor entenda a gravidade da situação. Não podemos tratar essas reclamações como casos isolados."],["Lucas","Absolutely. I'd rather we addressed the underlying problem now than waited until experienced employees started leaving the company.","Com certeza. Eu preferiria enfrentar o problema agora a esperar até funcionários experientes começarem a sair."],["Sarah","There's another issue. Some managers speak as if employees had unlimited time to complete additional tasks, which creates unrealistic expectations.","Há outra questão. Alguns gestores falam como se funcionários tivessem tempo ilimitado para tarefas extras, criando expectativas irreais."],["Lucas","I noticed that too. It's important that every department establish clear priorities and communicate them consistently, especially during particularly demanding periods.","Também percebi. É importante que cada departamento estabeleça prioridades claras e as comunique sempre, sobretudo em períodos exigentes."],["Sarah","Do you think the directors will support those recommendations? They've been reluctant to change the existing structure, even when presented with evidence.","Acha que os diretores apoiarão as recomendações? Têm resistido a mudar a estrutura, mesmo diante de evidências."],["Lucas","Possibly. I'd rather they took the feedback seriously, but we should prepare a convincing argument instead of assuming they'll immediately agree.","Talvez. Eu preferiria que levassem os comentários a sério, mas precisamos de bons argumentos, sem presumir concordância imediata."],["Sarah","Fair enough. I also wish we'd introduced regular feedback sessions earlier. We might have identified these concerns before they became so widespread.","Justo. Também gostaria que tivéssemos criado reuniões de feedback antes. Talvez identificássemos essas preocupações antes de se generalizarem."],["Lucas","True, but we can't change the past. What matters is that we respond constructively. I recommend that each team hold a monthly meeting dedicated to workload concerns.","Verdade, mas não mudamos o passado. O importante é responder bem. Recomendo reuniões mensais sobre carga de trabalho em cada equipe."],["Sarah","I'd support that, provided those meetings actually lead to decisions. I'd rather managers didn't turn them into another administrative formality.","Eu apoiaria isso se as reuniões levassem a decisões. Preferiria que os gestores não as tornassem mais uma formalidade."],["Lucas","Agreed. It's crucial that employees feel comfortable raising concerns without worrying about negative consequences for their professional development.","Concordo. É fundamental que os funcionários se sintam à vontade para falar sem receio de consequências para sua carreira."],["Sarah","Exactly. Some employees describe the workplace as though asking for support were a sign of weakness. That's a culture we urgently need to change.","Exatamente. Alguns descrevem o ambiente como se pedir ajuda fosse sinal de fraqueza. Precisamos mudar essa cultura."],["Lucas","Then perhaps we should recommend that the directors participate in the first feedback sessions. Their involvement could demonstrate genuine commitment.","Talvez devamos recomendar que os diretores participem das primeiras reuniões. Isso demonstraria comprometimento verdadeiro."],["Sarah","That's a sensible proposal. I'll prepare the recommendations, but I'd rather you reviewed the final document before we present it on Thursday.","É uma proposta sensata. Prepararei as recomendações, mas preferiria que você revisasse o documento antes da apresentação de quinta."],["Lucas","Of course. It's high time we turned employee feedback into meaningful action. If we approach this carefully, we might actually improve the way people work together.","Claro. Já passou da hora de transformar os comentários em ações concretas. Com cuidado, podemos melhorar a colaboração."]],"grammar":[{"h":"I suggest that he be: subjuntivo formal","p":["No inglês americano, suggest, recommend, insist e request podem exigir a forma base do verbo após that.","Isso vale também para he, she e it; na negativa, use not antes da forma base."],"ex":[["I recommend that she attend the training session.","Recomendo que ela participe do treinamento."],["The committee suggested that the proposal be reviewed.","O comitê sugeriu que a proposta fosse revisada."],["The director insisted that the report not be released.","O diretor insistiu que o relatório não fosse divulgado."]],"tip":"No subjuntivo, use he be, não he is, para uma recomendação formal."},{"h":"It's essential that","p":["Adjetivos como essential, vital, important e crucial podem introduzir subjuntivo formal para necessidades e exigências.","Também podemos usar It is important for someone to do something."],"ex":[["It's essential that every participant understand the instructions.","É essencial que todos compreendam as instruções."],["It's crucial that the information remain confidential.","É fundamental que a informação permaneça confidencial."],["It's important for managers to give constructive feedback.","É importante que gestores ofereçam comentários construtivos."]],"tip":"She understand é subjuntivo; she understands pode ter leitura factual."},{"h":"It's high time","p":["It's high time + sujeito + passado simples expressa que uma ação já deveria ter acontecido.","O passado cria distância e urgência, não indica necessariamente evento já concluído."],"ex":[["It's high time the company updated its policies.","Já passou da hora de a empresa atualizar as políticas."],["It's about time we acknowledged the problem.","Já estava na hora de reconhecermos o problema."],["It's high time you took your development seriously.","Já passou da hora de levar seu desenvolvimento a sério."]],"tip":"Não use o presente simples após it's high time quando há sujeito e verbo."},{"h":"As if e would rather","p":["As if/as though com passado expressa comparação hipotética.","Would rather + outra pessoa + passado indica preferência presente ou futura; + past perfect indica preferência sobre o passado."],"ex":[["He acts as if he were the director.","Ele age como se fosse o diretor."],["I'd rather you discussed the issue with me.","Eu preferiria que você discutisse a questão comigo."],["I'd rather they hadn't announced the changes yesterday.","Eu preferiria que não tivessem anunciado as mudanças ontem."]],"tip":"I'd rather you told me now contrasta com I'd rather you had told me yesterday."}],"vocab":[{"h":"Ambiente de trabalho","items":[["employee survey","pesquisa com funcionários"],["employee morale","motivação dos funcionários"],["workload distribution","distribuição de tarefas"],["underlying problem","problema fundamental"],["management training","treinamento em gestão"],["unrealistic expectations","expectativas irreais"],["constructive feedback","feedback construtivo"],["professional development","desenvolvimento profissional"]]},{"h":"Recomendação e urgência","items":[["I suggest that","sugiro que"],["I recommend that","recomendo que"],["It's essential that","é essencial que"],["It's crucial that","é fundamental que"],["It's high time","já passou da hora"],["I'd rather","eu preferiria"],["as if","como se"],["as though","como se"],["raise concerns","apresentar preocupações"]]}],"pron":[{"h":"It's high time","p":"High e time recebem destaque: “its hái táim”.","w":["It's high time","It's about time","It's time we talked"]},{"h":"I'd rather","p":"I'd equivale a I would; a sequência soa “áid rédher”.","w":["I'd rather","I'd rather you stayed","I'd rather they didn't"]},{"h":"Essential e suggest","p":"Essential soa “i-sén-shəl”; suggest recebe destaque final.","w":["essential","suggest","It's essential that"]}],"mc":[{"q":"Qual problema surgiu na pesquisa?","o":["Falta de computadores","Distribuição de tarefas","Ausência de férias"],"a":1,"e":"I agree. It's high time we reconsidered how responsibilities are distributed. Several employees feel they're constantly picking up other people's work."},{"q":"O que Lucas sugere ao coordenador?","o":["Treinamento de gestão","Demissão imediata","Trabalho remoto obrigatório"],"a":0,"e":"That sounds exhausting for everyone involved. I suggest that he be given additional management training before we consider more drastic measures."},{"q":"O que Sarah quer evitar?","o":["Reuniões práticas","Novos funcionários","Reuniões que virem formalidade"],"a":2,"e":"I'd support that, provided those meetings actually lead to decisions. I'd rather managers didn't turn them into another administrative formality."},{"q":"O que Lucas recomenda aos diretores?","o":["Ignorar críticas","Participar das primeiras reuniões","Cancelar as reuniões"],"a":1,"e":"Then perhaps we should recommend that the directors participate in the first feedback sessions. Their involvement could demonstrate genuine commitment."}],"gaps":[{"s":"I suggest that he ___ given more training.","a":["be"],"h":"Sugiro que ele receba mais treinamento."},{"s":"It is essential that she ___ the procedure.","a":["understand"],"h":"É essencial que ela compreenda o procedimento."},{"s":"It's high time we ___ our strategy.","a":["reconsidered","changed","reviewed"],"h":"Já passou da hora de reconsiderarmos a estratégia."},{"s":"She acts as if she ___ the director.","a":["were"],"h":"Ela age como se fosse diretora."},{"s":"I'd rather you ___ the issue with me.","a":["discussed"],"h":"Eu preferiria que você discutisse a questão comigo."},{"s":"I'd rather they hadn't ___ the changes.","a":["announced"],"h":"Eu preferiria que não tivessem anunciado as mudanças."}],"order":[{"t":["It's","high","time","we","made","changes."],"h":"Já passou da hora de mudar."},{"t":["I","suggest","that","he","be","informed."],"h":"Sugiro que ele seja informado."},{"t":["I'd","rather","you","stayed","a","little","longer."],"h":"Preferiria que você ficasse um pouco mais."}],"dict":[{"t":"It's high time we reconsidered how responsibilities are distributed across the different departments."},{"t":"The director recommended that every employee attend a training session before the new procedures were introduced."},{"t":"It's essential that the information remain confidential until the investigation has been completed."},{"t":"He behaves as if he were the only person capable of making important decisions."},{"t":"I'd rather the management team had discussed the proposed changes before announcing them."}],"shadow":["I agree. It's high time we reconsidered how responsibilities are distributed. Several employees feel they're constantly picking up other people's work.","That sounds exhausting for everyone involved. I suggest that he be given additional management training before we consider more drastic measures.","Absolutely. I'd rather we addressed the underlying problem now than waited until experienced employees started leaving the company.","Of course. It's high time we turned employee feedback into meaningful action. If we approach this carefully, we might actually improve the way people work together."],"write":{"task":"Escreva um e-mail de 110 a 140 palavras propondo melhorias no ambiente de trabalho. Use duas recomendações com subjuntivo, urgência e would rather.","ph":"It's high time we … I suggest that … It's essential that … I'd rather we …"},"cards":[["Já passou da hora de mudarmos a abordagem.","It's high time we changed our approach."],["Sugiro que ela receba mais treinamento.","I suggest that she receive additional training."],["É fundamental que ele esteja presente.","It's crucial that he be present."],["Prefiro que você não compartilhe essa informação.","I'd rather you didn't share that information."],["Ele fala como se soubesse de tudo.","He talks as if he knew everything."],["Recomendo que a proposta seja revisada.","I recommend that the proposal be reviewed."],["Já estava na hora de reconhecermos o problema.","It's about time we acknowledged the problem."],["É essencial que todos compreendam as regras.","It's essential that everyone understand the rules."],["Eu preferiria que você tivesse me avisado antes.","I'd rather you had warned me earlier."],["Ela agia como se fosse a responsável.","She acted as though she were in charge."]]},{"title":"By No Means","goal":"Usar do/did enfático, fronting, so/such...that, by no means, not in the least e the very para enfatizar e corrigir interpretações.","speakers":{"Emma":"f","Daniel":"m"},"setting":"Emma e Daniel preparam uma resposta pública a críticas sobre um lançamento digital.","lines":[["Emma","Have you read the article about our launch? It makes the entire project sound like a disaster, even though most of the technical problems have already been resolved.","Você leu a reportagem do lançamento? Ela faz o projeto inteiro parecer um desastre, embora a maioria dos problemas técnicos já tenha sido resolvida."],["Daniel","I have, and I do understand why customers were frustrated. The initial delays were unacceptable, but the article leaves out some important context.","Li, e realmente entendo a frustração dos clientes. Os atrasos iniciais eram inaceitáveis, mas a reportagem omite contexto importante."],["Emma","Exactly. The delays, I can explain. What I can't accept is the suggestion that we deliberately ignored complaints from customers who needed assistance.","Exatamente. Os atrasos posso explicar. O que não aceito é sugerirem que ignoramos deliberadamente clientes que precisavam de ajuda."],["Daniel","And by no means should we dismiss those complaints simply because the situation has improved. We need to acknowledge what actually happened.","De maneira alguma devemos desconsiderar reclamações só porque a situação melhorou. Precisamos reconhecer o que aconteceu."],["Emma","Agreed. I did send the journalist a detailed explanation last Friday, but apparently the final article didn't include most of it.","Concordo. Eu realmente enviei uma explicação detalhada ao jornalista na sexta, mas a reportagem omitiu quase tudo."],["Daniel","That's disappointing. So misleading was the headline that several readers assumed the service had been permanently discontinued.","É decepcionante. A manchete foi tão enganosa que leitores acharam que o serviço tinha sido encerrado definitivamente."],["Emma","And such was the confusion that our support team received hundreds of questions about problems that had already been fixed.","E a confusão foi tamanha que o suporte recebeu centenas de perguntas sobre problemas já resolvidos."],["Daniel","We should clarify the timeline. The very first day was particularly difficult, but response times improved substantially once the updated system went live.","Devemos esclarecer a sequência. O primeiro dia foi difícil, mas os tempos de resposta melhoraram quando o sistema atualizado entrou no ar."],["Emma","I agree, although I'm not suggesting everything is perfect now. By no means is the service free of problems, and we still have work to do.","Concordo, mas não digo que tudo esteja perfeito. O serviço está longe de ser livre de problemas, e ainda temos trabalho."],["Daniel","Of course. Do you think customers would object if we published a clear explanation of the changes we've made since the launch?","Claro. Acha que os clientes se oporiam a uma explicação clara das mudanças feitas desde o lançamento?"],["Emma","Not in the least. In fact, several customers specifically asked for a more transparent account of what went wrong and how we addressed it.","De forma alguma. Vários clientes pediram uma explicação mais transparente do que deu errado e do que fizemos."],["Daniel","Then we should avoid defensive language. I do believe we can acknowledge our mistakes without undermining confidence in the entire service.","Então devemos evitar linguagem defensiva. Realmente acredito que podemos reconhecer erros sem prejudicar a confiança no serviço."],["Emma","Exactly. The technical progress, we can demonstrate with actual figures. The long-term reliability of the system, however, still needs to be established.","Exatamente. Podemos demonstrar o avanço técnico com números. A confiabilidade a longo prazo, porém, ainda precisa ser comprovada."],["Daniel","That's the very distinction our presentation needs to emphasize. Improvements are measurable, but they shouldn't be confused with proof that future failures are impossible.","Essa é justamente a distinção a destacar. As melhorias são mensuráveis, mas não provam que falhas futuras sejam impossíveis."],["Emma","Some colleagues think we should respond more aggressively. I'm not convinced. Such an approach could make us look unwilling to accept legitimate criticism.","Alguns colegas querem uma resposta mais agressiva. Não concordo; isso pode parecer falta de abertura a críticas legítimas."],["Daniel","I couldn't agree more. We do need to defend the facts, but that doesn't mean attacking everyone who questions our decisions.","Concordo plenamente. Realmente precisamos defender os fatos, mas sem atacar quem questiona as decisões."],["Emma","Let's build the presentation around three points: what happened, what we've changed, and what remains unresolved. Nothing more dramatic than that.","Vamos estruturar a apresentação no que aconteceu, no que mudou e no que resta resolver. Nada mais dramático."],["Daniel","Perfect. By no means should we pretend the launch was flawless. What we can show is that the team responded seriously and made meaningful improvements.","Perfeito. De maneira alguma devemos fingir que o lançamento foi impecável. Podemos mostrar que a equipe reagiu com seriedade e melhorou."]],"grammar":[{"h":"Do/did enfático","p":["Em afirmações do presente e passado simples, do/does/did pode reforçar sinceridade ou contrariar uma suposição.","Depois do auxiliar, o verbo fica na forma base."],"ex":[["I do appreciate your feedback, even though I disagree.","Realmente valorizo seus comentários, embora discorde."],["She does understand the implications of the decision.","Ela realmente entende as consequências da decisão."],["We did notify the supplier before the deadline.","Nós realmente avisamos o fornecedor antes do prazo."]],"tip":"Na fala, o auxiliar enfático recebe destaque."},{"h":"Fronting: informação em destaque","p":["Deslocar um objeto para o início cria ênfase e contraste.","Esse fronting não exige automaticamente inversão entre sujeito e auxiliar."],"ex":[["That explanation, I can accept.","Essa explicação, eu consigo aceitar."],["The original proposal, I can support.","A proposta original, eu posso apoiar."],["The financial implications, we understand.","As implicações financeiras, nós entendemos."]],"tip":"Mantenha a ordem sujeito-verbo após o objeto deslocado."},{"h":"So... that e such... that","p":["So intensifica adjetivos e advérbios; such intensifica grupos nominais.","Quando so ou such aparecem no início de uma estrutura enfática formal, ocorre inversão."],"ex":[["The instructions were so confusing that people left.","As instruções eram tão confusas que pessoas desistiram."],["So serious was the disruption that operations stopped.","A interrupção foi tão grave que as operações pararam."],["Such was the demand that additional staff were hired.","A procura foi tamanha que contrataram funcionários."]],"tip":"So + adjetivo; such + substantivo."},{"h":"By no means, not in the least e the very","p":["By no means introduz negativa forte e exige inversão quando começa a oração.","Not in the least significa nem um pouco; the very destaca identidade ou precisão."],"ex":[["By no means should the findings be treated as proof.","De maneira alguma os resultados devem ser tratados como prova."],["Would you mind? Not in the least.","Você se importaria? Nem um pouco."],["That's the very issue we must address.","Essa é justamente a questão que precisamos resolver."]],"tip":"The very reason significa justamente o motivo, não um motivo muito grande."}],"vocab":[{"h":"Ênfase e contraste","items":[["by no means","de maneira alguma"],["not in the least","nem um pouco"],["the very reason","justamente o motivo"],["the very first day","logo no primeiro dia"],["so... that","tão... que"],["such... that","tamanho... que"],["I do believe","eu realmente acredito"],["I did mention","eu realmente mencionei"]]},{"h":"Comunicação pública","items":[["misleading headline","manchete enganosa"],["important context","contexto importante"],["legitimate criticism","crítica legítima"],["defensive language","linguagem defensiva"],["long-term reliability","confiabilidade de longo prazo"],["undermine confidence","prejudicar a confiança"],["acknowledge a mistake","reconhecer um erro"],["clarify the timeline","esclarecer a sequência dos fatos"]]}],"pron":[{"h":"Do/did enfático","p":"O auxiliar recebe o destaque: I DO understand.","w":["I do understand","I did send it","She does care"]},{"h":"By no means","p":"Aproximadamente “bái nôu míinz”.","w":["by no means","By no means should we","by no means simple"]},{"h":"Not in the least","p":"A sequência é conectada, aproximadamente “nát-in dhə líist”.","w":["not in the least","the very reason","the very first day"]}],"mc":[{"q":"Qual é o problema da reportagem?","o":["Omissão de contexto e tom excessivamente negativo","Divulgação antecipada","Documentos confidenciais"],"a":0,"e":"Have you read the article about our launch? It makes the entire project sound like a disaster, even though most of the technical problems have already been resolved."},{"q":"O que leitores entenderam da manchete?","o":["Serviço ampliado","Serviço encerrado","Serviço gratuito"],"a":1,"e":"That's disappointing. So misleading was the headline that several readers assumed the service had been permanently discontinued."},{"q":"Qual postura Daniel defende?","o":["Atacar críticos","Ignorar reclamações","Defender fatos e reconhecer erros"],"a":2,"e":"I couldn't agree more. We do need to defend the facts, but that doesn't mean attacking everyone who questions our decisions."},{"q":"Quais pontos da apresentação?","o":["Acontecimento, mudanças e pendências","Vendas, propaganda e custos","Apenas lucros"],"a":0,"e":"Let's build the presentation around three points: what happened, what we've changed, and what remains unresolved. Nothing more dramatic than that."}],"gaps":[{"s":"I ___ appreciate your feedback.","a":["do"],"h":"Eu realmente valorizo seu comentário."},{"s":"We ___ inform the client before the deadline.","a":["did"],"h":"Nós realmente informamos o cliente antes do prazo."},{"s":"By no means ___ this be interpreted as proof.","a":["should","must","can","could","may"],"h":"De maneira alguma isso deve ser interpretado como prova."},{"s":"___ serious was the problem that operations stopped.","a":["So"],"h":"O problema foi tão grave que as operações pararam."},{"s":"___ was the confusion that hundreds called.","a":["Such"],"h":"A confusão foi tamanha que centenas ligaram."},{"s":"That's the ___ reason we changed the rules.","a":["very"],"h":"É justamente por isso que mudamos as regras."}],"order":[{"t":["I","do","understand","your","concerns."],"h":"Eu realmente compreendo suas preocupações."},{"t":["By","no","means","is","this","acceptable."],"h":"Isso não é aceitável de maneira alguma."},{"t":["Such","was","the","demand","that","supplies","ran","out."],"h":"A demanda foi tamanha que os estoques acabaram."}],"dict":[{"t":"I do appreciate your perspective, but I strongly disagree with the interpretation presented in the report."},{"t":"By no means should customers be expected to accept misleading information about the quality of a service."},{"t":"So serious were the technical difficulties that the company had to postpone the official announcement."},{"t":"Such was the confusion surrounding the decision that several departments requested immediate clarification."},{"t":"The very reason we introduced the revised procedure was to prevent similar problems from occurring again."}],"shadow":["I have, and I do understand why customers were frustrated. The initial delays were unacceptable, but the article leaves out some important context.","And by no means should we dismiss those complaints simply because the situation has improved. We need to acknowledge what actually happened.","That's disappointing. So misleading was the headline that several readers assumed the service had been permanently discontinued.","Perfect. By no means should we pretend the launch was flawless. What we can show is that the team responded seriously and made meaningful improvements."],"write":{"task":"Escreva uma resposta profissional de 110 a 140 palavras a uma crítica. Use do enfático, by no means, so/such...that e the very.","ph":"We do recognize … By no means should … The problem was so … that … The very reason …"},"cards":[["Eu realmente compreendo sua preocupação.","I do understand your concern."],["Nós realmente enviamos os documentos ontem.","We did send the documents yesterday."],["De maneira alguma devemos ignorar esses riscos.","By no means should we ignore these risks."],["Essa proposta está longe de ser perfeita.","This proposal is by no means perfect."],["O problema era tão grave que tivemos que agir.","The problem was so serious that we had to act."],["A confusão foi tamanha que a reunião foi adiada.","Such was the confusion that the meeting was postponed."],["Nem um pouco. Não me importo de esperar.","Not in the least. I don't mind waiting."],["Esse é justamente o problema que precisamos resolver.","That's the very problem we need to address."],["Essa explicação, eu consigo aceitar.","That explanation, I can accept."],["Ela realmente se importa com os resultados.","She does care about the results."]]},{"title":"A Steep Learning Curve","goal":"Usar colocações, expressões idiomáticas e phrasal verbs da vida adulta: meet a deadline, cut corners, on the same page, get up to speed e outras.","speakers":{"Emma":"f","Lucas":"m"},"setting":"Emma conta a Lucas como está sendo seu primeiro mês em um cargo de coordenação de operações.","lines":[["Lucas","So, how's the new position treating you? Last time we spoke, you were still getting familiar with the team and trying to understand how everything worked.","Então, como está o novo cargo? Da última vez, você ainda estava conhecendo a equipe e tentando entender o funcionamento."],["Emma","It's been a steep learning curve, to put it mildly. I thought my previous experience would make the transition easier, but there's a lot more to learn than I expected.","Tem sido um aprendizado intenso, para dizer o mínimo. Pensei que minha experiência facilitaria tudo, mas há mais para aprender do que eu esperava."],["Lucas","That doesn't surprise me. Did they give you enough time to learn the ropes, or were you expected to hit the ground running?","Isso não surpreende. Deram tempo para você aprender como funciona ou esperavam produtividade imediata?"],["Emma","A bit of both. My supervisor helped me get up to speed, but I was assigned a major project before I'd even figured out the reporting system.","Um pouco dos dois. Meu supervisor me ajudou a me atualizar, mas recebi um projeto importante antes de entender o sistema de relatórios."],["Lucas","Sounds intense. Are you managing to stay on top of everything, or do you already have too much on your plate?","Parece intenso. Está conseguindo manter tudo sob controle ou já tem tarefas demais?"],["Emma","Honestly, I've got a lot on my plate. We're supposed to meet a tight deadline next Friday, and two departments aren't even on the same page about the priorities.","Sinceramente, estou cheia de tarefas. Temos prazo apertado na sexta e dois departamentos nem sequer concordam quanto às prioridades."],["Lucas","That's a recipe for trouble. Have you tried bringing everyone together to iron out the misunderstandings before they turn into bigger problems?","Isso é receita para problemas. Tentou reunir todo mundo para resolver os mal-entendidos antes que piorem?"],["Emma","I have. We finally agreed on a schedule yesterday. Still, one manager suggested cutting corners on the testing process to save time.","Sim. Finalmente concordamos sobre o cronograma ontem, mas um gestor sugeriu economizar etapas dos testes."],["Lucas","That sounds risky. Meeting a deadline matters, obviously, but cutting corners on quality could come back to bite you later.","Parece arriscado. Cumprir prazo importa, mas comprometer a qualidade pode trazer problemas depois."],["Emma","Exactly what I said. I'd rather push back the deadline slightly than release something unreliable. Fortunately, the team eventually backed me up.","Foi o que eu disse. Prefiro adiar um pouco o prazo a lançar algo pouco confiável. Felizmente, a equipe me apoiou."],["Lucas","Good for you. Taking ownership of a difficult decision isn't easy when you're new, especially if senior colleagues disagree with you.","Muito bem. Assumir responsabilidade por uma decisão difícil não é fácil quando você é nova, sobretudo se colegas antigos discordam."],["Emma","True. I'm also learning that delegating is a double-edged sword. It frees up time, but you need to make sure people have the information they need.","Verdade. Delegar também é uma faca de dois gumes. Libera tempo, mas é preciso garantir informação suficiente para todos."],["Lucas","Absolutely. Keeping everyone in the loop can make a huge difference. Otherwise, people start working from different assumptions.","Com certeza. Manter todos informados faz muita diferença. Senão, as pessoas trabalham com suposições diferentes."],["Emma","That's been one of my biggest lessons. We also discovered a bottleneck in the approval process, so I'm working with the team to streamline it.","Essa foi uma das maiores lições. Descobrimos um gargalo no processo de aprovação e estamos tentando simplificá-lo."],["Lucas","Sounds like you're making progress. Just remember that you don't have to prove yourself by doing everything alone. Nobody expects you to have all the answers.","Parece que você está progredindo. Lembre que não precisa provar seu valor fazendo tudo sozinha. Ninguém espera que saiba tudo."],["Emma","I appreciate that. I'm trying to set realistic expectations and avoid burning myself out. There's no point in delivering results if I can't maintain that pace.","Agradeço. Estou tentando criar expectativas realistas e evitar o esgotamento. Não adianta entregar resultados sem conseguir manter o ritmo."],["Lucas","Exactly. A demanding job can help you grow, but it's important to know when to push yourself and when to take a step back.","Exatamente. Um trabalho exigente ajuda a crescer, mas é importante saber quando se desafiar e quando diminuir o ritmo."],["Emma","You're right. All things considered, I'm enjoying the challenge. There's still a lot to figure out, but I finally feel like I'm finding my feet.","Você tem razão. Considerando tudo, gosto do desafio. Ainda tenho muito a descobrir, mas finalmente estou me adaptando."]],"grammar":[{"h":"Collocations: combinações naturais","p":["Collocations são palavras que ocorrem frequentemente juntas: meet a deadline, make progress, take responsibility.","Aprender a combinação inteira torna a fala mais natural."],"ex":[["We need to meet the deadline without compromising quality.","Precisamos cumprir o prazo sem comprometer a qualidade."],["The team made significant progress after agreeing on priorities.","A equipe progrediu bastante após alinhar prioridades."],["Taking responsibility requires confidence and good judgment.","Assumir responsabilidade exige confiança e bom senso."]],"tip":"Aprenda a expressão inteira, não apenas verbos isolados."},{"h":"Expressões de adaptação","p":["A steep learning curve indica aprendizado rápido e exigente, frequentemente difícil.","Learn the ropes é aprender o funcionamento; hit the ground running é começar produzindo imediatamente; a lot on your plate indica excesso de tarefas."],"ex":[["The first month involved a steep learning curve.","O primeiro mês exigiu intenso aprendizado."],["It took me weeks to learn the ropes.","Levei semanas para aprender como funcionava."],["We need someone who can hit the ground running.","Precisamos de alguém que consiga produzir desde o começo."]],"tip":"A steep learning curve não significa apenas aprender depressa."},{"h":"Cut corners e on the same page","p":["Cut corners é cortar etapas, geralmente prejudicando qualidade; on the same page é estar alinhado quanto a um assunto.","Get up to speed significa atualizar-se e iron out significa resolver detalhes problemáticos."],"ex":[["We can't cut corners on safety to meet a deadline.","Não podemos economizar etapas de segurança para cumprir prazo."],["Let's make sure everyone is on the same page.","Vamos garantir que todos estejam alinhados."],["I'll bring you up to speed before the meeting.","Vou atualizar você antes da reunião."],["We still need to iron out a few issues.","Ainda precisamos resolver algumas questões."]],"tip":"Observe as preposições das expressões."},{"h":"Registro e contexto profissional","p":["Expressões idiomáticas são comuns entre colegas, mas relatórios podem pedir formas neutras.","Keep someone in the loop equivale a manter informado; push back a deadline é adiar um prazo."],"ex":[["Please keep me in the loop if anything changes.","Mantenha-me informado se algo mudar."],["We may need to push back the deadline.","Talvez precisemos adiar o prazo."],["Delegating can be a double-edged sword.","Delegar pode ser uma faca de dois gumes."]],"tip":"Em textos técnicos, privilegie precisão em vez de acumular expressões."}],"vocab":[{"h":"Aprendizado e adaptação","items":[["a steep learning curve","aprendizado intenso e exigente"],["learn the ropes","aprender como funciona"],["hit the ground running","começar produzindo imediatamente"],["get up to speed","atualizar-se"],["find your feet","começar a se adaptar"],["figure something out","descobrir como funciona"],["burn yourself out","esgotar-se"],["set realistic expectations","definir expectativas realistas"]]},{"h":"Produtividade e equipe","items":[["meet a deadline","cumprir um prazo"],["tight deadline","prazo apertado"],["cut corners","cortar etapas importantes"],["on the same page","alinhados"],["have a lot on your plate","ter tarefas demais"],["keep someone in the loop","manter informado"],["iron out a problem","resolver um problema"],["push back a deadline","adiar prazo"],["take ownership","assumir responsabilidade"],["bottleneck","gargalo"]]}],"pron":[{"h":"A steep learning curve","p":"Steep tem vogal longa: “stíip”; curve tem r americano.","w":["a steep learning curve","learning curve","steep"]},{"h":"Cut corners","p":"Aproximadamente “kât cór-nərz”; meet a deadline tem vogal reduzida em a.","w":["cut corners","meet a deadline","meeting a tight deadline"]},{"h":"On the same page","p":"Same page recebe destaque; get up to speed conecta to como “tə”.","w":["on the same page","get up to speed","keep me in the loop"]}],"mc":[{"q":"Por que Emma fala em steep learning curve?","o":["O trabalho é simples","Precisa aprender muitas coisas rapidamente","Não mudou de função"],"a":1,"e":"It's been a steep learning curve, to put it mildly. I thought my previous experience would make the transition easier, but there's a lot more to learn than I expected."},{"q":"O que está desalinhado?","o":["As prioridades entre departamentos","Os salários","As viagens"],"a":0,"e":"Honestly, I've got a lot on my plate. We're supposed to meet a tight deadline next Friday, and two departments aren't even on the same page about the priorities."},{"q":"Por que Emma rejeita cut corners?","o":["Não há testes","Quer cancelar tudo","Não quer comprometer a confiabilidade"],"a":2,"e":"Exactly what I said. I'd rather push back the deadline slightly than release something unreliable. Fortunately, the team eventually backed me up."},{"q":"Qual o desafio da delegação?","o":["É sempre negativa","Requer informação adequada","Elimina responsabilidades"],"a":1,"e":"True. I'm also learning that delegating is a double-edged sword. It frees up time, but you need to make sure people have the information they need."}],"gaps":[{"s":"My new role involves a steep learning ___.","a":["curve"],"h":"Meu cargo exige aprendizado intenso."},{"s":"We need to ___ the deadline without compromising quality.","a":["meet"],"h":"Precisamos cumprir o prazo sem prejudicar a qualidade."},{"s":"We must not cut ___ on safety.","a":["corners"],"h":"Não devemos cortar etapas de segurança."},{"s":"Everyone needs to be on the same ___.","a":["page"],"h":"Todos precisam estar alinhados."},{"s":"Could you bring me up to ___?","a":["speed"],"h":"Você poderia me atualizar?"},{"s":"Keep me in the ___ if anything changes.","a":["loop"],"h":"Mantenha-me informado se algo mudar."}],"order":[{"t":["We","need","to","meet","the","deadline."],"h":"Precisamos cumprir o prazo."},{"t":["Let's","get","everyone","on","the","same","page."],"h":"Vamos alinhar todos."},{"t":["Don't","cut","corners","on","quality","control."],"h":"Não corte etapas do controle de qualidade."}],"dict":[{"t":"My first month in the new position has been a steep learning curve, but I'm gradually finding my feet."},{"t":"We need to meet the deadline without cutting corners or compromising the quality of our work."},{"t":"Before making major decisions, let's make sure everyone is on the same page about our priorities."},{"t":"I've got a lot on my plate this week, so I may need to delegate some responsibilities."},{"t":"Please keep me in the loop while the team works to iron out the remaining technical issues."}],"shadow":["It's been a steep learning curve, to put it mildly. I thought my previous experience would make the transition easier, but there's a lot more to learn than I expected.","Honestly, I've got a lot on my plate. We're supposed to meet a tight deadline next Friday, and two departments aren't even on the same page about the priorities.","That sounds risky. Meeting a deadline matters, obviously, but cutting corners on quality could come back to bite you later.","You're right. All things considered, I'm enjoying the challenge. There's still a lot to figure out, but I finally feel like I'm finding my feet."],"write":{"task":"Relate em 110 a 140 palavras sua adaptação a um projeto ou trabalho. Use cinco expressões idiomáticas de modo natural.","ph":"I faced a steep learning curve … I had to get up to speed … We were not on the same page …"},"cards":[["Meu novo trabalho exige aprendizado intenso.","My new job involves a steep learning curve."],["Preciso aprender como tudo funciona primeiro.","I need to learn the ropes first."],["Esperavam que eu começasse a produzir imediatamente.","They expected me to hit the ground running."],["Precisamos cumprir esse prazo apertado.","We need to meet this tight deadline."],["Não devemos comprometer a qualidade para economizar tempo.","We shouldn't cut corners to save time."],["Finalmente estamos alinhados.","We're finally on the same page."],["Pode me atualizar sobre o projeto?","Can you bring me up to speed on the project?"],["Estou com tarefas demais nesta semana.","I've got too much on my plate this week."],["Mantenha-me informado sobre qualquer mudança.","Keep me in the loop about any changes."],["Precisamos resolver alguns problemas antes do lançamento.","We need to iron out a few issues before the launch."]]},{"title":"Nevertheless","goal":"Construir argumentos coerentes usando nevertheless, consequently, whereas, notwithstanding, in light of e on the grounds that, com concessão e justificativas claras.","speakers":{"Sarah":"f","Daniel":"m"},"setting":"Sarah e Daniel preparam proposta para ampliar o transporte público em regiões afastadas da cidade.","lines":[["Sarah","I've reviewed the transportation survey. Demand for additional bus services is substantial, particularly in neighborhoods far from the city center.","Analisei a pesquisa de transporte. A demanda por ônibus adicionais é considerável, especialmente longe do centro."],["Daniel","That's encouraging. Nevertheless, we need to acknowledge that expanding the network would involve significant operating costs.","Isso anima. Mesmo assim, precisamos reconhecer que ampliar a rede teria custos operacionais significativos."],["Sarah","Absolutely. Residents in the northern district reported long waiting times, whereas those in the southern district were more concerned about unreliable schedules.","Claro. No norte, os moradores relataram longas esperas, enquanto no sul a preocupação era com horários pouco confiáveis."],["Daniel","That's an important distinction. Consequently, a single solution probably wouldn't address the needs of both communities effectively.","É uma distinção importante. Consequentemente, uma única solução provavelmente não atenderia bem a ambas as regiões."],["Sarah","Exactly. In light of these findings, I'd recommend increasing service frequency in the north and improving schedule reliability in the south.","Exatamente. À luz desses resultados, recomendaria mais frequência no norte e horários mais confiáveis no sul."],["Daniel","That seems reasonable. However, the finance department rejected a similar proposal last year on the grounds that it was financially unsustainable.","Parece razoável. Entretanto, o financeiro rejeitou proposta semelhante no ano passado alegando inviabilidade financeira."],["Sarah","I'm aware of that decision. Notwithstanding those concerns, the latest figures suggest that the long-term benefits could outweigh the initial investment.","Sei dessa decisão. Apesar dessas preocupações, os números recentes sugerem que os benefícios a longo prazo podem superar o investimento."],["Daniel","Possibly, but we shouldn't overstate the evidence. The survey measures residents' preferences, not necessarily how frequently they would use additional services.","Possivelmente, mas não devemos exagerar as evidências. A pesquisa mede preferências, não a frequência real de uso."],["Sarah","That's fair. We could propose a six-month pilot program, thereby allowing the city to evaluate actual demand before committing to permanent changes.","Justo. Podemos propor um teste de seis meses, permitindo avaliar a demanda real antes de mudanças permanentes."],["Daniel","I like that approach. Nevertheless, we'd need clear performance indicators to determine whether the pilot justified further investment.","Gosto da abordagem. Mesmo assim, precisaríamos de indicadores claros para saber se o teste justifica mais investimento."],["Sarah","Agreed. We should measure passenger numbers, average waiting times, operating costs, and satisfaction levels. Otherwise, the evaluation might be inconclusive.","Concordo. Devemos medir passageiros, espera média, custos e satisfação. Caso contrário, a avaliação pode ser inconclusiva."],["Daniel","There's another argument worth considering. Some officials believe investment should focus exclusively on roads rather than public transportation.","Outro argumento: algumas autoridades acreditam que o investimento deve ir só para vias, não para transporte público."],["Sarah","I understand their position. Nevertheless, road improvements alone wouldn't necessarily address the difficulties faced by residents who don't own cars.","Entendo, mas melhorar vias não resolve necessariamente as dificuldades de quem não tem carro."],["Daniel","Precisely. We could acknowledge the importance of road maintenance while arguing that accessible transportation deserves comparable attention.","Precisamente. Podemos reconhecer a manutenção viária e defender que transporte acessível merece atenção semelhante."],["Sarah","In light of the budget restrictions, perhaps we should recommend introducing the improvements gradually instead of expanding everything at once.","Considerando as restrições do orçamento, talvez seja melhor propor melhorias graduais em vez de ampliar tudo de uma vez."],["Daniel","That would strengthen our argument. A phased implementation would reduce immediate financial pressure and provide opportunities to adjust the strategy.","Isso fortalece o argumento. Implementação por etapas reduziria a pressão financeira e permitiria ajustes."],["Sarah","Then our conclusion should be balanced: the evidence supports further investment, albeit with careful monitoring and a realistic implementation schedule.","Nossa conclusão deve ser equilibrada: as evidências apoiam o investimento, embora exijam monitoramento e cronograma realista."],["Daniel","Agreed. A convincing proposal doesn't ignore opposing arguments. It acknowledges them, evaluates the evidence, and explains why the recommendation remains justified.","Concordo. Uma boa proposta não ignora críticas: reconhece, avalia as evidências e justifica a recomendação."]],"grammar":[{"h":"Nevertheless e however","p":["Nevertheless indica que algo continua válido apesar de uma objeção; however introduz contraste de modo mais amplo.","Em textos formais, use ponto ou ponto e vírgula antes desses conectores, não apenas vírgula."],"ex":[["The results were promising. Nevertheless, limitations remain.","Os resultados foram promissores. Mesmo assim, ainda há limitações."],["The proposal offers benefits; however, its costs need analysis.","A proposta oferece benefícios; entretanto, os custos exigem análise."],["The deadline is demanding. Even so, the team may succeed.","O prazo é exigente. Mesmo assim, a equipe pode conseguir."]],"tip":"Still e even so são alternativas mais conversacionais."},{"h":"Consequently e whereas","p":["Consequently introduz consequência lógica; whereas contrasta duas informações.","Não confunda causa e contraste ao organizar argumentos."],"ex":[["The requirements were not met. Consequently, the application was rejected.","As exigências não foram cumpridas. Consequentemente, o pedido foi rejeitado."],["The north experienced increased demand, whereas the south remained stable.","O norte teve aumento da demanda, enquanto o sul permaneceu estável."],["The sample was small; consequently, interpretation requires caution.","A amostra era pequena; por isso, é preciso cautela."]],"tip":"Consequently indica resultado; whereas, diferença."},{"h":"Notwithstanding e in light of","p":["Notwithstanding equivale a despite e introduz um obstáculo que não impede a conclusão.","In light of equivale a considerando, apresentando evidência relevante."],"ex":[["Notwithstanding the restrictions, the project was approved.","Apesar das restrições, o projeto foi aprovado."],["In light of the evidence, we revised our recommendation.","À luz das evidências, revisamos a recomendação."],["Notwithstanding these limitations, the study offers useful insights.","Apesar dessas limitações, o estudo oferece informações úteis."]],"tip":"As expressões não são sinônimas: uma concede e a outra fundamenta."},{"h":"On the grounds that","p":["On the grounds that + oração apresenta o fundamento alegado para uma decisão.","On the grounds of + substantivo é outra construção possível e mais nominal."],"ex":[["The proposal was rejected on the grounds that evidence was insufficient.","A proposta foi rejeitada sob o argumento de que as evidências eram insuficientes."],["They challenged the decision on the grounds of procedural errors.","Contestaram a decisão por erros processuais."],["The committee argued that benefits outweighed costs.","O comitê argumentou que os benefícios superavam os custos."]],"tip":"Apresentar uma justificativa alegada não significa necessariamente endossá-la."}],"vocab":[{"h":"Conectores argumentativos","items":[["nevertheless","entretanto; mesmo assim"],["consequently","consequentemente"],["whereas","enquanto; ao passo que"],["notwithstanding","apesar de"],["in light of","à luz de"],["on the grounds that","sob o argumento de que"],["albeit","embora"],["thereby","desse modo"],["even so","mesmo assim"]]},{"h":"Transporte e políticas","items":[["supporting evidence","evidência de apoio"],["opposing argument","argumento contrário"],["financially unsustainable","financeiramente inviável"],["outweigh the costs","superar os custos"],["performance indicator","indicador de desempenho"],["phased implementation","implementação por etapas"],["public transportation","transporte público"],["service frequency","frequência do serviço"],["budget restrictions","restrições orçamentárias"]]}],"pron":[{"h":"Nevertheless e consequently","p":"Nevertheless soa “né-vər-dhə-lés”; consequently soa “kán-sə-kuənt-li”.","w":["nevertheless","consequently","nevertheless we agreed"]},{"h":"Whereas e notwithstanding","p":"Whereas tem destaque inicial; notwithstanding destaca stand.","w":["whereas","notwithstanding","notwithstanding the difficulties"]},{"h":"In light of","p":"Aproximadamente “in láit əv”; grounds recebe destaque em on the grounds that.","w":["in light of","on the grounds that","in light of the results"]}],"mc":[{"q":"O que varia entre norte e sul?","o":["Preço de tarifas","Espera versus confiabilidade","Cor dos ônibus"],"a":1,"e":"Absolutely. Residents in the northern district reported long waiting times, whereas those in the southern district were more concerned about unreliable schedules."},{"q":"Por que a proposta anterior foi rejeitada?","o":["Inviabilidade financeira","Ausência de passageiros","Falta de veículos novos"],"a":0,"e":"That seems reasonable. However, the finance department rejected a similar proposal last year on the grounds that it was financially unsustainable."},{"q":"Qual estratégia para avaliar demanda real?","o":["Criar linhas permanentes","Cancelar a pesquisa","Programa experimental de seis meses"],"a":2,"e":"That's fair. We could propose a six-month pilot program, thereby allowing the city to evaluate actual demand before committing to permanent changes."},{"q":"Como lidar com restrições financeiras?","o":["Ignorá-las","Implementar por etapas","Reduzir toda manutenção"],"a":1,"e":"That would strengthen our argument. A phased implementation would reduce immediate financial pressure and provide opportunities to adjust the strategy."}],"gaps":[{"s":"The results were promising. ___, limitations remain.","a":["Nevertheless"],"h":"Os resultados foram promissores, mas há limitações."},{"s":"Demand increased. ___, operating costs rose.","a":["Consequently"],"h":"A demanda aumentou. Consequentemente, custos subiram."},{"s":"The north needs more buses, ___ the south needs reliability.","a":["whereas"],"h":"O norte precisa de ônibus; o sul, de horários confiáveis."},{"s":"___ the restrictions, the proposal was approved.","a":["Notwithstanding"],"h":"Apesar das restrições, a proposta foi aprovada."},{"s":"In ___ of recent evidence, we revised the report.","a":["light"],"h":"À luz das evidências, revisamos o relatório."},{"s":"The application was refused on the ___ that it was incomplete.","a":["grounds"],"h":"O pedido foi recusado por estar incompleto."}],"order":[{"t":["Nevertheless,","the","proposal","remains","a","viable","option."],"h":"Mesmo assim, a proposta continua viável."},{"t":["Consequently,","the","committee","revised","its","decision."],"h":"Consequentemente, o comitê revisou sua decisão."},{"t":["In","light","of","findings,","we","revised","the","proposal."],"h":"À luz dos resultados, revisamos a proposta."}],"dict":[{"t":"The investment would be costly; nevertheless, its long-term benefits could justify the expense."},{"t":"Demand increased in one district, whereas passenger numbers remained stable in the other."},{"t":"Notwithstanding financial restrictions, the committee recommended gradually expanding bus services."},{"t":"In light of new evidence, the organization reconsidered its recommendation."},{"t":"The proposal was rejected on the grounds that its benefits did not justify the costs."}],"shadow":["That's encouraging. Nevertheless, we need to acknowledge that expanding the network would involve significant operating costs.","Exactly. In light of these findings, I'd recommend increasing service frequency in the north and improving schedule reliability in the south.","I'm aware of that decision. Notwithstanding those concerns, the latest figures suggest that the long-term benefits could outweigh the initial investment.","Agreed. A convincing proposal doesn't ignore opposing arguments. It acknowledges them, evaluates the evidence, and explains why the recommendation remains justified."],"write":{"task":"Escreva um argumento de 130 a 160 palavras com tese, oposição e conclusão. Use cinco conectores da unidade com relações lógicas corretas.","ph":"Whereas some people argue … Nevertheless … In light of … Consequently …"},"cards":[["A proposta é cara. Mesmo assim, merece consideração.","The proposal is expensive. Nevertheless, it deserves consideration."],["A demanda aumentou. Consequentemente, os custos subiram.","Demand increased. Consequently, costs rose."],["Um grupo concordou, enquanto o outro se opôs.","One group agreed, whereas the other opposed the proposal."],["Apesar das dificuldades, o projeto continua viável.","Notwithstanding the difficulties, the project remains viable."],["À luz das evidências, precisamos rever a decisão.","In light of the evidence, we need to review the decision."],["A proposta foi rejeitada por ser inviável.","The proposal was rejected on the grounds that it was unsustainable."],["Os benefícios parecem superar os riscos.","The benefits appear to outweigh the risks."],["Os resultados são promissores, embora ainda limitados.","The findings are promising, albeit still limited."],["A decisão exige uma justificativa bem fundamentada.","The decision requires a well-founded justification."],["Devemos reconhecer argumentos contrários.","We should acknowledge opposing arguments."]]},{"title":"Would You Be Open To...?","goal":"Negociar e persuadir diplomaticamente com I was wondering if, would you be open to, might want to, I take your point, but e propostas de compromisso.","speakers":{"Emma":"f","Lucas":"m"},"setting":"Emma e Lucas negociam mudanças em um programa de treinamento para reduzir custos sem prejudicar a aprendizagem.","lines":[["Emma","Thanks for making time today. I was wondering if we could revisit the training schedule before confirming the arrangements with our external instructors.","Obrigada pelo tempo. Gostaria de saber se podemos rever o cronograma antes de confirmar os detalhes com os instrutores externos."],["Lucas","Of course. Is there a particular issue you're concerned about, or are you looking to make broader changes to the program?","Claro. Existe alguma preocupação específica ou você pretende mudar o programa de modo mais amplo?"],["Emma","Primarily the budget. Would you be open to combining two of the introductory sessions, provided we preserve enough time for questions?","Principalmente o orçamento. Você estaria disposto a unir duas sessões introdutórias, desde que haja tempo suficiente para perguntas?"],["Lucas","I can see the financial advantage. My concern is that larger groups might discourage participants from asking questions, especially during their first session.","Vejo a vantagem financeira. Minha preocupação é que grupos maiores desestimulem perguntas, principalmente na primeira sessão."],["Emma","I take your point, but we might be able to address that by including smaller discussion groups toward the end of the session.","Entendo seu argumento, mas talvez possamos resolver isso com grupos menores de discussão no final."],["Lucas","That's an interesting possibility. I'd be more comfortable with the change if we could guarantee enough facilitators for those discussions.","É uma possibilidade interessante. Eu ficaria mais confortável se garantíssemos facilitadores suficientes para as discussões."],["Emma","That sounds fair. Would it be possible to assign two experienced employees to support the instructor without significantly increasing our costs?","Parece justo. Seria possível designar dois funcionários experientes para apoiar o instrutor sem aumentar muito os custos?"],["Lucas","Potentially. However, I wouldn't want to commit their time without checking their availability. We should probably speak to their managers first.","Talvez. Mas não comprometeria o tempo deles sem verificar a disponibilidade. Devemos conversar com seus gestores primeiro."],["Emma","Absolutely. Another option might be to shorten the theoretical presentation and give participants more opportunities to practice independently.","Claro. Outra possibilidade seria encurtar a apresentação teórica e oferecer mais prática independente."],["Lucas","I'm open to that in principle. That said, I'd be hesitant to remove too much background information, since some participants have very little experience.","Em princípio, estou aberto. Dito isso, hesitaria em eliminar informações básicas demais, pois alguns participantes têm pouca experiência."],["Emma","That's understandable. What if we provided the essential background material beforehand and used the live session to clarify the more difficult concepts?","Entendo. E se distribuíssemos o material essencial antes e usássemos a sessão ao vivo para esclarecer os conceitos difíceis?"],["Lucas","That could work. We'd need to make sure the materials were accessible and avoid assuming everyone had enough time to study them.","Pode funcionar. Teríamos que garantir materiais acessíveis e não presumir que todos tenham tempo para estudá-los."],["Emma","Agreed. Perhaps we could meet halfway: keep the first session at its original length but shorten the second one slightly.","Concordo. Talvez possamos chegar a um meio-termo: manter a primeira sessão e encurtar um pouco a segunda."],["Lucas","I think that's a reasonable compromise. The first session is particularly important for establishing expectations and helping participants feel comfortable.","É um compromisso razoável. A primeira sessão ajuda a estabelecer expectativas e deixar as pessoas à vontade."],["Emma","Great. Would you mind putting together a revised outline so we can compare the costs and expected learning outcomes?","Ótimo. Você se importaria de preparar um roteiro revisado para compararmos custos e resultados de aprendizagem esperados?"],["Lucas","Not at all. Could I ask for one thing in return? I'd appreciate it if we could agree on the minimum instructional time before making further cuts.","De forma alguma. Posso pedir algo em troca? Agradeceria se concordássemos sobre o tempo mínimo de ensino antes de outros cortes."],["Emma","Absolutely. I'm not trying to compromise the training. I'm trying to find an arrangement that works within our financial constraints.","Com certeza. Não quero prejudicar o treinamento. Quero encontrar uma solução dentro das nossas limitações financeiras."],["Lucas","Then I think we're getting somewhere. Let's document what we've agreed on and revisit the remaining questions once we have the updated figures.","Então estamos avançando. Vamos registrar os acordos e revisitar as questões pendentes quando tivermos números atualizados."]],"grammar":[{"h":"I was wondering if","p":["I was wondering if suaviza pedidos e perguntas; o passado cria distanciamento diplomático, não necessariamente referência a uma dúvida encerrada.","Dentro da pergunta indireta, a ordem é afirmativa."],"ex":[["I was wondering if you could review the proposal.","Gostaria de saber se você poderia revisar a proposta."],["I was wondering whether we might postpone the meeting.","Gostaria de saber se poderíamos adiar a reunião."],["I was hoping we could reach an agreement.","Eu esperava que pudéssemos chegar a um acordo."]],"tip":"Diga if you could help, não if could you help."},{"h":"Would you be open to","p":["Would you be open to explora uma opção sem pressupor concordância.","Como to é preposição, use substantivo ou verbo em -ing depois dela."],"ex":[["Would you be open to extending the trial period?","Você estaria disposto a estender o período de testes?"],["How would you feel about introducing the changes gradually?","O que acharia de introduzir as mudanças gradualmente?"],["Would you consider adjusting the schedule?","Você consideraria ajustar o cronograma?"]],"tip":"Use open to reconsidering, não open to reconsider."},{"h":"I take your point, but","p":["I take your point reconhece um argumento sem necessariamente concordar.","I can see why e that's a fair concern também demonstram reconhecimento genuíno; that said introduz uma ressalva."],"ex":[["I take your point, but the deadline may be unrealistic.","Entendo seu argumento, mas o prazo pode ser irrealista."],["I can see why you'd prefer that option. That said, consider the costs.","Entendo sua preferência. Dito isso, considere os custos."],["I'd be hesitant to approve the changes without consultation.","Eu hesitaria em aprovar as mudanças sem consulta."]],"tip":"Diplomacia não significa esconder divergências importantes."},{"h":"Might want to e compromisso","p":["Might want to apresenta uma sugestão sem uma ordem explícita.","Could we perhaps e Would it be possible também exploram possibilidades.","Meet halfway e reach a compromise expressam concessões mútuas."],"ex":[["We might want to reconsider the timeline.","Talvez seja melhor reconsiderarmos o cronograma."],["Could we perhaps explore a less expensive option?","Será que poderíamos explorar uma opção mais barata?"],["I'd be willing to meet you halfway.","Eu estaria disposto a encontrar um meio-termo."]],"tip":"Registre claramente o que foi acordado e o que não é negociável."}],"vocab":[{"h":"Pedidos diplomáticos","items":[["I was wondering if","gostaria de saber se"],["would you be open to","estaria disposto a"],["would you consider","consideraria"],["would it be possible","seria possível"],["might want to","talvez seja melhor"],["could we perhaps","será que poderíamos"],["I'd appreciate it if","eu agradeceria se"],["how would you feel about","o que acharia de"]]},{"h":"Negociação e concessões","items":[["I take your point","entendo seu argumento"],["that's a fair concern","é uma preocupação válida"],["meet halfway","encontrar um meio-termo"],["reach a compromise","chegar a um compromisso"],["find common ground","encontrar pontos em comum"],["be hesitant to","hesitar em"],["be willing to","estar disposto a"],["in principle","em princípio"],["learning outcomes","resultados de aprendizagem"],["financial constraints","limitações financeiras"]]}],"pron":[{"h":"I was wondering if","p":"Was reduz frequentemente para “wəz”; wondering recebe o destaque principal.","w":["I was wondering if","I was wondering if you could","I was hoping"]},{"h":"Would you","p":"Would you pode soar “wúdju”; could we tem ligação entre as palavras.","w":["Would you be open to","Would you consider","Could we perhaps"]},{"h":"Compromise","p":"Compromise recebe destaque inicial, aproximadamente “kám-prə-maiz”.","w":["compromise","reach a compromise","meet halfway"]}],"mc":[{"q":"Qual o objetivo de Emma?","o":["Reduzir custos sem prejudicar a aprendizagem","Cancelar todo o programa","Contratar mais diretores"],"a":0,"e":"Primarily the budget. Would you be open to combining two of the introductory sessions, provided we preserve enough time for questions?"},{"q":"Qual preocupação de Lucas?","o":["Turmas sem instrutores","Grupos grandes podem desestimular perguntas","Poucos computadores"],"a":1,"e":"I can see the financial advantage. My concern is that larger groups might discourage participants from asking questions, especially during their first session."},{"q":"Qual compromisso foi proposto?","o":["Eliminar primeira sessão","Cancelar prática","Manter primeira sessão e encurtar segunda"],"a":2,"e":"Agreed. Perhaps we could meet halfway: keep the first session at its original length but shorten the second one slightly."},{"q":"O que Lucas pede em troca?","o":["Definir tempo mínimo de ensino","Mais orçamento de publicidade","Trocar todos os instrutores"],"a":0,"e":"Not at all. Could I ask for one thing in return? I'd appreciate it if we could agree on the minimum instructional time before making further cuts."}],"gaps":[{"s":"I was ___ if we could review the proposal.","a":["wondering"],"h":"Gostaria de saber se poderíamos revisar a proposta."},{"s":"Would you be ___ to reconsidering the schedule?","a":["open"],"h":"Você estaria disposto a reconsiderar o cronograma?"},{"s":"I ___ your point, but I am concerned.","a":["take"],"h":"Entendo seu argumento, mas estou preocupado."},{"s":"We might ___ to review the figures.","a":["want"],"h":"Talvez seja melhor rever os números."},{"s":"Could we ___ explore a cheaper option?","a":["perhaps"],"h":"Será que poderíamos explorar uma opção mais barata?"},{"s":"I'd appreciate it ___ you could respond today.","a":["if"],"h":"Eu agradeceria se você respondesse hoje."}],"order":[{"t":["Would","you","be","open","to","reconsidering","this?"],"h":"Você estaria disposto a reconsiderar isso?"},{"t":["I","take","your","point,","but","I'm","concerned."],"h":"Entendo seu argumento, mas estou preocupado."},{"t":["Could","we","perhaps","find","a","compromise?"],"h":"Será que podemos encontrar um meio-termo?"}],"dict":[{"t":"I was wondering if we could revisit the proposed schedule before confirming the final arrangements."},{"t":"Would you be open to combining the introductory sessions while preserving enough time for individual questions?"},{"t":"I take your point, but I'm concerned that the proposed changes might compromise the quality of the training."},{"t":"We might want to explore alternative arrangements before committing to a more expensive solution."},{"t":"I'd appreciate it if we could reach a reasonable compromise without sacrificing the essential learning outcomes."}],"shadow":["Thanks for making time today. I was wondering if we could revisit the training schedule before confirming the arrangements with our external instructors.","Primarily the budget. Would you be open to combining two of the introductory sessions, provided we preserve enough time for questions?","I take your point, but we might be able to address that by including smaller discussion groups toward the end of the session.","Agreed. Perhaps we could meet halfway: keep the first session at its original length but shorten the second one slightly."],"write":{"task":"Escreva um e-mail de negociação de 110 a 140 palavras com reconhecimento de objeção, proposta e compromisso. Use cinco expressões diplomáticas.","ph":"I was wondering if … Would you be open to … I take your point, but … We might want to …"},"cards":[["Gostaria de saber se poderíamos conversar amanhã.","I was wondering if we could talk tomorrow."],["Você estaria disposto a considerar outra opção?","Would you be open to considering another option?"],["Entendo seu argumento, mas tenho uma preocupação.","I take your point, but I have a concern."],["Talvez seja melhor revisarmos os termos.","We might want to review the terms."],["Seria possível ampliar o prazo?","Would it be possible to extend the deadline?"],["Eu hesitaria em concordar sem mais informações.","I'd be hesitant to agree without more information."],["Podemos tentar encontrar um meio-termo?","Could we try to meet halfway?"],["É uma preocupação válida e entendo sua posição.","That's a fair concern, and I understand your position."],["Eu agradeceria se você considerasse a proposta.","I'd appreciate it if you considered the proposal."],["Acho que estamos avançando em direção a um acordo.","I think we're making progress toward an agreement."]]},{"title":"Sort Of, Kind Of","goal":"Compreender o inglês americano espontâneo com linguagem vaga, marcadores discursivos, phrasal verbs, ironia leve e understatement, distinguindo contextos informais e formais.","speakers":{"Sarah":"f","Emma":"f"},"setting":"Sarah e Emma conversam em uma cafeteria sobre uma oficina comunitária marcada por problemas e resultados inesperados.","lines":[["Emma","So, how did yesterday's workshop go? You sounded kind of stressed when you called me on Friday, but I figured things would settle down.","Então, como foi a oficina? Você parecia meio estressada quando me ligou na sexta, mas achei que tudo se acalmaria."],["Sarah","Well, it was sort of a success. I mean, everyone seemed to enjoy themselves, but getting the whole thing organized was a bit of a nightmare.","Bom, foi meio que um sucesso. Quer dizer, todo mundo pareceu se divertir, mas organizar tudo foi um pequeno pesadelo."],["Emma","Oh, no. What happened? Was it the equipment again, or did someone back out at the last minute?","Ah, não. O que aconteceu? O equipamento deu problema de novo ou alguém desistiu na última hora?"],["Sarah","Both, actually. One volunteer pulled out on Friday night, and then the projector decided it wasn't interested in working anymore.","Os dois, na verdade. Um voluntário desistiu na sexta à noite e depois o projetor resolveu não funcionar mais."],["Emma","Fantastic. Exactly what you needed. Did you manage to sort it out before people started arriving?","Maravilha. Era exatamente o que faltava. Você conseguiu resolver antes de as pessoas chegarem?"],["Sarah","More or less. We got it running about ten minutes late, which wasn't exactly ideal, considering we'd spent the entire morning setting everything up.","Mais ou menos. Fizemos funcionar com dez minutos de atraso, nada ideal, considerando que organizamos tudo a manhã inteira."],["Emma","Well, ten minutes isn't too bad. Mind you, I suppose it feels a lot longer when fifty people are sitting there waiting.","Bom, dez minutos não é tanto. Pensando bem, deve parecer muito mais quando cinquenta pessoas estão esperando."],["Sarah","Exactly. And then this guy came up to me and started going on about how the whole registration process was unnecessarily complicated.","Exatamente. Aí um cara veio reclamar sem parar que a inscrição era desnecessariamente complicada."],["Emma","Seriously? Was he actually making a reasonable point, or was he just trying to give you a hard time?","Sério? Ele tinha razão ou só estava tentando dificultar sua vida?"],["Sarah","A bit of both, I guess. He had a point about the instructions, but he made it sound as though we'd deliberately designed them to confuse people.","Um pouco dos dois, acho. Ele tinha razão sobre as instruções, mas falou como se as tivéssemos feito para confundir."],["Emma","That's a little unfair. Still, you might want to look into the registration process before the next event.","Isso é meio injusto. Mesmo assim, talvez seja bom investigar o processo de inscrição antes do próximo evento."],["Sarah","Yeah, definitely. Anyway, once the workshop finally got going, people really got into it. The practical activities turned out to be a huge hit.","Sim. Enfim, quando a oficina começou, as pessoas se envolveram. As atividades práticas acabaram sendo um sucesso."],["Emma","That's great. So it wasn't a complete disaster after all. Did anyone bring up suggestions for future workshops or anything?","Que ótimo. Então não foi um desastre completo. Alguém sugeriu algo para oficinas futuras ou coisa assim?"],["Sarah","Quite a few, actually. Some wanted longer sessions, others asked for more hands-on examples, and a couple of people suggested an evening schedule.","Várias pessoas, na verdade. Algumas queriam sessões maiores, outras mais exemplos práticos, e algumas sugeriram horários noturnos."],["Emma","Sounds like useful feedback. I suppose the trick is figuring out which suggestions are worth following up on and which ones aren't realistic.","Parece útil. Imagino que o segredo seja decidir quais sugestões vale acompanhar e quais não são realistas."],["Sarah","Exactly. And, to be fair, the volunteers were brilliant. They just got on with things instead of making a fuss whenever something went wrong.","Exatamente. E, para ser justa, os voluntários foram ótimos. Continuaram trabalhando sem criar confusão a cada problema."],["Emma","That's what matters. You know, sometimes the events that seem like the biggest headaches end up being the ones people remember most fondly.","É o que importa. Sabe, às vezes os eventos que dão mais dor de cabeça são os de que as pessoas mais gostam de lembrar."],["Sarah","Yeah, funny how that works. Anyway, next time I'm bringing a spare projector, a printed registration list, and possibly an unreasonable amount of coffee.","Pois é, engraçado. Enfim, da próxima vez levarei um projetor reserva, uma lista impressa e provavelmente café em quantidade absurda."]],"grammar":[{"h":"Sort of, kind of e vague language","p":["Sort of e kind of suavizam avaliações ou indicam aproximação.","Kinda e sorta representam reduções informais de fala, não grafias adequadas para relatórios.","More or less, or something e -ish também tornam descrições aproximadas."],"ex":[["I'm kind of disappointed, although I understand the decision.","Estou meio decepcionado, embora entenda a decisão."],["The instructions were sort of confusing at first.","As instruções eram meio confusas no início."],["We could meet around seven-ish if that works.","Podemos nos encontrar por volta das sete, se estiver bom."]],"tip":"Use vague language para aproximar, não para esconder informações essenciais."},{"h":"I mean, mind you e anyway","p":["I mean corrige ou reformula uma ideia.","Mind you introduz uma ressalva; é mais associado ao inglês britânico, mas é compreendido nos EUA.","Anyway retoma assunto, encerra digressão ou avança a história; you know procura reconhecimento."],"ex":[["The meeting went well. I mean, we didn't resolve everything.","A reunião foi boa. Quer dizer, não resolvemos tudo."],["The hotel was comfortable. Mind you, we paid more than expected.","O hotel era confortável. Pensando bem, pagamos mais do que o esperado."],["Anyway, getting back to the question, we need a date.","Enfim, voltando à pergunta, precisamos de uma data."]],"tip":"Não repita marcadores a cada frase em apresentações formais."},{"h":"Phrasal verbs na conversa","p":["Back out é desistir de compromisso; sort out é resolver; look into é investigar; turn out descreve um resultado revelado depois.","Observe partículas e estruturas: back out of an agreement; look into a complaint."],"ex":[["The instructor backed out of the agreement.","O instrutor desistiu do acordo."],["We managed to sort out the technical difficulties.","Conseguimos resolver os problemas técnicos."],["I'll look into the complaint and get back to you.","Vou investigar a reclamação e responder."],["It turned out to be surprisingly straightforward.","Acabou sendo surpreendentemente simples."]],"tip":"Look into significa investigar, não olhar fisicamente para dentro."},{"h":"Ironia e understatement","p":["Understatement descreve algo com menos intensidade do que a realidade sugere.","A ironia contrasta sentido literal e intenção; o contexto e a entonação são fundamentais.","It wasn't exactly ideal pode transmitir forte insatisfação."],"ex":[["The presentation started forty minutes late, which wasn't exactly ideal.","A apresentação começou quarenta minutos atrasada, o que não foi exatamente ideal."],["Well, that went brilliantly. We forgot the only document we needed.","Nossa, deu maravilhosamente certo. Esquecemos o único documento necessário."],["The negotiations were challenging, to put it mildly.","As negociações foram difíceis, para dizer o mínimo."]],"tip":"Evite ironia em contextos nos quais possa ser mal interpretada."}],"vocab":[{"h":"Linguagem vaga e marcadores","items":[["sort of","meio que"],["kind of","meio; um pouco"],["more or less","mais ou menos"],["or something","ou algo assim"],["and stuff","e coisas desse tipo"],["around seven-ish","por volta das sete"],["to put it mildly","para dizer o mínimo"],["I mean","quer dizer"],["mind you","pensando bem"],["anyway","enfim"]]},{"h":"Phrasal verbs e informalidade","items":[["back out","desistir de compromisso"],["pull out","retirar-se"],["sort out","resolver"],["look into","investigar"],["turn out","acabar sendo"],["get into something","envolver-se com algo"],["go on about","falar repetidamente sobre"],["give someone a hard time","dificultar a vida de alguém"],["make a fuss","criar confusão"],["get on with something","seguir com algo"]]}],"pron":[{"h":"Kind of e sort of","p":"Reduções informais: kind of soa “káin-də”; sort of, “sór-də”.","w":["kind of","sort of","kind of difficult","sort of confusing"]},{"h":"I mean e you know","p":"I mean soa “ái mín”; you know pode reduzir para “yə nôu”.","w":["I mean","you know","you know what I mean"]},{"h":"Anyway e actually","p":"Anyway destaca a primeira sílaba; actually frequentemente é reduzido na fala.","w":["anyway","actually","anyway let's continue"]}],"mc":[{"q":"Quais problemas ocorreram?","o":["Desistência de voluntário e falha do projetor","Fechamento do prédio","Cancelamento de todas as atividades"],"a":0,"e":"Both, actually. One volunteer pulled out on Friday night, and then the projector decided it wasn't interested in working anymore."},{"q":"Qual sentido de sort of a success?","o":["Fracasso absoluto","Resultado positivo apesar dos problemas","Nenhuma participação"],"a":1,"e":"Well, it was sort of a success. I mean, everyone seemed to enjoy themselves, but getting the whole thing organized was a bit of a nightmare."},{"q":"Como foram as atividades práticas?","o":["Foram canceladas","Foram excessivamente curtas","Fizeram sucesso"],"a":2,"e":"Yeah, definitely. Anyway, once the workshop finally got going, people really got into it. The practical activities turned out to be a huge hit."},{"q":"Como agiram os voluntários?","o":["Continuaram trabalhando sem criar confusão","Foram embora","Deixaram tudo para Sarah"],"a":0,"e":"Exactly. And, to be fair, the volunteers were brilliant. They just got on with things instead of making a fuss whenever something went wrong."}],"gaps":[{"s":"The situation was ___ of confusing at first.","a":["kind","sort"],"h":"A situação foi meio confusa no começo."},{"s":"It was ___ of a success despite the difficulties.","a":["sort","kind"],"h":"Foi meio que um sucesso apesar dos problemas."},{"s":"I ___, we made progress even without finishing.","a":["mean"],"h":"Quer dizer, avançamos mesmo sem terminar."},{"s":"___ you, the results were surprisingly good.","a":["Mind"],"h":"Pensando bem, os resultados foram surpreendentemente bons."},{"s":"We managed to sort ___ the issue.","a":["out"],"h":"Conseguimos resolver a questão."},{"s":"The exercise turned ___ to be easier than expected.","a":["out"],"h":"O exercício acabou sendo mais fácil que o esperado."}],"order":[{"t":["It","was","kind","of","awkward","at","first."],"h":"Foi meio constrangedor no começo."},{"t":["Anyway,","we","managed","to","sort","it","out."],"h":"Enfim, conseguimos resolver isso."},{"t":["It","wasn't","exactly","the","smoothest","start."],"h":"Não foi exatamente o início mais tranquilo."}],"dict":[{"t":"The workshop was kind of chaotic at first, but everything turned out better than we expected."},{"t":"I mean, the instructions weren't exactly clear, but we managed to figure things out eventually."},{"t":"Mind you, it wasn't a complete disaster, and several participants actually asked for another session."},{"t":"One volunteer backed out at the last minute, so we had to sort out the arrangements ourselves."},{"t":"Anyway, to be fair, everyone worked incredibly hard, and the event was surprisingly successful in the end."}],"shadow":["Well, it was sort of a success. I mean, everyone seemed to enjoy themselves, but getting the whole thing organized was a bit of a nightmare.","More or less. We got it running about ten minutes late, which wasn't exactly ideal, considering we'd spent the entire morning setting everything up.","Yeah, definitely. Anyway, once the workshop finally got going, people really got into it. The practical activities turned out to be a huge hit.","Yeah, funny how that works. Anyway, next time I'm bringing a spare projector, a printed registration list, and possibly an unreasonable amount of coffee."],"write":{"task":"Escreva uma mensagem informal de 100 a 130 palavras sobre uma experiência inesperada, usando três marcadores, duas aproximações e três phrasal verbs.","ph":"Well, it was kind of … I mean … We had to sort out … Mind you … Anyway …"},"cards":[["Foi meio estranho no começo.","It was kind of awkward at first."],["Acho que funcionou, mais ou menos.","I guess it worked, more or less."],["Quer dizer, não foi exatamente um desastre.","I mean, it wasn't exactly a disaster."],["Pensando bem, poderia ter sido muito pior.","Mind you, it could have been much worse."],["Enfim, conseguimos resolver tudo.","Anyway, we managed to sort everything out."],["Ele desistiu do acordo na última hora.","He backed out of the agreement at the last minute."],["Vou investigar isso e depois aviso.","I'll look into it and let you know."],["No fim, acabou sendo uma experiência positiva.","It turned out to be a positive experience."],["Ela ficou falando sem parar sobre o problema.","She kept going on about the problem."],["Nossa, isso deu maravilhosamente certo.","Well, that went brilliantly."]]}]},"fr":{"name":"Francês","tts":"fr-FR","units":[{"title":"Bonjour !","goal":"Cumprimentar, dizer seu nome e de onde você é, e fazer as mesmas perguntas a outra pessoa.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Num café em Lyon, Claire conhece Lucas, que acabou de chegar do Brasil.","lines":[["Claire","Bonjour ! Je m'appelle Claire. Et toi ?","Olá! Eu me chamo Claire. E você?"],["Lucas","Salut, Claire ! Moi, c'est Lucas.","Oi, Claire! Eu sou o Lucas."],["Claire","Enchantée, Lucas.","Prazer, Lucas."],["Lucas","Enchanté.","Prazer."],["Claire","Tu viens d'où ?","De onde você vem?"],["Lucas","Je viens du Brésil. Je suis brésilien. Et toi ?","Eu venho do Brasil. Sou brasileiro. E você?"],["Claire","Moi, je suis française. Je suis de Lyon.","Eu sou francesa. Sou de Lyon."],["Lucas","Super !","Que legal!"],["Claire","Bon, à bientôt, Lucas !","Bom, até logo, Lucas!"],["Lucas","Au revoir, Claire !","Tchau, Claire!"]],"grammar":[{"h":"Je m'appelle… e Moi, c'est…","p":["<b>Je m'appelle Claire</b> quer dizer, ao pé da letra, “eu me chamo Claire”. <b>Moi, c'est Lucas</b> é mais informal, como “e eu sou o Lucas”.","Para perguntar o nome: <b>Tu t'appelles comment ?</b> (informal) ou <b>Vous vous appelez comment ?</b> (formal)."],"ex":[["Je m'appelle Claire.","Eu me chamo Claire."],["Moi, c'est Lucas.","Eu sou o Lucas."],["Tu t'appelles comment ?","Como você se chama?"]]},{"h":"Tu ou vous?","p":["<b>Tu</b> é para amigos, família e gente da sua idade em situação informal. <b>Vous</b> é para desconhecidos, situações formais e para falar com mais de uma pessoa. É parecido com “você” e “o senhor”.","Depois de <b>et</b>, tu vira <b>toi</b>: <b>Et toi ?</b> Com vous, nada muda: <b>Et vous ?</b>"],"ex":[["Et toi ?","E você? (informal)"],["Et vous ?","E o senhor? E a senhora? E vocês?"]],"tip":"Na dúvida com um adulto que você não conhece, use <b>vous</b>. Ninguém se ofende com o formal."},{"h":"Je suis: o verbo être","p":["<b>Être</b> quer dizer ser e estar. Nesta unidade: <b>je suis</b> (eu sou) e <b>tu es</b> (você é). Para falar da origem, use <b>je suis de</b> + cidade, ou <b>je viens du Brésil</b>."],"ex":[["Je suis brésilien.","Eu sou brasileiro."],["Je suis de Lyon.","Eu sou de Lyon."],["Je viens du Brésil.","Eu venho do Brasil."]],"tip":"Guarde <b>du Brésil</b> como um bloco pronto. Por que é “du” e não “de” você vê na Unidade 2, junto com os outros países."},{"h":"Masculino e feminino","p":["A nacionalidade muda conforme quem fala. Em geral, acrescenta-se <b>-e</b> no feminino: <b>brésilien</b> vira <b>brésilienne</b>, <b>français</b> vira <b>française</b>.","O mesmo vale para <b>enchanté</b>: a Claire escreve <b>enchantée</b> porque é mulher."],"ex":[["Il est brésilien.","Ele é brasileiro."],["Elle est brésilienne.","Ela é brasileira."],["Elle est française.","Ela é francesa."]],"tip":"<b>Enchanté</b> e <b>enchantée</b> soam iguais. Já em <b>française</b> o s passa a ser pronunciado, com som de z, e em <b>brésilienne</b> o n final aparece."}],"vocab":[{"h":"Cumprimentos","items":[["Bonjour","bom dia, olá (de dia)"],["Bonsoir","boa noite (ao chegar)"],["Salut","oi, tchau (informal)"],["Enchanté","prazer (quem fala é homem)"],["Enchantée","prazer (quem fala é mulher)"],["À bientôt","até logo"],["Au revoir","tchau, até logo"],["Merci","obrigado, obrigada"]]},{"h":"Nacionalidades","items":[["brésilien, brésilienne","brasileiro, brasileira"],["français, française","francês, francesa"],["portugais, portugaise","português, portuguesa"],["canadien, canadienne","canadense"],["américain, américaine","americano, americana"]]}],"numbers":["zéro","un","deux","trois","quatre","cinq","six","sept","huit","neuf","dix"],"pron":[{"h":"O final quase sempre some","p":"A maioria das consoantes finais não é pronunciada: <b>salut</b> soa “salü”, <b>français</b> soa “franssé”, <b>deux</b> soa “dö”. Exceções desta unidade: <b>cinq</b>, <b>sept</b> e <b>neuf</b> pronunciam o final.","w":["salut","français","deux","sept"]},{"h":"O u de salut e tu","p":"Diga “i”, mantenha a língua parada e arredonde os lábios como para dizer “u”. Esse som não existe em português.","w":["salut","tu","du"]},{"h":"O r francês","p":"Sai do fundo da garganta, parecido com o r de “carro” em boa parte do Brasil, só que mais suave.","w":["bonjour","merci","au revoir"]},{"h":"Sons nasais e o é","p":"<b>Bonjour</b> começa com um “on” nasal, parecido com o “om” de “bom”. O <b>é</b> com acento soa como o “ê” de “você”.","w":["bonjour","enchanté","brésilien"]}],"mc":[{"q":"De onde a Claire é?","o":["Paris","Lyon","Montréal"],"a":1,"e":"Ela diz: Je suis de Lyon."},{"q":"A Claire é mulher. Como ela escreve “prazer”?","o":["Enchanté.","Enchantée."],"a":1,"e":"No feminino acrescenta-se -e. Na fala, as duas formas soam iguais."},{"q":"Você fala com um senhor que não conhece. Como pergunta “e o senhor?”","o":["Et toi ?","Et vous ?"],"a":1,"e":"Vous é o formal."},{"q":"A Ana é brasileira. Elle est…","o":["brésilien","brésilienne"],"a":1,"e":"No feminino: brésilienne."}],"gaps":[{"s":"Je ___ Claire.","a":["m'appelle"],"h":"Eu me chamo Claire."},{"s":"Je ___ brésilien.","a":["suis"],"h":"Eu sou brasileiro."},{"s":"Tu ___ d'où ?","a":["viens"],"h":"De onde você vem?"},{"s":"Je viens ___ Brésil.","a":["du"],"h":"Eu venho do Brasil."},{"s":"Elle est ___.","a":["française"],"h":"Ela é francesa."}],"order":[{"t":["Tu","viens","d'où ?"],"h":"De onde você vem?"},{"t":["Je","m'appelle","Lucas."],"h":"Eu me chamo Lucas."},{"t":["Moi,","je","suis","française."],"h":"Eu sou francesa."}],"dict":[{"t":"Bonjour !"},{"t":"Je suis brésilien."},{"t":"Tu viens d'où ?"},{"t":"Enchanté.","alt":["Enchantée."],"note":"Enchanté e enchantée soam iguais: as duas respostas estão certas."},{"t":"trois"}],"shadow":["Bonjour ! Je m'appelle Claire.","Enchantée.","Tu viens d'où ?","Je viens du Brésil. Je suis brésilien."],"write":{"task":"Apresente-se em francês em 2 ou 3 frases: cumprimente, diga seu nome, sua nacionalidade e de onde você é.","ph":"Bonjour ! Je m'appelle …"},"cards":[["Eu me chamo Lucas.","Je m'appelle Lucas."],["Como você se chama?","Tu t'appelles comment ?"],["De onde você vem?","Tu viens d'où ?"],["Eu venho do Brasil.","Je viens du Brésil."],["Sou brasileiro. / Sou brasileira.","Je suis brésilien. / Je suis brésilienne."],["Prazer! (homem / mulher)","Enchanté ! / Enchantée !"],["E você? (informal)","Et toi ?"],["E o senhor? (formal)","Et vous ?"],["Até logo!","À bientôt !"]]},{"title":"D'où viens-tu ?","goal":"Dizer a nacionalidade e o país de alguém, e onde a pessoa mora.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Na escola de francês em Lyon, Claire apresenta os colegas de turma para o Lucas.","lines":[["Lucas","Qui est-ce ?","Quem é?"],["Claire","C'est Marta. Elle est espagnole. Elle vient de Madrid.","É a Marta. Ela é espanhola. Vem de Madri."],["Lucas","Et lui ?","E ele?"],["Claire","C'est Ken. Il est japonais. Il habite à Tokyo.","É o Ken. Ele é japonês. Mora em Tóquio."],["Lucas","Ils sont étudiants ?","Eles são estudantes?"],["Claire","Oui, nous sommes tous dans la même classe.","Sim, estamos todos na mesma turma."],["Lucas","Et le professeur ?","E o professor?"],["Claire","Il s'appelle Marc. Il est canadien. Il vient du Québec.","Ele se chama Marc. É canadense. Vem de Quebec."],["Lucas","Ah, il parle français et anglais !","Ah, ele fala francês e inglês!"],["Claire","Oui, mais il habite en France maintenant.","Sim, mas agora ele mora na França."]],"grammar":[{"h":"O verbo être completo","p":["<b>je suis</b>, <b>tu es</b>, <b>il est</b>, <b>elle est</b>, <b>on est</b>, <b>nous sommes</b>, <b>vous êtes</b>, <b>ils sont</b>, <b>elles sont</b>.","<b>Ils</b> serve para grupo só de homens ou misto. <b>Elles</b> é só para grupo de mulheres."],"ex":[["Nous sommes étudiants.","Nós somos estudantes."],["Vous êtes français ?","Vocês são franceses?"],["Ils sont japonais.","Eles são japoneses."]]},{"h":"Nacionalidade: masculino e feminino","p":["Em geral, o feminino ganha <b>-e</b>: japonais → <b>japonaise</b>, espagnol → <b>espagnole</b>. Algumas dobram a consoante: canadien → <b>canadienne</b>. O plural ganha <b>-s</b>, menos quando já termina em s: <b>ils sont japonais</b>."],"ex":[["Il est japonais.","Ele é japonês."],["Elle est japonaise.","Ela é japonesa."],["Elles sont canadiennes.","Elas são canadenses."]],"tip":"Como em português, a nacionalidade é escrita com letra minúscula: <b>il est français</b>."},{"h":"Em, no, na: países e cidades","p":["Países femininos (a maioria termina em -e) usam <b>en</b>: <b>en France</b>, <b>en Espagne</b>. Masculinos usam <b>au</b>: <b>au Brésil</b>, <b>au Canada</b>, <b>au Japon</b>. Plurais usam <b>aux</b>: <b>aux États-Unis</b>. Cidades usam <b>à</b>: <b>à Paris</b>."],"ex":[["J'habite au Brésil.","Moro no Brasil."],["Elle habite en France.","Ela mora na França."],["Il habite à Tokyo.","Ele mora em Tóquio."]],"tip":"<b>Le Mexique</b> termina em -e, mas é masculino: <b>au Mexique</b>."},{"h":"Venir de: de onde a pessoa vem","p":["<b>je viens</b>, <b>tu viens</b>, <b>il vient</b>. Com países: <b>de France</b> (feminino), <b>du Brésil</b> (de + le), <b>des États-Unis</b> (de + les). Com cidades: <b>de Lyon</b>."],"ex":[["Je viens du Brésil.","Venho do Brasil."],["Il vient des États-Unis.","Ele vem dos Estados Unidos."]]}],"vocab":[{"h":"Países","items":[["la France","a França"],["le Brésil","o Brasil"],["le Canada","o Canadá"],["le Japon","o Japão"],["l'Espagne","a Espanha"],["le Portugal","Portugal"],["les États-Unis","os Estados Unidos"],["le Mexique","o México"]]},{"h":"Nacionalidades","items":[["espagnol, espagnole","espanhol, espanhola"],["japonais, japonaise","japonês, japonesa"],["canadien, canadienne","canadense"],["américain, américaine","americano, americana"],["mexicain, mexicaine","mexicano, mexicana"],["portugais, portugaise","português, portuguesa"]]}],"pron":[{"h":"O feminino acorda a consoante","p":"No masculino, a consoante final é muda: <b>japonais</b> soa “japoné”. No feminino, ela aparece: <b>japonaise</b> soa “japonéz”.","w":["japonais","japonaise","américain","américaine"]},{"h":"Liaison","p":"Quando a palavra seguinte começa com vogal, a consoante muda pode se ligar a ela: <b>vous_êtes</b> soa “vuzét”.","w":["vous êtes","ils habitent","nous sommes"]},{"h":"Qui est-ce ?","p":"Soa como uma palavra só: “ki-ÉS”.","w":["Qui est-ce ?"]}],"mc":[{"q":"De onde a Marta vem?","o":["Madrid","Tokyo","Lyon"],"a":0,"e":"Elle vient de Madrid."},{"q":"Onde o Ken mora?","o":["Paris","Tokyo","Québec"],"a":1,"e":"Il habite à Tokyo."},{"q":"Como dizer “Moro no Brasil”?","o":["J'habite en Brésil.","J'habite au Brésil."],"a":1,"e":"Le Brésil é masculino: au."},{"q":"Como dizer “Ela é japonesa”?","o":["Elle est japonais.","Elle est japonaise."],"a":1,"e":"No feminino, acrescente -e."}],"gaps":[{"s":"Nous ___ étudiants.","a":["sommes"],"h":"Nós somos estudantes."},{"s":"Vous ___ français ?","a":["êtes"],"h":"Vocês são franceses?"},{"s":"J'habite ___ France.","a":["en"],"h":"Moro na França."},{"s":"Il habite ___ Canada.","a":["au"],"h":"Ele mora no Canadá."},{"s":"Ils ___ japonais.","a":["sont"],"h":"Eles são japoneses."}],"order":[{"t":["Elle","est","espagnole."],"h":"Ela é espanhola."},{"t":["J'habite","au","Brésil."],"h":"Moro no Brasil."},{"t":["Nous","sommes","dans","la","même","classe."],"h":"Estamos na mesma turma."}],"dict":[{"t":"Il est japonais."},{"t":"Elle est japonaise."},{"t":"J'habite au Brésil."},{"t":"Vous êtes français ?"},{"t":"les États-Unis"}],"shadow":["Qui est-ce ?","C'est Marta. Elle est espagnole.","Il est canadien. Il vient du Québec.","Il habite en France maintenant."],"write":{"task":"Apresente 3 pessoas em francês: o nome, a nacionalidade e onde moram.","ph":"Carla est brésilienne. Elle habite à …"},"cards":[["Quem é?","Qui est-ce ?"],["Ela é espanhola.","Elle est espagnole."],["Ele mora em Tóquio.","Il habite à Tokyo."],["Moro no Brasil.","J'habite au Brésil."],["Nós somos estudantes.","Nous sommes étudiants."],["Vocês são franceses?","Vous êtes français ?"],["Ele vem dos Estados Unidos.","Il vient des États-Unis."],["Ela mora na França.","Elle habite en France."]]},{"title":"Questions","goal":"Fazer e responder perguntas sobre dados pessoais, dizer a idade e negar.","speakers":{"Inès":"f","Lucas":"m"},"setting":"Lucas se inscreve numa academia em Lyon. Inès, a recepcionista, preenche a ficha.","lines":[["Inès","Bonjour ! Vous êtes nouveau ici ?","Bom dia! O senhor é novo aqui?"],["Lucas","Oui. Je voudrais m'inscrire.","Sim. Eu queria me inscrever."],["Inès","D'accord. Quel est votre nom ?","Certo. Qual é o seu nome?"],["Lucas","Lucas Silva.","Lucas Silva."],["Inès","Vous avez quel âge ?","Quantos anos o senhor tem?"],["Lucas","J'ai vingt-cinq ans.","Tenho vinte e cinco anos."],["Inès","Est-ce que vous êtes étudiant ?","O senhor é estudante?"],["Lucas","Non, je ne suis pas étudiant. Je travaille.","Não, não sou estudante. Eu trabalho."],["Inès","Vous avez un numéro de téléphone ?","O senhor tem um número de telefone?"],["Lucas","Oui : zéro six, douze, trente-quatre, cinquante-six, quarante-huit.","Sim: zero seis, doze, trinta e quatro, cinquenta e seis, quarenta e oito."],["Inès","Parfait, merci !","Perfeito, obrigada!"]],"grammar":[{"h":"O verbo avoir","p":["<b>j'ai</b>, <b>tu as</b>, <b>il a</b>, <b>elle a</b>, <b>nous avons</b>, <b>vous avez</b>, <b>ils ont</b>. É o “ter”."],"ex":[["J'ai un téléphone.","Tenho um telefone."],["Ils ont deux enfants.","Eles têm dois filhos."]]},{"h":"Idade com avoir","p":["Como em português, a idade usa “ter”: <b>J'ai 25 ans</b>. A pergunta: <b>Tu as quel âge ?</b> ou <b>Vous avez quel âge ?</b>"],"ex":[["J'ai vingt-cinq ans.","Tenho vinte e cinco anos."],["Elle a trente ans.","Ela tem trinta anos."]],"tip":"A palavra <b>ans</b> é obrigatória: “J'ai vingt-cinq” sozinho fica incompleto."},{"h":"Negação: ne… pas","p":["A negação abraça o verbo: <b>je ne suis pas</b>, <b>il ne travaille pas</b>. Antes de vogal, <b>ne</b> vira <b>n'</b>: <b>je n'ai pas</b>."],"ex":[["Je ne suis pas étudiant.","Não sou estudante."],["Elle n'habite pas ici.","Ela não mora aqui."]],"tip":"Na fala do dia a dia, o <b>ne</b> costuma sumir: “Je suis pas étudiant”. Escreva sempre com ele."},{"h":"Três jeitos de perguntar","p":["Pela entonação: <b>Vous êtes étudiant ?</b> Com <b>est-ce que</b>: <b>Est-ce que vous êtes étudiant ?</b> Com palavra de pergunta: <b>Quel est votre nom ?</b> <b>Vous habitez où ?</b>"],"ex":[["Est-ce que tu es français ?","Você é francês?"],["Tu habites où ?","Onde você mora?"]]}],"vocab":[{"h":"Perguntas pessoais","items":[["Quel est votre nom ?","Qual é o seu nome? (formal)"],["Vous avez quel âge ?","Quantos anos o senhor tem?"],["Tu as quel âge ?","Quantos anos você tem?"],["Vous habitez où ?","Onde o senhor mora?"],["Est-ce que… ?","(introduz pergunta)"],["D'accord.","Certo. Combinado."]]},{"h":"Palavras úteis","items":[["nouveau, nouvelle","novo, nova"],["le numéro de téléphone","o número de telefone"],["l'âge","a idade"],["un an","um ano"]]}],"numbers":[["11","onze"],["12","douze"],["13","treize"],["14","quatorze"],["15","quinze"],["16","seize"],["17","dix-sept"],["20","vingt"],["30","trente"],["40","quarante"],["50","cinquante"],["60","soixante"]],"pron":[{"h":"vingt","p":"O g e o t de <b>vingt</b> são mudos quando ele está sozinho: “vã”. Em <b>vingt-cinq</b>, o t aparece: “vãt-sank”.","w":["vingt","vingt-cinq"]},{"h":"ans se liga ao número","p":"Com <b>ans</b>, o número se liga ao a: <b>deux_ans</b> soa “dözã”, <b>trois_ans</b> soa “truazã”.","w":["deux ans","trois ans","vingt-cinq ans"]},{"h":"A pergunta sobe","p":"Sem <b>est-ce que</b>, a pergunta depende só da entonação: a voz sobe no fim.","w":["Vous êtes étudiant ?"]}],"mc":[{"q":"Quantos anos o Lucas tem?","o":["15","25","35"],"a":1,"e":"J'ai vingt-cinq ans."},{"q":"O Lucas é estudante?","o":["Sim","Não, ele trabalha"],"a":1,"e":"Je ne suis pas étudiant. Je travaille."},{"q":"Como dizer “Tenho 30 anos”?","o":["Je suis 30 ans.","J'ai 30 ans."],"a":1,"e":"Em francês, idade usa avoir."},{"q":"Qual negação está certa?","o":["Je pas suis étudiant.","Je ne suis pas étudiant."],"a":1,"e":"ne… pas em volta do verbo."}],"gaps":[{"s":"J'___ vingt-cinq ans.","a":["ai"],"h":"Tenho vinte e cinco anos."},{"s":"Je ne suis ___ français.","a":["pas"],"h":"Não sou francês."},{"s":"___ que vous êtes étudiant ?","a":["Est-ce"],"h":"O senhor é estudante?"},{"s":"Vous ___ quel âge ?","a":["avez"],"h":"Quantos anos o senhor tem?"},{"s":"Elle ___ vingt ans.","a":["a"],"h":"Ela tem vinte anos."}],"order":[{"t":["Vous","avez","quel","âge ?"],"h":"Quantos anos o senhor tem?"},{"t":["Je","ne","suis","pas","étudiant."],"h":"Não sou estudante."},{"t":["Est-ce","que","tu","es","français ?"],"h":"Você é francês?"}],"dict":[{"t":"J'ai vingt-cinq ans."},{"t":"Je ne suis pas étudiant.","alt":["Je ne suis pas étudiante."]},{"t":"Vous avez quel âge ?"},{"t":"quinze"},{"t":"soixante"}],"shadow":["Vous êtes nouveau ici ?","Vous avez quel âge ?","J'ai vingt-cinq ans.","Non, je ne suis pas étudiant."],"write":{"task":"Responda em francês: Comment vous vous appelez ? Vous avez quel âge ? Vous habitez où ? Vous êtes étudiant(e) ?","ph":"Je m'appelle … J'ai …"},"cards":[["Quantos anos o senhor tem?","Vous avez quel âge ?"],["Tenho 25 anos.","J'ai vingt-cinq ans."],["Não sou estudante.","Je ne suis pas étudiant(e)."],["Você é francês?","Est-ce que tu es français ?"],["Ela tem vinte anos.","Elle a vingt ans."],["Qual é o seu nome? (formal)","Quel est votre nom ?"],["Onde o senhor mora?","Vous habitez où ?"],["Eu trabalho.","Je travaille."]]},{"title":"Ma famille","goal":"Apresentar pessoas da família e dizer de quem é cada coisa.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Claire mostra fotos da família no celular.","lines":[["Lucas","C'est ta famille ?","É a sua família?"],["Claire","Oui ! Voici mes parents. Mon père s'appelle Paul et ma mère s'appelle Anne.","É! Estes são meus pais. Meu pai se chama Paul e minha mãe se chama Anne."],["Lucas","Et la jeune femme, c'est ta sœur ?","E a moça, é sua irmã?"],["Claire","Oui, c'est ma sœur, Julie. Son mari est italien.","É, é minha irmã, Julie. O marido dela é italiano."],["Lucas","Ils ont des enfants ?","Eles têm filhos?"],["Claire","Oui, un fils et une fille. Leur fils a six ans.","Sim, um filho e uma filha. O filho deles tem seis anos."],["Lucas","Et toi, tu as des frères ?","E você, tem irmãos?"],["Claire","Non, je n'ai pas de frère. Et toi ?","Não, não tenho irmão. E você?"],["Lucas","J'ai un frère et une sœur au Brésil.","Tenho um irmão e uma irmã no Brasil."]],"grammar":[{"h":"Artigos","p":["Definidos: <b>le</b> (o), <b>la</b> (a), <b>l'</b> (antes de vogal), <b>les</b> (os, as). Indefinidos: <b>un</b> (um), <b>une</b> (uma), <b>des</b> (uns, umas)."],"ex":[["le père, la mère, les parents","o pai, a mãe, os pais"],["un fils, une fille, des enfants","um filho, uma filha, filhos"]],"tip":"No plural, o <b>des</b> é obrigatório: “Ils ont enfants” está errado. Diga <b>Ils ont des enfants</b>."},{"h":"Possessivos","p":["<b>mon / ma / mes</b> (meu, minha, meus), <b>ton / ta / tes</b> (teu, tua), <b>son / sa / ses</b> (dele ou dela), <b>notre / nos</b> (nosso), <b>votre / vos</b> (seu, formal ou plural), <b>leur / leurs</b> (deles)."],"ex":[["mon père, ma mère, mes parents","meu pai, minha mãe, meus pais"],["leur fils","o filho deles"]],"tip":"Concorda com a <b>coisa</b>, não com o dono: <b>son mari</b> é “o marido dela”, porque <b>mari</b> é masculino."},{"h":"Negação com un, une, des","p":["Depois de uma negação, <b>un</b>, <b>une</b> e <b>des</b> viram <b>de</b> (ou <b>d'</b>): <b>Je n'ai pas de frère.</b>"],"ex":[["Je n'ai pas de sœur.","Não tenho irmã."],["Ils n'ont pas d'enfants.","Eles não têm filhos."]]}],"vocab":[{"h":"Família","items":[["le père","o pai"],["la mère","a mãe"],["les parents","os pais"],["le frère","o irmão"],["la sœur","a irmã"],["le mari","o marido"],["la femme","a esposa, a mulher"],["le fils","o filho"],["la fille","a filha, a menina"],["les enfants","os filhos, as crianças"],["le grand-père","o avô"],["la grand-mère","a avó"]]},{"h":"Apresentando","items":[["Voici…","Este é, estes são…"],["C'est…","É…"],["Ce sont…","São…"],["jeune","jovem"]]}],"pron":[{"h":"fils e fille","p":"<b>fils</b> soa “fiss” (o l é mudo, o s aparece). <b>fille</b> soa “fiy”.","w":["fils","fille"]},{"h":"sœur","p":"O <b>œu</b> é um “ê” com os lábios arredondados, parecido com o “ö” alemão.","w":["sœur","frère"]},{"h":"le, la, les","p":"<b>le</b> soa “lë” (vogal neutra), <b>les</b> soa “lê”. É essa diferença que mostra o plural na fala.","w":["le père","les parents","les enfants"]}],"mc":[{"q":"Como se chama a mãe da Claire?","o":["Julie","Anne","Paul"],"a":1,"e":"ma mère s'appelle Anne."},{"q":"Qual é a nacionalidade do marido da Julie?","o":["français","italien","brésilien"],"a":1,"e":"Son mari est italien."},{"q":"Como dizer “o marido dela”?","o":["sa mari","son mari"],"a":1,"e":"mari é masculino: son."},{"q":"Como dizer “Não tenho irmão”?","o":["Je n'ai pas un frère.","Je n'ai pas de frère."],"a":1,"e":"Depois da negação, un vira de."}],"gaps":[{"s":"C'est ___ père.","a":["mon"],"h":"Este é meu pai."},{"s":"C'est ___ mère.","a":["ma"],"h":"Esta é minha mãe."},{"s":"Voici ___ parents.","a":["mes"],"h":"Estes são meus pais."},{"s":"Ils ont ___ enfants.","a":["des"],"h":"Eles têm filhos."},{"s":"Je n'ai pas ___ sœur.","a":["de"],"h":"Não tenho irmã."}],"order":[{"t":["Mon","père","s'appelle","Paul."],"h":"Meu pai se chama Paul."},{"t":["Ils","ont","deux","enfants."],"h":"Eles têm dois filhos."},{"t":["Je","n'ai","pas","de","frère."],"h":"Não tenho irmão."}],"dict":[{"t":"C'est ma sœur."},{"t":"Voici mes parents."},{"t":"Son mari est italien."},{"t":"le fils"},{"t":"la fille"}],"shadow":["C'est ta famille ?","Voici mes parents.","Son mari est italien.","Je n'ai pas de frère."],"write":{"task":"Apresente 3 pessoas da sua família em francês: quem são, o nome e a idade.","ph":"Voici ma mère. Elle s'appelle …"},"cards":[["Este é meu pai.","C'est mon père."],["Esta é minha mãe.","C'est ma mère."],["Estes são meus pais.","Voici mes parents."],["O marido dela é italiano.","Son mari est italien."],["Eles têm dois filhos.","Ils ont deux enfants."],["Você tem irmãos?","Tu as des frères et sœurs ?"],["Não tenho irmã.","Je n'ai pas de sœur."],["O filho deles tem seis anos.","Leur fils a six ans."]]},{"title":"Les objets","goal":"Nomear objetos, perguntar o que é algo, o que tem num lugar e quanto custa.","speakers":{"Lucas":"m","Le vendeur":"m","Claire":"f"},"setting":"Lucas e Claire passeiam numa feira de antiguidades em Lyon.","lines":[["Lucas","Bonjour, qu'est-ce que c'est ?","Bom dia, o que é isso?"],["Le vendeur","C'est une vieille radio. Elle marche très bien !","É um rádio antigo. Funciona muito bem!"],["Lucas","Elle coûte combien ?","Quanto custa?"],["Le vendeur","Quinze euros.","Quinze euros."],["Claire","Il y a des livres aussi ?","Tem livros também?"],["Le vendeur","Oui, il y a des livres et des cartes postales, là-bas.","Tem, sim: livros e cartões-postais, ali."],["Claire","C'est combien, les cartes postales ?","Quanto custam os cartões-postais?"],["Le vendeur","Un euro la carte.","Um euro cada."],["Lucas","Super ! Une radio et deux cartes, s'il vous plaît.","Ótimo! Um rádio e dois cartões, por favor."]],"grammar":[{"h":"Todo substantivo tem gênero","p":["Em francês, toda coisa é masculina ou feminina, e nem sempre bate com o português: <b>la radio</b> (o rádio), <b>la voiture</b> (o carro), <b>le lait</b> (o leite)."],"ex":[["un livre","um livro"],["une radio","um rádio"],["une voiture","um carro"]],"tip":"Aprenda cada palavra junto com o artigo: não “livre”, mas <b>un livre</b>."},{"h":"Plural: o s é mudo","p":["Em geral, o plural ganha <b>-s</b>, mas ele não é pronunciado: <b>livre</b> e <b>livres</b> soam iguais. Na fala, quem mostra o plural é o artigo: <b>le livre</b> (“lë”) e <b>les livres</b> (“lê”)."],"ex":[["le livre, les livres","o livro, os livros"],["une carte, des cartes","um cartão, cartões"]]},{"h":"Il y a: tem, há","p":["<b>Il y a</b> diz que algo existe num lugar: <b>Il y a des livres.</b> Negativa: <b>Il n'y a pas de</b>… Pergunta: <b>Il y a… ?</b> ou <b>Est-ce qu'il y a… ?</b>"],"ex":[["Il y a un parc ici.","Tem um parque aqui."],["Il n'y a pas de stylo.","Não tem caneta."]],"tip":"Para “tem” no sentido de “existe”, nunca use <b>il a</b>: isso quer dizer “ele tem”."},{"h":"C'est e o preço","p":["<b>Qu'est-ce que c'est ?</b> (O que é isso?) — <b>C'est une radio.</b> Para o preço: <b>Ça coûte combien ?</b> ou <b>C'est combien ?</b>"],"ex":[["C'est combien ?","Quanto é?"],["Ça coûte quinze euros.","Custa quinze euros."]]}],"vocab":[{"h":"Objetos","items":[["le livre","o livro"],["le sac","a bolsa"],["la clé","a chave"],["le téléphone","o telefone"],["le portefeuille","a carteira"],["la radio","o rádio"],["la carte postale","o cartão-postal"],["le stylo","a caneta"],["la montre","o relógio de pulso"],["les lunettes","os óculos"]]},{"h":"Comprando","items":[["Ça coûte combien ?","quanto custa?"],["C'est combien ?","quanto é?"],["un euro","um euro"],["s'il vous plaît","por favor"],["là-bas","ali, lá"],["cher","caro"],["vieux, vieille","velho, velha, antigo"]]}],"pron":[{"h":"le ou les?","p":"<b>le</b> soa “lë”, com a boca relaxada. <b>les</b> soa “lê”, com sorriso. Treine em pares.","w":["le livre","les livres"]},{"h":"s'il vous plaît","p":"Na fala, vira quase uma palavra: “sil-vu-PLÉ”.","w":["s'il vous plaît"]},{"h":"euro","p":"O <b>eu</b> soa “ö”, com lábios arredondados: “ö-RÔ”.","w":["un euro","quinze euros"]}],"mc":[{"q":"Quanto custa o rádio?","o":["5 €","15 €","50 €"],"a":1,"e":"Quinze euros."},{"q":"Quanto custa cada cartão-postal?","o":["1 €","2 €","10 €"],"a":0,"e":"Un euro la carte."},{"q":"“Rádio” em francês é…","o":["le radio","la radio"],"a":1,"e":"Em francês, radio é feminino."},{"q":"Como perguntar “Tem livros?”","o":["Il y a des livres ?","Il a des livres ?"],"a":0,"e":"Il y a = tem, existe."}],"gaps":[{"s":"___ y a des livres ?","a":["Il"],"h":"Tem livros?"},{"s":"C'est ___ radio.","a":["une"],"h":"É um rádio."},{"s":"Ça coûte ___ ?","a":["combien"],"h":"Quanto custa?"},{"s":"Il n'y a pas ___ stylo.","a":["de"],"h":"Não tem caneta."},{"s":"Deux cartes, s'il vous ___.","a":["plaît"],"h":"Dois cartões, por favor."}],"order":[{"t":["Qu'est-ce","que","c'est ?"],"h":"O que é isso?"},{"t":["Il","y","a","des","livres."],"h":"Tem livros."},{"t":["Ça","coûte","combien ?"],"h":"Quanto custa?"}],"dict":[{"t":"Qu'est-ce que c'est ?"},{"t":"Il y a des livres."},{"t":"Ça coûte combien ?"},{"t":"s'il vous plaît"},{"t":"la montre"}],"shadow":["Qu'est-ce que c'est ?","Elle coûte combien ?","Il y a des livres aussi ?","Une radio et deux cartes, s'il vous plaît."],"write":{"task":"Descreva 4 objetos perto de você agora, usando c'est e il y a.","ph":"Il y a un livre. C'est un livre de …"},"cards":[["O que é isso?","Qu'est-ce que c'est ?"],["É um rádio.","C'est une radio."],["Quanto custa?","Ça coûte combien ?"],["Tem livros?","Il y a des livres ?"],["Não tem caneta.","Il n'y a pas de stylo."],["Por favor.","S'il vous plaît."],["Ali.","Là-bas."],["Dois cartões-postais.","Deux cartes postales."]]},{"title":"Ma journée","goal":"Contar a sua rotina, dizer as horas e perguntar sobre o dia de outra pessoa.","speakers":{"Claire":"f","Lucas":"m"},"setting":"No café antes da aula, Claire repara que o Lucas está com sono.","lines":[["Claire","Tu as l'air fatigué !","Você parece cansado!"],["Lucas","Je me lève à six heures tous les jours.","Eu me levanto às seis todos os dias."],["Claire","Pourquoi si tôt ?","Por que tão cedo?"],["Lucas","Je travaille le matin et j'étudie l'après-midi.","Trabalho de manhã e estudo à tarde."],["Claire","Tu déjeunes à quelle heure ?","A que horas você almoça?"],["Lucas","À midi et demi. Et toi ?","Ao meio-dia e meia. E você?"],["Claire","Moi, je ne travaille pas. J'étudie le matin et je regarde des séries le soir.","Eu não trabalho. Estudo de manhã e vejo séries à noite."],["Lucas","Tu te couches tard ?","Você vai dormir tarde?"],["Claire","Oui, vers minuit !","Vou, lá pela meia-noite!"]],"grammar":[{"h":"Verbos em -er no presente","p":["A maioria dos verbos franceses termina em <b>-er</b> e segue o mesmo modelo. <b>parler</b>: je <b>parle</b>, tu <b>parles</b>, il <b>parle</b>, nous <b>parlons</b>, vous <b>parlez</b>, ils <b>parlent</b>."],"ex":[["Je travaille le matin.","Trabalho de manhã."],["Nous étudions le français.","Estudamos francês."],["Ils regardent la télé.","Eles veem TV."]],"tip":"<b>parle</b>, <b>parles</b> e <b>parlent</b> soam iguais: “parl”. Na fala, só <b>nous</b> e <b>vous</b> mudam o som."},{"h":"Horas","p":["<b>Il est quelle heure ?</b> — <b>Il est huit heures.</b> Para dizer a que horas: <b>à</b> + hora: <b>à six heures</b>. <b>et quart</b> (e quinze), <b>et demie</b> (e meia), <b>moins le quart</b> (quinze para)."],"ex":[["à huit heures et demie","às oito e meia"],["à neuf heures moins le quart","às quinze para as nove"],["à midi, à minuit","ao meio-dia, à meia-noite"]],"tip":"Com <b>midi</b> e <b>minuit</b>, escreve-se <b>et demi</b>, sem e no final."},{"h":"Je me lève, je me couche","p":["Alguns verbos de rotina vêm com <b>me</b>, <b>te</b>, <b>se</b>, como “eu me levanto” em português: <b>je me lève</b>, <b>tu te lèves</b>, <b>il se lève</b>. Por enquanto, guarde as formas com je e tu."],"ex":[["Je me lève à sept heures.","Eu me levanto às sete."],["Tu te couches à quelle heure ?","A que horas você vai dormir?"]]},{"h":"Partes do dia","p":["<b>le matin</b> (de manhã), <b>l'après-midi</b> (à tarde), <b>le soir</b> (à noite), <b>la nuit</b> (de madrugada). Sem preposição: <b>je travaille le matin</b>."],"ex":[["tous les jours","todos os dias"],["le soir","à noite"]]}],"vocab":[{"h":"Rotina","items":[["se lever","levantar-se"],["prendre le petit-déjeuner","tomar café da manhã"],["travailler","trabalhar"],["déjeuner","almoçar"],["étudier","estudar"],["rentrer à la maison","voltar para casa"],["dîner","jantar"],["se coucher","ir dormir"]]},{"h":"Horas","items":[["Il est quelle heure ?","que horas são?"],["huit heures","oito horas"],["huit heures et quart","oito e quinze"],["huit heures et demie","oito e meia"],["neuf heures moins le quart","quinze para as nove"],["midi","meio-dia"],["minuit","meia-noite"],["tôt, tard","cedo, tarde"]]}],"pron":[{"h":"O -ent mudo","p":"No verbo, <b>-ent</b> é mudo: <b>ils travaillent</b> soa igual a <b>il travaille</b>.","w":["il travaille","ils travaillent"]},{"h":"heure se liga ao número","p":"O h de <b>heure</b> é mudo, então o número se liga: <b>six_heures</b> soa “sizör”, <b>deux_heures</b> soa “dözör”.","w":["six heures","deux heures","neuf heures"]},{"h":"matin e soir","p":"<b>matin</b> termina num “ã” nasal: “matã”. <b>soir</b> soa “suar”.","w":["le matin","le soir"]}],"mc":[{"q":"A que horas o Lucas se levanta?","o":["6h","7h","12h"],"a":0,"e":"Je me lève à six heures."},{"q":"A Claire trabalha?","o":["Sim","Não"],"a":1,"e":"Je ne travaille pas."},{"q":"Como soa “ils travaillent”?","o":["Igual a “il travaille”","Com o -ent pronunciado"],"a":0,"e":"O -ent dos verbos é mudo."},{"q":"Como dizer “à tarde”?","o":["l'après-midi","le soir"],"a":0,"e":"le soir é à noite."}],"gaps":[{"s":"Je me ___ à six heures.","a":["lève"],"h":"Eu me levanto às seis."},{"s":"Tu déjeunes à quelle ___ ?","a":["heure"],"h":"A que horas você almoça?"},{"s":"Nous ___ français.","a":["parlons"],"h":"Nós falamos francês."},{"s":"Je travaille ___ matin.","a":["le"],"h":"Trabalho de manhã."},{"s":"Vous ___ le soir ?","a":["étudiez"],"h":"Vocês estudam à noite?"}],"order":[{"t":["Je","travaille","le","matin."],"h":"Trabalho de manhã."},{"t":["Il","est","huit","heures."],"h":"São oito horas."},{"t":["Tu","te","couches","tard ?"],"h":"Você vai dormir tarde?"}],"dict":[{"t":"Je me lève à six heures."},{"t":"Il est midi."},{"t":"Nous parlons français."},{"t":"le soir"},{"t":"Tu déjeunes à quelle heure ?"}],"shadow":["Je me lève à six heures tous les jours.","Tu déjeunes à quelle heure ?","À midi et demi. Et toi ?","Tu te couches tard ?"],"write":{"task":"Descreva sua rotina em francês, com horários: a que horas se levanta, trabalha ou estuda, almoça e vai dormir.","ph":"Je me lève à …"},"cards":[["Eu me levanto às seis.","Je me lève à six heures."],["Que horas são?","Il est quelle heure ?"],["São oito horas.","Il est huit heures."],["Trabalho de manhã.","Je travaille le matin."],["A que horas você almoça?","Tu déjeunes à quelle heure ?"],["Vou dormir à meia-noite.","Je me couche à minuit."],["Nós falamos francês.","Nous parlons français."],["Todos os dias.","Tous les jours."]]},{"title":"Les métiers","goal":"Falar da sua profissão e da de outras pessoas, e de onde trabalham.","speakers":{"Lucas":"m","Claire":"f"},"setting":"Lucas e Claire conversam sobre trabalho e família.","lines":[["Lucas","Qu'est-ce que tu fais dans la vie ?","O que você faz da vida?"],["Claire","Je suis infirmière. Je travaille dans un hôpital.","Sou enfermeira. Trabalho num hospital."],["Lucas","Tu travailles la nuit ?","Você trabalha de madrugada?"],["Claire","Oui, parfois. Et toi, tu fais quoi ?","Às vezes. E você, faz o quê?"],["Lucas","Je suis développeur. Je travaille à la maison.","Sou desenvolvedor. Trabalho em casa."],["Claire","Et ta sœur ?","E a sua irmã?"],["Lucas","Elle est avocate. Son bureau est à São Paulo.","Ela é advogada. O escritório dela fica em São Paulo."],["Claire","Et ton frère ?","E o seu irmão?"],["Lucas","Il est encore étudiant. Il fait des études de médecine.","Ainda é estudante. Estuda medicina."]],"grammar":[{"h":"O verbo faire","p":["<b>je fais</b>, <b>tu fais</b>, <b>il fait</b>, <b>nous faisons</b>, <b>vous faites</b>, <b>ils font</b>. É o “fazer”."],"ex":[["Qu'est-ce que tu fais dans la vie ?","O que você faz da vida?"],["Vous faites quoi ?","O que vocês fazem?"]],"tip":"<b>vous faites</b> é irregular: “vous faisez” não existe."},{"h":"Profissão sem artigo","p":["Depois de <b>être</b>, a profissão vem sem artigo, como em português: <b>Je suis infirmière.</b> Mas com <b>c'est</b> o artigo volta: <b>C'est un médecin.</b>"],"ex":[["Il est médecin.","Ele é médico."],["C'est une avocate.","É uma advogada."]],"tip":"É o contrário do inglês: em francês, não diga “Je suis un médecin”."},{"h":"Profissões no feminino","p":["Muitas seguem modelos: <b>-ier</b> → <b>-ière</b> (infirmier, infirmière), <b>-eur</b> → <b>-euse</b> (serveur, serveuse), <b>-t</b> → <b>-te</b> (avocat, avocate). Algumas só mudam o artigo: <b>un</b> ou <b>une</b> médecin."],"ex":[["un serveur, une serveuse","um garçom, uma garçonete"],["un avocat, une avocate","um advogado, uma advogada"]]}],"vocab":[{"h":"Profissões","items":[["médecin","médico, médica"],["infirmier, infirmière","enfermeiro, enfermeira"],["avocat, avocate","advogado, advogada"],["professeur, professeure","professor, professora"],["ingénieur, ingénieure","engenheiro, engenheira"],["développeur, développeuse","desenvolvedor, desenvolvedora"],["serveur, serveuse","garçom, garçonete"],["vendeur, vendeuse","vendedor, vendedora"]]},{"h":"Lugares de trabalho","items":[["un hôpital","um hospital"],["un bureau","um escritório"],["une école","uma escola"],["un restaurant","um restaurante"],["un magasin","uma loja"],["à la maison","em casa"],["parfois","às vezes"],["encore","ainda"]]}],"pron":[{"h":"As formas de faire","p":"<b>fais</b> e <b>fait</b> soam “fé”. <b>faisons</b> soa “fëzõ” e <b>faites</b> soa “fét”. <b>font</b> soa “fõ”.","w":["je fais","nous faisons","vous faites","ils font"]},{"h":"O h mudo de hôpital","p":"O h de <b>hôpital</b> é mudo, então se liga: <b>un_hôpital</b> soa “ënopital”.","w":["un hôpital"]},{"h":"-ier e -ière","p":"<b>infirmier</b> termina em “iê”; <b>infirmière</b> termina em “iér”, com o r aparecendo.","w":["infirmier","infirmière"]}],"mc":[{"q":"Qual é a profissão da Claire?","o":["médecin","infirmière","avocate"],"a":1,"e":"Je suis infirmière."},{"q":"Onde o Lucas trabalha?","o":["Num escritório","Em casa","Num hospital"],"a":1,"e":"Je travaille à la maison."},{"q":"Como dizer “Sou médico”?","o":["Je suis un médecin.","Je suis médecin."],"a":1,"e":"Depois de être, sem artigo."},{"q":"Como dizer “vocês fazem”?","o":["vous faisez","vous faites"],"a":1,"e":"faites é irregular."}],"gaps":[{"s":"Qu'est-ce que tu ___ dans la vie ?","a":["fais"],"h":"O que você faz da vida?"},{"s":"Elle est ___.","a":["avocate"],"h":"Ela é advogada."},{"s":"Vous ___ quoi ?","a":["faites"],"h":"O que vocês fazem?"},{"s":"Je travaille dans un ___.","a":["hôpital"],"h":"Trabalho num hospital."},{"s":"Ils ___ des études de médecine.","a":["font"],"h":"Eles estudam medicina."}],"order":[{"t":["Je","suis","infirmière."],"h":"Sou enfermeira."},{"t":["Il","travaille","dans","un","bureau."],"h":"Ele trabalha num escritório."},{"t":["Qu'est-ce","que","vous","faites ?"],"h":"O que vocês fazem?"}],"dict":[{"t":"Je suis développeur."},{"t":"Elle est avocate."},{"t":"Qu'est-ce que tu fais ?"},{"t":"un hôpital"},{"t":"vous faites"}],"shadow":["Qu'est-ce que tu fais dans la vie ?","Je suis infirmière. Je travaille dans un hôpital.","Je suis développeur.","Il est encore étudiant."],"write":{"task":"Diga a sua profissão e a de 2 pessoas da sua família, e onde vocês trabalham.","ph":"Je suis … Je travaille …"},"cards":[["O que você faz da vida?","Qu'est-ce que tu fais dans la vie ?"],["Sou enfermeira.","Je suis infirmière."],["Ele é médico.","Il est médecin."],["Ela é advogada.","Elle est avocate."],["Trabalho em casa.","Je travaille à la maison."],["O que vocês fazem?","Vous faites quoi ?"],["Ele trabalha num escritório.","Il travaille dans un bureau."],["Ela é garçonete.","Elle est serveuse."]]},{"title":"Loisirs","goal":"Dizer do que você gosta, o que pratica e em que dias.","speakers":{"Lucas":"m","Claire":"f"},"setting":"Lucas e Claire conversam sobre o fim de semana.","lines":[["Lucas","Qu'est-ce que tu aimes faire le week-end ?","O que você gosta de fazer no fim de semana?"],["Claire","J'adore lire. Et je fais du vélo le dimanche.","Adoro ler. E ando de bicicleta aos domingos."],["Lucas","Tu aimes le sport ?","Você gosta de esporte?"],["Claire","Oui, mais je déteste courir ! Et toi ?","Gosto, mas detesto correr! E você?"],["Lucas","Moi, je joue au foot avec des amis le samedi.","Eu jogo futebol com amigos aos sábados."],["Claire","Tu joues d'un instrument ?","Você toca algum instrumento?"],["Lucas","Oui, je joue de la guitare. Mais pas très bien !","Toco violão. Mas não muito bem!"],["Claire","On fait de la musique ensemble un jour ?","Vamos tocar juntos um dia?"],["Lucas","Avec plaisir !","Com prazer!"]],"grammar":[{"h":"aimer, adorer, détester + infinitivo","p":["Depois desses verbos, o outro verbo vem no infinitivo e <b>sem preposição</b>: <b>J'aime lire</b>, <b>Je déteste courir</b>."],"ex":[["J'adore voyager.","Adoro viajar."],["Tu aimes danser ?","Você gosta de dançar?"]],"tip":"Não existe o “de” do português: “J'aime de lire” está errado."},{"h":"aimer + le, la, les","p":["Para gostos em geral, o francês usa o artigo definido: <b>J'aime le sport</b>, <b>J'aime la musique</b>, <b>J'aime les films</b>."],"ex":[["Je déteste le café.","Detesto café."],["Elle adore les chats.","Ela adora gatos."]]},{"h":"jouer à, jouer de, faire de","p":["Esportes e jogos: <b>jouer à</b> → <b>je joue au foot</b>, <b>aux cartes</b>. Instrumentos: <b>jouer de</b> → <b>je joue de la guitare</b>, <b>du piano</b>. Muitas atividades usam <b>faire de</b>: <b>faire du vélo</b>, <b>faire de la natation</b>."],"ex":[["Il joue au tennis.","Ele joga tênis."],["Je fais de la natation.","Faço natação."]]},{"h":"le samedi: aos sábados","p":["Com artigo, o dia indica hábito: <b>le samedi</b> = todo sábado. Sem artigo, um dia específico: <b>samedi</b> = este sábado."],"ex":[["Je joue au foot le samedi.","Jogo futebol aos sábados."],["On se voit samedi ?","A gente se vê no sábado?"]]}],"vocab":[{"h":"Atividades","items":[["lire","ler"],["courir","correr"],["nager","nadar"],["cuisiner","cozinhar"],["danser","dançar"],["voyager","viajar"],["regarder la télé","ver TV"],["écouter de la musique","ouvir música"],["faire du vélo","andar de bicicleta"],["jouer au foot","jogar futebol"],["jouer de la guitare","tocar violão"]]},{"h":"Expressões","items":[["le week-end","o fim de semana"],["ensemble","juntos"],["avec des amis","com amigos"],["Avec plaisir !","com prazer!"],["pas très bien","não muito bem"]]}],"pron":[{"h":"aime, aimes, aiment","p":"As três soam iguais: “ém”.","w":["j'aime","tu aimes","ils aiment"]},{"h":"foot e week-end","p":"Palavras emprestadas do inglês, com sotaque francês: <b>foot</b> soa “fut”, <b>week-end</b> soa “uikénd”.","w":["le foot","le week-end"]},{"h":"du e de","p":"<b>du</b> tem o u francês (lábios em bico); <b>de</b> tem a vogal neutra “ë”.","w":["du vélo","de la guitare"]}],"mc":[{"q":"O que a Claire detesta?","o":["lire","courir","faire du vélo"],"a":1,"e":"je déteste courir !"},{"q":"Que instrumento o Lucas toca?","o":["le piano","la guitare"],"a":1,"e":"je joue de la guitare."},{"q":"Como dizer “Gosto de ler”?","o":["J'aime de lire.","J'aime lire."],"a":1,"e":"Sem preposição."},{"q":"Como dizer “Jogo futebol”?","o":["Je joue du foot.","Je joue au foot."],"a":1,"e":"Esportes usam jouer à."}],"gaps":[{"s":"J'adore ___.","a":["lire"],"h":"Adoro ler."},{"s":"Je joue ___ foot.","a":["au"],"h":"Jogo futebol."},{"s":"Je joue ___ la guitare.","a":["de"],"h":"Toco violão."},{"s":"Je fais ___ vélo.","a":["du"],"h":"Ando de bicicleta."},{"s":"Elle ___ courir.","a":["déteste"],"h":"Ela detesta correr."}],"order":[{"t":["J'aime","écouter","de","la","musique."],"h":"Gosto de ouvir música."},{"t":["Je","fais","du","vélo","le","dimanche."],"h":"Ando de bicicleta aos domingos."},{"t":["Tu","joues","d'un","instrument ?"],"h":"Você toca algum instrumento?"}],"dict":[{"t":"J'adore lire."},{"t":"Je joue au foot."},{"t":"Je déteste courir."},{"t":"le week-end"},{"t":"Avec plaisir !"}],"shadow":["Qu'est-ce que tu aimes faire le week-end ?","J'adore lire.","Je joue au foot avec des amis le samedi.","Avec plaisir !"],"write":{"task":"Conte do que você gosta e não gosta de fazer no tempo livre, e em que dias faz cada coisa.","ph":"J'aime … Le samedi, je …"},"cards":[["Adoro ler.","J'adore lire."],["Detesto correr.","Je déteste courir."],["Jogo futebol aos sábados.","Je joue au foot le samedi."],["Toco violão.","Je joue de la guitare."],["Ando de bicicleta.","Je fais du vélo."],["O que você gosta de fazer?","Qu'est-ce que tu aimes faire ?"],["Gosto de música.","J'aime la musique."],["Com prazer!","Avec plaisir !"]]},{"title":"À table","goal":"Pedir comida e bebida num café ou restaurante com educação.","speakers":{"Le serveur":"m","Claire":"f","Lucas":"m"},"setting":"Claire e Lucas sentam num café no centro de Lyon.","lines":[["Le serveur","Bonjour, vous désirez ?","Bom dia, o que vão querer?"],["Claire","Bonjour. Je voudrais un café, s'il vous plaît.","Bom dia. Eu queria um café, por favor."],["Le serveur","Avec du lait ?","Com leite?"],["Claire","Non, merci. Vous avez des croissants ?","Não, obrigada. Vocês têm croissants?"],["Le serveur","Oui, et nous avons aussi de la tarte aux pommes.","Temos, e temos também torta de maçã."],["Claire","Je vais prendre un croissant.","Vou querer um croissant."],["Lucas","Et pour moi, un jus d'orange et un sandwich au fromage.","E para mim, um suco de laranja e um sanduíche de queijo."],["Le serveur","Très bien. Je vous apporte ça.","Muito bem. Já trago."],["Lucas","L'addition, s'il vous plaît !","A conta, por favor!"]],"grammar":[{"h":"Partitivos: du, de la, de l', des","p":["Para uma quantidade que não se conta, o francês usa <b>du</b> (masculino), <b>de la</b> (feminino), <b>de l'</b> (antes de vogal) e <b>des</b> (plural). Em português muitas vezes não dizemos nada."],"ex":[["Vous voulez du lait ?","Quer leite?"],["Je mange de la tarte.","Estou comendo torta."],["Je bois de l'eau.","Bebo água."]],"tip":"“Je voudrais lait” está errado: o francês sempre exige um artigo antes do substantivo."},{"h":"Na negativa, tudo vira de","p":["Depois de uma negação, <b>du</b>, <b>de la</b> e <b>des</b> viram <b>de</b> (ou <b>d'</b>): <b>Je ne veux pas de lait.</b> <b>Pas de sucre, merci.</b>"],"ex":[["Il n'y a pas de pain.","Não tem pão."],["Pas de sucre, merci.","Sem açúcar, obrigado."]]},{"h":"Pedindo com educação","p":["<b>Je voudrais…</b> (eu queria), <b>Je vais prendre…</b> (vou querer) e <b>Pour moi…</b> (para mim) são as formas naturais de pedir."],"ex":[["Je voudrais un thé.","Eu queria um chá."],["Pour moi, une salade.","Para mim, uma salada."]],"tip":"<b>Je veux</b> (eu quero) soa seco e mal-educado num restaurante."}],"vocab":[{"h":"Comida e bebida","items":[["le café","o café"],["le thé","o chá"],["le lait","o leite"],["l'eau","a água"],["le jus d'orange","o suco de laranja"],["le pain","o pão"],["le fromage","o queijo"],["le croissant","o croissant"],["la tarte aux pommes","a torta de maçã"],["le sucre","o açúcar"]]},{"h":"No café","items":[["Je voudrais…","eu queria…"],["Je vais prendre…","vou querer…"],["Pour moi…","para mim…"],["L'addition, s'il vous plaît.","a conta, por favor"],["la carte","o cardápio"],["Vous désirez ?","o que deseja?"]]}],"pron":[{"h":"voudrais","p":"Soa “vu-DRÉ”: o s final é mudo.","w":["je voudrais"]},{"h":"croissant","p":"Em francês: “krua-SÃ”, com o r da garganta e o final nasal.","w":["un croissant"]},{"h":"de l'eau","p":"<b>l'eau</b> soa “lô”, igual a <b>lo</b>.","w":["de l'eau"]}],"mc":[{"q":"O que a Claire pede para beber?","o":["un thé","un café","un jus d'orange"],"a":1,"e":"Je voudrais un café."},{"q":"O que o Lucas pede para comer?","o":["un croissant","un sandwich au fromage","de la tarte"],"a":1,"e":"un sandwich au fromage."},{"q":"Como perguntar “Quer leite?”","o":["Vous voulez lait ?","Vous voulez du lait ?"],"a":1,"e":"Precisa do partitivo du."},{"q":"Como dizer “Sem açúcar”?","o":["Pas du sucre.","Pas de sucre."],"a":1,"e":"Depois da negação, tudo vira de."}],"gaps":[{"s":"Je ___ un café.","a":["voudrais"],"h":"Eu queria um café."},{"s":"Avec ___ lait ?","a":["du"],"h":"Com leite?"},{"s":"Je voudrais ___ l'eau.","a":["de"],"h":"Eu queria água."},{"s":"Vous avez ___ croissants ?","a":["des"],"h":"Vocês têm croissants?"},{"s":"L'___, s'il vous plaît.","a":["addition"],"h":"A conta, por favor."}],"order":[{"t":["Je","voudrais","un","café."],"h":"Eu queria um café."},{"t":["Vous","avez","des","croissants ?"],"h":"Vocês têm croissants?"},{"t":["L'addition,","s'il","vous","plaît."],"h":"A conta, por favor."}],"dict":[{"t":"Je voudrais un café."},{"t":"Avec du lait ?"},{"t":"L'addition, s'il vous plaît."},{"t":"un jus d'orange"},{"t":"de l'eau"}],"shadow":["Je voudrais un café, s'il vous plaît.","Vous avez des croissants ?","Pour moi, un jus d'orange.","L'addition, s'il vous plaît !"],"write":{"task":"Escreva o seu pedido num café francês: bebida, comida e a conta.","ph":"Bonjour. Je voudrais …"},"cards":[["Eu queria um café.","Je voudrais un café."],["Com leite?","Avec du lait ?"],["Sem açúcar, obrigado.","Pas de sucre, merci."],["Vocês têm croissants?","Vous avez des croissants ?"],["Para mim, um suco de laranja.","Pour moi, un jus d'orange."],["A conta, por favor.","L'addition, s'il vous plaît."],["Eu queria água.","Je voudrais de l'eau."],["O cardápio, por favor.","La carte, s'il vous plaît."]]},{"title":"En ville","goal":"Perguntar onde fica um lugar, entender direções e dizer aonde você vai.","speakers":{"Lucas":"m","Sophie":"f"},"setting":"Lucas procura uma farmácia e pede ajuda a uma moradora, a Sophie.","lines":[["Lucas","Pardon, madame, il y a une pharmacie près d'ici ?","Com licença, senhora, tem uma farmácia aqui perto?"],["Sophie","Oui, dans la rue Victor-Hugo.","Tem, na rua Victor-Hugo."],["Lucas","Comment je vais là-bas ?","Como eu chego lá?"],["Sophie","Allez tout droit, puis tournez à gauche après la banque.","Siga reto e depois vire à esquerda depois do banco."],["Lucas","À gauche après la banque, d'accord.","À esquerda depois do banco, certo."],["Sophie","La pharmacie est à côté de la boulangerie, en face du parc.","A farmácia fica ao lado da padaria, em frente ao parque."],["Lucas","C'est loin ?","É longe?"],["Sophie","Non, c'est à cinq minutes à pied.","Não, fica a cinco minutos a pé."],["Lucas","Merci beaucoup !","Muito obrigado!"],["Sophie","Je vous en prie.","De nada."]],"grammar":[{"h":"O verbo aller","p":["<b>je vais</b>, <b>tu vas</b>, <b>il va</b>, <b>nous allons</b>, <b>vous allez</b>, <b>ils vont</b>. É o “ir”."],"ex":[["Je vais à la gare.","Vou à estação."],["Nous allons au musée.","Vamos ao museu."]]},{"h":"à + le = au, de + le = du","p":["<b>à</b> e <b>de</b> se juntam com <b>le</b> e <b>les</b>: à + le = <b>au</b>, à + les = <b>aux</b>, de + le = <b>du</b>, de + les = <b>des</b>. Com <b>la</b> e <b>l'</b> não muda nada."],"ex":[["Je vais au parc.","Vou ao parque."],["Je vais à la banque.","Vou ao banco."],["en face du parc","em frente ao parque"]],"tip":"“à le parc” e “de le parc” nunca existem em francês."},{"h":"Dando direções","p":["As direções usam o imperativo com <b>vous</b>: <b>Allez tout droit</b> (siga reto), <b>Tournez à gauche</b> (vire à esquerda), <b>Tournez à droite</b> (vire à direita), <b>Prenez la deuxième rue</b> (pegue a segunda rua)."],"ex":[["Tournez à droite après le parc.","Vire à direita depois do parque."]]},{"h":"Onde fica","p":["<b>à côté de</b> (ao lado de), <b>en face de</b> (em frente a), <b>entre</b> (entre), <b>près de</b> (perto de), <b>loin de</b> (longe de)."],"ex":[["à côté de la boulangerie","ao lado da padaria"],["près d'ici","aqui perto"]]}],"vocab":[{"h":"Lugares","items":[["la banque","o banco"],["la pharmacie","a farmácia"],["la boulangerie","a padaria"],["le supermarché","o supermercado"],["le parc","o parque"],["la gare","a estação de trem"],["l'arrêt de bus","o ponto de ônibus"],["le musée","o museu"],["la rue","a rua"]]},{"h":"Direções","items":[["tout droit","reto"],["à gauche","à esquerda"],["à droite","à direita"],["à côté de","ao lado de"],["en face de","em frente a"],["près de","perto de"],["loin","longe"],["à pied","a pé"],["Je vous en prie.","de nada (formal)"]]}],"pron":[{"h":"gauche e droite","p":"<b>gauche</b> soa “gôch”. <b>droite</b> soa “druat”, com o t aparecendo.","w":["à gauche","à droite"]},{"h":"tout droit","p":"Soa “tu drua”: os dois t finais são mudos.","w":["tout droit"]},{"h":"boulangerie","p":"O e do meio quase some: “bu-lãj-RI”.","w":["la boulangerie"]}],"mc":[{"q":"Onde fica a farmácia?","o":["Ao lado da padaria","Ao lado do banco","Entre dois parques"],"a":0,"e":"à côté de la boulangerie, en face du parc."},{"q":"A farmácia é longe?","o":["Sim, muito longe","Não, a cinco minutos a pé"],"a":1,"e":"c'est à cinq minutes à pied."},{"q":"Como dizer “Vou ao parque”?","o":["Je vais à le parc.","Je vais au parc."],"a":1,"e":"à + le = au."},{"q":"Como dizer “em frente ao parque”?","o":["en face du parc","en face de le parc"],"a":0,"e":"de + le = du."}],"gaps":[{"s":"Je ___ à la gare.","a":["vais"],"h":"Vou à estação."},{"s":"Tournez à ___.","a":["gauche"],"h":"Vire à esquerda."},{"s":"Allez tout ___.","a":["droit"],"h":"Siga reto."},{"s":"C'est à côté ___ la banque.","a":["de"],"h":"Fica ao lado do banco."},{"s":"Nous ___ au musée.","a":["allons"],"h":"Vamos ao museu."}],"order":[{"t":["Il","y","a","une","pharmacie","près","d'ici ?"],"h":"Tem uma farmácia aqui perto?"},{"t":["Tournez","à","droite","après","le","parc."],"h":"Vire à direita depois do parque."},{"t":["Je","vais","au","supermarché."],"h":"Vou ao supermercado."}],"dict":[{"t":"Allez tout droit."},{"t":"Tournez à gauche."},{"t":"C'est loin ?"},{"t":"en face du parc"},{"t":"Je vais au supermarché."}],"shadow":["Il y a une pharmacie près d'ici ?","Allez tout droit, puis tournez à gauche.","C'est loin ?","Je vous en prie."],"write":{"task":"Descreva o seu bairro em francês: o que tem perto da sua casa e onde fica cada lugar.","ph":"Il y a une boulangerie près de chez moi. Elle est à côté de …"},"cards":[["Tem uma farmácia aqui perto?","Il y a une pharmacie près d'ici ?"],["Siga reto.","Allez tout droit."],["Vire à esquerda.","Tournez à gauche."],["Ao lado da padaria.","À côté de la boulangerie."],["Em frente ao parque.","En face du parc."],["É longe?","C'est loin ?"],["Vou ao supermercado.","Je vais au supermarché."],["De nada.","Je vous en prie."]]},{"title":"Je peux, je veux","goal":"Convidar, aceitar ou recusar, e dizer o que você pode, quer e tem que fazer.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Claire convida o Lucas para ir ao cinema.","lines":[["Claire","Tu veux venir au cinéma samedi ?","Quer vir ao cinema no sábado?"],["Lucas","Je veux bien, mais je ne peux pas samedi. Je dois travailler.","Eu queria, mas não posso no sábado. Tenho que trabalhar."],["Claire","Dommage ! Et dimanche, tu peux ?","Que pena! E no domingo, você pode?"],["Lucas","Oui, dimanche je peux. On peut aller au cinéma l'après-midi ?","Sim, no domingo eu posso. Podemos ir à tarde?"],["Claire","D'accord. Je peux inviter Marta ?","Combinado. Posso convidar a Marta?"],["Lucas","Bien sûr ! Elle veut voir le nouveau film ?","Claro! Ela quer ver o filme novo?"],["Claire","Oui, elle adore. Mais on doit acheter les billets avant.","Quer, ela adora. Mas temos que comprar os ingressos antes."],["Lucas","Pas de problème, j'achète les billets en ligne.","Sem problema, eu compro os ingressos on-line."]],"grammar":[{"h":"pouvoir: poder","p":["<b>je peux</b>, <b>tu peux</b>, <b>il peut</b>, <b>nous pouvons</b>, <b>vous pouvez</b>, <b>ils peuvent</b>."],"ex":[["Je ne peux pas samedi.","Não posso no sábado."],["Vous pouvez répéter ?","O senhor pode repetir?"]]},{"h":"vouloir: querer","p":["<b>je veux</b>, <b>tu veux</b>, <b>il veut</b>, <b>nous voulons</b>, <b>vous voulez</b>, <b>ils veulent</b>. <b>Je veux bien</b> é um jeito simpático de aceitar."],"ex":[["Tu veux venir ?","Quer vir?"],["Je veux bien !","Aceito, com prazer!"]]},{"h":"devoir: ter que","p":["<b>je dois</b>, <b>tu dois</b>, <b>il doit</b>, <b>nous devons</b>, <b>vous devez</b>, <b>ils doivent</b>."],"ex":[["Je dois travailler.","Tenho que trabalhar."],["On doit acheter les billets.","Temos que comprar os ingressos."]]},{"h":"Os três + infinitivo","p":["Depois de <b>pouvoir</b>, <b>vouloir</b> e <b>devoir</b>, o verbo vem no infinitivo, sem preposição. <b>On</b> quer dizer “a gente” e usa a forma de il."],"ex":[["On peut aller au cinéma.","A gente pode ir ao cinema."]],"tip":"“Je dois de travailler” está errado. Diga <b>Je dois travailler</b>."}],"vocab":[{"h":"Convites","items":[["Tu veux venir ?","quer vir?"],["Je veux bien.","aceito, com prazer"],["Je ne peux pas.","não posso"],["Dommage !","que pena!"],["D'accord.","combinado"],["Bien sûr !","claro!"],["Pas de problème.","sem problema"]]},{"h":"Pedidos úteis","items":[["Vous pouvez répéter, s'il vous plaît ?","pode repetir, por favor?"],["Vous pouvez parler plus lentement ?","pode falar mais devagar?"],["Je peux entrer ?","posso entrar?"],["le cinéma","o cinema"],["le billet","o ingresso"],["en ligne","on-line"]]}],"pron":[{"h":"peux e veux","p":"O <b>eu</b> soa “ö”: “pö”, “vö”. O x final é mudo.","w":["je peux","je veux"]},{"h":"peuvent e veulent","p":"No plural, a consoante aparece: “pöv”, “völ”. O -ent continua mudo.","w":["ils peuvent","ils veulent"]},{"h":"dois","p":"Soa “duá”: o s é mudo.","w":["je dois","ils doivent"]}],"mc":[{"q":"Por que o Lucas não pode no sábado?","o":["Tem que trabalhar","Está doente","Vai viajar"],"a":0,"e":"Je dois travailler."},{"q":"Quando eles vão ao cinema?","o":["Sábado à noite","Domingo à tarde"],"a":1,"e":"dimanche… l'après-midi."},{"q":"Como dizer “Tenho que trabalhar”?","o":["Je dois travailler.","Je dois de travailler."],"a":0,"e":"devoir + infinitivo, sem preposição."},{"q":"Como pedir para repetir, de forma educada?","o":["Vous pouvez répéter ?","Vous peux répéter ?"],"a":0,"e":"Com vous: pouvez."}],"gaps":[{"s":"Tu ___ venir ?","a":["veux"],"h":"Quer vir?"},{"s":"Je ne ___ pas samedi.","a":["peux"],"h":"Não posso no sábado."},{"s":"Je ___ travailler.","a":["dois"],"h":"Tenho que trabalhar."},{"s":"Nous ___ aller au cinéma.","a":["pouvons"],"h":"Podemos ir ao cinema."},{"s":"Vous pouvez parler plus ___ ?","a":["lentement"],"h":"Pode falar mais devagar?"}],"order":[{"t":["Tu","veux","venir","au","cinéma ?"],"h":"Quer vir ao cinema?"},{"t":["Je","dois","travailler","samedi."],"h":"Tenho que trabalhar no sábado."},{"t":["Vous","pouvez","répéter,","s'il","vous","plaît ?"],"h":"Pode repetir, por favor?"}],"dict":[{"t":"Je ne peux pas."},{"t":"Je dois travailler."},{"t":"Tu veux venir ?"},{"t":"Dommage !"},{"t":"Vous pouvez répéter ?"}],"shadow":["Tu veux venir au cinéma samedi ?","Je veux bien, mais je ne peux pas.","Je dois travailler.","Vous pouvez répéter, s'il vous plaît ?"],"write":{"task":"Convide alguém para sair em francês e escreva a resposta: aceitando, ou recusando com uma desculpa.","ph":"Tu veux venir … ? — Je veux bien, mais …"},"cards":[["Quer vir ao cinema?","Tu veux venir au cinéma ?"],["Não posso no sábado.","Je ne peux pas samedi."],["Tenho que trabalhar.","Je dois travailler."],["Que pena!","Dommage !"],["Claro!","Bien sûr !"],["Posso entrar?","Je peux entrer ?"],["Pode repetir, por favor?","Vous pouvez répéter, s'il vous plaît ?"],["Pode falar mais devagar?","Vous pouvez parler plus lentement ?"]]},{"title":"Mes projets","goal":"Falar dos seus planos, dizer datas, dias da semana e meses.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Perto do fim do ano, Claire e Lucas falam das férias.","lines":[["Claire","Qu'est-ce que tu vas faire pendant les vacances ?","O que você vai fazer nas férias?"],["Lucas","Je vais rentrer au Brésil en décembre.","Vou voltar para o Brasil em dezembro."],["Claire","Super ! Tu vas voir ta famille ?","Que ótimo! Vai ver sua família?"],["Lucas","Oui, et on va passer Noël ensemble. Et toi ?","Vou, e vamos passar o Natal juntos. E você?"],["Claire","Moi, je vais aller à la montagne avec des amis. On va faire du ski !","Eu vou para a montanha com amigos. Vamos esquiar!"],["Lucas","Tu pars quand ?","Quando você viaja?"],["Claire","Le vingt décembre.","Dia vinte de dezembro."],["Lucas","Et tu reviens quand ?","E volta quando?"],["Claire","Le trois janvier.","Dia três de janeiro."],["Lucas","Bonnes vacances !","Boas férias!"],["Claire","Merci, toi aussi !","Obrigada, pra você também!"]],"grammar":[{"h":"Futur proche: aller + infinitivo","p":["Para planos, use <b>aller</b> no presente + verbo no infinitivo, exatamente como “vou viajar” em português: <b>Je vais voyager.</b>"],"ex":[["Je vais rentrer au Brésil.","Vou voltar para o Brasil."],["On va faire du ski.","Vamos esquiar."]]},{"h":"Negativa do futuro próximo","p":["O <b>ne… pas</b> abraça o verbo <b>aller</b>: <b>Je ne vais pas travailler.</b>"],"ex":[["Je ne vais pas sortir ce soir.","Não vou sair hoje à noite."]]},{"h":"Datas","p":["<b>le</b> + número + mês: <b>le vingt décembre</b>. Só o dia 1º é diferente: <b>le premier janvier</b>. Para o mês inteiro: <b>en décembre</b>."],"ex":[["le premier mai","1º de maio"],["le quatorze juillet","14 de julho"],["en août","em agosto"]],"tip":"Dias da semana e meses são escritos com letra minúscula: <b>lundi</b>, <b>janvier</b>."},{"h":"Partir e revenir","p":["Dois verbos de viagem, irregulares: <b>je pars</b>, <b>tu pars</b> (partir, viajar, ir embora); <b>je reviens</b>, <b>tu reviens</b> (voltar)."],"ex":[["Tu pars quand ?","Quando você viaja?"],["Je reviens lundi.","Volto na segunda."]]}],"vocab":[{"h":"Dias da semana","items":[["lundi","segunda-feira"],["mardi","terça-feira"],["mercredi","quarta-feira"],["jeudi","quinta-feira"],["vendredi","sexta-feira"],["samedi","sábado"],["dimanche","domingo"]]},{"h":"Meses e férias","items":[["janvier","janeiro"],["février","fevereiro"],["mars","março"],["avril","abril"],["mai","maio"],["juin","junho"],["juillet","julho"],["août","agosto"],["septembre","setembro"],["octobre","outubro"],["novembre","novembro"],["décembre","dezembro"],["les vacances","as férias"],["Noël","o Natal"],["Bonnes vacances !","boas férias!"]]}],"pron":[{"h":"août","p":"Soa só “ut” (ou “u”, para muitos franceses).","w":["août"]},{"h":"premier","p":"Soa “prë-MIÊ”: o r final é mudo.","w":["le premier janvier"]},{"h":"juin e juillet","p":"Os dois começam com o u francês seguido de vogal: “juã” e “jüi-IÉ”.","w":["juin","juillet"]}],"mc":[{"q":"Quando o Lucas volta para o Brasil?","o":["Em novembro","Em dezembro","Em janeiro"],"a":1,"e":"en décembre."},{"q":"O que a Claire vai fazer nas férias?","o":["Esquiar na montanha","Ir para a praia","Visitar o Brasil"],"a":0,"e":"On va faire du ski !"},{"q":"Como dizer “Vou viajar”?","o":["Je vais voyager.","Je vais voyage."],"a":0,"e":"aller + infinitivo."},{"q":"Como dizer “1º de janeiro”?","o":["le un janvier","le premier janvier"],"a":1,"e":"Só o dia 1º usa premier."}],"gaps":[{"s":"Je ___ rentrer au Brésil.","a":["vais"],"h":"Vou voltar para o Brasil."},{"s":"On ___ faire du ski.","a":["va"],"h":"Vamos esquiar."},{"s":"Je ne vais ___ travailler.","a":["pas"],"h":"Não vou trabalhar."},{"s":"Le ___ janvier.","a":["premier"],"h":"1º de janeiro."},{"s":"Tu vas voir ___ famille ?","a":["ta"],"h":"Você vai ver sua família?"}],"order":[{"t":["Je","vais","voir","ma","famille."],"h":"Vou ver minha família."},{"t":["On","va","faire","du","ski."],"h":"Vamos esquiar."},{"t":["Nous","allons","partir","en","juillet."],"h":"Vamos viajar em julho."}],"dict":[{"t":"Je vais rentrer au Brésil."},{"t":"le premier janvier"},{"t":"Bonnes vacances !"},{"t":"samedi"},{"t":"Qu'est-ce que tu vas faire ?"}],"shadow":["Qu'est-ce que tu vas faire pendant les vacances ?","Je vais rentrer au Brésil en décembre.","On va faire du ski !","Bonnes vacances !"],"write":{"task":"Conte seus planos para as próximas férias ou para o próximo fim de semana, com datas e dias, usando aller + infinitivo.","ph":"Le week-end prochain, je vais …"},"cards":[["O que você vai fazer?","Qu'est-ce que tu vas faire ?"],["Vou voltar para o Brasil.","Je vais rentrer au Brésil."],["Vamos esquiar.","On va faire du ski."],["Não vou trabalhar.","Je ne vais pas travailler."],["Dia 1º de janeiro.","Le premier janvier."],["Em dezembro.","En décembre."],["Boas férias!","Bonnes vacances !"],["Pra você também!","Toi aussi !"]]},{"title":"Le week-end dernier","goal":"Contar o que você fez no fim de semana ou nos últimos dias, usando o passé composé com avoir e expressões de tempo como hier e la semaine dernière.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Na segunda-feira de manhã, Claire e Lucas conversam durante uma pausa para o café sobre o que fizeram no fim de semana.","lines":[["Claire","Salut Lucas ! Tu as passé un bon week-end ?","Oi, Lucas! Teve um bom fim de semana?"],["Lucas","Oui ! Samedi, j'ai visité un musée avec ma sœur.","Sim! No sábado, visitei um museu com minha irmã."],["Claire","Ah oui ? Vous avez aimé l'exposition ?","É mesmo? Vocês gostaram da exposição?"],["Lucas","Beaucoup ! Après, on a mangé dans un petit restaurant.","Muito! Depois, a gente comeu num restaurante pequeno."],["Claire","Et dimanche, tu as travaillé ?","E no domingo, você trabalhou?"],["Lucas","Non, j'ai regardé une série et j'ai préparé le dîner.","Não, assisti a uma série e preparei o jantar."],["Claire","Moi, j'ai passé samedi chez mes parents.","Eu passei o sábado na casa dos meus pais."],["Lucas","Vous avez cuisiné ensemble ?","Vocês cozinharam juntos?"],["Claire","Oui, on a préparé des crêpes et on a écouté de la musique.","Sim, a gente preparou crepes e ouviu música."],["Lucas","Et hier, tu as profité du soleil ?","E ontem, você aproveitou o sol?"],["Claire","Oui, j'ai marché dans le parc, puis j'ai étudié le français.","Sim, caminhei no parque e depois estudei francês."],["Lucas","Tu as étudié toute la journée ?","Você estudou o dia inteiro?"],["Claire","Non, seulement une heure ! Après, j'ai appelé une amie.","Não, só uma hora! Depois, liguei para uma amiga."],["Lucas","Moi, la semaine dernière, j'ai étudié tous les soirs. Mais ce week-end, j'ai préféré me reposer !","Eu estudei todas as noites na semana passada. Mas neste fim de semana preferi descansar!"]],"grammar":[{"h":"Passé composé: avoir + particípio passado","p":["O <b>passé composé</b> é usado para contar ações concluídas no passado. Sua formação mais comum é: <b>avoir no presente + particípio passado</b>.","Nos verbos regulares terminados em <b>-er</b>, retire <b>-er</b> e coloque <b>-é</b>: <b>visiter → visité</b>, <b>regarder → regardé</b>, <b>travailler → travaillé</b>.","Em português, geralmente corresponde ao pretérito perfeito: <b>j'ai visité</b> significa “visitei”, não “tenho visitado”."],"ex":[["J'ai visité un musée.","Visitei um museu."],["Tu as regardé un film.","Você assistiu a um filme."],["On a préparé le dîner.","A gente preparou o jantar."]],"tip":"Nos verbos regulares em -er, o particípio termina em <b>-é</b>, com acento agudo. Não confunda <b>parler</b> (falar) com <b>parlé</b> (falado)."},{"h":"Conjugação do auxiliar avoir","p":["O auxiliar <b>avoir</b> muda conforme a pessoa: <b>j'ai</b>, <b>tu as</b>, <b>il/elle/on a</b>, <b>nous avons</b>, <b>vous avez</b>, <b>ils/elles ont</b>.","Com <b>avoir</b>, o particípio dos verbos regulares em -er normalmente permanece igual, independentemente de quem pratica a ação: <b>j'ai travaillé</b>, <b>elle a travaillé</b>, <b>nous avons travaillé</b>."],"ex":[["Nous avons travaillé samedi.","Trabalhamos no sábado."],["Vous avez aimé l'exposition ?","Vocês gostaram da exposição?"],["Ils ont parlé longtemps.","Eles conversaram por bastante tempo."]],"tip":"Não traduza o auxiliar separadamente. <b>Nous avons travaillé</b> significa simplesmente “nós trabalhamos”, referindo-se ao passado."},{"h":"Perguntas e negativas no passado","p":["Para fazer perguntas informais, mantenha a ordem normal da frase e use a entonação de pergunta: <b>Tu as travaillé ?</b>","Para negar, coloque <b>ne... pas</b> em volta do auxiliar <b>avoir</b>, não do particípio: <b>Je n'ai pas travaillé.</b> O <b>ne</b> vira <b>n'</b> antes de uma vogal.","Na fala informal, os franceses frequentemente omitem <b>ne</b>, mas na escrita padrão é melhor manter a negativa completa."],"ex":[["Je n'ai pas travaillé dimanche.","Não trabalhei no domingo."],["Tu as étudié hier ?","Você estudou ontem?"],["Elle n'a pas regardé la série.","Ela não assistiu à série."]]},{"h":"Expressões para situar ações no passado","p":["<b>Hier</b> significa “ontem”, e <b>hier soir</b> significa “ontem à noite”. Para períodos anteriores, use <b>le week-end dernier</b> (no fim de semana passado) e <b>la semaine dernière</b> (na semana passada).","Observe a concordância: <b>dernier</b> acompanha o masculino <b>week-end</b>, enquanto <b>dernière</b> acompanha o feminino <b>semaine</b>.","Essas expressions podem aparecer no início ou no fim da frase."],"ex":[["Hier, j'ai appelé une amie.","Ontem, liguei para uma amiga."],["Le week-end dernier, nous avons visité Paris.","No fim de semana passado, visitamos Paris."],["La semaine dernière, elle a marché tous les jours.","Na semana passada, ela caminhou todos os dias."]],"tip":"Não use preposição antes de <b>hier</b>, <b>samedi</b> ou <b>la semaine dernière</b> nesses exemplos."}],"vocab":[{"h":"Passeios e atividades","items":[["un musée","um museu"],["une exposition","uma exposição"],["un restaurant","um restaurante"],["un parc","um parque"],["une série","uma série"],["des crêpes","crepes"],["le dîner","o jantar"],["de la musique","música"]]},{"h":"Verbos para contar experiências","items":[["visiter","visitar"],["regarder","assistir a / olhar"],["préparer","preparar"],["écouter","escutar / ouvir"],["marcher","caminhar"],["appeler","ligar / chamar"],["travailler","trabalhar"],["étudier","estudar"],["cuisiner","cozinhar"],["passer","passar"]]},{"h":"Expressões de tempo","items":[["hier","ontem"],["hier soir","ontem à noite"],["samedi","sábado"],["dimanche","domingo"],["le week-end dernier","no fim de semana passado"],["la semaine dernière","na semana passada"]]}],"pron":[{"h":"Final -é dos particípios","p":"O <b>-é</b> final tem som fechado, parecido com “ê” em português. Em <b>visité</b>, a última sílaba soa aproximadamente “tê”. Não pronuncie como “ei”.","w":["visité","regardé","préparé","travaillé"]},{"h":"Ligação em vous avez","p":"Em <b>vous avez</b>, o s final de <b>vous</b> se liga à vogal seguinte com som de z: aproximadamente “vu-za-vê”. O mesmo ocorre em <b>nous avons</b>: “nu-za-võ”, com vogal nasal no final.","w":["vous avez aimé","nous avons travaillé","vous avez préparé"]},{"h":"j'ai","p":"O <b>je</b> perde o e antes de <b>ai</b>, formando <b>j'ai</b>. A pronúncia aproximada é “jê”, com o mesmo som inicial de “já” em português. O auxiliar e o pronome formam uma única unidade sonora.","w":["j'ai visité","j'ai regardé","j'ai étudié"]}],"mc":[{"q":"O que Lucas fez no sábado?","o":["Assistiu a um filme no cinema","Visitou um museu com a irmã","Caminhou no parque com Claire"],"a":1,"e":"Samedi, j'ai visité un musée avec ma sœur."},{"q":"Onde Claire passou o sábado?","o":["Na casa dos pais","Na casa de uma amiga","Em um restaurante"],"a":0,"e":"Moi, j'ai passé samedi chez mes parents."},{"q":"O que Claire preparou com a família?","o":["Um jantar italiano","Um bolo de chocolate","Crepes"],"a":2,"e":"Oui, on a préparé des crêpes et on a écouté de la musique."},{"q":"Por quanto tempo Claire estudou francês no domingo?","o":["O dia inteiro","Uma hora","Duas horas"],"a":1,"e":"Non, seulement une heure !"}],"gaps":[{"s":"Hier, j'___ visité un musée.","a":["ai"],"h":"Ontem, visitei um museu."},{"s":"Tu ___ regardé une série dimanche ?","a":["as"],"h":"Você assistiu a uma série no domingo?"},{"s":"Nous avons ___ des crêpes.","a":["préparé"],"h":"Nós preparamos crepes."},{"s":"Elle n'a ___ travaillé samedi.","a":["pas"],"h":"Ela não trabalhou no sábado."},{"s":"Vous avez ___ l'exposition ?","a":["aimé"],"h":"Vocês gostaram da exposição?"},{"s":"La semaine ___, j'ai appelé une amie.","a":["dernière"],"h":"Na semana passada, liguei para uma amiga."}],"order":[{"t":["J'ai","regardé","une","série","hier","soir."],"h":"Assisti a uma série ontem à noite."},{"t":["Nous","avons","visité","un","musée","samedi."],"h":"Visitamos um museu no sábado."},{"t":["Elle","n'a","pas","travaillé","dimanche","dernier."],"h":"Ela não trabalhou no domingo passado."}],"dict":[{"t":"J'ai visité un musée samedi."},{"t":"Tu as regardé une série ?"},{"t":"Nous avons préparé des crêpes."},{"t":"Je n'ai pas travaillé hier."},{"t":"La semaine dernière, on a écouté de la musique."}],"shadow":["Salut Lucas ! Tu as passé un bon week-end ?","Beaucoup ! Après, on a mangé dans un petit restaurant.","Oui, on a préparé des crêpes et on a écouté de la musique.","Non, seulement une heure ! Après, j'ai appelé une amie."],"write":{"task":"Conte três coisas que você fez no último fim de semana. Diga quando aconteceram, usando passé composé com avoir, e inclua pelo menos uma frase negativa.","ph":"Le week-end dernier, j'ai …"},"cards":[["Visitei um museu no sábado.","J'ai visité un musée samedi."],["Assisti a uma série ontem.","J'ai regardé une série hier."],["Você gostou da exposição?","Tu as aimé l'exposition ?"],["A gente preparou crepes.","On a préparé des crêpes."],["Ela trabalhou no domingo.","Elle a travaillé dimanche."],["Não estudei ontem à noite.","Je n'ai pas étudié hier soir."],["Vocês ouviram música?","Vous avez écouté de la musique ?"],["Nós caminhamos no parque.","Nous avons marché dans le parc."],["Eles conversaram durante uma hora.","Ils ont parlé pendant une heure."],["Na semana passada, liguei para um amigo.","La semaine dernière, j'ai appelé un ami."]]},{"title":"En voyage","goal":"Contar viagens e deslocamentos no passado, usando o passé composé com être, fazendo a concordância do particípio e empregando particípios irregulares como fait, pris, vu, eu e été.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Na segunda-feira, Claire e Lucas conversam durante uma pausa no trabalho sobre as viagens que fizeram no fim de semana.","lines":[["Claire","Salut Lucas ! Tu es parti où ce week-end ?","Oi, Lucas! Para onde você viajou neste fim de semana?"],["Lucas","Je suis allé à Lyon avec ma sœur.","Fui a Lyon com minha irmã."],["Claire","Vous êtes partis vendredi ?","Vocês viajaram na sexta-feira?"],["Lucas","Oui, nous sommes partis vendredi soir et nous sommes arrivés tard.","Sim, saímos na sexta à noite e chegamos tarde."],["Claire","Vous avez fait quoi samedi ?","O que vocês fizeram no sábado?"],["Lucas","On a visité la ville et j'ai pris des photos.","A gente conheceu a cidade e eu tirei fotos."],["Claire","Tu as vu le vieux quartier ?","Você viu o bairro antigo?"],["Lucas","Oui, et ma sœur a eu une bonne idée : visiter un musée.","Sim, e minha irmã teve uma boa ideia: visitar um museu."],["Claire","Super ! Moi, je suis allée à Bordeaux.","Que legal! Eu fui a Bordeaux."],["Lucas","Ah bon ? Tu es partie seule ?","É mesmo? Você viajou sozinha?"],["Claire","Non, une amie est venue avec moi.","Não, uma amiga veio comigo."],["Lucas","Et vous êtes rentrées dimanche ?","E vocês voltaram no domingo?"],["Claire","Oui, nous sommes rentrées dimanche soir. Le trajet a été long !","Sim, voltamos no domingo à noite. A viagem de volta foi longa!"],["Lucas","Moi aussi, je suis rentré dimanche soir. J'ai adoré Lyon !","Eu também voltei no domingo à noite. Adorei Lyon!"]],"grammar":[{"h":"Passé composé com être","p":["Na unidade anterior, você aprendeu o passé composé com <b>avoir</b>. Alguns verbos de deslocamento usam <b>être</b> como auxiliar. A estrutura é: <b>être no presente + particípio passado</b>.","Entre os principais estão <b>aller</b> (ir), <b>venir</b> (vir), <b>partir</b> (partir), <b>arriver</b> (chegar), <b>rentrer</b> (voltar para casa) e <b>revenir</b> (voltar).","O auxiliar segue a conjugação de être: <b>je suis, tu es, il/elle est, nous sommes, vous êtes, ils/elles sont</b>. Observe que aller forma o particípio irregular <b>allé</b>, enquanto partir forma <b>parti</b> e venir forma <b>venu</b>."],"ex":[["Je suis allé à Lyon.","Fui a Lyon."],["Tu es parti vendredi ?","Você viajou na sexta-feira?"],["Elle est venue avec moi.","Ela veio comigo."],["Nous sommes arrivés tard.","Chegamos tarde."]],"tip":"Não escolha o auxiliar apenas pelo significado do verbo. <b>Aller</b> usa être, mas <b>visiter</b> usa avoir."},{"h":"Concordância do particípio com être","p":["Com o auxiliar <b>être</b>, o particípio passado concorda com o sujeito em gênero e número. No masculino singular: <b>allé</b>; no feminino singular: <b>allée</b>.","No masculino plural, acrescentamos <b>-s</b>: <b>allés</b>. No feminino plural, acrescentamos <b>-es</b>: <b>allées</b>.","Quando um grupo tem homens e mulheres, usa-se o masculino plural. Por isso, Lucas e sua irmã dizem <b>nous sommes partis</b>, enquanto Claire e sua amiga dizem <b>nous sommes rentrées</b>."],"ex":[["Lucas est allé à Lyon.","Lucas foi a Lyon."],["Claire est allée à Bordeaux.","Claire foi a Bordeaux."],["Ils sont partis vendredi.","Eles viajaram na sexta-feira."],["Elles sont rentrées dimanche.","Elas voltaram no domingo."]],"tip":"As terminações <b>-e</b>, <b>-s</b> e <b>-es</b> de allé não mudam sua pronúncia."},{"h":"Particípios irregulares com avoir","p":["Além dos verbos regulares em -er, muitos verbos frequentes têm particípios irregulares. Cinco essenciais são: <b>faire → fait</b> (fazer), <b>prendre → pris</b> (pegar), <b>voir → vu</b> (ver), <b>avoir → eu</b> (ter) e <b>être → été</b> (ser/estar).","Esses cinco verbos usam <b>avoir</b> como auxiliar no passé composé. Isso também vale para o próprio verbo être: <b>j'ai été</b>, e não je suis été.","Nos exemplos desta unidade, os particípios com avoir não mudam de forma conforme o sujeito."],"ex":[["J'ai fait une promenade.","Fiz uma caminhada."],["J'ai pris le train.","Peguei o trem."],["Nous avons vu le musée.","Vimos o museu."],["J'ai eu une idée. Le voyage a été long.","Tive uma ideia. A viagem foi longa."]],"tip":"Memorize os cinco pares: <b>fait, pris, vu, eu, été</b>."},{"h":"Perguntas e negativas com être","p":["Para fazer perguntas informais no passé composé com être, mantenha a ordem normal e use a entonação: <b>Tu es parti ?</b>.","Na negativa, coloque <b>ne... pas</b> ao redor do auxiliar être, deixando o particípio depois: <b>Je ne suis pas parti.</b>","A concordância continua valendo nas negativas. Uma mulher diz <b>je ne suis pas partie</b>, com -e."],"ex":[["Tu es arrivée hier ?","Você chegou ontem?"],["Je ne suis pas parti samedi.","Não viajei no sábado."],["Elle n'est pas venue.","Ela não veio."],["Vous n'êtes pas rentrées ?","Vocês não voltaram?"]]}],"vocab":[{"h":"Verbos de viagem e deslocamento","items":[["aller","ir"],["venir","vir"],["partir","partir / viajar"],["arriver","chegar"],["rentrer","voltar para casa"],["revenir","voltar"],["prendre","pegar / tomar"],["voir","ver"]]},{"h":"Transporte e lugares","items":[["un voyage","uma viagem"],["un trajet","um trajeto / percurso"],["un train","um trem"],["un billet","uma passagem"],["une gare","uma estação de trem"],["un quartier","um bairro"],["le centre-ville","o centro da cidade"],["une valise","uma mala"]]},{"h":"Expressões úteis durante viagens","items":[["en train","de trem"],["en voiture","de carro"],["en avion","de avião"],["avec des amis","com amigos"],["tout seul","sozinho"],["toute seule","sozinha"],["en retard","atrasado / com atraso"],["à l'heure","na hora / pontualmente"]]}],"pron":[{"h":"allé, allée, allés, allées","p":"As quatro formas têm a mesma pronúncia, aproximadamente “a-LÊ”. As terminações escritas -e, -s e -es não acrescentam sons.","w":["allé","allée","allés","allées"]},{"h":"fait e pris","p":"Em <b>fait</b>, o t final não é pronunciado; a palavra soa aproximadamente “fê”. Em <b>pris</b>, o s também é mudo: aproximadamente “pri”, com r francês.","w":["j'ai fait","j'ai pris","nous avons fait"]},{"h":"vu, venu e eu","p":"O <b>u</b> francês não tem equivalente direto em português. Para produzi-lo, tente dizer “i” com os lábios arredondados. Em <b>vu</b>, soa aproximadamente “vü”; em <b>eu</b>, apenas “ü”.","w":["vu","venu","j'ai eu"]}],"mc":[{"q":"Para qual cidade Lucas viajou?","o":["Bordeaux","Paris","Lyon"],"a":2,"e":"Je suis allé à Lyon avec ma sœur."},{"q":"Quando Lucas e sua irmã chegaram ao destino?","o":["Na sexta-feira à noite, tarde","No sábado de manhã","No domingo à tarde"],"a":0,"e":"Oui, nous sommes partis vendredi soir et nous sommes arrivés tard."},{"q":"Com quem Claire viajou para Bordeaux?","o":["Com sua irmã","Com uma amiga","Sozinha"],"a":1,"e":"Non, une amie est venue avec moi."},{"q":"Como foi o trajeto de volta de Claire?","o":["Curto","Muito rápido","Longo"],"a":2,"e":"Le trajet a été long !"}],"gaps":[{"s":"Je ___ allé à Lyon vendredi.","a":["suis"],"h":"Fui a Lyon na sexta-feira."},{"s":"Claire est ___ à Bordeaux.","a":["allée"],"h":"Claire foi a Bordeaux."},{"s":"Claire et son amie sont ___ dimanche soir.","a":["rentrées"],"h":"Claire e sua amiga voltaram no domingo à noite."},{"s":"J'ai ___ le train pour Lyon.","a":["pris"],"h":"Peguei o trem para Lyon."},{"s":"Mon amie est ___ avec moi.","a":["venue"],"h":"Minha amiga veio comigo."},{"s":"Le voyage a ___ long.","a":["été"],"h":"A viagem foi longa."}],"order":[{"t":["Claire","est","allée","à","Bordeaux","samedi."],"h":"Claire foi a Bordeaux no sábado."},{"t":["Nous","sommes","partis","vendredi","soir."],"h":"Partimos na sexta-feira à noite."},{"t":["J'ai","pris","le","train","hier."],"h":"Peguei o trem ontem."}],"dict":[{"t":"Je suis allé à Lyon vendredi."},{"t":"Elle est venue avec moi."},{"t":"Nous sommes rentrées dimanche soir."},{"t":"J'ai pris le train et j'ai vu la ville."},{"t":"Le voyage a été long."}],"shadow":["Je suis allé à Lyon avec ma sœur.","Oui, nous sommes partis vendredi soir et nous sommes arrivés tard.","Non, une amie est venue avec moi.","Oui, nous sommes rentrées dimanche soir. Le trajet a été long !"],"write":{"task":"Conte uma viagem que você fez recentemente. Diga para onde foi, quando partiu, com quem viajou, o que viu ou fez e quando voltou. Use pelo menos três verbos com être no passé composé e dois particípios irregulares com avoir. Preste atenção à concordância.","ph":"Le week-end dernier, je suis allé(e) à …"},"cards":[["Ele foi a Lyon.","Il est allé à Lyon."],["Ela foi a Bordeaux.","Elle est allée à Bordeaux."],["O trem chegou atrasado.","Le train est arrivé en retard."],["Ela veio comigo.","Elle est venue avec moi."],["Nós duas voltamos no domingo.","Nous sommes rentrées dimanche."],["Você viajou sozinho?","Tu es parti seul ?"],["Você tirou fotos?","Tu as pris des photos ?"],["Vi o centro da cidade.","J'ai vu le centre-ville."],["A viagem foi longa.","Le voyage a été long."],["Tive tempo de visitar o museu.","J'ai eu le temps de visiter le musée."]]},{"title":"Quand j'étais petit","goal":"Falar sobre a infância, descrever como eram pessoas e lugares no passado e contar hábitos antigos usando o imparfait.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Na casa de Claire, durante uma tarde de domingo, ela mostra fotos antigas a Lucas. Os dois conversam sobre como era a vida quando eram crianças.","lines":[["Claire","Regarde cette photo ! C'était mon quartier quand j'étais petite.","Olha esta foto! Era o meu bairro quando eu era pequena."],["Lucas","Tu habitais ici ?","Você morava aqui?"],["Claire","Oui, j'habitais près d'un grand parc.","Sim, eu morava perto de um parque grande."],["Lucas","Tu jouais souvent dehors ?","Você brincava muito fora de casa?"],["Claire","Tous les jours ! Mes amis et moi, on jouait au ballon après l'école.","Todos os dias! Meus amigos e eu jogávamos bola depois da escola."],["Lucas","Moi, quand j'étais petit, j'habitais à la campagne.","Eu, quando era pequeno, morava no campo."],["Claire","C'était comment ?","Como era lá?"],["Lucas","C'était calme. Il y avait beaucoup d'arbres et une petite rivière.","Era tranquilo. Havia muitas árvores e um riozinho."],["Claire","Tu allais à l'école à pied ?","Você ia para a escola a pé?"],["Lucas","Oui, avec mon frère. On marchait pendant vingt minutes.","Sim, com meu irmão. A gente caminhava durante vinte minutos."],["Claire","Et le week-end, qu'est-ce que tu faisais ?","E nos fins de semana, o que você fazia?"],["Lucas","Je faisais du vélo et je regardais des dessins animés.","Eu andava de bicicleta e assistia a desenhos animados."],["Claire","Moi, j'écoutais beaucoup de musique, mais je n'aimais pas les maths !","Eu ouvia muita música, mas não gostava de matemática!"],["Lucas","Ah, moi non plus ! À l'école, j'aimais surtout le sport.","Ah, eu também não! Na escola, eu gostava principalmente de educação física."]],"grammar":[{"h":"Imparfait: como formar","p":["O <b>imparfait</b> é um tempo verbal usado para falar de hábitos, situações e descrições no passado. Em português, corresponde frequentemente a formas como “morava”, “brincava”, “fazia” e “era”.","Para formar o imparfait, pegue a forma de <b>nous</b> no presente, retire <b>-ons</b> e acrescente as terminações: <b>-ais, -ais, -ait, -ions, -iez, -aient</b>.","Exemplo com <b>habiter</b>: nous habitons → habit-. Assim: <b>j'habitais, tu habitais, il habitait, nous habitions, vous habitiez, ils habitaient</b>. O mesmo princípio funciona com a maioria dos verbos, inclusive muitos irregulares no presente."],"ex":[["J'habitais près du parc.","Eu morava perto do parque."],["Nous regardions la télévision.","Nós assistíamos à televisão."],["Ils jouaient dehors.","Eles brincavam fora de casa."]],"tip":"As terminações <b>-ais, -ait e -aient</b> têm a mesma pronúncia. A pessoa é identificada principalmente pelo sujeito."},{"h":"O caso especial de être","p":["O verbo <b>être</b> é a principal exceção na formação do imparfait. Em vez de usar a forma nous sommes, ele utiliza a base <b>ét-</b>.","Sua conjugação é: <b>j'étais, tu étais, il/elle/on était, nous étions, vous étiez, ils/elles étaient</b>.","A expressão <b>quand j'étais petit(e)</b> significa “quando eu era pequeno(a)”. Use petit para um homem e petite para uma mulher."],"ex":[["Quand j'étais petite, j'étais timide.","Quando eu era pequena, era tímida."],["Nous étions voisins.","Nós éramos vizinhos."],["Vous étiez amis ?","Vocês eram amigos?"]],"tip":"Não confunda <b>j'étais</b> (eu era/estava) com <b>j'ai été</b> (eu fui/estive)."},{"h":"Hábitos e ações repetidas no passado","p":["Use o imparfait para contar o que você <b>costumava fazer</b>, especialmente durante a infância. Não se trata de uma ação isolada, mas de algo repetido ou habitual.","Expressões como <b>tous les jours</b> (todos os dias), <b>souvent</b> (frequentemente), <b>d'habitude</b> (geralmente) e <b>le dimanche</b> (aos domingos) ajudam a indicar repetição.","Compare com o passé composé das unidades anteriores: <b>J'ai joué samedi</b> conta algo que aconteceu em um sábado específico; <b>Je jouais tous les samedis</b> descreve um hábito antigo."],"ex":[["Tous les jours, je marchais jusqu'à l'école.","Todos os dias, eu caminhava até a escola."],["Le dimanche, nous jouions au parc.","Aos domingos, brincávamos no parque."],["Quand j'étais petit, je faisais du vélo.","Quando eu era pequeno, andava de bicicleta."]],"tip":"Para dizer “eu costumava fazer”, muitas vezes basta usar o <b>imparfait</b>: <b>je faisais</b>."},{"h":"Descrever lugares e situações no passado","p":["O imparfait também descreve como as coisas eram: aparência, ambiente, sentimentos e situações que existiam no passado.","Duas construções muito úteis são <b>c'était</b> (era) e <b>il y avait</b> (havia/tinha). A primeira caracteriza algo; a segunda indica que alguma coisa existia.","Para negar, use <b>ne... pas</b> ao redor do verbo no imparfait: <b>Je n'aimais pas les maths</b> (eu não gostava de matemática)."],"ex":[["C'était un quartier calme.","Era um bairro tranquilo."],["Il y avait une petite rivière.","Havia um riozinho."],["Je n'aimais pas les maths.","Eu não gostava de matemática."]],"tip":"<b>Il y a</b> significa “há/tem” no presente. No passado, para descrever como era uma situação, use <b>il y avait</b>."}],"vocab":[{"h":"Infância e escola","items":[["l'enfance","a infância"],["petit / petite","pequeno / pequena"],["l'école","a escola"],["la cour de récréation","o pátio do recreio"],["un dessin animé","um desenho animado"],["un vélo","uma bicicleta"],["les maths","a matemática"],["le sport","o esporte / a educação física"]]},{"h":"Lugares e lembranças","items":[["un quartier","um bairro"],["la campagne","o campo / a zona rural"],["la ville","a cidade"],["une rivière","um rio"],["un arbre","uma árvore"],["un parc","um parque"],["un voisin / une voisine","um vizinho / uma vizinha"],["une photo","uma foto"]]},{"h":"Frequência e hábitos antigos","items":[["tous les jours","todos os dias"],["souvent","frequentemente"],["d'habitude","geralmente / normalmente"],["après l'école","depois da escola"],["le week-end","nos fins de semana"],["quand j'étais petit","quando eu era pequeno"],["à l'époque","naquela época"],["à pied","a pé"]]}],"pron":[{"h":"Terminações -ais, -ait e -aient","p":"As três terminações soam como um “é” aberto, semelhante ao de “pé” em português. Em <b>parlais</b>, <b>parlait</b> e <b>parlaient</b>, a pronúncia é igual, aproximadamente “par-LÉ”, com r francês.","w":["je parlais","il parlait","ils parlaient"]},{"h":"petit e petite","p":"Em <b>petit</b>, o t final é mudo: aproximadamente “pë-TI”. Em <b>petite</b>, o t é pronunciado: “pë-TIT”.","w":["quand j'étais petit","quand j'étais petite","une petite rivière"]},{"h":"il y avait","p":"A expressão <b>il y avait</b> é pronunciada de forma contínua, aproximadamente “il ia-VÉ”. O final -ait tem som de “é” aberto.","w":["il y avait","il y avait des arbres","il y avait une rivière"]}],"mc":[{"q":"Perto de que lugar Claire morava quando era pequena?","o":["De uma escola","De um parque grande","De uma estação de trem"],"a":1,"e":"Oui, j'habitais près d'un grand parc."},{"q":"Onde Lucas morava durante a infância?","o":["No campo","No centro da cidade","Perto da praia"],"a":0,"e":"Moi, quand j'étais petit, j'habitais à la campagne."},{"q":"Como Lucas ia para a escola?","o":["De bicicleta","De ônibus","A pé, com o irmão"],"a":2,"e":"Oui, avec mon frère. On marchait pendant vingt minutes."},{"q":"O que Lucas costumava fazer nos fins de semana?","o":["Estudar matemática e ouvir música","Andar de bicicleta e assistir a desenhos animados","Jogar bola com os amigos"],"a":1,"e":"Je faisais du vélo et je regardais des dessins animés."}],"gaps":[{"s":"Quand j'___ petit, j'habitais à la campagne.","a":["étais"],"h":"Quando eu era pequeno, morava no campo."},{"s":"Nous ___ près d'un parc quand nous étions enfants.","a":["habitions"],"h":"Morávamos perto de um parque quando éramos crianças."},{"s":"Tous les jours, elle ___ au ballon après l'école.","a":["jouait"],"h":"Todos os dias, ela jogava bola depois da escola."},{"s":"Avant, il y ___ une rivière ici.","a":["avait"],"h":"Antes, havia um rio aqui."},{"s":"Vous ___ du vélo tous les dimanches.","a":["faisiez"],"h":"Vocês andavam de bicicleta todos os domingos."},{"s":"Ils n'___ pas les maths à l'école.","a":["aimaient"],"h":"Eles não gostavam de matemática na escola."}],"order":[{"t":["Quand","j'étais","petit,","je","jouais","dehors."],"h":"Quando eu era pequeno, brincava fora de casa."},{"t":["Il","y","avait","une","petite","rivière."],"h":"Havia um riozinho."},{"t":["Nous","allions","à","l'école","à","pied."],"h":"Nós íamos para a escola a pé."}],"dict":[{"t":"Quand j'étais petite, j'habitais près d'un parc."},{"t":"Il y avait beaucoup d'arbres."},{"t":"On marchait pendant vingt minutes."},{"t":"Je faisais du vélo le dimanche."},{"t":"Nous étions souvent ensemble."}],"shadow":["Regarde cette photo ! C'était mon quartier quand j'étais petite.","Tous les jours ! Mes amis et moi, on jouait au ballon après l'école.","C'était calme. Il y avait beaucoup d'arbres et une petite rivière.","Je faisais du vélo et je regardais des dessins animés."],"write":{"task":"Descreva sua infância em cinco ou seis frases. Diga onde você morava, como era o bairro, o que costumava fazer depois da escola e o que gostava ou não gostava de fazer. Use o imparfait, incluindo pelo menos uma frase com c'était ou il y avait.","ph":"Quand j'étais petit(e), j'habitais …"},"cards":[["Eu morava no campo.","J'habitais à la campagne."],["Ela era muito tímida.","Elle était très timide."],["Quando éramos crianças, brincávamos no parque.","Quand nous étions petits, nous jouions au parc."],["Havia muitas árvores.","Il y avait beaucoup d'arbres."],["A gente ia para a escola a pé.","On allait à l'école à pied."],["Eu andava de bicicleta todos os domingos.","Je faisais du vélo tous les dimanches."],["Meu bairro era tranquilo.","Mon quartier était calme."],["Eles assistiam a desenhos animados.","Ils regardaient des dessins animés."],["Eu não gostava de matemática.","Je n'aimais pas les maths."],["Você brincava fora de casa?","Tu jouais dehors ?"]]},{"title":"Une histoire","goal":"Contar uma história no passado, combinando passé composé e imparfait para distinguir acontecimentos concluídos, situações em andamento e descrições.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Na segunda-feira, durante uma pausa no trabalho, Claire conta a Lucas o que aconteceu durante um passeio no sábado.","lines":[["Claire","Samedi, je marchais dans le parc quand il a commencé à pleuvoir.","No sábado, eu estava caminhando no parque quando começou a chover."],["Lucas","Tu étais seule ?","Você estava sozinha?"],["Claire","Non, j'étais avec une amie. On parlait de nos vacances.","Não, eu estava com uma amiga. A gente conversava sobre nossas férias."],["Lucas","Vous aviez un parapluie ?","Vocês tinham um guarda-chuva?"],["Claire","Non ! On a cherché un café, mais tout était fermé.","Não! Procuramos um café, mas estava tudo fechado."],["Lucas","Alors, vous avez fait quoi ?","Então, o que vocês fizeram?"],["Claire","On a attendu à l'arrêt de bus. Il pleuvait très fort.","Esperamos no ponto de ônibus. Estava chovendo muito."],["Lucas","Et le bus ? Il est arrivé ?","E o ônibus? Ele chegou?"],["Claire","Pendant qu'on attendait, mon amie a appelé un taxi.","Enquanto a gente esperava, minha amiga chamou um táxi."],["Lucas","Bonne idée ! Le taxi est arrivé vite ?","Boa ideia! O táxi chegou rápido?"],["Claire","Oui, il est arrivé dix minutes plus tard.","Sim, ele chegou dez minutos depois."],["Lucas","Et après ?","E depois?"],["Claire","On est rentrées chez moi et on a préparé du thé.","Voltamos para minha casa e preparamos um chá."],["Lucas","Quel samedi ! Moi, j'étais chez moi, au chaud.","Que sábado! Eu estava em casa, quentinho."]],"grammar":[{"h":"Passé composé x imparfait: a diferença","p":["Os dois tempos falam do passado, mas apresentam as ações de maneiras diferentes. O <b>passé composé</b> conta acontecimentos concluídos. O <b>imparfait</b> descreve situações, estados ou ações em andamento no passado.","Imagine uma história: o imparfait mostra o cenário e o que estava acontecendo; o passé composé conta os acontecimentos que fazem a história avançar.","Não é apenas uma diferença de duração. Uma ação curta também pode aparecer no imparfait quando descreve um hábito ou situação."],"ex":[["Il pleuvait très fort.","Estava chovendo muito."],["On a appelé un taxi.","Chamamos um táxi."]],"tip":"Pergunte: estou descrevendo como era a situação ou contando o que aconteceu?"},{"h":"Uma ação em andamento interrompida por outra","p":["Uma combinação muito comum é <b>imparfait + quand + passé composé</b>. O imparfait apresenta a ação que já estava acontecendo, enquanto o passé composé introduz um novo acontecimento.","Em português, frequentemente usamos “estava fazendo alguma coisa quando algo aconteceu”.","A ordem das duas partes pode mudar sem alterar o significado principal."],"ex":[["Je marchais quand la pluie a commencé.","Eu estava caminhando quando a chuva começou."],["Quand Lucas a appelé, je regardais un film.","Quando Lucas ligou, eu estava assistindo a um filme."]],"tip":"Depois de <b>quand</b>, não é obrigatório usar passé composé. O tempo depende de como você apresenta a ação."},{"h":"Sequência de acontecimentos","p":["Para narrar ações concluídas que aconteceram uma depois da outra, use o <b>passé composé</b>.","Palavras como <b>d'abord</b> (primeiro), <b>puis</b> (depois), <b>ensuite</b> (em seguida) e <b>finalement</b> (por fim) ajudam a organizar a história.","Entre esses acontecimentos, você pode inserir frases no imparfait para descrever o ambiente ou a situação."],"ex":[["D'abord, on a cherché un café.","Primeiro, procuramos um café."],["Puis, le taxi est arrivé.","Depois, o táxi chegou."]],"tip":"Uma história natural costuma alternar descrições no imparfait e acontecimentos no passé composé."},{"h":"Pendant que: enquanto","p":["<b>Pendant que</b> significa “enquanto” e permite relacionar duas ações no passado.","Quando duas ações estavam acontecendo ao mesmo tempo, podemos usar imparfait nas duas. Quando um acontecimento ocorre durante uma situação em andamento, podemos combinar imparfait e passé composé.","A expressão pode aparecer no início ou no meio da frase."],"ex":[["Pendant que je marchais, Claire regardait les vitrines.","Enquanto eu caminhava, Claire olhava as vitrines."],["Pendant qu'on attendait, elle a appelé un taxi.","Enquanto esperávamos, ela chamou um táxi."]],"tip":"<b>Pendant que</b> introduz uma oração com verbo. Já <b>pendant</b>, sozinho, pode indicar duração."}],"vocab":[{"h":"Chuva e imprevistos","items":[["la pluie","a chuva"],["pleuvoir","chover"],["un parapluie","um guarda-chuva"],["une averse","uma pancada de chuva"],["un arrêt de bus","um ponto de ônibus"],["un taxi","um táxi"],["fermé / fermée","fechado / fechada"],["mouillé / mouillée","molhado / molhada"]]},{"h":"Conectores para contar histórias","items":[["quand","quando"],["pendant que","enquanto"],["d'abord","primeiro"],["puis","depois"],["ensuite","em seguida"],["tout à coup","de repente"],["finalement","finalmente / por fim"],["plus tard","mais tarde / depois"]]},{"h":"Expressões para descrever situações","items":[["il pleuvait","estava chovendo"],["il faisait froid","estava frio"],["il faisait beau","o tempo estava bom"],["j'avais froid","eu estava com frio"],["au chaud","quentinho / em lugar aquecido"],["tout était fermé","estava tudo fechado"]]}],"pron":[{"h":"quand","p":"A palavra <b>quand</b> tem vogal nasal, aproximadamente “cã”. O d final normalmente é mudo. Antes de vogal, pode ocorrer uma ligação com som de t.","w":["quand","quand il","quand j'étais petit"]},{"h":"pleuvait e pluie","p":"Em <b>pleuvait</b>, o grupo eu tem um som sem equivalente exato em português, com os lábios arredondados; soa aproximadamente “plë-VÉ”. Em <b>pluie</b>, soa aproximadamente “plüi”.","w":["il pleuvait","la pluie","pleuvoir"]},{"h":"était e arrivé","p":"Em <b>était</b>, a terminação -ait soa como um é aberto. Em <b>arrivé</b>, a terminação -é é mais fechada.","w":["il était","il est arrivé","elle regardait","elle a regardé"]}],"mc":[{"q":"O que Claire fazia quando começou a chover?","o":["Esperava um ônibus","Caminhava no parque","Tomava um café"],"a":1,"e":"Samedi, je marchais dans le parc quand il a commencé à pleuvoir."},{"q":"Por que Claire e sua amiga não entraram num café?","o":["Estava tudo fechado","Não tinham dinheiro","Estavam com pressa"],"a":0,"e":"On a cherché un café, mais tout était fermé."},{"q":"O que a amiga fez enquanto esperavam?","o":["Comprou um guarda-chuva","Ligou para Lucas","Chamou um táxi"],"a":2,"e":"Pendant qu'on attendait, mon amie a appelé un taxi."},{"q":"O que fizeram em casa?","o":["Assistiram a um filme","Prepararam chá","Prepararam o jantar"],"a":1,"e":"On est rentrées chez moi et on a préparé du thé."}],"gaps":[{"s":"Je ___ dans le parc quand il a commencé à pleuvoir.","a":["marchais"],"h":"Eu estava caminhando no parque quando começou a chover."},{"s":"Il a ___ à pleuvoir samedi.","a":["commencé"],"h":"Começou a chover no sábado."},{"s":"Pendant qu'on ___, elle a appelé un taxi.","a":["attendait"],"h":"Enquanto a gente esperava, ela chamou um táxi."},{"s":"Il ___ encore quand le taxi est arrivé.","a":["pleuvait"],"h":"Ainda estava chovendo quando o táxi chegou."},{"s":"Le café ___ fermé quand nous sommes arrivés.","a":["était"],"h":"O café estava fechado quando chegamos."},{"s":"Claire et son amie sont ___ chez Claire.","a":["rentrées"],"h":"Claire e sua amiga voltaram para a casa de Claire."}],"order":[{"t":["Il","pleuvait","quand","je","suis","arrivé."],"h":"Estava chovendo quando cheguei."},{"t":["Nous","parlions","quand","le","bus","est","arrivé."],"h":"Conversávamos quando o ônibus chegou."},{"t":["Elle","a","appelé","un","taxi."],"h":"Ela chamou um táxi."}],"dict":[{"t":"Il pleuvait très fort."},{"t":"Nous marchions dans le parc."},{"t":"Le café était fermé."},{"t":"Elle a appelé un taxi."},{"t":"Pendant qu'on attendait, il faisait froid."}],"shadow":["Samedi, je marchais dans le parc quand il a commencé à pleuvoir.","Non ! On a cherché un café, mais tout était fermé.","Pendant qu'on attendait, mon amie a appelé un taxi.","On est rentrées chez moi et on a préparé du thé."],"write":{"task":"Conte um pequeno imprevisto que aconteceu com você. Descreva onde estava e o que estava fazendo quando algo aconteceu. Depois, conte duas ou três ações que vieram em seguida. Use pelo menos dois verbos no imparfait e dois no passé composé.","ph":"Un jour, j'étais … quand …"},"cards":[["Chovia quando saí.","Il pleuvait quand je suis parti."],["Eu estava no parque quando começou a chover.","J'étais au parc quand il a commencé à pleuvoir."],["Enquanto esperávamos, ela ligou.","Pendant qu'on attendait, elle a appelé."],["Todos os cafés estavam fechados.","Tous les cafés étaient fermés."],["Não tínhamos guarda-chuva.","Nous n'avions pas de parapluie."],["O táxi chegou dez minutos depois.","Le taxi est arrivé dix minutes plus tard."],["Primeiro, procuramos um café.","D'abord, on a cherché un café."],["Naquele momento, eu estava com frio.","À ce moment-là, j'avais froid."],["Eu caminhava quando vi Lucas.","Je marchais quand j'ai vu Lucas."],["Depois, elas voltaram para casa.","Ensuite, elles sont rentrées à la maison."]]},{"title":"Les vêtements","goal":"Comparar roupas, preços, tamanhos e estilos usando plus, moins e aussi... que, além de posicionar e concordar corretamente os adjetivos em francês.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Em uma loja de roupas no centro da cidade, Claire procura um casaco para o inverno. Lucas a ajuda a comparar diferentes modelos.","lines":[["Claire","J'ai besoin d'un manteau pour l'hiver. Regarde ces deux modèles.","Preciso de um casaco para o inverno. Olha estes dois modelos."],["Lucas","Le bleu est plus élégant que le noir.","O azul é mais elegante que o preto."],["Claire","Oui, mais le noir est moins cher que le bleu.","Sim, mas o preto é mais barato que o azul."],["Lucas","Tu peux essayer les deux.","Você pode experimentar os dois."],["Claire","Le bleu est plus grand, mais le noir est aussi confortable.","O azul é maior, mas o preto é igualmente confortável."],["Lucas","Je trouve le noir plus joli. Il est à ta taille.","Acho o preto mais bonito. Ele é do seu tamanho."],["Claire","Et cette veste rouge ? Elle est plus courte que les manteaux.","E esta jaqueta vermelha? Ela é mais curta que os casacos."],["Lucas","Oui, et elle est moins chaude. Pour l'hiver, ce n'est pas idéal.","Sim, e ela é menos quente. Para o inverno, não é ideal."],["Claire","Tu as raison. Je préfère un manteau long et chaud.","Você tem razão. Prefiro um casaco comprido e quente."],["Lucas","Regarde aussi ces chaussures ! Elles sont jolies.","Olha também estes sapatos! São bonitos."],["Claire","Oui, mais les noires sont moins confortables que les blanches.","Sim, mas os pretos são menos confortáveis que os brancos."],["Lucas","Alors, on reste sur les manteaux ?","Então, vamos continuar olhando os casacos?"],["Claire","Oui. Je vais prendre le noir : il est simple et pratique.","Sim. Vou levar o preto: ele é simples e prático."],["Lucas","Bon choix ! Et il est moins cher.","Boa escolha! E ele é mais barato."]],"grammar":[{"h":"Comparativo de superioridade: plus... que","p":["Para dizer que uma coisa é <b>mais</b> alguma coisa do que outra, use <b>plus + adjetivo + que</b>.","A estrutura funciona com diversos adjetivos: <b>plus grand que</b> (maior que), <b>plus cher que</b> (mais caro que), <b>plus élégant que</b> (mais elegante que).","O adjetivo concorda com o substantivo descrito. Assim, podemos dizer <b>plus grand</b> para um casaco e <b>plus grande</b> para uma jaqueta."],"ex":[["Ce manteau est plus cher que l'autre.","Este casaco é mais caro que o outro."],["Cette veste est plus grande que la noire.","Esta jaqueta é maior que a preta."],["Ces chaussures sont plus élégantes.","Estes sapatos são mais elegantes."]],"tip":"O <b>que</b> francês corresponde ao “que” de comparação em português. Não use <b>de</b> no lugar dele nessa estrutura."},{"h":"Comparativo de inferioridade: moins... que","p":["Para dizer que uma característica aparece em menor grau, use <b>moins + adjetivo + que</b>. Em português, corresponde a “menos... que”.","Essa estrutura é muito útil para comparar preços. <b>Moins cher</b> significa “menos caro”, mas a tradução mais natural costuma ser “mais barato”.","Assim como em plus... que, o adjetivo continua concordando com o substantivo que está sendo descrito."],"ex":[["Le pantalon gris est moins cher que le bleu.","A calça cinza é mais barata que a azul."],["Cette veste est moins chaude.","Esta jaqueta é menos quente."],["Ces chaussures sont moins confortables.","Estes sapatos são menos confortáveis."]],"tip":"Use <b>moins cher</b> para dizer “mais barato”."},{"h":"Comparativo de igualdade: aussi... que","p":["Para dizer que duas coisas têm uma característica no mesmo grau, use <b>aussi + adjetivo + que</b>, equivalente a “tão... quanto”.","A estrutura não muda no plural ou no feminino, mas o adjetivo precisa concordar normalmente.","Não confunda o <b>aussi</b> de comparação com seu outro uso, “também”. O contexto mostra o significado."],"ex":[["Ce manteau est aussi chaud que l'autre.","Este casaco é tão quente quanto o outro."],["Cette robe est aussi jolie que la bleue.","Este vestido é tão bonito quanto o azul."],["Ces chaussures sont aussi confortables que les noires.","Estes sapatos são tão confortáveis quanto os pretos."]],"tip":"Memorize as três estruturas juntas: <b>plus... que</b> (mais), <b>moins... que</b> (menos) e <b>aussi... que</b> (tão... quanto)."},{"h":"Posição e concordância dos adjetivos","p":["Em francês, a maioria dos adjetivos vem <b>depois do substantivo</b>: <b>un manteau noir</b> (um casaco preto), <b>une veste rouge</b> (uma jaqueta vermelha) e <b>des chaussures confortables</b> (sapatos confortáveis).","Alguns adjetivos frequentes aparecem geralmente <b>antes do substantivo</b>, como <b>petit</b> (pequeno), <b>grand</b> (grande), <b>joli</b> (bonito) e <b>beau</b> (belo).","Os adjetivos concordam em gênero e número: <b>noir → noire → noirs → noires</b>. Em geral, acrescentamos <b>-e</b> no feminino e <b>-s</b> no plural, embora existam formas irregulares, como <b>beau → belle</b>."],"ex":[["Elle porte une jolie robe noire.","Ela usa um vestido preto bonito."],["Il cherche un grand manteau gris.","Ele procura um casaco cinza grande."],["Ces vestes sont courtes et légères.","Estas jaquetas são curtas e leves."],["C'est une belle chemise blanche.","É uma bela camisa branca."]],"tip":"Cores geralmente ficam depois do substantivo: <b>une robe rouge</b>, <b>un pantalon bleu</b>. A cor <b>marron</b> normalmente não varia."}],"vocab":[{"h":"Roupas e acessórios","items":[["un manteau","um casaco"],["une veste","uma jaqueta"],["un pantalon","uma calça"],["une chemise","uma camisa"],["un tee-shirt","uma camiseta"],["une robe","um vestido"],["une jupe","uma saia"],["des chaussures","sapatos / calçados"],["un pull","um suéter"],["une écharpe","um cachecol"]]},{"h":"Características das roupas","items":[["cher / chère","caro / cara"],["grand / grande","grande"],["court / courte","curto / curta"],["long / longue","comprido / comprida"],["chaud / chaude","quente"],["léger / légère","é leve"],["élégant / élégante","elegante"],["confortable","confortável"],["serré / serrée","apertado / apertada"],["large","largo / larga"]]},{"h":"Na loja de roupas","items":[["essayer","experimentar"],["une taille","um tamanho / uma numeração"],["un modèle","um modelo"],["une cabine d'essayage","um provador"],["un prix","um preço"],["une réduction","um desconto"],["à ma taille","do meu tamanho"],["en soldes","em promoção / liquidação"]]}],"pron":[{"h":"plus: quando pronunciar o s","p":"Na comparação, antes de adjetivo iniciado por consoante, o s de <b>plus</b> normalmente é mudo: <b>plus cher</b> soa aproximadamente “plü chér”. Antes de vogal, geralmente há ligação com som de z.","w":["plus cher","plus grand","plus élégant","plus original"]},{"h":"chaud e chaude","p":"No masculino <b>chaud</b>, o d final é mudo: aproximadamente “chô”. No feminino <b>chaude</b>, o d é pronunciado: “chôd”.","w":["un manteau chaud","une veste chaude","des chaussures chaudes"]},{"h":"moins e aussi","p":"<b>Moins</b> tem vogal nasal e soa aproximadamente “muã”, normalmente sem pronunciar o s final. <b>Aussi</b> soa “o-ssi”, com som forte de s.","w":["moins cher","moins confortable","aussi joli","aussi élégant"]}],"mc":[{"q":"Qual casaco Lucas considera mais elegante?","o":["O preto","O vermelho","O azul"],"a":2,"e":"Le bleu est plus élégant que le noir."},{"q":"Qual dos dois casacos é mais barato?","o":["O preto","O azul","Têm o mesmo preço"],"a":0,"e":"Oui, mais le noir est moins cher que le bleu."},{"q":"Por que a jaqueta vermelha não é ideal para o inverno?","o":["É muito cara","É menos quente","É muito grande"],"a":1,"e":"Oui, et elle est moins chaude. Pour l'hiver, ce n'est pas idéal."},{"q":"Qual casaco Claire decide comprar?","o":["O azul","O vermelho","O preto"],"a":2,"e":"Oui. Je vais prendre le noir : il est simple et pratique."}],"gaps":[{"s":"Le manteau bleu est ___ élégant que le noir.","a":["plus"],"h":"O casaco azul é mais elegante que o preto."},{"s":"Le manteau noir est ___ cher que le bleu.","a":["moins"],"h":"O casaco preto é mais barato que o azul."},{"s":"Cette veste est aussi confortable ___ l'autre.","a":["que"],"h":"Esta jaqueta é tão confortável quanto a outra."},{"s":"Cette veste est plus ___ que ce manteau.","a":["courte"],"h":"Esta jaqueta é mais curta que este casaco."},{"s":"Les chaussures noires sont moins ___ que les blanches.","a":["confortables"],"h":"Os sapatos pretos são menos confortáveis que os brancos."},{"s":"Elle porte une ___ veste rouge.","a":["jolie"],"h":"Ela está usando uma jaqueta vermelha bonita."}],"order":[{"t":["Le","manteau","noir","est","moins","cher."],"h":"O casaco preto é mais barato."},{"t":["Cette","veste","est","plus","courte."],"h":"Esta jaqueta é mais curta."},{"t":["Ces","chaussures","sont","aussi","confortables","que","les","autres."],"h":"Estes sapatos são tão confortáveis quanto os outros."}],"dict":[{"t":"Ce manteau est plus cher que l'autre."},{"t":"Cette veste est moins chaude."},{"t":"Les chaussures sont aussi confortables."},{"t":"Je préfère une jolie robe noire."},{"t":"Ces pantalons sont trop grands."}],"shadow":["Le bleu est plus élégant que le noir.","Oui, mais le noir est moins cher que le bleu.","Et cette veste rouge ? Elle est plus courte que les manteaux.","Oui, mais les noires sont moins confortables que les blanches."],"write":{"task":"Imagine que você está escolhendo roupas em uma loja. Compare dois casacos, duas calças ou dois pares de sapatos. Escreva de quatro a seis frases, usando plus... que, moins... que e aussi... que. Inclua pelo menos um adjetivo no feminino e outro no plural.","ph":"Je préfère ce manteau parce qu'il est plus …"},"cards":[["Esta camisa é mais bonita que a outra.","Cette chemise est plus jolie que l'autre."],["Estes sapatos são mais baratos.","Ces chaussures sont moins chères."],["Esta calça é muito apertada.","Ce pantalon est trop serré."],["Este vestido é tão elegante quanto o outro.","Cette robe est aussi élégante que l'autre."],["Estou procurando um casaco mais quente.","Je cherche un manteau plus chaud."],["Esta saia é mais curta que a minha.","Cette jupe est plus courte que la mienne."],["Essas jaquetas são muito grandes.","Ces vestes sont trop grandes."],["Posso experimentar este suéter?","Je peux essayer ce pull ?"],["Você tem um tamanho menor?","Vous avez une taille plus petite ?"],["Prefiro roupas simples e confortáveis.","Je préfère les vêtements simples et confortables."]]},{"title":"Le meilleur","goal":"Descrever e comparar lugares, identificar o melhor, o mais bonito ou o menos caro e expressar preferências usando o superlativo, meilleur e mieux.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Em uma tarde de sábado, Claire mostra seu bairro a Lucas. Enquanto passeiam, os dois conversam sobre os melhores lugares para comer, caminhar e passar o tempo livre.","lines":[["Claire","Alors, tu aimes mon quartier ?","Então, você está gostando do meu bairro?"],["Lucas","Oui ! C'est le quartier le plus calme de la ville ?","Sim! É o bairro mais tranquilo da cidade?"],["Claire","Peut-être ! Pour moi, c'est surtout le plus agréable.","Talvez! Para mim, é principalmente o mais agradável."],["Lucas","Et ce parc ? C'est le plus grand du quartier ?","E este parque? É o maior do bairro?"],["Claire","Oui, et c'est aussi le plus beau !","Sim, e também é o mais bonito!"],["Lucas","J'ai vu une boulangerie près de la place.","Vi uma padaria perto da praça."],["Claire","C'est la meilleure boulangerie du quartier !","É a melhor padaria do bairro!"],["Lucas","Ah oui ? Les croissants sont bons ?","É mesmo? Os croissants são bons?"],["Claire","Ils sont excellents ! Et le café est très bon.","São excelentes! E o café é muito bom."],["Lucas","Et pour déjeuner, quel est le restaurant le moins cher ?","E para almoçar, qual é o restaurante mais barato?"],["Claire","Le restaurant sur la place. Mais on mange mieux au bistrot près du parc.","O restaurante da praça. Mas a comida é melhor no bistrô perto do parque."],["Lucas","D'accord, on va au bistrot. Il est loin ?","Tá bom, vamos ao bistrô. É longe?"],["Claire","Non, à cinq minutes à pied. Et c'est le meilleur endroit pour déjeuner ici.","Não, fica a cinco minutos a pé. E é o melhor lugar para almoçar por aqui."],["Lucas","Parfait ! Après, on fait un tour dans le parc ?","Perfeito! Depois, a gente dá uma volta no parque?"]],"grammar":[{"h":"Superlativo de superioridade: le plus, la plus, les plus","p":["Para destacar uma coisa dentro de um grupo, usamos o <b>superlativo</b>: <b>le plus, la plus ou les plus + adjetivo</b>.","O artigo concorda com o substantivo: <b>le plus grand</b>, <b>la plus grande</b>, <b>les plus grands</b> e <b>les plus grandes</b>. O adjetivo também concorda normalmente.","Para indicar o grupo, usamos frequentemente <b>de</b>: <b>de la ville</b>, <b>du quartier</b> e <b>des restaurants</b>. O superlativo pode aparecer depois do substantivo ou antes dele com adjetivos que costumam ocupar essa posição."],"ex":[["C'est le parc le plus calme du quartier.","É o parque mais tranquilo do bairro."],["C'est la plus jolie place du centre.","É a praça mais bonita do centro."],["Ce sont les rues les plus animées de la ville.","São as ruas mais movimentadas da cidade."]],"tip":"Compare: <b>plus grand que</b> = “maior que”; <b>le plus grand de</b> = “o maior de”."},{"h":"Superlativo de inferioridade: le moins, la moins, les moins","p":["Para indicar o menor grau de uma característica dentro de um grupo, use <b>le moins, la moins ou les moins + adjetivo</b>.","Essa estrutura equivale a “o menos”, “a menos”, “os menos” ou “as menos”.","<b>Le moins cher</b> significa literalmente “o menos caro”, mas costuma ser traduzido como “o mais barato”. O artigo e o adjetivo concordam com o substantivo."],"ex":[["C'est le restaurant le moins cher du quartier.","É o restaurante mais barato do bairro."],["Cette rue est la moins bruyante.","Esta rua é a menos barulhenta."],["Ce sont les hôtels les moins chers du centre.","São os hotéis mais baratos do centro."]],"tip":"<b>Moins cher que</b> = “mais barato que”; <b>le moins cher</b> = “o mais barato”."},{"h":"Bon, meilleur e le meilleur","p":["O adjetivo <b>bon</b> (bom) tem uma forma comparativa especial: <b>meilleur</b> (melhor). Em vez de plus bon, normalmente usamos <b>meilleur que</b>.","Para formar o superlativo, usamos <b>le meilleur</b>, <b>la meilleure</b>, <b>les meilleurs</b> ou <b>les meilleures</b>.","Como meilleur é um adjetivo, ele concorda em gênero e número com o substantivo que acompanha."],"ex":[["Ce café est meilleur que le café du musée.","Este café é melhor que o café do museu."],["C'est la meilleure boulangerie du quartier.","É a melhor padaria do bairro."],["Ces croissants sont les meilleurs de la ville.","Estes croissants são os melhores da cidade."]],"tip":"Memorize: <b>bon → meilleur → le meilleur</b>. No feminino: <b>bonne → meilleure → la meilleure</b>."},{"h":"Bien, mieux e le mieux","p":["Enquanto <b>meilleur</b> é o comparativo do adjetivo bon, <b>mieux</b> é o comparativo de <b>bien</b> (bem).","Use <b>meilleur</b> para dizer que algo é melhor, e <b>mieux</b> para dizer que uma ação é realizada melhor: <b>un meilleur restaurant</b>, mas <b>on mange mieux</b>.","O superlativo de bien é <b>le mieux</b>. Diferentemente de meilleur, <b>mieux</b> não muda no feminino ou no plural."],"ex":[["On mange mieux dans ce bistrot.","A comida é melhor neste bistrô."],["Tu parles mieux français maintenant.","Você fala francês melhor agora."],["Dans ce quartier, on mange le mieux ici.","Neste bairro, é aqui que se come melhor."],["C'est mieux comme ça.","É melhor assim."]],"tip":"<b>Bon → meilleur</b> para qualidades; <b>bien → mieux</b> para a maneira de realizar uma ação."}],"vocab":[{"h":"Lugares da cidade","items":[["un quartier","um bairro"],["une place","uma praça"],["un parc","um parque"],["une boulangerie","uma padaria"],["un bistrot","um bistrô"],["un restaurant","um restaurante"],["une rue","uma rua"],["un musée","um museu"],["une terrasse","uma área externa com mesas"],["le centre-ville","o centro da cidade"]]},{"h":"Características dos lugares","items":[["calme","tranquilo / tranquila"],["animé / animée","movimentado / movimentada"],["agréable","agradável"],["bruyant / bruyante","barulhento / barulhenta"],["propre","limpo / limpa"],["cher / chère","caro / cara"],["intéressant / intéressante","interessante"],["touristique","turístico / turística"],["accueillant / accueillante","acolhedor / acolhedora"],["pratique","prático / prática"]]},{"h":"Expressões para dar opiniões e comparar","items":[["à mon avis","na minha opinião"],["pour moi","para mim"],["je trouve que","eu acho que"],["surtout","principalmente"],["vraiment","realmente / muito"],["près de","perto de"],["à côté de","ao lado de"],["à pied","a pé"],["meilleur / meilleure","melhor"],["mieux","melhor / de maneira melhor"]]}],"pron":[{"h":"plus no superlativo","p":"Em <b>le plus grand</b>, o s de plus normalmente não é pronunciado. Antes de vogal, costuma ocorrer uma ligação com som de z: <b>le plus agréable</b>.","w":["le plus grand","la plus belle","le plus agréable","les plus intéressants"]},{"h":"meilleur e meilleure","p":"As formas <b>meilleur</b> e <b>meilleure</b> têm a mesma pronúncia, aproximadamente “mè-iêr”, com o último som vocálico produzido com os lábios arredondados.","w":["meilleur","meilleure","le meilleur café","la meilleure boulangerie"]},{"h":"mieux","p":"<b>Mieux</b> tem uma sílaba só, aproximadamente “miê”, mas com os lábios arredondados no final. O x normalmente é mudo. Antes de vogal, pode ocorrer ligação com som de z.","w":["mieux","c'est mieux","on mange mieux","mieux ici"]}],"mc":[{"q":"O que Lucas pergunta sobre o bairro?","o":["Se é o mais movimentado","Se é o mais tranquilo","Se é o mais antigo"],"a":1,"e":"C'est le quartier le plus calme de la ville ?"},{"q":"Onde fica a padaria que Claire recomenda?","o":["Perto da praça","Perto do museu","Dentro do parque"],"a":0,"e":"J'ai vu une boulangerie près de la place. C'est la meilleure boulangerie du quartier !"},{"q":"Onde fica o restaurante mais barato?","o":["Perto do museu","No parque","Na praça"],"a":2,"e":"Le restaurant sur la place."},{"q":"Por que Claire recomenda o bistrô?","o":["É o mais barato","Lá se come melhor","Fica no museu"],"a":1,"e":"Mais on mange mieux au bistrot près du parc."}],"gaps":[{"s":"C'est le quartier le ___ calme de la ville.","a":["plus"],"h":"É o bairro mais tranquilo da cidade."},{"s":"Cette place est la ___ grande du quartier.","a":["plus"],"h":"Esta praça é a maior do bairro."},{"s":"C'est la ___ boulangerie du quartier.","a":["meilleure"],"h":"É a melhor padaria do bairro."},{"s":"Dans ce bistrot, on mange ___.","a":["mieux"],"h":"Neste bistrô, se come melhor."},{"s":"Ces rues sont les plus ___ du centre.","a":["animées"],"h":"Estas ruas são as mais movimentadas do centro."},{"s":"Ce café est ___ que le café du musée.","a":["meilleur"],"h":"Este café é melhor que o café do museu."}],"order":[{"t":["C'est","le","plus","beau","parc","du","quartier."],"h":"É o parque mais bonito do bairro."},{"t":["On","mange","mieux","dans","ce","bistrot."],"h":"A comida é melhor neste bistrô."},{"t":["Cette","boulangerie","est","la","meilleure","du","centre."],"h":"Esta padaria é a melhor do centro."}],"dict":[{"t":"C'est le quartier le plus calme."},{"t":"Cette place est la plus jolie."},{"t":"C'est le restaurant le moins cher."},{"t":"Nous mangeons mieux ici."},{"t":"Cette boulangerie est la meilleure du quartier."}],"shadow":["Oui ! C'est le quartier le plus calme de la ville ?","Peut-être ! Pour moi, c'est surtout le plus agréable.","C'est la meilleure boulangerie du quartier !","Le restaurant sur la place. Mais on mange mieux au bistrot près du parc."],"write":{"task":"Descreva seu bairro ou uma cidade que você conhece. Indique o lugar mais bonito, o mais tranquilo, o restaurante mais barato e o melhor lugar para comer. Escreva cinco ou seis frases usando pelo menos dois superlativos, uma forma de meilleur e uma frase com mieux.","ph":"Dans mon quartier, le plus bel endroit est …"},"cards":[["É a rua mais movimentada do bairro.","C'est la rue la plus animée du quartier."],["Este museu é o mais interessante da cidade.","Ce musée est le plus intéressant de la ville."],["Na minha opinião, é a praça mais bonita.","À mon avis, c'est la plus belle place."],["Este parque é o menos barulhento.","Ce parc est le moins bruyant."],["O pão é melhor aqui.","Le pain est meilleur ici."],["A gente come melhor perto do mercado.","On mange mieux près du marché."],["É o melhor café do centro.","C'est le meilleur café du centre."],["São os melhores restaurantes da cidade.","Ce sont les meilleurs restaurants de la ville."],["Este terraço é o mais agradável.","Cette terrasse est la plus agréable."],["Qual é o lugar mais tranquilo ?","Quel est l'endroit le plus calme ?"]]},{"title":"Chez moi","goal":"Apresentar os cômodos da casa, descrever um apartamento e usar os pronomes le, la, l' e les para substituir objetos diretos, evitando repetições em frases afirmativas, negativas e com infinitivo.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Em uma tarde de sábado, Lucas visita o apartamento de Claire pela primeira vez. Ela mostra os cômodos e conta como usa os espaços da casa.","lines":[["Claire","Bienvenue chez moi ! Tu veux visiter l'appartement ?","Bem-vindo à minha casa! Quer conhecer o apartamento?"],["Lucas","Avec plaisir ! Le salon est où ?","Com prazer! Onde fica a sala?"],["Claire","Il est à droite. Tu le vois ?","Fica à direita. Está vendo?"],["Lucas","Oui, je le vois. J'aime beaucoup la fenêtre !","Sim, estou vendo. Gosto muito da janela!"],["Claire","Moi aussi, je l'aime. Elle donne sur le jardin.","Eu também gosto dela. Ela dá para o jardim."],["Lucas","Et la cuisine, tu l'utilises souvent ?","E a cozinha, você usa bastante?"],["Claire","Oui, tous les jours. Je la trouve très pratique.","Sim, todos os dias. Acho ela muito prática."],["Lucas","Les deux chambres sont au fond du couloir ?","Os dois quartos ficam no fim do corredor?"],["Claire","Exactement. Tu veux les voir ?","Exatamente. Quer ver os quartos?"],["Lucas","Oui, mais je ne les vois pas d'ici.","Sim, mas não consigo vê-los daqui."],["Claire","Viens, on va les visiter ensemble.","Vem, vamos conhecer os quartos juntos."],["Lucas","Et la salle de bains, elle est où ?","E o banheiro, onde fica?"],["Claire","À gauche, juste avant les chambres. Tu peux la voir aussi.","À esquerda, logo antes dos quartos. Você pode ver também."],["Lucas","Super ! Ton appartement est vraiment agréable.","Que legal! Seu apartamento é muito agradável."]],"grammar":[{"h":"Pronomes de objeto direto: le, la e les","p":["Em francês, os pronomes de objeto direto, chamados <b>COD (complément d'objet direct)</b>, substituem pessoas ou coisas que recebem diretamente a ação de um verbo, sem preposição.","Use <b>le</b> para um substantivo masculino singular, <b>la</b> para um feminino singular e <b>les</b> para o plural, masculino ou feminino.","Diferentemente do português, esses pronomes normalmente aparecem <b>antes do verbo conjugado</b>: <b>Je regarde le salon → Je le regarde.</b>","Le, la e les também podem ser artigos. Antes de um substantivo, são artigos; antes de um verbo, nos exemplos desta unidade, são pronomes."],"ex":[["Tu vois le salon ? Oui, je le vois.","Você está vendo a sala? Sim, estou vendo."],["Tu connais la cuisine ? Oui, je la connais.","Você conhece a cozinha? Sim, conheço."],["Tu vois les chambres ? Oui, je les vois.","Você está vendo os quartos? Sim, estou vendo."]],"tip":"Memorize: <b>le</b> substitui um masculino singular, <b>la</b> um feminino singular e <b>les</b> qualquer plural."},{"h":"L': antes de vogal ou h mudo","p":["Quando <b>le</b> ou <b>la</b> aparece antes de um verbo iniciado por vogal ou h mudo, usamos <b>l'</b>. Essa forma funciona tanto para masculino quanto para feminino.","Por exemplo, <b>la fenêtre</b> pode ser substituída por <b>l'</b> em <b>Je l'aime</b>. O mesmo acontece com <b>le canapé</b> em <b>Je l'utilise</b>.","O pronome plural <b>les</b> nunca se transforma em l', mesmo antes de uma vogal."],"ex":[["La fenêtre ? Je l'aime beaucoup.","A janela? Gosto muito dela."],["Le canapé ? Je l'utilise tous les jours.","O sofá? Eu uso todos os dias."],["Les chambres ? Je les adore.","Os quartos? Eu adoro."]],"tip":"Em <b>je l'aime</b>, l' pode significar “o” ou “a”. O contexto indica o objeto."},{"h":"Pronomes COD nas frases negativas","p":["Na negativa, o pronome de objeto direto continua antes do verbo. A estrutura é: <b>ne + pronome COD + verbo + pas</b>.","Compare: <b>Je vois le salon</b> (vejo a sala), <b>Je le vois</b> (eu a vejo) e <b>Je ne le vois pas</b> (não a vejo).","Quando o pronome é l', a negativa aparece como <b>je ne l'aime pas</b>. Observe que ne permanece antes do pronome."],"ex":[["Je ne le vois pas.","Não estou vendo."],["Elle ne la connaît pas.","Ela não a conhece."],["Nous ne les utilisons pas.","Nós não os usamos."]],"tip":"Na negativa, mantenha sempre o pronome junto do verbo: <b>je ne le vois pas</b>."},{"h":"Pronomes antes do infinitivo","p":["Quando uma frase apresenta um verbo conjugado seguido de outro no infinitivo, como <b>vouloir + infinitivo</b>, <b>pouvoir + infinitivo</b> ou <b>aller + infinitivo</b>, o pronome COD que completa o infinitivo aparece imediatamente antes dele.","Compare: <b>Je veux visiter le salon → Je veux le visiter.</b> O pronome le substitui le salon e fica antes de visiter, não de veux.","Essa regra também se aplica ao futur proche, estudado no A1: <b>On va visiter les chambres → On va les visiter.</b>","Na negativa, ne... pas envolve o verbo conjugado: <b>Je ne veux pas le visiter.</b>"],"ex":[["Je veux le visiter.","Quero conhecê-lo."],["On va les regarder.","Vamos olhar para eles."],["Tu peux la voir.","Você pode vê-la."],["Je ne veux pas l'utiliser.","Não quero usar isso."]],"tip":"Com dois verbos, identifique qual recebe o objeto: <b>Je peux la voir</b>. O pronome fica imediatamente antes do infinitivo voir."}],"vocab":[{"h":"Cômodos da casa","items":[["le salon","a sala de estar"],["la cuisine","a cozinha"],["la chambre","o quarto"],["la salle de bains","o banheiro"],["les toilettes","o banheiro / o lavabo"],["le couloir","o corredor"],["l'entrée","a entrada"],["le balcon","a varanda"]]},{"h":"Móveis e elementos da casa","items":[["le canapé","o sofá"],["la fenêtre","a janela"],["la porte","a porta"],["la table","a mesa"],["une étagère","uma prateleira / uma estante"],["un placard","um armário"],["un lit","uma cama"],["un tapis","um tapete"]]},{"h":"Ações e expressões em casa","items":[["visiter","visitar / conhecer"],["montrer","mostrar"],["voir","ver"],["utiliser","usar"],["ranger","arrumar / guardar"],["ouvrir","abrir"],["fermer","fechar"],["nettoyer","limpar"]]}],"pron":[{"h":"le, la e l'","p":"O pronome <b>le</b> soa aproximadamente “lë”, com vogal curta e lábios arredondados. <b>La</b> soa “la”. Antes de vogal, ambos se reduzem a <b>l'</b>.","w":["je le vois","je la vois","je l'aime","je l'utilise"]},{"h":"Liaison com les","p":"O s final de <b>les</b> é normalmente mudo antes de consoante. Antes de vogal ou h mudo, ocorre ligação com som de z.","w":["je les vois","je les utilise","tu les aimes","nous les ouvrons"]},{"h":"salon e couloir","p":"Em <b>salon</b>, o on final tem som nasal, aproximadamente “sa-lõ”. Em <b>couloir</b>, oi tem som de “uá”: aproximadamente “cu-luár”, com r francês.","w":["le salon","dans le salon","le couloir","au fond du couloir"]}],"mc":[{"q":"Onde fica a sala de estar de Claire?","o":["À esquerda","À direita","No fim do corredor"],"a":1,"e":"Il est à droite. Tu le vois ?"},{"q":"O que dá para o jardim?","o":["A porta do quarto","A varanda","A janela"],"a":2,"e":"Moi aussi, je l'aime. Elle donne sur le jardin."},{"q":"Onde ficam os dois quartos?","o":["No fim do corredor","Ao lado da entrada","À direita da cozinha"],"a":0,"e":"Les deux chambres sont au fond du couloir ?"},{"q":"Onde fica o banheiro?","o":["Ao lado da sala","À esquerda, antes dos quartos","No fim da cozinha"],"a":1,"e":"À gauche, juste avant les chambres. Tu peux la voir aussi."}],"gaps":[{"s":"Le salon ? Je ___ vois.","a":["le"],"h":"A sala? Estou vendo."},{"s":"La fenêtre ? Je ___ aime beaucoup.","a":["l'"],"h":"A janela? Gosto muito dela."},{"s":"Les chambres ? Je ne ___ vois pas.","a":["les"],"h":"Os quartos? Não estou vendo."},{"s":"La cuisine ? On va ___ visiter.","a":["la"],"h":"A cozinha? Vamos conhecê-la."},{"s":"Le balcon ? Tu veux ___ voir ?","a":["le"],"h":"A varanda? Quer vê-la?"},{"s":"La porte ? Je vais ___ abrir.","a":["l'"],"h":"A porta? Vou abri-la."}],"order":[{"t":["Je","ne","le","vois","pas","d'ici."],"h":"Não consigo vê-lo daqui."},{"t":["On","va","les","visiter","ensemble."],"h":"Vamos conhecê-los juntos."},{"t":["Tu","peux","la","voir","aussi."],"h":"Você pode vê-la também."}],"dict":[{"t":"Tu le vois ?"},{"t":"Je l'aime beaucoup."},{"t":"Je ne les vois pas d'ici."},{"t":"On va les visiter."},{"t":"La salle de bains est à gauche."}],"shadow":["Bienvenue chez moi ! Tu veux visiter l'appartement ?","Moi aussi, je l'aime. Elle donne sur le jardin.","Oui, mais je ne les vois pas d'ici.","Viens, on va les visiter ensemble."],"write":{"task":"Descreva sua casa ou seu apartamento em cinco ou seis frases. Fale de dois cômodos e de alguns móveis que você tem. Depois, use le, la, l' e les para evitar repetir os nomes desses objetos. Inclua pelo menos uma frase negativa e outra com vouloir, pouvoir ou aller + infinitivo.","ph":"Chez moi, il y a … Je l'aime parce que …"},"cards":[["Você conhece a sala? Sim, conheço.","Tu connais le salon ? Oui, je le connais."],["A cozinha? Eu uso todos os dias.","La cuisine ? Je l'utilise tous les jours."],["Os quartos? Quero vê-los.","Les chambres ? Je veux les voir."],["Não estou vendo a porta.","Je ne vois pas la porte."],["Esta mesa é bonita. Vou comprá-la.","Cette table est jolie. Je vais l'acheter."],["O sofá? Não gosto dele.","Le canapé ? Je ne l'aime pas."],["As janelas? Vou abri-las.","Les fenêtres ? Je vais les ouvrir."],["Este armário é grande. Eu o uso bastante.","Ce placard est grand. Je l'utilise souvent."],["A varanda fica à direita. Você consegue vê-la?","Le balcon est à droite. Tu peux le voir ?"],["Essas cadeiras são práticas. Vou guardá-las.","Ces chaises sont pratiques. Je vais les ranger."]]},{"title":"Entre amis","goal":"Conversar sobre amigos, transmitir informações, fazer pedidos e dizer a quem você telefonou ou enviou uma mensagem, usando os pronomes indiretos lui e leur com verbos como dire, demander e téléphoner à.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Na sexta-feira, Claire e Lucas organizam um jantar com amigos para o sábado. Eles conversam sobre os convites, as mensagens enviadas e o que ainda precisam combinar.","lines":[["Claire","Tu as parlé à ta sœur pour le dîner de samedi soir ?","Você conversou com sua irmã sobre o jantar de sábado à noite?"],["Lucas","Oui, je lui ai téléphoné hier soir après le travail.","Sim, liguei para ela ontem à noite, depois do trabalho."],["Claire","Tu lui as dit l'heure du dîner ?","Você disse a ela o horário do jantar?"],["Lucas","Oui, je lui ai dit l'heure et je lui ai donné l'adresse.","Sim, disse o horário e passei o endereço para ela."],["Claire","Et nos amis, tu leur as envoyé un message ?","E os nossos amigos, você mandou uma mensagem para eles?"],["Lucas","Oui, je leur ai envoyé l'adresse et une photo du salon.","Sim, mandei o endereço e uma foto da sala para eles."],["Claire","Très bien ! Ils ont répondu ?","Muito bem! Eles responderam?"],["Lucas","Pas encore. Je vais leur téléphoner ce soir.","Ainda não. Vou ligar para eles hoje à noite."],["Claire","Tu peux leur demander d'apporter des boissons ?","Você pode pedir para eles trazerem bebidas?"],["Lucas","Bien sûr. Je vais leur demander d'apporter du jus.","Claro. Vou pedir para eles trazerem suco."],["Claire","Et ta sœur, elle aime les pâtes ?","E sua irmã, ela gosta de macarrão?"],["Lucas","Oui, je lui ai demandé. Elle adore les pâtes !","Sim, perguntei para ela. Ela adora macarrão!"],["Claire","Parfait ! Et ton frère, il vient aussi samedi ?","Perfeito! E seu irmão, ele também vem no sábado?"],["Lucas","Je ne lui ai pas encore parlé. Je vais l'appeler demain.","Ainda não falei com ele. Vou ligar para ele amanhã."]],"grammar":[{"h":"Pronomes indiretos: lui e leur","p":["Na unidade anterior, você aprendeu os pronomes de objeto direto (COD): <b>le, la, l' e les</b>. Agora, vamos estudar dois pronomes de objeto indireto, chamados <b>COI (complément d'objet indirect)</b>: <b>lui</b> e <b>leur</b>.","Esses pronomes substituem complementos de verbos construídos com <b>à + pessoa</b>, como téléphoner à quelqu'un (telefonar para alguém).","Use <b>lui</b> para uma pessoa, masculina ou feminina. Use <b>leur</b> para duas ou mais pessoas, independentemente do gênero.","Assim como os pronomes COD, lui e leur normalmente ficam <b>antes do verbo conjugado</b>."],"ex":[["Je téléphone à ma sœur. Je lui téléphone.","Telefono para minha irmã. Telefono para ela."],["Je parle à mon frère. Je lui parle.","Converso com meu irmão. Converso com ele."],["Je téléphone à mes amis. Je leur téléphone.","Telefono para meus amigos. Telefono para eles."]],"tip":"Memorize: <b>lui = a ele / a ela</b> e <b>leur = a eles / a elas</b>. O gênero não altera esses pronomes."},{"h":"Dire, demander e téléphoner à","p":["Três verbos muito comuns na comunicação são <b>dire</b> (dizer), <b>demander</b> (perguntar/pedir) e <b>téléphoner à</b> (telefonar para).","Com dire e demander, podemos usar <b>verbo + informação ou coisa + à quelqu'un</b>. O pronome lui ou leur substitui a pessoa que recebe a informação ou o pedido.","Atenção à diferença entre <b>appeler quelqu'un</b> (ligar para alguém) e <b>téléphoner à quelqu'un</b>. O primeiro usa COD; o segundo, COI.","No presente, dire tem formas irregulares: <b>je dis, tu dis, il/elle dit, nous disons, vous dites, ils/elles disent</b>."],"ex":[["Je lui dis la vérité.","Eu digo a verdade para ele."],["Tu leur demandes l'adresse ?","Você pergunta o endereço para eles?"],["Je l'appelle. Je lui téléphone.","Eu ligo para ele. Eu telefono para ele."]],"tip":"O pronome depende da construção do verbo, não apenas da tradução."},{"h":"Lui e leur no passado e na negativa","p":["No <b>passé composé</b>, lui e leur aparecem antes do auxiliar avoir: <b>Je lui ai parlé</b> e <b>Je leur ai téléphoné</b>.","Na negativa, use a sequência <b>ne + pronome + auxiliar + pas + particípio</b>. Para dizer “ainda não”, use <b>ne... pas encore</b>.","O pronome indireto não provoca concordância do particípio passado. <b>Je lui ai téléphoné</b> permanece igual para um homem ou uma mulher."],"ex":[["Je lui ai envoyé un message.","Enviei uma mensagem para ela."],["Nous leur avons parlé hier.","Conversamos com eles ontem."],["Je ne lui ai pas encore téléphoné.","Ainda não liguei para ele."]],"tip":"A posição do pronome é antes do auxiliar: <b>je lui ai dit</b>, não j'ai lui dit."},{"h":"Pronomes com infinitivo e pedidos","p":["Quando usamos <b>aller, vouloir ou pouvoir + infinitivo</b>, o pronome indireto que completa o infinitivo aparece imediatamente antes dele.","Por exemplo: <b>Je vais téléphoner à mes amis → Je vais leur téléphoner</b>. Essa estrutura é igual à que você aprendeu com os pronomes COD na unidade anterior.","Para pedir que alguém faça alguma coisa, use <b>demander à quelqu'un de + infinitivo</b>. Substituindo a pessoa, temos <b>lui demander de</b> ou <b>leur demander de</b>."],"ex":[["Je vais lui téléphoner demain.","Vou telefonar para ela amanhã."],["Tu peux leur demander l'heure ?","Você pode perguntar o horário para eles?"],["Je vais lui demander d'apporter du pain.","Vou pedir para ele trazer pão."]],"tip":"Com dois verbos, coloque lui ou leur antes do infinitivo: <b>je veux lui parler</b>, <b>je vais leur demander</b>."}],"vocab":[{"h":"Verbos de comunicação","items":[["dire","dizer"],["demander","perguntar / pedir"],["téléphoner à","telefonar para"],["parler à","falar com"],["répondre à","responder a"],["envoyer","enviar / mandar"],["appeler","ligar / chamar"],["expliquer","explicar"],["donner","dar / passar"],["inviter","convidar"]]},{"h":"Amigos e organização de encontros","items":[["un ami / une amie","um amigo / uma amiga"],["une invitation","um convite"],["un message","uma mensagem"],["une adresse","um endereço"],["un dîner","um jantar"],["une soirée","uma noite de encontro / festa"],["les invités","os convidados"],["une réponse","uma resposta"]]},{"h":"Expressões para combinar planos","items":[["pas encore","ainda não"],["bien sûr","claro / com certeza"],["c'est d'accord","combinado"],["à quelle heure ?","a que horas?"],["apporter quelque chose","trazer alguma coisa"],["préparer le dîner","preparar o jantar"],["tout le monde","todo mundo"],["demain soir","amanhã à noite"]]}],"pron":[{"h":"lui","p":"O pronome <b>lui</b> é pronunciado em uma única sílaba, aproximadamente “lüi”. O u francês exige lábios arredondados, como para dizer “u”, enquanto a língua fica na posição de “i”.","w":["lui","je lui parle","je lui ai dit","tu lui téléphones"]},{"h":"leur","p":"O pronome <b>leur</b> soa aproximadamente “lêr”, mas com vogal arredondada, semelhante ao eu de <b>peur</b>. O r final é pronunciado à francesa.","w":["leur","je leur parle","je leur demande","nous leur téléphonons"]},{"h":"téléphoner e téléphoné","p":"O infinitivo <b>téléphoner</b> e o particípio <b>téléphoné</b> têm a mesma pronúncia, aproximadamente “tê-lê-fo-NÊ”. O grupo ph tem som de f.","w":["téléphoner","téléphoné","je vais téléphoner","j'ai téléphoné"]}],"mc":[{"q":"Com quem Lucas conversou por telefone na noite anterior?","o":["Com o irmão","Com a irmã","Com todos os amigos"],"a":1,"e":"Oui, je lui ai téléphoné hier soir après le travail."},{"q":"O que Lucas enviou para os amigos?","o":["O endereço e uma foto da sala","O cardápio e o horário","A lista dos convidados"],"a":0,"e":"Oui, je leur ai envoyé l'adresse et une photo du salon."},{"q":"O que Claire pede para Lucas combinar com os amigos?","o":["Que cheguem cedo","Que preparem a sobremesa","Que tragam bebidas"],"a":2,"e":"Tu peux leur demander d'apporter des boissons ?"},{"q":"Por que Lucas ainda precisa ligar para o irmão?","o":["O irmão perdeu o endereço","Ainda não conversou com ele","O irmão não gosta de massa"],"a":1,"e":"Je ne lui ai pas encore parlé. Je vais l'appeler demain."}],"gaps":[{"s":"Ma sœur ? Je ___ ai téléphoné hier.","a":["lui"],"h":"Minha irmã? Liguei para ela ontem."},{"s":"Mes amis ? Je ___ ai envoyé l'adresse.","a":["leur"],"h":"Meus amigos? Mandei o endereço para eles."},{"s":"Mon frère ? Je ne ___ ai pas encore parlé.","a":["lui"],"h":"Meu irmão? Ainda não conversei com ele."},{"s":"Mes parents ? Je vais ___ téléphoner demain.","a":["leur"],"h":"Meus pais? Vou telefonar para eles amanhã."},{"s":"Mon amie ? Je veux ___ demander d'apporter du pain.","a":["lui"],"h":"Minha amiga? Quero pedir para ela trazer pão."},{"s":"Mes amis ? Je ne ___ ai pas encore répondu.","a":["leur"],"h":"Meus amigos? Ainda não respondi a eles."}],"order":[{"t":["Je","lui","ai","donné","l'adresse."],"h":"Passei o endereço para ela."},{"t":["Je","ne","leur","ai","pas","téléphoné."],"h":"Não telefonei para eles."},{"t":["Nous","allons","leur","envoyer","un","message."],"h":"Vamos mandar uma mensagem para eles."}],"dict":[{"t":"Je lui ai téléphoné hier soir."},{"t":"Tu leur as envoyé un message ?"},{"t":"Je vais lui demander l'adresse."},{"t":"Nous ne leur avons pas parlé."},{"t":"Elle lui a demandé d'apporter du pain."}],"shadow":["Oui, je lui ai téléphoné hier soir après le travail.","Oui, je lui ai dit l'heure et je lui ai donné l'adresse.","Tu peux leur demander d'apporter des boissons ?","Je ne lui ai pas encore parlé. Je vais l'appeler demain."],"write":{"task":"Imagine que você está organizando um jantar ou encontro com amigos. Escreva de cinco a seis frases explicando para quem você já telefonou, que informações enviou, o que pediu para os convidados trazerem e com quem ainda precisa falar. Use lui e leur pelo menos duas vezes cada, incluindo uma frase negativa e outra no futuro próximo.","ph":"Pour samedi, j'ai invité mes amis. Je leur ai …"},"cards":[["Eu disse a verdade para ela.","Je lui ai dit la vérité."],["Você telefonou para os seus pais?","Tu as téléphoné à tes parents ?"],["Vou mandar uma mensagem para eles.","Je vais leur envoyer un message."],["Ainda não respondi a ela.","Je ne lui ai pas encore répondu."],["Você pode perguntar o endereço para ele?","Tu peux lui demander l'adresse ?"],["Nós explicamos o problema para eles.","Nous leur avons expliqué le problema."],["Ela pediu ajuda para o irmão.","Elle a demandé de l'aide à son frère."],["Não quero telefonar para eles agora.","Je ne veux pas leur téléphoner maintenant."],["Vou pedir para ela chegar às oito.","Je vais lui demander d'arriver à huit heures."],["Ele disse aos amigos que está ocupado.","Il a dit à ses amis qu'il est occupé."]]},{"title":"Au marché","goal":"Comprar alimentos no mercado, falar de quantidades e substituir complementos com en (quantidades e de + coisa) e y (lugares), usando expressões como un kilo de e un peu de.","speakers":{"Claire":"f","Lucas":"m"},"setting":"No sábado de manhã, Claire e Lucas fazem compras em um mercado de bairro para preparar o almoço.","lines":[["Claire","On va au marché ? Il nous faut des légumes pour le déjeuner.","Vamos ao mercado? Precisamos de legumes para o almoço."],["Lucas","Bonne idée ! Tu y vas souvent ?","Boa ideia! Você vai lá com frequência?"],["Claire","Oui, j'y vais tous les samedis. Les produits sont frais.","Sim, vou lá todos os sábados. Os produtos são frescos."],["Lucas","On prend des tomates ? Il y en a de très belles ici.","Vamos levar tomates? Tem umas muito bonitas aqui."],["Claire","Oui, on en prend un kilo. Et il nous faut des pommes de terre.","Sim, vamos levar um quilo. E precisamos de batatas."],["Lucas","Tu en veux combien ?","Você quer quantas?"],["Claire","Un kilo aussi. On en a déjà un peu à la maison.","Um quilo também. A gente já tem um pouco em casa."],["Lucas","Et des carottes ? On en prend ?","E cenouras? Vamos levar?"],["Claire","Oui, j'en prends cinq, s'il te plaît.","Sim, vou levar cinco, por favor."],["Lucas","D'accord. Pour le dessert, on achète des fraises ?","Combinado. Para a sobremesa, compramos morangos?"],["Claire","Oui, mais pas beaucoup. On en prend une petite barquette.","Sim, mas não muitos. Vamos levar uma bandejinha."],["Lucas","Il faut aussi du fromage. On en a encore ?","Também precisamos de queijo. Ainda temos?"],["Claire","Non, il n'y en a plus. Je vais en acheter deux cents grammes.","Não, não temos mais. Vou comprar duzentos gramas."],["Lucas","Parfait ! Après, on rentre ? J'ai faim !","Perfeito! Depois a gente volta para casa? Estou com fome!"]],"grammar":[{"h":"O pronome en: substituir quantidades","p":["O pronome <b>en</b> retoma algo já mencionado quando se fala de quantidade. Em vez de repetir des tomates, por exemplo, podemos dizer <b>J'en prends un kilo</b>.","Quando a quantidade é expressa por número, unidade ou palavra como beaucoup ou un peu, <b>a quantidade continua na frase</b>: <b>J'en veux cinq</b> (quero cinco), <b>J'en prends un peu</b> (vou levar um pouco).","No presente, en aparece antes do verbo conjugado: <b>Tu en veux ?</b>. Antes de vogal, je vira j': <b>j'en veux</b>."],"ex":[["Tu veux des pommes ? J'en veux trois.","Quer maçãs? Quero três."],["Nous en achetons un kilo.","Compramos um quilo."],["Il en reste un peu.","Ainda sobra um pouco."]],"tip":"A quantidade permanece mesmo quando o substantivo desaparece: <b>trois pommes → j'en veux trois</b>."},{"h":"En com de e nas frases negativas","p":["Além de quantidades, <b>en</b> pode substituir um complemento introduzido por <b>de</b> quando se refere a uma coisa: <b>Tu veux du fromage ? Oui, j'en veux.</b>","Na negativa, en continua antes do verbo: <b>Je n'en veux pas</b>. Para dizer que algo acabou, use <b>il n'y en a plus</b>, construção frequente no comércio; nessa expressão, <b>y</b> faz parte da estrutura fixa <b>il y a</b>.","No passé composé, en vem antes do auxiliar: <b>J'en ai acheté</b> (comprei um pouco/disso). Antes de infinitivo, aparece imediatamente antes dele: <b>Je vais en acheter</b>."],"ex":[["Tu veux du pain ? Oui, j'en veux.","Quer pão? Sim, quero."],["Je n'en ai pas acheté.","Não comprei nenhum."],["Il n'y en a plus.","Não tem mais."]],"tip":"En não substitui automaticamente qualquer pessoa introduzida por de; aqui estamos aprendendo seus usos com coisas e quantidades."},{"h":"O pronome y: substituir lugares","p":["O pronome <b>y</b> retoma um lugar já mencionado, muitas vezes introduzido por <b>à, dans, chez</b> ou <b>en</b>: <b>Je vais au marché → J'y vais</b>.","Ele fica antes do verbo conjugado: <b>Tu y vas ?</b>. No passé composé, aparece antes do auxiliar: <b>J'y suis allé</b> (fui lá).","Com aller + infinitivo, y fica antes do infinitivo quando pertence a ele: <b>Je vais y retourner</b> (vou voltar lá)."],"ex":[["Tu vas au marché ? Oui, j'y vais.","Você vai ao mercado? Sim, vou lá."],["On y a acheté des légumes.","Compramos legumes lá."],["Je veux y retourner demain.","Quero voltar lá amanhã."]],"tip":"Não confunda <b>y</b> (lá) com <b>en</b> (disso/deles em contexto de quantidade)."},{"h":"Medidas e quantidades: de e d'","p":["Depois de expressões de medida e quantidade, use normalmente <b>de + substantivo</b>: <b>un kilo de tomates</b>, <b>deux cents grammes de fromage</b>, <b>un peu de sel</b>.","Antes de vogal, de vira <b>d'</b>: <b>un litre d'eau</b>. Já com números de itens, não é necessário de: <b>cinq carottes</b>.","Para perguntar a quantidade, use <b>combien de</b> diante do nome ou <b>combien</b> sozinho quando o alimento já foi mencionado."],"ex":[["Je prends un kilo de pommes.","Vou levar um quilo de maçãs."],["On prend un litre d'eau.","Vamos levar um litro de água."],["Combien de carottes tu veux ?","Quantas cenouras você quer?"]],"tip":"Depois de beaucoup, peu e un kilo, use de, não des: <b>beaucoup de fraises</b>."}],"vocab":[{"h":"Frutas e legumes","items":[["une tomate","um tomate"],["une pomme de terre","uma batata"],["une carotte","uma cenoura"],["une fraise","um morango"],["une pomme","uma maçã"],["une poire","uma pera"],["une courgette","uma abobrinha"],["un oignon","uma cebola"]]},{"h":"Medidas e compras","items":[["un kilo de","um quilo de"],["un gramme de","um grama de"],["un litre de","um litro de"],["un peu de","um pouco de"],["beaucoup de","muito(s) / muita(s)"],["une barquette","uma bandeja pequena"],["un panier","uma cesta"],["un marché","um mercado"],["frais / fraîche","fresco / fresca"]]},{"h":"Expressões úteis","items":[["il en reste","ainda sobra"],["il n'y en a plus","não tem mais"],["combien ?","quanto? / quantos?"],["j'en prends","vou levar alguns / um pouco"],["j'y vais","eu vou lá"],["on en prend ?","vamos levar?"]]}],"pron":[{"h":"en e y","p":"Em <b>j'en prends</b>, en soa aproximadamente “ã”, com vogal nasal. O pronome <b>y</b> soa “i”: <b>j'y vais</b>, aproximadamente “ji vê”. São curtos e ficam ligados ao verbo.","w":["j'en prends","j'en veux","j'y vais"]},{"h":"un kilo de","p":"Em <b>un kilo de</b>, o n de un normalmente não forma uma sílaba separada; a vogal é nasal. Kilo soa aproximadamente “ki-lo”.","w":["un kilo de tomates","un kilo de pommes"]},{"h":"combien e o som nasal","p":"<b>Combien</b> termina com uma vogal nasal parecida com “iã”, e seu b é pronunciado: aproximadamente “cõ-biã”.","w":["combien","combien de carottes","tu en veux combien ?"]}],"mc":[{"q":"Com que frequência Claire vai ao mercado?","o":["Uma vez por mês","Todos os sábados","Todos os dias"],"a":1,"e":"Oui, j'y vais tous les samedis."},{"q":"Quantas cenouras Claire quer?","o":["Três","Um quilo","Cinco"],"a":2,"e":"Oui, j'en prends cinq, s'il te plaît."},{"q":"O que eles decidem comprar para a sobremesa?","o":["Uma bandeja pequena de morangos","Uma torta de maçã","Um quilo de peras"],"a":0,"e":"On en prend une petite barquette."},{"q":"Quanto queijo Claire pretende comprar?","o":["Um quilo","Duzentos gramas","Cinquenta gramas"],"a":1,"e":"Je vais en acheter deux cents grammes."}],"gaps":[{"s":"Tu veux des pommes ? J'___ veux trois.","a":["en"],"h":"Quer maçãs? Quero três."},{"s":"Tu vas au marché ? Oui, j'___ vais.","a":["y"],"h":"Vai ao mercado? Sim, vou lá."},{"s":"Je voudrais un kilo ___ tomates.","a":["de"],"h":"Eu gostaria de um quilo de tomates."},{"s":"Il n'y en a ___ dans le frigo.","a":["plus"],"h":"Não tem mais na geladeira."},{"s":"On achète des fraises ? Oui, on ___ prend un kilo.","a":["en"],"h":"Vamos comprar morangos? Sim, vamos levar um quilo."},{"s":"J'ai visité ce marché hier. J'___ ai acheté du fromage.","a":["y"],"h":"Visitei esse mercado ontem. Comprei queijo lá."}],"order":[{"t":["J'en","veux","cinq,","s'il","te","plaît."],"h":"Quero cinco, por favor."},{"t":["Je","vais","y","retourner","demain."],"h":"Vou voltar lá amanhã."},{"t":["On","achète","un","kilo","de","tomates."],"h":"Vamos comprar um quilo de tomates."}],"dict":[{"t":"Tu en veux combien ?"},{"t":"J'en voudrais cinq, s'il te plaît."},{"t":"Je n'en veux pas."},{"t":"Il n'y en a plus."},{"t":"Je vais en acheter deux cents grammes."}],"shadow":["On va au marché ? Il nous faut des légumes pour le déjeuner.","Oui, j'y vais tous les samedis. Les produits sont frais.","Oui, j'en prends cinq, s'il te plaît.","Non, il n'y en a plus. Je vais en acheter deux cents grammes."],"write":{"task":"Descreva compras para uma refeição. Diga a que mercado vai, liste três produtos e suas quantidades, e use en pelo menos duas vezes e y uma vez.","ph":"Je vais au marché le samedi. J'y achète …"},"cards":[["Você vai ao mercado com frequência?","Tu vas souvent au marché ?"],["Eu vou lá aos sábados.","J'y vais le samedi."],["Eu quero três maçãs.","Je veux trois pommes."],["Quero três delas.","J'en veux trois."],["Precisamos de um quilo de batatas.","Il nous faut un kilo de pommes de terre."],["Não temos mais leite.","Nous n'avons plus de lait."],["Você quer um pouco de queijo?","Tu veux un peu de fromage ?"],["Eu já comprei um pouco.","J'en ai déjà acheté."],["Quanto você quer?","Tu en veux combien ?"],["Vamos levar uma bandeja de morangos.","On va prendre une barquette de fraises."]]},{"title":"La santé","goal":"Descrever sintomas, dizer onde dói e explicar necessidades e recomendações simples usando avoir mal à, il faut + infinitivo e devoir, em situações de consulta e farmácia.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Em uma manhã de segunda-feira, Claire chega ao trabalho sentindo-se mal. Lucas conversa com ela e, mais tarde, ajuda a explicar o problema na farmácia onde trabalha.","lines":[["Lucas","Bonjour Claire ! Tu n'as pas l'air en forme aujourd'hui.","Bom dia, Claire! Você não parece estar muito bem hoje."],["Claire","Non, j'ai mal à la tête et j'ai un peu de fièvre.","Não, estou com dor de cabeça e um pouco de febre."],["Lucas","Depuis quand tu te sens comme ça ?","Desde quando você está se sentindo assim?"],["Claire","Depuis hier soir. J'ai aussi mal à la gorge.","Desde ontem à noite. Também estou com dor de garganta."],["Lucas","Tu dois te reposer. Il faut boire beaucoup d'eau.","Você precisa descansar. É necessário beber bastante água."],["Claire","Oui, mais je dois finir un travail ce matin.","Sim, mas tenho que terminar um trabalho hoje de manhã."],["Lucas","Tu peux appeler le médecin. Il faut prendre rendez-vous.","Você pode ligar para o médico. É preciso marcar uma consulta."],["Claire","Bonne idée. Et toi, tu connais une pharmacie près d'ici ?","Boa ideia. E você conhece uma farmácia perto daqui?"],["Lucas","Oui, je travaille dans une pharmacie le samedi. Elle est à côté du métro.","Sim, eu trabalho numa farmácia aos sábados. Ela fica ao lado do metrô."],["Claire","Je peux y acheter quelque chose pour la gorge ?","Posso comprar alguma coisa lá para a garganta?"],["Lucas","Tu peux demander conseil au pharmacien. Mais avec de la fièvre, il faut consulter un médecin.","Você pode pedir orientação ao farmacêutico. Mas, com febre, é importante consultar um médico."],["Claire","D'accord. Je vais prendre rendez-vous cet après-midi.","Tá bom. Vou marcar uma consulta hoje à tarde."],["Lucas","Et tu ne dois pas travailler si tu te sens trop mal.","E você não deve trabalhar se estiver se sentindo muito mal."],["Claire","Tu as raison. Je vais rentrer et me reposer.","Você tem razão. Vou voltar para casa e descansar."]],"grammar":[{"h":"Avoir mal à: dizer onde dói","p":["Para falar de dor em uma parte do corpo, use <b>avoir mal à + parte do corpo</b>. Em português, corresponde a “estar com dor de/no/na”.","A preposição <b>à</b> se combina com o artigo: <b>à + le = au</b>, <b>à + les = aux</b>. Com la, fica <b>à la</b>; antes de vogal ou h mudo, use <b>à l'</b>.","Por isso dizemos <b>mal à la tête</b>, <b>mal au dos</b>, <b>mal aux jambes</b> e <b>mal à l'estomac</b>."],"ex":[["J'ai mal à la tête.","Estou com dor de cabeça."],["Elle a mal au dos.","Ela está com dor nas costas."],["Nous avons mal aux jambes.","Estamos com dor nas pernas."],["Tu as mal à l'estomac ?","Você está com dor no estômago?"]],"tip":"O verbo é <b>avoir</b>, não être: diga <b>j'ai mal</b>, e não je suis mal, quando falar de uma dor."},{"h":"Il faut + infinitivo: necessidade geral","p":["<b>Il faut + infinitivo</b> expressa uma necessidade ou recomendação geral, sem indicar diretamente uma pessoa: “é preciso”, “é necessário”.","Depois de <b>il faut</b>, use sempre um verbo no infinitivo: <b>il faut boire</b>, <b>il faut dormir</b>. A expressão não varia conforme a pessoa.","Para negar a necessidade, a forma usual é <b>il ne faut pas + infinitivo</b>, que normalmente comunica proibição ou recomendação para não fazer algo."],"ex":[["Il faut boire de l'eau.","É preciso beber água."],["Il faut se reposer.","É preciso descansar."],["Il ne faut pas fumer ici.","Não se deve fumar aqui."]],"tip":"Use il faut para conselhos gerais; para necessidades pessoais, também é possível usar devoir."},{"h":"Devoir + infinitivo: obrigação ou conselho","p":["<b>Devoir</b> significa “dever”, “ter que” ou “precisar”, conforme o contexto. No presente: <b>je dois, tu dois, il/elle doit, nous devons, vous devez, ils/elles doivent</b>.","Depois de devoir, o segundo verbo fica no infinitivo: <b>Je dois appeler</b> (tenho que ligar). Na negativa: <b>Je ne dois pas sortir</b> (não devo sair).","A forma <b>tu dois</b> dirige a recomendação a uma pessoa, enquanto <b>il faut</b> apresenta uma necessidade geral."],"ex":[["Je dois prendre rendez-vous.","Tenho que marcar uma consulta."],["Tu dois te reposer.","Você precisa descansar."],["Vous ne devez pas conduire.","Vocês não devem dirigir."]],"tip":"<b>Devoir</b> é conjugado; o verbo depois dele não: <b>nous devons partir</b>, nunca nous devons partons."},{"h":"Na consulta e na farmácia","p":["Para explicar sintomas, frases diretas ajudam muito: <b>j'ai de la fièvre</b> (estou com febre), <b>j'ai mal à la gorge</b> (estou com dor de garganta) e <b>depuis hier</b> (desde ontem).","Para falar de consulta, use <b>prendre rendez-vous</b>. Na farmácia, <b>demander conseil au pharmacien</b> significa pedir orientação ao farmacêutico.","É possível falar de cuidados simples em francês, mas sintomas persistentes ou preocupantes devem ser avaliados por um profissional de saúde."],"ex":[["J'ai de la fièvre depuis hier.","Estou com febre desde ontem."],["Je dois prendre rendez-vous.","Preciso marcar uma consulta."],["Je vais demander conseil au pharmacien.","Vou pedir orientação ao farmacêutico."]],"tip":"A expressão <b>depuis + ponto de partida</b> indica algo que começou no passado e continua agora."}],"vocab":[{"h":"Partes do corpo","items":[["la tête","a cabeça"],["la gorge","a garganta"],["le dos","as costas"],["le ventre","a barriga"],["l'estomac","o estômago"],["les jambes","as pernas"],["les bras","os braços"],["les dents","os dentes"]]},{"h":"Sintomas e cuidados","items":[["la fièvre","a febre"],["la toux","a tosse"],["un rhume","um resfriado"],["fatigué / fatiguée","cansado / cansada"],["un médicament","um medicamento"],["se reposer","descansar"],["dormir","dormir"],["boire de l'eau","beber água"],["aller mieux","melhorar / sentir-se melhor"]]},{"h":"Consulta e farmácia","items":[["un médecin","um médico"],["une pharmacie","uma farmácia"],["un pharmacien / une pharmacienne","um farmacêutico / uma farmacêutica"],["un rendez-vous","uma consulta / um horário marcado"],["une ordonnance","uma receita médica"],["un conseil","um conselho / orientação"],["prendre rendez-vous","marcar consulta"],["depuis hier","desde ontem"]]}],"pron":[{"h":"j’ai mal","p":"Em <b>j'ai mal</b>, j'ai soa aproximadamente “jê”, com o j semelhante ao de “já”. O l de mal é pronunciado.","w":["j'ai mal","j'ai mal au dos","j'ai mal à la tête"]},{"h":"gorge e jambes","p":"Em <b>gorge</b>, os dois g têm som semelhante ao j de “já”. Em <b>jambes</b>, o grupo am é nasal: aproximadamente “jãb”, sem pronunciar o s final.","w":["la gorge","les jambes","mal à la gorge"]},{"h":"il faut","p":"O t final de <b>faut</b> é mudo. A expressão soa aproximadamente “il fô”, com vogal fechada e arredondada no final.","w":["il faut boire","il faut dormir","il faut se reposer"]}],"mc":[{"q":"Quais sintomas Claire apresenta?","o":["Dor de cabeça, febre e dor de garganta","Dor nas pernas e tosse","Dor no estômago e dor nas costas"],"a":0,"e":"Non, j'ai mal à la tête et j'ai un peu de fièvre."},{"q":"Desde quando ela se sente mal?","o":["Desde sábado","Desde ontem à noite","Desde esta manhã"],"a":1,"e":"Depuis hier soir."},{"q":"O que Lucas recomenda que Claire faça por causa da febre?","o":["Tomar um trem","Continuar trabalhando","Consultar um médico"],"a":2,"e":"Mais avec de la fièvre, il faut consulter un médecin."},{"q":"O que Claire decide fazer à tarde?","o":["Marcar uma consulta","Ir ao cinema","Trabalhar até tarde"],"a":0,"e":"Je vais prendre rendez-vous cet après-midi."}],"gaps":[{"s":"J'ai mal ___ dos.","a":["au"],"h":"Estou com dor nas costas."},{"s":"Elle a mal ___ jambes.","a":["aux"],"h":"Ela está com dor nas pernas."},{"s":"Il faut ___ beaucoup d'eau.","a":["boire"],"h":"É preciso beber muita água."},{"s":"Nous ___ prendre rendez-vous.","a":["devons"],"h":"Precisamos marcar uma consulta."},{"s":"Tu ne ___ pas travailler si tu es malade.","a":["dois"],"h":"Você não deve trabalhar se estiver doente."},{"s":"J'ai mal ___ la gorge.","a":["à"],"h":"Estou com dor de garganta."}],"order":[{"t":["J'ai","mal","à","la","tête."],"h":"Estou com dor de cabeça."},{"t":["Il","faut","prendre","rendez-vous","aujourd'hui."],"h":"É necessário marcar uma consulta hoje."},{"t":["Nous","devons","boire","plus","d'eau."],"h":"Precisamos beber mais água."}],"dict":[{"t":"J'ai mal à la gorge."},{"t":"Tu dois te reposer."},{"t":"Il faut boire beaucoup d'eau."},{"t":"Je vais prendre rendez-vous."},{"t":"J'ai de la fièvre depuis hier."}],"shadow":["Non, j'ai mal à la tête et j'ai un peu de fièvre.","Tu dois te reposer. Il faut boire beaucoup d'eau.","Tu peux demander conseil au pharmacien. Mais avec de la fièvre, il faut consulter un médecin.","Tu as raison. Je vais rentrer et me reposer."],"write":{"task":"Escreva de cinco a seis frases simulando uma conversa simples sobre saúde: descreva dois sintomas, diga desde quando começaram e inclua dois conselhos com il faut e devoir.","ph":"Depuis hier, j'ai mal … Il faut …"},"cards":[["Estou com dor nas costas.","J'ai mal au dos."],["Ela está com dor de garganta.","Elle a mal à la gorge."],["Meus braços estão doendo.","J'ai mal aux bras."],["Estou com um pouco de febre.","J'ai un peu de fièvre."],["É preciso descansar.","Il faut se reposer."],["Você deve beber água.","Tu dois boire de l'eau."],["Não devemos sair hoje.","Nous ne devons pas sortir aujourd'hui."],["Preciso marcar uma consulta.","Je dois prendre rendez-vous."],["Desde quando você está doente?","Depuis quand tu es malade ?"],["Onde fica a farmácia mais próxima?","Où est la pharmacie la plus proche ?"]]},{"title":"L'avenir","goal":"Falar de projetos, previsões e compromissos futuros usando o futur simple, incluindo verbos regulares e os irregulares être, avoir, aller, faire e pouvoir.","speakers":{"Claire":"f","Lucas":"m"},"setting":"No início do ano, Claire e Lucas conversam em um café sobre planos para os próximos meses e sobre como imaginam suas vidas no futuro.","lines":[["Claire","Cette année, je changerai quelques habitudes.","Neste ano, vou mudar alguns hábitos."],["Lucas","Ah oui ? Tu feras plus de sport ?","É mesmo? Você vai praticar mais esporte?"],["Claire","Oui, je marcherai tous les matins et je mangerai mieux.","Sim, vou caminhar todas as manhãs e comer melhor."],["Lucas","Moi, je vais prendre des cours de français le mois prochain.","Eu vou fazer aulas de francês no mês que vem."],["Claire","Super ! Tu pourras pratiquer avec moi.","Ótimo! Você vai poder praticar comigo."],["Lucas","Et toi, tu voyageras pendant les vacances ?","E você, vai viajar nas férias?"],["Claire","Oui, j'irai à Marseille en juillet avec ma sœur.","Sim, irei a Marselha em julho com minha irmã."],["Lucas","Vous serez là-bas combien de temps ?","Vocês vão ficar lá por quanto tempo?"],["Claire","Une semaine. Nous visiterons la ville et nous irons à la plage.","Uma semana. Vamos conhecer a cidade e ir à praia."],["Lucas","Vous aurez sûrement du beau temps !","Vocês provavelmente vão pegar tempo bom!"],["Claire","J'espère ! Et toi, que feras-tu cet été ?","Tomara! E você, o que fará neste verão?"],["Lucas","Je travaillerai en août, mais j'aurai des vacances en septembre.","Vou trabalhar em agosto, mas terei férias em setembro."],["Claire","Tu seras libre pour un dîner à la rentrée ?","Você estará livre para um jantar na volta das férias?"],["Lucas","Bien sûr ! On pourra organiser ça ensemble.","Claro! A gente poderá organizar isso junto."]],"grammar":[{"h":"Futur simple: verbos regulares","p":["O <b>futur simple</b> expressa acontecimentos posteriores ao momento da fala, compromissos, planos e previsões. Em português, pode equivaler a “farei”, “viajarei” ou ao futuro com “vou”, dependendo do contexto.","Para verbos regulares terminados em <b>-er</b> e <b>-ir</b>, acrescentamos as terminações <b>-ai, -as, -a, -ons, -ez, -ont</b> ao infinitivo: <b>parler → je parlerai</b>; <b>finir → nous finirons</b>.","Nos verbos regulares terminados em <b>-re</b>, retire o e final antes de acrescentar as terminações: <b>attendre → j'attendrai</b>."],"ex":[["Je voyagerai en juillet.","Viajarei em julho."],["Nous finirons demain.","Terminaremos amanhã."],["Ils attendront devant le café.","Eles esperarão em frente ao café."]],"tip":"As terminações do futuro são as mesmas para todos os verbos. O que pode mudar é a base."},{"h":"Futur simple: être, avoir e aller","p":["Alguns verbos frequentes têm uma base irregular no futur simple. Para <b>être</b>, use <b>ser-</b>: <b>je serai, tu seras, il sera, nous serons, vous serez, ils seront</b>.","Para <b>avoir</b>, use <b>aur-</b>: <b>j'aurai, tu auras, il aura</b>. Para <b>aller</b>, use <b>ir-</b>: <b>j'irai, tu iras, il ira</b>. As terminações continuam iguais.","Use être para estados e situações, avoir para posse ou experiências, e aller para deslocamentos futuros."],"ex":[["Tu seras libre demain ?","Você estará livre amanhã?"],["Nous aurons plus de temps.","Teremos mais tempo."],["J'irai à Marseille en juillet.","Irei a Marselha em julho."]],"tip":"Lembre das três bases: <b>ser-, aur-, ir-</b>."},{"h":"Futur simple: faire e pouvoir","p":["Outros dois verbos indispensáveis são <b>faire → fer-</b> e <b>pouvoir → pourr-</b>. Assim dizemos <b>je ferai</b> (farei) e <b>je pourrai</b> (poderei).","O verbo <b>faire</b> serve para atividades e planos. <b>Pouvoir</b> indica possibilidade ou capacidade no futuro.","Observe a diferença entre <b>je pourrai</b> (poderei) e <b>je pourrais</b> (poderia), que será útil na unidade seguinte."],"ex":[["Que feras-tu samedi ?","O que você fará no sábado?"],["Nous ferons une promenade.","Faremos uma caminhada."],["Vous pourrez venir demain.","Vocês poderão vir amanhã."]],"tip":"Em <b>pourrai</b>, há dois r na escrita. Essa base irregular é importante para não confundir com o condicional."},{"h":"Futur simple, futur proche e expressões de tempo","p":["Você já conhece o <b>futur proche</b>: <b>je vais partir</b> (vou sair). O <b>futur simple</b>, como <b>je partirai</b>, também fala do futuro e é muito usado para promessas, previsões e planos.","Não existe regra fixa que limite o futur proche ao futuro imediato: as duas formas frequentemente são possíveis. O contexto e a intenção do falante influenciam a escolha.","As expressões <b>demain</b> (amanhã), <b>la semaine prochaine</b> (semana que vem), <b>l'année prochaine</b> (ano que vem) e <b>dans deux mois</b> (daqui a dois meses) situam ações futuras.","A negativa envolve o verbo conjugado: <b>Je ne travaillerai pas dimanche</b> (não trabalharei no domingo)."],"ex":[["Je vais étudier ce soir.","Vou estudar hoje à noite."],["J'étudierai davantage l'année prochaine.","Estudarei mais no ano que vem."],["Nous ne serons pas là demain.","Não estaremos lá amanhã."]],"tip":"Uma previsão com futur simple pode ser uma certeza ou uma expectativa, e não necessariamente um evento distante."}],"vocab":[{"h":"Expressões de futuro","items":[["demain","amanhã"],["après-demain","depois de amanhã"],["la semaine prochaine","na semana que vem"],["le mois prochain","no mês que vem"],["l'année prochaine","no ano que vem"],["dans deux mois","daqui a dois meses"],["cet été","neste verão"],["plus tard","mais tarde"],["à l'avenir","no futuro"]]},{"h":"Projetos e mudanças","items":[["un projet","um projeto"],["une habitude","um hábito"],["un objetivo","um objetivo"],["changer","mudar"],["apprendre","aprender"],["organiser","organizar"],["économiser","economizar"],["voyager","viajar"],["pratiquer","praticar"]]},{"h":"Verbos essenciais no futuro","items":[["je serai","eu serei / estarei"],["j'aurai","eu terei"],["j'irai","eu irei"],["je ferai","eu farei"],["je pourrai","eu poderei"],["nous serons","nós seremos / estaremos"],["nous aurons","nós teremos"],["nous irons","nós iremos"]]}],"pron":[{"h":"-ai e -ais","p":"A terminação escrita <b>-ai</b> do futur simple costuma soar como um “ê” aberto ou fechado conforme a região e o falante; muitas vezes se aproxima de “ê”. Compare a escrita <b>je parlerai</b> (falarei) e <b>je parlais</b> (eu falava), que podem soar iguais para muitos franceses.","w":["je parlerai","je voyagerai","je serai"]},{"h":"serai e aurai","p":"<b>Je serai</b> soa aproximadamente “jë së-RÊ” e <b>j'aurai</b>, “jo-RÊ”. Em ambos, o r é pronunciado à francesa e a terminação final não se pronuncia como “ai” do português.","w":["je serai","j'aurai","nous aurons"]},{"h":"pourrai","p":"Em <b>pourrai</b>, o grupo ou tem som de “u” português. A palavra soa aproximadamente “pu-RÊ”, com r francês. Os dois r na escrita não criam duas sílabas.","w":["je pourrai","tu pourras","nous pourrons"]}],"mc":[{"q":"Que mudança Claire planeja para este ano?","o":["Aprender a dirigir","Caminhar todas as manhãs e comer melhor","Mudar de cidade"],"a":1,"e":"Oui, je marcherai tous les matins et je mangerai mieux."},{"q":"Para onde Claire pretende viajar em julho?","o":["Marselha","Lyon","Paris"],"a":0,"e":"Oui, j'irai à Marseille en juillet avec ma sœur."},{"q":"Quando Lucas pretende tirar férias?","o":["Em julho","Em agosto","Em setembro"],"a":2,"e":"Je travaillerai en août, mais j'aurai des vacances en septembre."},{"q":"O que Lucas e Claire poderão organizar juntos?","o":["Uma viagem de trabalho","Um jantar","Uma aula de francês"],"a":1,"e":"On pourra organiser ça ensemble."}],"gaps":[{"s":"Demain, j'___ au marché.","a":["irai"],"h":"Amanhã, irei ao mercado."},{"s":"Nous ___ à la maison dimanche.","a":["serons"],"h":"Estaremos em casa no domingo."},{"s":"L'année prochaine, j'___ plus de temps.","a":["aurai"],"h":"No ano que vem, terei mais tempo."},{"s":"Vous ___ du sport samedi.","a":["ferez"],"h":"Vocês praticarão esporte no sábado."},{"s":"Tu ___ venir demain ?","a":["pourras"],"h":"Você poderá vir amanhã?"},{"s":"Ils ___ français tous les jours.","a":["étudieront"],"h":"Eles estudarão francês todos os dias."}],"order":[{"t":["Je","voyagerai","en","juillet","avec","ma","sœur."],"h":"Viajarei em julho com minha irmã."},{"t":["Nous","aurons","plus","de","temps","demain."],"h":"Teremos mais tempo amanhã."},{"t":["Tu","pourras","pratiquer","avec","moi."],"h":"Você poderá praticar comigo."}],"dict":[{"t":"Je serai libre demain."},{"t":"Nous irons à la plage."},{"t":"Tu pourras pratiquer avec moi."},{"t":"Je ne travaillerai pas dimanche."},{"t":"Ils feront du sport."}],"shadow":["Oui, je marcherai tous les matins et je mangerai mieux.","Oui, j'irai à Marseille en juillet avec ma sœur.","Une semaine. Nous visiterons la ville et nous irons à la plage.","Bien sûr ! On pourra organiser ça ensemble."],"write":{"task":"Escreva cinco ou seis frases com seus planos para o próximo ano: diga aonde irá, o que fará, como estará e o que poderá realizar. Use pelo menos quatro verbos diferentes no futur simple, incluindo duas formas irregulares.","ph":"L'année prochaine, je voyagerai … Je serai …"},"cards":[["Vou estudar mais no próximo ano.","J'étudierai plus l'année prochaine."],["Nós iremos à praia em julho.","Nous irons à la plage en juillet."],["Ela estará livre amanhã.","Elle sera libre demain."],["Terei mais tempo em setembro.","J'aurai plus de temps en septembre."],["O que você fará neste verão?","Que feras-tu cet été ?"],["Poderemos viajar juntos.","Nous pourrons voyager ensemble."],["Eles trabalharão na semana que vem.","Ils travailleront la semaine prochaine."],["Não estarei em casa amanhã.","Je ne serai pas à la maison demain."],["Você fará mais esporte?","Tu feras plus de sport ?"],["Daqui a dois meses, terminarei o curso.","Dans deux mois, je finirai le cours."]]},{"title":"On sort ?","goal":"Convidar alguém para sair, aceitar ou recusar convites com educação, fazer pedidos usando je voudrais, pourriez-vous e on pourrait, e empregar o imperativo para sugestões e orientações simples.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Na sexta-feira à tarde, Claire e Lucas combinam um passeio para o fim de semana. Depois, conversam sobre reservar uma mesa e escolher um horário.","lines":[["Lucas","Salut Claire ! Ça te dirait de sortir vendredi soir ?","Oi, Claire! Você gostaria de sair na sexta-feira à noite?"],["Claire","Désolée, je ne peux pas vendredi. On pourrait aller au cinéma samedi ?","Desculpa, não posso na sexta. A gente poderia ir ao cinema no sábado?"],["Lucas","Bonne idée, mais je préférerais voir une comédie.","Boa ideia, mas eu preferiria ver uma comédia."],["Claire","D'accord. Regardons les séances en ligne.","Tá bom. Vamos olhar os horários das sessões na internet."],["Lucas","Il y a une séance à dix-neuf heures. Ça te va ?","Tem uma sessão às sete da noite. Está bom para você?"],["Claire","Oui, mais j'aimerais dîner avant le film.","Sim, mas eu gostaria de jantar antes do filme."],["Lucas","On pourrait réserver une table près du cinéma.","A gente poderia reservar uma mesa perto do cinema."],["Claire","Parfait. Tu veux appeler le restaurant ?","Perfeito. Quer ligar para o restaurante?"],["Lucas","Oui. Bonjour, je voudrais réserver une table pour deux, samedi à dix-sept heures trente.","Sim. Olá, eu gostaria de reservar uma mesa para duas pessoas, sábado às cinco e meia da tarde."],["Claire","Demande s'ils ont une table près de la fenêtre.","Pergunte se eles têm uma mesa perto da janela."],["Lucas","Pourriez-vous nous proposer une table près de la fenêtre, s'il vous plaît ?","O senhor ou a senhora poderia nos oferecer uma mesa perto da janela, por favor?"],["Claire","Et n'oublie pas de demander l'adresse exacte !","E não se esqueça de perguntar o endereço exato!"],["Lucas","C'est bon, j'ai tout noté. On se retrouve devant le restaurant à dix-sept heures vingt.","Pronto, anotei tudo. A gente se encontra em frente ao restaurante às cinco e vinte."],["Claire","Très bien ! À samedi. Et prends ton parapluie !","Ótimo! Até sábado. E leve seu guarda-chuva!"]],"grammar":[{"h":"Condicional de cortesia: je voudrais e j’aimerais","p":["O <b>conditionnel présent</b> é muito usado para fazer pedidos ou expressar desejos com educação. Nesta unidade, o objetivo é reconhecer e usar algumas formas frequentes, sem precisar estudar todos os seus usos.","<b>Je voudrais</b> (eu gostaria) é mais delicado do que <b>je veux</b> (eu quero). Da mesma forma, <b>j'aimerais</b> pode introduzir desejos e propostas de maneira natural.","Essas formas são especialmente úteis em restaurantes, lojas, reservas e situações com desconhecidos."],"ex":[["Je voudrais réserver une table.","Eu gostaria de reservar uma mesa."],["J'aimerais un café, s'il vous plaît.","Eu gostaria de um café, por favor."],["Je préférerais partir plus tôt.","Eu preferiria sair mais cedo."]],"tip":"<b>Je voudrais</b> vem do verbo vouloir e não se confunde com <b>je veux</b>, que é mais direto."},{"h":"Poderia...?: pourriez-vous e on pourrait","p":["<b>Pourriez-vous + infinitivo</b> significa “o senhor/a senhora poderia...?” ou “vocês poderiam...?”, e é uma forma educada de pedir alguma coisa.","<b>On pourrait + infinitivo</b> significa “a gente poderia...” e é uma maneira natural de propor um plano sem impor a decisão.","<b>Tu pourrais</b> é a forma informal para sugerir algo a alguém conhecido. Todas essas expressões vêm de pouvoir no condicional."],"ex":[["Pourriez-vous répéter, s'il vous plaît ?","Poderia repetir, por favor?"],["On pourrait aller au cinéma.","A gente poderia ir ao cinema."],["Tu pourrais venir samedi ?","Você poderia vir no sábado?"]],"tip":"Repare na diferença: <b>tu pourras</b> é futuro (“você poderá”); <b>tu pourrais</b> é condicional (“você poderia”)."},{"h":"Imperativo: convite, instrução e conselho","p":["O <b>impératif</b> serve para fazer convites diretos, dar orientações ou instruções. Usamos três pessoas: <b>tu, nous e vous</b>, mas sem escrever o pronome sujeito.","Para muitos verbos, as formas seguem o presente: <b>nous regardons → regardons !</b>, <b>vous écoutez → écoutez !</b>. Nos verbos regulares em -er, a forma tu normalmente perde o s: <b>tu regardes → regarde !</b>.","Para negar, coloque <b>ne... pas</b> ao redor do verbo: <b>Ne parle pas !</b>. Com um tom amigável e por favor, o imperativo também pode soar educado."],"ex":[["Regardons les horaires !","Vamos olhar os horários!"],["Prends ton parapluie !","Leve seu guarda-chuva!"],["N'oublie pas l'adresse !","Não se esqueça do endereço!"]],"tip":"<b>Allons-y !</b> é uma expressão pronta muito comum para dizer “vamos lá!”."},{"h":"Convidar, aceitar e recusar com delicadeza","p":["Para convidar alguém conhecido, use <b>Ça te dirait de + infinitivo ?</b> (você gostaria de...?) ou <b>Tu veux + infinitivo ?</b> (você quer...?).","Respostas positivas naturais incluem <b>Avec plaisir !</b> (com prazer!), <b>Bonne idée !</b> e <b>Pourquoi pas ?</b> (por que não?).","Para recusar sem parecer rude, agradeça e dê uma explicação curta: <b>Désolé, je ne peux pas</b> ou <b>Merci, mais je suis pris samedi</b>. Você também pode propor outro dia.","A expressão <b>Ça te va ?</b> pergunta se uma proposta de horário ou plano está boa para a outra pessoa."],"ex":[["Ça te dirait de dîner ensemble ?","Você gostaria de jantar comigo?"],["Avec plaisir !","Com prazer!"],["Désolé, je ne peux pas samedi.","Desculpa, não posso no sábado."],["Dimanche, ça te va ?","Domingo está bom para você?"]],"tip":"Uma recusa fica mais gentil com <b>merci, mais...</b> e, se possível, uma alternativa."}],"vocab":[{"h":"Convites e respostas","items":[["ça te dirait de… ?","você gostaria de...?"],["avec plaisir","com prazer"],["pourquoi pas ?","por que não?"],["bonne idée !","boa ideia!"],["désolé / désolée","desculpa"],["ça te va ?","está bom para você?"],["je suis pris / prise","estou ocupado / ocupada"],["une autre fois","outra vez"]]},{"h":"Passeios e reservas","items":[["une séance","uma sessão"],["une comédie","uma comédia"],["un cinéma","um cinema"],["un restaurant","um restaurante"],["réserver une table","reservar uma mesa"],["une réservation","uma reserva"],["un horaire","um horário"],["l'adresse exacte","o endereço exato"],["près de la fenêtre","perto da janela"]]},{"h":"Formas educadas e imperativo","items":[["je voudrais","eu gostaria"],["j'aimerais","eu gostaria"],["pourriez-vous… ?","poderia...?"],["on pourrait","a gente poderia"],["regardons !","vamos olhar!"],["écoutez !","escutem! / escute!"],["prends !","pegue! / leve!"],["n'oublie pas !","não se esqueça!"]]}],"pron":[{"h":"voudrais e pourrais","p":"Em <b>voudrais</b>, a terminação -ais soa como “é” aberto, e o grupo ou como “u”: aproximadamente “vu-DRÉ”. <b>Pourrais</b> tem som aproximado “pu-RÉ”, com r francês.","w":["je voudrais","tu pourrais","on pourrait"]},{"h":"pourriez-vous","p":"Em <b>pourriez-vous</b>, a sequência riez soa aproximadamente “ri-ê” e o s final de vous normalmente não se pronuncia antes de consoante: “pu-riê-vu”.","w":["pourriez-vous répéter ?","pourriez-vous nous aider ?"]},{"h":"regardons e prends","p":"No imperativo <b>regardons</b>, o -ons final é nasal e o s é mudo. Em <b>prends</b>, as letras d e s finais normalmente não são pronunciadas.","w":["regardons","prenons","prends ton parapluie"]}],"mc":[{"q":"O que Claire sugere fazer no sábado?","o":["Ir ao cinema","Fazer uma trilha","Visitar um museu"],"a":0,"e":"On pourrait aller au cinéma samedi ?"},{"q":"Que tipo de filme Lucas prefere?","o":["Drama","Comédia","Documentário"],"a":1,"e":"Bonne idée, mais je préférerais voir une comédie."},{"q":"Para quantas pessoas Lucas quer reservar uma mesa?","o":["Quatro","Três","Duas"],"a":2,"e":"Oui. Bonjour, je voudrais réserver une table pour deux, samedi à dix-sept heures trente."},{"q":"Onde eles combinam de se encontrar?","o":["Na frente do restaurante","Na porta do cinema","Na casa de Claire"],"a":0,"e":"On se retrouve devant le restaurant à dix-sept heures vingt."}],"gaps":[{"s":"Je ___ réserver une table, s'il vous plaît.","a":["voudrais"],"h":"Eu gostaria de reservar uma mesa, por favor."},{"s":"On ___ aller au cinéma samedi.","a":["pourrait"],"h":"A gente poderia ir ao cinema no sábado."},{"s":"___-vous répéter, s'il vous plaît ?","a":["Pourriez"],"h":"Poderia repetir, por favor?"},{"s":"___ les horaires ensemble !","a":["Regardons"],"h":"Vamos olhar os horários juntos!"},{"s":"N'___ pas ton parapluie !","a":["oublie"],"h":"Não se esqueça do seu guarda-chuva!"},{"s":"___ ton manteau, il fait froid !","a":["Prends"],"h":"Pegue seu casaco, está frio!"}],"order":[{"t":["On","pourrait","dîner","ensemble","samedi."],"h":"Poderíamos jantar juntos no sábado."},{"t":["Je","voudrais","une","table","près","de","la","fenêtre."],"h":"Eu gostaria de uma mesa perto da janela."},{"t":["N'oublie","pas","ton","parapluie","!"],"h":"Não se esqueça do seu guarda-chuva!"}],"dict":[{"t":"Je voudrais réserver une table pour deux."},{"t":"On pourrait aller au cinéma samedi."},{"t":"Pourriez-vous répéter, s'il vous plaît ?"},{"t":"Regardons les horaires !"},{"t":"Avec plaisir !"}],"shadow":["Salut Claire ! Ça te dirait de sortir vendredi soir ?","Désolée, je ne peux pas vendredi. On pourrait aller au cinéma samedi ?","Pourriez-vous nous proposer une table près de la fenêtre, s'il vous plaît ?","Très bien ! À samedi. Et prends ton parapluie !"],"write":{"task":"Escreva uma conversa curta convidando um amigo para sair. Proponha duas atividades, aceite ou recuse educadamente uma sugestão e use je voudrais ou pourriez-vous em um pedido. Inclua ao menos uma frase no imperativo.","ph":"Ça te dirait de … ? On pourrait …"},"cards":[["Você gostaria de sair sábado?","Ça te dirait de sortir samedi ?"],["Poderíamos ir ao cinema.","On pourrait aller au cinéma."],["Eu gostaria de reservar uma mesa.","Je voudrais réserver une table."],["Poderia repetir, por favor?","Pourriez-vous répéter, s'il vous plaît ?"],["Prefiro uma comédia.","Je préfère une comédie."],["Vamos olhar os horários!","Regardons les horaires !"],["Leve seu guarda-chuva!","Prends ton parapluie !"],["Não se esqueça do endereço!","N'oublie pas l'adresse !"],["Desculpa, não posso no sábado.","Désolé, je ne peux pas samedi."],["Domingo está bom para você?","Dimanche, ça te va ?"]]},{"title":"Depuis quand ?","goal":"Falar sobre há quanto tempo uma situação continua, quando algo começou e quanto durou uma atividade concluída, usando depuis, il y a, pendant e ça fait... que, além de escolher corretamente entre presente e passé composé.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Em outubro, durante uma exposição de fotografia em um centro cultural de Lyon, Claire e Lucas conversam sobre sua experiência com fotografia e os projetos que estão desenvolvendo.","lines":[["Claire","Tu prends des photos depuis longtemps, Lucas ? J'ai vu ton album sur la table.","Você fotografa há muito tempo, Lucas? Vi seu álbum em cima da mesa."],["Lucas","Oui, je fais de la photo depuis trois ans, mais je n'utilise cet appareil que depuis six mois.","Sim, fotografo há três anos, mas só uso esta câmera há seis meses."],["Claire","Moi, j'ai commencé il y a un an. Avant, je prenais surtout des photos avec mon téléphone.","Eu comecei há um ano. Antes, tirava fotos principalmente com meu celular."],["Lucas","Et ça fait combien de temps que tu suis les ateliers du centre culturel ?","E faz quanto tempo que você participa das oficinas do centro cultural?"],["Claire","Ça fait quatre mois que je viens chaque mercredi. J'ai découvert cet endroit grâce à une amie.","Faz quatro meses que venho toda quarta-feira. Descobri este lugar por meio de uma amiga."],["Lucas","J'ai suivi un cours ici pendant deux semaines l'été dernier. Le professeur était très patient.","Fiz um curso aqui durante duas semanas no verão passado. O professor era muito paciente."],["Claire","Tu as appris à retoucher les images pendant ce cours ou tu savais déjà le faire ?","Você aprendeu a editar as imagens durante esse curso ou já sabia fazer isso?"],["Lucas","J'ai appris les bases, puis j'ai travaillé seul pendant plusieurs mois pour progresser.","Aprendi o básico e depois pratiquei sozinho durante vários meses para melhorar."],["Claire","Et tu exposes tes photos depuis quand ? Celle du port est vraiment réussie.","E desde quando você expõe suas fotos? Aquela do porto ficou realmente ótima."],["Lucas","Depuis le mois de mai. J'ai présenté ma première série il y a cinq mois.","Desde maio. Apresentei minha primeira série há cinco meses."],["Claire","Je prépare une exposition depuis le début de l'été, mais je n'ai pas encore choisi les photos.","Estou preparando uma exposição desde o começo do verão, mas ainda não escolhi as fotos."],["Lucas","Ça fait donc plusieurs mois que tu travailles sur ce projet. Tu veux un avis extérieur ?","Então faz vários meses que você trabalha nesse projeto. Quer uma opinião de alguém de fora?"],["Claire","Volontiers. J'ai essayé différentes idées pendant les vacances, sans trouver le bon thème.","Quero, sim. Experimentei várias ideias durante as férias, mas não encontrei o tema certo."],["Lucas","On peut regarder tes images demain. Je suis libre depuis la fin de mon dernier projet.","Podemos olhar suas imagens amanhã. Estou livre desde que terminei meu último projeto."],["Claire","Parfait. Ça fait longtemps que je cherche quelqu'un pour m'aider à faire une sélection.","Perfeito. Faz tempo que procuro alguém para me ajudar a selecionar as fotos."],["Lucas","Alors, apporte ton ordinateur. On prendra le temps de choisir sans se presser.","Então traga seu computador. Vamos escolher com calma, sem pressa."]],"grammar":[{"h":"Depuis: uma situação que continua","p":["Use <b>depuis</b> para indicar quando uma situação começou ou há quanto tempo ela continua. A estrutura pode ser <b>depuis + duração</b> ou <b>depuis + ponto de partida</b>.","Quando a situação começou no passado e continua no presente, o francês normalmente usa o <b>présent</b>. Em português, frequentemente usamos “há três anos”, “faz três anos” ou “desde”.","Também podemos usar <b>depuis quand</b> para perguntar desde quando algo acontece. A resposta pode indicar uma duração ou uma data."],"ex":[["Je fais de la photo depuis trois ans.","Fotografo há três anos."],["Elle habite ici depuis septembre.","Ela mora aqui desde setembro."],["Depuis quand tu connais ce quartier ?","Desde quando você conhece este bairro?"],["Nous attendons depuis vingt minutes.","Estamos esperando há vinte minutos."]],"tip":"Se a ação começou no passado e ainda continua, pense em <b>depuis + présent</b>. Não traduza automaticamente o passado do português por passé composé."},{"h":"Il y a: há quanto tempo algo aconteceu","p":["<b>Il y a + duração</b> indica quanto tempo se passou desde um acontecimento. Quando falamos de uma ação concluída no passado, normalmente usamos o <b>passé composé</b>.","Compare: <b>J'ai commencé il y a trois ans</b> destaca o momento em que comecei. Já <b>Je pratique depuis trois ans</b> informa que continuo praticando.","A expressão <b>il y a</b> também pode significar “há” no sentido de existência. O contexto indica se estamos falando de tempo ou de algo que existe."],"ex":[["J'ai acheté cet appareil il y a six mois.","Comprei esta câmera há seis meses."],["Nous nous sommes rencontrés il y a deux ans.","Nós nos conhecemos há dois anos."],["Il y a une semaine, elle a changé de travail.","Há uma semana, ela mudou de emprego."],["Il y a plusieurs photos sur la table.","Há várias fotos em cima da mesa."]],"tip":"<b>Depuis trois ans</b> indica uma duração que chega até agora. <b>Il y a trois ans</b> localiza um acontecimento no passado."},{"h":"Pendant: a duração de uma atividade","p":["<b>Pendant + duração</b> indica por quanto tempo uma atividade acontece ou aconteceu. Quando usamos o passé composé, normalmente estamos falando de um período concluído.","Diferentemente de depuis, pendant não indica necessariamente que uma situação continua até o presente. Ele destaca o intervalo de tempo.","Também é possível usar pendant com o presente ou o futuro, dependendo do contexto. No passado, é especialmente útil para contar quanto durou uma atividade."],"ex":[["J'ai étudié pendant deux heures hier.","Estudei durante duas horas ontem."],["Elle a travaillé à Paris pendant cinq ans.","Ela trabalhou em Paris durante cinco anos."],["Nous avons discuté pendant toute la soirée.","Conversamos durante a noite inteira."],["Je vais rester ici pendant trois jours.","Vou ficar aqui durante três dias."]],"tip":"Compare: <b>J'ai travaillé ici pendant deux ans</b> fala de um período concluído. <b>Je travaille ici depuis deux ans</b> indica que ainda trabalho aqui."},{"h":"Ça fait... que: outra maneira de expressar duração","p":["A estrutura <b>ça fait + duração + que + frase</b> é muito usada no francês falado para expressar há quanto tempo uma situação continua.","Ela frequentemente tem o mesmo significado de depuis. Compare: <b>Je travaille ici depuis un an</b> e <b>Ça fait un an que je travaille ici</b>.","Para perguntar a duração, use <b>Ça fait combien de temps que... ?</b>. Em situações mais formais, também podemos encontrar <b>Cela fait...</b>."],"ex":[["Ça fait quatre mois que je viens ici.","Faz quatro meses que venho aqui."],["Ça fait deux ans qu'elle apprend le français.","Faz dois anos que ela aprende francês."],["Ça fait combien de temps que tu attends ?","Faz quanto tempo que você está esperando?"],["Ça fait longtemps qu'on ne s'est pas vus.","Faz tempo que a gente não se vê."]],"tip":"Na conversa cotidiana, <b>ça fait... que</b> é uma alternativa muito natural a depuis."}],"vocab":[{"h":"Fotografia e projetos criativos","items":[["la photographie","a fotografia"],["un appareil photo","uma câmera fotográfica"],["un objectif","uma lente / uma objetiva"],["une exposition","uma exposição"],["un atelier","uma oficina"],["retoucher une photo","editar / retocar uma foto"],["une sélection","uma seleção"],["réussi / réussie","bem-feito / bem-feita"]]},{"h":"Expressões de tempo e duração","items":[["depuis","desde / há"],["depuis quand","desde quando"],["il y a","há / faz"],["pendant","durante / por"],["ça fait... que","faz... que"],["le mois dernier","no mês passado"],["l'été dernier","no verão passado"],["depuis longtemps","há muito tempo"]]},{"h":"Evolução e experiência","items":[["progresser","progredir / melhorar"],["apprendre les bases","aprender o básico"],["s'améliorer","melhorar"],["acquérir de l'expérience","adquirir experiência"],["débuter","começar / ser iniciante"],["participer à","participar de"],["un avis extérieur","uma opinião de alguém de fora"],["prendre son temps","fazer algo com calma"]]}],"pron":[{"h":"depuis","p":"Em <b>depuis</b>, a primeira sílaba é leve, aproximadamente “de”. O grupo <b>ui</b> tem um som arredondado, parecido com “üi”. A palavra soa aproximadamente “de-püi”. O s final não é pronunciado.","w":["depuis","depuis trois ans","depuis quand","depuis longtemps"]},{"h":"pendant","p":"Em <b>pendant</b>, as duas vogais são nasais. A pronúncia aproximada é “pã-dã”, com a boca mais aberta no francês. O t final é mudo.","w":["pendant","pendant deux semaines","pendant les vacances"]},{"h":"il y a e ça fait","p":"Na fala natural, <b>il y a</b> soa aproximadamente “il-iá” e pode ser reduzido. Já <b>ça fait</b> soa como “sa fé”, com a vogal final aberta. Treine as duas expressões como blocos.","w":["il y a un an","il y a cinq mois","ça fait longtemps","ça fait deux ans"]}],"mc":[{"q":"Há quanto tempo Lucas pratica fotografia?","o":["Há seis meses","Há três anos","Há cinco meses"],"a":1,"e":"Oui, je fais de la photo depuis trois ans, mais je n'utilise cet appareil que depuis six mois."},{"q":"Há quanto tempo Claire participa das oficinas do centro cultural?","o":["Há quatro meses","Há um ano","Há duas semanas"],"a":0,"e":"Ça fait quatre mois que je viens chaque mercredi. J'ai découvert cet endroit grâce à une amie."},{"q":"Quanto tempo durou o curso que Lucas fez no verão passado?","o":["Vários meses","Quatro semanas","Duas semanas"],"a":2,"e":"J'ai suivi un cours ici pendant deux semaines l'été dernier. Le professeur était très patient."},{"q":"Por que Claire ainda não concluiu a preparação de sua exposição?","o":["Porque perdeu sua câmera","Porque ainda não escolheu as fotos","Porque o centro cultural está fechado"],"a":1,"e":"Je prépare une exposition depuis le début de l'été, mais je n'ai pas encore choisi les photos."}],"gaps":[{"s":"Je fais de la photo ___ trois ans.","a":["depuis"],"h":"Fotografo há três anos."},{"s":"J'ai commencé la photographie ___ un an.","a":["il y a"],"h":"Comecei a fotografar há um ano."},{"s":"J'ai suivi ce cours ___ deux semaines l'été dernier.","a":["pendant"],"h":"Fiz esse curso durante duas semanas no verão passado."},{"s":"Ça ___ quatre mois que je viens ici chaque mercredi.","a":["fait"],"h":"Faz quatro meses que venho aqui toda quarta-feira."},{"s":"Je ___ membre de ce club depuis le printemps.","a":["suis"],"h":"Sou membro deste clube desde a primavera."},{"s":"J'___ acheté cet appareil il y a six mois.","a":["ai"],"h":"Comprei esta câmera há seis meses."}],"order":[{"t":["Je","travaille","ici","depuis","trois","ans."],"h":"Trabalho aqui há três anos."},{"t":["J'ai","commencé","il","y","a","un","an."],"h":"Comecei há um ano."},{"t":["Ça","fait","six","mois","que","j'apprends."],"h":"Faz seis meses que estou aprendendo."}],"dict":[{"t":"Je travaille dans cette entreprise depuis trois ans."},{"t":"J'ai commencé la photographie il y a un an."},{"t":"Nous avons suivi un atelier pendant deux semaines."},{"t":"Ça fait plusieurs mois que je prépare cette exposition."},{"t":"Depuis le mois de mai, je présente mes photos au public."}],"shadow":["Oui, je fais de la photo depuis trois ans, mais je n'utilise cet appareil que depuis six mois.","Ça fait quatre mois que je viens chaque mercredi. J'ai découvert cet endroit grâce à une amie.","Je prépare une exposition depuis le début de l'été, mais je n'ai pas encore choisi les photos.","Volontiers. J'ai essayé différentes idées pendant les vacances, sans trouver le bon thème."],"write":{"task":"Conte sua experiência com uma atividade que você pratica atualmente, como um esporte, um idioma ou um hobby. Diga há quanto tempo pratica, quando começou e quanto durou algum curso ou experiência concluída. Use depuis, il y a, pendant e ça fait... que.","ph":"Je pratique … depuis … . J'ai commencé il y a …"},"cards":[["Estudo francês há dois anos.","J'étudie le français depuis deux ans."],["Comecei há seis meses.","J'ai commencé il y a six mois."],["Moro aqui desde janeiro.","J'habite ici depuis janvier."],["Trabalhei lá durante três anos.","J'ai travaillé là-bas pendant trois ans."],["Faz tempo que espero por isso.","Ça fait longtemps que j'attends ça."],["Desde quando você pratica esse esporte?","Depuis quand tu pratiques ce sport ?"],["Fiz um curso durante um mês.","J'ai suivi un cours pendant un mois."],["Conheci essa pessoa há duas semanas.","J'ai rencontré cette personne il y a deux semaines."],["Faz um ano que trabalho neste projeto.","Ça fait un an que je travaille sur ce projet."],["Tenho esta câmera desde o verão.","J'ai cet appareil photo depuis l'été."]]},{"title":"Avant, j'avais déjà...","goal":"Contar acontecimentos no passado deixando clara a ordem em que ocorreram, usando o plus-que-parfait para falar de ações anteriores a outros fatos passados e combinando esse tempo com passé composé e imparfait.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Na segunda-feira, durante uma pausa no trabalho, Claire conta a Lucas como perdeu o trem para Bordeaux no sábado e o que aconteceu depois.","lines":[["Lucas","Alors, ton week-end à Bordeaux ? Tu as finalement pris le train samedi matin ?","E aí, como foi seu fim de semana em Bordeaux? Você conseguiu pegar o trem no sábado de manhã?"],["Claire","Oui, mais ça a mal commencé. Quand je suis arrivée à la gare, mon train était déjà parti.","Sim, mas começou mal. Quando cheguei à estação, meu trem já tinha partido."],["Lucas","Tu étais en retard ? Pourtant, tu avais préparé ton sac la veille, non ?","Você estava atrasada? Mas você tinha preparado sua mala na véspera, não tinha?"],["Claire","Oui, j'avais tout préparé, mais j'avais lu le mauvais horaire sur mon téléphone.","Sim, eu tinha preparado tudo, mas tinha lido o horário errado no celular."],["Lucas","Tu n'avais pas vérifié l'heure de départ sur ton billet avant de quitter la maison ?","Você não tinha conferido o horário de partida na passagem antes de sair de casa?"],["Claire","Non, j'avais regardé l'horaire du dimanche par erreur. J'ai compris mon erreur devant le panneau.","Não, eu tinha olhado o horário de domingo por engano. Percebi meu erro diante do painel."],["Lucas","Et tu avais réservé ta place longtemps avant le voyage ou seulement la veille ?","E você tinha reservado seu lugar muito antes da viagem ou só na véspera?"],["Claire","J'avais acheté mon billet trois semaines avant. J'étais vraiment déçue en voyant le quai vide.","Eu tinha comprado minha passagem três semanas antes. Fiquei muito decepcionada ao ver a plataforma vazia."],["Lucas","Tu as pu changer ton billet ou tu as dû en acheter un autre au dernier moment ?","Você conseguiu trocar a passagem ou teve que comprar outra na última hora?"],["Claire","Heureusement, une employée m'a proposé un autre train qui partait deux heures plus tard.","Felizmente, uma funcionária me ofereceu outro trem que partiria duas horas depois."],["Lucas","Donc, quand tu es arrivée à Bordeaux, tes amis avaient déjà commencé le dîner ?","Então, quando você chegou a Bordeaux, seus amigos já tinham começado o jantar?"],["Claire","Exactement. Ils avaient commandé les entrées, mais ils m'avaient gardé une place à table.","Exatamente. Eles já tinham pedido as entradas, mas tinham guardado um lugar para mim à mesa."],["Lucas","Au moins, tu n'as pas tout raté. Tu avais déjà visité Bordeaux avant ce voyage ?","Pelo menos você não perdeu tudo. Já tinha visitado Bordeaux antes dessa viagem?"],["Claire","Non, je n'y étais jamais allée. Le lendemain, on a marché dans le centre toute la journée.","Não, eu nunca tinha ido lá. No dia seguinte, caminhamos pelo centro o dia inteiro."],["Lucas","Finalement, tu as quand même profité du week-end. Tu as changé de réveil depuis ?","No fim, você aproveitou o fim de semana mesmo assim. Já trocou de despertador desde então?"],["Claire","Non, le réveil fonctionnait très bien ! Mais j'ai enregistré le bon horaire pour mon prochain départ.","Não, o despertador funcionava perfeitamente! Mas salvei o horário certo para minha próxima partida."]],"grammar":[{"h":"Plus-que-parfait: o passado anterior a outro passado","p":["O <b>plus-que-parfait</b> serve para falar de uma ação que já tinha acontecido antes de outro momento no passado. Em português, geralmente corresponde a “tinha feito”, “havia chegado” ou “já tinha saído”.","Imagine dois acontecimentos: primeiro, o trem partiu; depois, Claire chegou à estação. Para destacar essa ordem, usamos plus-que-parfait na ação mais antiga e passé composé na ação seguinte.","O plus-que-parfait também aparece em relatos que começam por uma consequência e depois explicam o que tinha acontecido antes."],"ex":[["Quand je suis arrivé, elle avait déjà mangé.","Quando cheguei, ela já tinha comido."],["Le train était parti avant notre arrivée.","O trem tinha partido antes da nossa chegada."],["J'étais fatigué parce que j'avais mal dormi.","Eu estava cansado porque tinha dormido mal."],["Elle a trouvé le livre qu'elle avait perdu.","Ela encontrou o livro que tinha perdido."]],"tip":"Pergunte qual acontecimento ocorreu primeiro. Se você estiver olhando para trás a partir de outro momento passado, provavelmente precisará do <b>plus-que-parfait</b>."},{"h":"Como formar o plus-que-parfait","p":["A formação é <b>avoir ou être no imparfait + participe passé</b> do verbo principal. Com avoir: j'avais parlé, tu avais fini, il avait compris, nous avions vu.","Os verbos que usam être no passé composé também usam être no plus-que-parfait. Por exemplo: j'étais parti, elle était arrivée, nous étions sortis.","Com o auxiliar être, o particípio concorda em gênero e número com o sujeito. Com o auxiliar avoir, normalmente não há concordância com o sujeito."],"ex":[["J'avais préparé mon sac.","Eu tinha preparado minha mala."],["Nous avions déjà terminé le travail.","Nós já tínhamos terminado o trabalho."],["Claire était arrivée trop tard.","Claire tinha chegado tarde demais."],["Mes amies étaient parties avant midi.","Minhas amigas tinham saído antes do meio-dia."]],"tip":"Você já conhece o participe passé do passé composé. No plus-que-parfait, a principal mudança é colocar o auxiliar no <b>imparfait</b>."},{"h":"Plus-que-parfait x passé composé x imparfait","p":["Ao contar uma história, os três tempos podem aparecer juntos. O <b>passé composé</b> apresenta os acontecimentos concluídos que fazem a narrativa avançar.","O <b>imparfait</b> descreve a situação, as condições e os hábitos no passado. Já o <b>plus-que-parfait</b> explica o que tinha acontecido antes do momento narrado.","Você não precisa colocar toda ação antiga no plus-que-parfait. Use esse tempo quando for importante estabelecer uma relação de anterioridade com outro momento passado."],"ex":[["Il faisait froid quand je suis sorti.","Estava frio quando saí."],["J'ai appelé Lucas, mais il était déjà parti.","Liguei para Lucas, mas ele já tinha saído."],["Elle était triste parce qu'elle avait perdu son téléphone.","Ela estava triste porque tinha perdido o celular."],["Nous sommes rentrés après avoir attendu longtemps.","Voltamos para casa depois de esperar bastante."]],"tip":"Pense em três funções: <b>imparfait</b> descreve, <b>passé composé</b> conta o que aconteceu e <b>plus-que-parfait</b> explica o que já tinha acontecido."},{"h":"Déjà, jamais e expressões de anterioridade","p":["<b>Déjà</b> significa “já” e frequentemente acompanha o plus-que-parfait. Normalmente aparece entre o auxiliar e o particípio passado.","Para dizer que algo nunca tinha acontecido antes de determinado momento passado, use <b>ne... jamais</b>. O ne aparece antes do auxiliar, e jamais geralmente fica entre o auxiliar e o particípio.","Expressões como <b>avant</b>, <b>la veille</b> e <b>quelques jours plus tôt</b> ajudam a organizar a sequência temporal. La veille significa “na véspera” em relação a um dia do passado."],"ex":[["J'avais déjà vu ce film.","Eu já tinha visto esse filme."],["Elle n'avait jamais pris l'avion.","Ela nunca tinha viajado de avião."],["Nous avions réservé la veille.","Tínhamos reservado na véspera."],["Il était parti quelques minutes plus tôt.","Ele tinha saído quelques minutes avant."]],"tip":"Compare <b>Je n'ai jamais visité Paris</b>, sobre sua experiência até agora, com <b>Je n'avais jamais visité Paris</b>, sobre sua experiência antes de um momento no passado."}],"vocab":[{"h":"Viagens de trem","items":[["une gare","uma estação ferroviária"],["un quai","uma plataforma de embarque"],["un billet","uma passagem"],["un horaire","um horário"],["un panneau d'affichage","um painel de informações"],["un départ","uma partida"],["une réservation","uma reserva"],["rater son train","perder o trem"]]},{"h":"Sequência e anterioridade","items":[["déjà","já"],["auparavant","anteriormente"],["avant","antes"],["la veille","na véspera"],["plus tôt","mais cedo / antes"],["entre-temps","nesse meio-tempo"],["finalement","no fim / finalmente"],["à ce moment-là","naquele momento"]]},{"h":"Problemas e soluções","items":[["se tromper","se enganar"],["par erreur","por engano"],["vérifier","conferir / verificar"],["se rendre compte de","perceber / dar-se conta de"],["être déçu / déçue","ficar decepcionado / decepcionada"],["changer son billet","trocar a passagem"],["au dernier moment","na última hora"],["profiter de","aproveitar"]]}],"pron":[{"h":"avais, avait e avaient","p":"As formas <b>avais</b>, <b>avait</b> e <b>avaient</b> têm a mesma pronúncia no francês padrão, aproximadamente “a-vé”, com o é aberto. As terminações escritas são diferentes, mas não se ouvem.","w":["j'avais","tu avais","il avait","ils avaient"]},{"h":"était, étais e étaient","p":"Em <b>étais</b>, <b>était</b> e <b>étaient</b>, a terminação tem som de é aberto, aproximadamente “é-té”, com a última vogal aberta. Não confunda com <b>été</b>, cujas vogais são mais fechadas.","w":["j'étais parti","elle était arrivée","ils étaient sortis","été"]},{"h":"déjà e jamais","p":"Em <b>déjà</b>, o j tem o som de j em “janela”, aproximadamente “dê-já”. Já <b>jamais</b> soa aproximadamente “ja-mé”, com a vogal final aberta e o s mudo.","w":["déjà","jamais","j'avais déjà mangé","je n'étais jamais allé"]}],"mc":[{"q":"O que já tinha acontecido quando Claire chegou à estação?","o":["O trem tinha sido cancelado","A estação tinha fechado","O trem já tinha partido"],"a":2,"e":"Oui, mais ça a mal commencé. Quand je suis arrivée à la gare, mon train était déjà parti."},{"q":"Por que Claire perdeu o trem?","o":["Porque tinha consultado o horário errado","Porque tinha esquecido sua mala","Porque tinha comprado a passagem para outra cidade"],"a":0,"e":"Oui, j'avais tout préparé, mais j'avais lu le mauvais horaire sur mon téléphone."},{"q":"O que os amigos de Claire já tinham feito quando ela chegou a Bordeaux?","o":["Tinham terminado a sobremesa","Tinham pedido as entradas","Tinham saído do restaurante"],"a":1,"e":"Exactement. Ils avaient commandé les entrées, mais ils m'avaient gardé une place à table."},{"q":"Claire já tinha visitado Bordeaux antes daquela viagem?","o":["Sim, várias vezes","Sim, uma vez quando era criança","Não, nunca tinha ido"],"a":2,"e":"Non, je n'y étais jamais allée. Le lendemain, on a marché dans le centre toute la journée."}],"gaps":[{"s":"Quand je suis arrivée, le train ___ déjà parti.","a":["était"],"h":"Quando cheguei, o trem já tinha partido."},{"s":"J'___ préparé mon sac la veille.","a":["avais"],"h":"Eu tinha preparado minha mala na véspera."},{"s":"Je n'___ jamais allée à Bordeaux avant ce voyage.","a":["étais"],"h":"Eu nunca tinha ido a Bordeaux antes dessa viagem."},{"s":"Mes amis avaient déjà ___ les entrées.","a":["commandé"],"h":"Meus amigos já tinham pedido as entradas."},{"s":"Nous ___ partis avant l'arrivée de la pluie.","a":["étions"],"h":"Nós tínhamos saído antes da chegada da chuva."},{"s":"Elle avait ___ le mauvais horaire sur son téléphone.","a":["regardé"],"h":"Ela tinha consultado o horário errado no celular."}],"order":[{"t":["J'avais","déjà","préparé","mon","sac."],"h":"Eu já tinha preparado minha mala."},{"t":["Le","train","était","déjà","parti."],"h":"O trem já tinha partido."},{"t":["Elle","n'était","jamais","allée","à","Bordeaux."],"h":"Ela nunca tinha ido a Bordeaux."}],"dict":[{"t":"Quand je suis arrivée, le train était déjà parti."},{"t":"J'avais préparé mon sac la veille du départ."},{"t":"Nous avions réservé nos places trois semaines avant."},{"t":"Elle n'était jamais allée dans cette région auparavant."},{"t":"Ils avaient déjà commandé les entrées quand je suis arrivée."}],"shadow":["Oui, mais ça a mal commencé. Quand je suis arrivée à la gare, mon train était déjà parti.","Oui, j'avais tout préparé, mais j'avais lu le mauvais horaire sur mon téléphone.","J'avais acheté mon billet trois semaines avant. J'étais vraiment déçue en voyant le quai vide.","Exactement. Ils avaient commandé les entrées, mais ils m'avaient gardé une place à table."],"write":{"task":"Conte um imprevisto que aconteceu durante uma viagem, no trabalho ou em algum compromisso. Explique o que aconteceu e pelo menos duas coisas que já tinham acontecido antes daquele momento. Use plus-que-parfait, passé composé e expressions como déjà, avant e la veille.","ph":"Un jour, quand je suis arrivé …, j'ai découvert que … avait déjà …"},"cards":[["Eu já tinha terminado meu trabalho.","J'avais déjà terminé mon travail."],["Ela tinha saído antes da minha chegada.","Elle était partie avant mon arrivée."],["Nós nunca tínhamos visto aquilo.","Nous n'avions jamais vu ça."],["Eles tinham reservado uma mesa.","Ils avaient réservé une table."],["Eu tinha esquecido minha carteira.","J'avais oublié mon portefeuille."],["O filme já tinha começado.","Le film avait déjà commencé."],["Você tinha recebido minha mensagem?","Tu avais reçu mon message ?"],["Tínhamos comprado as passagens na véspera.","Nous avions acheté les billets la veille."],["Ela já tinha ido embora quando liguei.","Elle était déjà partie quand j'ai appelé."],["Eu nunca tinha experimentado esse prato.","Je n'avais jamais goûté ce plat."]]},{"title":"Si j'avais le temps...","goal":"Falar sobre situações imaginárias e seus possíveis resultados, expressar desejos, fazer sugestões e dar conselhos de maneira educada, usando si + imparfait, conditionnel présent e expressões como à ta place, je...","speakers":{"Claire":"f","Lucas":"m"},"setting":"No fim de uma tarde de trabalho, em um café de Lyon, Claire e Lucas conversam sobre a vontade de fazer uma viagem curta para descansar e imaginam como organizariam o passeio.","lines":[["Lucas","Tu as l'air fatiguée. Tu travailles encore sur ton projet du week-end ?","Você parece cansada. Ainda está trabalhando naquele projeto do fim de semana?"],["Claire","Oui. Si j'avais plus de temps, je partirais quelques jours à la montagne pour me reposer.","Sim. Se eu tivesse mais tempo, passaria alguns dias na montanha para descansar."],["Lucas","À ta place, je prendrais au moins une journée sans écran. Tu pourrais vraiment déconnecter.","No seu lugar, eu tiraria pelo menos um dia longe das telas. Você poderia realmente se desligar."],["Claire","Ce serait idéal, mais je dois terminer mon dossier avant vendredi. Et toi, tu ferais quoi ?","Seria ideal, mas preciso terminar meu relatório antes de sexta. E você, o que faria?"],["Lucas","Si je pouvais choisir, j'irais dans un petit village près d'un lac. Je marcherais toute la journée.","Se eu pudesse escolher, iria a uma vila perto de um lago. Caminharia o dia inteiro."],["Claire","Ça me plairait aussi. Tu inviterais des amis ou tu préférerais partir seul ?","Eu também gostaria disso. Você convidaria amigos ou preferiria viajar sozinho?"],["Lucas","Je partirais avec un ou deux amis. On louerait une petite maison et on cuisinerait ensemble.","Eu viajaria com um ou dois amigos. Alugaríamos uma casinha e cozinharíamos juntos."],["Claire","Si on avait un budget plus large, on pourrait même rester une semaine entière.","Se tivéssemos um orçamento maior, poderíamos até ficar uma semana inteira."],["Lucas","C'est vrai. Mais avec notre budget actuel, je chercherais une destination accessible en train.","É verdade. Mas com nosso orçamento atual, eu procuraria um destino acessível de trem."],["Claire","Tu aurais un conseil pour trouver un logement sans trop dépenser ?","Você teria alguma dica para encontrar hospedagem sem gastar muito?"],["Lucas","À ta place, je comparerais les prix et je réserverais en dehors des vacances scolaires.","No seu lugar, eu compararia os preços e reservaria fora das férias escolares."],["Claire","Et si la météo était mauvaise ? Je n'aimerais pas passer trois jours sous la pluie.","E se o tempo estivesse ruim? Eu não gostaria de passar três dias debaixo de chuva."],["Lucas","On visiterait les villages voisins ou on lirait tranquillement. Ce ne serait pas un problème.","Visitaríamos as vilas vizinhas ou leríamos tranquilamente. Isso não seria um problema."],["Claire","Tu as raison. Si je finissais mon dossier jeudi, je pourrais partir dès vendredi soir.","Você tem razão. Se eu terminasse meu relatório na quinta, poderia viajar já na sexta à noite."],["Lucas","Alors, pourquoi ne pas préparer une liste ? Je t'aiderais volontiers à organiser le trajet.","Então, por que não preparar uma lista? Eu ajudaria você com prazer a organizar o trajeto."],["Claire","Bonne idée ! Je choisirais deux destinations, puis on comparerait les prix avant de décider.","Boa ideia! Eu escolheria dois destinos e depois compararíamos os preços antes de decidir."]],"grammar":[{"h":"Conditionnel présent: falar do que aconteceria","p":["O <b>conditionnel présent</b> permite falar de ações imaginárias, possibilidades, desejos e situações que dependem de uma condição. Em português, muitas vezes corresponde a terminações como “-ria”: eu viajaria, você faria, nós ficaríamos.","Para formar o conditionnel présent, normalmente usamos o radical do futuro simples e acrescentamos as terminações do imparfait: <b>-ais, -ais, -ait, -ions, -iez, -aient</b>.","Nos verbos regulares terminados em -er e -ir, o infinitivo costuma servir como base. Nos verbos terminados em -re, retiramos o e final. Alguns verbos muito comuns possuem radicais irregulares."],"ex":[["Je voyagerais plus souvent.","Eu viajaria com mais frequência."],["Nous choisirions un hôtel moins cher.","Escolheríamos um hotel mais barato."],["Elle prendrait le train.","Ela pegaria o trem."],["Vous resteriez deux jours de plus.","Vocês ficariam mais dois dias."]],"tip":"As terminações são as mesmas do imparfait, mas o radical normalmente é o do futuro. Compare <b>je parlais</b> com <b>je parlerais</b>."},{"h":"Si + imparfait + conditionnel présent","p":["Para imaginar uma situação diferente da realidade atual ou apresentar uma possibilidade hipotética, usamos <b>si + imparfait</b> na condição e <b>conditionnel présent</b> no resultado.","A estrutura equivale a construções como “se eu tivesse mais tempo, viajaria”. A ordem das duas partes pode ser invertida sem mudar o sentido principal.","A regra fundamental é que, nessa estrutura, <b>não usamos conditionnel logo depois de si</b>. A condição recebe imparfait; a consequência recebe conditionnel présent."],"ex":[["Si j'avais le temps, je voyagerais davantage.","Se eu tivesse tempo, viajaria mais."],["Si nous habitions près de la mer, nous irions à la plage.","Se morássemos perto do mar, iríamos à praia."],["Je serais plus détendu si je travaillais moins.","Eu estaria mais tranquilo se trabalhasse menos."],["Si tu connaissais cette ville, tu pourrais nous guider.","Se você conhecesse esta cidade, poderia nos guiar."]],"tip":"Correto: <b>Si j'avais le temps, je partirais</b>. Incorreto: si j'aurais le temps. Depois de si, use o imparfait nessa construção."},{"h":"Verbos irregulares e expressões de desejo","p":["Alguns dos verbos mais úteis no conditionnel présent são irregulares: <b>être → serais</b>, <b>avoir → aurais</b>, <b>aller → irais</b>, <b>faire → ferais</b>, <b>pouvoir → pourrais</b> e <b>vouloir → voudrais</b>.","As formas <b>je voudrais</b> e <b>j'aimerais</b> são muito usadas para expressar desejos e fazer pedidos de maneira mais educada do que com o presente.","As formas <b>je pourrais</b> e <b>ce serait</b> ajudam a apresentar possibilidades sem parecer que você está afirmando algo com certeza."],"ex":[["J'aimerais passer quelques jours à la campagne.","Eu gostaria de passar alguns dias no campo."],["Je voudrais réserver une chambre pour samedi.","Eu gostaria de reservar um quarto para sábado."],["Ce serait une bonne occasion de se reposer.","Seria uma boa oportunidade para descansar."],["Tu pourrais venir avec nous.","Você poderia vir com a gente."]],"tip":"Aprenda <b>j'aimerais</b>, <b>je voudrais</b>, <b>je pourrais</b> e <b>ce serait</b> como expressões prontas. Elas aparecem o tempo todo em conversas reais."},{"h":"Dar conselhos com à ta place e devoir","p":["A expressão <b>à ta place, je...</b> significa “no seu lugar, eu...”. É uma maneira natural de aconselhar alguém sem dar uma ordem direta. Depois dela, usamos frequentemente o conditionnel présent.","Também usamos <b>tu devrais</b> para dizer “você deveria”. Essa forma costuma soar mais suave que tu dois, que expressa obrigação.","Para aconselhar uma pessoa com quem usamos vous, podemos dizer <b>à votre place, je...</b> ou <b>vous devriez...</b>. A escolha depende da situação e do grau de proximidade."],"ex":[["À ta place, je prendrais quelques jours de repos.","No seu lugar, eu tiraria alguns dias de descanso."],["Tu devrais comparer les prix avant de réserver.","Você deveria comparar os preços antes de reservar."],["À votre place, je demanderais plus d'informations.","No lugar do senhor ou da senhora, eu pediria mais informações."],["Vous devriez partir un peu plus tôt.","Vocês deveriam sair um pouco mais cedo."]],"tip":"Para dar um conselho gentil, prefira <b>tu devrais</b> ou <b>à ta place, je...</b> quando não houver uma obrigação real."}],"vocab":[{"h":"Viagens e descanso","items":[["se reposer","descansar"],["déconnecter","se desconectar"],["un séjour","uma estadia"],["un logement","uma hospedagem / acomodação"],["louer une maison","alugar uma casa"],["un trajet","um trajeto"],["une destination","um destino"],["les vacances scolaires","as férias escolares"]]},{"h":"Hipóteses e desejos","items":[["si j'avais","se eu tivesse"],["si je pouvais","se eu pudesse"],["je voudrais","eu gostaria / eu queria"],["j'aimerais","eu gostaria"],["je pourrais","eu poderia"],["ce serait","seria"],["je préférerais","eu preferiria"],["à ta place","no seu lugar"]]},{"h":"Planejamento e orçamento","items":[["un budget","um orçamento"],["comparer les prix","comparar os preços"],["faire des économies","economizar dinheiro"],["réserver à l'avance","reservar com antecedência"],["dépenser","gastar"],["abordable","acessível financeiramente"],["une offre","uma oferta"],["une dépense","uma despesa"]]}],"pron":[{"h":"serais e serait","p":"As formas <b>serais</b> e <b>serait</b> têm a mesma pronúncia, aproximadamente “se-ré”, com o é final aberto. O s e o t finais são mudos. A diferença aparece na escrita e no sujeito.","w":["je serais","tu serais","ce serait","il serait"]},{"h":"pourrais e voudrais","p":"Em <b>pourrais</b>, a pronúncia é aproximadamente “pu-ré”. Em <b>voudrais</b>, soa como “vu-dré”, com um r francês pronunciado na garganta. As terminações têm som de é aberto.","w":["je pourrais","tu pourrais","je voudrais","vous voudriez"]},{"h":"Si j'avais e j'irais","p":"Em <b>si j'avais</b>, j'avais começa com o som do j de “janela”. Já <b>j'irais</b> começa com a vogal i depois desse j. Pratique as expressões completas, sem fazer pausas entre as palavras.","w":["si j'avais le temps","si je pouvais choisir","j'irais à Paris","j'aimerais voyager"]}],"mc":[{"q":"O que Claire faria se tivesse mais tempo?","o":["Passaria alguns dias na montanha","Mudaria definitivamente de cidade","Compraria um computador novo"],"a":0,"e":"Oui. Si j'avais plus de temps, je partirais quelques jours à la montagne pour me reposer."},{"q":"Para onde Lucas iria se pudesse escolher?","o":["Para uma grande cidade à beira-mar","Para um hotel no centro de Paris","Para uma pequena vila perto de um lago"],"a":2,"e":"Si je pouvais choisir, j'irais dans un petit village près d'un lac. Je marcherais toute la journée."},{"q":"O que Lucas aconselha Claire a fazer para gastar menos com hospedagem?","o":["Reservar durante as férias escolares","Comparar preços e reservar fora das férias escolares","Escolher sempre o hotel mais próximo da estação"],"a":1,"e":"À ta place, je comparerais les prix et je réserverais en dehors des vacances scolaires."},{"q":"O que Claire poderia fazer se terminasse seu relatório na quinta-feira?","o":["Viajar já na sexta-feira à noite","Pedir férias por um mês","Ficar trabalhando durante todo o fim de semana"],"a":0,"e":"Tu as raison. Si je finissais mon dossier jeudi, je pourrais partir dès vendredi soir."}],"gaps":[{"s":"Si j'___ (avoir) plus de temps, je voyagerais davantage.","a":["avais"],"h":"Se eu tivesse mais tempo, viajaria mais."},{"s":"À ta place, je ___ (prendre) une journée de repos.","a":["prendrais"],"h":"No seu lugar, eu tiraria um dia de descanso."},{"s":"Si nous ___ (prendre) le train, nous économiserions de l'argent.","a":["prenions"],"h":"Se pegássemos o trem, economizaríamos dinheiro."},{"s":"Si je ___ (pouvoir) choisir, j'irais à la montagne.","a":["pouvais"],"h":"Se eu pudesse escolher, iria para a montanha."},{"s":"Nous ___ (aller) au lac si la météo était bonne.","a":["irions"],"h":"Iríamos ao lago se o tempo estivesse bom."},{"s":"Tu ___ (devoir) comparer les prix avant de réserver.","a":["devrais"],"h":"Você deveria comparar os preços antes de reservar."}],"order":[{"t":["Si","j'avais","le","temps,","je","partirais."],"h":"Se eu tivesse tempo, viajaria."},{"t":["À","ta","place,","je","réserverais","tôt."],"h":"No seu lugar, eu reservaria cedo."},{"t":["Nous","irions","au","lac","ensemble."],"h":"Iríamos ao lago juntos."}],"dict":[{"t":"Si j'avais plus de temps, je voyagerais davantage."},{"t":"À ta place, je prendrais quelques jours de repos."},{"t":"Nous pourrions louer une petite maison près du lac."},{"t":"J'aimerais trouver un logement confortable et abordable."},{"t":"Si la météo était meilleure, nous partirions dès demain matin."}],"shadow":["Oui. Si j'avais plus de temps, je partirais quelques jours à la montagne pour me reposer.","Si je pouvais choisir, j'irais dans un petit village près d'un lac. Je marcherais toute la journée.","À ta place, je comparerais les prix et je réserverais en dehors des vacances scolaires.","Tu as raison. Si je finissais mon dossier jeudi, je pourrais partir dès vendredi soir."],"write":{"task":"Imagine que você tivesse uma semana livre e um orçamento maior para viajar. Escreva o que faria, para onde iria, com quem viajaria e onde ficaria. Depois, dê dois conselhos a um amigo que quer fazer uma viagem econômica. Use si + imparfait, conditionnel présent, j'aimerais e à ta place.","ph":"Si j'avais une semaine libre, je partirais … . J'aimerais …"},"cards":[["Se eu tivesse dinheiro, viajaria mais.","Si j'avais de l'argent, je voyagerais plus."],["Eu gostaria de conhecer essa região.","J'aimerais découvrir cette région."],["No seu lugar, eu esperaria um pouco.","À ta place, j'attendrais un peu."],["Você deveria descansar mais.","Tu devrais te reposer davantage."],["Poderíamos viajar juntos.","Nous pourrions voyager ensemble."],["Seria uma ótima oportunidade.","Ce serait uma excelente ocasião."],["Se eu pudesse, trabalharia menos.","Si je pouvais, je travaillerais moins."],["Eu preferiria ficar perto do centro.","Je préférerais rester près du centre."],["O que você faria no meu lugar?","Tu ferais quoi à ma place ?"],["Eu reservaria com antecedência para economizar.","Je réserverais à l'avance pour faire des économies."]]},{"title":"Il faut que tu viennes","goal":"Organizar tarefas, expressar necessidades e desejos e indicar o que deve acontecer antes de outra ação, usando o subjonctif présent depois de il faut que, vouloir que e avant que.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Na sexta-feira à tarde, no centro cultural de Lyon, Claire e Lucas dividem as tarefas para uma exposição de fotografias que abrirá no sábado.","lines":[["Claire","Lucas, tu peux venir au centre culturel demain matin ? On prépare l'exposition de samedi.","Lucas, você pode vir ao centro cultural amanhã de manhã? Estamos preparando a exposição de sábado."],["Lucas","Oui, mais il faut que je finisse un dossier avant de partir. Tu veux que j'arrive à quelle heure ?","Sim, mas preciso terminar um relatório antes de sair. Você quer que eu chegue a que horas?"],["Claire","Il faut que tu viennes vers neuf heures. Je voudrais qu'on installe les photos avant midi.","Você precisa vir por volta das nove. Eu gostaria que a gente instalasse as fotos antes do meio-dia."],["Lucas","D'accord. Tu préfères que je prépare les cadres ou que je vérifie les étiquettes ?","Certo. Você prefere que eu prepare as molduras ou confira as etiquetas?"],["Claire","Je veux que tu vérifies les noms des artistes. Il faut qu'ils soient corrects.","Quero que você confira os nomes dos artistas. Eles precisam estar corretos."],["Lucas","Très bien. Et pour les affiches, il faut que nous fassions quelque chose aujourd'hui ?","Muito bem. E quanto aos cartazes, precisamos fazer alguma coisa hoje?"],["Claire","Oui, avant que les visiteurs arrivent, il faut qu'on mette des affiches à l'entrée.","Sim, antes que os visitantes cheguem, precisamos colocar cartazes na entrada."],["Lucas","Je peux les imprimer ce soir, mais il faut que j'aie la version finale du programme.","Posso imprimi-los hoje à noite, mas preciso ter a versão final da programação."],["Claire","Je t'envoie le programme après la réunion. Il faut aussi que nous ayons assez de chaises.","Vou enviar a programação para você depois da reunião. Também precisamos ter cadeiras suficientes."],["Lucas","Tu veux que j'aille en chercher dans la salle voisine ?","Você quer que eu vá buscar algumas na sala ao lado?"],["Claire","Oui, s'il te plaît. Je préfère qu'elles soient déjà installées avant l'ouverture.","Sim, por favor. Prefiro que elas já estejam colocadas antes da abertura."],["Lucas","Et qui accueille le public ? Il faut qu'une personne reste près de la porte.","E quem recebe o público? É preciso que alguém fique perto da porta."],["Claire","Je m'en occupe. Mais je veux que tu m'appelles si un artiste arrive en avance.","Eu cuido disso. Mas quero que você me ligue se algum artista chegar adiantado."],["Lucas","Pas de problème. Tu veux que je fasse une dernière vérification des lumières ?","Sem problema. Você quer que eu faça uma última verificação das luzes?"],["Claire","Oui, avant qu'on ouvre les portes, il faut que tout soit prêt.","Sim, antes de abrirmos as portas, tudo precisa estar pronto."],["Lucas","Alors, je note toutes les tâches. Comme ça, on n'oubliera rien demain.","Então vou anotar todas as tarefas. Assim, não vamos esquecer nada amanhã."]],"grammar":[{"h":"Il faut que: necessidade com subjonctif","p":["Usamos <b>il faut que + sujeito + subjonctif présent</b> quando é necessário que alguém faça algo. É diferente de <b>il faut + infinitif</b>, que expressa uma necessidade de forma geral, sem indicar obrigatoriamente quem fará a ação.","O subjonctif não é um tempo futuro: ele expressa aqui uma ação desejada ou necessária, que ainda pode não ter acontecido. A tradução natural costuma ser “é preciso que”, “preciso que” ou “tem que”.","A expressão é impessoal: <b>il faut que</b> não muda com o sujeito da oração seguinte. O verbo depois de que é que assume a forma correspondente à pessoa."],"ex":[["Il faut que tu arrives avant neuf heures.","Você precisa chegar antes das nove horas."],["Il faut que nous finissions le programme.","Precisamos terminar a programação."],["Il faut qu'elle soit à l'accueil.","Ela precisa estar na recepção."]],"tip":"Compare <b>Il faut préparer la salle</b> (é preciso preparar a sala) com <b>Il faut que tu prépares la salle</b> (você precisa prepará-la)."},{"h":"Vouloir que: o que uma pessoa deseja que outra faça","p":["Quando alguém quer que outra pessoa faça algo, usamos <b>vouloir que + subjonctif</b>. Isso também ocorre com expressões como <b>préférer que</b>. O verbo principal apresenta o desejo; o subjonctif aparece na ação desejada.","Quando o sujeito é o mesmo nas duas ações, normalmente usamos <b>vouloir + infinitif</b>: Je veux partir. Com sujeitos diferentes, usamos Je veux que tu partes.","<b>Je voudrais que...</b> é uma forma educada de expressar um desejo, e continua exigindo o subjonctif na oração seguinte."],"ex":[["Je veux que tu vérifies les étiquettes.","Quero que você confira as etiquetas."],["Elle préfère que nous arrivions ensemble.","Ela prefere que cheguemos juntos."],["Je voudrais que tout soit prêt demain.","Eu gostaria que tudo estivesse pronto amanhã."]],"tip":"Observe quem faz cada ação: <b>Je veux partir</b>, mas <b>Je veux que tu partes</b>."},{"h":"Avant que: antes que alguma coisa aconteça","p":["Use <b>avant que + subjonctif</b> quando a expressão introduz uma oração com sujeito e verbo: antes que os visitantes cheguem, antes que a reunião comece.","Se não há uma nova oração com sujeito, prefira <b>avant de + infinitif</b>, especialmente quando a pessoa que realiza as duas ações é a mesma.","Em registros mais formais, pode aparecer um <b>ne</b> sem sentido negativo depois de avant que. Por enquanto, use a construção simples, sem esse ne."],"ex":[["Partons avant que la pluie commence.","Vamos sair antes que a chuva comece."],["Il faut finir avant que les invités arrivent.","Precisamos terminar antes que os convidados cheguem."],["Je vérifie la liste avant de partir.","Confiro a lista antes de sair."]],"tip":"<b>Avant de partir</b> = antes de sair. <b>Avant qu'il parte</b> = antes que ele saia."},{"h":"Como formar o subjonctif présent","p":["Para muitos verbos regulares, partimos da forma <b>ils/elles</b> no presente do indicativo, retiramos <b>-ent</b> e acrescentamos <b>-e, -es, -e, -ions, -iez, -ent</b>. Por exemplo: ils parlent → que je parle; ils finissent → que tu finisses.","Alguns verbos frequentes exigem atenção: <b>être</b> (que je sois, que nous soyons), <b>avoir</b> (que j'aie, que nous ayons), <b>aller</b> (que j'aille, que nous allions) e <b>faire</b> (que je fasse, que nous fassions).","O verbo <b>venir</b>, presente no título da unidade, também é irregular: que je vienne, que tu viennes, qu'il vienne, que nous venions, que vous veniez, qu'ils viennent. Algumas formas do subjonctif são idênticas às do presente do indicativo; é a construção que determina o modo."],"ex":[["Il faut que tu viennes demain.","Você precisa vir amanhã."],["Je veux qu'elle aille chercher des chaises.","Quero que ela vá buscar cadeiras."],["Il faut que nous fassions attention.","Precisamos prestar atenção."],["Je préfère qu'ils aient une copie du programme.","Prefiro que eles tenham uma cópia da programação."]],"tip":"Memorize primeiro as formas mais usadas: <b>sois, aie, aille, fasse, vienne</b>. Depois observe como elas mudam com cada sujeito."}],"vocab":[{"h":"Organização de eventos","items":[["une exposition","uma exposição"],["un cadre","uma moldura"],["une étiquette","uma etiqueta"],["une affiche","um cartaz"],["un programme","uma programação"],["une entrée","uma entrada"],["une ouverture","uma abertura"],["accueillir le public","receber o público"]]},{"h":"Pedidos e necessidades","items":[["il faut que","é preciso que"],["vouloir que","querer que"],["préférer que","preferir que"],["avant que","antes que"],["vérifier","conferir / verificar"],["prévenir","avisar"],["s'occuper de","cuidar de"],["être prêt / prête","estar pronto / pronta"]]},{"h":"Trabalho em equipe","items":[["une tâche","uma tarefa"],["répartir les tâches","dividir as tarefas"],["une version finale","uma versão final"],["une vérification","uma conferência / verificação"],["une salle voisine","uma sala ao lado"],["installer","instalar / organizar no lugar"],["imprimer","imprimir"],["en avance","adiantado / antes da hora"]]}],"pron":[{"h":"que tu viennes","p":"Em <b>viennes</b>, a combinação <b>ienn</b> tem uma vogal aberta seguida do som n, sem nasalização: aproximadamente “vièn”. O s final é mudo. Em <b>que tu viennes</b>, o que costuma ser leve: “ke tü vièn”.","w":["que tu viennes","qu'il vienne","que nous venions"]},{"h":"sois e soit","p":"<b>Sois</b> e <b>soit</b> soam igual, aproximadamente “suá”. O s ou t final não é pronunciado. Compare com <b>soyons</b>, aproximadamente “sua-iõ”, com vogal nasal no final.","w":["que je sois","qu'elle soit","que nous soyons"]},{"h":"j'aie e que je fasse","p":"<b>J'aie</b> tem som de “jé” aberto, como o j de “janela”. <b>Fasse</b> soa aproximadamente “fass”, com o e final mudo. Treine as formas ligadas a que, como aparecem em pedidos reais.","w":["il faut que j'aie","que tu aies","que je fasse","que nous fassions"]}],"mc":[{"q":"A que horas Claire precisa que Lucas chegue?","o":["Por volta das oito horas","Por volta das nove horas","Depois do meio-dia"],"a":1,"e":"Il faut que tu viennes vers neuf heures. Je voudrais qu'on installe les photos avant midi."},{"q":"O que Claire quer que Lucas confira?","o":["Os nomes dos artistas","O preço dos ingressos","O endereço dos visitantes"],"a":0,"e":"Je veux que tu vérifies les noms des artistes. Il faut qu'ils soient corrects."},{"q":"O que Lucas precisa receber para imprimir os cartazes?","o":["Uma lista de convidados","As fotografias originais","A versão final da programação"],"a":2,"e":"Je peux les imprimer ce soir, mais il faut que j'aie la version finale du programme."},{"q":"O que Claire prefere que esteja pronto antes da abertura?","o":["O almoço dos artistas","As cadeiras já instaladas","O relatório de Lucas"],"a":1,"e":"Oui, s'il te plaît. Je préfère qu'elles soient déjà installées avant l'ouverture."}],"gaps":[{"s":"Il faut que tu ___ (venir) avant neuf heures.","a":["viennes"],"h":"Você precisa vir antes das nove horas."},{"s":"Je veux que vous ___ (vérifier) les affiches.","a":["vérifiiez"],"h":"Quero que vocês confiram os cartazes."},{"s":"Il faut qu'elle ___ (être) à l'entrée.","a":["soit"],"h":"Ela precisa estar na entrada."},{"s":"Je préfère que nous ___ (avoir) assez de chaises.","a":["ayons"],"h":"Prefiro que tenhamos cadeiras suficientes."},{"s":"Avant qu'on ___ (ouvrir) les portes, vérifie les lumières.","a":["ouvre"],"h":"Antes que a gente abra as portas, confira as luzes."},{"s":"Je voudrais que tu ___ (faire) une dernière vérification.","a":["fasses"],"h":"Eu gostaria que você fizesse uma última verificação."}],"order":[{"t":["Il","faut","que","tu","viennes","demain."],"h":"Você precisa vir amanhã."},{"t":["Je","veux","que","tu","sois","prêt."],"h":"Quero que você esteja pronto."},{"t":["Partons","avant","que","la","pluie","commence."],"h":"Vamos sair antes que a chuva comece."}],"dict":[{"t":"Il faut que tu viennes avant l'ouverture de l'exposition."},{"t":"Je voudrais que nous finissions le programme aujourd'hui."},{"t":"Il faut que j'aie les affiches avant ce soir."},{"t":"Avant que les invités arrivent, il faut que tout soit prêt."},{"t":"Je préfère que vous fassiez une dernière vérification."}],"shadow":["Il faut que tu viennes vers neuf heures. Je voudrais qu'on installe les photos avant midi.","Je veux que tu vérifies les noms des artistes. Il faut qu'ils soient corrects.","Je peux les imprimer ce soir, mais il faut que j'aie la version finale du programme.","Oui, avant qu'on ouvre les portes, il faut que tout soit prêt."],"write":{"task":"Você vai organizar um encontro ou pequeno evento com um amigo. Escreva cinco ou seis frases dizendo o que cada pessoa precisa fazer, o que você quer que esteja pronto e o que deve acontecer antes da chegada dos convidados. Use il faut que, je veux que ou je voudrais que e avant que.","ph":"Pour notre événement, il faut que tu … . Je voudrais que nous …"},"cards":[["Preciso que você chegue cedo.","Il faut que tu arrives tôt."],["Quero que você me ligue hoje.","Je veux que tu m'appelles aujourd'hui."],["É preciso que ela esteja aqui.","Il faut qu'elle soit ici."],["Prefiro que a gente vá junto.","Je préfère qu'on y aille ensemble."],["Antes que a reunião comece, leia isto.","Avant que la réunion commence, lis ça."],["Quero que você faça isso amanhã.","Je veux que tu fasses ça demain."],["Precisamos ter mais informações.","Il faut que nous ayons plus d'informations."],["Quero que eles terminem hoje.","Je veux qu'ils finissent aujourd'hui."],["Você precisa ficar até o fim.","Il faut que tu restes jusqu'à la fin."],["Eu gostaria que tudo desse certo.","Je voudrais que tout se passe bien."]]},{"title":"La personne qui...","goal":"Descrever pessoas, lugares e objetos com mais precisão e unir informações em frases naturais usando os pronomes relativos qui, que, où e dont.","speakers":{"Claire":"f","Lucas":"m"},"setting":"No domingo à tarde, enquanto tomam um café em Lyon, Claire conta a Lucas sobre dois apartamentos que visitou porque pretende se mudar.","lines":[["Lucas","Alors, tu as trouvé l'appartement dont tu m'avais parlé la semaine dernière ?","Então, você encontrou o apartamento de que tinha me falado na semana passada?"],["Claire","J'en ai visité un qui se trouve près du parc, mais le loyer est trop élevé.","Visitei um que fica perto do parque, mas o aluguel é caro demais."],["Lucas","C'est celui que tu avais vu sur le site de l'agence ?","É aquele que você tinha visto no site da imobiliária?"],["Claire","Oui. Les photos que l'agence a publiées étaient très belles, mais les pièces sont petites.","Sim. As fotos que a imobiliária publicou eram lindas, mas os cômodos são pequenos."],["Lucas","Et le quartier où il se trouve ? Il est agréable ?","E o bairro onde ele fica? É agradável?"],["Claire","Oui, c'est un endroit où je pourrais aller au travail à vélo. Mais je cherche moins cher.","Sim, é um lugar de onde eu poderia ir de bicicleta ao trabalho. Mas procuro algo mais barato."],["Lucas","Tu connais quelqu'un qui habite là-bas ?","Você conhece alguém que mora lá?"],["Claire","Une collègue qui vit dans la rue voisine m'a conseillé de visiter un autre logement.","Uma colega que mora na rua ao lado me aconselhou a visitar outro imóvel."],["Lucas","C'est l'appartement dont les fenêtres donnent sur une cour intérieure ?","É o apartamento cujas janelas dão para um pátio interno?"],["Claire","Exactement. C'est celui dont je t'ai envoyé les photos hier soir.","Exatamente. É aquele de que te mandei as fotos ontem à noite."],["Lucas","Ah oui ! La cuisine que j'ai vue sur les photos avait l'air lumineuse.","Ah, sim! A cozinha que vi nas fotos parecia bem iluminada."],["Claire","Et il y a une petite pièce où je pourrais travailler tranquillement.","E tem um cômodo pequeno onde eu poderia trabalhar com tranquilidade."],["Lucas","Le balcon qui donne sur le jardin est sympa aussi. Tu l'as visité en personne ?","A varanda que dá para o jardim também é legal. Você visitou o imóvel pessoalmente?"],["Claire","Oui, hier. Mais il reste un point dont je dois parler avec l'agence : les animaux.","Sim, ontem. Mas ainda há uma questão sobre a qual preciso conversar com a imobiliária: os animais."],["Lucas","Tu devrais poser la question avant de signer le contrat. Et les charges que tu devras payer ?","Você deveria perguntar antes de assinar o contrato. E as taxas que terá que pagar?"],["Claire","Je vais tout vérifier. Je veux surtout un logement où je pourrais me sentir bien au quotidien.","Vou conferir tudo. Acima de tudo, quero um lugar onde eu poderia me sentir bem no dia a dia."]],"grammar":[{"h":"Qui: o relativo que faz o papel de sujeito","p":["O pronome relativo <b>qui</b> une duas informações e substitui o sujeito da segunda oração. Ele pode retomar uma pessoa ou uma coisa. Depois de qui, vem normalmente um verbo, pois qui já representa quem pratica a ação.","Compare duas frases: C'est une collègue. Elle habite ici. Podemos unir as informações: <b>C'est une collègue qui habite ici</b>.","Não confunda esse qui relativo com a palavra usada em perguntas, como Qui est là ? Aqui, o objetivo é descrever alguém ou algo já mencionado."],"ex":[["C'est une collègue qui travaille près d'ici.","É uma colega que trabalha aqui perto."],["J'ai trouvé un appartement qui a un balcon.","Encontrei um apartamento que tem varanda."],["Le bus qui passe ici va au centre-ville.","O ônibus que passa aqui vai para o centro."]],"tip":"Quando o relativo é o sujeito do verbo seguinte, use <b>qui</b>: la personne qui parle, le train qui arrive."},{"h":"Que e qu': o relativo que faz o papel de objeto direto","p":["O pronome relativo <b>que</b> substitui o objeto direto da segunda oração, isto é, aquilo ou aquela pessoa que recebe a ação. Depois dele, geralmente vem um sujeito explícito, como je, tu, elle ou l'agence.","Compare: J'ai vu cet appartement. Cet appartement est petit. Podemos dizer <b>L'appartement que j'ai vu est petit</b>.","Antes de vogal ou h mudo, <b>que</b> vira <b>qu'</b>. Com passé composé e avoir, quando que retoma o objeto direto que vem antes do verbo, pode haver concordância do particípio: les photos que j'ai vues."],"ex":[["Voici le logement que j'ai visité hier.","Aqui está o imóvel que visitei ontem."],["C'est une annonce qu'elle a trouvée en ligne.","É um anúncio que ela encontrou na internet."],["Les photos que nous avons prises sont nettes.","As fotos que tiramos estão nítidas."]],"tip":"<b>Qui</b> é sujeito; <b>que</b> é objeto direto. Compare la personne qui appelle e la personne que j'appelle."},{"h":"Où: lugar e momento","p":["O pronome relativo <b>où</b> retoma um lugar e significa normalmente “onde” ou “em que”. Também pode retomar uma referência de tempo, como um dia ou uma época.","Com où, você pode unir a informação sobre um lugar ou momento à descrição principal sem repetir esse lugar ou usar duas frases curtas.","Não confunda <b>où</b>, com acento grave, com <b>ou</b>, sem acento, que significa “ou” e apresenta alternativas."],"ex":[["C'est le quartier où je voudrais habiter.","É o bairro onde eu gostaria de morar."],["Voici le café où nous nous sommes rencontrés.","Este é o café onde nos conhecemos."],["Je me souviens du jour où j'ai emménagé.","Lembro do dia em que me mudei."]],"tip":"Use <b>où</b> quando a relação for de lugar ou tempo: la ville où je vis, le jour où je suis arrivé."},{"h":"Dont: quando a relação exige de","p":["O relativo <b>dont</b> substitui uma expressão introduzida por <b>de</b> na segunda oração. É frequente com verbos e expressões como <b>parler de</b>, <b>avoir besoin de</b> e <b>être fier de</b>.","Compare: Je parle de cet appartement. Cet appartement est agréable. A frase unida fica <b>L'appartement dont je parle est agréable</b>.","Dont também pode indicar posse ou relação entre duas coisas: un appartement dont les fenêtres donnent sur la cour. Em português, isso pode corresponder a “cujas janelas”."],"ex":[["C'est le document dont j'ai besoin.","É o documento de que preciso."],["Voici le projet dont nous avons parlé.","Aqui está o projeto sobre o qual conversamos."],["J'ai visité une maison dont le jardin est immense.","Visitei uma casa cujo jardim é enorme."],["C'est un résultat dont elle est fière.","É um resultado do qual ela se orgulha."]],"tip":"Pergunte qual expressão você usaria sem o relativo: parler <b>de</b> quelque chose → a coisa <b>dont</b> je parle."}],"vocab":[{"h":"Imóveis e ambientes","items":[["un appartement","um apartamento"],["un logement","um imóvel / uma moradia"],["une pièce","um cômodo"],["une cour intérieure","um pátio interno"],["un balcon","uma varanda"],["un jardin","um jardim"],["une fenêtre","uma janela"],["lumineux / lumineuse","bem iluminado / bem iluminada"]]},{"h":"Busca e aluguel","items":[["un loyer","um aluguel (valor mensal)"],["une agence immobilière","uma imobiliária"],["une annonce","um anúncio"],["un propriétaire","um proprietário"],["les charges","as taxas e despesas do imóvel"],["signer un contrat","assinar um contrato"],["visiter un logement","visitar um imóvel"],["emménager","mudar-se para uma nova casa"]]},{"h":"Como descrever e relacionar informações","items":[["qui","que (sujeito)"],["que / qu'","que (objeto direto)"],["où","onde / em que"],["dont","de que / do qual / cujo"],["donner sur","dar para / ter vista para"],["avoir l'air","parecer"],["se trouver","ficar / localizar-se"],["au quotidien","no dia a dia"]]}],"pron":[{"h":"qui e que","p":"<b>Qui</b> tem som aproximado de “ki”, com i claro. <b>Que</b> soa como “ke”, com e bem leve, e se reduz a <b>qu'</b> antes de vogal. Escute como a frase continua sem pausa depois do relativo.","w":["la personne qui parle","le livre que je lis","l'annonce qu'elle a trouvée"]},{"h":"où e ou","p":"<b>Où</b> e <b>ou</b> têm exatamente o mesmo som, aproximadamente “u”. Só a escrita e o contexto mostram a diferença: où indica lugar ou tempo; ou indica escolha.","w":["le quartier où j'habite","le jour où je suis arrivé","ici ou là"]},{"h":"dont","p":"Em <b>dont</b>, o grupo on forma uma vogal nasal, aproximadamente “dõ”. Nem o n nem o t final são pronunciados separadamente. A palavra faz a ligação de sentido com uma expressão construída com de.","w":["dont je parle","dont j'ai besoin","dont les fenêtres donnent sur la rue"]}],"mc":[{"q":"Por que Claire não quer o apartamento perto do parque?","o":["Porque não tem cozinha","Porque fica longe do trabalho","Porque o aluguel é alto demais"],"a":2,"e":"J'en ai visité un qui se trouve près du parc, mais le loyer est trop élevé."},{"q":"Quem sugeriu que Claire visitasse outro imóvel?","o":["Uma colega que mora na rua vizinha","O dono do café","Um amigo que trabalha na imobiliária"],"a":0,"e":"Une collègue qui vit dans la rue voisine m'a conseillé de visiter un autre logement."},{"q":"O que há no segundo apartamento que seria útil para Claire trabalhar?","o":["Um escritório compartilhado no prédio","Um pequeno cômodo tranquilo","Uma sala de reuniões no jardim"],"a":1,"e":"Et il y a une petite pièce où je pourrais travailler tranquillement."},{"q":"Qual questão Claire ainda precisa resolver com a imobiliária?","o":["A localização da estação","A cor das paredes","A questão dos animais"],"a":2,"e":"Oui, hier. Mais il reste un point dont je dois parler avec l'agence : les animaux."}],"gaps":[{"s":"Je connais une personne ___ travaille dans cette agence.","a":["qui"],"h":"Conheço uma pessoa que trabalha nessa imobiliária."},{"s":"L'appartement ___ j'ai visité hier est lumineux.","a":["que"],"h":"O apartamento que visitei ontem é bem iluminado."},{"s":"C'est la ville ___ je suis né.","a":["où"],"h":"É a cidade onde nasci."},{"s":"Voilà le document ___ j'ai besoin pour signer.","a":["dont"],"h":"Aqui está o documento de que preciso para assinar."},{"s":"C'est une annonce ___ elle a trouvée hier soir.","a":["qu'"],"h":"É um anúncio que ela encontrou ontem à noite."},{"s":"C'est une maison ___ le jardin donne sur une rivière.","a":["dont"],"h":"É uma casa cujo jardim dá para um rio."}],"order":[{"t":["C'est","le","quartier","où","j'habite."],"h":"É o bairro onde moro."},{"t":["Voici","le","livre","dont","je","parlais."],"h":"Aqui está o livro de que eu falava."},{"t":["La","femme","qui","travaille","ici","est","sympathique."],"h":"A mulher que trabalha aqui é simpática."}],"dict":[{"t":"Je cherche un appartement qui se trouve près du centre."},{"t":"C'est le logement que nous avons visité la semaine dernière."},{"t":"Le quartier où j'habite est calme et bien desservi."},{"t":"Voilà le document dont j'ai besoin pour la réservation."},{"t":"Les photos qu'elle a publiées ne montrent pas toutes les pièces."}],"shadow":["J'en ai visité un qui se trouve près du parc, mais le loyer est trop élevé.","Oui. Les photos que l'agence a publiées étaient très belles, mais les pièces sont petites.","Exactement. C'est celui dont je t'ai envoyé les photos hier soir.","Oui, hier. Mais il reste un point dont je dois parler avec l'agence : les animaux."],"write":{"task":"Descreva sua casa atual ou a casa em que gostaria de morar. Fale sobre o bairro, os cômodos e pelo menos uma característica importante. Escreva de cinco a sete frases e use qui, que, où e dont pelo menos uma vez cada.","ph":"J'aimerais habiter dans un quartier où … . Je cherche un logement qui …"},"cards":[["É o restaurante onde comemos ontem.","C'est le restaurant où nous avons mangé hier."],["Conheço uma pessoa que pode ajudar.","Je connais quelqu'un qui peut aider."],["Aqui está o filme de que eu te falei.","Voici le film dont je t'ai parlé."],["O livro que comprei é interessante.","Le livre que j'ai acheté est intéressant."],["É um trabalho do qual tenho orgulho.","C'est un travail dont je suis fier."],["A rua onde moro é tranquila.","La rue où j'habite est calme."],["A mulher que mora aqui é gentil.","La femme qui habite ici est gentille."],["É a informação de que precisamos.","C'est l'information dont nous avons besoin."],["O dia em que cheguei estava ensolarado.","Le jour où je suis arrivé, il faisait beau."],["A mensagem que você enviou chegou.","Le message que tu as envoyé est arrivé."]]},{"title":"Il m'a dit que...","goal":"Transmitir o que outra pessoa disse ou perguntou, relatando declarações e perguntas diretas ou indiretas, com dire que, demander si e demander ce que, e ajustando os tempos verbais em relatos no presente e no passado.","speakers":{"Claire":"f","Lucas":"m"},"setting":"No escritório, na véspera de uma reunião sobre um projeto comunitário, Claire e Lucas conferem por telefone e por e-mail as informações enviadas pela responsável por uma associação parceira.","lines":[["Claire","Lucas, tu as eu des nouvelles de la responsable pour la réunion de demain ?","Lucas, você teve notícias da responsável sobre a reunião de amanhã?"],["Lucas","Oui. Elle m'a dit qu'elle ne pouvait pas venir le matin et qu'elle préférait l'après-midi.","Sim. Ela me disse que não podia vir de manhã e que preferia a parte da tarde."],["Claire","Ah bon ? Hier, elle disait pourtant qu'elle serait libre à dix heures.","É mesmo? Mas ontem ela dizia que estaria livre às dez horas."],["Lucas","Son rendez-vous a changé. Elle a expliqué qu'elle avait reçu un appel important.","O compromisso dela mudou. Ela explicou que tinha recebido uma ligação importante."],["Claire","Et elle a proposé une autre heure ?","E ela sugeriu outro horário?"],["Lucas","Oui, elle a dit qu'elle arriverait vers quinze heures. Elle m'a demandé si cette heure nous convenait.","Sim, ela disse que chegaria por volta das quinze horas. Perguntou se esse horário era bom para nós."],["Claire","Tu lui as répondu quoi ?","O que você respondeu a ela?"],["Lucas","Je lui ai dit que j'étais disponible, mais que je devais vérifier avec toi.","Eu disse a ela que estava disponível, mas que precisava confirmar com você."],["Claire","Qu'est-ce qu'elle veut préparer exactement ?","O que exatamente ela quer preparar?"],["Lucas","Elle m'a demandé ce que nous voulions présenter pendant la réunion.","Ela me perguntou o que queríamos apresentar durante a reunião."],["Claire","Alors, dis-lui qu'on souhaite montrer le bilan du projet et discuter du budget.","Então, diga a ela que queremos mostrar o balanço do projeto e discutir o orçamento."],["Lucas","D'accord. Elle a aussi demandé si nous avions terminé le document.","Certo. Ela também perguntou se tínhamos terminado o documento."],["Claire","Nous l'avons fini hier soir. Tu peux lui dire qu'il est prêt.","Terminamos ontem à noite. Você pode dizer a ela que está pronto."],["Lucas","Elle voulait également savoir ce que nous avions prévu pour le mois prochain.","Ela também queria saber o que tínhamos planejado para o próximo mês."],["Claire","Je vais lui envoyer un résumé. Tu peux lui demander si elle préfère le recevoir aujourd'hui ?","Vou enviar um resumo a ela. Você pode perguntar se ela prefere recebê-lo hoje?"],["Lucas","Bonne idée. Je lui écris maintenant et je te transmettrai sa réponse.","Boa ideia. Vou escrever para ela agora e te encaminharei a resposta."]],"grammar":[{"h":"Discurso indireto com dire que","p":["O <b>discours indirect</b> permite contar o que alguém disse sem repetir exatamente as palavras. Para relatar uma afirmação, use <b>dire que + oração</b>. A palavra que une a fala original ao relato.","É comum mudar os pronomes pessoais e possessivos de acordo com quem conta a informação. Por exemplo, a frase direta Je suis libre pode se tornar Elle dit qu'elle est libre.","Na fala cotidiana, aparecem tanto <b>il dit que...</b>, para transmitir algo no presente, quanto <b>il a dit que...</b>, para relatar uma fala anterior."],"ex":[["Je suis disponible. → Il dit qu'il est disponible.","Estou disponível. → Ele diz que está disponível."],["Je prépare le bilan. → Elle dit qu'elle prépare le bilan.","Estou preparando o balanço. → Ela diz que está preparando o balanço."],["Je lui dis que la salle est prête.","Eu digo a ela que a sala está pronta."]],"tip":"No discurso indireto, retire as aspas da fala original e ajuste a pessoa: <b>je</b> pode virar <b>il</b> ou <b>elle</b>."},{"h":"Demander si: relatar perguntas de sim ou não","p":["Quando a pergunta original pode ser respondida por sim ou não, usamos <b>demander si</b> no discurso indireto. Si aqui significa “se”, e não introduz uma condição hipotética.","A pergunta indireta segue a ordem normal de uma afirmação, sem inversão interrogativa e sem ponto de interrogação quando faz parte de uma frase declarativa.","Ao relatar uma pergunta anterior, o tempo verbal pode mudar para combinar com o momento passado em que a pergunta foi feita."],"ex":[["Tu es libre ? → Elle demande si tu es libre.","Você está livre? → Ela pergunta se você está livre."],["Il a demandé si nous avions le temps.","Ele perguntou se tínhamos tempo."],["Je lui ai demandé si la réunion était confirmée.","Perguntei a ela se a reunião estava confirmada."]],"tip":"Se a pergunta direta aceita <b>oui</b> ou <b>non</b>, pense em <b>demander si</b>."},{"h":"Demander ce que: perguntar o que alguém faz ou quer","p":["Para transmitir uma pergunta com <b>qu'est-ce que</b> ou <b>que</b> no sentido de “o que”, podemos usar <b>demander ce que + oração</b>. A forma ce que introduz aquilo sobre o qual a pessoa perguntou.","A pergunta direta Qu'est-ce que tu prépares ? torna-se Il demande ce que tu prépares. A ordem da oração depois de ce que é a ordem normal: sujeito e verbo.","Atenção à diferença: <b>demander si</b> relata uma pergunta de sim ou não; <b>demander ce que</b> relata uma pergunta sobre o conteúdo de uma ação."],"ex":[["Qu'est-ce que tu fais ? → Elle demande ce que tu fais.","O que você está fazendo? → Ela pergunta o que você está fazendo."],["Il m'a demandé ce que je voulais présenter.","Ele me perguntou o que eu queria apresentar."],["Nous avons demandé ce qu'elle avait choisi.","Perguntamos o que ela tinha escolhido."]],"tip":"Antes de vogal, <b>ce que</b> vira <b>ce qu'</b>: elle demande ce qu'il prépare."},{"h":"Relatar no passado: mudanças de tempo e referências","p":["Quando o verbo que introduz o relato está no passado, é frequente recuar os tempos da fala original: <b>présent → imparfait</b>, <b>passé composé → plus-que-parfait</b> e <b>futur → conditionnel présent</b>. Esses tempos já foram estudados nas unidades anteriores.","Compare: Elle dit qu'elle est occupée (relato no presente) e Elle a dit qu'elle était occupée (relato de uma fala passada). Se a informação continua verdadeira no momento atual, o francês também pode manter o presente em alguns contextos.","Marcadores de tempo e lugar podem mudar com o ponto de vista do relato, por exemplo: <b>aujourd'hui → ce jour-là</b>, <b>demain → le lendemain</b> e <b>hier → la veille</b>, quando nos referimos a um momento passado diferente do atual."],"ex":[["Elle a dit qu'elle était fatiguée.","Ela disse que estava cansada."],["Il a expliqué qu'il avait perdu son billet.","Ele explicou que tinha perdido a passagem."],["Elle a annoncé qu'elle arriverait le lendemain.","Ela anunciou que chegaria no dia seguinte."],["Il a dit qu'il partirait deux jours plus tard.","Ele disse que partiria dois dias depois."]],"tip":"Em relatos no passado, confira três coisas: <b>quem fala</b>, <b>quando a ação acontece</b> e <b>qual era a referência de tempo</b> da fala original."}],"vocab":[{"h":"Comunicação e reuniões","items":[["une responsable","uma responsável / coordenadora"],["un rendez-vous","um compromisso / encontro marcado"],["une réunion","uma reunião"],["un bilan","um balanço / resumo de resultados"],["un budget","um orçamento"],["un document","um documento"],["un résumé","um resumo"],["une réponse","uma resposta"]]},{"h":"Verbos para relatar informações","items":[["dire que","dizer que"],["expliquer que","explicar que"],["annoncer que","anunciar que"],["demander si","perguntar se"],["demander ce que","perguntar o que"],["répondre","responder"],["confirmer","confirmar"],["transmettre","encaminhar / transmitir"]]},{"h":"Referências de tempo no relato","items":[["ce jour-là","naquele dia"],["la veille","na véspera"],["le lendemain","no dia seguinte"],["deux jours plus tard","dois dias depois"],["à ce moment-là","naquele momento"],["dans l'après-midi","durante a tarde"],["vers quinze heures","por volta das quinze horas"],["le mois suivant","no mês seguinte"]]}],"pron":[{"h":"dit que e demandé si","p":"Em <b>dit</b>, o t final é mudo: soa “di”. <b>Que</b> geralmente tem e leve. Em <b>demandé</b>, o é final tem som fechado, como em “dê”; <b>si</b> tem som “si”. Pratique as expressões inteiras.","w":["il dit que","elle m'a dit que","il a demandé si","elle demande si"]},{"h":"ce que e ce qu'elle","p":"Em <b>ce que</b>, as vogais são leves, aproximadamente “se ke”. Antes de vogal, o e de que desaparece na escrita e na fala: <b>ce qu'elle</b> soa aproximadamente “se kèl”.","w":["ce que tu veux","ce qu'elle prépare","ce qu'il a dit"]},{"h":"était e arriverait","p":"As terminações <b>-ait</b> e <b>-aient</b> de imparfait e conditionnel têm, no francês padrão, som de é aberto. Compare <b>elle était</b>, aproximadamente “èl é-té”, e <b>elle arriverait</b>, aproximadamente “èl a-ri-ve-ré”.","w":["elle était libre","elle arriverait demain","nous voulions","ils viendraient"]}],"mc":[{"q":"Por que a responsável não pode comparecer de manhã?","o":["Porque a equipe cancelou o projeto","Porque o compromisso dela mudou após uma ligação","Porque a reunião já aconteceu"],"a":1,"e":"Son rendez-vous a changé. Elle a expliqué qu'elle avait reçu un appel important."},{"q":"Que horário a responsável sugeriu para chegar?","o":["Por volta das quinze horas","Às dez horas","Às oito horas"],"a":0,"e":"Oui, elle a dit qu'elle arriverait vers quinze heures. Elle m'a demandé si cette heure nous convenait."},{"q":"O que a responsável perguntou sobre o documento?","o":["Se ele havia sido enviado à imprensa","Quem tinha escrito a primeira versão","Se eles tinham terminado o documento"],"a":2,"e":"D'accord. Elle a aussi demandé si nous avions terminé le document."},{"q":"O que Claire pretende enviar à responsável?","o":["Uma fatura","Um resumo","Uma lista de convidados"],"a":1,"e":"Je vais lui envoyer un résumé. Tu peux lui demander si elle préfère le recevoir aujourd'hui ?"}],"gaps":[{"s":"Elle m'a ___ (dire) qu'elle était disponible.","a":["dit"],"h":"Ela me disse que estava disponível."},{"s":"Il m'a demandé ___ je pouvais venir demain.","a":["si"],"h":"Ele me perguntou se eu podia vir amanhã."},{"s":"Elle m'a demandé ce ___ nous voulions présenter.","a":["que"],"h":"Ela me perguntou o que queríamos apresentar."},{"s":"Hier, elle a dit qu'elle ___ (être) occupée ce jour-là.","a":["était"],"h":"Ontem, ela disse que estava ocupada naquele dia."},{"s":"Il a expliqué qu'il ___ (avoir) reçu un appel la veille.","a":["avait"],"h":"Ele explicou que tinha recebido uma ligação na véspera."},{"s":"Elle a annoncé qu'elle ___ (venir) le lendemain.","a":["viendrait"],"h":"Ela anunciou que viria no dia seguinte."}],"order":[{"t":["Elle","a","dit","qu'elle","était","libre."],"h":"Ela disse que estava livre."},{"t":["Il","m'a","demandé","si","je","venais."],"h":"Ele me perguntou se eu viria."},{"t":["Elle","demande","ce","que","nous","préparons."],"h":"Ela pergunta o que estamos preparando."}],"dict":[{"t":"La responsable m'a dit qu'elle préférait l'après-midi."},{"t":"Elle m'a demandé si cette heure nous convenait."},{"t":"Il a expliqué qu'il avait reçu un appel important."},{"t":"Elle voulait savoir ce que nous avions prévu pour le mois suivant."},{"t":"Il a annoncé qu'il arriverait le lendemain vers quinze heures."}],"shadow":["Oui. Elle m'a dit qu'elle ne pouvait pas venir le matin et qu'elle préférait l'après-midi.","Oui, elle a dit qu'elle arriverait vers quinze heures. Elle m'a demandé si cette heure nous convenait.","Elle m'a demandé ce que nous voulions présenter pendant la réunion.","Elle voulait également savoir ce que nous avions prévu pour le mois prochain."],"write":{"task":"Imagine que você conversou com um colega sobre uma reunião e agora precisa transmitir as informações a outra pessoa. Escreva de cinco a sete frases relatando duas afirmações, uma pergunta de sim ou não e uma pergunta sobre o que alguém quer fazer. Use il/elle a dit que, demander si e demander ce que; inclua pelo menos uma mudança de tempo verbal.","ph":"Mon collègue m'a dit qu'il … . Il m'a demandé si …"},"cards":[["Ela disse que estava cansada.","Elle a dit qu'elle était fatiguée."],["Ele perguntou se eu tinha tempo.","Il a demandé si j'avais le temps."],["Ela quer saber o que você faz.","Elle veut savoir ce que tu fais."],["Ele disse que chegaria amanhã.","Il a dit qu'il arriverait demain."],["Ela explicou que tinha perdido a chave.","Elle a expliqué qu'elle avait perdu sa clé."],["Perguntei se a reunião estava confirmada.","J'ai demandé si la réunion était confirmée."],["Ele me perguntou o que eu queria.","Il m'a demandé ce que je voulais."],["Ela disse que tinha terminado.","Elle a dit qu'elle avait terminé."],["Eles anunciaram que partiriam no dia seguinte.","Ils ont annoncé qu'ils partiraient le lendemain."],["Diga a ela que estou disponível.","Dis-lui que je suis disponible."]]},{"title":"En travaillant","goal":"Explicar como realizar uma tarefa, descrever ações simultâneas e condições práticas com o gérondif, além de reconhecer o participe présent em avisos e textos informativos.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Numa quarta-feira, no centro comunitário do bairro, Claire e Lucas organizam uma feira de troca de livros que acontecerá no sábado.","lines":[["Claire","On a beaucoup de choses à préparer pour samedi. Tu as réussi à contacter les bénévoles ?","Temos muita coisa para preparar para sábado. Você conseguiu entrar em contato com os voluntários?"],["Lucas","Oui. En envoyant un message au groupe, j'ai trouvé six personnes disponibles pour nous aider.","Sim. Mandando uma mensagem no grupo, encontrei seis pessoas disponíveis para nos ajudar."],["Claire","Super ! Moi, j'ai gagné du temps en préparant une liste des tâches avant la réunion.","Ótimo! Eu economizei tempo preparando uma lista de tarefas antes da reunião."],["Lucas","Tu pourrais me la montrer ? Je voudrais répartir le travail en tenant compte des horaires de chacun.","Você poderia me mostrar? Quero dividir o trabalho levando em conta os horários de cada um."],["Claire","Bien sûr. En regardant ce tableau, tu verras qui peut installer les tables et accueillir les visiteurs.","Claro. Olhando esta tabela, você verá quem pode montar as mesas e receber os visitantes."],["Lucas","Et pour les livres ? On pourrait les classer par thème en collant une étiquette sur chaque carton.","E os livros? Poderíamos separá-los por tema colando uma etiqueta em cada caixa."],["Claire","Bonne idée. En faisant ça, les visiteurs trouveront plus facilement ce qu'ils cherchent.","Boa ideia. Fazendo isso, os visitantes encontrarão com mais facilidade o que procuram."],["Lucas","J'ai aussi lu l'annonce sur notre site. Il est écrit que les personnes souhaitant participer doivent apporter un livre.","Também li o anúncio no nosso site. Está escrito que as pessoas que desejam participar devem trazer um livro."],["Claire","Oui, souhaitant veut dire ici qui souhaitent. On le voit souvent dans les annonces officielles.","Sim, souhaitant quer dizer aqui que desejam. A gente vê muito isso em anúncios oficiais."],["Lucas","Tu penses qu'on attirera plus de monde en publiant quelques photos des livres sur les réseaux ?","Você acha que vamos atrair mais gente publicando algumas fotos dos livros nas redes sociais?"],["Claire","Sans doute. Et en demandant aux commerçants du quartier de partager l'annonce, on touchera d'autres habitants.","Provavelmente. E pedindo aos comerciantes do bairro que compartilhem o anúncio, vamos alcançar outros moradores."],["Lucas","D'accord. Je peux m'occuper des affiches en rentrant chez moi ce soir.","Combinado. Posso cuidar dos cartazes quando voltar para casa hoje à noite."],["Claire","Attention, en travaillant trop vite, tu risques d'oublier l'heure et l'adresse sur l'affiche.","Cuidado: trabalhando rápido demais, você corre o risco de esquecer o horário e o endereço no cartaz."],["Lucas","Tu as raison. Je vais vérifier les informations en relisant tout avant de publier.","Você tem razão. Vou conferir as informações relendo tudo antes de publicar."],["Claire","Parfait. Et on pourra discuter avec les visiteurs tout en leur proposant un café.","Perfeito. E poderemos conversar com os visitantes enquanto oferecemos um café a eles."],["Lucas","Avec une bonne organisation, on peut réussir cette journée sans se fatiguer inutilement !","Com uma boa organização, podemos fazer esse dia dar certo sem nos cansarmos à toa!"]],"grammar":[{"h":"Formação do gérondif: en + -ant","p":["O <b>gérondif</b> é formado por <b>en + participe présent</b>. Na maioria dos verbos, usamos a forma de nous no presente, retiramos -ons e acrescentamos -ant: nous parlons → en parlant; nous finissons → en finissant.","Há três formas irregulares importantes: <b>être → en étant</b>, <b>avoir → en ayant</b> e <b>savoir → en sachant</b>. O gérondif não varia em gênero ou número.","Diferentemente de um tempo verbal conjugado, o gérondif não muda conforme a pessoa. A informação sobre quem realiza a ação vem da oração principal."],"ex":[["Je progresse en pratiquant chaque jour.","Melhoro praticando todos os dias."],["Nous apprenons en faisant des erreurs.","Aprendemos cometendo erros."],["En étant patient, tu comprendras mieux.","Sendo paciente, você vai entender melhor."],["En ayant une liste, on oublie moins de choses.","Tendo uma lista, a gente esquece menos coisas."]],"tip":"Para muitos verbos, lembre da fórmula: <b>nous - ons + ant</b>, precedida de en."},{"h":"Simultaneidade: duas ações ao mesmo tempo","p":["O gérondif pode mostrar que duas ações acontecem ao mesmo tempo. Em português, frequentemente usamos o gerúndio ou a palavra “enquanto”.","As duas ações normalmente têm <b>o mesmo sujeito</b>: a pessoa que lê a mensagem é a mesma que toma notas. Se os sujeitos forem diferentes, use outra construção, como pendant que.","Podemos acrescentar <b>tout</b> antes de en para destacar ainda mais a simultaneidade: tout en parlant, tout en travaillant."],"ex":[["Elle écoute de la musique en travaillant.","Ela ouve música enquanto trabalha."],["J'ai pris des notes en écoutant la réunion.","Anotei algumas coisas enquanto ouvia a reunião."],["Il sourit tout en expliquant les règles.","Ele sorri enquanto explica as regras."]],"tip":"Se precisar dizer que <b>uma pessoa</b> falava enquanto <b>outra</b> escrevia, prefira <b>pendant que</b>."},{"h":"Maneira, meio e condição","p":["O gérondif também explica <b>como</b> alcançar um resultado: en comparant les prix significa “comparando os preços”. Pode apresentar um meio prático de fazer algo.","Dependendo do contexto, o gérondif também indica uma condição: <b>En partant tôt, tu éviteras les bouchons</b> equivale aproximadamente a “Se sair cedo, você evitará o trânsito”.","A interpretação depende do sentido da frase. Não é preciso traduzir sempre o gérondif pela mesma palavra em português."],"ex":[["On économise en achetant d'occasion.","A gente economiza comprando itens de segunda mão."],["En vérifiant les horaires, tu éviteras les erreurs.","Conferindo os horários, você evitará erros."],["Tu trouveras une solution en demandant conseil.","Você encontrará uma solução pedindo conselho."]],"tip":"Pergunte se a expressão responde a <b>como?</b> ou a <b>em que condição?</b>."},{"h":"Participe présent: reconhecer em textos","p":["O <b>participe présent</b> aparece sem en em certos textos, especialmente avisos e instruções. No B1, o objetivo principal é <b>reconhecer</b> essa forma e entender o sentido.","Em anúncios, ele pode equivaler a <b>qui + verbo</b>: les personnes souhaitant participer significa les personnes qui souhaitent participer.","Não confunda o participe présent isolado com o gérondif, que sempre traz <b>en</b> antes da forma terminada em -ant."],"ex":[["Les personnes souhaitant participer doivent s'inscrire.","As pessoas que desejam participar precisam se inscrever."],["Un message indiquant l'adresse est affiché à l'entrée.","Uma mensagem com o endereço está afixada na entrada."],["En lisant l'annonce, j'ai compris les règles.","Lendo o anúncio, entendi as regras."]],"tip":"Sem <b>en</b>, não chame automaticamente a forma de gérondif: pode ser um participe présent usado para caracterizar algo."}],"vocab":[{"h":"Organização de eventos","items":[["une foire aux livres","uma feira de livros"],["un bénévole","um voluntário"],["répartir les tâches","dividir as tarefas"],["une affiche","um cartaz"],["une étiquette","uma etiqueta"],["un carton","uma caixa de papelão"],["accueillir","receber / acolher"],["un commerçant","um comerciante"]]},{"h":"Ações úteis com en","items":[["en préparant","preparando"],["en vérifiant","conferindo"],["en comparant","comparando"],["en demandant","pedindo"],["en lisant","lendo"],["en faisant","fazendo"],["en tenant compte de","levando em conta"],["tout en parlant","enquanto fala"]]},{"h":"Comunicação e resultados","items":[["une annonce","um anúncio"],["les réseaux sociaux","as redes sociais"],["partager","compartilhar"],["attirer du monde","atrair gente"],["gagner du temps","ganhar tempo"],["risquer de","correr o risco de"],["un habitant","um morador"],["une inscription","uma inscrição"]]}],"pron":[{"h":"Terminação -ant","p":"Em <b>parlant</b> e <b>préparant</b>, o grupo -ant tem uma vogal nasal próxima de “ã”, sem pronunciar o t final. O som não é igual ao gerúndio português em -ando.","w":["en parlant","en préparant","en regardant","en travaillant"]},{"h":"en e ligação entre palavras","p":"O <b>en</b> do gérondif tem som nasal, próximo de “ã”. Antes de uma vogal, costuma haver ligação: <b>en écoutant</b> soa aproximadamente “ãn-né-cu-tã”, sem inserir uma pausa.","w":["en écoutant","en envoyant","en organisant","en ayant"]},{"h":"faisant e souhaitant","p":"Em <b>faisant</b>, a sequência fai soa como “fe”, formando aproximadamente “fe-zã”. Em <b>souhaitant</b>, ou soa como “u” e a terminação é nasal: aproximadamente “su-é-tã”.","w":["en faisant","faisant","souhaitant","les personnes souhaitant participer"]}],"mc":[{"q":"Como Lucas encontrou seis pessoas para ajudar na feira?","o":["Ligando para uma livraria","Mandando uma mensagem no grupo","Distribuindo cartazes na rua"],"a":1,"e":"Oui. En envoyant un message au groupe, j'ai trouvé six personnes disponibles pour nous aider."},{"q":"O que Claire fez para ganhar tempo antes da reunião?","o":["Preparou uma lista de tarefas","Comprou etiquetas prontas","Mudou o local da feira"],"a":0,"e":"Super ! Moi, j'ai gagné du temps en préparant une liste des tâches avant la réunion."},{"q":"O que significa souhaitant no anúncio do site?","o":["Que já participaram","Que estão organizando","Que desejam participar"],"a":2,"e":"Oui, souhaitant veut dire ici qui souhaitent. On le voit souvent dans les annonces officielles."},{"q":"O que Lucas vai fazer antes de publicar os cartazes?","o":["Pedir autorização à prefeitura","Reler e conferir as informações","Trocar a data do evento"],"a":1,"e":"Tu as raison. Je vais vérifier les informations en relisant tout avant de publier."}],"gaps":[{"s":"Je gagne du temps en ___ (préparer) une liste.","a":["préparant"],"h":"Ganho tempo preparando uma lista."},{"s":"Nous apprenons en ___ (faire) des erreurs.","a":["faisant"],"h":"Aprendemos cometendo erros."},{"s":"En ___ (lire) l'annonce, tu comprendras les règles.","a":["lisant"],"h":"Lendo o anúncio, você vai entender as regras."},{"s":"En ___ (être) attentif, tu éviteras les oublis.","a":["étant"],"h":"Prestando atenção, você evitará esquecimentos."},{"s":"Elle écoute la radio tout ___ cuisinant.","a":["en"],"h":"Ela ouve rádio enquanto cozinha."},{"s":"Les personnes ___ (souhaiter) participer doivent s'inscrire.","a":["souhaitant"],"h":"As pessoas que desejam participar precisam se inscrever."}],"order":[{"t":["J'apprends","en","pratiquant","chaque","jour."],"h":"Aprendo praticando todos os dias."},{"t":["Elle","travaille","en","écoutant","la","radio."],"h":"Ela trabalha ouvindo rádio."},{"t":["En","partant","tôt,","nous","éviterons","les","embouteillages."],"h":"Saindo cedo, evitaremos os engarrafamentos."}],"dict":[{"t":"En préparant une liste, j'ai gagné du temps."},{"t":"Nous pouvons apprendre beaucoup en travaillant ensemble."},{"t":"Elle écoute de la musique tout en faisant ses devoirs."},{"t":"En vérifiant l'adresse, tu éviteras une erreur."},{"t":"Les personnes souhaitant participer doivent apporter un livre."}],"shadow":["Oui. En envoyant un message au groupe, j'ai trouvé six personnes disponibles pour nous aider.","Bonne idée. En faisant ça, les visiteurs trouveront plus facilement ce qu'ils cherchent.","Sans doute. Et en demandant aux commerçants du quartier de partager l'annonce, on touchera d'autres habitants.","Tu as raison. Je vais vérifier les informations en relisant tout avant de publier."],"write":{"task":"Explique a um amigo como você organiza uma tarefa importante, como estudar, preparar uma viagem ou realizar um projeto. Escreva quatro a seis frases usando en + -ant para mostrar simultaneidade, maneira e condição. Inclua uma frase com tout en.","ph":"Pour bien m'organiser, je commence en … . En …, je peux …"},"cards":[["Aprendo ouvindo podcasts.","J'apprends en écoutant des podcasts."],["Economizo comprando livros usados.","J'économise en achetant des livres d'occasion."],["Você vai melhorar praticando regularmente.","Tu progresseras en pratiquant régulièrement."],["Ela trabalha enquanto ouve música.","Elle travaille tout en écoutant de la musique."],["Conferindo o endereço, você evitará erros.","En vérifiant l'adresse, tu éviteras les erreurs."],["Descobri o evento lendo o jornal.","J'ai découvert l'événement en lisant le journal."],["Podemos nos conhecer melhor conversando.","Nous pouvons mieux nous connaître en discutant."],["Ele resolveu o problema pedindo ajuda.","Il a résolu le problema en demandant de l'aide."],["Sendo paciente, você terá melhores resultados.","En étant patient, tu obtiendras de meilleurs résultats."],["As pessoas interessadas devem se inscrever.","Les personnes intéressées doivent s'inscrire."]]},{"title":"C'est fabriqué en France","goal":"Descrever como e onde produtos são feitos, reconhecer e formar a voz passiva com être e participe passé, indicar o agente com par e entender usos comuns de de.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Num domingo à tarde, Claire e Lucas visitam uma feira de design e artesanato em Lyon e conversam sobre a origem e a fabricação dos objetos expostos.","lines":[["Claire","Regarde ces sacs ! Ils sont fabriqués en France ou importés d'un autre pays ?","Olha essas bolsas! Elas são fabricadas na França ou importadas de outro país?"],["Lucas","D'après l'étiquette, ils sont fabriqués dans un atelier près de Lille, avec du tissu recyclé.","Segundo a etiqueta, elas são fabricadas em uma oficina perto de Lille, com tecido reciclado."],["Claire","J'aime bien ce modèle. Il a été dessiné par une jeune créatrice de la région, c'est ça ?","Gostei deste modelo. Ele foi desenhado por uma jovem designer da região, é isso?"],["Lucas","Oui, et toutes les pièces sont coupées à la main. Les coutures sont faites avec beaucoup de soin.","Sim, e todas as peças são cortadas à mão. As costuras são feitas com muito cuidado."],["Claire","Ça explique le prix. Mais est-ce que les matières premières sont aussi produites ici ?","Isso explica o preço. Mas as matérias-primas também são produzidas aqui?"],["Lucas","Pas toutes. Le coton vient d'ailleurs, mais il est transformé en tissu dans le nord de la France.","Nem todas. O algodão vem de outro lugar, mas é transformado em tecido no norte da França."],["Claire","Et cette lampe en bois ? Elle est exposée juste à côté des sacs, mais je ne vois pas son prix.","E esta luminária de madeira? Está exposta bem ao lado das bolsas, mas não estou vendo o preço."],["Lucas","Son prix est indiqué derrière. Elle a été conçue par un artisan local et assemblée dans son atelier.","O preço está indicado atrás. Ela foi projetada por um artesão local e montada na oficina dele."],["Claire","J'avais vu une lampe semblable dans une boutique, mais celle-ci paraît beaucoup plus solide.","Eu tinha visto uma luminária parecida em uma loja, mas esta parece muito mais resistente."],["Lucas","Les objets de cette marque sont appréciés des clients parce qu'ils peuvent être réparés facilement.","Os objetos dessa marca são apreciados pelos clientes porque podem ser consertados com facilidade."],["Claire","C'est intéressant. Et les emballages ? Ils sont jetés après l'achat ou réutilisés ?","Interessante. E as embalagens? Elas são jogadas fora depois da compra ou reutilizadas?"],["Lucas","Ils sont réutilisés quand c'est possible. L'an dernier, les emballages en plastique ont été remplacés par du carton.","Elas são reutilizadas quando possível. No ano passado, as embalagens plásticas foram substituídas por papelão."],["Claire","On dirait que cette marque fait des efforts. Son atelier est ouvert aux visiteurs ?","Parece que essa marca se esforça. A oficina deles está aberta à visitação?"],["Lucas","Oui, des visites sont organisées chaque mois. Les réservations sont faites directement sur leur site.","Sim, visitas são organizadas todo mês. As reservas são feitas diretamente pelo site deles."],["Claire","Alors, je vais regarder les dates. J'aimerais voir comment ces objets sont fabriqués.","Então vou olhar as datas. Gostaria de ver como esses objetos são fabricados."],["Lucas","Bonne idée. On comprend mieux le prix quand on découvre le travail réalisé derrière chaque objet.","Boa ideia. A gente entende melhor o preço quando descobre o trabalho realizado por trás de cada objeto."]],"grammar":[{"h":"O que é a voz passiva?","p":["Na <b>voz ativa</b>, destacamos quem faz a ação: Un artisan fabrique cette lampe. Na <b>voz passiva</b>, destacamos aquilo que recebe a ação: Cette lampe est fabriquée par un artisan.","A voz passiva é formada com <b>être + participe passé</b>. Ela é especialmente comum em informações sobre produtos, processos, notícias e descrições quando o autor da ação é menos importante.","Muitas vezes o agente nem aparece, porque é desconhecido, óbvio ou irrelevante: Ces sacs sont fabriqués en France."],"ex":[["Cette lampe est fabriquée en France.","Esta luminária é fabricada na França."],["Les articles sont vendus dans cette boutique.","Os produtos são vendidos nesta loja."],["Ce modèle est dessiné par une créatrice locale.","Este modelo é desenhado por uma designer local."],["Un artisan fabrique ces sacs.","Um artesão fabrica essas bolsas."]],"tip":"Ao transformar a frase em passiva, o objeto da frase ativa passa a ocupar a posição de sujeito."},{"h":"Concordância do participe passé","p":["Na voz passiva, o <b>participe passé concorda com o sujeito</b> em gênero e número. O padrão é parecido com um adjetivo: fabriqué, fabriquée, fabriqués, fabriquées.","O auxiliar être é conjugado de acordo com o sujeito e com o tempo da frase. No presente: est fabriqué, sont fabriquées.","Observe o sujeito antes de escolher a terminação. Com les affiches, por exemplo, usamos sont imprimées porque affiches é feminino plural."],"ex":[["Le sac est fabriqué à Lille.","A bolsa é fabricada em Lille."],["La table est fabriquée à Lyon.","A mesa é fabricada em Lyon."],["Les sacs sont fabriqués à Lille.","As bolsas são fabricadas em Lille."],["Les tables sont fabriquées à Lyon.","As mesas são fabricadas em Lyon."]],"tip":"Na voz passiva com être, confira sempre masculino ou feminino e singular ou plural do sujeito."},{"h":"Voz passiva no presente e no passado","p":["Podemos colocar <b>être</b> no tempo necessário. Para processos habituais usamos o presente: les affiches sont imprimées ici. Para acontecimentos concluídos, usamos o <b>passé composé passivo</b>: ont été imprimées.","O passado passivo é formado por <b>avoir no presente + été + participe passé</b>, porque être faz seu passé composé com avoir. O particípio principal continua concordando com o sujeito.","Também é possível usar o <b>imparfait passivo</b> para descrever um costume ou uma situação no passado, com était ou étaient + participe passé."],"ex":[["Les invitations sont envoyées par courriel.","Os convites são enviados por e-mail."],["Les invitations ont été envoyées hier.","Os convites foram enviados ontem."],["Autrefois, les sacs étaient cousus à la main.","Antigamente, as bolsas eram costuradas à mão."],["Les anciennes affiches ont été remplacées.","Os cartazes antigos foram substituídos."]],"tip":"No passado, não confunda <b>est fabriqué</b> (é fabricado) com <b>a été fabriqué</b> (foi fabricado)."},{"h":"Par e de: indicando o agente","p":["Quando queremos dizer quem realizou a ação numa frase passiva, usamos normalmente <b>par</b>: Cette lampe a été conçue par un artisan. O agente pode ser uma pessoa, um grupo ou uma organização.","Com algumas expressions que indicam <b>sentimento, opinião ou estado</b>, encontramos <b>de</b>: être apprécié de ses clients, être connu de tous. São usos frequentes, mas não devemos substituir par por de em toda frase.","Em descrições como être entouré de montagnes, de introduz aquilo que cerca algo. Nem todo de depois de um particípio representa uma pessoa que praticou uma ação."],"ex":[["Le dessin a été réalisé par une artiste.","O desenho foi feito por uma artista."],["Cette marque est appréciée de ses clients.","Essa marca é apreciada por seus clientes."],["Cette technique est connue de tous.","Essa técnica é conhecida por todos."],["Le village est entouré de forêts.","A vila é cercada por florestas."]],"tip":"Para um agente que realiza uma ação concreta, <b>par</b> é a escolha mais comum. Aprenda os casos frequentes com <b>de</b> como expressões."}],"vocab":[{"h":"Fabricação e materiais","items":[["fabriquer","fabricar"],["concevoir","projetar / conceber"],["assembler","montar"],["coudre","costurar"],["une matière première","uma matéria-prima"],["le coton","o algodão"],["le tissu recyclé","o tecido reciclado"],["une couture","uma costura"]]},{"h":"Comércio e artesanato","items":[["un artisan","um artesão"],["une créatrice","uma criadora / designer"],["un atelier","uma oficina / ateliê"],["une étiquette","uma etiqueta"],["une lampe","uma luminária"],["un emballage","uma embalagem"],["une marque","uma marca"],["une visite guidée","uma visita guiada"]]},{"h":"Formas comuns da voz passiva","items":[["est fabriqué","é fabricado"],["est fabriquée","é fabricada"],["sont vendus","são vendidos"],["sont produites","são produzidas"],["a été conçu","foi projetado"],["ont été remplacés","foram substituídos"],["par une équipe","por uma equipe"],["apprécié de tous","apreciado por todos"]]}],"pron":[{"h":"fabriqué, fabriquée e fabriqués","p":"As formas <b>fabriqué</b>, <b>fabriquée</b> e <b>fabriqués</b> normalmente têm a mesma pronúncia, aproximadamente “fa-bri-kê”. A concordância muda a escrita, não o som nessas formas.","w":["est fabriqué","est fabriquée","sont fabriqués","sont fabriquées"]},{"h":"été e étaient","p":"Em <b>été</b>, as duas vogais são fechadas, próximas de “ê-tê”. Em <b>étaient</b>, a segunda é aberta, próxima de “é” aberto. Essa diferença ajuda a distinguir estruturas do passado.","w":["a été fabriqué","ont été envoyées","étaient vendus","était exposée"]},{"h":"conçu e conçue","p":"Em <b>conçu</b> e <b>conçue</b>, a terminação u tem um som francês arredondado, próximo de “ü”. A letra ç tem som de s. As duas formas são pronunciadas da mesma maneira.","w":["un objet conçu","une lampe conçue","a été conçue"]}],"mc":[{"q":"Onde são fabricadas as bolsas da feira?","o":["Perto de Lille","Em outro continente","No centro de Paris"],"a":0,"e":"D'après l'étiquette, ils sont fabriqués dans un atelier près de Lille, avec du tissu recyclé."},{"q":"Quem projetou a luminária de madeira?","o":["Uma fábrica estrangeira","Uma equipe de estudantes","Um artesão local"],"a":2,"e":"Son prix est indiqué derrière. Elle a été conçue par un artisan local et assemblée dans son atelier."},{"q":"Por que os clientes gostam dos objetos dessa marca?","o":["Porque são os mais baratos","Porque podem ser consertados facilmente","Porque são feitos de plástico novo"],"a":1,"e":"Les objets de cette marque sont appréciés des clients parce qu'ils peuvent être réparés facilement."},{"q":"O que aconteceu com as embalagens plásticas no ano passado?","o":["Foram substituídas por papelão","Foram enviadas a outra cidade","Passaram a ser maiores"],"a":0,"e":"Ils sont réutilisés quand c'est possible. L'an dernier, les emballages en plastique ont été remplacés par du carton."}],"gaps":[{"s":"Cette table est ___ (fabriquer) en France.","a":["fabriquée"],"h":"Esta mesa é fabricada na França."},{"s":"Ces sacs sont ___ (produire) près de Lille.","a":["produits"],"h":"Essas bolsas são produzidas perto de Lille."},{"s":"La lampe a été ___ (concevoir) par un artisan.","a":["conçue"],"h":"A luminária foi projetada por um artesão."},{"s":"Les affiches ont ___ imprimées hier.","a":["été"],"h":"Os cartazes foram impressos ontem."},{"s":"Ce modèle a été dessiné ___ une créatrice locale.","a":["par"],"h":"Este modelo foi desenhado por uma designer local."},{"s":"Les emballages en plastique ont été ___ (remplacer) par du carton.","a":["remplacés"],"h":"As embalagens plásticas foram substituídas por papelão."}],"order":[{"t":["Cette","lampe","est","fabriquée","en","France."],"h":"Esta luminária é fabricada na França."},{"t":["Ces","sacs","sont","vendus","dans","notre","boutique."],"h":"Essas bolsas são vendidas na nossa loja."},{"t":["Le","modèle","a","été","dessiné","par","une","artiste."],"h":"O modelo foi desenhado por Lucas."}],"dict":[{"t":"Ces sacs sont fabriqués en France avec du tissu recyclé."},{"t":"La lampe a été conçue par un artisan local."},{"t":"Les emballages ont été remplacés l'année dernière."},{"t":"Cette marque est appréciée de ses clients."},{"t":"Des visites de l'atelier sont organisées chaque mois."}],"shadow":["D'après l'étiquette, ils sont fabriqués dans un atelier près de Lille, avec du tissu recyclé.","Oui, et toutes les pièces sont coupées à la main. Les coutures sont faites avec beaucoup de soin.","Son prix est indiqué derrière. Elle a été conçue par un artisan local et assemblée dans son atelier.","Ils sont réutilisés quand c'est possible. L'an dernier, les emballages en plastique ont été remplacés par du carton."],"write":{"task":"Escolha um objeto que você usa no dia a dia. Escreva de quatro a seis frases dizendo onde ele é fabricado, de quais materiais é feito, por quem foi projetado (se souber) e como é vendido. Use pelo menos três construções na voz passiva, incluindo uma no passado.","ph":"Cet objet est fabriqué … . Il est composé de … . Il a été …"},"cards":[["Este casaco é fabricado na França.","Ce manteau est fabriqué en France."],["As caixas são recicladas.","Les boîtes sont recyclées."],["O livro foi escrito por uma jornalista.","Le livre a été écrit par une journaliste."],["Esses móveis são feitos à mão.","Ces meubles sont faits à la main."],["A ponte foi construída há cem anos.","Le pont a été construit il y a cent ans."],["As informações são enviadas por e-mail.","Les informations sont envoyées par courriel."],["O produto foi lançado no ano passado.","Le produit a été lancé l'année dernière."],["As reservas são confirmadas automaticamente.","Les réservations sont confirmées automatiquement."],["Essa artista é conhecida por todos.","Cette artiste est connue de tous."],["O prédio é cercado por árvores.","Le bâtiment est entouré d'arbres."]]},{"title":"Je lui en ai parlé","goal":"Usar dois pronomes complementos na mesma frase para evitar repetições, aplicando a ordem de me le, le lui, lui en e y en no presente, no passé composé e com infinitivo.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Na sexta-feira à noite, em casa, Claire e Lucas organizam a ida a um festival cultural do bairro e conferem ingressos, horários e inscrições.","lines":[["Claire","Tu as vu le programme du festival ? Je te l'ai envoyé hier avec les horaires des concerts.","Você viu a programação do festival? Eu te mandei ontem com os horários dos shows."],["Lucas","Oui, tu me l'as envoyé par message. Je l'ai lu dans le bus ce matin.","Sim, você me mandou por mensagem. Li no ônibus hoje de manhã."],["Claire","Et ta sœur, elle sait qu'il y a aussi des ateliers gratuits ? Tu lui as montré le programme ?","E sua irmã, ela sabe que também tem oficinas gratuitas? Você mostrou a programação para ela?"],["Lucas","Oui, je le lui ai montré. Elle voudrait essayer l'atelier de céramique samedi.","Sim, mostrei para ela. Ela gostaria de experimentar a oficina de cerâmica no sábado."],["Claire","Tu lui as parlé des places limitées ? Les inscriptions ouvrent demain matin.","Você falou com ela sobre as vagas limitadas? As inscrições abrem amanhã de manhã."],["Lucas","Oui, je lui en ai parlé. Elle m'a demandé de lui réserver deux places si possible.","Sim, falei disso com ela. Ela me pediu para reservar duas vagas, se possível."],["Claire","J'ai déjà deux billets pour le concert de samedi soir. Tu veux que je te les garde ?","Já tenho dois ingressos para o show de sábado à noite. Quer que eu guarde para você?"],["Lucas","Oui, garde-les-moi jusqu'à demain, s'il te plaît. Je dois encore confirmer avec elle.","Sim, guarda os dois para mim até amanhã, por favor. Ainda preciso confirmar com ela."],["Claire","D'accord, je te les garde. Et l'atelier de photographie, tu t'y es inscrit ?","Combinado, guardo para você. E a oficina de fotografia, você se inscreveu nela?"],["Lucas","Oui, je m'y suis inscrit hier soir. Mais il n'y avait presque plus de places.","Sim, me inscrevi nela ontem à noite. Mas quase não havia mais vagas."],["Claire","Et pour l'atelier de cuisine ? Il y en a encore, des places, ou tout est complet ?","E para a oficina de culinária? Ainda tem vagas ou já está tudo lotado?"],["Lucas","Il y en a trois pour dimanche. J'ai vérifié sur le site il y a cinq minutes.","Ainda tem três para domingo. Conferi no site há cinco minutos."],["Claire","Super. Je vais demander les détails à l'accueil et je te les enverrai ce soir.","Ótimo. Vou pedir os detalhes na recepção e te mando hoje à noite."],["Lucas","Merci ! Tu pourrais aussi envoyer l'adresse à ma sœur ? Je ne la lui ai pas encore donnée.","Obrigado! Você também poderia mandar o endereço para minha irmã? Ainda não passei para ela."],["Claire","Bien sûr, je vais la lui envoyer avec le plan. On peut aller au festival en tramway.","Claro, vou mandar para ela junto com o mapa. Podemos ir ao festival de bonde."],["Lucas","Parfait. Avec toutes ces informations, on ne risque pas de se tromper de lieu ! On pourra profiter des concerts et des ateliers sans courir partout.","Perfeito. Com todas essas informações, não corremos o risco de ir ao lugar errado! Vamos poder curtir os shows e as oficinas sem ficar correndo de um lado para outro."]],"grammar":[{"h":"Por que usar dois pronomes?","p":["Em francês, usamos pronomes para evitar repetir pessoas e objetos já mencionados. Podemos combinar <b>um pronome para a coisa</b> e <b>outro para a pessoa</b>: Je donne le programme à Lucas → Je le lui donne.","As formas <b>le, la, les</b> substituem complementos diretos. <b>Lui</b> e <b>leur</b> substituem complementos introduzidos por à quando se referem a pessoas, em construções como donner quelque chose à quelqu'un.","Na maioria das frases afirmativas com verbo conjugado, os dois pronomes aparecem <b>antes do verbo</b>. Não basta trocar as palavras: também é preciso respeitar a ordem francesa."],"ex":[["Je donne le billet à Lucas. Je le lui donne.","Dou o ingresso a Lucas. Dou para ele."],["Nous avons envoyé les documents à nos amis. Nous les leur avons envoyés.","Enviamos os documentos aos nossos amigos. Nós os enviamos para eles."],["Tu m'envoies le lien. Tu me l'envoies.","Você me manda o link. Você o manda para mim."]],"tip":"Antes de usar dois pronomes, descubra o que cada um substitui: <b>o quê?</b> e <b>para quem?</b>"},{"h":"Ordem: me le, te la, le lui, la leur","p":["Quando aparece <b>me, te, nous ou vous</b>, esse pronome fica antes de <b>le, la ou les</b>: me le, te la, nous les, vous le. Os reflexivos se seguem à mesma posição quando combinados.","Com <b>lui</b> e <b>leur</b>, a ordem se inverte: <b>le, la, les + lui, leur</b>. Portanto, dizemos je le lui donne, e não je lui le donne.","Antes de vogal, me, te, le e la podem perder a vogal: me l'a, te l'envoie, le lui (sem elisão de le porque lui começa com consoante)."],"ex":[["Tu me le prêtes ?","Você me empresta isso?"],["Je te la rendrai demain.","Vou devolver ela para você amanhã."],["Je le lui ai montré.","Mostrei isso para ela."],["Nous les leur avons envoyés.","Nós os enviamos para eles."]],"tip":"Decore duas sequências práticas: <b>me / te / nous / vous + le / la / les</b> e <b>le / la / les + lui / leur</b>."},{"h":"Combinações com en e y","p":["O pronome <b>en</b> pode retomar um assunto introduzido por de ou uma quantidade: parler de quelque chose → en parler; acheter trois billets → en acheter trois.","O pronome <b>y</b> pode retomar um lugar ou um complemento introduzido por à quando não se trata de uma pessoa: s'inscrire à un atelier → s'y inscrire.","Combinados com outros pronomes, usamos formas muito comuns como <b>je lui en parle</b> e <b>je m'y inscris</b>. A sequência <b>y en</b> aparece especialmente em <b>il y en a</b>, usada para dizer que existe certa quantidade."],"ex":[["Je lui en ai parlé hier.","Falei disso com ela ontem."],["Je m'y suis inscrit lundi.","Eu me inscrevi nisso na segunda-feira."],["Il y en a encore trois.","Ainda restam três."],["Elle nous en a apporté deux.","Ela trouxe dois para nós."]],"tip":"Em <b>il y en a</b>, y faz parte da expressão de existência e en retoma a quantidade mencionada."},{"h":"Posição no passé composé, na negação e no infinitivo","p":["No <b>passé composé</b>, os pronomes ficam antes do auxiliar: Je le lui ai envoyé. Na negação, ne vem antes dos pronomes, e pas vem depois do auxiliar: Je ne le lui ai pas envoyé.","Quando o complemento direto le, la ou les aparece antes do auxiliar avoir, o particípio passado concorda com esse complemento: <b>Je les lui ai envoyés</b> (billets) e <b>Je la lui ai envoyée</b> (adresse).","Com dois verbos e um infinitivo, os pronomes que pertencem ao infinitivo ficam antes dele: Je vais le lui envoyer. Em ordens afirmativas, a posição muda e usamos hífens: Donne-le-moi !"],"ex":[["Je ne le lui ai pas donné.","Não dei isso para ela."],["Les billets ? Je te les ai gardés.","Os ingressos? Guardei para você."],["Je vais la lui envoyer demain.","Vou mandá-la para ela amanhã."],["Donne-le-moi, s'il te plaît !","Me dá isso, por favor!"]],"tip":"No passé composé com <b>avoir</b>, verifique se le, la ou les antecipa um complemento direto: isso pode exigir concordância do particípio."}],"vocab":[{"h":"Festival e inscrições","items":[["un programme","uma programação"],["un billet","um ingresso"],["un atelier","uma oficina"],["une inscription","uma inscrição"],["une place disponible","uma vaga disponível"],["complet / complète","lotado / lotada"],["l'accueil","a recepção"],["un plan","um mapa"]]},{"h":"Pronomes em combinações frequentes","items":[["je te le donne","eu te dou isso"],["tu me la prêtes","você me empresta isso (feminino)"],["je le lui envoie","eu mando isso para ele / ela"],["je la leur montre","eu mostro isso para eles / elas"],["je lui en parle","eu falo disso com ele / ela"],["je m'y inscris","eu me inscrevo nisso"],["il y en a","há / tem alguns"],["je te les garde","eu guardo para você"]]},{"h":"Enviar e confirmar informações","items":[["envoyer un lien","enviar um link"],["montrer un document","mostrar um documento"],["garder des billets","guardar ingressos"],["réserver une place","reservar uma vaga"],["confirmer","confirmar"],["vérifier les horaires","conferir os horários"],["se tromper de lieu","confundir o local"],["demander des détails","pedir detalhes"]]}],"pron":[{"h":"me l'a e te l'ai","p":"Quando <b>me</b> ou <b>te</b> aparece antes de le ou la seguido de vogal, ocorrem elisões. <b>Tu me l'as envoyé</b> soa aproximadamente “tü me lá ã-vua-iê”, com as palavras ligadas de forma natural.","w":["tu me l'as envoyé","je te l'ai donné","elle me l'a montré"]},{"h":"le lui e la leur","p":"Em <b>le lui</b>, as duas palavras são pronunciadas separadamente, aproximadamente “le lüi”. Em <b>la leur</b>, ouve-se aproximadamente “la lër”. Não troque a ordem ao falar rapidamente.","w":["je le lui donne","je la leur montre","je le lui ai envoyé"]},{"h":"y en e il y en a","p":"Na expressão <b>il y en a</b>, os sons se encadeiam, aproximadamente “il i ã na”. O en tem vogal nasal. Na fala informal, o il inicial pode ser reduzido, mas a forma completa é recomendada na escrita.","w":["il y en a","il y en a trois","il y en avait encore"]}],"mc":[{"q":"Como Claire enviou a programação a Lucas?","o":["Por carta","Por mensagem","Impressa em papel"],"a":1,"e":"Oui, tu me l'as envoyé par message. Je l'ai lu dans le bus ce matin."},{"q":"Que oficina a irmã de Lucas gostaria de fazer?","o":["A oficina de fotografia","A oficina de culinária","A oficina de cerâmica"],"a":2,"e":"Oui, je le lui ai montré. Elle voudrait essayer l'atelier de céramique samedi."},{"q":"Em qual oficina Lucas já se inscreveu?","o":["Na oficina de fotografia","Na oficina de culinária","Na oficina de cerâmica"],"a":0,"e":"Oui, je m'y suis inscrit hier soir. Mais il n'y avait presque plus de places."},{"q":"Quantas vagas ainda havia para a oficina de culinária no domingo?","o":["Uma","Três","Cinco"],"a":1,"e":"Il y en a trois pour dimanche. J'ai vérifié sur le site il y a cinq minutes."}],"gaps":[{"s":"Tu veux le programme ? Je te ___ donne maintenant.","a":["le"],"h":"Você quer a programação? Eu te dou agora."},{"s":"Je montre le programme à ma sœur. Je le ___ montre.","a":["lui"],"h":"Mostro a programação à minha irmã. Mostro para ela."},{"s":"Je parle de l'atelier à Lucas. Je lui ___ parle.","a":["en"],"h":"Falo da oficina com Lucas. Falo disso com ele."},{"s":"Je me suis inscrit à l'atelier. Je m'___ suis inscrit.","a":["y"],"h":"Inscrevi-me na oficina. Inscrevi-me nela."},{"s":"Il reste trois billets. Il y ___ a trois.","a":["en"],"h":"Restam três ingressos. Ainda há três."},{"s":"L'adresse ? Je la lui ai ___ (envoyer) hier.","a":["envoyée"],"h":"O endereço? Eu o enviei a ela ontem."}],"order":[{"t":["Je","le","lui","ai","montré","hier."],"h":"Mostrei isso a ela ontem."},{"t":["Tu","me","les","gardes","jusqu'à","demain?"],"h":"Você guarda eles para mim até amanhã?"},{"t":["Je","ne","la","lui","ai","pas","donnée."],"h":"Não dei isso a ela."}],"dict":[{"t":"Je te l'ai envoyé hier avec les horaires."},{"t":"Je le lui ai montré dès mon arrivée."},{"t":"Je lui en ai parlé, mais elle hésite encore."},{"t":"Je m'y suis inscrit hier soir."},{"t":"Je ne la lui ai pas encore envoyée."}],"shadow":["Oui, je le lui ai montré. Elle voudrait essayer l'atelier de céramique samedi.","Oui, je lui en ai parlé. Elle m'a demandé de lui réserver deux places si possible.","Oui, je m'y suis inscrit hier soir. Mais il n'y avait presque plus de places.","Merci ! Tu pourrais aussi envoyer l'adresse à ma sœur ? Je ne la lui ai pas encore donnée."],"write":{"task":"Imagine que você está organizando uma saída com amigos. Conte o que já mandou para cada pessoa, quais ingressos reservou, sobre quais atividades conversou e em qual oficina se inscreveu. Use pelo menos quatro combinações de pronomes, como je le lui ai envoyé, je lui en ai parlé e je m'y suis inscrit.","ph":"J'ai préparé le programme. Je l'ai envoyé à … . Je lui en ai parlé …"},"cards":[["O livro? Eu te empresto.","Le livre ? Je te le prête."],["Mostrei a foto para ela.","Je la lui ai montrée."],["Vou mandar os documentos para eles.","Je vais les leur envoyer."],["Já falei disso com ele.","Je lui en ai déjà parlé."],["Guarde os ingressos para mim.","Garde-les-moi."],["Eu os devolvo para você amanhã.","Je te les rends demain."],["Inscrevi-me nesse curso.","Je m'y suis inscrit."],["Ainda restam dois.","Il y en a encore deux."],["Não passei o endereço para ela.","Je ne la lui ai pas donnée."],["Ela trouxe três para nós.","Elle nous en a apporté trois."]]},{"title":"Parce que, donc, pourtant","goal":"Explicar motivos, apresentar consequências e contrastar ideias usando parce que, puisque, comme, donc, alors, mais, pourtant e malgré em situações reais.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Na sexta-feira, Claire e Lucas conversam por telefone sobre a mudança de planos de uma oficina de jardinagem organizada pela associação do bairro.","lines":[["Claire","Tu as vu le message de l'association ? L'atelier de jardinage en plein air est reporté à dimanche.","Você viu a mensagem da associação? A oficina de jardinagem ao ar livre foi adiada para domingo."],["Lucas","Oui, il a beaucoup plu, donc le terrain est trop humide pour travailler demain.","Sim, choveu muito, então o terreno está úmido demais para trabalharmos amanhã."],["Claire","Comme plusieurs bénévoles avaient déjà prévu de venir, je pensais qu'on garderait une activité samedi.","Como vários voluntários já tinham planejado vir, achei que manteríamos alguma atividade no sábado."],["Lucas","Le responsable préfère attendre, puisque les outils risquent de s'abîmer dans la boue.","O responsável prefere esperar, já que as ferramentas correm o risco de estragar na lama."],["Claire","Pourtant, la météo annonce du soleil pour samedi après-midi. On pourrait peut-être planter quelques fleurs.","Mesmo assim, a previsão anuncia sol para sábado à tarde. Talvez pudéssemos plantar algumas flores."],["Lucas","C'est vrai, mais le sol ne séchera pas assez vite. On pourrait préparer les graines à l'intérieur.","É verdade, mas o solo não vai secar rápido o suficiente. Poderíamos preparar as sementes em um espaço fechado."],["Claire","Bonne idée. Malgré ce changement de programme, je suis sûre qu'on peut avancer.","Boa ideia. Apesar dessa mudança de programação, tenho certeza de que podemos avançar."],["Lucas","Alors, je peux apporter des pots et de la terre. Tu pourrais prévenir les autres ?","Então posso levar vasos e terra. Você poderia avisar os outros?"],["Claire","Bien sûr. Comme tout le monde n'a pas lu le message, je vais contacter les bénévoles un par un.","Claro. Como nem todo mundo leu a mensagem, vou entrar em contato com os voluntários um por um."],["Lucas","Explique que l'atelier dehors est reporté à cause de la pluie, mais qu'on se retrouve dans la salle.","Explique que a oficina ao ar livre foi adiada por causa da chuva, mas que vamos nos encontrar na sala."],["Claire","D'accord. Puisque la salle est petite, on devrait limiter chaque groupe à dix personnes.","Certo. Já que a sala é pequena, deveríamos limitar cada grupo a dez pessoas."],["Lucas","Oui, pourtant presque vingt personnes voulaient participer samedi. Il faut trouver une solution.","Sim, no entanto quase vinte pessoas queriam participar no sábado. Precisamos encontrar uma solução."],["Claire","On peut organiser deux séances, donc personne ne sera exclu. Une le matin et une l'après-midi.","Podemos organizar duas sessões, assim ninguém ficará de fora. Uma de manhã e outra à tarde."],["Lucas","Ça me paraît juste. Malgré les difficultés, le projet avance bien depuis le printemps.","Isso me parece justo. Apesar das dificuldades, o projeto vem avançando bem desde a primavera."],["Claire","Je suis d'accord. Les habitants reviennent parce qu'ils veulent rendre le quartier plus agréable.","Concordo. Os moradores voltam porque querem tornar o bairro mais agradável."],["Lucas","Alors, on prépare les graines samedi et on plante dimanche, si le sol est assez sec.","Então preparamos as sementes no sábado e plantamos no domingo, se o solo estiver seco o suficiente."]],"grammar":[{"h":"Parce que: explicar o motivo","p":["Use <b>parce que</b> para responder a por que algo acontece. Ele introduz uma causa e é seguido de uma oração com verbo. Antes de vogal, a expressão vira <b>parce qu'</b>.","A causa pode vir depois de uma afirmação ou responder diretamente a uma pergunta com <b>pourquoi</b>. Em português, normalmente traduzimos por “porque”.","A expressão <b>à cause de</b> também apresenta uma causa, mas vem antes de um substantivo ou grupo nominal. Ela costuma aparecer para causas desfavoráveis."],"ex":[["Je reste chez moi parce qu'il pleut.","Fico em casa porque está chovendo."],["Pourquoi tu pars ? Parce que je suis fatigué.","Por que você vai embora? Porque estou cansado."],["L'atelier est reporté à cause de la pluie.","A oficina foi adiada por causa da chuva."]],"tip":"Depois de <b>parce que</b>, vem uma oração; depois de <b>à cause de</b>, geralmente vem um substantivo."},{"h":"Puisque e comme: apresentar uma causa conhecida","p":["<b>Puisque</b> significa “já que” ou “visto que”. É comum quando o motivo é conhecido, evidente ou aceito pelas pessoas que conversam.","<b>Comme</b>, com sentido de “como” ou “já que”, costuma aparecer no início da frase e apresenta primeiro o motivo para depois mostrar a consequência.","As três expressões parce que, puisque e comme podem apresentar causas, mas não dão exatamente a mesma ênfase à informação."],"ex":[["Puisque tu es libre, viens nous aider.","Já que você está livre, venha nos ajudar."],["Comme il faisait froid, nous sommes rentrés.","Como estava frio, voltamos para casa."],["Puisqu'on a le matériel, on peut commencer.","Já que temos o material, podemos começar."]],"tip":"Use <b>comme</b> no início quando quiser apresentar o motivo antes do resultado."},{"h":"Donc e alors: mostrar a consequência","p":["<b>Donc</b> e <b>alors</b> conectam uma situação à sua consequência. Dependendo do contexto, podem significar “então”, “portanto” ou “por isso”.","<b>Donc</b> costuma destacar uma conclusão lógica. <b>Alors</b> é muito frequente na fala e também pode marcar a próxima decisão ou etapa.","É possível apresentar a causa em uma frase e a consequência na frase seguinte, deixando o raciocínio fácil de acompanhar."],"ex":[["Il pleut, donc l'activité est reportée.","Está chovendo, portanto a atividade foi adiada."],["La salle est petite, alors on fera deux groupes.","A sala é pequena, então faremos dois grupos."],["J'ai terminé plus tôt, donc je peux venir.","Terminei mais cedo, por isso posso ir."]],"tip":"Pergunte: esta parte explica o motivo ou apresenta o resultado? Para o resultado, pense em <b>donc</b> ou <b>alors</b>."},{"h":"Mais, pourtant e malgré: expressar oposição","p":["<b>Mais</b> introduz uma oposição simples: “mas”. <b>Pourtant</b> significa “no entanto” ou “mesmo assim” e destaca um contraste que pode surpreender.","<b>Malgré</b> significa “apesar de” e deve ser seguido de um substantivo ou grupo nominal, não diretamente de uma oração com verbo conjugado.","Compare: <b>Il pleut, pourtant on sort</b> e <b>Malgré la pluie, on sort</b>. As duas frases apresentam uma oposição, mas com estruturas diferentes."],"ex":[["Il est fatigué, mais il veut participer.","Ele está cansado, mas quer participar."],["Il pleut. Pourtant, ils travaillent dehors.","Está chovendo. Mesmo assim, eles trabalham ao ar livre."],["Malgré le retard, nous avons terminé.","Apesar do atraso, terminamos."]],"tip":"Evite usar <b>malgré que</b> neste nível. Prefira <b>malgré + substantivo</b> ou <b>pourtant + frase</b>."}],"vocab":[{"h":"Projetos de bairro e voluntariado","items":[["une association","uma associação"],["un bénévole / une bénévole","um voluntário / uma voluntária"],["un jardin partagé","uma horta comunitária"],["un atelier de jardinage","uma oficina de jardinagem"],["des graines","sementes"],["un pot","um vaso"],["la boue","a lama"],["une séance","uma sessão / um encontro"]]},{"h":"Causa e consequência","items":[["parce que","porque"],["puisque","já que / visto que"],["comme","como / já que"],["à cause de","por causa de"],["donc","portanto / então"],["alors","então / por isso"],["c'est pourquoi","é por isso que"],["en raison de","devido a"]]},{"h":"Oposição e mudanças de plano","items":[["mais","mas"],["pourtant","no entanto / mesmo assim"],["malgré","apesar de"],["cependant","contudo / entretanto"],["reporter","adiar"],["prévenir","avisar"],["une difficulté","uma dificuldade"],["une solution","uma solução"]]}],"pron":[{"h":"parce que e puisque","p":"Em <b>parce que</b>, o e final costuma ser discreto na fala, aproximadamente “parss-ke”. <b>Puisque</b> soa aproximadamente “püisk”. Diante de vogal, escrevemos <b>parce qu'</b> e <b>puisqu'</b>.","w":["parce que","parce qu'il pleut","puisque","puisqu'on est là"]},{"h":"donc e pourtant","p":"Em <b>donc</b>, o som nasal é semelhante a “dõk”, com o c final pronunciado na fala cuidadosa. <b>Pourtant</b> soa aproximadamente “pur-tã”, com a última vogal nasal e o t final mudo.","w":["donc","donc on attend","pourtant","pourtant il vient"]},{"h":"malgré","p":"Em <b>malgré</b>, a última sílaba tem um é fechado e o r é pronunciado na garganta: aproximadamente “mal-grê”. A palavra é curta, mas não elimine o grupo gr.","w":["malgré","malgré la pluie","malgré le retard"]}],"mc":[{"q":"Por que a oficina ao ar livre foi adiada?","o":["Porque faltaram sementes","Porque a chuva deixou o terreno úmido demais","Porque ninguém se inscreveu"],"a":1,"e":"Oui, il a beaucoup plu, donc le terrain est trop humide pour travailler demain."},{"q":"Qual atividade Lucas propõe fazer em um espaço fechado?","o":["Preparar as sementes","Pintar o muro da associação","Assistir a uma palestra"],"a":0,"e":"C'est vrai, mais le sol ne séchera pas assez vite. On pourrait préparer les graines à l'intérieur."},{"q":"Por que Claire sugere limitar os grupos a dez pessoas?","o":["Porque há apenas dez vasos","Porque o encontro será à noite","Porque a sala é pequena"],"a":2,"e":"D'accord. Puisque la salle est petite, on devrait limiter chaque groupe à dix personnes."},{"q":"Como pretendem permitir a participação de quase vinte pessoas?","o":["Organizando duas sessões","Cancelando as inscrições","Transferindo todos para domingo à noite"],"a":0,"e":"On peut organiser deux séances, donc personne ne sera exclu. Une le matin et une l'après-midi."}],"gaps":[{"s":"Je reste chez moi ___ qu'il pleut.","a":["parce"],"h":"Fico em casa porque está chovendo."},{"s":"___ nous avons déjà les outils, commençons maintenant.","a":["Puisque","Comme"],"h":"Já que já temos as ferramentas, vamos começar agora."},{"s":"___ il faisait froid, nous sommes rentrés tôt.","a":["Comme","Puisque"],"h":"Como estava frio, voltamos cedo para casa."},{"s":"La salle est pleine, ___ nous organiserons une deuxième séance.","a":["donc","alors"],"h":"A sala está cheia, portanto organizaremos uma segunda sessão."},{"s":"Il pleut. ___, ils veulent travailler dehors.","a":["Pourtant","Cependant","Néanmoins","Toutefois"],"h":"Está chovendo. Mesmo assim, eles querem trabalhar ao ar livre."},{"s":"___ la pluie, les bénévoles sont venus.","a":["Malgré"],"h":"Apesar da chuva, os voluntários vieram."}],"order":[{"t":["Il","pleut,","donc","nous","restons","ici."],"h":"Está chovendo, então ficamos aqui."},{"t":["Malgré","le","retard,","nous","avançons","bien."],"h":"Apesar do atraso, estamos avançando bem."},{"t":["Puisque","tu","es","libre,","viens","demain."],"h":"Já que você está livre, venha amanhã."}],"dict":[{"t":"L'atelier est reporté parce que le terrain est humide."},{"t":"Comme il a plu, nous travaillerons à l'intérieur."},{"t":"La salle est petite, donc nous ferons deux groupes."},{"t":"Pourtant, plusieurs bénévoles veulent participer samedi."},{"t":"Malgré le changement de programme, le projet avance bien."}],"shadow":["Oui, il a beaucoup plu, donc le terrain est trop humide pour travailler demain.","Le responsable préfère attendre, puisque les outils risquent de s'abîmer dans la boue.","Bonne idée. Malgré ce changement de programme, je suis sûre qu'on peut avancer.","On peut organiser deux séances, donc personne ne sera exclu. Une le matin et une l'après-midi."],"write":{"task":"Conte uma mudança de planos que aconteceu com você, como um passeio cancelado, um atraso ou um problema no trabalho. Explique o motivo, o resultado e uma dificuldade superada. Use parce que, comme ou puisque, depois donc ou alors, e por fim pourtant ou malgré.","ph":"Comme …, j'ai dû … . Donc …, mais malgré …"},"cards":[["O encontro foi adiado por causa da chuva.","La réunion a été reportée à cause de la pluie."],["Como estou ocupado, vou responder amanhã.","Comme je suis occupé, je répondrai demain."],["Já que você está aqui, pode me ajudar.","Puisque tu es là, tu peux m'aider."],["Estava frio, por isso ficamos dentro de casa.","Il faisait froid, donc nous sommes restés à l'intérieur."],["Mesmo assim, quero tentar.","Pourtant, je veux essayer."],["Apesar do barulho, consegui estudar.","Malgré le bruit, j'ai réussi à étudier."],["Não saí porque estava cansada.","Je ne suis pas sortie parce que j'étais fatiguée."],["A loja está fechada, então voltaremos amanhã.","Le magasin est fermé, alors nous reviendrons demain."],["Ele tem experiência, mas ainda precisa aprender.","Il a de l'expérience, mais il doit encore apprendre."],["Apesar das dificuldades, não desistimos.","Malgré les difficultés, nous n'avons pas abandonné."]]},{"title":"Au travail","goal":"Participar de uma entrevista de emprego, apresentar experiências e competências e destacar informações importantes com c'est... qui e c'est... que, usando um registro profissional natural.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Na manhã de terça-feira, em uma empresa de serviços em Lyon, Lucas entrevista Claire para uma vaga de atendimento ao cliente.","lines":[["Lucas","Bonjour, Claire. Merci d'être venue. Vous postulez au poste de chargée de clientèle, c'est bien ça ?","Bom dia, Claire. Obrigado por ter vindo. Você está se candidatando à vaga de analista de atendimento ao cliente, certo?"],["Claire","Oui. C'est le contact avec les clients qui m'intéresse le plus dans ce métier.","Sim. É o contato com os clientes que mais me interessa nessa profissão."],["Lucas","Vous avez travaillé dans quel secteur jusqu'à présent ?","Em que setor você trabalhou até agora?"],["Claire","J'ai travaillé trois ans dans une librairie. C'est là que j'ai appris à gérer les demandes difficiles.","Trabalhei três anos em uma livraria. Foi lá que aprendi a lidar com solicitações difíceis."],["Lucas","Et quelles compétences pourraient être utiles dans notre équipe ?","E quais competências poderiam ser úteis na nossa equipe?"],["Claire","C'est mon sens de l'organisation que je voudrais mettre en avant, ainsi que ma capacité d'écoute.","É minha capacidade de organização que eu gostaria de destacar, assim como minha capacidade de ouvir."],["Lucas","Pouvez-vous me donner un exemple concret de votre expérience ?","Você pode me dar um exemplo concreto da sua experiência?"],["Claire","L'an dernier, nous avions beaucoup de commandes en retard. C'est moi qui ai proposé un nouveau suivi.","No ano passado, tínhamos muitos pedidos atrasados. Fui eu quem propôs um novo acompanhamento."],["Lucas","Qu'est-ce que cette solution a changé pour les clients ?","O que essa solução mudou para os clientes?"],["Claire","Les clients recevaient des réponses plus rapides, donc nous avons réduit le nombre de réclamations.","Os clientes passaram a receber respostas mais rápidas, então reduzimos o número de reclamações."],["Lucas","C'est une expérience intéressante. Comment travaillez-vous avec vos collègues ?","É uma experiência interessante. Como você trabalha com seus colegas?"],["Claire","Je partage les informations et j'aide quand c'est nécessaire. C'est le travail d'équipe qui me motive.","Compartilho informações e ajudo quando necessário. É o trabalho em equipe que me motiva."],["Lucas","Pourquoi souhaitez-vous rejoindre notre entreprise plutôt qu'une autre ?","Por que você deseja entrar na nossa empresa em vez de outra?"],["Claire","C'est votre programme de formation que j'apprécie, parce que je veux continuer à progresser.","É o programa de capacitação de vocês que valorizo, porque quero continuar me desenvolvendo."],["Lucas","Nous prévoyons une réponse d'ici vendredi. Avez-vous une question sur le poste ?","Pretendemos dar uma resposta até sexta-feira. Você tem alguma pergunta sobre a vaga?"],["Claire","Oui. Est-ce que vous pourriez me préciser les horaires et les possibilités de télétravail ?","Sim. Você poderia me esclarecer os horários e as possibilidades de trabalho remoto?"]],"grammar":[{"h":"C'est... qui: dar destaque ao sujeito","p":["A estrutura <b>c'est + informação em destaque + qui + verbo</b> permite enfatizar quem ou o que realiza uma ação. Em português, muitas vezes equivale a “é... que” ou “foi... quem”.","Depois de <b>qui</b>, o verbo concorda com a pessoa ou coisa destacada. Por exemplo: <b>C'est moi qui ai proposé</b> e <b>C'est nous qui avons décidé</b>.","Em uma entrevista, essa construção ajuda a destacar sua participação real em um projeto sem deixar a frase longa ou confusa."],"ex":[["C'est Claire qui organise les réunions.","É a Claire que organiza as reuniões."],["C'est moi qui ai proposé cette solution.","Fui eu quem propôs essa solução."],["C'est nous qui préparons les commandes.","Somos nós que preparamos os pedidos."],["C'est l'expérience qui fait la différence.","É a experiência que faz a diferença."]],"tip":"Em <b>c'est moi qui ai</b>, use <b>ai</b>, não a. O verbo concorda com moi, isto é, com je."},{"h":"C'est... que: destacar o complemento","p":["Use <b>c'est + informação em destaque + que + sujeito + verbo</b> para enfatizar o que alguém faz, escolhe, aprecia ou procura. Nesse caso, o elemento destacado não é o sujeito do verbo.","Compare: <b>C'est Lucas qui recrute</b> destaca Lucas como responsável pela ação. Já <b>C'est ce poste que je veux</b> destaca a vaga desejada.","Diante de vogal, <b>que</b> vira <b>qu'</b>. Para destacar elementos no plural, também existe a forma <b>ce sont... qui/que</b>, mais frequente em registros cuidados."],"ex":[["C'est ce poste que je recherche.","É essa vaga que estou procurando."],["C'est cette compétence que je veux développer.","É essa competência que quero desenvolver."],["C'est votre équipe que j'aimerais rejoindre.","É da equipe de vocês que eu gostaria de fazer parte."],["C'est cette entreprise qu'elle préfère.","É essa empresa que ela prefere."]],"tip":"Pergunte: estou destacando quem faz a ação? Use <b>qui</b>. Estou destacando aquilo que recebe a ação? Em geral, use <b>que</b>."},{"h":"Destacar o lugar ou momento: c'est là que e c'est... que","p":["Em francês, também podemos destacar o lugar ou o momento de uma experiência com <b>c'est... que</b>, especialmente em expressions como <b>c'est là que</b> e <b>c'est à ce moment-là que</b>.","Essas estruturas são úteis para contar como você adquiriu determinada competência. Elas permitem conectar o contexto da experiência ao que você aprendeu ou realizou.","Não confunda com <b>c'est... qui</b>, que destaca o sujeito da ação. O objetivo de ambas é dar mais ênfase a uma informação específica."],"ex":[["C'est là que j'ai appris à travailler en équipe.","Foi lá que aprendi a trabalhar em equipe."],["C'est pendant ce stage que j'ai progressé.","Foi durante esse estágio que evoluí."],["C'est à ce moment-là que j'ai changé de méthode.","Foi naquele momento que mudei de método."]],"tip":"<b>C'est là que...</b> é especialmente útil quando você conta uma experiência profissional anterior."},{"h":"Respostas profissionais: experiência, competências e cortesia","p":["Em uma entrevista formal, é comum usar <b>vous</b>, falar de experiências com o passé composé e apresentar resultados concretos. Em vez de apenas afirmar “sou organizado”, explique quando essa habilidade foi útil.","Expressões como <b>je souhaite</b> e <b>je voudrais</b> ajudam a descrever objetivos profissionais. O conditionnel présent também suaviza perguntas: <b>Pourriez-vous... ?</b>.","Para apresentar uma realização, siga uma sequência simples: contexto, ação que você tomou e resultado. Você pode usar conectores como parce que e donc, vistos na unidade anterior."],"ex":[["Je souhaite développer mes compétences.","Desejo desenvolver minhas competências."],["J'ai aidé l'équipe à réduire les retards.","Ajudei a equipe a reduzir os atrasos."],["Pourriez-vous préciser les horaires ?","Você poderia esclarecer os horários?"],["Je suis disponible à partir de lundi.","Estou disponível a partir de segunda-feira."]],"tip":"O destaque com <b>c'est... qui/que</b> funciona melhor quando evidencia algo concreto, e não quando substitui toda a sua apresentação."}],"vocab":[{"h":"Entrevista e candidatura","items":[["un entretien d'embauche","uma entrevista de emprego"],["une offre d'emploi","uma vaga de emprego"],["postuler à un poste","candidatar-se a uma vaga"],["un recruteur / une recruteuse","um recrutador / uma recrutadora"],["un candidat / une candidate","um candidato / uma candidata"],["un parcours professionnel","uma trajetória profissional"],["une expérience professionnelle","uma experiência profissional"],["être disponible","estar disponível"]]},{"h":"Competências e desempenho","items":[["une compétence","uma competência / habilidade"],["le sens de l'organisation","a capacidade de organização"],["la capacité d'écoute","a capacidade de ouvir"],["le travail d'équipe","o trabalho em equipe"],["gérer une demande","lidar com uma solicitação"],["une réclamation","uma reclamação"],["un suivi","um acompanhamento"],["mettre en avant","destacar / valorizar"]]},{"h":"Condições de trabalho e planos","items":[["un salaire","um salário"],["les horaires","os horários"],["le télétravail","o trabalho remoto"],["une formation","uma capacitação / formação"],["rejoindre une entreprise","entrar para uma empresa"],["évoluer","evoluir profissionalmente"],["une équipe","uma equipe"],["d'ici vendredi","até sexta-feira"]]}],"pron":[{"h":"c'est... qui e c'est... que","p":"Em <b>c'est</b>, a pronúncia é aproximadamente “sé”, com e aberto. <b>Qui</b> soa “ki”, enquanto <b>que</b> tem uma vogal curta e discreta, aproximadamente “kê” sem acento tônico forte.","w":["c'est moi qui","c'est Claire qui","c'est ce poste que","c'est là que"]},{"h":"entretien e embauche","p":"Em <b>entretien</b>, as vogais do início e do final são nasais, aproximadamente “ã-tre-tiã”. Em <b>embauche</b>, a primeira vogal é nasal e <b>au</b> soa como ô: aproximadamente “ã-bôsh”.","w":["un entretien","un entretien d'embauche","une embauche"]},{"h":"compétence e expérience","p":"Em <b>compétence</b>, a primeira vogal é nasal e o início soa aproximadamente “cõ-pé”. <b>Expérience</b> termina com um som nasal parecido com “iãss”. Pronuncie essas palavras devagar antes de usá-las em uma resposta longa.","w":["une compétence","mes compétences","une expérience","mon expérience professionnelle"]}],"mc":[{"q":"A qual vaga Claire está se candidatando?","o":["Gerente de livraria","Professora de francês","Profissional de atendimento ao cliente"],"a":2,"e":"Bonjour, Claire. Merci d'être venue. Vous postulez au poste de chargée de clientèle, c'est bien ça ?"},{"q":"Onde Claire adquiriu experiência com solicitações difíceis?","o":["Em uma livraria","Em uma escola","Em uma agência de viagens"],"a":0,"e":"J'ai travaillé trois ans dans une librairie. C'est là que j'ai appris à gérer les demandes difficiles."},{"q":"Qual iniciativa Claire afirma ter proposto?","o":["Um programa de férias","Um novo acompanhamento dos pedidos","Uma mudança no horário de funcionamento"],"a":1,"e":"L'an dernier, nous avions beaucoup de commandes en retard. C'est moi qui ai proposé un nouveau suivi."},{"q":"O que Claire pergunta ao final da entrevista?","o":["Quando poderá pedir demissão","Quem criou a empresa","Os horários e as possibilidades de trabalho remoto"],"a":2,"e":"Oui. Est-ce que vous pourriez me préciser les horaires et les possibilités de télétravail ?"}],"gaps":[{"s":"C'est moi ___ ai proposé la solution.","a":["qui"],"h":"Fui eu quem propôs a solução."},{"s":"C'est ce poste ___ je recherche.","a":["que"],"h":"É essa vaga que estou procurando."},{"s":"C'est ___ que j'ai appris à gérer les clients. (naquele lugar)","a":["là"],"h":"Foi lá que aprendi a lidar com os clientes."},{"s":"C'est nous qui ___ préparé les commandes. (avoir, passé composé)","a":["avons"],"h":"Fomos nós que preparamos os pedidos."},{"s":"C'est votre programme de formation ___ j'apprécie.","a":["que"],"h":"É o programa de capacitação de vocês que valorizo."},{"s":"C'est l'expérience ___ fait la différence.","a":["qui"],"h":"É a experiência que faz a diferença."}],"order":[{"t":["C'est","moi","qui","ai","proposé","cela."],"h":"Fui eu quem propôs isso."},{"t":["C'est","ce","poste","que","je","veux."],"h":"É essa vaga que eu quero."},{"t":["C'est","là","que","j'ai","appris","ce","métier."],"h":"Foi lá que aprendi essa profissão."}],"dict":[{"t":"C'est le travail d'équipe qui me motive le plus."},{"t":"C'est mon expérience que je voudrais mettre en avant."},{"t":"C'est moi qui ai proposé un nouveau suivi des commandes."},{"t":"J'ai appris à gérer les réclamations dans une librairie."},{"t":"Pourriez-vous me préciser les possibilités de télétravail ?"}],"shadow":["Oui. C'est le contact avec les clients qui m'intéresse le plus dans ce métier.","C'est mon sens de l'organisation que je voudrais mettre en avant, ainsi que ma capacité d'écoute.","L'an dernier, nous avions beaucoup de commandes en retard. C'est moi qui ai proposé un nouveau suivi.","C'est votre programme de formation que j'apprécie, parce que je veux continuer à progresser."],"write":{"task":"Imagine que você está se candidatando a uma vaga que gostaria de conseguir. Apresente uma experiência anterior, destaque duas competências com c'est... qui e c'est... que e conte um resultado concreto. Termine com uma pergunta educada ao recrutador.","ph":"Je souhaite postuler à … . C'est … qui … . C'est … que je …"},"cards":[["Estou me candidatando a esta vaga.","Je postule à ce poste."],["É minha experiência que quero destacar.","C'est mon expérience que je veux mettre en avant."],["Foi minha colega quem propôs a ideia.","C'est ma collègue qui a proposé l'idée."],["É essa equipe que eu gostaria de integrar.","C'est cette équipe que j'aimerais rejoindre."],["Foi nesse emprego que aprendi mais.","C'est dans cet emploi que j'ai le plus appris."],["Tenho três anos de experiência em atendimento.","J'ai trois anos d'expérience dans le service client."],["Gosto de trabalhar em equipe.","J'aime travailler en équipe."],["Você poderia explicar as próximas etapas?","Pourriez-vous expliquer les prochaines étapes ?"],["Tenho disponibilidade a partir de segunda-feira.","Je suis disponible à partir de lundi."],["Quero continuar desenvolvendo minhas competências.","Je veux continuer à développer mes compétences."]]},{"title":"Mon avis","goal":"Apresentar e justificar opiniões, concordar ou discordar com respeito e organizar argumentos, distinguindo je pense que com indicativo de je ne pense pas que com subjuntivo.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Durante o almoço no escritório, Claire e Lucas discutem uma proposta de semana de trabalho de quatro dias e procuram chegar a uma posição equilibrada.","lines":[["Claire","J'ai lu une proposition pour passer à la semaine de quatre jours. Tu en penses quoi ?","Li uma proposta de adotar a semana de trabalho de quatro dias. O que você acha?"],["Lucas","Personnellement, je pense que cela peut améliorer l'équilibre entre le travail et la vie privée.","Pessoalmente, acho que isso pode melhorar o equilíbrio entre o trabalho e a vida pessoal."],["Claire","Je suis plutôt d'accord, parce qu'un jour libre de plus permettrait de mieux se reposer.","Eu concordo em parte, porque um dia livre a mais permitiria descansar melhor."],["Lucas","En revanche, je ne pense pas que ce soit facile à organiser dans tous les métiers.","Por outro lado, não acho que seja fácil organizar isso em todas as profissões."],["Claire","C'est vrai, mais je crois que certaines équipes peuvent s'adapter sans trop de difficultés.","É verdade, mas acredito que algumas equipes conseguem se adaptar sem muitas dificuldades."],["Lucas","Je ne suis pas convaincu. Il faut que le service reste ouvert toute la semaine.","Não estou convencido. É preciso que o atendimento continue funcionando durante toda a semana."],["Claire","À mon avis, on pourrait organiser des horaires différents selon les équipes.","Na minha opinião, poderíamos organizar horários diferentes conforme as equipes."],["Lucas","Oui, pourtant je ne pense pas que tout le monde ait envie de travailler plus longtemps chaque jour.","Sim, mas mesmo assim não acho que todo mundo queira trabalhar mais horas por dia."],["Claire","Tu as raison sur ce point. D'un autre côté, personne ne devrait être obligé de changer ses horaires.","Você tem razão nesse ponto. Por outro lado, ninguém deveria ser obrigado a mudar seus horários."],["Lucas","Exactement. Je trouve que le choix des salariés est essentiel dans cette discussion.","Exatamente. Acho que a escolha dos funcionários é essencial nessa discussão."],["Claire","Pour moi, le plus important, c'est de garder un bon équilibre et de limiter le stress.","Para mim, o mais importante é manter um bom equilíbrio e reduzir o estresse."],["Lucas","Je comprends ton argument, mais je ne crois pas qu'une seule solution soit adaptée à toutes les entreprises.","Entendo seu argumento, mas não acredito que uma única solução seja adequada a todas as empresas."],["Claire","On pourrait commencer par un essai de trois mois et demander l'avis de chaque salarié.","Poderíamos começar com um teste de três meses e pedir a opinião de cada funcionário."],["Lucas","Voilà une proposition raisonnable. Si les résultats étaient bons, on continuerait.","Essa é uma proposta razoável. Se os resultados fossem bons, continuaríamos."],["Claire","Donc, on est d'accord pour essayer, si chacun peut participer à la décision.","Então concordamos em experimentar, desde que todos possam participar da decisão."],["Lucas","Oui, je suis pour un essai, mais il faudrait aussi vérifier la satisfaction des clients.","Sim, sou a favor de um teste, mas também seria necessário avaliar a satisfação dos clientes."]],"grammar":[{"h":"Je pense que + indicativo: afirmar uma opinião","p":["Para expressar uma opinião de maneira afirmativa, use <b>je pense que</b>, <b>je crois que</b> ou <b>je trouve que</b>. Quando apresentamos uma ideia como verdadeira ou provável, essas estruturas normalmente são seguidas do <b>indicativo</b>.","O indicativo pode aparecer no presente para opiniões sobre a situação atual. Você também pode usar outros tempos ou o conditionnel quando o conteúdo da opinião exigir.","Expressões como <b>à mon avis</b>, <b>selon moi</b> e <b>pour moi</b> ajudam a deixar claro que você está apresentando seu ponto de vista."],"ex":[["Je pense que cette idée est intéressante.","Acho que essa ideia é interessante."],["Je crois que nous avons assez de temps.","Acredito que temos tempo suficiente."],["Je trouve que ce projet fonctionne bien.","Acho que esse projeto funciona bem."],["À mon avis, il faut demander l'avis des salariés.","Na minha opinião, é preciso ouvir os funcionários."]],"tip":"Na afirmação, <b>je pense que</b> costuma vir com indicativo: <b>Je pense que c'est utile</b>."},{"h":"Je ne pense pas que + subjonctif: expressar dúvida","p":["Quando negamos uma opinião com <b>je ne pense pas que</b> ou <b>je ne crois pas que</b>, o francês geralmente usa o <b>subjonctif</b>. A frase passa a expressar dúvida ou falta de convicção.","Reaproveite os verbos do subjuntivo estudados na Unidade 4: <b>être → soit</b>, <b>avoir → ait</b>, <b>aller → aille</b> e <b>faire → fasse</b>.","Compare: <b>Je pense que c'est possible</b> (afirmação) e <b>Je ne pense pas que ce soit possible</b> (opinião negativa). Na fala informal, às vezes o ne desaparece, mas na escrita formal é melhor mantê-lo."],"ex":[["Je ne pense pas que ce soit une bonne solution.","Não acho que essa seja uma boa solução."],["Je ne crois pas qu'il ait assez de temps.","Não acredito que ele tenha tempo suficiente."],["Je ne pense pas qu'elle aille à la réunion.","Não acho que ela vá à reunião."],["Je ne crois pas que cette mesure fasse plaisir à tous.","Não acredito que essa medida agrade a todos."]],"tip":"Como regra prática do B1: <b>je pense que + indicativo</b>; <b>je ne pense pas que + subjonctif</b>."},{"h":"Concordar e discordar com respeito","p":["Para concordar, use <b>je suis d'accord</b>, <b>tout à fait</b> ou <b>tu as raison</b>. Para concordar apenas em parte, você pode dizer <b>je suis plutôt d'accord</b> ou <b>je suis d'accord sur ce point</b>.","Para discordar sem soar agressivo, comece reconhecendo o argumento: <b>Je comprends, mais...</b> ou <b>C'est vrai, cependant...</b>. Depois explique seu motivo.","<b>Je ne suis pas convaincu(e)</b> indica que você ainda tem dúvidas. Já <b>je suis pour</b> e <b>je suis contre</b> servem para dizer que você é a favor ou contra uma proposta."],"ex":[["Je suis tout à fait d'accord avec toi.","Concordo totalmente com você."],["Tu as raison sur ce point.","Você tem razão nesse ponto."],["Je comprends, mais je ne partage pas ton avis.","Entendo, mas não compartilho da sua opinião."],["Je suis pour cette proposition.","Sou a favor dessa proposta."]],"tip":"Discordar bem não é só dizer não. Reconheça um ponto e apresente um motivo para sua opinião."},{"h":"Construir um argumento: ponto de vista, razão e conclusão","p":["Uma opinião convincente costuma ter três etapas: diga o que pensa, apresente uma razão e termine com uma consequência, exemplo ou proposta.","Use <b>parce que</b> ou <b>puisque</b> para justificar. Use <b>mais</b>, <b>en revanche</b> e <b>d'un autre côté</b> para mostrar outro ponto de vista. Use <b>donc</b> para concluir.","Expressões como <b>le plus important, c'est...</b> ajudam a identificar sua prioridade. Também é útil propor um teste ou uma solução intermediária quando as pessoas discordam."],"ex":[["À mon avis, ce changement serait utile parce qu'il réduirait le stress.","Na minha opinião, essa mudança seria útil porque reduziria o estresse."],["D'un autre côté, certains salariés préfèrent leurs horaires actuels.","Por outro lado, alguns funcionários preferem seus horários atuais."],["Donc, je propose de commencer par un essai.","Por isso, proponho começar com um teste."],["Le plus important, c'est de trouver un équilibre.","O mais importante é encontrar um equilíbrio."]],"tip":"Um modelo útil para o DELF B1 é: <b>À mon avis...</b> + <b>parce que...</b> + <b>cependant...</b> + <b>donc...</b>."}],"vocab":[{"h":"Opiniões e argumentos","items":[["à mon avis","na minha opinião"],["selon moi","na minha visão"],["personnellement","pessoalmente"],["je trouve que","acho que / considero que"],["un argument","um argumento"],["un point de vue","um ponto de vista"],["être convaincu / convaincue","estar convencido / convencida"],["une proposition","uma proposta"]]},{"h":"Concordância e oposição","items":[["être d'accord","concordar"],["ne pas être d'accord","discordar"],["avoir raison","ter razão"],["être pour","ser a favor"],["être contre","ser contra"],["en revanche","em contrapartida / por outro lado"],["d'un autre côté","por outro lado"],["tout à fait","totalmente / exatamente"]]},{"h":"Organização da vida profissional","items":[["une semaine de quatre jours","uma semana de quatro dias"],["l'équilibre entre vie professionnelle et vie privée","o equilíbrio entre vida profissional e pessoal"],["un salarié / une salariée","um funcionário / uma funcionária"],["la satisfaction","a satisfação"],["une période de test","um período de teste"],["une décision collective","uma decisão coletiva"],["réduire le stress","reduzir o estresse"],["les horaires de travail","os horários de trabalho"]]}],"pron":[{"h":"à mon avis","p":"Em <b>à mon avis</b>, o n de mon se liga à vogal seguinte: a expressão soa aproximadamente “a mõ-na-vi”. O s final de avis é mudo. Evite separar mon e avis com uma pausa.","w":["à mon avis","à mon avis, c'est utile","selon moi"]},{"h":"soit e aient","p":"No subjonctif, <b>soit</b> soa aproximadamente “suá” e <b>aient</b> soa como “é”, com vogal aberta; as letras finais não se pronunciam. Essas formas aparecem em opiniões negativas.","w":["que ce soit","qu'il soit","qu'ils aient","qu'elle ait"]},{"h":"convaincu e équilibre","p":"Em <b>convaincu</b>, os dois primeiros grupos vocálicos são nasais e o u final francês não é o u português; soa aproximadamente “cõ-vẽ-kü”. Em <b>équilibre</b>, o início soa “é-ki” e o r é francês.","w":["convaincu","convaincue","un bon équilibre","je ne suis pas convaincu"]}],"mc":[{"q":"Qual proposta Claire apresenta no início da conversa?","o":["Trabalhar exclusivamente de casa","Adotar uma semana de quatro dias","Eliminar as férias escolares"],"a":1,"e":"J'ai lu une proposition pour passer à la semaine de quatre jours. Tu en penses quoi ?"},{"q":"O que Lucas pensa sobre aplicar a proposta a todas as profissões?","o":["Acha que pode ser difícil organizá-la em todas as profissões","Porque todas as equipes já trabalham quatro dias","Porque não existe interesse dos funcionários"],"a":0,"e":"En revanche, je ne pense pas que ce soit facile à organiser dans tous les métiers."},{"q":"Qual é uma preocupação de Lucas sobre a mudança?","o":["A falta de transporte público","A redução do horário de almoço","O fato de algumas pessoas não quererem trabalhar mais horas por dia"],"a":2,"e":"Oui, pourtant je ne pense pas que tout le monde ait envie de travailler plus longtemps chaque jour."},{"q":"Que solução intermediária Claire propõe?","o":["Um teste de três meses","Uma decisão sem consultar os funcionários","Cancelar o debate por tempo indeterminado"],"a":0,"e":"On pourrait commencer par un essai de trois mois et demander l'avis de chaque salarié."}],"gaps":[{"s":"Je pense que cette idée ___ (être, indicatif présent) intéressante.","a":["est"],"h":"Acho que essa ideia é interessante."},{"s":"Je ne pense pas que ce ___ (être, subjonctif présent) possible.","a":["soit"],"h":"Não acho que isso seja possível."},{"s":"Je ne crois pas qu'il ___ (avoir, subjonctif présent) raison.","a":["ait"],"h":"Não acredito que ele tenha razão."},{"s":"À mon ___, on devrait essayer.","a":["avis"],"h":"Na minha opinião, deveríamos experimentar."},{"s":"Je suis d'___ avec toi sur ce point.","a":["accord"],"h":"Concordo com você nesse ponto."},{"s":"Je ne pense pas qu'elle ___ (aller, subjonctif présent) à la réunion.","a":["aille"],"h":"Não acho que ela vá à reunião."}],"order":[{"t":["Je","pense","que","c'est","une","bonne","idée."],"h":"Acho que é uma boa ideia."},{"t":["Je","ne","pense","pas","que","ce","soit","possible."],"h":"Não acho que isso seja possível."},{"t":["À","mon","avis,","il","faut","essayer."],"h":"Na minha opinião, precisamos tentar."}],"dict":[{"t":"Je pense que ce projet peut améliorer notre quotidien."},{"t":"Je ne pense pas que cette solution soit adaptée à tous."},{"t":"À mon avis, il faut écouter les salariés."},{"t":"Je comprends ton argument, mais je ne suis pas convaincu."},{"t":"On pourrait commencer par un essai de trois mois."}],"shadow":["Personnellement, je pense que cela peut améliorer l'équilibre entre le travail et la vie privée.","En revanche, je ne pense pas que ce soit facile à organiser dans tous les métiers.","Je comprends ton argument, mais je ne crois pas qu'une seule solution soit adaptée à toutes les entreprises.","On pourrait commencer par un essai de trois mois et demander l'avis de chaque salarié."],"write":{"task":"Escreva sua opinião sobre uma mudança na rotina de trabalho ou estudos, como horários flexíveis ou aulas online. Apresente uma vantagem, uma possível dificuldade e uma solução. Use je pense que + indicativo, je ne pense pas que + subjuntivo, uma expressão para concordar ou discordar e conectores de argumentação.","ph":"À mon avis, … . Je pense que … parce que … . Cependant, je ne pense pas que …"},"cards":[["Na minha opinião, essa ideia é útil.","À mon avis, cette idée est utile."],["Acho que podemos encontrar uma solução.","Je pense que nous pouvons trouver une solução."],["Não acho que isso seja necessário.","Je ne pense pas que ce soit nécessaire."],["Não acredito que ele tenha tempo suficiente.","Je ne crois pas qu'il ait assez de temps."],["Concordo com você nesse ponto.","Je suis d'accord avec toi sur ce point."],["Entendo sua opinião, mas discordo.","Je comprends ton avis, mais je ne suis pas d'accord."],["Por outro lado, precisamos pensar nos custos.","D'un autre côté, nous devons penser aux coûts."],["Sou a favor de um período de teste.","Je suis pour uma période de test."],["O mais importante é ouvir a equipe.","Le plus important, c'est d'écouter l'équipe."],["Por isso, proponho discutir antes de decidir.","Donc, je propose d'en discuter avant de décider."]]},{"title":"Il était une fois","goal":"Contar acontecimentos passados alternando passé composé, imparfait e plus-que-parfait e reconhecer o passé simple.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Em Lyon, Claire conta a Lucas como reencontrou uma livraria onde trabalhava.","lines":[["Lucas","Tu as l'air de bonne humeur ce matin. Il s'est passé quelque chose de spécial pendant ton week-end ?","Você parece bem-humorada hoje. Aconteceu algo especial no seu fim de semana?"],["Claire","Samedi, je suis retournée par hasard dans une librairie où je travaillais quand j'étais étudiante. Je n'y avais pas mis les pieds depuis dix ans.","No sábado, voltei por acaso a uma livraria onde trabalhava quando era estudante. Eu não pisava lá havia dez anos."],["Lucas","Elle existe encore ? Je croyais que presque toutes les petites librairies du quartier avaient fermé.","Ela ainda existe? Achava que quase todas as pequenas livrarias tinham fechado."],["Claire","Celle-ci a résisté. À l'époque, j'y passais mes après-midi et le propriétaire me recommandait toujours des romans que je n'aurais jamais choisis seule.","Essa resistiu. Na época, eu passava as tardes lá e o dono sempre recomendava romances que eu nunca teria escolhido sozinha."],["Lucas","Et qu'est-ce qui t'a poussée à entrer après toutes ces années ? Tu cherchais un livre en particulier ?","O que fez você entrar depois de tantos anos? Estava procurando algum livro específico?"],["Claire","Pas du tout. Il pleuvait à verse, j'avais oublié mon parapluie et j'ai aperçu la vitrine en traversant la rue.","Nada disso. Chovia muito, eu tinha esquecido meu guarda-chuva e vi a vitrine ao atravessar a rua."],["Lucas","Le propriétaire était là ? Ça devait lui faire drôle de te revoir après si longtemps.","O dono estava lá? Deve ter sido estranho para ele rever você depois de tanto tempo."],["Claire","Oui. Il avait déjà fermé la caisse, mais il rangeait encore des livres qu'il avait reçus la veille. Au début, il ne m'a pas reconnue.","Sim. Já tinha fechado o caixa, mas ainda arrumava livros recebidos na véspera. No começo não me reconheceu."],["Lucas","Je comprends. Vous aviez sûrement tous les deux beaucoup changé. Comment as-tu réussi à lui rafraîchir la mémoire ?","Imagino. Vocês tinham mudado bastante. Como você refrescou a memória dele?"],["Claire","Je lui ai rappelé les lectures du jeudi qu'on organisait autrefois. Dès que j'ai parlé du vieux fauteuil rouge, il a éclaté de rire.","Lembrei das leituras de quinta-feira que organizávamos. Ao mencionar a velha poltrona vermelha, ele caiu na risada."],["Lucas","C'est incroyable qu'il se souvienne encore de ce détail. Il t'a raconté ce qui s'était passé depuis ton départ ?","Incrível que ele ainda se lembre disso. Contou o que aconteceu desde sua saída?"],["Claire","Mieux que ça : il a sorti un cahier que j'avais laissé derrière moi. Je pensais l'avoir perdu pendant mon déménagement.","Melhor: pegou um caderno que eu tinha deixado lá. Eu achava que o perdera na mudança."],["Lucas","Un cahier de cours ? Ou bien tu écrivais déjà des histoires à cette époque ?","Um caderno de aula? Ou você já escrevia histórias?"],["Claire","J'y avais dessiné un projet de club de lecture pour les habitants du quartier. J'étais persuadée que personne ne lirait ces notes.","Eu tinha esboçado um clube de leitura para moradores. Achava que ninguém leria as anotações."],["Lucas","Ne me dis pas qu'il s'en est inspiré ! Ce serait une sacrée coïncidence, après tout ce temps.","Não me diga que ele se inspirou nisso! Seria uma coincidência e tanto."],["Claire","Si ! Il avait lancé un club l'année suivante. Quand je suis sortie, la pluie s'était arrêtée et j'ai décidé de participer à leur prochaine rencontre.","Sim! Ele tinha criado um clube no ano seguinte. Quando saí, a chuva tinha parado e decidi participar do próximo encontro."]],"grammar":[{"h":"Passé composé: acontecimentos concluídos","p":["O <b>passé composé</b> indica acontecimentos completos que fazem o relato avançar e frequentemente se combina com marcadores de sequência temporal."],"ex":[["Samedi, je suis retournée dans mon ancienne librairie.","No sábado, voltei à minha antiga livraria."],["J'ai aperçu la vitrine et je suis entrée.","Vi a vitrine e entrei."],["Le libraire a sorti un vieux cahier.","O livreiro tirou um caderno antigo."]],"tip":"Identifique cada ação pontual que move a história."},{"h":"Imparfait: cenário e hábitos","p":["O <b>imparfait</b> descreve situações em curso, estados e hábitos, enquanto o passé composé apresenta o evento que ocorre nesse cenário."],"ex":[["Il pleuvait quand j'ai traversé la rue.","Chovia quando atravessei a rua."],["À l'époque, je travaillais tous les samedis.","Na época, trabalhava aos sábados."],["Il rangeait les livres quand je suis arrivée.","Arrumava os livros quando cheguei."]],"tip":"Pense em uma fotografia do passado."},{"h":"Plus-que-parfait: anterioridade","p":["Forme o plus-que-parfait com avoir ou être no imparfait mais o particípio passado: <b>j'avais oublié</b>, <b>elle était partie</b>."],"ex":[["J'avais oublié mon parapluie.","Eu tinha esquecido meu guarda-chuva."],["Il avait fermé la caisse avant mon arrivée.","Ele tinha fechado o caixa antes de eu chegar."],["Elle était partie depuis une heure.","Ela tinha saído havia uma hora."]],"tip":"Relacione dois momentos do passado."},{"h":"Passé simple na escrita","p":["O <b>passé simple</b> aparece principalmente em romances e narrativas históricas e substitui o passé composé no primeiro plano narrativo."],"ex":[["Elle entra et découvrit une lettre.","Ela entrou e descobriu uma carta."],["Il vit le cahier et sourit.","Ele viu o caderno e sorriu."],["Elle comprit enfin la vérité.","Ela finalmente entendeu a verdade."]],"tip":"Reconheça esse tempo, sem tentar usá-lo na conversa."}],"vocab":[{"h":"Livraria e lembranças","items":[["une librairie","uma livraria"],["un libraire","um livreiro"],["une vitrine","uma vitrine"],["un cahier","um caderno"],["un roman","um romance"],["un fauteuil","uma poltrona"],["un déménagement","uma mudança de casa"],["un club de lecture","um clube de leitura"]]},{"h":"Relatos e marcadores temporais","items":[["par hasard","por acaso"],["autrefois","antigamente"],["à l'époque","na época"],["la veille","na véspera"],["apercevoir","avistar"],["se souvenir de","lembrar-se de"],["rafraîchir la mémoire","refrescar a memória"],["éclater de rire","cair na risada"]]}],"pron":[{"h":"plus-que-parfait","p":"Em plus-que-parfait, o s de plus é mudo; a pronúncia aproximada é “plü-ke-par-fé”.","w":["plus-que-parfait","j'avais oublié","il avait reçu"]},{"h":"avais e avait","p":"As duas formas têm pronúncia igual em francês padrão, aproximadamente “avè”, com som e aberto.","w":["j'avais","il avait","elle avait fermé"]}],"mc":[{"q":"Há quanto tempo Claire não visitava a livraria?","o":["Desde a semana anterior","Havia dez anos","Havia dois meses"],"a":1,"e":"Samedi, je suis retournée par hasard dans une librairie où je travaillais quand j'étais étudiante. Je n'y avais pas mis les pieds depuis dix ans."},{"q":"Por que Claire entrou na livraria naquele sábado?","o":["Porque viu um anúncio de emprego","Porque precisava de um romance","Porque chovia e ela estava sem guarda-chuva"],"a":2,"e":"Pas du tout. Il pleuvait à verse, j'avais oublié mon parapluie et j'ai aperçu la vitrine en traversant la rue."},{"q":"O que o livreiro encontrou e mostrou a Claire?","o":["Um caderno que ela tinha deixado lá","Uma fotografia de família","Uma carta que chegou naquela manhã"],"a":0,"e":"Mieux que ça : il a sorti un cahier que j'avais laissé derrière moi. Je pensais l'avoir perdu pendant mon déménagement."},{"q":"O que Claire decidiu fazer ao final da visita?","o":["Trabalhar novamente na livraria","Participar de um encontro do clube","Organizar uma mudança"],"a":1,"e":"Si ! Il avait lancé un club l'année suivante. Quand je suis sortie, la pluie s'était arrêtée et j'ai décidé de participer à leur prochaine rencontre."}],"gaps":[{"s":"Hier, je ___ (retrouver, passé composé) mon ancien cahier.","a":["ai retrouvé"],"h":"Ontem encontrei meu caderno antigo."},{"s":"Quand j'étais étudiante, je ___ (lire, imparfait) dans ce café.","a":["lisais"],"h":"Quando era estudante, lia naquele café."},{"s":"Le libraire l'___ (fermer, plus-que-parfait) avant mon arrivée.","a":["avait fermée"],"h":"O livreiro já a tinha fechado antes de eu chegar."},{"s":"Il ___ (pleuvoir, imparfait) quand je suis entrée.","a":["pleuvait"],"h":"Chovia quando entrei."},{"s":"Elle ___ (partir, plus-que-parfait) avant le début.","a":["était partie"],"h":"Ela tinha saído antes do início."},{"s":"Soudain, le propriétaire ___ (reconnaître, passé composé) ma voix.","a":["a reconnu"],"h":"De repente, o dono reconheceu minha voz."}],"order":[{"t":["J'y","suis","retournée","par","hasard."],"h":"Voltei lá por acaso."},{"t":["J'avais","déjà","perdu","ce","cahier."],"h":"Eu já tinha perdido aquele caderno."},{"t":["Je","lui","ai","rappelé","une","vieille","histoire."],"h":"Lembrei a ele de uma história antiga."}],"dict":[{"t":"Samedi, je suis retournée par hasard dans une librairie où je travaillais quand j'étais étudiante. Je n'y avais pas mis les pieds depuis dix ans."},{"t":"Et qu'est-ce qui t'a poussée à entrer après toutes ces années ? Tu cherchais un livre en particulier ?"},{"t":"Oui. Il avait déjà fermé la caisse, mais il rangeait encore des livres qu'il avait reçus la veille. Au début, il ne m'a pas reconnue."},{"t":"C'est incroyable qu'il se souvienne encore de ce détail. Il t'a raconté ce qui s'était passé depuis ton départ ?"},{"t":"Ne me dis pas qu'il s'en est inspiré ! Ce serait une sacrée coïncidence, après tout ce temps."}],"shadow":["Samedi, je suis retournée par hasard dans une librairie où je travaillais quand j'étais étudiante. Je n'y avais pas mis les pieds depuis dix ans.","Pas du tout. Il pleuvait à verse, j'avais oublié mon parapluie et j'ai aperçu la vitrine en traversant la rue.","C'est incroyable qu'il se souvienne encore de ce détail. Il t'a raconté ce qui s'était passé depuis ton départ ?","Si ! Il avait lancé un club l'année suivante. Quand je suis sortie, la pluie s'était arrêtée et j'ai décidé de participer à leur prochaine rencontre."],"write":{"task":"Conte uma lembrança de uma visita inesperada em cinco a sete frases com passé composé, imparfait e plus-que-parfait.","ph":"L'autre jour, je suis retourné(e) … . Il faisait …"},"cards":[["Voltei lá por acaso.","J'y suis retournée par hasard."],["Fazia tempo que eu não entrava ali.","Cela faisait longtemps que je n'y étais pas entrée."],["Na época, eu morava perto.","À l'époque, j'habitais tout près."],["Chovia quando cheguei.","Il pleuvait quand je suis arrivée."],["Eu já tinha perdido aquele caderno.","J'avais déjà perdu ce cahier."],["Ele não me reconheceu imediatamente.","Il ne m'a pas reconnue tout de suite."],["Nós nos encontrávamos toda quinta-feira.","Nous nous retrouvions tous les jeudis."],["Ela tinha saído um pouco antes.","Elle était partie un peu plus tôt."],["Lembrei a ele de uma história antiga.","Je lui ai rappelé une vieille histoire."],["Aquela visita me fez mudar de ideia.","Cette visite m'a fait changer d'avis."]]},{"title":"Quand j'aurai fini...","goal":"Planejar prazos e projetos usando futur antérieur para fatos concluídos antes de uma etapa futura e para suposições sobre o passado.","speakers":{"Inès":"f","Antoine":"m"},"setting":"Inès e Antoine organizam o lançamento de um site para um festival.","lines":[["Inès","On a enfin fixé la mise en ligne du site du festival à vendredi, dix-huit heures. Tu penses qu'on tiendra le délai ?","Marcamos a publicação do site para sexta, às dezoito horas. Você acha que cumpriremos o prazo?"],["Antoine","Oui, mais il faut garder une marge pour les imprévus. Quand j'aurai intégré les dernières images, je lancerai les tests sur mobile.","Sim, mas precisamos de uma margem para imprevistos. Quando inserir as imagens, começarei os testes no celular."],["Inès","Parfait. Dès que j'aurai reçu les textes définitifs des organisateurs, je te transmettrai la version corrigée.","Ótimo. Assim que receber os textos definitivos, vou enviar a versão corrigida."],["Antoine","Tu sais quand ils nous répondront ? Sans leurs descriptions, je ne peux pas terminer les pages des artistes.","Sabe quando responderão? Sem as descrições, não consigo terminar as páginas dos artistas."],["Inès","Ils m'ont promis une réponse demain matin. D'ici mercredi soir, nous aurons normalement validé tout le contenu.","Prometeram responder amanhã de manhã. Até quarta à noite, teremos aprovado o conteúdo."],["Antoine","De mon côté, j'aurai terminé la version mobile avant la réunion de jeudi. Il restera seulement à vérifier les liens et les formulaires.","Terei terminado a versão móvel antes da reunião de quinta. Restará conferir links e formulários."],["Inès","Et l'accessibilité ? On doit s'assurer que les images auront des descriptions et que les contrastes seront suffisants.","E a acessibilidade? Precisamos garantir descrições nas imagens e contraste suficiente."],["Antoine","J'y travaille. Une fois que j'aurai ajouté les textes alternatifs, Claire pourra contrôler chaque page avec son lecteur d'écran.","Estou cuidando disso. Quando acrescentar os textos alternativos, Claire poderá conferir cada página com o leitor de tela."],["Inès","Très bien. Quand elle aura terminé ses vérifications, demande-lui de nous envoyer une liste précise des problèmes.","Muito bem. Quando terminar as verificações, peça uma lista precisa de problemas."],["Antoine","C'est prévu. Dès que nous aurons corrigé les derniers défauts, je préparerai une sauvegarde complète du site.","Já está previsto. Assim que corrigirmos as falhas, farei um backup completo."],["Inès","N'attends pas vendredi pour la sauvegarde. Si un souci technique survient, il faudra pouvoir revenir à la version précédente.","Não espere até sexta para o backup. Se houver problemas técnicos, precisaremos voltar à versão anterior."],["Antoine","Tu as raison. Je ferai aussi une copie jeudi. Quand le site sera en ligne, on surveillera les messages des visiteurs.","Você tem razão. Farei uma cópia na quinta. Quando estiver no ar, acompanharemos as mensagens dos visitantes."],["Inès","Au fait, le partenaire principal n'a toujours pas envoyé son logo. Tu crois qu'il a changé d'avis ?","Aliás, o patrocinador ainda não enviou o logo. Acha que mudou de ideia?"],["Antoine","Il aura simplement oublié notre dernier message. Je peux le relancer aujourd'hui, sans lui mettre trop de pression.","Provavelmente só esqueceu nossa mensagem. Posso cobrar uma resposta hoje, sem pressionar demais."],["Inès","Bonne idée. Et une fois que tout aura été vérifié, on pourra annoncer officiellement le lancement sur nos réseaux.","Boa ideia. Quando tudo tiver sido conferido, poderemos anunciar o lançamento nas redes."],["Antoine","Entendu. D'ici jeudi soir, nous aurons bouclé l'essentiel. Vendredi, on se concentrera sur les derniers détails, pas sur les urgences.","Combinado. Até quinta, concluiremos o essencial. Na sexta, cuidaremos dos detalhes, não das urgências."]],"grammar":[{"h":"Formation du futur antérieur","p":["Forme com <b>avoir</b> ou <b>être</b> no futur simple mais o particípio passado. O auxiliar determina a concordância habitual."],"ex":[["J'aurai terminé le dossier avant jeudi.","Terei terminado o relatório antes de quinta."],["Nous aurons reçu les textes demain.","Teremos recebido os textos amanhã."],["Inès sera arrivée avant la réunion.","Inès terá chegado antes da reunião."]],"tip":"O futuro está no auxiliar: aurai, auras, aura, aurons, aurez, auront."},{"h":"Quand, dès que, une fois que","p":["O futur antérieur indica uma etapa concluída antes de outra ação futura, geralmente com futur simple na oração seguinte."],"ex":[["Quand j'aurai fini, je t'appellerai.","Quando eu terminar, ligarei."],["Dès qu'elle aura répondu, nous déciderons.","Assim que ela responder, decidiremos."],["Une fois que vous aurez relu, on publiera.","Depois que vocês revisarem, publicaremos."]],"tip":"Essas expressões pedem futuro em francês quando se referem ao futuro."},{"h":"D'ici e antes de um prazo","p":["O futur antérieur apresenta resultados concluídos até um momento determinado; para indicar apenas um estado futuro, use futur simple."],"ex":[["D'ici vendredi, nous aurons tout validé.","Até sexta, teremos aprovado tudo."],["Elle aura préparé la sauvegarde.","Ela terá preparado o backup."],["Le site sera en ligne vendredi.","O site estará no ar na sexta."]],"tip":"D'ici marca um limite de tempo."},{"h":"Suposição sobre o passado","p":["O futur antérieur também expressa uma hipótese plausível sobre um fato passado sem afirmar certeza."],"ex":[["Il aura oublié notre message.","Ele provavelmente esqueceu nossa mensagem."],["Ils auront rencontré un problème.","Eles devem ter encontrado um problema."],["Elle aura pris le mauvais train.","Ela deve ter pegado o trem errado."]],"tip":"O contexto diferencia prazo de suposição."}],"vocab":[{"h":"Projetos e prazos","items":[["une mise en ligne","uma publicação online"],["un délai","um prazo"],["un imprévu","um imprevisto"],["une marge","uma margem"],["une version définitive","uma versão definitiva"],["valider","aprovar"],["boucler un projet","concluir um projeto"],["une sauvegarde","um backup"]]},{"h":"Desenvolvimento e comunicação","items":[["un lien","um link"],["un formulaire","um formulário"],["un texte alternatif","um texto alternativo"],["un lecteur d'écran","um leitor de tela"],["un défaut","uma falha"],["corriger","corrigir"],["relancer quelqu'un","cobrar uma resposta"],["tenir le délai","cumprir o prazo"]]}],"pron":[{"h":"j'aurai e j'aurais","p":"O final de j'aurai pode ter e mais fechado; j'aurais pode ter e aberto. Na fala, a diferença muitas vezes desaparece: “jorê”.","w":["j'aurai fini","j'aurais fini","nous aurons fini"]},{"h":"vous aurez","p":"A ligação de vous aurez produz som z, aproximadamente “vu-zo-rê”.","w":["vous aurez reçu","nous aurons fini","ils auront répondu"]}],"mc":[{"q":"Para quando está prevista a publicação do site?","o":["Para quinta-feira de manhã","Para sábado ao meio-dia","Para sexta-feira às dezoito horas"],"a":2,"e":"On a enfin fixé la mise en ligne du site du festival à vendredi, dix-huit heures. Tu penses qu'on tiendra le délai ?"},{"q":"O que Antoine fará depois de incluir as últimas imagens?","o":["Iniciará os testes no celular","Mandará um contrato","Publicará o site imediatamente"],"a":0,"e":"Oui, mais il faut garder une marge pour les imprévus. Quand j'aurai intégré les dernières images, je lancerai les tests sur mobile."},{"q":"Quem verificará a acessibilidade com um leitor de tela?","o":["O patrocinador principal","Claire","Os organizadores do festival"],"a":1,"e":"J'y travaille. Une fois que j'aurai ajouté les textes alternatifs, Claire pourra contrôler chaque page avec son lecteur d'écran."},{"q":"Por que Antoine acha que o logotipo não chegou?","o":["O patrocinador cancelou","O arquivo foi apagado","O patrocinador esqueceu a mensagem"],"a":2,"e":"Il aura simplement oublié notre dernier message. Je peux le relancer aujourd'hui, sans lui mettre trop de pression."}],"gaps":[{"s":"Quand tu ___ (finir, futur antérieur) les tests, tu m'enverras le rapport.","a":["auras fini"],"h":"Quando terminar os testes, enviará o relatório."},{"s":"D'ici jeudi, nous ___ (valider, futur antérieur) tout le contenu.","a":["aurons validé"],"h":"Até quinta teremos aprovado tudo."},{"s":"Une fois que vous ___ (recevoir, futur antérieur) le dossier, appelez-moi.","a":["aurez reçu"],"h":"Depois que receberem o documento, liguem."},{"s":"Quand Inès ___ (arriver, futur antérieur), nous commencerons.","a":["sera arrivée"],"h":"Quando Inès chegar, começaremos."},{"s":"Dès que nous aurons corrigé les erreurs, nous ___ (publier, futur simple) le site.","a":["publierons"],"h":"Assim que corrigirmos os erros, publicaremos o site."},{"s":"Il ne répond pas ; il ___ (oublier, futur antérieur) notre rendez-vous.","a":["aura oublié"],"h":"Ele não responde; provavelmente esqueceu nosso encontro."}],"order":[{"t":["Quand","j'aurai","fini,","je","te","préviendrai."],"h":"Quando eu terminar, aviso você."},{"t":["Une","fois","que","tu","auras","vérifié,","nous","publierons."],"h":"Depois que você conferir, publicaremos."},{"t":["Je","relancerai","mon","contact","aujourd'hui","même."],"h":"Vou cobrar uma resposta ainda hoje."}],"dict":[{"t":"Oui, mais il faut garder une marge pour les imprévus. Quand j'aurai intégré les dernières images, je lancerai les tests sur mobile."},{"t":"Ils m'ont promis une réponse demain matin. D'ici mercredi soir, nous aurons normalement validé tout le contenu."},{"t":"J'y travaille. Une fois que j'aurai ajouté les textes alternatifs, Claire pourra contrôler chaque page avec son lecteur d'écran."},{"t":"N'attends pas vendredi pour la sauvegarde. Si un souci technique survient, il faudra pouvoir revenir à la version précédente."},{"t":"Bonne idée. Et une fois que tout aura été vérifié, on pourra annoncer officiellement le lancement sur nos réseaux."}],"shadow":["Oui, mais il faut garder une marge pour les imprévus. Quand j'aurai intégré les dernières images, je lancerai les tests sur mobile.","De mon côté, j'aurai terminé la version mobile avant la réunion de jeudi. Il restera seulement à vérifier les liens et les formulaires.","N'attends pas vendredi pour la sauvegarde. Si un souci technique survient, il faudra pouvoir revenir à la version précédente.","Entendu. D'ici jeudi soir, nous aurons bouclé l'essentiel. Vendredi, on se concentrera sur les derniers détails, pas sur les urgences."],"write":{"task":"Planeje um projeto pessoal e escreva seis frases indicando resultados alcançados até uma data e próximas etapas.","ph":"D'ici la fin du mois, j'aurai … . Dès que j'aurai …"},"cards":[["Quando eu terminar, aviso você.","Quand j'aurai fini, je te préviendrai."],["Teremos terminado até quinta-feira.","Nous aurons terminé d'ici jeudi."],["Assim que ela responder, decidiremos.","Dès qu'elle aura répondu, nous déciderons."],["Até amanhã, já terei enviado o arquivo.","D'ici demain, j'aurai envoyé le fichier."],["Depois que você conferir, publicaremos.","Une fois que tu auras vérifié, nous publierons."],["Ele provavelmente esqueceu nosso encontro.","Il aura oublié notre rendez-vous."],["Ela terá chegado antes do almoço.","Elle sera arrivée avant le déjeuner."],["Vamos deixar uma margem para imprevistos.","Nous garderons une marge pour les imprévus."],["Vou cobrar uma resposta ainda hoje.","Je relancerai mon contact aujourd'hui même."],["Na sexta, o essencial já estará pronto.","Vendredi, l'essentiel sera déjà prêt."]]},{"title":"J'aurais dû...","goal":"Expressar arrependimentos, críticas construtivas e hipóteses sobre situações passadas com conditionnel passé e si + plus-que-parfait.","speakers":{"Inès":"f","Lucas":"m"},"setting":"Inès e Lucas discutem uma candidatura a financiamento recusada por falta de um documento.","lines":[["Inès","Tu as eu des nouvelles pour notre dossier de subvention ? La réponse devait arriver vendredi, mais je n'ai rien reçu.","Você teve notícias do pedido de financiamento? A resposta deveria chegar na sexta, mas não recebi nada."],["Lucas","Oui, et ce n'est pas une bonne nouvelle. Le dossier a été rejeté : j'avais oublié de joindre le tableau du budget. J'aurais dû tout vérifier.","Sim, e não são boas notícias. Foi recusado: esqueci de anexar a planilha de orçamento. Deveria ter conferido tudo."],["Inès","Ah mince... Je t'avais pourtant envoyé ce tableau jeudi. Tu n'as pas vu mon message avec la pièce jointe ?","Puxa... Mas enviei a planilha na quinta. Não viu minha mensagem com o anexo?"],["Lucas","Si, mais je l'ai lu entre deux réunions. Si j'avais pris cinq minutes de plus, j'aurais remarqué que le fichier manquait.","Vi, mas li entre duas reuniões. Se tivesse dedicado cinco minutos a mais, teria notado a falta do arquivo."],["Inès","Et si tu m'avais transmis la version finale avant l'envoi, j'aurais pu repérer le problème à temps.","Se você tivesse me enviado a versão final, eu poderia ter identificado o problema a tempo."],["Lucas","C'est vrai. Tu aurais aussi pu me rappeler que tu attendais cette copie, mais c'était surtout à moi de l'envoyer.","Verdade. Você também poderia ter me lembrado da cópia, mas era responsabilidade minha enviar."],["Inès","De mon côté, je n'aurais pas dû supposer que tout était prêt. Je m'en veux de ne pas avoir posé la question.","Eu não deveria ter presumido que tudo estava pronto. Estou chateada por não ter perguntado."],["Lucas","Ne te reproche pas toute l'erreur. C'est moi qui avais promis de faire la dernière vérification avant la date limite.","Não se culpe por todo o erro. Fui eu que prometi fazer a última conferência."],["Inès","On aurait peut-être obtenu cette aide si le dossier avait été complet. Les ateliers auraient pu commencer dès janvier.","Talvez tivéssemos conseguido o apoio com o pedido completo. As oficinas poderiam ter começado em janeiro."],["Lucas","Peut-être, mais rien n'était garanti. Même avec un dossier impeccable, notre demande aurait pu être refusée.","Talvez, mas nada era garantido. Mesmo impecável, o pedido poderia ter sido recusado."],["Inès","Tu as raison. On ferait mieux d'en tirer une leçon plutôt que de chercher un coupable. Qu'est-ce qu'on peut encore faire ?","Tem razão. Melhor aprender com isso do que procurar culpados. O que podemos fazer?"],["Lucas","J'aurais préféré qu'on en parle hier, mais j'avais besoin de prendre du recul. J'ai finalement appelé le service ce matin.","Teria preferido conversar ontem, mas precisava refletir. Liguei para o setor hoje de manhã."],["Inès","Et qu'est-ce qu'ils ont dit ? Si on expliquait la situation, ils accepteraient peut-être de revoir notre dossier.","O que disseram? Se explicássemos, talvez aceitassem reavaliar o pedido."],["Lucas","Malheureusement non. Si nous avions signalé l'oubli avant la clôture, ils auraient accepté le document manquant.","Infelizmente não. Se tivéssemos comunicado o esquecimento antes do encerramento, teriam aceitado o documento."],["Inès","C'est dommage. Pour le prochain appel à projets, on pourrait créer une liste de contrôle et prévoir deux relectures.","É uma pena. No próximo edital, poderíamos criar uma lista de controle e prever duas revisões."],["Lucas","Bonne idée. Sans cette erreur, on n'aurait peut-être jamais revu notre méthode. Je t'enverrai une première liste ce soir.","Boa ideia. Sem esse erro, talvez nunca revisássemos nosso método. Enviarei uma primeira lista hoje."]],"grammar":[{"h":"Conditionnel passé: formação","p":["Forme com <b>avoir</b> ou <b>être</b> no conditionnel présent e o particípio passado. Essa forma apresenta uma hipótese contrária a algo realizado."],"ex":[["J'aurais vérifié le dossier plus tôt.","Teria conferido a solicitação antes."],["Elle serait venue si tu l'avais invitée.","Ela teria vindo se você tivesse convidado."],["Nous aurions terminé avant vendredi.","Teríamos terminado antes de sexta."]],"tip":"A escolha do auxiliar segue as regras dos tempos compostos."},{"h":"J'aurais dû e j'aurais pu","p":["<b>J'aurais dû</b> apresenta uma obrigação não cumprida; <b>j'aurais pu</b> apresenta uma possibilidade não aproveitada. Na negativa, je n'aurais pas dû exprime arrependimento por uma ação realizada."],"ex":[["J'aurais dû relire les pièces jointes.","Eu deveria ter relido os anexos."],["Je n'aurais pas dû envoyer le dossier si vite.","Não deveria ter enviado tão rápido."],["Tu aurais pu me prévenir plus tôt.","Você poderia ter me avisado antes."]],"tip":"Suavize críticas para não soar acusatório."},{"h":"Si + plus-que-parfait","p":["Na hipótese irreal sobre o passado, usamos <b>si + plus-que-parfait</b> na condição e conditionnel passé no resultado. Não use conditionnel imediatamente após si."],"ex":[["Si j'avais su, j'aurais attendu.","Se eu soubesse, teria esperado."],["Nous aurions réussi si nous avions mieux préparé.","Teríamos conseguido se tivéssemos nos preparado melhor."],["Si elle était arrivée plus tôt, elle aurait aidé.","Se chegasse mais cedo, teria ajudado."]],"tip":"Si j'avais su, nunca si j'aurais su."},{"h":"Hipóteses com nuance","p":["O conditionnel passé aparece em avaliações e conjecturas, com talvez e condições implícitas, sem apresentar resultados como garantidos."],"ex":[["On aurait peut-être obtenu une aide.","Talvez tivéssemos obtido apoio."],["Sans ton aide, je n'aurais pas fini.","Sem sua ajuda não teria terminado."],["À ta place, j'aurais demandé conseil.","No seu lugar teria pedido orientação."]],"tip":"Peut-être indica incerteza sobre o resultado alternativo."}],"vocab":[{"h":"Documentos e financiamento","items":[["une subvention","um subsídio"],["un dossier","uma solicitação"],["une pièce jointe","um anexo"],["un budget","um orçamento"],["un appel à projets","um edital"],["une candidature","uma candidatura"],["une date limite","um prazo final"],["une clôture","um encerramento"]]},{"h":"Erros e soluções","items":[["oublier de","esquecer de"],["joindre un fichier","anexar um arquivo"],["repérer une erreur","identificar um erro"],["supposer","presumir"],["s'en vouloir","ficar chateado consigo"],["reprocher","censurar"],["prendre du recul","refletir com distanciamento"],["une liste de contrôle","uma lista de conferência"]]}],"pron":[{"h":"aurais e aurait","p":"O s ou t final é mudo. As duas palavras soam aproximadamente “orè”.","w":["j'aurais dû","tu aurais pu","il aurait accepté"]},{"h":"dû e pu","p":"O u francês tem lábios arredondados e posição de língua próxima ao i. Tente “dü” e “pü”.","w":["j'aurais dû","elle aurait pu","nous aurions dû"]}],"mc":[{"q":"Por que a solicitação de financiamento foi recusada?","o":["Faltava a planilha do orçamento","O projeto custava demais","Não havia participantes inscritos"],"a":0,"e":"Oui, et ce n'est pas une bonne nouvelle. Le dossier a été rejeté : j'avais oublié de joindre le tableau du budget. J'aurais dû tout vérifier."},{"q":"O que Inès poderia ter feito com a versão final?","o":["Alterar o prazo","Enviar um novo contrato","Identificar o problema a tempo"],"a":2,"e":"Et si tu m'avais transmis la version finale avant l'envoi, j'aurais pu repérer le problème à temps."},{"q":"A aprovação estaria garantida com o documento completo?","o":["Sim, já estava aprovada","Não, ainda poderia ser recusada","Sim, porque o orçamento era pequeno"],"a":1,"e":"Peut-être, mais rien n'était garanti. Même avec un dossier impeccable, notre demande aurait pu être refusée."},{"q":"Qual solução Inès propõe para o próximo edital?","o":["Criar lista de conferência e fazer duas revisões","Deixar para o último dia","Eliminar anexos obrigatórios"],"a":0,"e":"C'est dommage. Pour le prochain appel à projets, on pourrait créer une liste de contrôle et prévoir deux relectures."}],"gaps":[{"s":"Si j'___ (vérifier, plus-que-parfait) le dossier, j'aurais vu l'erreur.","a":["avais vérifié"],"h":"Se eu tivesse conferido, teria visto o erro."},{"s":"J'___ (devoir, conditionnel passé) relire les documents.","a":["aurais dû"],"h":"Eu deveria ter relido os documentos."},{"s":"Si Inès m'avait prévenu, je l'___ (remarquer, conditionnel passé).","a":["aurais remarqué"],"h":"Se Inès tivesse avisado, eu teria percebido."},{"s":"Elle ___ (venir, conditionnel passé) si elle avait eu le temps.","a":["serait venue"],"h":"Ela teria vindo se tivesse tido tempo."},{"s":"Si nous ___ (envoyer, plus-que-parfait) le dossier à temps, ils l'auraient accepté.","a":["avions envoyé"],"h":"Se tivéssemos enviado a tempo, teriam aceitado."},{"s":"À ta place, je n'___ (pas envoyer, conditionnel passé) le dossier si vite.","a":["aurais pas envoyé"],"h":"No seu lugar, não teria enviado tão rápido."}],"order":[{"t":["J'aurais","dû","vérifier","la","pièce","jointe."],"h":"Eu deveria ter conferido o anexo."},{"t":["Sans","ton","aide,","je","n'y","serais","pas","arrivé."],"h":"Sem sua ajuda, não teria conseguido."},{"t":["La","réponse","aurait","peut-être","été","différente."],"h":"Talvez a resposta fosse diferente."}],"dict":[{"t":"Oui, et ce n'est pas une bonne nouvelle. Le dossier a été rejeté : j'avais oublié de joindre le tableau du budget. J'aurais dû tout vérifier."},{"t":"Et si tu m'avais transmis la version finale avant l'envoi, j'aurais pu repérer le problème à temps."},{"t":"Ne te reproche pas toute l'erreur. C'est moi qui avais promis de faire la dernière vérification avant la date limite."},{"t":"Tu as raison. On ferait mieux d'en tirer une leçon plutôt que de chercher un coupable. Qu'est-ce qu'on peut encore faire ?"},{"t":"C'est dommage. Pour le prochain appel à projets, on pourrait créer une liste de contrôle et prévoir deux relectures."}],"shadow":["Oui, et ce n'est pas une bonne nouvelle. Le dossier a été rejeté : j'avais oublié de joindre le tableau du budget. J'aurais dû tout vérifier.","C'est vrai. Tu aurais aussi pu me rappeler que tu attendais cette copie, mais c'était surtout à moi de l'envoyer.","Tu as raison. On ferait mieux d'en tirer une leçon plutôt que de chercher un coupable. Qu'est-ce qu'on peut encore faire ?","Bonne idée. Sans cette erreur, on n'aurait peut-être jamais revu notre méthode. Je t'enverrai une première liste ce soir."],"write":{"task":"Escreva seis frases sobre uma decisão passada de que se arrepende e o que teria mudado com outra escolha.","ph":"La semaine dernière, j'aurais dû … . Si j'avais …"},"cards":[["Eu deveria ter conferido o anexo.","J'aurais dû vérifier la pièce jointe."],["Eu não deveria ter esperado tanto.","Je n'aurais pas dû attendre si longtemps."],["Você poderia ter me avisado.","Tu aurais pu me prévenir."],["Se eu soubesse, teria ligado.","Si j'avais su, j'aurais appelé."],["Sem sua ajuda, não teria conseguido.","Sans ton aide, je n'y serais pas arrivé."],["Ela teria vindo mais cedo.","Elle serait venue plus tôt."],["Teríamos evitado esse problema.","Nous aurions évité ce problème."],["No seu lugar, eu teria pedido ajuda.","À ta place, j'aurais demandé de l'aide."],["Talvez a resposta fosse diferente.","La réponse aurait peut-être été différente."],["Poderíamos ter resolvido ontem.","Nous aurions pu régler ça hier."]]},{"title":"Bien que ce soit difficile","goal":"Expressar sentimentos, dúvidas e concessões usando subjonctif depois de bien que, avoir peur que e douter que.","speakers":{"Claire":"f","Antoine":"m"},"setting":"Em Lyon, Claire e Antoine organizam um ateliê comunitário enquanto aguardam confirmação da prefeitura.","lines":[["Claire","Bien que l'atelier de réparation soit prévu samedi, la mairie n'a toujours pas confirmé la salle. Ça commence à m'inquiéter.","Embora a oficina esteja prevista para sábado, a prefeitura não confirmou a sala. Estou começando a me preocupar."],["Antoine","J'ai peur qu'ils nous répondent trop tard pour prévenir les bénévoles. Tu as essayé de les joindre ce matin ?","Tenho medo de que respondam tarde demais para avisarmos os voluntários. Você tentou falar com eles?"],["Claire","Oui, mais personne n'a décroché. Je doute que nous obtenions une réponse aujourd'hui si on attend sans rien faire.","Sim, mas ninguém atendeu. Duvido que tenhamos resposta hoje se ficarmos esperando."],["Antoine","On pourrait passer directement à l'accueil. Même si l'employée est débordée, elle pourra peut-être nous renseigner.","Podemos passar na recepção. Mesmo sobrecarregada, talvez a funcionária consiga nos informar."],["Claire","Je suis contente que tu proposes quelque chose de concret. J'avais commencé à imaginer le pire.","Fico contente que proponha algo concreto. Eu já imaginava o pior."],["Antoine","Et pour les bénévoles ? Je crains que certains soient déjà pris samedi matin depuis qu'on a changé l'horaire.","E os voluntários? Receio que alguns já tenham compromissos sábado de manhã após a mudança de horário."],["Claire","Bien que nous soyons moins nombreux que prévu, on peut maintenir les réparations les plus simples.","Embora sejamos menos que o previsto, podemos manter os reparos mais simples."],["Antoine","Je trouve dommage que l'atelier sur les vélos soit annulé. C'était celui qui attirait le plus de monde.","Acho uma pena que a oficina de bicicletas seja cancelada. Era a mais procurada."],["Claire","Il n'est pas annulé. Je doute simplement que nous ayons assez d'outils pour accueillir vingt personnes.","Não foi cancelada. Duvido apenas que tenhamos ferramentas para vinte pessoas."],["Antoine","J'en apporterai quelques-uns. Ça me rassure que tu veuilles adapter le programme plutôt que renoncer.","Vou levar algumas ferramentas. Me tranquiliza que prefira adaptar a programação a desistir."],["Claire","Merci. J'ai aussi peur que des visiteurs viennent avec des appareils trop dangereux à réparer sur place.","Obrigada. Também tenho medo de que tragam aparelhos perigosos demais para reparar ali."],["Antoine","On précisera les règles à l'inscription. Bien que ce soit gratuit, il faut expliquer ce qu'on ne peut pas prendre en charge.","Vamos esclarecer as regras na inscrição. Embora gratuito, precisamos explicar as limitações."],["Claire","Attends, la mairie vient de répondre : la petite salle est libre, mais la grande est réservée pour une réunion.","Espere, a prefeitura respondeu: a sala pequena está livre, mas a grande foi reservada."],["Antoine","Je suis soulagé qu'on ait enfin une salle ! Mais je doute que tout le matériel tienne dans cet espace.","Estou aliviado por termos uma sala! Mas duvido que o material caiba."],["Claire","On installera deux tables au lieu de quatre. Je suis ravie que tu sois prêt à revoir l'organisation.","Colocaremos duas mesas em vez de quatro. Estou feliz por você topar reorganizar."],["Antoine","Alors je préviens les bénévoles. Même si tout n'est pas parfait, je suis sûr qu'on fera quelque chose d'utile.","Então aviso os voluntários. Mesmo que nem tudo seja perfeito, faremos algo útil."]],"grammar":[{"h":"Sentimentos com subjonctif","p":["Expressões como <b>être content que</b>, être ravi que e trouver dommage que pedem subjonctif mesmo quando o fato é real."],"ex":[["Je suis ravie que tu sois disponible.","Fico feliz que você esteja disponível."],["Ça me rassure que vous connaissiez les règles.","Fico mais tranquilo por conhecerem as regras."],["C'est dommage que cet atelier soit annulé.","É uma pena que essa oficina seja cancelada."]],"tip":"O subjonctif marca uma reação emocional, não necessariamente dúvida."},{"h":"Avoir peur que e craindre que","p":["Essas expressões de receio pedem subjonctif. Em registros formais pode aparecer ne explétif, que sozinho não expressa negação."],"ex":[["J'ai peur que les bénévoles arrivent tard.","Tenho medo de que os voluntários cheguem tarde."],["Je crains que la salle soit trop petite.","Receio que a sala seja pequena."],["Elle a peur que nous ne puissions pas terminer.","Ela teme que não consigamos terminar."]],"tip":"Para negar, use ne... pas."},{"h":"Douter que","p":["<b>Douter que</b> expressa incerteza e normalmente pede subjonctif; quando a afirmação é de certeza, como ne pas douter que, o indicatif é frequente."],"ex":[["Je doute qu'ils puissent venir.","Duvido que possam vir."],["Nous doutons que ce budget soit suffisant.","Duvidamos que baste o orçamento."],["Elle doute que nous ayons assez de temps.","Ela duvida que tenhamos tempo."]],"tip":"Memorize je doute que ce soit possible."},{"h":"Bien que x même si","p":["<b>Bien que</b> usa subjonctif para concessão; <b>même si</b> usa indicatif mesmo quando o português usa o subjuntivo."],"ex":[["Bien que ce soit difficile, continuons.","Embora difícil, vamos continuar."],["Bien qu'il pleuve, les visiteurs arrivent.","Embora chova, os visitantes chegam."],["Même s'il pleut, nous maintiendrons l'événement.","Mesmo que chova, manteremos o evento."]],"tip":"Bien que ce soit, mas même si c'est."}],"vocab":[{"h":"Organização comunitária","items":[["un atelier de réparation","uma oficina de reparos"],["une mairie","uma prefeitura"],["un bénévole","um voluntário"],["une inscription","uma inscrição"],["un outil","uma ferramenta"],["un appareil","um aparelho"],["un matériel","um equipamento"],["prendre en charge","assumir responsabilidade"]]},{"h":"Emoções e soluções","items":[["être soulagé","estar aliviado"],["être ravi","ficar feliz"],["être débordé","estar sobrecarregado"],["s'inquiéter","preocupar-se"],["craindre","recear"],["douter de","duvidar de"],["rassurer","tranquilizar"],["renoncer","desistir"]]}],"pron":[{"h":"bien que","p":"Bien tem vogal nasal, aproximadamente “biã”; evite pronunciar um n isolado.","w":["bien que","bien qu'il pleuve","bien que ce soit"]},{"h":"soit e soient","p":"As duas formas soam igual, aproximadamente “suá”, com consoantes finais mudas.","w":["soit","soient","sois"]}],"mc":[{"q":"Por que Claire está preocupada no início?","o":["Faltam inscrições","Todos desistiram","A prefeitura não confirmou a sala"],"a":2,"e":"Bien que l'atelier de réparation soit prévu samedi, la mairie n'a toujours pas confirmé la salle. Ça commence à m'inquiéter."},{"q":"O que Antoine sugere para obter informações?","o":["Ir pessoalmente à recepção","Cancelar o evento","Procurar outra prefeitura"],"a":0,"e":"On pourrait passer directement à l'accueil. Même si l'employée est débordée, elle pourra peut-être nous renseigner."},{"q":"Por que Claire tem dúvidas sobre a oficina de bicicletas?","o":["Ninguém demonstrou interesse","Talvez não haja ferramentas suficientes","Bicicletas são proibidas"],"a":1,"e":"Il n'est pas annulé. Je doute simplement que nous ayons assez d'outils pour accueillir vingt personnes."},{"q":"Como adaptam o espaço disponível?","o":["Mudam o evento para domingo","Eliminam todas as oficinas","Usam duas mesas em vez de quatro"],"a":2,"e":"On installera deux tables au lieu de quatre. Je suis ravie que tu sois prêt à revoir l'organisation."}],"gaps":[{"s":"Bien que ce ___ (être, subjonctif) difficile, nous continuerons.","a":["soit"],"h":"Embora seja difícil, continuaremos."},{"s":"J'ai peur que les bénévoles ___ (arriver, subjonctif) en retard.","a":["arrivent"],"h":"Tenho medo de que cheguem atrasados."},{"s":"Je doute que nous ___ (avoir, subjonctif) assez d'outils.","a":["ayons"],"h":"Duvido que tenhamos ferramentas suficientes."},{"s":"Je suis contente que tu ___ (proposer, subjonctif) une solution.","a":["proposes"],"h":"Fico contente que proponha uma solução."},{"s":"Bien que nous ___ (être, subjonctif) peu nombreux, l'atelier aura lieu.","a":["soyons"],"h":"Embora sejamos poucos, haverá oficina."},{"s":"Je crains qu'il ___ (pleuvoir, subjonctif) demain.","a":["pleuve"],"h":"Receio que chova amanhã."}],"order":[{"t":["Bien","que","ce","soit","compliqué,","nous","allons","essayer."],"h":"Embora complicado, vamos tentar."},{"t":["C'est","dommage","qu'elle","ne","puisse","pas","venir."],"h":"É uma pena que ela não possa vir."},{"t":["Je","doute","qu'ils","soient","d'accord."],"h":"Duvido que eles concordem."}],"dict":[{"t":"J'ai peur qu'ils nous répondent trop tard pour prévenir les bénévoles. Tu as essayé de les joindre ce matin ?"},{"t":"Je suis contente que tu proposes quelque chose de concret. J'avais commencé à imaginer le pire."},{"t":"Je trouve dommage que l'atelier sur les vélos soit annulé. C'était celui qui attirait le plus de monde."},{"t":"Merci. J'ai aussi peur que des visiteurs viennent avec des appareils trop dangereux à réparer sur place."},{"t":"On installera deux tables au lieu de quatre. Je suis ravie que tu sois prêt à revoir l'organisation."}],"shadow":["J'ai peur qu'ils nous répondent trop tard pour prévenir les bénévoles. Tu as essayé de les joindre ce matin ?","Et pour les bénévoles ? Je crains que certains soient déjà pris samedi matin depuis qu'on a changé l'horaire.","Merci. J'ai aussi peur que des visiteurs viennent avec des appareils trop dangereux à réparer sur place.","Alors je préviens les bénévoles. Même si tout n'est pas parfait, je suis sûr qu'on fera quelque chose d'utile."],"write":{"task":"Escreva seis frases sobre imprevistos em um evento com bien que, avoir peur que, douter que e sentimentos.","ph":"Bien que notre événement soit …, j'ai peur que …"},"cards":[["Embora complicado, vamos tentar.","Bien que ce soit compliqué, nous allons essayer."],["Tenho medo de que ele se atrase.","J'ai peur qu'il soit en retard."],["Duvido que isso seja suficiente.","Je doute que ce soit suffisant."],["Fico feliz que esteja aqui.","Je suis heureux que tu sois là."],["É uma pena que ela não possa vir.","C'est dommage qu'elle ne puisse pas venir."],["Receio que tenhamos pouco tempo.","Je crains que nous ayons peu de temps."],["Embora cansados, eles continuam.","Bien qu'ils soient fatigués, ils continuent."],["Fico aliviado que tudo esteja pronto.","Je suis soulagé que tout soit prêt."],["Duvido que eles concordem.","Je doute qu'ils soient d'accord."],["Mesmo que chova, iremos.","Même s'il pleut, nous irons."]]},{"title":"Indicatif ou subjonctif ?","goal":"Escolher entre indicatif e subjonctif em opiniões e hipóteses, e empregar subjonctif passé para ações anteriores.","speakers":{"Inès":"f","Lucas":"m"},"setting":"Inès e Lucas analisam uma pesquisa sobre trabalho híbrido antes de apresentá-la à direção.","lines":[["Inès","J'ai enfin reçu les résultats de notre enquête sur le télétravail. Je pense que l'équipe est plutôt satisfaite des deux jours à distance.","Recebi os resultados da pesquisa sobre teletrabalho. Acho que a equipe está satisfeita com os dois dias remotos."],["Lucas","C'est encourageant, mais je ne pense pas que les chiffres racontent toute l'histoire. Combien de personnes ont répondu ?","É animador, mas não acho que os números contem tudo. Quantas pessoas responderam?"],["Inès","Trente-deux sur quarante. Je suis certaine que les réponses ont été enregistrées correctement, mais il manque encore des commentaires.","Trinta e duas de quarenta. Tenho certeza de que foram registradas corretamente, mas faltam comentários."],["Lucas","Il est possible que certaines personnes aient oublié le questionnaire. Le rappel est parti tard vendredi, non ?","É possível que algumas pessoas tenham esquecido o questionário. O lembrete saiu tarde na sexta, não?"],["Inès","Oui. Je regrette que nous ayons envoyé le rappel si tard. J'espère pourtant que les derniers retours arriveront avant jeudi.","Sim. Lamento termos enviado tão tarde. Espero que as últimas respostas cheguem antes de quinta."],["Lucas","À mon avis, nous pouvons déjà présenter les tendances, à condition de signaler les limites de l'enquête.","Na minha opinião, já podemos apresentar as tendências, desde que indiquemos as limitações."],["Inès","Je ne crois pas que la direction veuille tirer des conclusions définitives dès maintenant. Elle veut surtout comprendre les difficultés.","Não acho que a direção queira conclusões definitivas agora. Quer entender as dificuldades."],["Lucas","Je pense que plusieurs collègues ont eu du mal à réserver une salle les jours de présence. Les témoignages le confirment.","Acho que colegas tiveram dificuldade para reservar salas nos dias presenciais. Os depoimentos confirmam."],["Inès","C'est vrai. Il se peut qu'on ait sous-estimé les besoins en salles de réunion. Ça expliquerait certaines critiques.","É verdade. Pode ser que tenhamos subestimado a necessidade de salas. Isso explicaria críticas."],["Lucas","Tu es sûre que tout le monde a reçu la même version du formulaire ? Le lien avait changé en cours de semaine.","Tem certeza de que todos receberam a mesma versão? O link mudou durante a semana."],["Inès","Oui, j'ai vérifié les envois. Je suis contente que tu aies soulevé ce point, car j'avais eu le même doute.","Sim, conferi os envios. Fico contente por levantar a questão; eu tinha a mesma dúvida."],["Lucas","Tant mieux. J'espère que nous trouverons une solution simple sans revoir toute l'organisation du travail.","Que bom. Espero que encontremos solução simples sem rever toda a organização."],["Inès","Je ne pense pas qu'il soit nécessaire de tout modifier. On pourrait commencer par réserver des espaces supplémentaires.","Não acho necessário mudar tudo. Poderíamos começar reservando espaços adicionais."],["Lucas","D'accord. Il est possible que les responsables aient déjà proposé des ajustements. Demandons-leur avant la réunion.","Certo. É possível que gestores já tenham proposto ajustes. Vamos perguntar antes da reunião."],["Inès","Bonne idée. Je sais que deux équipes ont changé leurs horaires, mais je ne suis pas sûre que les autres aient fait de même.","Boa ideia. Sei que duas equipes mudaram os horários, mas não sei se outras fizeram o mesmo."],["Lucas","Alors, présentons ce qui est confirmé et distinguons clairement ce qui reste à vérifier. Ce sera plus convaincant.","Então vamos apresentar o confirmado e distinguir o que precisa ser verificado. Será mais convincente."]],"grammar":[{"h":"Penser que afirmativo","p":["Com <b>je pense que</b> e <b>je crois que</b> afirmativos, o indicatif apresenta uma opinião considerada verdadeira. Expressões de certeza também pedem indicatif."],"ex":[["Je pense que cette solution fonctionne.","Acho que essa solução funciona."],["Je crois qu'ils ont compris le problème.","Acho que entenderam."],["Je suis certaine que le rapport sera prêt.","Tenho certeza de que o relatório estará pronto."]],"tip":"Uma opinião não pede automaticamente subjonctif."},{"h":"Ne pas penser que","p":["Na negativa, penser que e croire que geralmente pedem subjonctif, expressando dúvida ou rejeição da informação."],"ex":[["Je ne pense pas que ce soit vrai.","Não acho que isso seja verdade."],["Je ne crois pas qu'ils comprennent.","Não acredito que entendam."],["Je ne suis pas sûre que tout le monde ait raison.","Não tenho certeza de que todos tenham razão."]],"tip":"Compare je pense qu'il vient e je ne pense pas qu'il vienne."},{"h":"Espérer que x il est possible que","p":["<b>Espérer que</b> costuma pedir indicatif, especialmente futur simple, enquanto <b>il est possible que</b> e <b>il se peut que</b> pedem subjonctif."],"ex":[["J'espère qu'il acceptera.","Espero que aceite."],["Il est possible qu'elle soit absente.","É possível que esteja ausente."],["Il se peut que nous devions reporter.","Pode ser que precisemos adiar."]],"tip":"Il est possible qu'il vienne, mas j'espère qu'il viendra."},{"h":"Subjonctif passé","p":["Forma-se com avoir ou être no subjonctif présent seguido do particípio passado. Apresenta ação anterior em oração que exige subjonctif."],"ex":[["Je regrette que nous ayons attendu.","Lamento termos esperado."],["Il est possible qu'elle ait oublié.","É possível que ela tenha esquecido."],["Je suis contente que tu sois venu.","Fico feliz por você ter vindo."]],"tip":"Que j'aie fait e qu'elle soit partie são formas usuais."}],"vocab":[{"h":"Pesquisa e resultados","items":[["une enquête","uma pesquisa"],["un questionnaire","um questionário"],["un résultat","um resultado"],["un témoignage","um depoimento"],["une tendance","uma tendência"],["un échantillon","uma amostra"],["une donnée","um dado"],["une conclusion","uma conclusão"]]},{"h":"Trabalho e opiniões","items":[["le télétravail","trabalho remoto"],["un travail hybride","trabalho híbrido"],["une salle de réunion","uma sala de reunião"],["un responsable","um responsável"],["un ajustement","um ajuste"],["un rappel","um lembrete"],["sous-estimer","subestimar"],["soulever un point","levantar uma questão"]]}],"pron":[{"h":"aie, ait e aient","p":"As três formas soam igual, com e aberto, aproximadamente “è”.","w":["que j'aie","qu'il ait","qu'ils aient"]},{"h":"espère e espérer","p":"O è de espère é aberto; o -er final de espérer tem som mais fechado, como “ê”.","w":["j'espère","nous espérons","espérer une réponse"]}],"mc":[{"q":"Quantas pessoas responderam à pesquisa?","o":["Vinte e oito de quarenta","Trinta e duas de quarenta","Todas as quarenta"],"a":1,"e":"Trente-deux sur quarante. Je suis certaine que les réponses ont été enregistrées correctement, mais il manque encore des commentaires."},{"q":"Que erro Inès lamenta?","o":["Apagar resultados","Usar formulário incorreto","Enviar o lembrete tarde demais"],"a":2,"e":"Oui. Je regrette que nous ayons envoyé le rappel si tard. J'espère pourtant que les derniers retours arriveront avant jeudi."},{"q":"Que dificuldade aparece nos depoimentos?","o":["Reservar salas nos dias presenciais","Falta de computadores domésticos","Cancelamento dos dias remotos"],"a":0,"e":"Je pense que plusieurs collègues ont eu du mal à réserver une salle les jours de présence. Les témoignages le confirment."},{"q":"Como apresentarão os resultados?","o":["Apenas resultados positivos","Separando fatos confirmados do que falta verificar","Adiando um mês"],"a":1,"e":"Alors, présentons ce qui est confirmé et distinguons clairement ce qui reste à vérifier. Ce sera plus convaincant."}],"gaps":[{"s":"Je pense que cette solution ___ (être, indicatif présent) efficace.","a":["est"],"h":"Acho que a solução é eficaz."},{"s":"Je ne pense pas que ce chiffre ___ (être, subjonctif présent) fiable.","a":["soit"],"h":"Não acho que esse número seja confiável."},{"s":"J'espère que la direction ___ (accepter, futur simple) notre proposition.","a":["acceptera"],"h":"Espero que a direção aceite."},{"s":"Il est possible qu'ils ___ (oublier, subjonctif passé) le questionnaire.","a":["aient oublié"],"h":"É possível que tenham esquecido o questionário."},{"s":"Je suis contente que tu ___ (soulever, subjonctif passé) cette question.","a":["aies soulevé"],"h":"Fico contente que tenha levantado a questão."},{"s":"Je ne suis pas sûr qu'elle ___ (venir, subjonctif passé) hier.","a":["soit venue"],"h":"Não tenho certeza de que ela veio ontem."}],"order":[{"t":["Je","pense","que","cette","information","est","fiable."],"h":"Acho que essa informação é confiável."},{"t":["Je","suis","sûr","qu'il","a","compris."],"h":"Tenho certeza de que ele entendeu."},{"t":["J'espère","que","tout","fonctionnera","bien."],"h":"Espero que tudo funcione bem."}],"dict":[{"t":"C'est encourageant, mais je ne pense pas que les chiffres racontent toute l'histoire. Combien de personnes ont répondu ?"},{"t":"Oui. Je regrette que nous ayons envoyé le rappel si tard. J'espère pourtant que les derniers retours arriveront avant jeudi."},{"t":"Je pense que plusieurs collègues ont eu du mal à réserver une salle les jours de présence. Les témoignages le confirment."},{"t":"Oui, j'ai vérifié les envois. Je suis contente que tu aies soulevé ce point, car j'avais eu le même doute."},{"t":"Bonne idée. Je sais que deux équipes ont changé leurs horaires, mais je ne suis pas sûre que les autres aient fait de même."}],"shadow":["C'est encourageant, mais je ne pense pas que les chiffres racontent toute l'histoire. Combien de personnes ont répondu ?","À mon avis, nous pouvons déjà présenter les tendances, à condition de signaler les limites de l'enquête.","Oui, j'ai vérifié les envois. Je suis contente que tu aies soulevé ce point, car j'avais eu le même doute.","Alors, présentons ce qui est confirmé et distinguons clairement ce qui reste à vérifier. Ce sera plus convaincant."],"write":{"task":"Analise uma pequena pesquisa e escreva seis frases sobre opiniões, dúvidas, esperanças e fatos anteriores.","ph":"Je pense que les résultats … . Je ne crois pas que …"},"cards":[["Acho que essa informação é confiável.","Je pense que cette information est fiable."],["Não acho que seja a melhor solução.","Je ne pense pas que ce soit la meilleure solution."],["Espero que eles aceitem a proposta.","J'espère qu'ils accepteront la proposition."],["É possível que ela tenha esquecido.","Il est possible qu'elle ait oublié."],["Tenho certeza de que ele entendeu.","Je suis sûr qu'il a compris."],["Não acredito que eles saibam disso.","Je ne crois pas qu'ils le sachent."],["Lamento que tenhamos esperado tanto.","Je regrette que nous ayons tant attendu."],["Pode ser que ele já tenha saído.","Il se peut qu'il soit déjà parti."],["Espero que tudo funcione bem.","J'espère que tout fonctionnera bien."],["Não tenho certeza de que ela recebeu.","Je ne suis pas sûr qu'elle ait reçu le message."]]},{"title":"Le projet auquel je pense","goal":"Empregar pronomes relativos compostos lequel, auquel, duquel e suas variações com preposições.","speakers":{"Inès":"f","Antoine":"m"},"setting":"Inès e Antoine avaliam propostas para transformar um antigo cinema em Bordeaux.","lines":[["Inès","J'ai relu les propositions pour l'ancien cinéma. Le projet auquel je pense permettrait d'en faire un lieu ouvert aux associations.","Reli as propostas do antigo cinema. O projeto em que penso o transformaria em espaço para associações."],["Antoine","Tu parles du dossier sur lequel nous avons travaillé en juin ? Celui qui prévoit une salle polyvalente au rez-de-chaussée ?","Está falando do documento em que trabalhamos em junho? Aquele com sala multiuso no térreo?"],["Inès","Exactement. La salle dans laquelle on organiserait les débats existe déjà. Il faudrait surtout refaire l'isolation.","Exato. A sala onde organizaríamos debates já existe. Precisamos refazer o isolamento."],["Antoine","Et la cour à côté de laquelle se trouve l'entrée secondaire ? On pourrait l'utiliser pour les événements d'été.","E o pátio ao lado do qual fica a entrada secundária? Poderíamos usar para eventos no verão."],["Inès","C'est justement l'espace auquel les habitants tiennent le plus, d'après la consultation organisée au printemps.","É justamente o espaço mais valorizado pelos moradores, segundo a consulta da primavera."],["Antoine","Le comité auprès duquel nous avons déposé la demande souhaite-t-il conserver les murs d'origine ?","O comitê ao qual apresentamos o pedido quer preservar as paredes originais?"],["Inès","Oui. Les architectes avec lesquels nous avons échangé proposent de garder la façade et de renforcer la structure.","Sim. Os arquitetos com quem conversamos propõem manter a fachada e reforçar a estrutura."],["Antoine","Le bureau pour lequel je travaillais autrefois a rénové un bâtiment semblable. Je pourrais lui demander conseil.","O escritório para o qual trabalhava reformou um prédio semelhante. Posso pedir orientação."],["Inès","Bonne idée. Et les associations auxquelles nous avons écrit ont-elles confirmé leur intérêt pour les activités ?","Boa ideia. E as associações para as quais escrevemos confirmaram interesse?"],["Antoine","Trois ont répondu. Celle avec laquelle j'ai parlé hier aimerait réserver un créneau chaque mercredi après-midi.","Três responderam. A associação com que conversei ontem quer um horário às quartas à tarde."],["Inès","Il reste le jardin près duquel passe une piste cyclable. L'accès serait pratique pour les familles du quartier.","Ainda resta o jardim perto do qual passa uma ciclovia. Seria prático para famílias do bairro."],["Antoine","Le terrain autour duquel on voudrait installer des bancs appartient aussi à la ville. Il faudra son autorisation.","O terreno em torno do qual queremos instalar bancos também pertence à cidade. Precisaremos de autorização."],["Inès","On a reçu deux devis entre lesquels il faut choisir avant la fin du mois. Tu as pu comparer les montants ?","Recebemos dois orçamentos para escolher até o fim do mês. Você comparou os valores?"],["Antoine","Le premier, selon lequel les travaux dureraient six mois, est plus cher, mais il semble mieux détaillé.","O primeiro, segundo o qual a obra duraria seis meses, é mais caro, mas detalhado."],["Inès","Et le second ? Il manque des précisions sur les matériaux à partir desquels les cloisons seraient fabriquées.","E o segundo? Faltam detalhes dos materiais com que seriam feitas as divisórias."],["Antoine","Je vais poser ces questions aux entreprises et préparer un tableau grâce auquel nous pourrons comparer les offres.","Vou perguntar às empresas e criar uma tabela com que poderemos comparar as propostas."]],"grammar":[{"h":"Lequel: concordância","p":["O pronome relativo composto tem formas <b>lequel, laquelle, lesquels, lesquelles</b> conforme gênero e número do antecedente. Aparece após preposições."],"ex":[["Voici le dossier sur lequel je travaille.","Este é o documento em que trabalho."],["C'est la salle dans laquelle nous nous réunissons.","É a sala onde nos reunimos."],["Il y a des projets entre lesquels choisir.","Há projetos entre os quais escolher."]],"tip":"Identifique o nome retomado e depois a preposição."},{"h":"À + lequel","p":["Combine à com lequel: <b>auquel, à laquelle, auxquels, auxquelles</b>. Com pessoas, à qui também é comum."],"ex":[["C'est le projet auquel je pense.","É o projeto em que penso."],["Voici l'association à laquelle nous participons.","Esta é a associação de que participamos."],["Ce sont les personnes auxquelles nous avons écrit.","São as pessoas a quem escrevemos."]],"tip":"Penser à → le projet auquel je pense."},{"h":"De + lequel","p":["Após près de, à côté de, auprès de e outras locuções, use <b>duquel, de laquelle, desquels, desquelles</b>. Com um verbo seguido simplesmente de, dont costuma ser mais natural."],"ex":[["Voici le jardin près duquel je travaille.","Este é o jardim perto do qual trabalho."],["La maison à côté de laquelle il habite est grande.","A casa ao lado da qual mora é grande."],["Ce sont les documents à partir desquels nous travaillons.","São os documentos a partir dos quais trabalhamos."]],"tip":"Le projet dont je parle, mas le bâtiment à côté duquel j'habite."},{"h":"Outras preposições","p":["Com avec, pour, selon, entre e outras, mantenha a preposição seguida da forma adequada de lequel, sem contração."],"ex":[["C'est l'architecte avec lequel nous travaillons.","É o arquiteto com quem trabalhamos."],["Voici l'entreprise pour laquelle elle travaille.","Esta é a empresa para a qual ela trabalha."],["Selon ce document, les travaux sont terminés.","Segundo este documento, as obras terminaram."]],"tip":"Para pessoas, avec qui é muito frequente."}],"vocab":[{"h":"Arquitetura e espaços","items":[["un ancien cinéma","um antigo cinema"],["une salle polyvalente","uma sala multiuso"],["un rez-de-chaussée","um térreo"],["une façade","uma fachada"],["une isolation","um isolamento"],["une cloison","uma divisória"],["une cour","um pátio"],["une piste cyclable","uma ciclovia"]]},{"h":"Projetos e avaliação","items":[["un devis","um orçamento"],["une offre","uma proposta"],["un comité","um comitê"],["une demande","uma solicitação"],["une autorisation","uma autorização"],["un montant","um valor"],["une consultation","uma consulta pública"],["un créneau","um horário disponível"]]}],"pron":[{"h":"lequel e laquelle","p":"Lequel soa “le-kèl” e laquelle “la-kèl”; o e final de laquelle é mudo.","w":["lequel","laquelle","avec laquelle"]},{"h":"auquel e auxquels","p":"Auquel e auxquels têm a mesma pronúncia, aproximadamente “o-kèl”.","w":["auquel","auxquels","auxquelles"]}],"mc":[{"q":"Qual proposta Inès prefere?","o":["Transformar o cinema em espaço para associações","Demolir para construir apartamentos","Construir um estacionamento"],"a":0,"e":"J'ai relu les propositions pour l'ancien cinéma. Le projet auquel je pense permettrait d'en faire un lieu ouvert aux associations."},{"q":"O que os arquitetos querem conservar?","o":["Equipamentos de projeção","Cadeiras originais","A fachada do prédio"],"a":2,"e":"Oui. Les architectes avec lesquels nous avons échangé proposent de garder la façade et de renforcer la structure."},{"q":"Quantas associações responderam?","o":["Duas","Três","Cinco"],"a":1,"e":"Trois ont répondu. Celle avec laquelle j'ai parlé hier aimerait réserver un créneau chaque mercredi après-midi."},{"q":"Como Antoine pretende facilitar a escolha dos orçamentos?","o":["Fazer tabela comparativa após consultar empresas","Aceitar o mais barato imediatamente","Deixar a prefeitura escolher sozinha"],"a":0,"e":"Je vais poser ces questions aux entreprises et préparer un tableau grâce auquel nous pourrons comparer les offres."}],"gaps":[{"s":"Le projet ___ (à + lequel) je pense concerne le cinéma.","a":["auquel"],"h":"O projeto em que penso diz respeito ao cinema."},{"s":"La salle dans ___ (lequel, feminino singular) nous organiserons les débats existe déjà.","a":["laquelle"],"h":"A sala onde faremos debates já existe."},{"s":"Les associations ___ (à + lesquelles) nous avons écrit ont répondu.","a":["auxquelles"],"h":"As associações a que escrevemos responderam."},{"s":"Le jardin près ___ (de + lequel) passe la piste cyclable sera rénové.","a":["duquel"],"h":"O jardim perto do qual passa a ciclovia será reformado."},{"s":"Les architectes avec ___ (lequel, masculino plural) nous travaillons sont expérimentés.","a":["lesquels"],"h":"Os arquitetos com quem trabalhamos são experientes."},{"s":"L'entreprise pour ___ (lequel, feminino singular) elle travaille construit des bibliothèques.","a":["laquelle"],"h":"A empresa para a qual ela trabalha constrói bibliotecas."}],"order":[{"t":["C'est","le","projet","auquel","je","pense."],"h":"É o projeto em que estou pensando."},{"t":["Le","bâtiment","près","duquel","j'habite","est","ancien."],"h":"O prédio perto do qual moro é antigo."},{"t":["Voici","la","salle","dans","laquelle","nous","travaillons."],"h":"Esta é a sala onde trabalhamos."}],"dict":[{"t":"Tu parles du dossier sur lequel nous avons travaillé en juin ? Celui qui prévoit une salle polyvalente au rez-de-chaussée ?"},{"t":"C'est justement l'espace auquel les habitants tiennent le plus, d'après la consultation organisée au printemps."},{"t":"Le bureau pour lequel je travaillais autrefois a rénové un bâtiment semblable. Je pourrais lui demander conseil."},{"t":"Il reste le jardin près duquel passe une piste cyclable. L'accès serait pratique pour les familles du quartier."},{"t":"Et le second ? Il manque des précisions sur les matériaux à partir desquels les cloisons seraient fabriquées."}],"shadow":["Tu parles du dossier sur lequel nous avons travaillé en juin ? Celui qui prévoit une salle polyvalente au rez-de-chaussée ?","Le comité auprès duquel nous avons déposé la demande souhaite-t-il conserver les murs d'origine ?","Il reste le jardin près duquel passe une piste cyclable. L'accès serait pratique pour les familles du quartier.","Je vais poser ces questions aux entreprises et préparer un tableau grâce auquel nous pourrons comparer les offres."],"write":{"task":"Descreva um projeto em seis frases usando lequel, auquel, duquel e as formas femininas e plurais.","ph":"Le projet auquel je pense … . Les personnes avec lesquelles …"},"cards":[["É o projeto em que estou pensando.","C'est le projet auquel je pense."],["Esta é a sala onde trabalhamos.","Voici la salle dans laquelle nous travaillons."],["A empresa para a qual trabalho é pequena.","L'entreprise pour laquelle je travaille est petite."],["Conheço as pessoas com quem você trabalha.","Je connais les personnes avec lesquelles tu travailles."],["O prédio perto do qual moro é antigo.","Le bâtiment près duquel j'habite est ancien."],["Estas são as questões a que precisamos responder.","Voici les questions auxquelles nous devons répondre."],["Há duas propostas entre as quais escolher.","Il y a deux propositions entre lesquelles choisir."],["A ferramenta com a qual trabalho é prática.","L'outil avec lequel je travaille est pratique."],["O escritório ao lado do qual estacionamos está fechado.","Le bureau à côté duquel nous nous garons est fermé."],["Esta é a decisão da qual dependemos.","C'est la décision dont nous dépendons."]]},{"title":"Il m'a assuré que...","goal":"Relatar afirmações, promessas, perguntas e críticas com discurso indireto e concordância dos tempos.","speakers":{"Inès":"f","Lucas":"m"},"setting":"Inès e Lucas esclarecem informações contraditórias após uma reunião sobre uma conferência.","lines":[["Inès","La réunion avec l'organisatrice a été plus tendue que prévu. Elle a affirmé que le programme avait été modifié sans son accord.","A reunião foi mais tensa que o previsto. Ela afirmou que a programação foi alterada sem sua aprovação."],["Lucas","Pourtant, mardi, elle nous avait assuré que nous pouvions avancer. Tu lui as rappelé ce qu'elle avait écrit dans son message ?","Mas na terça ela tinha garantido que podíamos prosseguir. Lembrou a ela o que escreveu?"],["Inès","Oui, mais elle a précisé qu'elle avait seulement autorisé le changement de salle, pas celui des horaires.","Sim, mas disse que tinha autorizado só a mudança da sala, não dos horários."],["Lucas","Et le technicien ? Il prétendait avoir reçu la nouvelle version mercredi, alors que je la lui avais envoyée lundi.","E o técnico? Ele dizia ter recebido a nova versão na quarta, mas enviei na segunda."],["Inès","Il a expliqué qu'il n'avait ouvert le fichier que le lendemain de notre envoi. Il a reconnu qu'il aurait dû le vérifier plus tôt.","Explicou que só abriu o arquivo no dia seguinte. Reconheceu que deveria tê-lo conferido antes."],["Lucas","Au moins, il a reconnu son erreur. L'organisatrice t'a demandé pourquoi les horaires avaient changé ?","Pelo menos reconheceu o erro. A organizadora perguntou por que os horários mudaram?"],["Inès","Exactement. Elle voulait aussi savoir si les intervenants avaient tous reçu la dernière version du programme.","Exatamente. Queria saber se todos os palestrantes tinham recebido a última versão."],["Lucas","Je lui avais pourtant confirmé que les messages étaient partis la veille. Je ne comprends pas d'où vient cette confusion.","Mas confirmei que as mensagens saíram na véspera. Não entendo a confusão."],["Inès","Elle nous a reproché de ne pas avoir prévenu les bénévoles assez tôt. Sur ce point, je pense qu'elle avait raison.","Ela nos criticou por avisarmos os voluntários tarde. Nesse ponto tinha razão."],["Lucas","C'est vrai. Et qu'a-t-elle dit à propos de la salle principale ? Elle devait être disponible vendredi matin.","É verdade. E o que disse sobre a sala principal? Deveria estar disponível sexta."],["Inès","Elle a assuré qu'elle serait libre le lendemain et que l'équipe technique pourrait commencer l'installation à huit heures.","Garantiu que estaria livre no dia seguinte e que a instalação começaria às oito."],["Lucas","C'est déjà ça. Le responsable avait promis qu'il aurait terminé les vérifications avant l'arrivée des premiers invités.","Já é algo. O responsável prometera terminar as verificações antes dos convidados."],["Inès","Oui, mais l'organisatrice nous a demandé d'envoyer une confirmation écrite pour éviter toute nouvelle ambiguïté.","Sim, mas pediu confirmação escrita para evitar novas ambiguidades."],["Lucas","Bonne idée. Je lui expliquerai ce que nous avons modifié et pourquoi nous avons pris ces décisions.","Boa ideia. Explicarei o que mudamos e por quê."],["Inès","Ajoute aussi qu'elle nous avait demandé de réduire les pauses. C'est cette consigne qui a entraîné le changement d'horaires.","Acrescente que ela pediu reduzir os intervalos. Essa instrução causou a mudança."],["Lucas","D'accord. Je vais distinguer ce qu'elle a confirmé de ce que nous avons simplement supposé. Ce sera plus clair pour tout le monde.","Certo. Vou separar o que confirmou do que presumimos. Ficará mais claro."]],"grammar":[{"h":"Discurso indireto","p":["Para relatar palavras, use <b>dire que</b>, affirmer que e expliquer que. Depois de verbo introdutório no passado, o présent simultâneo passa frequentemente ao imparfait."],"ex":[["Il dit qu'il est disponible.","Ele diz que está disponível."],["Il a dit qu'il était disponible.","Ele disse que estava disponível."],["Elle a expliqué qu'elle travaillait.","Ela explicou que trabalhava."]],"tip":"Ajuste também pronomes e possessivos."},{"h":"Concordância dos tempos","p":["O passé composé passa frequentemente ao plus-que-parfait; o futur simple ao conditionnel présent; e o futur antérieur ao conditionnel passé."],"ex":[["Elle a affirmé qu'elle avait envoyé le dossier.","Ela afirmou que enviara o documento."],["Il a assuré qu'il terminerait le lendemain.","Garantiu que terminaria no dia seguinte."],["Elle avait promis qu'elle aurait tout vérifié.","Prometera que teria conferido tudo."]],"tip":"Preserve a cronologia das ações."},{"h":"Perguntas e instruções indiretas","p":["Para pergunta sim/não, use <b>demander si</b>; perguntas abertas mantêm pourquoi, quand, où, comment ou ce que sem inversão. Pedidos usam demander à quelqu'un de + infinitif."],"ex":[["Elle m'a demandé si la salle était libre.","Ela perguntou se a sala estava livre."],["Il voulait savoir ce que nous avions décidé.","Queria saber o que decidíramos."],["Elle nous a demandé de confirmer.","Ela pediu para confirmarmos."]],"tip":"Não reproduza inversão da pergunta direta."},{"h":"Verbos e referências temporais","p":["Affirmer apresenta declaração firme; assurer, garantia; prétendre, alegação por vezes posta em dúvida; reprocher à quelqu'un de, crítica. Adapte hier/demain para la veille/le lendemain."],"ex":[["Il prétendait avoir reçu le message la veille.","Alegava ter recebido na véspera."],["Elle lui a reproché de ne pas avoir répondu.","Criticou-o por não ter respondido."],["Il reviendrait le lendemain.","Voltaria no dia seguinte."]],"tip":"Ne pas confundir reprocher e répéter."}],"vocab":[{"h":"Comunicação profissional","items":[["une affirmation","uma afirmação"],["une consigne","uma instrução"],["une confirmation écrite","uma confirmação escrita"],["un malentendu","um mal-entendido"],["une ambiguïté","uma ambiguidade"],["un intervenant","um palestrante"],["une modification","uma mudança"],["une vérification","uma conferência"]]},{"h":"Relatos e prazos","items":[["affirmer que","afirmar que"],["assurer que","garantir que"],["prétendre que","alegar que"],["reprocher à quelqu'un de","criticar alguém por"],["la veille","na véspera"],["le lendemain","no dia seguinte"],["ce jour-là","naquele dia"],["à temps","a tempo"]]}],"pron":[{"h":"affirmer e assurer","p":"Affirmer termina com -er pronunciado “ê”; em assurer, o u é arredondado.","w":["affirmer","assurer","elle a assuré"]},{"h":"reprocher e reproché","p":"As formas soam igual, aproximadamente “re-pro-chê”; ch corresponde a ch de chuva.","w":["reprocher","reproché","elle lui a reproché"]}],"mc":[{"q":"O que a organizadora afirmou?","o":["A programação mudou sem sua autorização","Todos cancelaram","O evento foi adiado um mês"],"a":0,"e":"La réunion avec l'organisatrice a été plus tendue que prévu. Elle a affirmé que le programme avait été modifié sans son accord."},{"q":"O que o técnico reconheceu?","o":["Que perdeu o computador","Que não recebeu o arquivo","Que deveria tê-lo conferido antes"],"a":2,"e":"Il a expliqué qu'il n'avait ouvert le fichier que le lendemain de notre envoi. Il a reconnu qu'il aurait dû le vérifier plus tôt."},{"q":"Por que ela criticou a equipe?","o":["Equipamentos muito antigos","Voluntários avisados tarde demais","Inscrições encerradas"],"a":1,"e":"Elle nous a reproché de ne pas avoir prévenu les bénévoles assez tôt. Sur ce point, je pense qu'elle avait raison."},{"q":"O que ela pediu para evitar mal-entendidos?","o":["Confirmação por escrito","Uma nova empresa","Cancelamento da instalação"],"a":0,"e":"Oui, mais l'organisatrice nous a demandé d'envoyer une confirmation écrite pour éviter toute nouvelle ambiguïté."}],"gaps":[{"s":"Elle a affirmé qu'elle ___ (être, imparfait) disponible.","a":["était"],"h":"Ela afirmou que estava disponível."},{"s":"Il a expliqué qu'il ___ (recevoir, plus-que-parfait) le fichier la veille.","a":["avait reçu"],"h":"Ele explicou que tinha recebido o arquivo na véspera."},{"s":"Elle a assuré qu'elle ___ (venir, conditionnel présent) le lendemain.","a":["viendrait"],"h":"Ela garantiu que viria no dia seguinte."},{"s":"Il nous a demandé ___ la réunion était confirmée.","a":["si"],"h":"Ele perguntou se a reunião estava confirmada."},{"s":"Elle leur a reproché ___ ne pas avoir répondu.","a":["de"],"h":"Ela os criticou por não terem respondido."},{"s":"Elle avait promis qu'elle ___ (avoir terminé, conditionnel passé) avant vendredi.","a":["aurait terminé"],"h":"Prometera que teria terminado antes de sexta."}],"order":[{"t":["Il","a","dit","qu'il","était","occupé."],"h":"Ele disse que estava ocupado."},{"t":["Il","voulait","savoir","ce","que","nous","avions","décidé."],"h":"Ele queria saber o que decidimos."},{"t":["Il","a","expliqué","qu'il","terminerait","cette","semaine-là."],"h":"Ele explicou que terminaria naquela semana."}],"dict":[{"t":"Pourtant, mardi, elle nous avait assuré que nous pouvions avancer. Tu lui as rappelé ce qu'elle avait écrit dans son message ?"},{"t":"Il a expliqué qu'il n'avait ouvert le fichier que le lendemain de notre envoi. Il a reconnu qu'il aurait dû le vérifier plus tôt."},{"t":"Je lui avais pourtant confirmé que les messages étaient partis la veille. Je ne comprends pas d'où vient cette confusion."},{"t":"Elle a assuré qu'elle serait libre le lendemain et que l'équipe technique pourrait commencer l'installation à huit heures."},{"t":"Ajoute aussi qu'elle nous avait demandé de réduire les pauses. C'est cette consigne qui a entraîné le changement d'horaires."}],"shadow":["Pourtant, mardi, elle nous avait assuré que nous pouvions avancer. Tu lui as rappelé ce qu'elle avait écrit dans son message ?","Au moins, il a reconnu son erreur. L'organisatrice t'a demandé pourquoi les horaires avaient changé ?","Elle a assuré qu'elle serait libre le lendemain et que l'équipe technique pourrait commencer l'installation à huit heures.","D'accord. Je vais distinguer ce qu'elle a confirmé de ce que nous avons simplement supposé. Ce sera plus clair pour tout le monde."],"write":{"task":"Relate seis falas e perguntas de uma reunião passada usando discurso indireto e diferentes verbos introdutórios.","ph":"Hier, pendant la réunion, mon collègue a affirmé que …"},"cards":[["Ele disse que estava ocupado.","Il a dit qu'il était occupé."],["Ela afirmou que já tinha enviado tudo.","Elle a affirmé qu'elle avait déjà tout envoyé."],["Ele garantiu que voltaria no dia seguinte.","Il a assuré qu'il reviendrait le lendemain."],["Ela perguntou se eu estava disponível.","Elle m'a demandé si j'étais disponible."],["Ele queria saber o que decidimos.","Il voulait savoir ce que nous avions décidé."],["Ela alegou que não recebeu nada.","Elle a prétendu qu'elle n'avait rien reçu."],["Ele me criticou por ter chegado tarde.","Il m'a reproché d'être arrivé en retard."],["Ela pediu que confirmássemos por escrito.","Elle nous a demandé de confirmer par écrit."],["Ele explicou que terminaria naquela semana.","Il a expliqué qu'il terminerait cette semaine-là."],["Ela reconheceu que tinha cometido um erro.","Elle a reconnu qu'elle avait commis une erreur."]]},{"title":"Ayant terminé...","goal":"Descrever simultaneidade, causa e anterioridade usando participe présent, gérondif e participe composé.","speakers":{"Inès":"f","Antoine":"m"},"setting":"Inès e Antoine avaliam um percurso cultural a pé e os textos de um guia digital.","lines":[["Inès","Ayant testé le parcours hier après-midi, j'ai repéré plusieurs passages qui risquent de poser problème aux visiteurs.","Depois de testar o trajeto ontem, identifiquei trechos problemáticos."],["Antoine","Lesquels ? En suivant le plan actuel, j'avais trouvé l'itinéraire assez simple lors de notre première visite.","Quais? Seguindo o mapa, achei o itinerário simples na primeira visita."],["Inès","En traversant la place principale, on arrive devant deux rues presque identiques. Sans indication, il est facile de se tromper.","Ao atravessar a praça, chegamos a duas ruas parecidas. É fácil se confundir."],["Antoine","Connaissant bien le quartier, je n'avais même pas remarqué cette difficulté. C'est justement pour ça qu'il faut tester le guide.","Como conheço o bairro, nem percebi a dificuldade. Por isso devemos testar o guia."],["Inès","J'ai aussi observé plusieurs personnes consultant leur téléphone tout en marchant. Certaines ne regardaient presque pas les panneaux.","Observei pessoas olhando o celular enquanto andavam. Algumas nem viam as placas."],["Antoine","On pourrait ajouter des indications audio. En écoutant les consignes, les visiteurs pourraient garder les yeux sur leur environnement.","Poderíamos acrescentar áudio. Ouvindo as instruções, poderiam prestar atenção ao entorno."],["Inès","Bonne idée. Ayant déjà enregistré quelques descriptions, je peux préparer un premier exemple pour lundi.","Boa ideia. Como já gravei descrições, posso preparar um exemplo para segunda."],["Antoine","Il faudra également vérifier la durée. En prenant le chemin par le jardin, on gagne dix minutes, mais on évite plusieurs bâtiments intéressants.","Precisamos conferir a duração. Pelo jardim economizamos dez minutos, mas perdemos prédios interessantes."],["Inès","Tout en privilégiant un itinéraire court, je voudrais conserver les étapes qui racontent vraiment l'histoire du quartier.","Mesmo priorizando trajeto curto, quero manter paradas históricas."],["Antoine","Ayant comparé les deux versions, je préfère celle qui longe la rivière. Elle est plus agréable, même si elle prend un peu plus de temps.","Depois de comparar, prefiro a versão junto ao rio. É mais agradável, embora demore mais."],["Inès","Et concernant l'accessibilité ? En montant les marches près du musée, j'ai constaté qu'il n'y avait aucune indication d'un accès alternatif.","E a acessibilidade? Subindo as escadas, notei falta de informação sobre acesso alternativo."],["Antoine","Étant arrivé en avance ce matin, j'ai appelé le musée. Une employée m'a confirmé qu'une rampe se trouvait à l'arrière du bâtiment.","Como cheguei cedo, liguei para o museu. Confirmaram uma rampa nos fundos."],["Inès","Parfait. Sachant que certains visiteurs auront besoin de cet accès, il faudrait l'indiquer dès le début du parcours.","Perfeito. Sabendo que alguns precisarão, devemos indicar desde o início."],["Antoine","D'accord. Je vais revoir les descriptions en évitant les phrases trop longues. Les informations seront plus faciles à comprendre.","Certo. Vou revisar descrições evitando frases longas. Será mais fácil compreender."],["Inès","Ayant terminé mes notes, je vais rédiger une synthèse cet après-midi. Tu pourras ensuite vérifier les changements proposés.","Terminadas as notas, vou redigir um resumo à tarde. Depois você confere as mudanças."],["Antoine","Parfait. En travaillant ainsi, on devrait publier un guide plus clair, tout en conservant ce qui rend le parcours intéressant.","Perfeito. Assim publicaremos um guia mais claro, preservando o interessante."]],"grammar":[{"h":"Participe présent: formação","p":["Geralmente usa a base da forma nous no presente menos -ons, mais -ant. Irregulares: ayant, étant e sachant. É invariável como verbo."],"ex":[["Les visiteurs consultant le plan attendent.","Os visitantes que consultam o mapa esperam."],["Connaissant le quartier, elle a proposé un raccourci.","Como conhece o bairro, propôs atalho."],["Sachant que la route était fermée, nous avons changé.","Sabendo que a estrada estava fechada, mudamos."]],"tip":"Atenção ao sujeito de cada ação."},{"h":"Gérondif: en + participe présent","p":["<b>En + participe présent</b> expressa simultaneidade, maneira ou meio, geralmente com o mesmo sujeito da oração principal. Tout en reforça simultaneidade ou contraste."],"ex":[["En suivant les panneaux, vous trouverez le musée.","Seguindo placas, encontrarão o museu."],["Elle apprend en discutant.","Aprende conversando."],["Il travaille tout en écoutant de la musique.","Trabalha ouvindo música."]],"tip":"O sujeito de en marchant deve ser quem caminha."},{"h":"Participe présent causal","p":["Sem en, pode resumir uma oração causal e é mais frequente em registro escrito. Use parce que quando a construção puder gerar ambiguidade."],"ex":[["Connaissant les risques, nous avons modifié le parcours.","Conhecendo os riscos, mudamos o percurso."],["Étant disponible vendredi, je participerai.","Estando disponível sexta, participarei."],["Ne sachant pas répondre, il a demandé conseil.","Sem saber responder, pediu orientação."]],"tip":"A clareza é mais importante que a concisão."},{"h":"Participe composé","p":["<b>Ayant</b> ou <b>étant</b> seguido de particípio passado indica anterioridade; com être, concorde com o sujeito."],"ex":[["Ayant terminé son rapport, elle est rentrée.","Após terminar o relatório, voltou."],["Étant arrivés en avance, nous avons attendu.","Tendo chegado cedo, esperamos."],["Ayant reçu les commentaires, j'ai corrigé.","Após receber comentários, corrigi."]],"tip":"Ayant terminé indica ação já concluída."}],"vocab":[{"h":"Percursos e orientação","items":[["un itinéraire","um itinerário"],["un parcours","um percurso"],["un raccourci","um atalho"],["un passage","um trecho"],["une indication","uma orientação"],["un panneau","uma placa"],["une rampe","uma rampa"],["longer une rivière","acompanhar um rio"]]},{"h":"Avaliação e guia","items":[["repérer","identificar"],["constater","constatar"],["remarquer","perceber"],["comparer","comparar"],["privilégier","priorizar"],["conserver","preservar"],["une synthèse","um resumo"],["un accès alternatif","um acesso alternativo"]]}],"pron":[{"h":"terminação -ant","p":"O grupo -ant tem vogal nasal, aproximadamente “ã”, e o t final é mudo.","w":["parlant","travaillant","observant"]},{"h":"ayant e étant","p":"Ayant soa aproximadamente “è-iã”; étant soa “é-tã”, com final nasal.","w":["ayant terminé","étant arrivé","ayant reçu"]}],"mc":[{"q":"Que dificuldade Inès identificou na praça?","o":["Duas ruas muito parecidas","Ausência de transporte","Museu fechado para sempre"],"a":0,"e":"En traversant la place principale, on arrive devant deux rues presque identiques. Sans indication, il est facile de se tromper."},{"q":"Por que Antoine sugere instruções em áudio?","o":["Eliminar todas as placas","Dispensar mapas completamente","Permitir que visitantes observem o entorno"],"a":2,"e":"On pourrait ajouter des indications audio. En écoutant les consignes, les visiteurs pourraient garder les yeux sur leur environnement."},{"q":"O que Antoine descobriu ao ligar ao museu?","o":["Entrada principal fechada","Uma rampa nos fundos","Abertura somente no mês seguinte"],"a":1,"e":"Étant arrivé en avance ce matin, j'ai appelé le musée. Une employée m'a confirmé qu'une rampe se trouvait à l'arrière du bâtiment."},{"q":"O que Inès fará depois de terminar suas notas?","o":["Redigir um resumo à tarde","Cancelar o projeto","Recomeçar o guia inteiro"],"a":0,"e":"Ayant terminé mes notes, je vais rédiger une synthèse cet après-midi. Tu pourras ensuite vérifier les changements proposés."}],"gaps":[{"s":"En ___ (suivre, participe présent) les panneaux, vous trouverez le musée.","a":["suivant"],"h":"Seguindo as placas, encontrarão o museu."},{"s":"___ (connaître, participe présent) bien le quartier, Lucas a proposé un raccourci.","a":["Connaissant"],"h":"Como conhece o bairro, Lucas propôs um atalho."},{"s":"___ (terminer, participe composé) son rapport, elle a quitté le bureau.","a":["Ayant terminé"],"h":"Depois de terminar o relatório, ela saiu."},{"s":"___ (arriver, participe composé) en avance, Inès a préparé la salle.","a":["Étant arrivée"],"h":"Como chegou adiantada, Inès preparou a sala."},{"s":"Tout en ___ (discuter, gérondif) du projet, ils prennent des notes.","a":["discutant"],"h":"Enquanto discutem o projeto, fazem anotações."},{"s":"___ (savoir, participe présent) que le passage était fermé, Antoine a changé de trajet.","a":["Sachant"],"h":"Sabendo da passagem fechada, Antoine mudou o trajeto."}],"order":[{"t":["En","suivant","ce","chemin,","tu","arriveras","plus","vite."],"h":"Seguindo esse caminho, chegará mais rápido."},{"t":["Connaissant","le","problème,","j'ai","proposé","une","solution."],"h":"Conhecendo o problema, propus uma solução."},{"t":["Ayant","terminé,","je","suis","parti."],"h":"Depois de terminar, fui embora."}],"dict":[{"t":"Lesquels ? En suivant le plan actuel, j'avais trouvé l'itinéraire assez simple lors de notre première visite."},{"t":"J'ai aussi observé plusieurs personnes consultant leur téléphone tout en marchant. Certaines ne regardaient presque pas les panneaux."},{"t":"Il faudra également vérifier la durée. En prenant le chemin par le jardin, on gagne dix minutes, mais on évite plusieurs bâtiments intéressants."},{"t":"Et concernant l'accessibilité ? En montant les marches près du musée, j'ai constaté qu'il n'y avait aucune indication d'un accès alternatif."},{"t":"Ayant terminé mes notes, je vais rédiger une synthèse cet après-midi. Tu pourras ensuite vérifier les changements proposés."}],"shadow":["Lesquels ? En suivant le plan actuel, j'avais trouvé l'itinéraire assez simple lors de notre première visite.","On pourrait ajouter des indications audio. En écoutant les consignes, les visiteurs pourraient garder les yeux sur leur environnement.","Et concernant l'accessibilité ? En montant les marches près du musée, j'ai constaté qu'il n'y avait aucune indication d'un accès alternatif.","Parfait. En travaillant ainsi, on devrait publier un guide plus clair, tout en conservant ce qui rend le parcours intéressant."],"write":{"task":"Descreva uma tarefa recente em seis frases usando gerúndio, particípio presente e composto.","ph":"Ayant terminé …, j'ai décidé de … . En travaillant …"},"cards":[["Seguindo esse caminho, chegará mais rápido.","En suivant ce chemin, tu arriveras plus vite."],["Conhecendo o problema, propus uma solução.","Connaissant le problème, j'ai proposé une solution."],["Depois de terminar, fui embora.","Ayant terminé, je suis parti."],["Ela aprende praticando todos os dias.","Elle apprend en pratiquant tous les jours."],["Como sabia da mudança, avisei a equipe.","Sachant qu'il y avait un changement, j'ai prévenu l'équipe."],["Ele trabalha ouvindo música.","Il travaille tout en écoutant de la musique."],["Depois de receber a resposta, liguei.","Ayant reçu la réponse, j'ai appelé."],["Como chegou cedo, ela ajudou.","Étant arrivée tôt, elle a pu aider."],["Evitando o horário de pico, você ganha tempo.","En évitant les heures de pointe, tu gagnes du temps."],["Não sabendo o que dizer, fiquei em silêncio.","Ne sachant pas quoi dire, je suis resté silencieux."]]},{"title":"Pour que tout soit prêt","goal":"Explicar finalidade, causa e consequência com pour que, afin que, de peur que, étant donné que, si bien que e tellement... que.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Claire e Lucas organizam os preparativos de um fórum de carreiras em Tours.","lines":[["Claire","Les inscriptions au forum ont tellement augmenté que nous avons dû ouvrir une deuxième salle. On attend maintenant près de deux cents personnes.","As inscrições aumentaram tanto que abrimos uma segunda sala. Esperamos quase duzentas pessoas."],["Lucas","C'est une bonne nouvelle, mais l'accueil risque d'être compliqué. J'ai avancé l'ouverture des portes pour que les visiteurs puissent s'installer tranquillement.","É bom, mas a recepção será complicada. Antecipei a abertura para que as pessoas se acomodem."],["Claire","Très bien. Étant donné que beaucoup viennent en train, j'ai ajouté un plan depuis la gare dans le message de confirmation.","Como muitos vêm de trem, incluí um mapa a partir da estação na confirmação."],["Lucas","Il faudrait aussi installer des panneaux à chaque étage afin que personne ne se trompe de salle pendant les conférences.","Precisamos pôr placas por andar para que ninguém erre a sala."],["Claire","J'ai préparé des indications supplémentaires de peur que certains participants ne trouvent pas l'entrée secondaire.","Preparei orientações adicionais por receio de que não encontrem a entrada secundária."],["Lucas","Bonne précaution. Les bénévoles se sont réparti les tâches hier, si bien que chacun sait déjà de quel espace il sera responsable.","Boa precaução. Os voluntários dividiram tarefas, de modo que todos sabem suas responsabilidades."],["Claire","En revanche, nous avons reçu tellement de questions sur les formations à distance qu'il faudrait prolonger cette conférence.","Recebemos tantas perguntas sobre formação remota que deveríamos prolongar a palestra."],["Lucas","D'accord, mais il faudra raccourcir la pause pour que les autres interventions commencent à l'heure.","Certo, mas encurtaremos o intervalo para que as próximas falas comecem no horário."],["Claire","Étant donné que les participants auront des profils très différents, je préférerais qu'on évite les explications trop techniques.","Como os participantes têm perfis distintos, prefiro evitar explicações técnicas demais."],["Lucas","Je vais prévenir les intervenants afin qu'ils préparent des exemples concrets et qu'ils réservent du temps aux questions.","Vou avisar os palestrantes para que preparem exemplos e reservem tempo para perguntas."],["Claire","Il faudrait aussi prévoir des documents numériques. Nous avons imprimé beaucoup de brochures, mais certaines personnes préfèrent les consulter sur leur téléphone.","Precisamos de documentos digitais. Imprimimos folhetos, mas alguns preferem consultar pelo celular."],["Lucas","J'ai créé une page avec les ressources, si bien que les visiteurs pourront retrouver les liens après l'événement.","Criei uma página com materiais, então poderão encontrar os links depois."],["Claire","Parfait. Je vais vérifier les formulaires d'inscription de peur qu'une erreur ne bloque l'arrivée des personnes inscrites à la dernière minute.","Vou conferir formulários por receio de que um erro impeça inscritos de entrar."],["Lucas","Tu as raison. Le formulaire avait été tellement utilisé hier soir que le serveur avait ralenti pendant quelques minutes.","Verdade. O formulário foi tão usado que o servidor ficou lento."],["Claire","Heureusement, l'équipe technique a corrigé le problème. Pour que tout soit prêt demain, nous devons terminer les derniers tests cet après-midi.","Felizmente corrigiram. Para tudo ficar pronto amanhã, precisamos terminar os testes hoje."],["Lucas","Alors, répartissons les dernières vérifications. Si chacun s'occupe de sa partie, on devrait pouvoir accueillir tout le monde dans de bonnes conditions.","Então dividamos as conferências. Se cada um fizer sua parte, receberemos todos bem."]],"grammar":[{"h":"Pour que e afin que","p":["Essas expressões apresentam um objetivo e pedem <b>subjonctif</b>. Afin que costuma ser um pouco mais formal."],"ex":[["J'ai ajouté un plan pour que vous trouviez le bâtiment.","Acrescentei mapa para encontrarem o prédio."],["Nous expliquerons les règles afin que chacun comprenne.","Explicaremos para todos compreenderem."],["Elle parle lentement pour que tout le monde puisse suivre.","Ela fala devagar para todos acompanharem."]],"tip":"Para sujeitos iguais, use pour + infinitif."},{"h":"De peur que","p":["Marca a tentativa de evitar resultado indesejado e pede subjonctif. O ne explétif pode aparecer sem valor negativo."],"ex":[["J'ai envoyé un rappel de peur qu'ils oublient.","Enviei lembrete por receio de esquecimento."],["Elle a gardé une copie de peur que le fichier disparaisse.","Guardou cópia com medo de perder o arquivo."],["Je vérifie pour éviter les erreurs.","Confiro para evitar erros."]],"tip":"Contraste finalidade desejada com risco evitado."},{"h":"Étant donné que","p":["Apresenta uma causa considerada estabelecida e utiliza indicatif. É mais formal que parce que. Puisque também introduz uma causa conhecida."],"ex":[["Étant donné que la salle est petite, limitons les inscriptions.","Como a sala é pequena, limitemos inscrições."],["Puisque tout le monde est là, commençons.","Já que todos estão aqui, comecemos."],["La réunion a été reportée parce que le responsable était absent.","Foi adiada porque ele faltou."]],"tip":"Indique a causa real, não um objetivo."},{"h":"Si bien que, tellement... que","p":["Si bien que indica consequência; tellement... que enfatiza intensidade e resultado. Em consequências reais, normalmente usam indicatif."],"ex":[["Les inscriptions ont augmenté, si bien que nous avons ouvert une salle.","Aumentaram, então abrimos uma sala."],["Il y avait tellement de monde que nous avons attendu.","Havia tanta gente que esperamos."],["Le programme était tellement chargé que la pause a été raccourcie.","Era tão cheio que encurtamos a pausa."]],"tip":"Pour que é objetivo; si bien que é resultado."}],"vocab":[{"h":"Eventos e organização","items":[["un forum","um fórum"],["un intervenant","um palestrante"],["une conférence","uma palestra"],["un participant","um participante"],["une inscription","uma inscrição"],["un bénévole","um voluntário"],["une brochure","um folheto"],["un formulaire","um formulário"]]},{"h":"Explicações e resultados","items":[["pour que","para que"],["afin que","a fim de que"],["de peur que","por receio de que"],["étant donné que","considerando que"],["puisque","já que"],["si bien que","de modo que"],["tellement de","tanto ou tanta"],["entraîner","provocar"]]}],"pron":[{"h":"pour que e afin que","p":"Em pour, ou tem som de u; afin termina com vogal nasal, aproximadamente “a-fã”.","w":["pour que","afin que","afin que chacun comprenne"]},{"h":"tellement","p":"A terminação -ment tem vogal nasal, aproximadamente “mã”.","w":["tellement","tellement de monde","tellement compliqué"]}],"mc":[{"q":"Por que foi preciso abrir uma segunda sala?","o":["A primeira está em obras","As inscrições aumentaram muito","Os palestrantes pediram salas individuais"],"a":1,"e":"Les inscriptions au forum ont tellement augmenté que nous avons dû ouvrir une deuxième salle. On attend maintenant près de deux cents personnes."},{"q":"Por que Claire incluiu um mapa da estação?","o":["Muitos participantes virão de trem","O evento mudou de cidade","A estação está fechada"],"a":0,"e":"Très bien. Étant donné que beaucoup viennent en train, j'ai ajouté un plan depuis la gare dans le message de confirmation."},{"q":"Por que pretendem prolongar a palestra sobre ensino a distância?","o":["O palestrante se atrasará","Foi cancelada","Receberam muitas perguntas"],"a":2,"e":"En revanche, nous avons reçu tellement de questions sur les formations à distance qu'il faudrait prolonger cette conférence."},{"q":"Qual problema técnico ocorreu?","o":["Arquivos apagados","O servidor ficou lento","O site ficou fora do ar o dia inteiro"],"a":1,"e":"Tu as raison. Le formulaire avait été tellement utilisé hier soir que le serveur avait ralenti pendant quelques minutes."}],"gaps":[{"s":"Nous avons installé des panneaux afin que les visiteurs ___ (trouver, subjonctif) les salles.","a":["trouvent"],"h":"Instalamos placas para que encontrem as salas."},{"s":"___ donné que le hall est petit, nous limiterons les inscriptions.","a":["Étant"],"h":"Como o saguão é pequeno, limitaremos as inscrições."},{"s":"Nous avons reçu tellement ___ questions que nous avons prolongé la conférence.","a":["de"],"h":"Recebemos tantas perguntas que prolongamos a palestra."},{"s":"Les bénévoles se sont organisés, si bien ___ l'accueil sera plus rapide.","a":["que"],"h":"Os voluntários se organizaram, então a recepção será mais rápida."},{"s":"J'ai envoyé un rappel de peur que les participants ___ (oublier, subjonctif) l'horaire.","a":["oublient"],"h":"Enviei lembrete por receio de esquecimento do horário."},{"s":"Nous avons préparé une entrée pour ___ (éviter, infinitif) les files d'attente.","a":["éviter"],"h":"Preparamos uma entrada para evitar filas."}],"order":[{"t":["Elle","a","tout","expliqué","pour","éviter","les","malentendus."],"h":"Ela explicou tudo para evitar confusões."},{"t":["Étant","donné","qu'il","pleut,","nous","resterons","ici."],"h":"Como chove, ficaremos aqui."},{"t":["Il","était","tellement","fatigué","qu'il","est","parti","tôt."],"h":"Ele estava tão cansado que saiu cedo."}],"dict":[{"t":"Nous avons avancé l'ouverture des portes pour que les visiteurs puissent entrer tranquillement."},{"t":"Étant donné que beaucoup de participants viennent en train, nous avons ajouté un plan."},{"t":"Il faudrait installer des panneaux afin que personne ne se trompe de salle."},{"t":"Les inscriptions ont tellement augmenté que nous avons dû ouvrir une deuxième salle."},{"t":"J'ai envoyé un rappel de peur que les participants oublient l'heure de leur conférence."}],"shadow":["C'est une bonne nouvelle, mais l'accueil risque d'être compliqué. J'ai avancé l'ouverture des portes pour que les visiteurs puissent s'installer tranquillement.","Bonne précaution. Les bénévoles se sont réparti les tâches hier, si bien que chacun sait déjà de quel espace il sera responsable.","Il faudrait aussi prévoir des documents numériques. Nous avons imprimé beaucoup de brochures, mais certaines personnes préfèrent les consulter sur leur téléphone.","Alors, répartissons les dernières vérifications. Si chacun s'occupe de sa partie, on devrait pouvoir accueillir tout le monde dans de bonnes conditions."],"write":{"task":"Escreva seis frases explicando objetivos, causas e consequências de um projeto usando conectores diferentes.","ph":"Nous avons organisé … pour que tout le monde puisse …"},"cards":[["Falo devagar para que todos entendam.","Je parle lentement pour que tout le monde comprenne."],["Enviamos um mapa para que encontre o local.","Nous avons envoyé un plan pour que tu trouves le lieu."],["Como chove, ficaremos aqui.","Étant donné qu'il pleut, nous resterons ici."],["Havia tanta gente que esperamos.","Il y avait tellement de monde que nous avons dû attendre."],["Ela explicou tudo para evitar confusões.","Elle a tout expliqué pour éviter les malentendus."],["Preparamos cópia por receio de perder o arquivo.","Nous avons préparé une copie de peur de perdre le fichier."],["Ele estava tão cansado que saiu cedo.","Il était tellement fatigué qu'il est parti tôt."],["O evento foi adiado, então mudamos planos.","L'événement a été reporté, si bien que nous avons changé nos plans."],["Já que todos chegaram, podemos começar.","Puisque tout le monde est arrivé, nous pouvons commencer."],["Vou confirmar para que não se atrase.","Je vais confirmer l'horaire pour que tu ne sois pas en retard."]]},{"title":"Alors que, tandis que, même si","goal":"Expressar oposição, simultaneidade e concessão usando alors que, tandis que, même si, quoique e avoir beau.","speakers":{"Claire":"f","Antoine":"m"},"setting":"Claire e Antoine discutem a organização de uma festa de bairro em Strasbourg.","lines":[["Claire","On doit décider aujourd'hui si on ferme la rue pendant la fête. Alors que les habitants veulent plus d'espace, les commerçants craignent de perdre des clients.","Temos que decidir sobre o fechamento da rua. Moradores querem espaço, comerciantes temem perder clientes."],["Antoine","Je les comprends. Pourtant, tandis que certains magasins dépendent des livraisons, les cafés profiteraient d'une rue piétonne.","Entendo. Enquanto lojas dependem das entregas, cafés se beneficiariam de rua de pedestres."],["Claire","Même si la rue est fermée samedi, les livreurs pourront accéder aux commerces avant huit heures.","Mesmo se fecharmos sábado, as entregas poderão chegar antes das oito."],["Antoine","J'ai beau expliquer cet horaire aux responsables, certains restent persuadés qu'ils seront bloqués toute la journée.","Por mais que explique, alguns acham que ficarão bloqueados o dia inteiro."],["Claire","Quoique la proposition soit assez souple, elle ne convaincra pas tout le monde. On devrait rencontrer les commerçants individuellement.","Embora flexível, não convencerá todos. Devemos conversar individualmente."],["Antoine","Alors que le marché attire beaucoup de visiteurs, la petite place voisine reste presque vide. On pourrait mieux utiliser cet espace.","Enquanto o mercado atrai gente, a praça vizinha fica vazia. Poderíamos aproveitá-la."],["Claire","On pourrait y installer les stands d'information, tandis que les concerts auraient lieu près de la mairie.","Poderíamos colocar estandes lá, enquanto os shows seriam perto da prefeitura."],["Antoine","Oui, mais même si les concerts finissent tôt, le bruit risque de gêner les voisins qui habitent au-dessus des commerces.","Sim, mas mesmo terminando cedo, o barulho pode incomodar moradores."],["Claire","On a beau réduire le volume, les basses traversent les murs. Je proposerais une scène orientée vers le parc.","Por mais que baixemos o volume, graves atravessam paredes. Eu viraria o palco para o parque."],["Antoine","Ça me semble raisonnable. Quoiqu'on dispose d'un budget limité, on pourrait louer quelques panneaux acoustiques.","Parece razoável. Embora o orçamento seja limitado, poderíamos alugar painéis acústicos."],["Claire","Il faudrait surtout prévenir les riverains. Tandis que les bénévoles s'occuperont de l'affichage, je contacterai les immeubles concernés.","Precisamos avisar moradores. Enquanto voluntários cuidam dos cartazes, contatarei os prédios."],["Antoine","Et la pluie ? Même s'il pleut, on pourra maintenir les stands couverts. En revanche, les ateliers en plein air seront plus compliqués.","E a chuva? Mesmo chovendo, manteremos estandes cobertos, mas oficinas externas ficam difíceis."],["Claire","J'ai beau consulter les prévisions, elles changent sans arrêt. Prévoyons donc une salle de repli.","Por mais que consulte a previsão, ela muda sempre. Vamos reservar sala alternativa."],["Antoine","Quoique ce soit compliqué de tout prévoir, il vaut mieux disposer de deux solutions que d'improviser au dernier moment.","Embora seja difícil prever tudo, melhor ter duas soluções que improvisar."],["Claire","D'accord. Je présenterai les avantages et les contraintes, pendant que tu recueilleras les remarques des commerçants.","Certo. Apresentarei vantagens e limitações enquanto você recolhe opiniões dos comerciantes."],["Antoine","Parfait. Même si nous ne sommes pas tous d'accord, nous pourrons prendre une décision à partir d'informations claires.","Mesmo sem unanimidade, poderemos decidir com base em informações claras."]],"grammar":[{"h":"Alors que e tandis que","p":["Esses conectores seguidos de indicatif podem expressar contraste ou simultaneidade conforme o contexto."],"ex":[["Elle préfère travailler seule, alors que je préfère l'équipe.","Ela prefere sozinha, eu equipe."],["Certains veulent partir, tandis que d'autres restent.","Alguns querem ir, outros ficar."],["Il cuisinait tandis que je mettais la table.","Ele cozinhava enquanto eu arrumava a mesa."]],"tip":"Observe se as ações são contrastantes ou simultâneas."},{"h":"Même si + indicatif","p":["Mesmo se ou mesmo que introduz condição que não muda o resultado e pede <b>indicatif</b>."],"ex":[["Même s'il pleut, nous sortirons.","Mesmo que chova, sairemos."],["Même si tu n'es pas d'accord, écoute.","Mesmo que discorde, escute."],["Même si nous avons peu de temps, essayons.","Mesmo com pouco tempo, tentemos."]],"tip":"Diferente de bien que + subjonctif."},{"h":"Quoique + subjonctif","p":["Equivale a embora e normalmente usa subjonctif, com elisão em quoiqu'il e quoiqu'on. Não confunda com quoi que (seja o que for que)."],"ex":[["Quoique ce soit coûteux, étudions le projet.","Embora caro, vamos analisar."],["Quoiqu'elle soit fatiguée, elle continue.","Embora cansada, ela continua."],["Quoique nous ayons peu de moyens, avançons.","Embora com poucos recursos, avancemos."]],"tip":"Quoique é uma única palavra."},{"h":"Avoir beau + infinitif","p":["Marca esforços que não atingem o resultado desejado. Conjugue avoir e deixe o outro verbo no infinitivo."],"ex":[["J'ai beau expliquer, personne ne comprend.","Por mais que explique, ninguém entende."],["Nous avons beau chercher, nous ne trouvons rien.","Por mais que busquemos, nada encontramos."],["Elle avait beau insister, il refusait.","Por mais que insistisse, ele recusava."]],"tip":"Normalmente há uma contradição entre esforço e resultado."}],"vocab":[{"h":"Bairro e eventos","items":[["une rue piétonne","uma rua de pedestres"],["un commerçant","um comerciante"],["un riverain","um morador próximo"],["une livraison","uma entrega"],["un stand","um estande"],["un panneau acoustique","um painel acústico"],["une salle de repli","uma sala alternativa"],["un bénévole","um voluntário"]]},{"h":"Concessão e negociação","items":[["alors que","enquanto"],["tandis que","enquanto"],["même si","mesmo que"],["quoique","embora"],["avoir beau","por mais que"],["pourtant","no entanto"],["en revanche","em contrapartida"],["un compromis","um compromisso negociado"]]}],"pron":[{"h":"quoique","p":"Quoique e quoi que soam praticamente igual, aproximadamente “kuá-ke”.","w":["quoique","quoi que","quoiqu'il soit"]},{"h":"j'ai beau","p":"Beau é pronunciado como “bô”, sem pronunciar separadamente as três letras da vogal.","w":["j'ai beau","nous avons beau","il avait beau essayer"]}],"mc":[{"q":"Qual é o conflito sobre o fechamento da rua?","o":["Os moradores querem cancelar a festa","Os comerciantes querem ingressos pagos","Moradores querem espaço e comerciantes temem perder clientes"],"a":2,"e":"On doit décider aujourd'hui si on ferme la rue pendant la fête. Alors que les habitants veulent plus d'espace, les commerçants craignent de perdre des clients."},{"q":"Até que horas são possíveis as entregas?","o":["Antes das oito","Até meio-dia","Durante toda a tarde"],"a":0,"e":"Même si la rue est fermée samedi, les livreurs pourront accéder aux commerces avant huit heures."},{"q":"Por que Claire sugere virar o palco para o parque?","o":["Os cafés estarão fechados","O som grave atravessa as paredes","O parque terá mais comerciantes"],"a":1,"e":"On a beau réduire le volume, les basses traversent les murs. Je proposerais une scène orientée vers le parc."},{"q":"O que Claire sugere por causa da previsão do tempo?","o":["Cancelar todos os shows","Adiar a festa um mês","Reservar uma sala alternativa"],"a":2,"e":"J'ai beau consulter les prévisions, elles changent sans arrêt. Prévoyons donc une salle de repli."}],"gaps":[{"s":"___ que les habitants souhaitent le calme, les commerces veulent rester ouverts.","a":["Alors"],"h":"Enquanto os moradores querem silêncio, as lojas querem abrir."},{"s":"Même s'il ___ (pleuvoir, indicatif présent), la fête aura lieu.","a":["pleut"],"h":"Mesmo que chova, haverá festa."},{"s":"Quoique la proposition ___ (être, subjonctif) raisonnable, elle ne plaît pas à tous.","a":["soit"],"h":"Embora razoável, nem todos gostam."},{"s":"J'___ (avoir, présent) beau répéter les règles, personne ne les respecte.","a":["ai"],"h":"Por mais que repita as regras, ninguém respeita."},{"s":"Les enfants jouent tandis que leurs parents ___ (discuter, indicatif).","a":["discutent"],"h":"Crianças brincam enquanto pais conversam."},{"s":"Nous avons beau ___ (chercher, infinitif), nous ne trouvons rien.","a":["chercher"],"h":"Por mais que procuremos, nada achamos."}],"order":[{"t":["Alors","qu'il","préfère","rester,","je","veux","sortir."],"h":"Enquanto ele fica, eu quero sair."},{"t":["Il","cuisine","tandis","que","je","travaille."],"h":"Ele cozinha enquanto trabalho."},{"t":["Même","si","c'est","cher,","ça","vaut","la","peine."],"h":"Mesmo que seja caro, vale a pena."}],"dict":[{"t":"Je les comprends. Pourtant, tandis que certains magasins dépendent des livraisons, les cafés profiteraient d'une rue piétonne."},{"t":"Quoique la proposition soit assez souple, elle ne convaincra pas tout le monde. On devrait rencontrer les commerçants individuellement."},{"t":"Oui, mais même si les concerts finissent tôt, le bruit risque de gêner les voisins qui habitent au-dessus des commerces."},{"t":"Il faudrait surtout prévenir les riverains. Tandis que les bénévoles s'occuperont de l'affichage, je contacterai les immeubles concernés."},{"t":"D'accord. Je présenterai les avantages et les contraintes, pendant que tu recueilleras les remarques des commerçants."}],"shadow":["Je les comprends. Pourtant, tandis que certains magasins dépendent des livraisons, les cafés profiteraient d'une rue piétonne.","Alors que le marché attire beaucoup de visiteurs, la petite place voisine reste presque vide. On pourrait mieux utiliser cet espace.","Il faudrait surtout prévenir les riverains. Tandis que les bénévoles s'occuperont de l'affichage, je contacterai les immeubles concernés.","Parfait. Même si nous ne sommes pas tous d'accord, nous pourrons prendre une décision à partir d'informations claires."],"write":{"task":"Compare duas opções em seis frases usando alors que, tandis que, même si, quoique e avoir beau.","ph":"Alors que certaines personnes préfèrent …, d'autres …"},"cards":[["Enquanto ele fica, eu quero sair.","Alors qu'il préfère rester, je veux sortir."],["Mesmo que seja caro, vale a pena.","Même si c'est cher, ça vaut la peine."],["Embora cansada, ela continua.","Quoiqu'elle soit fatiguée, elle continue."],["Por mais que tente, não consigo.","J'ai beau essayer, je n'y arrive pas."],["Ele cozinha enquanto trabalho.","Il cuisine tandis que je travaille."],["Mesmo que discorde, vou explicar.","Même si tu n'es pas d'accord, je vais expliquer."],["Embora com pouco tempo, tentaremos.","Quoique nous ayons peu de temps, nous allons essayer."],["Por mais que procuremos, nada achamos.","Nous avons beau chercher, nous ne trouvons rien."],["Ela prefere trem, ele prefere carro.","Elle préfère le train, tandis qu'il préfère la voiture."],["Mesmo que chova amanhã, iremos.","Même s'il pleut demain, nous irons."]]},{"title":"Madame, Monsieur","goal":"Redigir correspondência formal, apresentar reclamações e pedidos educados e empregar nominalização.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Claire pede ajuda a Lucas para escrever uma reclamação sobre o cancelamento de uma sala em Toulouse.","lines":[["Claire","Je dois écrire au service des réservations. Ils ont annulé notre salle deux jours avant la conférence, sans nous proposer d'alternative.","Preciso escrever ao setor de reservas. Cancelaram nossa sala dois dias antes da conferência sem oferecer alternativa."],["Lucas","Dans ce cas, évite un ton agressif. Un courrier formel commence par « Madame, Monsieur, » et présente les faits clairement.","Evite tom agressivo. Carta formal começa com prezados senhores e descreve fatos claramente."],["Claire","Je peux écrire : « Je me permets de vous contacter au sujet de l'annulation de notre réservation du 12 novembre » ?","Posso escrever: tomo a liberdade de contatá-los sobre o cancelamento de 12 de novembro?"],["Lucas","Oui. Ajoute la référence du dossier et la date de confirmation, afin que le service retrouve facilement ta demande.","Sim. Acrescente referência e data para que localizem o pedido."],["Claire","Je voudrais expliquer que leur décision a perturbé toute notre organisation, mais sans paraître trop accusatrice.","Quero explicar que a decisão prejudicou a organização sem parecer acusatória."],["Lucas","Formule plutôt : « Cette annulation a entraîné une modification importante de notre programme. » C'est précis et professionnel.","Prefira: esse cancelamento provocou uma alteração importante do programa. É preciso e profissional."],["Claire","Ensuite, est-ce que je peux demander : « Nous exigeons une nouvelle salle immédiatement » ?","Posso pedir: exigimos uma nova sala imediatamente?"],["Lucas","Ce serait trop direct. Écris : « Nous souhaiterions savoir si une salle équivalente pourrait être mise à notre disposition. »","Seria direto demais. Escreva: gostaríamos de saber se uma sala equivalente poderia ser disponibilizada."],["Claire","J'hésite entre « à cause de » et « en raison de ». Le second convient mieux à un courrier officiel ?","Estou em dúvida entre por causa de e em razão de. A segunda é mais formal?"],["Lucas","Oui. Par exemple : « En raison de ce changement, plusieurs intervenants ont dû modifier leur déplacement. »","Sim. Em razão da mudança, vários palestrantes precisaram alterar o deslocamento."],["Claire","Je vais joindre la confirmation initiale et le message d'annulation. Comment annoncer les pièces jointes ?","Vou anexar a confirmação e o cancelamento. Como menciono os anexos?"],["Lucas","Tu peux écrire : « Vous trouverez en pièces jointes les documents relatifs à notre réservation. »","Pode escrever: os documentos relativos à reserva estão anexados."],["Claire","Et pour le délai : « Nous vous remercions de bien vouloir nous apporter une réponse d'ici vendredi » ?","E para o prazo: agradecemos se puderem responder até sexta?"],["Lucas","Très bien. Tu peux ajouter : « Je vous remercie par avance de l'attention portée à notre demande. »","Muito bem. Acrescente: agradeço antecipadamente a atenção à solicitação."],["Claire","Il me manque seulement la formule finale. Je trouve « Cordialement » un peu court pour cette première réclamation.","Só falta despedida. Acho cordialmente um pouco simples para essa reclamação."],["Lucas","Alors utilise : « Je vous prie d'agréer, Madame, Monsieur, l'expression de mes salutations distinguées. » Ce sera parfaitement adapté.","Use a fórmula tradicional de respeitosos cumprimentos. Será adequada."]],"grammar":[{"h":"Estrutura formal","p":["Um e-mail formal deve ter objeto, saudação, motivo, pedido e encerramento. Use vous, orações completas e tom respeitoso."],"ex":[["Objet : Demande de confirmation de réservation.","Assunto: pedido de confirmação de reserva."],["Madame, Monsieur, je vous contacte au sujet de notre demande.","Prezados senhores, entro em contato sobre nossa solicitação."],["Je vous remercie de votre réponse.","Agradeço sua resposta."]],"tip":"Uma mensagem clara identifica o pedido rapidamente."},{"h":"Conditionnel para pedidos","p":["<b>Je souhaiterais</b>, <b>nous voudrions</b> e <b>pourriez-vous</b> tornam pedidos menos impositivos."],"ex":[["Je souhaiterais obtenir des informations.","Gostaria de informações."],["Pourriez-vous confirmer la disponibilité ?","Poderiam confirmar disponibilidade?"],["Nous vous remercions de bien vouloir examiner notre demande.","Agradecemos a análise da solicitação."]],"tip":"Prefira je souhaiterais a je veux."},{"h":"Nominalisation","p":["Em registros profissionais, nominalização transforma verbos em substantivos: décider → décision, annuler → annulation, confirmer → confirmation."],"ex":[["L'annulation de notre réservation pose problème.","O cancelamento causa problema."],["Nous attendons la confirmation de votre décision.","Aguardamos confirmação da decisão."],["Cette modification a entraîné des frais.","A mudança gerou custos."]],"tip":"Use sem deixar o texto artificial."},{"h":"Conectores e despedida","p":["En raison de, à la suite de e concernant organizam argumentos. Mencione anexos e escolha despedida adequada ao grau de formalidade."],"ex":[["En raison de ce retard, nous avons changé le programme.","Por causa do atraso, mudamos o programa."],["Vous trouverez en pièce jointe la confirmation.","A confirmação está anexa."],["Dans l'attente de votre réponse, je vous remercie.","No aguardo da resposta, agradeço."]],"tip":"Cordialement é comum em e-mails; salutations distinguées é mais solene."}],"vocab":[{"h":"Correspondência formal","items":[["un objet","um assunto"],["un destinataire","um destinatário"],["une formule de politesse","uma fórmula de cortesia"],["une pièce jointe","um anexo"],["une référence de dossier","uma referência"],["une réclamation","uma reclamação"],["une demande","uma solicitação"],["un courrier","uma carta"]]},{"h":"Pedidos e nominalização","items":[["je me permets de","tomo a liberdade de"],["je souhaiterais","eu gostaria"],["pourriez-vous","poderia"],["bien vouloir","ter a gentileza de"],["une décision","uma decisão"],["une annulation","um cancelamento"],["une confirmation","uma confirmação"],["un remboursement","um reembolso"]]}],"pron":[{"h":"Madame, Monsieur","p":"Madame soa aproximadamente “ma-dam”, com e final mudo; Monsieur se aproxima de “me-siê”.","w":["Madame","Monsieur","Madame, Monsieur"]},{"h":"souhaiterais","p":"A terminação -ais tem som de e aberto; em souhait, ou soa como u brasileiro.","w":["je souhaiterais","nous souhaiterions","souhaiter une réponse"]}],"mc":[{"q":"Por que Claire escreve a reclamação?","o":["Uma cobrança duplicada","Falta de equipamentos de som","Cancelaram a sala sem alternativa"],"a":2,"e":"Je dois écrire au service des réservations. Ils ont annulé notre salle deux jours avant la conférence, sans nous proposer d'alternative."},{"q":"Que dados Lucas pede para identificar a reserva?","o":["Referência e data de confirmação","Endereços de palestrantes","Participação em eventos anteriores"],"a":0,"e":"Oui. Ajoute la référence du dossier et la date de confirmation, afin que le service retrouve facilement ta demande."},{"q":"Como Lucas sugere pedir outra sala?","o":["Ameaçando denunciar publicamente","Solicitando educadamente uma sala equivalente","Exigindo devolução de documentos"],"a":1,"e":"Ce serait trop direct. Écris : « Nous souhaiterions savoir si une salle équivalente pourrait être mise à notre disposition. »"},{"q":"Qual encerramento Lucas considera adequado?","o":["Uma saudação informal","Nenhum encerramento","Uma fórmula tradicional de cortesia"],"a":2,"e":"Alors utilise : « Je vous prie d'agréer, Madame, Monsieur, l'expression de mes salutations distinguées. » Ce sera parfaitement adapté."}],"gaps":[{"s":"Je me ___ (permettre, présent) de vous contacter concernant notre réservation.","a":["permets"],"h":"Entro em contato sobre nossa reserva."},{"s":"Nous ___ (souhaiter, conditionnel présent) obtenir une confirmation.","a":["souhaiterions"],"h":"Gostaríamos de uma confirmação."},{"s":"L'___ (annuler → nom) de notre réservation entraîne des difficultés.","a":["annulation"],"h":"O cancelamento provoca dificuldades."},{"s":"Pourriez-vous transmettre votre ___ (décider → nom) avant vendredi ?","a":["décision"],"h":"Poderiam transmitir sua decisão até sexta?"},{"s":"En ___ de ce changement, plusieurs participants ont modifié leurs billets.","a":["raison"],"h":"Em razão disso, participantes mudaram passagens."},{"s":"Vous trouverez en pièce ___ la confirmation.","a":["jointe"],"h":"A confirmação está anexa."}],"order":[{"t":["L'annulation","a","entraîné","des","difficultés."],"h":"O cancelamento causou dificuldades."},{"t":["Nous","souhaiterions","demander","un","remboursement."],"h":"Gostaríamos de solicitar um reembolso."},{"t":["Je","souhaiterais","obtenir","des","informations","complémentaires."],"h":"Gostaria de informações adicionais."}],"dict":[{"t":"Dans ce cas, évite un ton agressif. Un courrier formel commence par « Madame, Monsieur, » et présente les faits clairement."},{"t":"Je voudrais expliquer que leur décision a perturbé toute notre organisation, mais sans paraître trop accusatrice."},{"t":"Ce serait trop direct. Écris : « Nous souhaiterions savoir si une salle équivalente pourrait être mise à notre disposition. »"},{"t":"Je vais joindre la confirmation initiale et le message d'annulation. Comment annoncer les pièces jointes ?"},{"t":"Il me manque seulement la formule finale. Je trouve « Cordialement » un peu court pour cette première réclamation."}],"shadow":["Dans ce cas, évite un ton agressif. Un courrier formel commence par « Madame, Monsieur, » et présente les faits clairement.","Formule plutôt : « Cette annulation a entraîné une modification importante de notre programme. » C'est précis et professionnel.","Je vais joindre la confirmation initiale et le message d'annulation. Comment annoncer les pièces jointes ?","Alors utilise : « Je vous prie d'agréer, Madame, Monsieur, l'expression de mes salutations distinguées. » Ce sera parfaitement adapté."],"write":{"task":"Escreva carta formal de reclamação ou pedido com assunto, abertura, nominalização, anexos e encerramento.","ph":"Objet : Demande concernant … . Madame, Monsieur, je me permets de …"},"cards":[["Entro em contato sobre minha reserva.","Je me permets de vous contacter au sujet de ma réservation."],["Gostaria de informações adicionais.","Je souhaiterais obtenir des informations complémentaires."],["Poderiam confirmar a data?","Pourriez-vous confirmer la date ?"],["Aguardamos sua decisão.","Nous attendons votre décision."],["O cancelamento causou dificuldades.","L'annulation a entraîné des difficultés."],["A confirmação está anexa.","La confirmation se trouve en pièce jointe."],["Em razão do atraso, mudamos os planos.","En raison du retard, nous avons modifié nos plans."],["Agradeço antecipadamente sua resposta.","Je vous remercie par avance de votre réponse."],["Gostaríamos de solicitar um reembolso.","Nous souhaiterions demander un remboursement."],["Fico à disposição para informações adicionais.","Je reste à votre disposition pour toute information complémentaire."]]},{"title":"Débattre","goal":"Participar de debates com argumentos equilibrados, concessões e estruturas de mise en relief.","speakers":{"Inès":"f","Lucas":"m"},"setting":"Inès e Lucas discutem a abertura dominical de uma biblioteca pública em Rennes.","lines":[["Inès","On nous demande un avis sur l'ouverture de la médiathèque le dimanche. Personnellement, je trouve l'idée intéressante, mais j'aimerais connaître le coût.","Pediram nossa opinião sobre abrir a biblioteca aos domingos. Acho interessante, mas quero saber o custo."],["Lucas","Il me semble que ce serait utile aux personnes qui travaillent toute la semaine. Ce qui me plaît, c'est la possibilité de venir en famille.","Parece útil a quem trabalha a semana. O que me agrada é poder ir em família."],["Inès","Certes, ce serait pratique, mais le personnel devrait accepter de changer ses horaires. Ce n'est pas un détail.","Seria prático, mas os funcionários teriam de mudar horários. Isso importa."],["Lucas","Je suis d'accord. En revanche, on pourrait commencer par un dimanche par mois au lieu d'imposer une ouverture systématique.","Concordo. Poderíamos começar com um domingo por mês em vez de abrir sempre."],["Inès","Ce que je crains, c'est qu'on annonce ce changement sans prévoir les moyens nécessaires. Les bonnes intentions ne suffisent pas.","Temo que anunciem sem prever recursos. Boas intenções não bastam."],["Lucas","Tu marques un point. Cela dit, certaines médiathèques proposent déjà des événements ponctuels le dimanche, avec des équipes volontaires.","Você tem razão nesse ponto. Algumas bibliotecas já fazem eventos pontuais aos domingos com equipes voluntárias."],["Inès","Il faudrait éviter de tout faire reposer sur le volontariat. Ce sont les salariés qui assurent l'accueil et le suivi des collections.","Devemos evitar depender só do voluntariado. Funcionários garantem atendimento e acervo."],["Lucas","Bien sûr. Ce que je propose, c'est de consulter l'équipe avant de fixer les dates. On pourrait aussi demander l'avis des usagers.","Claro. Proponho consultar a equipe antes das datas e também os usuários."],["Inès","D'une part, cette ouverture rendrait la culture plus accessible. D'autre part, elle entraînerait des dépenses supplémentaires.","Por um lado ampliaria acesso à cultura, por outro geraria despesas."],["Lucas","Je ne nie pas les coûts. Toutefois, on pourrait mesurer la fréquentation pendant trois mois avant de décider si l'essai vaut la peine.","Não nego custos. Porém podemos medir público por três meses antes de decidir."],["Inès","Ce dont nous avons besoin, c'est d'une estimation précise, pas seulement d'un chiffre approximatif.","Precisamos de uma estimativa precisa, não de número aproximado."],["Lucas","Absolument. C'est la direction qui pourrait présenter un budget, et ce sont les usagers qui pourraient indiquer leurs besoins.","Exato. A direção apresentaria orçamento, e usuários indicariam necessidades."],["Inès","Il me semble aussi que les étudiants auraient intérêt à disposer d'un espace calme le week-end.","Também acho que os estudantes se beneficiariam de espaço tranquilo nos fins de semana."],["Lucas","En revanche, il ne faut pas supposer qu'une ouverture dominicale conviendra à tout le monde. Les horaires et les transports comptent.","Mas não devemos presumir que domingo sirva para todos. Horários e transporte importam."],["Inès","Finalement, je serais favorable à un essai limité, à condition qu'il repose sur une concertation et un financement clairs.","Por fim, apoio teste limitado com diálogo e financiamento claros."],["Lucas","Nous sommes donc plutôt d'accord : certes, l'idée mérite d'être testée, mais pas au détriment des conditions de travail.","Estamos quase de acordo: vale testar, mas não às custas das condições de trabalho."]],"grammar":[{"h":"Il me semble que: opinião com nuance","p":["Apresenta opinião cautelosa; na forma afirmativa geralmente usa indicatif ou conditionnel hipotético; na negativa costuma usar subjonctif."],"ex":[["Il me semble que cette proposition est raisonnable.","Parece-me razoável."],["Il me semble que ce serait une bonne solution.","Parece boa solução."],["Il ne me semble pas que ce soit nécessaire.","Não me parece necessário."]],"tip":"Nuance é melhor que certeza infundada."},{"h":"Certes... mais e en revanche","p":["Reconheça a força de argumento antes de apresentar uma ressalva. En revanche e toutefois marcam contraste com diferentes nuances."],"ex":[["Certes, c'est pratique, mais cela coûte cher.","É prático, mas caro."],["Le projet demande du temps. En revanche, il est utile.","Exige tempo, mas é útil."],["Je comprends votre argument. Toutefois, des questions restent ouvertes.","Entendo, mas há questões."]],"tip":"Reconheça argumentos contrários sem caricaturas."},{"h":"Construir argumentos e conclusão","p":["D'une part... d'autre part apresenta dois lados. Je reconnais que aceita objeção. En somme resume uma conclusão coerente."],"ex":[["D'une part, c'est utile, d'autre part, c'est coûteux.","Por um lado útil, por outro caro."],["Je reconnais que votre remarque est pertinente.","Reconheço que sua observação é pertinente."],["En somme, testons cette solution.","Em resumo, testemos a solução."]],"tip":"Diferencie argumento, ressalva e conclusão."},{"h":"Mise en relief","p":["<b>Ce qui... c'est</b> destaca sujeito; <b>ce que... c'est</b> destaca objeto direto; <b>ce dont... c'est</b> destaca complemento com de. C'est... qui destaca sujeito."],"ex":[["Ce qui m'inquiète, c'est le manque de temps.","O que me preocupa é falta de tempo."],["Ce que je propose, c'est de commencer progressivement.","Proponho começar gradualmente."],["Ce dont nous avons besoin, c'est d'un budget précis.","Precisamos de orçamento preciso."],["C'est la direction qui décidera.","É a direção que decidirá."]],"tip":"Escolha qui, que ou dont pela função sintática."}],"vocab":[{"h":"Debates e opiniões","items":[["un débat","um debate"],["un argument","um argumento"],["un point de vue","um ponto de vista"],["une réserve","uma ressalva"],["une objection","uma objeção"],["une proposition","uma proposta"],["un compromis","um acordo intermediário"],["une conclusion","uma conclusão"]]},{"h":"Conectores e projetos","items":[["certes","é verdade que"],["en revanche","por outro lado"],["toutefois","no entanto"],["cependant","entretanto"],["d'une part","por um lado"],["d'autre part","por outro lado"],["une estimation","uma estimativa"],["un financement","um financiamento"]]}],"pron":[{"h":"certes","p":"O s final é pronunciado, diferentemente de várias palavras francesas: aproximadamente “sèrtss”.","w":["certes","certes, mais","certes, cette idée"]},{"h":"ce qui, ce que, ce dont","p":"Ce qui soa “se-ki”, ce que soa “se-ke” e ce dont termina com vogal nasal.","w":["ce qui me plaît","ce que je propose","ce dont nous avons besoin"]}],"mc":[{"q":"Qual é o tema da discussão?","o":["Construir nova universidade","Abrir a biblioteca aos domingos","Aumentar preços dos livros"],"a":1,"e":"On nous demande un avis sur l'ouverture de la médiathèque le dimanche. Personnellement, je trouve l'idée intéressante, mais j'aimerais connaître le coût."},{"q":"Qual alternativa Lucas propõe?","o":["Abrir um domingo por mês","Abrir de madrugada","Atender somente por aplicativo"],"a":0,"e":"Je suis d'accord. En revanche, on pourrait commencer par un dimanche par mois au lieu d'imposer une ouverture systématique."},{"q":"O que Inès considera necessário?","o":["Pesquisar os livros mais emprestados","Fazer campanha publicitária","Ter estimativa precisa dos recursos"],"a":2,"e":"Ce dont nous avons besoin, c'est d'une estimation précise, pas seulement d'un chiffre approximatif."},{"q":"Quando Inès apoiaria um teste limitado?","o":["Se eliminassem empréstimos","Com diálogo e financiamento claros","Com funcionários sem remuneração"],"a":1,"e":"Finalement, je serais favorable à un essai limité, à condition qu'il repose sur une concertation et un financement clairs."}],"gaps":[{"s":"Il me semble que cette proposition ___ (être, indicatif présent) raisonnable.","a":["est"],"h":"Parece-me que a proposta é razoável."},{"s":"Il ne me semble pas que ce ___ (être, subjonctif) nécessaire.","a":["soit"],"h":"Não me parece necessário."},{"s":"___, cette idée est intéressante, mais elle coûterait trop cher.","a":["Certes"],"h":"É verdade que é interessante, mas custaria caro."},{"s":"Ce ___ m'inquiète, c'est le manque de personnel.","a":["qui"],"h":"O que me preocupa é falta de funcionários."},{"s":"Ce ___ je propose, c'est de commencer progressivement.","a":["que"],"h":"O que proponho é começar gradualmente."},{"s":"Ce ___ nous avons besoin, c'est d'un budget précis.","a":["dont"],"h":"O que precisamos é de orçamento preciso."}],"order":[{"t":["Il","me","semble","que","c'est","une","bonne","idée."],"h":"Parece-me uma boa ideia."},{"t":["Je","reconnais","que","votre","argument","est","valable."],"h":"Reconheço que o argumento é válido."},{"t":["Certes,","c'est","utile,","mais","cela","coûte","cher."],"h":"É útil, mas custa caro."}],"dict":[{"t":"Il me semble que ce serait utile aux personnes qui travaillent toute la semaine. Ce qui me plaît, c'est la possibilité de venir en famille."},{"t":"Ce que je crains, c'est qu'on annonce ce changement sans prévoir les moyens nécessaires. Les bonnes intentions ne suffisent pas."},{"t":"Bien sûr. Ce que je propose, c'est de consulter l'équipe avant de fixer les dates. On pourrait aussi demander l'avis des usagers."},{"t":"Ce dont nous avons besoin, c'est d'une estimation précise, pas seulement d'un chiffre approximatif."},{"t":"Finalement, je serais favorable à un essai limité, à condition qu'il repose sur une concertation et un financement clairs."}],"shadow":["Il me semble que ce serait utile aux personnes qui travaillent toute la semaine. Ce qui me plaît, c'est la possibilité de venir en famille.","Tu marques un point. Cela dit, certaines médiathèques proposent déjà des événements ponctuels le dimanche, avec des équipes volontaires.","Ce dont nous avons besoin, c'est d'une estimation précise, pas seulement d'un chiffre approximatif.","Nous sommes donc plutôt d'accord : certes, l'idée mérite d'être testée, mais pas au détriment des conditions de travail."],"write":{"task":"Redija um texto argumentativo de oito a dez frases com posição, contra-argumento, ressalvas, mise en relief e conclusão equilibrada.","ph":"Il me semble que … . Certes, …, mais …"},"cards":[["Parece-me uma boa ideia.","Il me semble que c'est une bonne idée."],["É útil, mas custa caro.","Certes, c'est utile, mais cela coûte cher."],["Por outro lado, economizaríamos tempo.","En revanche, nous gagnerions du temps."],["O que me agrada é a flexibilidade.","Ce qui me plaît, c'est la flexibilité."],["Proponho fazer um teste.","Ce que je propose, c'est de faire un essai."],["Precisamos de mais informações.","Ce dont nous avons besoin, c'est de plus d'informations."],["É a direção que decidirá.","C'est la direction qui prendra la décision."],["Por um lado é prático; por outro caro.","D'une part, c'est pratique ; d'autre part, c'est cher."],["Reconheço que o argumento é válido.","Je reconnais que votre argument est valable."],["Em resumo, precisamos de uma solução equilibrada.","En somme, nous avons besoin d'une solution équilibrée."]]},{"title":"Il fut une époque","goal":"Reconhecer o passé simple e o subjonctif imparfait em textos literários e históricos, distinguindo a narração escrita do relato oral contemporâneo.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Numa biblioteca em Lyon, Claire e Lucas preparam uma leitura pública a partir de uma crônica histórica.","lines":[["Lucas","J'ai relu la chronique que tu m'as envoyée. Dès la première phrase, j'ai eu l'impression d'ouvrir un roman du XIXe siècle.","Reli a crônica que você me mandou. Logo na primeira frase, tive a impressão de abrir um romance do século XIX."],["Claire","C'est l'effet recherché. Écoute : Un soir de novembre, une inconnue entra dans la ville et aperçut une lumière derrière les volets clos.","Era exatamente esse o efeito pretendido. Escuta: Numa noite de novembro, uma desconhecida entrou na cidade e avistou uma luz atrás das persianas fechadas."],["Lucas","À l'oral, je dirais plutôt qu'une femme est entrée dans la ville et qu'elle a aperçu une lumière. Le passé simple change vraiment la couleur du récit.","Falando, eu diria que uma mulher entrou na cidade e avistou uma luz. O passé simple realmente muda o tom da narrativa."],["Claire","Exactement. Plus loin, on lit : Elle prit la lettre, en brisa le sceau et découvrit un nom qu'elle croyait oublié. Trois actions qui font avancer l'histoire.","Exatamente. Mais adiante, lemos: Ela pegou a carta, rompeu o lacre e descobriu um nome que julgava esquecido. Três ações que fazem a história avançar."],["Lucas","Et l'imparfait reste là pour planter le décor : la rue était déserte, le vent soufflait et personne ne semblait attendre cette visite.","E o imparfait continua servindo para criar o cenário: a rua estava deserta, ventava e ninguém parecia esperar aquela visita."],["Claire","Tu as vu la phrase suivante ? Le maire exigea qu'elle fût reçue sans délai. Le fût m'a fait sourire : on ne parle plus comme ça.","Viu a frase seguinte? O prefeito exigiu que ela fosse recebida sem demora. Esse fût me fez sorrir: ninguém mais fala assim."],["Lucas","C'est le subjonctif imparfait de être, non ? Aujourd'hui, on dirait qu'elle soit reçue, même si le verbe principal est au passé.","É o subjuntivo imperfeito de être, certo? Hoje diríamos qu'elle soit reçue, mesmo que o verbo principal esteja no passado."],["Claire","Oui. Et dans il fallait qu'il vînt avant l'aube, vînt correspond au subjonctif présent vienne. À comprendre dans un texte, pas à ressortir au café.","Sim. E em il fallait qu'il vînt avant l'aube, vînt corresponde ao subjuntivo presente vienne. É para entender num texto, não para usar no café."],["Lucas","Heureusement ! Si je disais à mes collègues qu'il fallait qu'ils vinssent à huit heures, ils penseraient que je me moque d'eux.","Ainda bem! Se eu dissesse aos colegas que eles deveriam vir às oito, achariam que estou tirando sarro deles."],["Claire","Dans un article historique, ces formes peuvent donner de la distance. Mais un reportage sur un événement d'hier emploiera normalement le passé composé.","Num artigo histórico, essas formas podem dar distanciamento. Mas uma reportagem sobre algo de ontem normalmente usará o passé composé."],["Lucas","Donc il disparut n'est pas une autre manière de dire il disparaissait. Le premier marque un événement achevé ; le second peut décrire une action en cours.","Então il disparut não é outra forma de dizer il disparaissait. O primeiro marca um acontecimento concluído; o segundo pode descrever uma ação em andamento."],["Claire","Tout à fait. Et il eut peur signifie qu'il a eu peur à ce moment-là, tandis qu'il avait peur décrit plutôt son état ou la situation.","Isso mesmo. E il eut peur significa que ele sentiu medo naquele momento, enquanto il avait peur descreve mais o estado dele ou a situação."],["Lucas","Je me suis aussi arrêté sur bien qu'il eût des témoins. Là, eût n'est pas le passé simple de avoir, mais le subjonctif imparfait.","Também parei em bien qu'il eût des témoins. Aí, eût não é o passé simple de avoir, mas o subjuntivo imperfeito."],["Claire","Bien vu. Sans accent, il eut correspond au passé simple ; avec l'accent circonflexe, qu'il eût appartient au subjonctif imparfait.","Bem observado. Sem circunflexo, il eut é passé simple; com o acento, qu'il eût é subjuntivo imperfeito."],["Lucas","Pour la lecture publique, tu veux que je garde les formes originales ou que je reformule quelques passages pour le public ?","Na leitura pública, você quer que eu mantenha as formas originais ou reformule alguns trechos para o público?"],["Claire","Gardons l'original à voix haute, puis racontons les événements avec nos mots. Les auditeurs entendront la différence sans subir un cours de conjugaison.","Vamos manter o original em voz alta e depois contar os acontecimentos com nossas palavras. O público vai perceber a diferença sem aguentar uma aula de conjugação."],["Lucas","Bonne idée. Je lirai elle découvrit la vérité, puis j'expliquerai simplement qu'elle a découvert ce qui s'était passé la veille.","Boa ideia. Vou ler elle découvrit la vérité e depois explicar que ela descobriu o que havia acontecido na véspera."],["Claire","Parfait. On montrera qu'un texte ancien peut rester vivant, à condition de ne pas confondre comprendre un temps et devoir l'utiliser au quotidien.","Perfeito. Vamos mostrar que um texto antigo pode continuar vivo, desde que não se confunda entender um tempo verbal com precisar usá-lo no dia a dia."]],"grammar":[{"h":"Passé simple: ações concluídas em narrativas","p":["O <b>passé simple</b> marca ações pontuais que fazem a narrativa escrita avançar. Aparece sobretudo em romances, contos, biografias narrativas e certos textos históricos. Na conversa cotidiana, normalmente usamos o passé composé."],"ex":[["Elle entra, prit la lettre et disparut.","Ela entrou, pegou a carta e desapareceu."],["Il aperçut la maison et comprit son erreur.","Ele avistou a casa e entendeu o erro."],["Ils partirent avant le lever du soleil.","Eles partiram antes do nascer do sol."]],"tip":"Para ler, reconheça formas como fut, eut, fit, prit, vit e vinrent."},{"h":"Passé simple e imparfait não são intercambiáveis","p":["Mesmo em um texto literário, o <b>imparfait</b> descreve cenário, hábitos e ações em curso. O <b>passé simple</b> introduz eventos delimitados. Ao reformular oralmente, troque em geral o passé simple pelo passé composé, sem trocar automaticamente o imparfait."],"ex":[["La rue était vide lorsqu'elle arriva.","A rua estava vazia quando ela chegou."],["Il lisait tranquillement ; soudain, quelqu'un frappa.","Ele lia tranquilamente; de repente, alguém bateu."],["Elle ouvrit la porte, mais personne ne l'attendait.","Ela abriu a porta, mas ninguém a esperava."]],"tip":"Pergunte: a frase descreve o pano de fundo ou um acontecimento?"},{"h":"Subjonctif imparfait: reconhecer sem imitar","p":["O <b>subjonctif imparfait</b> é hoje principalmente literário. Pode surgir após verbos de exigência, vontade e certas conjunções, quando a oração principal está no passado. Na língua corrente, usa-se em geral o subjonctif présent: il fallait qu'il vînt → il fallait qu'il vienne."],"ex":[["Il exigea qu'elle fût présente.","Ele exigiu que ela estivesse presente."],["Il fallait qu'il vînt avant midi.","Era necessário que ele viesse antes do meio-dia."],["Bien qu'il eût peur, il poursuivit sa route.","Embora estivesse com medo, ele prosseguiu seu caminho."]],"tip":"Compare qu'il fût com qu'il soit, e qu'il eût com qu'il ait."},{"h":"Cuidado com eut e eût","p":["No verbo avoir, <b>il eut</b> (sem acento) é passé simple do indicativo. <b>Qu'il eût</b> (com circunflexo) é subjonctif imparfait. O contexto sintático e o acento ajudam a reconhecer a forma."],"ex":[["Il eut une idée inattendue.","Ele teve uma ideia inesperada."],["Bien qu'il eût une solution, il hésitait.","Embora tivesse uma solução, hesitava."],["Elle fut surprise qu'il fût déjà là.","Ela ficou surpresa por ele já estar ali."]],"tip":"Fut não tem circunflexo; fût tem. O mesmo contraste aparece em eut/eût."}],"vocab":[{"h":"Literatura e documentos","items":[["une chronique","uma crônica"],["un récit","um relato, uma narrativa"],["un passage","um trecho"],["un sceau","um lacre, um selo"],["les volets","as persianas externas"],["l'aube","o amanhecer"],["un témoin","uma testemunha"],["une lecture publique","uma leitura pública"]]},{"h":"Analisar uma narrativa","items":[["planter le décor","criar o cenário"],["faire avancer l'histoire","fazer a história avançar"],["un événement achevé","um acontecimento concluído"],["sans délai","sem demora"],["reformuler","reformular"],["le registre littéraire","o registro literário"],["la veille","a véspera"],["prendre de la distance","ganhar distanciamento"]]}],"pron":[{"h":"fut e fût","p":"As duas grafias soam igual, aproximadamente “fü”; o circunflexo distingue funções gramaticais, não a pronúncia.","w":["il fut","qu'il fût","elle fut surprise"]},{"h":"eut e eût","p":"Ambas são pronunciadas aproximadamente “ü” em francês padrão; o acento não cria uma sílaba nova.","w":["il eut","qu'il eût","elle eut peur"]},{"h":"vint e vînt","p":"As duas formas têm som nasal semelhante a “vẽ”, sem pronunciar o t final; a diferença é morfológica.","w":["il vint","qu'il vînt","il fallait qu'il vînt"]}],"mc":[{"q":"Por que Claire escolheu uma crônica com passé simple?","o":["Para reproduzir a fala coloquial de hoje","Para criar um efeito de narrativa literária","Para ensinar apenas tempos do futuro"],"a":1,"e":"C'est l'effet recherché. Écoute : Un soir de novembre, une inconnue entra dans la ville et aperçut une lumière derrière les volets clos."},{"q":"Que forma Lucas usaria oralmente no lugar de entra e aperçut?","o":["Est entrée e a aperçu","Entrera e apercevra","Entrant e apercevant"],"a":0,"e":"À l'oral, je dirais plutôt qu'une femme est entrée dans la ville et qu'elle a aperçu une lumière."},{"q":"Como Claire recomenda tratar o subjonctif imparfait hoje?","o":["Usá-lo em toda conversa profissional","Substituir sempre pelo infinitivo","Reconhecê-lo na leitura, sem empregá-lo no café"],"a":2,"e":"À comprendre dans un texte, pas à ressortir au café."},{"q":"Como será organizada a leitura pública?","o":["Somente com uma tradução escrita","Primeiro o texto original, depois uma reformulação oral","Apenas com verbos no presente"],"a":1,"e":"Gardons l'original à voix haute, puis racontons les événements avec nos mots."}],"gaps":[{"s":"Dans ce conte, elle ___ (entrer, passé simple) sans bruit.","a":["entra"],"h":"Nesse conto, ela entrou sem fazer barulho."},{"s":"Le héros ___ (prendre, passé simple) la dernière lettre.","a":["prit"],"h":"O herói pegou a última carta."},{"s":"La ville ___ (être, imparfait) silencieuse lorsqu'il arriva.","a":["était"],"h":"A cidade estava silenciosa quando ele chegou."},{"s":"Le maire voulut qu'elle ___ (être, subjonctif imparfait) reçue.","a":["fût"],"h":"O prefeito quis que ela fosse recebida."},{"s":"Bien qu'il ___ (avoir, subjonctif imparfait) peur, il avança.","a":["eût"],"h":"Embora estivesse com medo, ele avançou."},{"s":"Soudain, elle ___ (découvrir, passé simple) la vérité.","a":["découvrit"],"h":"De repente, ela descobriu a verdade."}],"order":[{"t":["Elle","prit","la","lettre","sans","hésiter."],"h":"Ela pegou a carta sem hesitar."},{"t":["La","rue","était","encore","déserte."],"h":"A rua ainda estava deserta."},{"t":["Il","fallait","qu'elle","fût","présente."],"h":"Era necessário que ela estivesse presente."}],"dict":[{"t":"Un soir de novembre, une inconnue entra dans la ville et aperçut une lumière derrière les volets clos."},{"t":"Elle prit la lettre, en brisa le sceau et découvrit un nom qu'elle croyait oublié."},{"t":"Le maire exigea qu'elle fût reçue sans délai."},{"t":"Dans un article historique, ces formes peuvent donner de la distance. Mais un reportage sur un événement d'hier emploiera normalement le passé composé."},{"t":"Gardons l'original à voix haute, puis racontons les événements avec nos mots. Les auditeurs entendront la différence sans subir un cours de conjugaison."}],"shadow":["À l'oral, je dirais plutôt qu'une femme est entrée dans la ville et qu'elle a aperçu une lumière. Le passé simple change vraiment la couleur du récit.","Et l'imparfait reste là pour planter le décor : la rue était déserte, le vent soufflait et personne ne semblait attendre cette visite.","Je me suis aussi arrêté sur bien qu'il eût des témoins. Là, eût n'est pas le passé simple de avoir, mais le subjonctif imparfait.","Bonne idée. Je lirai elle découvrit la vérité, puis j'expliquerai simplement qu'elle a découvert ce qui s'était passé la veille."],"write":{"task":"Escolha uma cena de romance ou crônica e, em cinco a sete frases em francês, explique duas formas literárias e como você contaria a cena oralmente.","ph":"Dans ce passage, l'auteur emploie … . À l'oral, je dirais plutôt …"},"cards":[["Ela entrou sem fazer barulho.","Elle entra sans bruit."],["Ele viu uma luz ao longe.","Il aperçut une lumière au loin."],["Ela pegou a última carta.","Elle prit la dernière lettre."],["A rua estava completamente vazia.","La rue était complètement vide."],["De repente, eles ouviram um barulho.","Soudain, ils entendirent un bruit."],["Era preciso que ele viesse.","Il fallait qu'il vînt."],["Embora tivesse uma pista, ele hesitava.","Bien qu'il eût un indice, il hésitait."],["Esse verbo é típico da escrita literária.","Ce verbe est typique de l'écriture littéraire."],["Na fala, eu usaria o passé composé.","À l'oral, j'emploierais le passé composé."],["O cenário é descrito no imparfait.","Le décor est décrit à l'imparfait."]]},{"title":"C'est lui qui...","goal":"Dar destaque a pessoas, informações e prioridades com c'est... qui/que, ce qui... c'est, ce dont... c'est e ce à quoi... c'est, em apresentações e conversas.","speakers":{"Inès":"f","Antoine":"m"},"setting":"Em uma associação de bairro em Nantes, Inès e Antoine revisam uma apresentação sobre um projeto de mobilidade antes de uma reunião pública.","lines":[["Antoine","J'ai regardé tes diapositives. Les chiffres sont clairs, mais on ne comprend pas tout de suite pourquoi les habitants devraient soutenir le projet.","Olhei seus slides. Os números estão claros, mas não fica evidente por que os moradores deveriam apoiar o projeto."],["Inès","Tu as raison. Ce qui me gêne, c'est que notre message principal arrive à la fin, après trois tableaux que personne ne retiendra.","Você tem razão. O que me incomoda é que nossa mensagem principal aparece no final, depois de três tabelas das quais ninguém vai se lembrar."],["Antoine","Alors commençons par une phrase forte : C'est la sécurité des piétons qui motive cette proposition, pas une envie de compliquer la circulation.","Então vamos começar com uma frase forte: É a segurança dos pedestres que motiva a proposta, não uma vontade de complicar o trânsito."],["Inès","Oui, et c'est autour des écoles que nous avons observé les situations les plus dangereuses. Ça donne un exemple concret dès le départ.","Sim, e foi perto das escolas que observamos as situações mais perigosas. Isso dá um exemplo concreto logo de início."],["Antoine","Ce que les parents nous ont demandé, c'est un passage piéton mieux éclairé. Il ne faut pas présenter leur demande comme un simple détail technique.","O que os pais nos pediram foi uma faixa de pedestres mais bem iluminada. Não devemos tratar esse pedido como mero detalhe técnico."],["Inès","Et ce dont les riverains ont surtout besoin, c'est d'informations fiables sur les travaux. Ils ont peur que le chantier dure indéfiniment.","E do que os moradores mais precisam é de informações confiáveis sobre as obras. Eles temem que a obra se arraste indefinidamente."],["Antoine","Exactement. Ce à quoi ils tiennent, c'est à pouvoir accéder à leurs commerces pendant les travaux. On doit répondre à cette inquiétude.","Exatamente. O que eles fazem questão de preservar é o acesso ao comércio durante as obras. Precisamos responder a essa preocupação."],["Inès","Je pourrais dire : C'est une enquête de terrain que nous avons menée, et non une décision prise à huis clos. Tu trouves ça trop défensif ?","Eu poderia dizer: Foi uma pesquisa de campo que realizamos, não uma decisão tomada a portas fechadas. Acha defensivo demais?"],["Antoine","Un peu. Ce qui compte, c'est de montrer la méthode, pas de répondre à des critiques qui n'ont même pas encore été formulées.","Um pouco. O importante é mostrar o método, não responder a críticas que nem foram feitas ainda."],["Inès","D'accord. Je présenterai les entretiens, puis j'expliquerai que c'est Claire qui a coordonné les observations avec les bénévoles.","Combinado. Vou apresentar as entrevistas e depois explicar que foi Claire quem coordenou as observações com os voluntários."],["Antoine","Attention à la suite : si tu dis c'est moi qui ai rédigé le rapport, le verbe s'accorde avec moi, pas avec le singulier apparent de c'est.","Atenção à continuação: se você disser c'est moi qui ai rédigé le rapport, o verbo concorda com moi, não com a aparência singular de c'est."],["Inès","Je vois. Et c'est nous qui avons recueilli les témoignages, puisque l'équipe entière a participé. La tournure permet de répartir les responsabilités.","Entendi. E fomos nós que reunimos os depoimentos, já que a equipe inteira participou. A construção ajuda a distribuir as responsabilidades."],["Antoine","Autre détail : évite de répéter c'est toutes les deux phrases. La mise en relief fonctionne mieux lorsqu'on choisit vraiment ce qui mérite l'accent.","Outro detalhe: evite repetir c'est a cada duas frases. O destaque funciona melhor quando escolhemos bem o que merece ênfase."],["Inès","Bonne remarque. Ce que je voudrais surtout éviter, c'est de donner l'impression qu'on impose un projet déjà bouclé.","Boa observação. O que eu mais gostaria de evitar é passar a impressão de que estamos impondo um projeto já fechado."],["Antoine","Dans ce cas, dis : Ce à quoi nous sommes ouverts, ce sont les propositions d'aménagement des habitants. Ça invite réellement à la discussion.","Nesse caso, diga: Estamos abertos às propostas dos moradores sobre como adaptar o espaço. Isso realmente convida ao diálogo."],["Inès","Et pour le financement ? Ce dont nous disposons aujourd'hui, c'est d'un budget provisoire. Je préfère être transparente sur ce point.","E quanto ao financiamento? O que temos hoje é um orçamento provisório. Prefiro ser transparente nesse ponto."],["Antoine","Très bien. Ce n'est pas une promesse définitive que tu présentent, c'est une démarche à discuter collectivement. La nuance change tout.","Muito bem. O que você apresenta não é uma promessa definitiva, e sim uma proposta a ser discutida coletivamente. Essa nuance muda tudo."],["Inès","Parfait. Ce qui me rassure, c'est qu'on a maintenant une ligne directrice. Il ne reste plus qu'à raccourcir les diapositives.","Perfeito. O que me tranquiliza é que agora temos uma linha mestra. Só falta enxugar os slides."]],"grammar":[{"h":"C'est... qui e c'est... que: sujeito e complemento","p":["A estrutura <b>c'est + elemento destacado + qui</b> realça o sujeito da oração; <b>c'est + elemento destacado + que</b> realça um complemento, inclusive uma expressão de tempo ou lugar. No plural, ce sont pode ser preferível em registro monitorado."],"ex":[["C'est Inès qui présente le projet.","É Inès quem apresenta o projeto."],["C'est ce rapport que nous avons relu.","Foi esse relatório que relemos."],["C'est demain que la réunion aura lieu.","É amanhã que a reunião acontecerá."]],"tip":"Pergunte se o trecho destacado faz a ação (qui) ou recebe a ação / situa o fato (que)."},{"h":"Ce qui... c'est e ce que... c'est","p":["Quando a informação destacada é uma ideia inteira, use <b>ce qui</b> se ela exerce função de sujeito do verbo seguinte; use <b>ce que</b> se exerce função de objeto direto. A segunda parte introduz o elemento focalizado."],"ex":[["Ce qui m'inquiète, c'est le calendrier.","O que me preocupa é o cronograma."],["Ce que nous proposons, c'est un essai de six mois.","O que propomos é um teste de seis meses."],["Ce qui manque, c'est une réponse précise.","O que falta é uma resposta precisa."]],"tip":"Diferencie ce qui manque (o que falta) de ce que je demande (o que eu peço)."},{"h":"Ce dont... c'est: recuperar a preposição de","p":["Use <b>ce dont</b> quando o verbo ou expressão pede de: avoir besoin de, parler de, disposer de, se souvenir de. Na segunda parte, a preposição exigida pode reaparecer: Ce dont nous avons besoin, c'est d'un délai."],"ex":[["Ce dont nous avons besoin, c'est de temps.","O que precisamos é de tempo."],["Ce dont elle parle, c'est du budget.","Do que ela está falando é do orçamento."],["Ce dont je me souviens, c'est de sa réaction.","Do que me lembro é da reação dela."]],"tip":"Identifique primeiro a construção de base: avoir besoin de quelque chose."},{"h":"Ce à quoi... c'est: recuperar a preposição à","p":["Use <b>ce à quoi</b> com verbos e locuções que exigem à, como tenir à, penser à ou s'attendre à. A construção dá ênfase sem apagar a regência verbal."],"ex":[["Ce à quoi je tiens, c'est à la concertation.","O que considero essencial é a consulta pública."],["Ce à quoi il pense, c'est à une solution durable.","No que ele pensa é numa solução duradoura."],["Ce à quoi nous nous attendons, c'est à un débat animé.","O que esperamos é um debate acalorado."]],"tip":"Em c'est moi qui ai..., a concordância é com moi: ai, e não a."}],"vocab":[{"h":"Projetos e participação pública","items":[["une enquête de terrain","uma pesquisa de campo"],["un riverain","um morador das imediações"],["un chantier","uma obra, um canteiro de obras"],["un passage piéton","uma faixa de pedestres"],["un aménagement","uma adaptação do espaço"],["un témoignage","um depoimento"],["un bénévole","um voluntário"],["un budget provisoire","um orçamento provisório"]]},{"h":"Argumentar com precisão","items":[["mettre en relief","dar destaque"],["à huis clos","a portas fechadas"],["une ligne directrice","uma linha mestra"],["bouclé","concluído, fechado"],["une démarche","uma iniciativa, uma abordagem"],["répartir les responsabilités","distribuir as responsabilidades"],["être ouvert à","estar aberto a"],["être transparent sur","ser transparente sobre"]]}],"pron":[{"h":"c'est e ces","p":"C'est e ces são homófonos, aproximadamente “sè”; o contexto e a grafia revelam se há uma estrutura de destaque.","w":["c'est lui","ces projects","c'est important"]},{"h":"ce dont","p":"Em ce dont, dont contém a vogal nasal /ɔ̃/, aproximada por “dõ”, sem pronunciar n nem t final isoladamente.","w":["ce dont","ce dont j'ai besoin","ce dont nous disposons"]},{"h":"ce à quoi","p":"Na fala encadeada, ce à quoi soa aproximadamente “sə-a-kua”, com a sequência vocálica bem articulada.","w":["ce à quoi","ce à quoi je tiens","ce à quoi nous pensons"]}],"mc":[{"q":"O que motivou a proposta de mobilidade?","o":["Reduzir o orçamento das escolas","Restringir o acesso a todos os comércios","Melhorar a segurança dos pedestres"],"a":2,"e":"C'est la sécurité des piétons qui motive cette proposition, pas une envie de compliquer la circulation."},{"q":"Qual foi o pedido dos pais mencionado por Antoine?","o":["Uma faixa de pedestres mais bem iluminada","Uma nova linha de ônibus","O cancelamento imediato das obras"],"a":0,"e":"Ce que les parents nous ont demandé, c'est un passage piéton mieux éclairé."},{"q":"O que os moradores querem preservar durante a obra?","o":["A distribuição de panfletos","O acesso aos comércios","A proibição das reuniões públicas"],"a":1,"e":"Ce à quoi ils tiennent, c'est à pouvoir accéder à leurs commerces pendant les travaux."},{"q":"Qual a situação atual do financiamento?","o":["O projeto não tem nenhum orçamento","Os recursos já foram aprovados definitivamente","Há apenas um orçamento provisório"],"a":2,"e":"Ce dont nous disposons aujourd'hui, c'est d'un budget provisoire."}],"gaps":[{"s":"C'est Inès ___ présente les résultats.","a":["qui"],"h":"É Inès quem apresenta os resultados."},{"s":"C'est ce document ___ j'ai préparé hier.","a":["que"],"h":"Foi esse documento que preparei ontem."},{"s":"Ce ___ me gêne, c'est le manque de clarté.","a":["qui"],"h":"O que me incomoda é a falta de clareza."},{"s":"Ce ___ nous proposons, c'est une concertation.","a":["que"],"h":"O que propomos é uma consulta pública."},{"s":"Ce ___ nous avons besoin, c'est d'un délai.","a":["dont"],"h":"O que precisamos é de um prazo."},{"s":"Ce à ___ je tiens, c'est à la transparence.","a":["quoi"],"h":"O que considero essencial é a transparência."}],"order":[{"t":["C'est","Inès","qui","a","répondu."],"h":"Foi Inès quem respondeu."},{"t":["Ce","qui","compte,","c'est","la","sécurité."],"h":"O que importa é a segurança."},{"t":["Ce","dont","j'ai","besoin,","c'est","de","temps."],"h":"O que preciso é de tempo."}],"dict":[{"t":"Ce qui me gêne, c'est que notre message principal arrive à la fin, après trois tableaux que personne ne retiendra."},{"t":"C'est la sécurité des piétons qui motive cette proposition, pas une envie de compliquer la circulation."},{"t":"Et ce dont les riverains ont surtout besoin, c'est d'informations fiables sur les travaux."},{"t":"Ce à quoi ils tiennent, c'est à pouvoir accéder à leurs commerces pendant les travaux. On doit répondre à cette inquiétude."},{"t":"Ce que je voudrais surtout éviter, c'est de donner l'impression qu'on impose un projet déjà bouclé."}],"shadow":["Oui, et c'est autour des écoles que nous avons observé les situations les plus dangereuses. Ça donne un exemple concret dès le départ.","Ce que les parents nous ont demandé, c'est un passage piéton mieux éclairé. Il ne faut pas présenter leur demande comme un simple détail technique.","Je vois. Et c'est nous qui avons recueilli les témoignages, puisque l'équipe entière a participé. La tournure permet de répartir les responsabilités.","Et pour le financement ? Ce dont nous disposons aujourd'hui, c'est d'un budget provisoire. Je préfère être transparente sur ce point."],"write":{"task":"Escreva cinco a sete frases para defender uma melhoria no seu bairro, destacando a prioridade, quem a propôs e do que as pessoas precisam.","ph":"Ce qui me paraît essentiel, c'est … . C'est … qui …"},"cards":[["É essa questão que precisamos resolver.","C'est cette question que nous devons résoudre."],["Foi ela quem fez a pesquisa.","C'est elle qui a mené l'enquête."],["É amanhã que apresentaremos a proposta.","C'est demain que nous présenterons la proposition."],["O que me preocupa é o prazo.","Ce qui m'inquiète, c'est le délai."],["O que queremos é uma resposta clara.","Ce que nous voulons, c'est une réponse claire."],["O que falta é um plano realista.","Ce qui manque, c'est un plan réaliste."],["O que preciso é de mais informações.","Ce dont j'ai besoin, c'est de plus d'informations."],["Do que falamos é do financiamento.","Ce dont nous parlons, c'est du financement."],["O que considero importante é o diálogo.","Ce à quoi je tiens, c'est au dialogue."],["Somos nós que organizamos a reunião.","C'est nous qui organisons la réunion."]]},{"title":"Avoir beau essayer","goal":"Expressar concessões e objeções com quoiqu(e), si... que, avoir beau, quand bien même, tout... que e aussi... que, escolhendo o modo e o registro adequados.","speakers":{"Claire":"f","Antoine":"m"},"setting":"Na véspera de um festival de cinema independente em Bordeaux, Claire e Antoine discutem contratempos e decidem se mantêm a programação.","lines":[["Antoine","J'ai reçu le dernier message du cinéma. Quoiqu'ils aient confirmé la salle, ils ne peuvent toujours pas garantir que le projecteur sera réparé demain.","Recebi a última mensagem do cinema. Embora tenham confirmado a sala, ainda não conseguem garantir que o projetor estará consertado amanhã."],["Claire","On a beau les appeler depuis trois jours, on obtient chaque fois la même réponse. Je commence à me demander s'ils ont vraiment contacté un technicien.","Faz três dias que ligamos para eles, mas sempre recebemos a mesma resposta. Estou começando a me perguntar se realmente chamaram um técnico."],["Antoine","Si compétente que soit leur équipe, elle ne peut pas inventer une pièce de rechange. Essayons de distinguer ce qui dépend d'eux de ce qui n'en dépend pas.","Por mais competente que seja a equipe deles, ela não pode inventar uma peça de reposição. Vamos separar o que depende deles do que não depende."],["Claire","D'accord, mais quand bien même le projecteur fonctionnerait, il resterait le problème des sous-titres. Deux fichiers sont arrivés dans le mauvais format.","Certo, mas mesmo que o projetor funcionasse, ainda restaria o problema das legendas. Dois arquivos chegaram no formato errado."],["Antoine","J'ai beau convertir les fichiers, le logiciel refuse toujours la deuxième piste. À ce stade, il nous faut un plan de secours crédible.","Por mais que eu converta os arquivos, o programa continua rejeitando a segunda faixa. A essa altura, precisamos de um plano B viável."],["Claire","Aussi frustrante que soit la situation, je préfère qu'on évite d'annuler trop vite. Les réalisateurs viennent de loin et le public a déjà réservé.","Por mais frustrante que seja a situação, prefiro não cancelar depressa demais. Os diretores vêm de longe e o público já reservou."],["Antoine","Tout petit qu'il soit, le cinéma voisin possède un équipement récent. Je pourrais leur demander s'ils accepteraient d'accueillir la projection.","Embora seja bem pequeno, o cinema vizinho tem equipamentos modernos. Eu poderia perguntar se aceitariam receber a sessão."],["Claire","Bonne piste. Quoique ce soit moins confortable, une salle plus petite vaut mieux qu'une annulation à la dernière minute.","Boa ideia. Embora seja menos confortável, uma sala menor é melhor do que um cancelamento de última hora."],["Antoine","En revanche, si motivés que nous soyons, nous ne pourrons pas installer tout le matériel en une heure. Il faudrait négocier un créneau supplémentaire.","Por mais motivados que estejamos, não conseguiremos instalar todo o equipamento em uma hora. Teríamos de negociar um horário extra."],["Claire","Même si le public est compréhensif, une séance qui commence avec quarante minutes de retard risque d'agacer tout le monde. Il faut être réalistes.","Mesmo que o público seja compreensivo, uma sessão que comece com quarenta minutos de atraso pode irritar todo mundo. Temos de ser realistas."],["Antoine","Tu as raison. Je leur proposerai un début à vingt heures trente, à condition que la vérification technique ait lieu avant l'ouverture des portes.","Você tem razão. Vou propor início às oito e meia da noite, desde que a checagem técnica ocorra antes da abertura das portas."],["Claire","Et quand bien même nous devrions changer de lieu, nous pourrions prévenir les spectateurs par courriel et afficher un plan à l'entrée du cinéma initial.","E mesmo que tivéssemos de mudar de local, poderíamos avisar o público por e-mail e colocar um mapa na entrada do cinema original."],["Antoine","Je reconnais que ton idée tient la route. Pourtant, tout enthousiastes qu'ils soient, les bénévoles ne pourront pas assurer l'accueil sur deux sites à la fois.","Reconheço que sua ideia faz sentido. Mas, por mais animados que estejam, os voluntários não conseguirão recepcionar pessoas em dois locais ao mesmo tempo."],["Claire","Alors concentrons l'équipe dans la nouvelle salle. On aura beau préparer un dispositif parfait sur le papier, rien ne remplacera des consignes simples.","Então vamos concentrar a equipe na nova sala. Por mais que preparemos um esquema perfeito no papel, nada substitui instruções simples."],["Antoine","Aussi solide que paraisse ce plan, je voudrais une confirmation écrite avant d'annoncer quoi que ce soit. Sans ça, on risque de créer davantage de confusion.","Por mais sólido que esse plano pareça, eu gostaria de uma confirmação por escrito antes de anunciar qualquer coisa. Sem isso, corremos o risco de gerar mais confusão."],["Claire","Bien sûr. Et même si nous restons dans la salle d'origine, ces préparatifs ne seront pas perdus : ils nous serviront lors de la prochaine édition.","Claro. E mesmo que fiquemos na sala original, essa preparação não será perdida: ela vai servir para a próxima edição."],["Antoine","Je vais appeler le cinéma voisin maintenant. Si accueillants qu'ils soient, je doute qu'ils bloquent leur salle sans connaître nos contraintes techniques.","Vou ligar agora para o cinema vizinho. Por mais acolhedores que sejam, duvido que reservem a sala sem conhecer nossas exigências técnicas."],["Claire","Vas-y. Quoi qu'il arrive, on expliquera la situation sans dramatiser. Le festival mérite mieux qu'un silence embarrassé ou une promesse irréaliste.","Vai lá. Aconteça o que acontecer, explicaremos a situação sem dramatizar. O festival merece mais do que um silêncio constrangedor ou uma promessa irreal."]],"grammar":[{"h":"Quoique + subjonctif: objeção reconhecida","p":["<b>Quoique</b>, no sentido de embora, introduz uma concessão e normalmente pede subjonctif. Não confunda com <b>quoi que</b>, separado, que significa seja o que for que / qualquer coisa que. O registro de quoique tende a ser mais cuidado que o de même si."],"ex":[["Quoiqu'il soit tard, nous continuons.","Embora esteja tarde, continuamos."],["Quoique les places soient limitées, l'accès reste gratuit.","Embora as vagas sejam limitadas, a entrada continua gratuita."],["Quoi qu'il arrive, nous vous informerons.","Aconteça o que acontecer, avisaremos vocês."]],"tip":"Quoique = embora; quoi que = seja o que for que."},{"h":"Avoir beau + infinitif: esforço sem resultado","p":["<b>Avoir beau + infinitif</b> apresenta uma tentativa, esforço ou situação que não produz o resultado esperado. É muito natural na fala e na escrita; o verbo avoir é conjugado normalmente."],"ex":[["J'ai beau expliquer, personne ne m'écoute.","Por mais que eu explique, ninguém me escuta."],["Nous avons beau insister, ils refusent.","Por mais que insistamos, eles se recusam."],["Elle avait beau vérifier, l'erreur persistait.","Por mais que ela conferisse, o erro persistia."]],"tip":"Não coloque subjonctif depois de avoir beau: use o infinitivo."},{"h":"Si... que e aussi... que + subjonctif","p":["As estruturas <b>si + adjetivo/advérbio + que + subjonctif</b> e <b>aussi + adjetivo/advérbio + que + subjonctif</b> significam por mais... que. Em contexto concessivo, são construções mais elaboradas, frequentes em argumentações formais."],"ex":[["Si pressés que nous soyons, restons prudents.","Por mais apressados que estejamos, vamos agir com prudência."],["Aussi séduisante que soit l'idée, elle coûte cher.","Por mais atraente que seja a ideia, ela custa caro."],["Si clairement qu'il s'exprime, certains doutent encore.","Por mais claramente que ele se expresse, alguns ainda têm dúvidas."]],"tip":"Concorde o adjetivo com o referente: pressés, séduisante, motivées."},{"h":"Quand bien même e tout... que","p":["<b>Quand bien même</b> apresenta uma hipótese concessiva forte e costuma vir com conditionnel. <b>Tout + adjetivo + que</b> (com variações de concordância conforme gênero e número) admite uma característica que não impede o resultado. Ambas soam mais cuidadas que même si."],"ex":[["Quand bien même il accepterait, le délai serait trop court.","Mesmo que ele aceitasse, o prazo seria curto."],["Tout expérimenté qu'il soit, il peut se tromper.","Embora seja muito experiente, ele pode errar."],["Toute petite qu'elle soit, cette salle est bien équipée.","Embora seja bem pequena, essa sala é bem equipada."]],"tip":"Para uma conversa mais neutra, mesmo que + indicativo em francês costuma ser même si + indicatif."}],"vocab":[{"h":"Imprevistos e soluções","items":[["une pièce de rechange","uma peça de reposição"],["un sous-titre","uma legenda"],["une piste","uma faixa; uma possibilidade"],["un plan de secours","um plano de contingência"],["un créneau","um horário disponível"],["une séance","uma sessão"],["un contretemps","um imprevisto"],["une confirmation écrite","uma confirmação por escrito"]]},{"h":"Negociar e avaliar riscos","items":[["tenir la route","fazer sentido, ser viável"],["à ce stade","a essa altura"],["à la dernière minute","de última hora"],["risquer de","correr o risco de"],["assurer l'accueil","cuidar da recepção"],["une contrainte technique","uma limitação técnica"],["dramatiser","dramatizar"],["un dispositif","uma organização, um esquema"]]}],"pron":[{"h":"quoique e quoi que","p":"As duas formas soam aproximadamente “kua-kə” na fala articulada; o significado depende da escrita e da construção da frase.","w":["quoique","quoi qu'il arrive","quoique ce soit difficile"]},{"h":"beau e beaux","p":"Beau e beaux soam aproximadamente “bô”, com o x de beaux mudo fora de uma ligação pertinente.","w":["avoir beau","de beaux projects","nous avons beau essayer"]},{"h":"quand bien même","p":"Em quand bien même, o d final de quand normalmente não é pronunciado diante de bien; o conjunto soa aproximadamente “kã biã mèm”.","w":["quand bien même","quand bien même il viendrait","quand bien même nous partirions"]}],"mc":[{"q":"Qual incerteza permanece mesmo depois da confirmação da sala?","o":["A reparação do projetor","A presença de todos os diretores","A venda de ingressos para o ano seguinte"],"a":0,"e":"Quoiqu'ils aient confirmé la salle, ils ne peuvent toujours pas garantir que le projecteur sera réparé demain."},{"q":"Por que Claire não quer cancelar imediatamente?","o":["Porque não há público inscrito","Porque os diretores viajam de longe e o público já reservou","Porque o cinema vizinho já confirmou a reserva"],"a":1,"e":"Les réalisateurs viennent de loin et le public a déjà réservé."},{"q":"Que alternativa Antoine considera?","o":["Transferir o festival para outra cidade","Realizar o festival sem legendas","Consultar um cinema vizinho com equipamentos recentes"],"a":2,"e":"Tout petit qu'il soit, le cinéma voisin possède un équipement récent. Je pourrais leur demander s'ils accepteraient d'accueillir la projection."},{"q":"O que Antoine exige antes de anunciar uma mudança?","o":["Confirmação por escrito","Uma entrevista com a imprensa","Um novo cartaz impresso"],"a":0,"e":"Aussi solide que paraisse ce plan, je voudrais une confirmation écrite avant d'annoncer quoi que ce soit."}],"gaps":[{"s":"___ (quoique) la salle soit petite, elle convient au festival.","a":["Quoique"],"h":"Embora a sala seja pequena, ela serve para o festival."},{"s":"J'ai ___ vérifier, le fichier reste illisible.","a":["beau"],"h":"Por mais que eu confira, o arquivo continua ilegível."},{"s":"Si motivés que nous ___ (être, subjonctif présent), il faut un plan B.","a":["soyons"],"h":"Por mais motivados que estejamos, precisamos de um plano B."},{"s":"Aussi utile que ___ (paraître, subjonctif présent) cette solution, elle reste coûteuse.","a":["paraisse"],"h":"Por mais útil que essa solução pareça, ela continua cara."},{"s":"Quand bien même il ___ (accepter, conditionnel présent), le délai serait trop court.","a":["accepterait"],"h":"Mesmo que ele aceitasse, o prazo seria curto."},{"s":"___ petite qu'elle soit, la salle est bien équipée.","a":["Toute"],"h":"Embora seja bem pequena, a sala é bem equipada."}],"order":[{"t":["J'ai","beau","insister,","ils","refusent."],"h":"Por mais que eu insista, eles se recusam."},{"t":["Quoique","le","délai","soit","court,","essayons."],"h":"Embora o prazo seja curto, vamos tentar."},{"t":["Aussi","difficile","que","soit","la","situation,","continuons."],"h":"Por mais difícil que a situação seja, vamos continuar."}],"dict":[{"t":"Quoiqu'ils aient confirmé la salle, ils ne peuvent toujours pas garantir que le projecteur sera réparé demain."},{"t":"On a beau les appeler depuis trois jours, on obtient chaque fois la même réponse."},{"t":"Aussi frustrante que soit la situation, je préfère qu'on évite d'annuler trop vite. Les réalisateurs viennent de loin et le public a déjà réservé."},{"t":"Et quand bien même nous devrions changer de lieu, nous pourrions prévenir les spectateurs par courriel et afficher un plan à l'entrée du cinéma initial."},{"t":"Aussi solide que paraisse ce plan, je voudrais une confirmation écrite avant d'annoncer quoi que ce soit."}],"shadow":["Si compétente que soit leur équipe, elle ne peut pas inventer une pièce de rechange. Essayons de distinguer ce qui dépend d'eux de ce qui n'en dépend pas.","D'accord, mais quand bien même le projecteur fonctionnerait, il resterait le problème des sous-titres. Deux fichiers sont arrivés dans le mauvais format.","Tout petit qu'il soit, le cinéma voisin possède un équipement récent. Je pourrais leur demander s'ils accepteraient d'accueillir la projection.","Alors concentrons l'équipe dans la nouvelle salle. On aura beau préparer un dispositif parfait sur le papier, rien ne remplacera des consignes simples."],"write":{"task":"Descreva em cinco a sete frases um imprevisto profissional ou pessoal e defenda sua solução usando três estruturas diferentes de concessão.","ph":"Quoique …, nous avons décidé de … . J'ai beau …, mais …"},"cards":[["Embora seja tarde, ainda podemos tentar.","Quoiqu'il soit tard, nous pouvons encore essayer."],["Por mais que eu explique, ele não entende.","J'ai beau expliquer, il ne comprend pas."],["Por mais que insistam, a resposta não muda.","Ils ont beau insister, la réponse ne change pas."],["Por mais urgente que seja, precisamos conferir.","Si urgent que ce soit, nous devons vérifier."],["Por mais interessante que pareça, há riscos.","Aussi intéressant que cela paraisse, il y a des risques."],["Mesmo que ele aceitasse, seria tarde demais.","Quand bien même il accepterait, il serait trop tard."],["Embora seja pequeno, o espaço funciona bem.","Tout petit qu'il soit, cet espace fonctionne bien."],["Aconteça o que acontecer, avisaremos você.","Quoi qu'il arrive, nous vous préviendrons."],["Precisamos de um plano B viável.","Il nous faut un plan de secours crédible."],["Mesmo com esses problemas, não vou desistir.","Malgré ces difficultés, je ne renoncerai pas."]]},{"title":"Pourvu que ça marche","goal":"Formular condições, hipóteses e ressalvas com à condition que, pourvu que, au cas où, à moins que, en admettant que e à supposer que, distinguindo possibilidades reais de situações hipotéticas.","speakers":{"Inès":"f","Lucas":"m"},"setting":"Em Grenoble, Inès e Lucas organizam um fim de semana de atividades na montanha para um grupo de voluntários e discutem as condições para realizar o evento.","lines":[["Lucas","J'ai eu la responsable du refuge au téléphone. Elle accepte de nous accueillir à condition que nous confirmions le nombre de participants avant jeudi.","Falei com a responsável pelo refúgio por telefone. Ela aceita nos receber desde que confirmemos o número de participantes até quinta-feira."],["Inès","Ça me paraît raisonnable. Pourvu que tout le monde réponde à temps ! La dernière fois, certains ont confirmé leur présence le matin même.","Parece razoável. Tomara que todo mundo responda a tempo! Da última vez, alguns confirmaram a presença na própria manhã do evento."],["Lucas","J'ai prévu une solution de repli au cas où la météo serait mauvaise. On pourrait remplacer la randonnée par des ateliers à l'intérieur.","Preparei uma alternativa caso o tempo esteja ruim. Poderíamos substituir a caminhada por oficinas em um espaço fechado."],["Inès","Bonne idée. En admettant que le temps s'améliore samedi matin, est-ce qu'on pourrait quand même maintenir la sortie prévue l'après-midi ?","Boa ideia. Supondo que o tempo melhore no sábado de manhã, ainda poderíamos manter o passeio previsto para a tarde?"],["Lucas","Oui, à moins que les sentiers ne soient devenus trop glissants. Je préfère renoncer à une promenade plutôt que prendre un risque inutile.","Sim, a menos que as trilhas tenham ficado escorregadias demais. Prefiro desistir de um passeio a correr um risco desnecessário."],["Inès","À supposer que la randonnée soit annulée, il faudrait prévenir le guide assez tôt. Je ne voudrais pas qu'il se déplace pour rien.","Supondo que a caminhada seja cancelada, precisaríamos avisar o guia com antecedência. Não queria que ele se deslocasse à toa."],["Lucas","Je suis d'accord, mais je tiens à garder une certaine souplesse. On peut modifier le programme à condition que les participants soient informés clairement.","Concordo, mas faço questão de manter certa flexibilidade. Podemos alterar a programação desde que os participantes sejam informados com clareza."],["Inès","Au cas où quelqu'un aurait besoin d'un transport adapté, nous devrions le savoir avant de réserver le minibus. Tu as posé la question dans le formulaire ?","Caso alguém precise de transporte adaptado, deveríamos saber antes de reservar o micro-ônibus. Você perguntou isso no formulário?"],["Lucas","Oui, et j'ai précisé que chacun pouvait signaler ses besoins en privé. Pourvu que les réponses arrivent avant la clôture des inscriptions !","Sim, e esclareci que cada pessoa pode informar suas necessidades em particular. Tomara que as respostas cheguem antes do encerramento das inscrições!"],["Inès","À moins que le groupe ne dépasse vingt personnes, le minibus devrait suffire. Sinon, il faudra prévoir un deuxième véhicule.","A menos que o grupo ultrapasse vinte pessoas, o micro-ônibus deverá ser suficiente. Caso contrário, precisaremos providenciar outro veículo."],["Lucas","En admettant que nous obtenions une réduction sur l'hébergement, nous pourrions consacrer davantage d'argent aux repas. Le budget est vraiment serré.","Supondo que consigamos um desconto na hospedagem, poderíamos destinar mais dinheiro às refeições. O orçamento está realmente apertado."],["Inès","Je vais négocier avec le refuge. Ils feront peut-être un geste commercial, à condition qu'on réserve les deux nuits et pas seulement celle du samedi.","Vou negociar com o refúgio. Talvez concedam um desconto, desde que reservemos as duas noites, e não apenas a de sábado."],["Lucas","À supposer qu'ils refusent, on pourrait demander une participation supplémentaire de cinq euros. Mais je préférerais éviter cette solution.","Caso eles recusem, poderíamos pedir uma contribuição adicional de cinco euros. Mas eu preferiria evitar essa solução."],["Inès","Moi aussi. Pourvu que les frais restent accessibles à tous ! L'objectif, c'est de réunir les bénévoles, pas de sélectionner ceux qui peuvent payer.","Eu também. Tomara que os custos continuem acessíveis a todos! O objetivo é reunir os voluntários, não selecionar quem pode pagar."],["Lucas","Il reste une question : au cas où le guide devrait annuler au dernier moment, qui serait capable d'animer les activités de remplacement ?","Resta uma questão: caso o guia precise cancelar na última hora, quem seria capaz de conduzir as atividades alternativas?"],["Inès","Je peux m'en charger, à condition que Claire m'aide à préparer le matériel. J'ai déjà animé ce genre d'atelier, mais jamais toute seule.","Posso cuidar disso, desde que Claire me ajude a preparar o material. Já conduzi esse tipo de oficina, mas nunca sozinha."],["Lucas","Parfait. À moins qu'un imprévu majeur ne survienne, on devrait pouvoir maintenir le week-end. Je vais envoyer un récapitulatif ce soir.","Perfeito. A menos que aconteça algum imprevisto grave, devemos conseguir manter o fim de semana. Vou enviar um resumo hoje à noite."],["Inès","Fais ça. Et pourvu qu'on ait enfin un week-end sans mauvaise surprise ! Avec toutes ces précautions, on aura au moins limité les risques.","Faça isso. E tomara que finalmente tenhamos um fim de semana sem surpresas desagradáveis! Com todas essas precauções, pelo menos teremos reduzido os riscos."]],"grammar":[{"h":"À condition que e pourvu que: condição e desejo","p":["<b>À condition que + subjonctif</b> estabelece uma condição necessária. <b>Pourvu que + subjonctif</b> também indica condição, mas pode expressar um desejo intenso, como “tomara que”."],"ex":[["Nous partirons à condition que chacun confirme sa présence.","Partiremos desde que cada pessoa confirme sua presença."],["Je viendrai, pourvu que les horaires me conviennent.","Irei, contanto que os horários sejam adequados para mim."],["Pourvu qu'il fasse beau demain !","Tomara que faça tempo bom amanhã!"]],"tip":"À condition de + infinitif é possível quando as duas ações têm o mesmo sujeito."},{"h":"Au cas où + conditionnel: eventualidades","p":["<b>Au cas où</b> introduz uma eventualidade para a qual se prepara uma solução. No francês padrão, é normalmente seguido de <b>conditionnel</b>, ainda que o evento seja futuro."],"ex":[["Prends une veste au cas où il ferait froid.","Leve um casaco caso faça frio."],["Au cas où le train serait supprimé, nous prendrions un bus.","Caso o trem seja cancelado, pegaríamos um ônibus."],["Je garde son numéro au cas où j'en aurais besoin.","Guardo o número dele caso precise."]],"tip":"Compare si + indicatif: S'il pleut, nous resterons ici."},{"h":"À moins que: exceção","p":["<b>À moins que + subjonctif</b> introduz a circunstância que pode impedir algo. Na escrita cuidada, admite <b>ne explétif</b>, que não exprime negação e não exige pas."],"ex":[["Nous maintiendrons la sortie, à moins qu'il pleuve.","Manteremos o passeio, a menos que chova."],["Je signerai demain, à moins qu'un problème ne survienne.","Assinarei amanhã, a menos que apareça um problema."],["Tout sera prêt, à moins que la livraison soit retardée.","Tudo estará pronto, a menos que a entrega atrase."]],"tip":"À moins qu'il ne vienne pas contém uma negação real graças ao pas."},{"h":"En admettant que e à supposer que: hipóteses","p":["<b>En admettant que</b> e <b>à supposer que</b> admitem provisoriamente uma hipótese para desenvolver o raciocínio e pedem subjonctif. A consequência muitas vezes usa conditionnel."],"ex":[["En admettant qu'il accepte, que ferions-nous ensuite ?","Supondo que ele aceite, o que faríamos depois?"],["À supposer que nous ayons assez d'argent, où irions-nous ?","Supondo que tenhamos dinheiro suficiente, para onde iríamos?"],["En admettant que les chiffres soient exacts, le projet serait rentable.","Admitindo que os números estejam corretos, o projeto seria rentável."]],"tip":"Use-as para explorar possibilidades sem afirmar que acontecerão."}],"vocab":[{"h":"Planejamento e imprevistos","items":[["un refuge","um refúgio de montanha"],["une randonnée","uma caminhada em trilha"],["un sentier","uma trilha"],["une solution de repli","uma alternativa de emergência"],["un hébergement","uma hospedagem"],["un imprévu","um imprevisto"],["un transport adapté","um transporte adaptado"],["un récapitulatif","um resumo dos pontos principais"]]},{"h":"Negociação e organização","items":[["la clôture des inscriptions","o encerramento das inscrições"],["un budget serré","um orçamento apertado"],["faire un geste commercial","conceder uma vantagem comercial"],["les frais","os custos, as despesas"],["renoncer à","desistir de"],["se charger de","encarregar-se de"],["maintenir un événement","manter um evento"],["prévoir un créneau","reservar um horário"]]}],"pron":[{"h":"pourvu que","p":"Pourvu soa aproximadamente “pur-vü”, com o u francês produzido com os lábios arredondados.","w":["pourvu que","pourvu qu'il vienne","pourvu que ça marche"]},{"h":"au cas où","p":"A expressão soa aproximadamente “ô-ka-zü”. O s de cas faz ligação com où e produz z.","w":["au cas où","au cas où il pleuvrait","au cas où nous devrions partir"]},{"h":"à moins que","p":"Em moins, oin forma uma vogal nasal, aproximadamente “muẽ”; s final mudo diante de que.","w":["à moins que","à moins qu'il refuse","à moins qu'un problème survienne"]}],"mc":[{"q":"O que o refúgio exige para receber o grupo?","o":["Pagamento integral até segunda-feira","Confirmação do número de participantes até quinta-feira","Contratação obrigatória de dois guias"],"a":1,"e":"Elle accepte de nous accueillir à condition que nous confirmions le nombre de participants avant jeudi."},{"q":"Qual alternativa Lucas preparou para o mau tempo?","o":["Adiar o encontro por um mês","Cancelar todas as atividades","Substituir a caminhada por oficinas internas"],"a":2,"e":"On pourrait remplacer la randonnée par des ateliers à l'intérieur."},{"q":"E se houver mais de vinte pessoas?","o":["Será necessário outro veículo","Todos irão de trem","O encontro será cancelado"],"a":0,"e":"Sinon, il faudra prévoir un deuxième véhicule."},{"q":"Em que condição Inès aceita conduzir as oficinas?","o":["Se o guia estiver presente","Se Claire ajudar no material","Se o grupo tiver menos de dez pessoas"],"a":1,"e":"Je peux m'en charger, à condition que Claire m'aide à préparer le matériel."}],"gaps":[{"s":"Nous partirons à condition que chacun ___ (confirmer, subjonctif présent) sa présence.","a":["confirme"],"h":"Partiremos desde que cada pessoa confirme sua presença."},{"s":"Pourvu qu'il ne ___ (pleuvoir, subjonctif présent) pas demain !","a":["pleuve"],"h":"Tomara que não chova amanhã!"},{"s":"Au cas où le refuge ___ (être, conditionnel présent) fermé, nous chercherions un hôtel.","a":["serait"],"h":"Caso o refúgio esteja fechado, procuraríamos um hotel."},{"s":"Nous maintiendrons le départ, à moins que la météo ne ___ (changer, subjonctif présent).","a":["change"],"h":"Manteremos a partida, a menos que o tempo mude."},{"s":"En admettant que nous ___ (obtenir, subjonctif présent) un rabais, le budget suffirait.","a":["obtenions"],"h":"Supondo que consigamos um desconto, o orçamento seria suficiente."},{"s":"À supposer qu'ils ___ (venir, subjonctif présent), nous devrions prévoir plus de repas.","a":["viennent"],"h":"Supondo que eles venham, precisaríamos preparar mais refeições."}],"order":[{"t":["Pourvu","que","tout","se","passe","bien !"],"h":"Tomara que tudo corra bem!"},{"t":["Nous","partirons","à","condition","qu'il","vienne."],"h":"Partiremos desde que ele venha."},{"t":["Au","cas","où","il","pleuvrait,","restons","prudents."],"h":"Caso chova, vamos agir com prudência."}],"dict":[{"t":"J'ai eu la responsable du refuge au téléphone. Elle accepte de nous accueillir à condition que nous confirmions le nombre de participants avant jeudi."},{"t":"Bonne idée. En admettant que le temps s'améliore samedi matin, est-ce qu'on pourrait quand même maintenir la sortie prévue l'après-midi ?"},{"t":"Au cas où quelqu'un aurait besoin d'un transport adapté, nous devrions le savoir avant de réserver le minibus. Tu as posé la question dans le formulaire ?"},{"t":"À supposer qu'ils refusent, on pourrait demander une participation supplémentaire de cinq euros. Mais je préférerais éviter cette solution."},{"t":"Parfait. À moins qu'un imprévu majeur ne survienne, on devrait pouvoir maintenir le week-end. Je vais envoyer un récapitulatif ce soir."}],"shadow":["Ça me paraît raisonnable. Pourvu que tout le monde réponde à temps ! La dernière fois, certains ont confirmé leur présence le matin même.","Oui, à moins que les sentiers ne soient devenus trop glissants. Je préfère renoncer à une promenade plutôt que prendre un risque inutile.","À moins que le groupe ne dépasse vingt personnes, le minibus devrait suffire. Sinon, il faudra prévoir un deuxième véhicule.","Je peux m'en charger, à condition que Claire m'aide à préparer le matériel. J'ai déjà animé ce genre d'atelier, mais jamais toute seule."],"write":{"task":"Planeje uma viagem ou evento em seis a oito frases, com duas condições, um desejo, uma exceção e duas hipóteses.","ph":"Nous pourrions organiser … à condition que … . Pourvu que …"},"cards":[["Irei desde que você confirme.","Je viendrai à condition que tu confirmes."],["Tomara que dê certo!","Pourvu que ça marche !"],["Caso ele se atrase, começaremos sem ele.","Au cas où il serait en retard, nous commencerons sans lui."],["Partiremos, a menos que chova.","Nous partirons, à moins qu'il pleuve."],["Supondo que ela aceite, qual seria o próximo passo?","En admettant qu'elle accepte, quelle serait la prochaine étape ?"],["Caso tenhamos tempo, poderíamos visitar o centro.","À supposer que nous ayons le temps, nous pourrions visiter le centre."],["Tomara que ninguém desista.","Pourvu que personne ne renonce."],["Guardarei uma cópia caso precise.","Je garderai une copie au cas où j'en aurais besoin."],["Tudo depende de confirmarmos a reserva.","Tout dépend de la confirmation de notre réservation."],["Podemos adaptar o programa se necessário.","Nous pouvons adapter le programme si nécessaire."]]},{"title":"La mise en œuvre de...","goal":"Transformar ações verbais em estruturas nominais para redigir relatórios, comunicados e e-mails profissionais, mantendo clareza, precisão e um registro formal natural.","speakers":{"Inès":"f","Antoine":"m"},"setting":"Em Lille, Inès e Antoine revisam um relatório para a prefeitura sobre os primeiros meses de um serviço municipal de empréstimo de computadores.","lines":[["Antoine","J'ai terminé la première version du rapport, mais le texte ressemble encore trop à un compte rendu oral. On pourrait adopter un style plus institutionnel.","Terminei a primeira versão do relatório, mas o texto ainda parece muito um relato oral. Poderíamos adotar um estilo mais institucional."],["Inès","Montre-moi le début. Tu as écrit : Nous avons mis en place un service de prêt en janvier. C'est clair, mais on peut condenser la formulation.","Mostre o começo. Você escreveu: Implantamos um serviço de empréstimo em janeiro. Está claro, mas podemos tornar a formulação mais concisa."],["Antoine","Je proposerais : La mise en place du service de prêt a eu lieu en janvier. Ça met l'accent sur l'action plutôt que sur notre équipe.","Eu proporia: A implantação do serviço de empréstimo ocorreu em janeiro. Isso destaca a ação, não nossa equipe."],["Inès","Oui, mais gardons une phrase plus directe dans l'introduction. À force de nominaliser chaque verbe, on risque de rendre le rapport indigeste.","Sim, mas vamos manter uma frase mais direta na introdução. Se transformarmos todos os verbos em substantivos, corremos o risco de deixar o relatório indigesto."],["Antoine","Dans la section suivante, j'ai remplacé Nous avons distribué les ordinateurs par La distribution des ordinateurs. Le résultat est plus synthétique.","Na seção seguinte, substituí Distribuímos os computadores por A distribuição dos computadores. O resultado ficou mais sintético."],["Inès","Très bien. En revanche, précise que la distribution a été assurée par les agents des médiathèques. Leur contribution ne doit pas disparaître.","Muito bem. Em compensação, esclareça que a distribuição foi realizada pelos funcionários das bibliotecas. A contribuição deles não deve desaparecer."],["Antoine","D'accord. Pour les retards, j'ai écrit : Le déploiement des équipements a été reporté en raison de difficultés d'approvisionnement.","Certo. Sobre os atrasos, escrevi: A distribuição dos equipamentos foi adiada devido a dificuldades de abastecimento."],["Inès","C'est précis, à condition d'ajouter la durée du report. Un lecteur doit comprendre les conséquences concrètes, pas seulement les causes administratives.","Está preciso, desde que você acrescente a duração do adiamento. O leitor precisa entender as consequências concretas, não apenas as causas administrativas."],["Antoine","Pour les retours des usagers, j'hésite entre Nous avons recueilli leurs avis et Le recueil des avis des usagers. Tu préfères quoi ?","Quanto ao retorno dos usuários, estou em dúvida entre Reunimos as opiniões deles e A coleta das opiniões dos usuários. Qual você prefere?"],["Inès","La seconde formule convient à un intertitre. Dans le corps du texte, je garderais des verbes pour expliquer comment nous avons procédé.","A segunda formulação funciona como subtítulo. No corpo do texto, eu manteria verbos para explicar como fizemos o trabalho."],["Antoine","J'ai aussi ajouté : À la suite des réclamations, une modification des horaires a été décidée. C'est plus neutre que On a changé les horaires.","Também acrescentei: Após as reclamações, foi decidida uma alteração dos horários. É mais neutro do que Mudamos os horários."],["Inès","C'est neutre, mais un peu vague. Qui a pris cette décision ? Si le service municipal l'a prise, autant le dire explicitement.","É neutro, mas um pouco vago. Quem tomou essa decisão? Se foi o serviço municipal, é melhor dizer explicitamente."],["Antoine","Tu as raison. Je vais préciser : Le service municipal a décidé la modification des horaires afin de faciliter l'accès aux équipements.","Você tem razão. Vou especificar: O serviço municipal decidiu alterar os horários para facilitar o acesso aos equipamentos."],["Inès","Dans la conclusion, évoquons aussi l'amélioration du suivi des emprunts et la réduction du délai de traitement des demandes.","Na conclusão, vamos mencionar também a melhoria do acompanhamento dos empréstimos e a redução do prazo de processamento dos pedidos."],["Antoine","J'aimerais ajouter une recommandation : la prolongation du dispositif pendant six mois permettrait de mieux mesurer son efficacité.","Gostaria de acrescentar uma recomendação: a prorrogação do programa por seis meses permitiria avaliar melhor sua eficácia."],["Inès","Bonne idée. Et au lieu de dire Faire plus de publicité, écrivons Renforcement de la communication auprès des publics concernés.","Boa ideia. E em vez de escrever Fazer mais publicidade, vamos usar Reforço da comunicação com os públicos envolvidos."],["Antoine","Ça sonne effectivement plus professionnel. Cela dit, je vais supprimer quelques formulations trop lourdes pour éviter l'effet catalogue administratif.","Realmente soa mais profissional. Dito isso, vou eliminar algumas formulações pesadas demais para evitar aquele efeito de catálogo burocrático."],["Inès","Parfait. La précision du vocabulaire compte, mais la lisibilité reste essentielle. Un bon rapport doit pouvoir être compris sans dictionnaire administratif.","Perfeito. A precisão do vocabulário importa, mas a legibilidade continua essencial. Um bom relatório deve ser compreensível sem um dicionário de burocratês."]],"grammar":[{"h":"Nominalização: transformar verbos em substantivos","p":["A <b>nominalisation</b> transforma uma ação verbal em grupo nominal. É frequente em relatórios, notícias e documentos profissionais. Existem substantivos em -tion, -ment e -age, mas também formações irregulares."],"ex":[["Nous avons décidé de reporter le lancement.","Decidimos adiar o lançamento."],["Le report du lancement a été décidé.","Foi decidido o adiamento do lançamento."],["Le déploiement du service débutera en juin.","A implantação do serviço começará em junho."]],"tip":"Aprenda os pares distribuer/distribution, suivre/suivi e mettre en œuvre/mise en œuvre."},{"h":"Construção dos grupos nominais","p":["Os complementos antes ligados ao verbo passam frequentemente a ser introduzidos por <b>de</b>: distribuer les ordinateurs → la distribution des ordinateurs. Conserve as contrações do, du, des e um determinante adequado."],"ex":[["La réduction des délais constitue une priorité.","A redução dos prazos é uma prioridade."],["La validation du dossier reste nécessaire.","A validação do processo continua necessária."],["La mise à jour des informations est prévue.","A atualização das informações está prevista."]],"tip":"Observe la mise en œuvre du projet e l'accès aux services."},{"h":"Registro formal: causas, objetivos e consequências","p":["<b>En raison de</b> apresenta uma causa; <b>à la suite de</b>, um evento anterior; <b>afin de</b>, uma finalidade; e <b>dans le cadre de</b>, o contexto de uma ação."],"ex":[["Le lancement a été reporté en raison des travaux.","O lançamento foi adiado devido às obras."],["À la suite des remarques, le document a été modifié.","Após as observações, o documento foi alterado."],["Une réunion est prévue afin de clarifier les responsabilités.","Uma reunião está prevista para esclarecer as responsabilidades."],["Cette action s'inscrit dans le cadre du programme municipal.","Essa ação faz parte do programa municipal."]],"tip":"Escolha conectores que indiquem exatamente a relação lógica."},{"h":"Precisão sem excesso de burocratês","p":["A nominalização torna o texto conciso, mas seu excesso pode ocultar quem realizou a ação. Alterne frases nominais com verbos e identifique o agente sempre que a responsabilidade for relevante."],"ex":[["La réorganisation du service a été validée.","A reorganização do serviço foi aprovada."],["La direction a validé la réorganisation du service.","A direção aprovou a reorganização do serviço."],["Nous avons simplifié la procédure pour réduire les délais.","Simplificamos o procedimento para reduzir os prazos."]],"tip":"Se a frase acumular substantivos abstratos, experimente recuperar um verbo."}],"vocab":[{"h":"Substantivos do registro profissional","items":[["la mise en œuvre","a implementação"],["la mise en place","a implantação, a organização"],["le déploiement","a implantação em escala"],["le suivi","o acompanhamento"],["le recueil","a coleta"],["le report","o adiamento"],["la prolongation","a prorrogação"],["le renforcement","o reforço"]]},{"h":"Relatórios e administração","items":[["un compte rendu","um relato, uma ata resumida"],["un approvisionnement","um abastecimento"],["une réclamation","uma reclamação"],["un dispositif","um programa, um mecanismo"],["un usager","um usuário de serviço"],["un délai de traitement","um prazo de processamento"],["un intertitre","um subtítulo interno"],["la lisibilité","a legibilidade"]]},{"h":"Conectores formais úteis","items":[["en raison de","devido a"],["à la suite de","após, em decorrência de"],["afin de","a fim de"],["dans le cadre de","no âmbito de"],["auprès de","junto a"],["à cet effet","para esse fim"]]}],"pron":[{"h":"mise en œuvre","p":"Soa aproximadamente “miz-ã-neuvr”, com ligação entre mise e en e entre en e œuvre.","w":["la mise en œuvre","la mise en œuvre du projet","mettre en œuvre"]},{"h":"déploiement","p":"Oi tem som de “uá” e -ment é nasal: aproximadamente “dê-plua-mã”.","w":["un déploiement","le déploiement du service","le déploiement des équipements"]},{"h":"suivi e recueil","p":"Em suivi, ui combina o u francês com i, próximo de “süi-vi”. Em recueil, cuei produz uma sequência com vogal arredondada.","w":["le suivi","le recueil","le recueil des avis"]}],"mc":[{"q":"Por que Antoine quer alterar o relatório?","o":["Porque parece oral demais","Porque faltam valores financeiros","Porque precisa de tradução"],"a":0,"e":"Le texte ressemble encore trop à un compte rendu oral."},{"q":"Qual é a ressalva de Inès sobre nominalização?","o":["Deve aparecer apenas em títulos","É proibida em relatórios","Em excesso dificulta a leitura"],"a":2,"e":"À force de nominaliser chaque verbe, on risque de rendre le rapport indigeste."},{"q":"O que acrescentar sobre o adiamento?","o":["O nome do fornecedor","A duração do adiamento","O preço dos computadores"],"a":1,"e":"C'est précis, à condition d'ajouter la durée du report."},{"q":"Qual recomendação Antoine faz?","o":["Prorrogar o programa por seis meses","Encerrar o serviço","Substituir os equipamentos"],"a":0,"e":"La prolongation du dispositif pendant six mois permettrait de mieux mesurer son efficacité."}],"gaps":[{"s":"La ___ (distribuer, substantivo) des ordinateurs commencera lundi.","a":["distribution"],"h":"A distribuição dos computadores começará na segunda-feira."},{"s":"Le ___ (déployer, substantivo) du dispositif prendra trois semaines.","a":["déploiement"],"h":"A implantação do programa levará três semanas."},{"s":"La ___ (réduire, substantivo) des délais est une priorité.","a":["réduction"],"h":"A redução dos prazos é uma prioridade."},{"s":"Le lancement a été reporté en ___ de difficultés techniques.","a":["raison"],"h":"O lançamento foi adiado devido a dificuldades técnicas."},{"s":"Une réunion aura lieu afin ___ clarifier les responsabilités.","a":["de"],"h":"Uma reunião acontecerá para esclarecer as responsabilidades."},{"s":"La mise en œuvre ___ projet nécessite un suivi régulier.","a":["du"],"h":"A implementação do projeto exige acompanhamento regular."}],"order":[{"t":["La","distribution","des","équipements","a","commencé."],"h":"A distribuição dos equipamentos começou."},{"t":["Le","report","du","lancement","était","nécessaire."],"h":"O adiamento do lançamento era necessário."},{"t":["La","réduction","des","délais","reste","prioritaire."],"h":"A redução dos prazos continua sendo prioridade."}],"dict":[{"t":"J'ai terminé la première version du rapport, mais le texte ressemble encore trop à un compte rendu oral. On pourrait adopter un style plus institutionnel."},{"t":"Oui, mais gardons une phrase plus directe dans l'introduction. À force de nominaliser chaque verbe, on risque de rendre le rapport indigeste."},{"t":"C'est précis, à condition d'ajouter la durée du report. Un lecteur doit comprendre les conséquences concrètes, pas seulement les causes administratives."},{"t":"Tu as raison. Je vais préciser : Le service municipal a décidé la modification des horaires afin de faciliter l'accès aux équipements."},{"t":"Ça sonne effectivement plus professionnel. Cela dit, je vais supprimer quelques formulations trop lourdes pour éviter l'effet catalogue administratif."}],"shadow":["Montre-moi le début. Tu as écrit : Nous avons mis en place un service de prêt en janvier. C'est clair, mais on peut condenser la formulation.","Dans la section suivante, j'ai remplacé Nous avons distribué les ordinateurs par La distribution des ordinateurs. Le résultat est plus synthétique.","La seconde formule convient à un intertitre. Dans le corps du texte, je garderais des verbes pour expliquer comment nous avons procédé.","Bonne idée. Et au lieu de dire Faire plus de publicité, écrivons Renforcement de la communication auprès des publics concernés."],"write":{"task":"Redija um comunicado profissional de seis a oito frases sobre implantação, adiamento ou melhoria de um serviço, usando quatro nominalizações e dois conectores formais.","ph":"Dans le cadre de …, la mise en place de … a été réalisée … . En raison de …"},"cards":[["A implantação do serviço foi concluída.","La mise en place du service est terminée."],["A implementação do projeto começará em maio.","La mise en œuvre du projet débutera en mai."],["A distribuição dos equipamentos foi adiada.","La distribution des équipements a été reportée."],["A redução dos custos é uma prioridade.","La réduction des coûts est une priorité."],["O acompanhamento dos pedidos será reforçado.","Le suivi des demandes sera renforcé."],["O adiamento ocorreu devido a dificuldades técnicas.","Le report est intervenu en raison de difficultés techniques."],["Após as reclamações, o procedimento foi revisto.","À la suite des réclamations, la procédure a été revue."],["O objetivo é facilitar o acesso ao serviço.","L'objectif est de faciliter l'accès au service."],["A direção aprovou a reorganização.","La direction a validé la réorganisation."],["A prorrogação do programa está em estudo.","La prolongation du dispositif est à l'étude."]]},{"title":"Or, en effet, néanmoins","goal":"Construir argumentos complexos com or, en effet, néanmoins, d’ailleurs, toutefois, ainsi, en revanche e quitte à, diferenciando justificativa, oposição, concessão e consequência em textos e debates.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Em uma pequena redação em Rennes, Claire e Lucas preparam um artigo de opinião sobre a substituição de embalagens descartáveis por recipientes reutilizáveis nas cantinas universitárias.","lines":[["Claire","J'ai rédigé l'introduction de notre article. Les universités veulent réduire leurs déchets. Or, leurs cantines utilisent encore des milliers de barquettes jetables.","Redigi a introdução do nosso artigo. As universidades querem reduzir seus resíduos. No entanto, suas cantinas ainda usam milhares de embalagens descartáveis."],["Lucas","Le contraste est intéressant. Néanmoins, il faudrait éviter de laisser entendre que les établissements ne font aucun effort. Plusieurs expérimentent déjà des solutions.","O contraste é interessante. Mesmo assim, deveríamos evitar dar a entender que as instituições não fazem esforço algum. Várias já testam soluções."],["Claire","Tu as raison. J'ai d'ailleurs interrogé une responsable de cantine qui utilise des contenants consignés depuis six mois. Son retour est plutôt encourageant.","Você tem razão. Aliás, entrevistei uma responsável por uma cantina que utiliza recipientes com depósito há seis meses. O retorno dela é bastante positivo."],["Lucas","En effet, les étudiants rapportent la majorité des contenants. Mais il faut préciser que le dispositif repose sur une organisation assez rigoureuse.","De fato, os estudantes devolvem a maioria dos recipientes. Mas precisamos esclarecer que o sistema depende de uma organização bastante rigorosa."],["Claire","Ainsi, la cantine a prévu un point de collecte à chaque sortie. Les équipes récupèrent les boîtes, puis les envoient au lavage avant leur réutilisation.","Dessa forma, a cantina instalou um ponto de coleta em cada saída. As equipes recolhem os potes e os encaminham para lavagem antes da reutilização."],["Lucas","Le système réduit les emballages jetés. En revanche, il demande davantage de personnel pour le nettoyage et la gestion des retours.","O sistema reduz as embalagens descartadas. Em compensação, exige mais funcionários para a limpeza e a gestão das devoluções."],["Claire","C'est un point essentiel. Toutefois, les responsables affirment que ces dépenses pourraient diminuer avec une meilleure organisation.","Esse é um ponto essencial. Contudo, os responsáveis afirmam que essas despesas poderiam diminuir com uma organização melhor."],["Lucas","Je mettrais cette affirmation au conditionnel. En effet, nous n'avons pas encore de bilan complet permettant de vérifier les économies annoncées.","Eu colocaria essa afirmação no condicional. Afinal, ainda não temos um balanço completo que permita verificar a economia anunciada."],["Claire","D'accord. On pourrait écrire : Le dispositif semble prometteur ; néanmoins, son efficacité économique reste à confirmer sur une période plus longue.","Combinado. Poderíamos escrever: O sistema parece promissor; entretanto, sua eficiência econômica ainda precisa ser confirmada ao longo de um período maior."],["Lucas","Ça me convient. D'ailleurs, une autre université a abandonné son projet après quelques semaines, faute de moyens suffisants pour assurer le lavage.","Está bom para mim. Aliás, outra universidade abandonou o projeto depois de algumas semanas por falta de recursos suficientes para garantir a lavagem."],["Claire","Justement, il faudrait expliquer pourquoi les résultats diffèrent. Dans le premier établissement, les étudiants participent activement ; dans le second, ils étaient moins informés.","Justamente, precisaríamos explicar por que os resultados diferem. Na primeira instituição, os estudantes participam ativamente; na segunda, estavam menos informados."],["Lucas","Or, sans participation régulière des usagers, un système de consigne perd rapidement son intérêt. C'est un argument important pour notre conclusion.","Ora, sem a participação regular dos usuários, um sistema de depósito perde rapidamente sua utilidade. Esse é um argumento importante para nossa conclusão."],["Claire","On pourrait donc recommander une phase d'essai, quitte à investir davantage au départ pour former les équipes et informer les étudiants.","Poderíamos, portanto, recomendar uma fase de testes, mesmo que isso exija investir mais no início para treinar as equipes e informar os estudantes."],["Lucas","Oui, mais attention : quitte à dépenser davantage, autant mesurer précisément les résultats. Sinon, on risque de financer une bonne intention plutôt qu'une solution efficace.","Sim, mas atenção: se vamos gastar mais, melhor medir os resultados com precisão. Caso contrário, corremos o risco de financiar uma boa intenção, não uma solução eficaz."],["Claire","Je vois ce que tu veux dire. Ainsi, notre recommandation pourrait inclure trois indicateurs : les déchets évités, les coûts réels et le taux de retour.","Entendo seu ponto. Assim, nossa recomendação poderia incluir três indicadores: os resíduos evitados, os custos reais e a taxa de devolução."],["Lucas","Parfait. En revanche, je supprimerais le passage où nous opposons les étudiants responsables aux autres. Cette distinction est trop simpliste.","Perfeito. Por outro lado, eu eliminaria o trecho em que contrapomos os estudantes responsáveis aos demais. Essa distinção é simplista demais."],["Claire","Je suis d'accord. Toutefois, nous devons conserver une position claire : la réduction des déchets mérite des investissements, à condition d'en évaluer les effets.","Concordo. Contudo, precisamos manter uma posição clara: a redução dos resíduos merece investimentos, desde que seus efeitos sejam avaliados."],["Lucas","Alors concluons là-dessus. Un article convaincant ne se contente pas d'affirmer une bonne idée ; il montre aussi ses limites, ses conditions et ses conséquences.","Então vamos concluir com isso. Um artigo convincente não se limita a afirmar que uma ideia é boa; também mostra seus limites, suas condições e suas consequências."]],"grammar":[{"h":"Or e en effet: organizar o raciocínio","p":["<b>Or</b> introduz um fato ou uma premissa que muda o rumo do argumento; <b>en effet</b> sustenta ou confirma uma afirmação. En fait costuma corrigir ou reformular, e não justificar."],"ex":[["Le service doit être accessible. Or, les horaires sont limités.","O serviço precisa ser acessível. Ora, os horários são limitados."],["Le projet exige des moyens. En effet, le matériel coûte cher.","O projeto exige recursos. De fato, os equipamentos são caros."],["Les chiffres semblaient corrects. En fait, une erreur subsistait.","Os números pareciam corretos. Na verdade, ainda havia um erro."]],"tip":"Or introduz uma premissa; en effet a fundamenta."},{"h":"Néanmoins e toutefois: ressalvas","p":["<b>Néanmoins</b> e <b>toutefois</b> introduzem uma ressalva que não invalida completamente a ideia anterior. Néanmoins frequentemente enfatiza que algo continua válido apesar de uma dificuldade."],"ex":[["Les résultats sont encourageants. Néanmoins, restons prudents.","Os resultados são animadores. Mesmo assim, vamos manter a cautela."],["La méthode est fiable. Toutefois, elle reste coûteuse.","O método é confiável. Contudo, continua caro."],["Le projet a pris du retard ; néanmoins, il avance.","O projeto atrasou; apesar disso, está avançando."]],"tip":"Podem aparecer no início da frase ou entre vírgulas."},{"h":"D’ailleurs e en revanche: reforço e contraste","p":["<b>D’ailleurs</b> acrescenta informação que complementa ou reforça um argumento. <b>En revanche</b> contrapõe características, situações ou resultados; não equivale obrigatoriamente a concessão."],"ex":[["Cette solution fonctionne. D'ailleurs, plusieurs villes l'ont adoptée.","Essa solução funciona. Aliás, várias cidades a adotaram."],["Le système est simple. En revanche, son entretien coûte cher.","O sistema é simples. Em compensação, sua manutenção custa caro."],["Le premier modèle est rapide. Le second, en revanche, consomme moins.","O primeiro modelo é rápido. Já o segundo consome menos."]],"tip":"D’ailleurs acrescenta; en revanche contrapõe."},{"h":"Ainsi e quitte à: consequência e custo assumido","p":["<b>Ainsi</b> pode indicar consequência, conclusão ou exemplo. <b>Quitte à + infinitif</b> indica aceitar um inconveniente para alcançar algo: “mesmo que seja preciso” ou “já que vamos...”."],"ex":[["Les demandes ont augmenté. Ainsi, le service a été renforcé.","Os pedidos aumentaram. Assim, o serviço foi reforçado."],["Quitte à attendre, autant le faire confortablement.","Já que vamos esperar, melhor fazê-lo com conforto."],["Nous poursuivrons le projet, quitte à réduire son ampleur.","Continuaremos o projeto, mesmo que seja preciso reduzir sua dimensão."]],"tip":"Quitte à pede infinitivo, não subjonctif."}],"vocab":[{"h":"Meio ambiente e serviços coletivos","items":[["une barquette jetable","uma embalagem descartável"],["un contenant réutilisable","um recipiente reutilizável"],["une consigne","um depósito reembolsável"],["un point de collecte","um ponto de coleta"],["le lavage","a lavagem"],["le taux de retour","a taxa de devolução"],["un déchet","um resíduo"],["une phase d'essai","uma fase de testes"]]},{"h":"Argumentação e avaliação","items":[["un argument convaincant","um argumento convincente"],["une réserve","uma ressalva"],["un bilan complet","um balanço completo"],["une affirmation","uma afirmação"],["une démarche rigoureuse","uma abordagem rigorosa"],["faute de moyens","por falta de recursos"],["mettre en évidence","evidenciar"],["reposer sur","basear-se em, depender de"]]},{"h":"Conectores argumentativos","items":[["or","ora; introdução de uma premissa"],["en effet","de fato; apresentação de justificativa"],["néanmoins","entretanto; ainda assim"],["toutefois","contudo; entretanto"],["d'ailleurs","aliás; além disso"],["en revanche","em compensação; por outro lado"],["ainsi","assim; dessa forma"],["quitte à","mesmo que seja preciso"]]}],"pron":[{"h":"néanmoins","p":"Pronúncia aproximada “nê-ã-muẽ”; a terminação é nasal, e o s final não se pronuncia.","w":["néanmoins","néanmoins, il faut attendre","néanmoins, les résultats progressent"]},{"h":"d’ailleurs","p":"A expressão soa aproximadamente “da-iêr”, com articulação fluida e r francês no final.","w":["d'ailleurs","d'ailleurs, je suis d'accord","d'ailleurs, plusieurs villes participent"]},{"h":"toutefois e en revanche","p":"Toutefois soa “tut-fua”, com s mudo; em revanche tem ch como em “chá”.","w":["toutefois","en revanche","toutefois, le coût reste élevé"]}],"mc":[{"q":"Qual contradição Claire apresenta?","o":["Não existem cantinas","Querem reduzir resíduos, mas usam descartáveis","Os estudantes rejeitam toda alimentação"],"a":1,"e":"Les universités veulent réduire leurs déchets. Or, leurs cantines utilisent encore des milliers de barquettes jetables."},{"q":"Qual dificuldade prática Lucas aponta?","o":["Falta de identificação","Desinteresse de todos","Mais trabalho de limpeza e devoluções"],"a":2,"e":"En revanche, il demande davantage de personnel pour le nettoyage et la gestion des retours."},{"q":"Por que Lucas usa cautela sobre economia?","o":["Ainda não há balanço completo","A experiência é ilegal","Os recipientes são importados"],"a":0,"e":"Nous n'avons pas encore de bilan complet permettant de vérifier les économies annoncées."},{"q":"Quais indicadores Claire recomenda?","o":["Notas e matrículas","Resíduos evitados, custos reais e devoluções","Distâncias e férias"],"a":1,"e":"Ainsi, notre recommandation pourrait inclure trois indicateurs : les déchets évités, les coûts réels et le taux de retour."}],"gaps":[{"s":"Le service doit être accessible. ___ (connecteur introduisant une prémisse), ses horaires restent limités.","a":["Or"],"h":"O serviço precisa ser acessível. Ora, seus horários continuam limitados."},{"s":"Les coûts sont élevés. En ___, le matériel nécessite un entretien régulier.","a":["effet"],"h":"Os custos são elevados. De fato, os equipamentos exigem manutenção regular."},{"s":"Les résultats sont encourageants. ___ (connecteur commençant par N), il reste des incertitudes.","a":["Néanmoins"],"h":"Os resultados são animadores. Mesmo assim, ainda existem incertezas."},{"s":"La première solution est rapide. En ___, la seconde est moins coûteuse.","a":["revanche"],"h":"A primeira solução é rápida. Em compensação, a segunda custa menos."},{"s":"Les demandes ont augmenté. ___ (connecteur de conséquence commençant par A), le service a recruté du personnel.","a":["Ainsi"],"h":"Os pedidos aumentaram. Assim, o serviço contratou funcionários."},{"s":"Quitte ___ investir davantage, autant mesurer les résultats.","a":["à"],"h":"Já que vamos investir mais, melhor medir os resultados."}],"order":[{"t":["Les","résultats","progressent.","Néanmoins,","restons","prudents."],"h":"Os resultados melhoram. Mesmo assim, vamos manter a cautela."},{"t":["En","revanche,","cette","solution","coûte","moins","cher."],"h":"Em compensação, essa solução custa menos."},{"t":["Quitte","à","changer,","autant","tout","revoir."],"h":"Já que vamos mudar, melhor rever tudo."}],"dict":[{"t":"Les universités veulent réduire leurs déchets. Or, leurs cantines utilisent encore des milliers de barquettes jetables."},{"t":"En effet, les étudiants rapportent la majorité des contenants."},{"t":"Le système réduit les emballages jetés. En revanche, il demande davantage de personnel pour le nettoyage et la gestion des retours."},{"t":"Or, sans participation régulière des usagers, un système de consigne perd rapidement son intérêt."},{"t":"On pourrait donc recommander une phase d'essai, quitte à investir davantage au départ pour former les équipes et informer les étudiants."}],"shadow":["Le contraste est intéressant. Néanmoins, il faudrait éviter de laisser entendre que les établissements ne font aucun effort.","C'est un point essentiel. Toutefois, les responsables affirment que ces dépenses pourraient diminuer avec une meilleure organisation.","Ça me convient. D'ailleurs, une autre université a abandonné son projet après quelques semaines, faute de moyens suffisants pour assurer le lavage.","Parfait. En revanche, je supprimerais le passage où nous opposons les étudiants responsables aux autres."],"write":{"task":"Escreva um artigo de oito a dez frases sobre medida ambiental ou tecnológica, com tese, justificativas, objeção, comparação e conclusão. Use cinco conectores.","ph":"Cette mesure présente plusieurs avantages. En effet, … . Or, … . Néanmoins, …"},"cards":[["O projeto é útil. No entanto, custa caro.","Le projet est utile. Néanmoins, il coûte cher."],["O objetivo é claro. Ora, faltam recursos.","L'objectif est clair. Or, les moyens manquent."],["De fato, os resultados confirmam essa hipótese.","En effet, les résultats confirment cette hypothèse."],["Aliás, vários especialistas concordam.","D'ailleurs, plusieurs experts sont d'accord."],["Contudo, precisamos considerar os riscos.","Toutefois, nous devons prendre en compte les risques."],["Em compensação, a segunda opção é mais simples.","En revanche, la deuxième option est plus simple."],["Assim, podemos reduzir as despesas.","Ainsi, nous pouvons réduire les dépenses."],["Mesmo que seja preciso adiar, manteremos o projeto.","Nous maintiendrons le projet, quitte à le reporter."],["Essa conclusão exige uma análise mais detalhada.","Cette conclusion nécessite une analyse plus approfondie."],["Um argumento sólido reconhece suas limitações.","Un argument solide reconnaît ses limites."]]},{"title":"Il semblerait que...","goal":"Expressar incerteza, prudência e diferentes graus de confiança com conditionnel de prudence, il semblerait que, sembler, paraître, il se peut que e sans doute, distinguindo rumores, hipóteses e informações confirmadas.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Na redação de um jornal local em Toulouse, Claire e Lucas verificam informações sobre uma possível reforma da biblioteca municipal antes de publicar uma notícia.","lines":[["Lucas","Tu as vu les messages qui circulent depuis ce matin ? La médiathèque du centre fermerait pendant plusieurs mois à partir de janvier.","Você viu as mensagens que estão circulando desde hoje cedo? A biblioteca do centro supostamente fecharia por vários meses a partir de janeiro."],["Claire","Oui, mais rien n'est officiellement confirmé. Il semblerait que la mairie envisage des travaux importants, sans avoir encore fixé de calendrier.","Sim, mas nada foi confirmado oficialmente. Ao que parece, a prefeitura está considerando obras importantes, sem ainda ter definido um cronograma."],["Lucas","D'après un employé, le bâtiment présenterait des problèmes d'isolation. Il aurait aussi besoin d'une rénovation complète du système électrique.","Segundo um funcionário, o prédio apresentaria problemas de isolamento. Também precisaria de uma reforma completa do sistema elétrico."],["Claire","Attention à la formulation. Le conditionnel permet de présenter ces informations avec prudence, mais il ne suffit pas à garantir leur fiabilité.","Cuidado com a formulação. O condicional permite apresentar essas informações com cautela, mas não basta para garantir sua confiabilidade."],["Lucas","Tu as raison. Il se peut que les travaux soient nécessaires, mais nous ignorons encore leur ampleur. Je vais demander un document officiel.","Você tem razão. Pode ser que as obras sejam necessárias, mas ainda desconhecemos sua dimensão. Vou solicitar um documento oficial."],["Claire","J'ai déjà contacté le service de communication. Leur réponse paraît assez vague : ils évoquent une réflexion en cours, sans annoncer de décision.","Já entrei em contato com a assessoria de comunicação. A resposta parece bastante vaga: mencionam uma análise em andamento, sem anunciar nenhuma decisão."],["Lucas","Il me semble que cette réponse confirme au moins l'existence d'un projet. En revanche, elle ne permet pas d'affirmer que la fermeture est décidée.","Parece-me que essa resposta confirma pelo menos a existência de um projeto. Por outro lado, não permite afirmar que o fechamento foi decidido."],["Claire","Exactement. Il semble que certaines options soient encore à l'étude. Nous devrions distinguer les faits établis des scénarios envisagés.","Exatamente. Parece que algumas opções ainda estão sendo estudadas. Deveríamos distinguir os fatos confirmados dos cenários considerados."],["Lucas","Sans doute cherchent-ils à éviter une annonce prématurée. Cela dit, les habitants méritent de savoir si leurs services habituels seront maintenus.","Provavelmente estão tentando evitar um anúncio precipitado. Dito isso, os moradores merecem saber se seus serviços habituais serão mantidos."],["Claire","Peut-être. Mais sans doute ne signifie pas sans aucun doute. Nous ne connaissons pas leurs intentions, alors évitons de les présenter comme certaines.","Talvez. Mas provavelmente não significa sem nenhuma dúvida. Não conhecemos as intenções deles, então vamos evitar apresentá-las como certezas."],["Lucas","Une solution provisoire serait apparemment envisagée dans un autre bâtiment. Toutefois, personne n'a confirmé que les collections pourraient y être transférées.","Ao que parece, uma solução provisória estaria sendo considerada em outro prédio. Contudo, ninguém confirmou que o acervo poderia ser transferido para lá."],["Claire","Cette option paraît intéressante, mais elle semble difficile à mettre en œuvre rapidement. Il faudrait notamment prévoir le transport et le personnel.","Essa opção parece interessante, mas aparentemente seria difícil implementá-la rapidamente. Seria necessário prever, entre outras coisas, o transporte e os funcionários."],["Lucas","Selon une association de lecteurs, plusieurs activités risqueraient d'être suspendues. Je préciserai qu'il s'agit de leur inquiétude, pas d'une décision officielle.","Segundo uma associação de leitores, várias atividades correriam o risco de ser suspensas. Vou esclarecer que essa é a preocupação deles, não uma decisão oficial."],["Claire","Bonne précaution. Il se pourrait aussi que certains ateliers soient déplacés plutôt qu'annulés. Attendons une réponse avant de tirer des conclusions.","Boa precaução. Também seria possível que algumas oficinas fossem transferidas em vez de canceladas. Vamos esperar uma resposta antes de tirar conclusões."],["Lucas","Je pourrais titrer : Une fermeture prolongée de la médiathèque serait à l'étude. Le lecteur comprendra immédiatement que l'information reste à confirmer.","Eu poderia usar o título: Um fechamento prolongado da biblioteca estaria em estudo. O leitor entenderá imediatamente que a informação ainda precisa ser confirmada."],["Claire","C'est acceptable, à condition d'expliquer dès le début ce que nous savons réellement. Une formulation prudente ne remplace jamais une vérification sérieuse.","É aceitável, desde que expliquemos logo no início o que realmente sabemos. Uma formulação cautelosa nunca substitui uma verificação séria."],["Lucas","Entendu. Si la mairie confirme les travaux, nous mettrons l'article à jour. Sinon, nous indiquerons clairement que plusieurs possibilités restent ouvertes.","Entendido. Se a prefeitura confirmar as obras, atualizaremos a matéria. Caso contrário, indicaremos claramente que várias possibilidades continuam em aberto."],["Claire","Parfait. Notre rôle n'est pas de transformer une hypothèse plausible en certitude, mais d'informer avec précision, même lorsque les réponses manquent.","Perfeito. Nosso papel não é transformar uma hipótese plausível em certeza, mas informar com precisão, mesmo quando faltam respostas."]],"grammar":[{"h":"Conditionnel de prudence: informações não confirmadas","p":["O <b>conditionnel de prudence</b> apresenta informações atribuídas a fontes mas ainda não confirmadas. Não representa necessariamente uma hipótese condicional. Seu uso não substitui a verificação."],"ex":[["Le directeur aurait annoncé son départ.","O diretor teria anunciado sua saída."],["La mairie envisagerait une nouvelle réglementation.","A prefeitura estaria considerando uma nova regulamentação."],["Plusieurs services seraient concernés par la réforme.","Vários serviços seriam afetados pela reforma."]],"tip":"Compare a afirmação a démissionné com a informação cautelosa aurait démissionné."},{"h":"Il semblerait que e il se peut que","p":["<b>Il semblerait que</b> expressa uma avaliação cautelosa, normalmente com subjonctif; <b>il se peut que</b> apresenta uma possibilidade e também pede subjonctif. Il se pourrait que torna a hipótese ainda mais distante."],"ex":[["Il semblerait que les négociations avancent.","Ao que parece, as negociações estão avançando."],["Il se peut que la réunion soit reportée.","É possível que a reunião seja adiada."],["Il se pourrait que nous ayons mal compris.","Pode ser que tenhamos entendido errado."]],"tip":"Observe formas do subjonctif como soit, aient, puissent."},{"h":"Sembler e paraître: impressões","p":["<b>Sembler</b> e <b>paraître</b> significam parecer. Podem ser usados com adjetivo ou infinitivo. Impessoal il semble que expressando incerteza normalmente pede subjonctif; il me semble que muitas vezes recebe indicatif ao apresentar a avaliação do falante."],"ex":[["Cette explication paraît convaincante.","Essa explicação parece convincente."],["Il semble que le problème soit plus complexe.","Parece que o problema é mais complexo."],["Il me semble que nous avons déjà abordé ce sujet.","Parece-me que já abordamos esse assunto."]],"tip":"Aprenda a construção completa e a diferença de perspectiva."},{"h":"Sans doute x sans aucun doute","p":["No francês atual, <b>sans doute</b> frequentemente significa provavelmente. <b>Sans aucun doute</b> indica forte confiança, sem nenhuma dúvida. Apparemment e peut-être expressam outros graus de certeza."],"ex":[["Il viendra sans doute demain.","Ele provavelmente virá amanhã."],["Cette décision aura sans aucun doute des conséquences.","Essa decisão terá, sem dúvida alguma, consequências."],["Apparemment, personne n'a été prévenu.","Ao que parece, ninguém foi avisado."]],"tip":"Não interprete sans doute automaticamente como certeza absoluta."}],"vocab":[{"h":"Informações e fontes","items":[["une source fiable","uma fonte confiável"],["une information confirmée","uma informação confirmada"],["un fait établi","um fato comprovado"],["une rumeur","um boato"],["une hypothèse plausible","uma hipótese plausível"],["une annonce prématurée","um anúncio precipitado"],["une vérification","uma verificação"],["un scénario envisagé","um cenário considerado"]]},{"h":"Graus de certeza","items":[["apparemment","aparentemente"],["probablement","provavelmente"],["sans doute","provavelmente"],["sans aucun doute","sem nenhuma dúvida"],["il semblerait que","ao que parece"],["il se peut que","é possível que"],["à première vue","à primeira vista"],["sous réserve de confirmation","sujeito a confirmação"]]}],"pron":[{"h":"sembler e semblerait","p":"O grupo bl é pronunciado sem vogal entre as consoantes; semblerait é próximo de “sã-blə-rè”.","w":["sembler","il semblerait","il semblerait que"]},{"h":"sans doute","p":"Sans tem vogal nasal “sã”; o s não se pronuncia e o t de doute é audível.","w":["sans doute","sans aucun doute","sans doute possible"]},{"h":"paraît e paraît-il","p":"O t de paraît é mudo isoladamente, mas aparece na ligação de paraît-il.","w":["il paraît","paraît-il","cela paraît probable"]}],"mc":[{"q":"O que se comenta sobre a biblioteca?","o":["Foi demolida","Fecharia por meses a partir de janeiro","Todas as atividades já foram transferidas"],"a":1,"e":"La médiathèque du centre fermerait pendant plusieurs mois à partir de janvier."},{"q":"Por que o conditionnel exige cautela?","o":["Não garante que a informação seja confiável","É proibido em notícias","Sempre indica certeza"],"a":0,"e":"Le conditionnel permet de présenter ces informations avec prudence, mais il ne suffit pas à garantir leur fiabilité."},{"q":"O que a resposta da prefeitura parece confirmar?","o":["A data de fechamento","A transferência do acervo","A existência de um projeto"],"a":2,"e":"Cette réponse confirme au moins l'existence d'un projet."},{"q":"Se as obras forem confirmadas, o que farão?","o":["Apagar a matéria","Atualizar a matéria","Publicar como rumor antigo"],"a":1,"e":"Si la mairie confirme les travaux, nous mettrons l'article à jour."}],"gaps":[{"s":"Selon plusieurs sources, le directeur ___ (envisager, conditionnel présent) de partir.","a":["envisagerait"],"h":"Segundo várias fontes, o diretor estaria considerando sair."},{"s":"Il semblerait que les discussions ___ (avancer, subjonctif présent).","a":["avancent"],"h":"Ao que parece, as discussões estão avançando."},{"s":"Il se peut que cette information ___ (être, subjonctif présent) inexacte.","a":["soit"],"h":"É possível que essa informação esteja incorreta."},{"s":"Cette proposition ___ (paraître, indicatif présent) raisonnable.","a":["paraît"],"h":"Essa proposta parece razoável."},{"s":"Il me semble que nous ___ (avoir, indicatif présent) assez de preuves.","a":["avons"],"h":"Parece-me que temos provas suficientes."},{"s":"Cette annonce aura sans ___ doute des conséquences.","a":["aucun"],"h":"Esse anúncio terá consequências, sem nenhuma dúvida."}],"order":[{"t":["Il","semblerait","que","la","situation","évolue."],"h":"Ao que parece, a situação está evoluindo."},{"t":["Cette","information","reste","à","confirmer."],"h":"Essa informação ainda precisa ser confirmada."},{"t":["Il","se","pourrait","qu'elle","ait","raison."],"h":"Pode ser que ela tenha razão."}],"dict":[{"t":"Tu as vu les messages qui circulent depuis ce matin ? La médiathèque du centre fermerait pendant plusieurs mois à partir de janvier."},{"t":"Attention à la formulation. Le conditionnel permet de présenter ces informations avec prudence, mais il ne suffit pas à garantir leur fiabilité."},{"t":"Exactement. Il semble que certaines options soient encore à l'étude. Nous devrions distinguer les faits établis des scénarios envisagés."},{"t":"Selon une association de lecteurs, plusieurs activités risqueraient d'être suspendues. Je préciserai qu'il s'agit de leur inquiétude, pas d'une décision officielle."},{"t":"Entendu. Si la mairie confirme les travaux, nous mettrons l'article à jour. Sinon, nous indiquerons clairement que plusieurs possibilités restent ouvertes."}],"shadow":["Oui, mais rien n'est officiellement confirmé. Il semblerait que la mairie envisage des travaux importants, sans avoir encore fixé de calendrier.","Tu as raison. Il se peut que les travaux soient nécessaires, mais nous ignorons encore leur ampleur. Je vais demander un document officiel.","Peut-être. Mais sans doute ne signifie pas sans aucun doute. Nous ne connaissons pas leurs intentions, alors évitons de les présenter comme certaines.","C'est acceptable, à condition d'expliquer dès le début ce que nous savons réellement. Une formulation prudente ne remplace jamais une vérification sérieuse."],"write":{"task":"Escreva de seis a oito frases sobre uma informação não confirmada, distinguindo fatos, rumores e hipóteses com quatro expressões de prudência.","ph":"Selon certaines informations, … . Il semblerait que … . Toutefois, …"},"cards":[["Ao que parece, o projeto será adiado.","Il semblerait que le projet soit reporté."],["O diretor teria deixado o cargo.","Le directeur aurait quitté ses fonctions."],["É possível que a situação mude.","Il se peut que la situation change."],["Essa informação ainda não foi confirmada.","Cette information n'a pas encore été confirmée."],["Parece-me que a proposta é viável.","Il me semble que la proposition est viable."],["A explicação parece pouco convincente.","L'explication paraît peu convaincante."],["Provavelmente teremos uma resposta amanhã.","Nous aurons sans doute une réponse demain."],["Sem dúvida alguma, isso terá consequências.","Sans aucun doute, cela aura des conséquences."],["É cedo demais para tirar conclusões.","Il est trop tôt pour tirer des conclusions."],["Precisamos distinguir fatos de suposições.","Nous devons distinguer les faits des suppositions."]]},{"title":"Il a souligné que...","goal":"Relatar declarações de outras pessoas com verbos precisos como déplorer, souligner, nier, concéder, reconnaître, s’indigner e faire remarquer, preservando a intenção e a fidelidade ao discurso original.","speakers":{"Claire":"f","Antoine":"m"},"setting":"Em Strasbourg, Claire e Antoine preparam a ata e o resumo público de uma reunião sobre a ampliação dos horários dos ônibus municipais.","lines":[["Claire","J'ai repris mes notes de la réunion d'hier. Le directeur des transports a souligné que la fréquentation des bus avait augmenté depuis septembre.","Revisei minhas anotações da reunião de ontem. O diretor de transportes destacou que o número de passageiros dos ônibus havia aumentado desde setembro."],["Antoine","Oui, mais il a également reconnu que certains quartiers restaient mal desservis le soir. Il faut conserver ces deux éléments dans notre compte rendu.","Sim, mas ele também reconheceu que alguns bairros continuavam mal atendidos à noite. Precisamos manter esses dois pontos no nosso resumo."],["Claire","Une habitante a déploré que le dernier bus parte avant vingt et une heures. Elle a expliqué que cela compliquait son retour du travail.","Uma moradora lamentou que o último ônibus saísse antes das nove da noite. Ela explicou que isso dificultava sua volta do trabalho."],["Antoine","Et le représentant des étudiants s'est indigné que les usagers n'aient pas été consultés avant la modification des horaires.","E o representante dos estudantes se indignou com o fato de os usuários não terem sido consultados antes da mudança dos horários."],["Claire","Le directeur a nié que cette modification ait été décidée sans aucune concertation. Il a cité deux réunions organisées avec des associations locales.","O diretor negou que essa mudança tivesse sido decidida sem nenhuma consulta. Ele mencionou duas reuniões organizadas com associações locais."],["Antoine","Attention : il n'a pas nié les difficultés rencontrées par les usagers. Il a seulement contesté l'absence totale de concertation.","Atenção: ele não negou as dificuldades enfrentadas pelos usuários. Contestou apenas a suposta ausência completa de consulta."],["Claire","Tu as raison. Je reformulerai ce passage. Le choix du verbe est important, parce qu'il peut modifier la portée d'une déclaration.","Você tem razão. Vou reformular esse trecho. A escolha do verbo é importante porque pode alterar o alcance de uma declaração."],["Antoine","La responsable de l'association a fait remarquer que deux réunions ne suffisaient pas à représenter l'ensemble des habitants.","A responsável pela associação observou que duas reuniões não bastavam para representar todos os moradores."],["Claire","Elle a également concédé que la municipalité avait augmenté le nombre de bus aux heures de pointe, tout en jugeant ces efforts insuffisants.","Ela também admitiu que a prefeitura havia aumentado o número de ônibus nos horários de pico, embora considerasse esses esforços insuficientes."],["Antoine","C'est une nuance essentielle. Concéder signifie admettre un point, souvent malgré une position critique. Ce n'est pas exactement approuver.","Essa é uma nuance essencial. Concéder significa admitir um ponto, muitas vezes apesar de uma postura crítica. Não é exatamente aprovar."],["Claire","Le directeur a ensuite affirmé que trois nouvelles lignes seraient testées au printemps. Il a précisé qu'aucune décision définitive n'avait été prise.","O diretor afirmou em seguida que três novas linhas seriam testadas na primavera. Ele esclareceu que nenhuma decisão definitiva havia sido tomada."],["Antoine","Il faut garder le conditionnel seraient : il correspond au futur vu depuis le moment de sa déclaration, pas nécessairement à une information incertaine.","Precisamos manter o condicional seraient: ele corresponde ao futuro visto a partir do momento da declaração, não necessariamente a uma informação incerta."],["Claire","Une conseillère municipale a toutefois fait remarquer que le budget prévu ne couvrait pas encore toutes les dépenses nécessaires.","Uma vereadora, entretanto, observou que o orçamento previsto ainda não cobria todas as despesas necessárias."],["Antoine","Le directeur l'a reconnu, puis il a souligné que des financements complémentaires étaient recherchés. Il n'a donc pas garanti leur obtention.","O diretor reconheceu isso e depois destacou que estavam sendo buscados recursos adicionais. Portanto, ele não garantiu que seriam obtidos."],["Claire","Je vais éviter d'écrire qu'il a promis de financer les nouvelles lignes. Ce serait une interprétation excessive de ses propos.","Vou evitar escrever que ele prometeu financiar as novas linhas. Isso seria uma interpretação exagerada do que ele disse."],["Antoine","Bonne décision. Un compte rendu fidèle doit distinguer ce que quelqu'un affirme, ce qu'il reconnaît et ce qu'il se contente d'envisager.","Boa decisão. Um resumo fiel precisa distinguir aquilo que alguém afirma, aquilo que reconhece e aquilo que apenas considera."],["Claire","Pour finir, je préciserai que plusieurs participants ont demandé qu'une nouvelle consultation soit organisée avant toute décision définitive.","Para terminar, vou esclarecer que vários participantes solicitaram que uma nova consulta fosse organizada antes de qualquer decisão definitiva."],["Antoine","Parfait. Nous pouvons résumer les désaccords sans les amplifier. L'objectif n'est pas de rendre le débat plus spectaculaire, mais plus compréhensible.","Perfeito. Podemos resumir as divergências sem exagerá-las. O objetivo não é tornar o debate mais espetacular, e sim mais compreensível."]],"grammar":[{"h":"Souligner, faire remarquer e affirmer","p":["<b>Souligner que</b> destaca algo importante, <b>faire remarquer que</b> introduz uma observação, e <b>affirmer que</b> relata declaração firme. Em afirmações, seguem geralmente indicatif."],"ex":[["Elle a souligné que les résultats étaient encourageants.","Ela destacou que os resultados eram animadores."],["Il a fait remarquer que le délai était très court.","Ele observou que o prazo era muito curto."],["Le responsable a affirmé que le projet avançait.","O responsável afirmou que o projeto estava avançando."]],"tip":"Escolha o verbo por seu valor discursivo, não por variedade estilística apenas."},{"h":"Déplorer e s’indigner: reações","p":["<b>Déplorer que</b> apresenta um fato como lamentável; <b>s’indigner que</b> expressa indignação. Em geral exigem subjonctif, inclusive quando o acontecimento é real. A anterioridade pode pedir subjonctif passé."],"ex":[["Elle déplore que les horaires soient si limités.","Ela lamenta que os horários sejam tão restritos."],["Ils se sont indignés que personne ne les ait prévenus.","Eles se indignaram porque ninguém os havia avisado."],["Le directeur a déploré que cette mesure ait échoué.","O diretor lamentou que essa medida tivesse fracassado."]],"tip":"O subjonctif aqui decorre da avaliação emocional, não de irrealidade."},{"h":"Nier, reconnaître e concéder","p":["<b>Nier que</b> nega um fato e, na forma afirmativa, costuma pedir subjonctif. <b>Reconnaître que</b> admite um fato, e <b>concéder que</b> aceita um ponto apesar de discordâncias, normalmente com indicatif."],"ex":[["Il nie que cette décision soit définitive.","Ele nega que essa decisão seja definitiva."],["Elle a reconnu que le service était insuffisant.","Ela reconheceu que o serviço era insuficiente."],["Ils ont concédé que la proposition avait des avantages.","Eles admitiram que a proposta tinha vantagens."]],"tip":"Concéder não equivale a aprovar a conclusão de alguém."},{"h":"Discurso indireto e sequência dos tempos","p":["Após um verbo de discurso no passado, é comum adaptar présent → imparfait, passé composé → plus-que-parfait e futur simple → conditionnel présent. O conditionnel pode ser futuro no passado, sem indicar dúvida."],"ex":[["Il a déclaré qu'il travaillait sur une solution.","Ele declarou que estava trabalhando numa solução."],["Elle a expliqué qu'elle avait envoyé les documents.","Ela explicou que havia enviado os documentos."],["Le maire a annoncé que les travaux commenceraient en juin.","O prefeito anunciou que as obras começariam em junho."]],"tip":"Contextualize o futuro a partir do momento original da fala."}],"vocab":[{"h":"Verbos de discurso relatado","items":[["souligner","destacar, enfatizar"],["faire remarquer","observar, chamar a atenção"],["déplorer","lamentar"],["s'indigner","indignar-se"],["nier","negar"],["reconnaître","reconhecer"],["concéder","admitir, conceder um argumento"],["contester","contestar"]]},{"h":"Debates e declarações públicas","items":[["un compte rendu fidèle","um relato fiel"],["une concertation","uma consulta a interessados"],["un désaccord","uma divergência"],["une déclaration","uma declaração"],["la portée d'une déclaration","o alcance de uma declaração"],["une interprétation excessive","uma interpretação exagerada"],["une heure de pointe","um horário de pico"],["une consultation publique","uma consulta pública"]]}],"pron":[{"h":"souligner","p":"Em souligner, gn representa som de nh, sem g separado: “su-li-nhê”.","w":["souligner","il a souligné","souligner une difficulté"]},{"h":"déplorer","p":"Aproximadamente “dê-plo-rê”, com r francês e -er final soando ê.","w":["déplorer","elle a déploré","déplorer une décision"]},{"h":"reconnaître","p":"Oi tem som aproximado de “uá”; -aître soa “ètr”, com e final mudo.","w":["reconnaître","il a reconnu","reconnaître une erreur"]}],"mc":[{"q":"O que o diretor reconheceu?","o":["Todas as linhas seriam canceladas","Estudantes não participaram","Alguns bairros eram mal atendidos à noite"],"a":2,"e":"Il a également reconnu que certains quartiers restaient mal desservis le soir."},{"q":"Por que o representante estudantil se indignou?","o":["Falta de consulta prévia aos usuários","Ônibus gratuitos","Contratação de motoristas"],"a":0,"e":"Le représentant des étudiants s'est indigné que les usagers n'aient pas été consultés avant la modification des horaires."},{"q":"O que a responsável da associação concedeu?","o":["Serviço perfeito","Mais ônibus nos horários de pico","Todos desistiram das reivindicações"],"a":1,"e":"Elle a également concédé que la municipalité avait augmenté le nombre de bus aux heures de pointe,"},{"q":"Por que Claire não dirá que houve promessa de financiamento?","o":["A reunião foi cancelada","O orçamento estava aprovado","Seria exagero interpretar assim"],"a":2,"e":"Ce serait une interprétation excessive de ses propos."}],"gaps":[{"s":"Elle a ___ (souligner, participe passé) que le problème était urgent.","a":["souligné"],"h":"Ela destacou que o problema era urgente."},{"s":"Le responsable a déploré que les délais ___ (être, subjonctif présent) si longs.","a":["soient"],"h":"O responsável lamentou que os prazos fossem tão longos."},{"s":"Il nie que cette décision ___ (être, subjonctif présent) définitive.","a":["soit"],"h":"Ele nega que essa decisão seja definitiva."},{"s":"Elle a ___ (reconnaître, participe passé) que son équipe avait commis une erreur.","a":["reconnu"],"h":"Ela reconheceu que sua equipe tinha cometido um erro."},{"s":"Ils se sont indignés que personne ne les ___ (consulter, subjonctif passé) avant la décision.","a":["ait consultés"],"h":"Eles se indignaram porque ninguém os havia consultado antes da decisão."},{"s":"Le directeur a annoncé que les travaux ___ (commencer, futur dans le passé) en juillet.","a":["commenceraient"],"h":"O diretor anunciou que as obras começariam em julho."}],"order":[{"t":["Elle","a","souligné","que","le","projet","avançait."],"h":"Ela destacou que o projeto estava avançando."},{"t":["Il","a","reconnu","une","erreur","importante."],"h":"Ele reconheceu um erro importante."},{"t":["Ils","ont","contesté","la","décision","municipale."],"h":"Eles contestaram a decisão municipal."}],"dict":[{"t":"J'ai repris mes notes de la réunion d'hier. Le directeur des transports a souligné que la fréquentation des bus avait augmenté depuis septembre."},{"t":"Et le représentant des étudiants s'est indigné que les usagers n'aient pas été consultés avant la modification des horaires."},{"t":"La responsable de l'association a fait remarquer que deux réunions ne suffisaient pas à représenter l'ensemble des habitants."},{"t":"Une conseillère municipale a toutefois fait remarquer que le budget prévu ne couvrait pas encore toutes les dépenses nécessaires."},{"t":"Pour finir, je préciserai que plusieurs participants ont demandé qu'une nouvelle consultation soit organisée avant toute décision définitive."}],"shadow":["Oui, mais il a également reconnu que certains quartiers restaient mal desservis le soir. Il faut conserver ces deux éléments dans notre compte rendu.","Le directeur a nié que cette modification ait été décidée sans aucune concertation. Il a cité deux réunions organisées avec des associations locales.","C'est une nuance essentielle. Concéder signifie admettre un point, souvent malgré une position critique. Ce n'est pas exactement approuver.","Bonne décision. Un compte rendu fidèle doit distinguer ce que quelqu'un affirme, ce qu'il reconnaît et ce qu'il se contente d'envisager."],"write":{"task":"Relate em seis a oito frases uma reunião com posições diferentes, usando cinco verbos de discurso e diferenciando concordância, crítica e negação.","ph":"Lors de la réunion, la responsable a souligné que … . Un participant a toutefois déploré que …"},"cards":[["Ela destacou que os resultados melhoraram.","Elle a souligné que les résultats s'étaient améliorés."],["Ele lamentou que o prazo fosse tão curto.","Il a déploré que le délai soit si court."],["A direção negou que a decisão fosse definitiva.","La direction a nié que la décision soit définitive."],["Ela reconheceu que havia cometido um erro.","Elle a reconnu qu'elle avait commis une erreur."],["Ele admitiu que a proposta tinha vantagens.","Il a concédé que la proposition avait des avantages."],["Os moradores se indignaram com o atraso.","Les habitants se sont indignés du retard."],["Ela observou que faltavam informações.","Elle a fait remarquer que des informations manquaient."],["O diretor afirmou que o projeto continuaria.","Le directeur a affirmé que le projet se poursuivrait."],["Não devemos distorcer as declarações.","Nous ne devons pas déformer les déclarations."],["É importante relatar fielmente os fatos.","Il est important de rapporter fidèlement les faits."]]},{"title":"Soutenu, courant, familier","goal":"Reconhecer e utilizar conscientemente os registros soutenu, courant e familier, compreendendo palavras coloquiais, expressões de argot e formas frequentes de verlan como bagnole, boulot, flemme, relou, chelou e ouf.","speakers":{"Inès":"f","Lucas":"m"},"setting":"Num café em Montpellier, Inès e Lucas revisam mensagens para amigos e comunicados profissionais de uma associação de compartilhamento de veículos.","lines":[["Lucas","J'ai préparé deux messages pour annoncer notre nouveau service. L'un est destiné aux adhérents, l'autre au groupe de bénévoles. Tu peux les relire ?","Preparei duas mensagens para anunciar nosso novo serviço. Uma é destinada aos associados, a outra ao grupo de voluntários. Pode revisar?"],["Inès","Bien sûr. Mais pourquoi tu as écrit Notre nouvelle bagnole est enfin disponible dans le communiqué officiel ? Ça fait vraiment trop familier.","Claro. Mas por que você escreveu Nossa nova caranga finalmente está disponível no comunicado oficial? Soa informal demais."],["Lucas","Ah oui, j'ai copié la phrase du groupe de discussion. Entre amis, on dit facilement bagnole. Dans un communiqué, véhicule serait plus approprié.","Ah, sim, copiei a frase do grupo de conversa. Entre amigos, a gente fala facilmente caranga. Num comunicado, veículo seria mais apropriado."],["Inès","Exactement. Voiture est courant, bagnole est familier et véhicule convient mieux au registre administratif. Le sens est proche, mais l'effet change.","Exatamente. Voiture é neutro, bagnole é coloquial e véhicule combina melhor com o registro administrativo. O sentido é próximo, mas o efeito muda."],["Lucas","Dans le message aux bénévoles, j'ai aussi écrit : Quel boulot de relou, cette inscription ! C'était censé être une plaisanterie.","Na mensagem aos voluntários, também escrevi: Que trabalho chato pra caramba, essa inscrição! Era para ser uma brincadeira."],["Inès","Je comprends, mais relou peut paraître assez négatif. C'est du verlan de lourd, et ça signifie pénible ou agaçant selon le contexte.","Entendo, mas relou pode soar bastante negativo. É verlan de lourd e significa chato, inconveniente ou irritante, dependendo do contexto."],["Lucas","D'ailleurs, quelqu'un m'a répondu que le formulaire était chelou. J'ai d'abord cru qu'il parlait d'un problème technique précis.","Aliás, alguém me respondeu que o formulário era chelou. No começo achei que estivesse falando de um problema técnico específico."],["Inès","Pas forcément. Chelou vient de louche et veut dire bizarre ou suspect. C'est vague ; mieux vaut demander ce qui lui semble étrange.","Não necessariamente. Chelou vem de louche e significa estranho ou suspeito. É vago; melhor perguntar o que parece estranho para a pessoa."],["Lucas","Et quand un bénévole a écrit C'est ouf, le nombre de demandes !, il exprimait plutôt son étonnement que sa colère, non ?","E quando um voluntário escreveu É surreal a quantidade de pedidos!, estava expressando mais surpresa do que raiva, certo?"],["Inès","Oui. Ouf vient de fou en verlan. Selon le ton, ça peut vouloir dire incroyable, impressionnant ou complètement fou, en bien ou en mal.","Sim. Ouf vem de fou em verlan. Dependendo do tom, pode significar incrível, impressionante ou completamente absurdo, positiva ou negativamente."],["Lucas","Pour être franc, j'ai parfois la flemme de chercher une formulation différente pour chaque public. Pourtant, je vois bien que c'est nécessaire.","Para ser sincero, às vezes me dá preguiça de procurar uma formulação diferente para cada público. Mas percebo que é necessário."],["Inès","Dire j'ai la flemme est très naturel entre proches. Dans un mail professionnel, tu dirais plutôt je manque de temps ou je n'ai pas eu le temps.","Dizer j'ai la flemme é muito natural entre pessoas próximas. Num e-mail profissional, você diria que está sem tempo ou que não teve tempo."],["Lucas","Donc pour le groupe, je peux écrire : Désolé, j'ai pas eu le temps de finir le truc. Mais au travail, il vaut mieux éviter cette formulation.","Então, no grupo, posso escrever: Foi mal, não tive tempo de terminar o negócio. Mas no trabalho é melhor evitar essa formulação."],["Inès","Oui, surtout avec des interlocuteurs que tu connais peu. À l'écrit formel, préfère : Je n'ai pas pu finaliser le document dans les délais prévus.","Sim, especialmente com pessoas que você conhece pouco. Na escrita formal, prefira: Não consegui finalizar o documento dentro dos prazos previstos."],["Lucas","Et pour demander une pièce justificative ? Entre collègues, je dirais Tu peux m'envoyer le document ? Avec un partenaire, Pourriez-vous me le transmettre ?","E para solicitar um comprovante? Entre colegas, eu diria Pode me mandar o documento? Com um parceiro, O senhor poderia encaminhá-lo?"],["Inès","Tout à fait. Inutile d'être excessivement solennel, mais adapte le vocabulaire, les pronoms et le degré de politesse à la relation.","Isso mesmo. Não precisa ser excessivamente solene, mas adapte o vocabulário, os pronomes e o nível de formalidade à relação."],["Lucas","Je comprends mieux. On peut garder un ton chaleureux dans un message officiel sans écrire comme dans un groupe de potes après le boulot.","Agora entendo melhor. Podemos manter um tom acolhedor numa mensagem oficial sem escrever como num grupo de amigos depois do expediente."],["Inès","Exactement. Et si quelqu'un trouve notre communication trop reloue, on lui demandera des exemples concrets, mais sans reprendre le mot dans notre réponse officielle !","Exatamente. E se alguém achar nossa comunicação chata demais, vamos pedir exemplos concretos, mas sem repetir a palavra na resposta oficial!"]],"grammar":[{"h":"Soutenu, courant e familier: adequação","p":["O <b>registre soutenu</b> emprega léxico e sintaxe cuidados, sobretudo em textos oficiais. <b>Courant</b> é o registro neutro; <b>familier</b> aparece entre pessoas próximas, com expressões coloquiais e estrutura menos monitorada."],"ex":[["Je vous prie de bien vouloir patienter.","Peço a gentileza de aguardar."],["Veuillez patienter quelques instants.","Por favor, aguarde alguns instantes."],["Attends deux secondes !","Espera dois segundos!"]],"tip":"A melhor escolha é adequada ao interlocutor, não necessariamente a mais formal."},{"h":"Argot: boulot, bagnole, flemme","p":["<b>Argot</b> é vocabulário informal, em parte integrado à fala cotidiana. <b>Boulot</b> é trabalho; <b>bagnole</b>, carro; <b>avoir la flemme de</b>, ter preguiça de fazer algo. Evite em documentos oficiais."],"ex":[["J'ai trouvé un nouveau boulot.","Consegui um emprego novo."],["Ma bagnole est encore en panne.","Meu carro está quebrado de novo."],["J'ai la flemme de sortir ce soir.","Estou com preguiça de sair hoje à noite."]],"tip":"Compare travail/boulot e voiture/bagnole."},{"h":"Verlan: relou, chelou, ouf","p":["<b>Verlan</b> inverte sílabas ou partes sonoras, às vezes com outras alterações. <b>Relou</b> vem de lourd, <b>chelou</b> de louche e <b>ouf</b> de fou. Não se pode inverter qualquer palavra livremente."],"ex":[["Ce type est vraiment relou.","Esse cara é muito inconveniente."],["Son histoire est un peu chelou.","A história dele é meio estranha."],["C'est ouf comme le temps passe vite !","É impressionante como o tempo passa rápido!"]],"tip":"Aprenda formas de verlan já estabelecidas."},{"h":"Sintaxe informal e polidez profissional","p":["Na fala familiar é comum omitir <b>ne</b> (j'ai pas compris) e fazer perguntas por entonação. Na escrita profissional, prefira a negação completa, conditionnel de politesse e tu/vous adequado."],"ex":[["J'ai pas compris ce qu'il veut.","Não entendi o que ele quer."],["Je n'ai pas compris votre demande.","Não compreendi sua solicitação."],["Pourriez-vous me transmettre le document ?","Poderia me encaminhar o documento?"]],"tip":"A ausência de ne é frequente na fala, mas não adequada a todos os contextos."}],"vocab":[{"h":"Três registros","items":[["un emploi / un travail / un boulot","um emprego, um trabalho, um trampo"],["un véhicule / une voiture / une bagnole","um veículo, um carro, uma caranga"],["une rémunération / un salaire / la paie","uma remuneração, um salário, o pagamento"],["se restaurer / manger / bouffer","alimentar-se, comer, bater uma boia"],["une résidence / une maison / une baraque","uma residência, uma casa, um barraco"],["un camarade / un ami / un pote","um colega, um amigo, um parceiro"],["être mécontent / être contrarié / en avoir marre","estar insatisfeito, contrariado, de saco cheio"],["une difficulté / un problème / une galère","uma dificuldade, um problema, um perrengue"]]},{"h":"Argot e verlan frequentes","items":[["relou","chato, inconveniente"],["chelou","estranho, suspeito"],["ouf","impressionante, louco, absurdo"],["avoir la flemme","estar com preguiça"],["un truc","uma coisa, um negócio"],["un pote","um amigo, um parceiro"],["une galère","um perrengue"],["ça me saoule","isso me irrita, me enche"]]},{"h":"Comunicação profissional","items":[["un communiqué","um comunicado"],["une pièce justificative","um documento comprobatório"],["transmettre un document","encaminhar um documento"],["finaliser","finalizar"],["dans les délais prévus","dentro dos prazos previstos"],["un interlocuteur","um interlocutor"],["un adhérent","um associado"],["un registre approprié","um registro adequado"]]}],"pron":[{"h":"boulot","p":"Boulot soa “bu-lô”, com t final mudo e ou semelhante ao u português.","w":["le boulot","après le boulot","un nouveau boulot"]},{"h":"relou e chelou","p":"Relou é próximo de “rə-lu”; chelou de “chə-lu”, com ch como em chuva.","w":["relou","chelou","c'est trop relou"]},{"h":"ouf e fou","p":"Fou é “fu”; ouf é “uf”, com f final audível.","w":["fou","ouf","c'est ouf"]}],"mc":[{"q":"Por que Inès critica bagnole no comunicado?","o":["É palavra desconhecida","Descreve só carro de luxo","É familiar demais"],"a":2,"e":"Ça fait vraiment trop familier."},{"q":"O que chelou significa?","o":["Estranho ou suspeito","Muito longo","Gratuito"],"a":0,"e":"Chelou vient de louche et veut dire bizarre ou suspect."},{"q":"Qual sentido de ouf?","o":["Sempre uma crítica","Surpresa ou intensidade, boa ou ruim","Imediatamente"],"a":1,"e":"Selon le ton, ça peut vouloir dire incroyable, impressionnant ou complètement fou, en bien ou en mal."},{"q":"O que Inès recomenda?","o":["Sempre o mais formal","Excluir gírias de toda fala","Adaptar vocabulário e polidez ao contexto"],"a":2,"e":"Adapte le vocabulaire, les pronoms et le degré de politesse à la relation."}],"gaps":[{"s":"Entre amis, on dit souvent ___ (équivalent familier de voiture).","a":["bagnole"],"h":"Entre amigos, muitas vezes se usa bagnole para carro."},{"s":"J'ai trouvé un nouveau ___ (équivalent familier de travail).","a":["boulot"],"h":"Consegui um emprego novo."},{"s":"J'ai la ___ de sortir ce soir.","a":["flemme"],"h":"Estou com preguiça de sair hoje à noite."},{"s":"Cette situation est vraiment ___ (verlan de lourd).","a":["relou"],"h":"Essa situação é muito chata."},{"s":"Son comportement paraît ___ (verlan de louche).","a":["chelou"],"h":"O comportamento dele parece estranho."},{"s":"Pourriez-vous me ___ (envoyer, registre professionnel) le document ?","a":["transmettre"],"h":"Poderia me encaminhar o documento?"}],"order":[{"t":["J'ai","la","flemme","de","sortir","ce","soir."],"h":"Estou com preguiça de sair hoje à noite."},{"t":["Ce","formulaire","est","un","peu","chelou."],"h":"Esse formulário é meio estranho."},{"t":["Pourriez-vous","me","transmettre","ce","document","demain ?"],"h":"Poderia me encaminhar esse documento amanhã?"}],"dict":[{"t":"J'ai préparé deux messages pour annoncer notre nouveau service. L'un est destiné aux adhérents, l'autre au groupe de bénévoles. Tu peux les relire ?"},{"t":"Exactement. Voiture est courant, bagnole est familier et véhicule convient mieux au registre administratif. Le sens est proche, mais l'effet change."},{"t":"Pas forcément. Chelou vient de louche et veut dire bizarre ou suspect. C'est vague ; mieux vaut demander ce qui lui semble étrange."},{"t":"Donc pour le groupe, je peux écrire : Désolé, j'ai pas eu le temps de finir le truc. Mais au travail, il vaut mieux éviter cette formulation."},{"t":"Je comprends mieux. On peut garder un ton chaleureux dans un message officiel sans écrire comme dans un groupe de potes après le boulot."}],"shadow":["Bien sûr. Mais pourquoi tu as écrit Notre nouvelle bagnole est enfin disponible dans le communiqué officiel ? Ça fait vraiment trop familier.","Dans le message aux bénévoles, j'ai aussi écrit : Quel boulot de relou, cette inscription ! C'était censé être une plaisanterie.","Oui. Ouf vient de fou en verlan. Selon le ton, ça peut vouloir dire incroyable, impressionnant ou complètement fou, en bien ou en mal.","Tout à fait. Inutile d'être excessivement solennel, mais adapte le vocabulaire, les pronoms et le degré de politesse à la relation."],"write":{"task":"Escreva uma mensagem informal para um amigo e outra profissional sobre o mesmo problema de trabalho, com três a quatro frases cada.","ph":"Salut ! J'ai eu une galère au boulot … / Bonjour, je souhaitais vous informer que …"},"cards":[["Esse trabalho está me deixando maluco.","Ce boulot me rend dingue."],["Meu carro quebrou de novo.","Ma bagnole est encore tombée en panne."],["Estou com preguiça de cozinhar.","J'ai la flemme de cuisiner."],["Esse cara é muito chato.","Ce mec est vraiment relou."],["Essa situação parece meio estranha.","Cette situation paraît un peu chelou."],["É impressionante como ele aprende rápido!","C'est ouf comme il apprend vite !"],["Tive um perrengue no trabalho.","J'ai eu une galère au boulot."],["Poderia me enviar os documentos solicitados?","Pourriez-vous m'envoyer les documents demandés ?"],["Não consegui concluir a tarefa no prazo.","Je n'ai pas pu terminer la tâche dans les délais."],["Precisamos adaptar o tom ao público.","Nous devons adapter le ton au public."]]},{"title":"Poser un lapin","goal":"Compreender e utilizar expressões idiomáticas frequentes no francês cotidiano, como avoir le cafard, poser un lapin, coûter les yeux de la tête e tomber dans les pommes, interpretando seu sentido figurado e sua adequação ao contexto.","speakers":{"Inès":"f","Antoine":"m"},"setting":"Em um café de Paris, Inès encontra Antoine depois de uma manhã complicada. Eles conversam sobre um encontro que não aconteceu e os preparativos de uma festa.","lines":[["Inès","Tu fais une drôle de tête. Qu'est-ce qui t'arrive ? On dirait que tu as le cafard depuis ce matin.","Você está com uma cara estranha. O que aconteceu? Parece que está meio para baixo desde hoje cedo."],["Antoine","Ne m'en parle pas ! J'avais rendez-vous avec un organisateur à neuf heures, et il m'a posé un lapin. Pas même un message d'excuse.","Nem me fale! Eu tinha uma reunião com um organizador às nove, e ele me deu um bolo. Nem sequer mandou uma mensagem se desculpando."],["Inès","Sérieusement ? Tu as attendu longtemps ? Ça m'énerve, les gens qui ne préviennent pas quand ils ont un empêchement.","Sério? Você esperou muito? Fico irritada com gente que não avisa quando tem um imprevisto."],["Antoine","Quarante minutes, sous la pluie. J'ai fini par appeler son bureau. Sa collègue m'a dit qu'il avait complètement oublié notre rendez-vous.","Quarenta minutos, na chuva. Acabei ligando para o escritório dele. A colega disse que ele tinha esquecido completamente da reunião."],["Inès","Il aurait au moins pu s'excuser lui-même. Mais ne te prends pas la tête : tu trouveras bien quelqu'un d'autre pour organiser la soirée.","Ele poderia pelo menos ter pedido desculpas pessoalmente. Mas não esquenta a cabeça: você vai encontrar outra pessoa para organizar a festa."],["Antoine","J'espère. J'ai regardé les tarifs de trois salles, et elles coûtent toutes les yeux de la tête. Notre budget ne suivra jamais.","Espero. Consultei os preços de três salões, e todos custam os olhos da cara. Nosso orçamento nunca vai dar conta."],["Inès","À ce point-là ? Je connais une petite salle associative. Elle n'a rien de luxueux, mais elle pourrait faire l'affaire.","Tudo isso? Conheço um pequeno salão comunitário. Não tem nada de luxuoso, mas pode servir."],["Antoine","Ça m'intéresse. Quand j'ai vu le premier devis, j'ai failli tomber dans les pommes. Ils demandaient presque le double de ce qu'on avait prévu.","Isso me interessa. Quando vi o primeiro orçamento, quase desmaiei. Estavam cobrando quase o dobro do que tínhamos previsto."],["Inès","Tu exagères un peu, non ? Tomber dans les pommes, c'est vraiment s'évanouir. Enfin, je suppose que tu emploies l'expression pour plaisanter.","Você está exagerando um pouco, não? Tomber dans les pommes significa realmente desmaiar. Bom, suponho que esteja usando a expressão para brincar."],["Antoine","Évidemment ! J'ai juste eu un choc en découvrant le prix. Je ne suis pas tombé par terre au milieu de l'agence.","Claro! Só fiquei chocado quando descobri o preço. Não caí no chão no meio da agência."],["Inès","Heureusement ! Et pour la décoration, tu as trouvé quelqu'un ? Il faudrait éviter de dépenser une fortune pour trois guirlandes.","Ainda bem! E para a decoração, encontrou alguém? Seria bom evitar gastar uma fortuna com três enfeites."],["Antoine","Claire m'a proposé son aide. Elle a le cœur sur la main, mais je ne veux pas lui faire porter tout le projet sur les épaules.","Claire se ofereceu para ajudar. Ela é muito generosa, mas não quero colocar o projeto inteiro nas costas dela."],["Inès","Tu as raison. On pourrait répartir les tâches. D'ailleurs, Lucas m'a dit qu'il voulait donner un coup de main pour la musique.","Você tem razão. Poderíamos dividir as tarefas. Aliás, Lucas me disse que queria dar uma mãozinha com a música."],["Antoine","Parfait. Ça me remonte le moral. À force de gérer les imprévus tout seul, j'avais l'impression d'être au bout du rouleau.","Perfeito. Isso me anima. De tanto lidar sozinho com os imprevistos, eu estava me sentindo no limite."],["Inès","Je comprends. Mais attention aux expressions dans ton courriel à la mairie. Évite d'écrire qu'on nous a posé un lapin.","Entendo. Mas cuidado com as expressões no seu e-mail para a prefeitura. Evite escrever que alguém nos deu um bolo."],["Antoine","Bien vu. Je dirai plutôt que notre interlocuteur ne s'est pas présenté au rendez-vous et que nous cherchons une solution de remplacement.","Boa observação. Vou dizer que nosso contato não compareceu à reunião e que estamos procurando uma alternativa."],["Inès","Exactement. Entre amis, les images rendent la conversation vivante. Dans un message officiel, mieux vaut privilégier la précision.","Exatamente. Entre amigos, essas imagens deixam a conversa mais viva. Numa mensagem oficial, é melhor priorizar a precisão."],["Antoine","D'accord. Finalement, cette journée n'est pas complètement fichue. Si on trouve une salle abordable, je pourrai enfin souffler un peu.","Combinado. No fim das contas, o dia não está totalmente perdido. Se encontrarmos um salão acessível, finalmente vou poder respirar um pouco."]],"grammar":[{"h":"Poser un lapin: faltar a um compromisso","p":["<b>Poser un lapin à quelqu’un</b> significa faltar a um encontro marcado, geralmente sem avisar. A pessoa prejudicada pode aparecer com lui ou leur: il m'a posé un lapin, elle lui a posé un lapin."],"ex":[["Il m'a posé un lapin hier soir.","Ele me deu um bolo ontem à noite."],["Elle lui a posé un lapin sans prévenir.","Ela deu um bolo nele sem avisar."],["Je déteste qu'on me pose un lapin.","Odeio quando alguém me dá um bolo."]],"tip":"No registro formal, prefira ne pas se présenter au rendez-vous."},{"h":"Avoir le cafard: tristeza e desânimo","p":["<b>Avoir le cafard</b> indica tristeza, melancolia ou desânimo geralmente passageiros; não necessariamente um diagnóstico clínico. <b>Donner le cafard</b> apresenta a causa do sentimento."],"ex":[["J'ai le cafard depuis dimanche.","Estou meio para baixo desde domingo."],["Elle a le cafard quand elle rentre de vacances.","Ela fica triste quando volta das férias."],["Cette musique me donne le cafard.","Essa música me deixa melancólico."]],"tip":"Avoir le cafard descreve o estado; donner le cafard, o que o provoca."},{"h":"Coûter les yeux de la tête: exagero expressivo","p":["<b>Coûter les yeux de la tête</b> é uma hipérbole familiar para custos extremamente elevados. Não expressa valor literal nem substitui uma estimativa numérica em documentos de orçamento."],"ex":[["Ce restaurant coûte les yeux de la tête.","Esse restaurante custa os olhos da cara."],["Leur nouvel appartement leur coûte les yeux de la tête.","O apartamento novo deles custa os olhos da cara."],["Cette réparation nous a coûté les yeux de la tête.","Esse conserto nos custou uma fortuna."]],"tip":"Em texto formal, use représenter un coût élevé ou dépasser le budget."},{"h":"Tomber dans les pommes e imagens figuradas","p":["<b>Tomber dans les pommes</b> significa desmaiar, mas pode ser usado exageradamente para surpresa. Avoir le cœur sur la main indica generosidade; donner un coup de main, ajudar; être au bout du rouleau, esgotamento."],"ex":[["Elle est tombée dans les pommes à cause de la chaleur.","Ela desmaiou por causa do calor."],["Il a le cœur sur la main.","Ele é muito generoso."],["Tu peux me donner un coup de main ?","Pode me dar uma mãozinha?"],["Je suis au bout du rouleau après cette semaine.","Estou esgotado depois desta semana."]],"tip":"Interprete a expressão inteira, com contexto e entonação."}],"vocab":[{"h":"Expressões idiomáticas do cotidiano","items":[["poser un lapin","dar um bolo"],["avoir le cafard","estar para baixo, triste"],["coûter les yeux de la tête","custar os olhos da cara"],["tomber dans les pommes","desmaiar"],["avoir le cœur sur la main","ser muito generoso"],["donner un coup de main","dar uma mãozinha"],["être au bout du rouleau","estar esgotado"],["se prendre la tête","esquentar a cabeça"]]},{"h":"Compromissos e contratempos","items":[["un empêchement","um imprevisto que impede comparecimento"],["un devis","um orçamento"],["faire l'affaire","servir, resolver o problema"],["répartir les tâches","dividir as tarefas"],["remonter le moral","levantar o astral"],["un interlocuteur","um contato, um interlocutor"],["une solution de remplacement","uma solução alternativa"],["souffler un peu","respirar um pouco, descansar"]]}],"pron":[{"h":"poser un lapin","p":"Soa aproximadamente “pô-zê-ã-la-pẽ”. Lapin termina com vogal nasal, sem n independente.","w":["poser un lapin","il m'a posé un lapin","on lui a posé un lapin"]},{"h":"avoir le cafard","p":"Cafard soa aproximadamente “ka-far”, com r francês e d final mudo.","w":["avoir le cafard","j'ai le cafard","ça me donne le cafard"]},{"h":"tomber dans les pommes","p":"Soa aproximadamente “tõ-bê-dã-lê-pom”, com vogais nasais em tomber e dans e s mudo em pommes.","w":["tomber dans les pommes","elle est tombée dans les pommes","j'ai failli tomber dans les pommes"]}],"mc":[{"q":"Por que Antoine estava desanimado?","o":["Perdeu o emprego","Alguém faltou ao encontro","A festa foi cancelada"],"a":1,"e":"Il m'a posé un lapin. Pas même un message d'excuse."},{"q":"O que significa custar les yeux de la tête?","o":["Ser muito caro","Exigir pagamento em dinheiro","Ser alugado por um dia"],"a":0,"e":"Elles coûtent toutes les yeux de la tête."},{"q":"Antoine realmente desmaiou?","o":["Sim, foi hospitalizado","Sim, mas acordou logo","Não, ele exagerou para brincar"],"a":2,"e":"J'ai juste eu un choc en découvrant le prix. Je ne suis pas tombé par terre au milieu de l'agence."},{"q":"O que Inès recomenda para o e-mail oficial?","o":["Usar expressões familiares","Preferir precisão em vez de imagens coloquiais","Omitir referência ao encontro"],"a":1,"e":"Dans un message officiel, mieux vaut privilégier la précision."}],"gaps":[{"s":"Il n'est pas venu au rendez-vous : il m'a posé un ___.","a":["lapin"],"h":"Ele não apareceu: me deu um bolo."},{"s":"Depuis son départ, elle a le ___.","a":["cafard"],"h":"Desde que ele partiu, ela anda meio triste."},{"s":"Cette réparation coûte les yeux de la ___.","a":["tête"],"h":"Esse conserto custa os olhos da cara."},{"s":"À cause de la chaleur, il est tombé dans les ___.","a":["pommes"],"h":"Por causa do calor, ele desmaiou."},{"s":"Elle aide tout le monde : elle a le cœur sur la ___.","a":["main"],"h":"Ela ajuda todo mundo: é muito generosa."},{"s":"Après cette semaine épuisante, je suis au bout du ___.","a":["rouleau"],"h":"Depois dessa semana exaustiva, estou no meu limite."}],"order":[{"t":["Il","m'a","posé","un","lapin","hier."],"h":"Ele me deu um bolo ontem."},{"t":["Cette","réparation","coûte","les","yeux","de","la","tête."],"h":"Esse conserto custa os olhos da cara."},{"t":["Tu","peux","me","donner","un","coup","de","main ?"],"h":"Pode me dar uma mãozinha?"}],"dict":[{"t":"Tu fais une drôle de tête. Qu'est-ce qui t'arrive ? On dirait que tu as le cafard depuis ce matin."},{"t":"Quarante minutes, sous la pluie. J'ai fini par appeler son bureau. Sa collègue m'a dit qu'il avait complètement oublié notre rendez-vous."},{"t":"Ça m'intéresse. Quand j'ai vu le premier devis, j'ai failli tomber dans les pommes. Ils demandaient presque le double de ce qu'on avait prévu."},{"t":"Tu as raison. On pourrait répartir les tâches. D'ailleurs, Lucas m'a dit qu'il voulait donner un coup de main pour la musique."},{"t":"Exactement. Entre amis, les images rendent la conversation vivante. Dans un message officiel, mieux vaut privilégier la précision."}],"shadow":["Ne m'en parle pas ! J'avais rendez-vous avec un organisateur à neuf heures, et il m'a posé un lapin. Pas même un message d'excuse.","Il aurait au moins pu s'excuser lui-même. Mais ne te prends pas la tête : tu trouveras bien quelqu'un d'autre pour organiser la soirée.","Évidemment ! J'ai juste eu un choc en découvrant le prix. Je ne suis pas tombé par terre au milieu de l'agence.","Bien vu. Je dirai plutôt que notre interlocuteur ne s'est pas présenté au rendez-vous et que nous cherchons une solution de remplacement."],"write":{"task":"Conte um imprevisto em cinco a sete frases, usando três expressões idiomáticas, e reformule uma frase em registro profissional.","ph":"L'autre jour, quelqu'un m'a posé un lapin … . J'avais le cafard parce que …"},"cards":[["Ele me deu um bolo ontem.","Il m'a posé un lapin hier."],["Hoje estou meio para baixo.","Aujourd'hui, j'ai le cafard."],["Essa viagem custou os olhos da cara.","Ce voyage a coûté les yeux de la tête."],["Ela desmaiou de repente.","Elle est tombée dans les pommes soudainement."],["Não esquenta a cabeça com isso.","Ne te prends pas la tête avec ça."],["Ele sempre ajuda os outros.","Il a vraiment le cœur sur la main."],["Preciso de uma mãozinha.","J'ai besoin d'un coup de main."],["Estou completamente esgotado.","Je suis complètement au bout du rouleau."],["Isso me deixou muito animado.","Ça m'a vraiment remonté le moral."],["Não leve essa expressão ao pé da letra.","Ne prends pas cette expression au pied de la lettre."]]},{"title":"Seriez-vous prêt à...?","goal":"Negociar condições, apresentar contrapropostas e convencer interlocutores com o conditionnel de politesse, concessões, argumentos e fórmulas de acordo, mantendo um tom profissional e colaborativo.","speakers":{"Claire":"f","Lucas":"m"},"setting":"Em Nantes, Lucas negocia com Claire, responsável por um centro cultural, o aluguel de uma sala para três oficinas gratuitas de formação digital.","lines":[["Claire","Bonjour Lucas. J'ai examiné votre demande de réservation. La salle est disponible les jeudis, mais le tarif habituel est de trois cents euros par soirée.","Olá, Lucas. Analisei seu pedido de reserva. A sala está disponível às quintas-feiras, mas o preço normal é de trezentos euros por noite."],["Lucas","Merci de nous recevoir. Votre espace répond parfaitement à nos besoins. Toutefois, notre budget ne nous permet pas de dépasser deux cent cinquante euros.","Obrigado por nos receber. Seu espaço atende perfeitamente às nossas necessidades. Contudo, nosso orçamento não permite ultrapassar duzentos e cinquenta euros."],["Claire","Je comprends votre contrainte. Néanmoins, le tarif comprend l'ouverture du bâtiment, le chauffage et la présence d'un agent d'accueil.","Entendo sua limitação. Mesmo assim, o preço inclui a abertura do prédio, o aquecimento e a presença de um funcionário na recepção."],["Lucas","Seriez-vous prête à envisager un tarif réduit si nous réservions trois soirées consécutives ? Cela vous garantirait une occupation régulière.","A senhora estaria disposta a considerar um preço reduzido se reservássemos três noites consecutivas? Isso garantiria uma ocupação regular do espaço."],["Claire","C'est une proposition intéressante. Je pourrais descendre à deux cent soixante euros par soirée, à condition que les dates soient fixées dès aujourd'hui.","É uma proposta interessante. Eu poderia baixar para duzentos e sessenta euros por noite, desde que as datas fossem definidas hoje."],["Lucas","J'apprécie votre effort. Cela dit, même avec cette réduction, nous dépasserions le montant prévu. Pourrions-nous examiner une autre formule ?","Agradeço seu esforço. Dito isso, mesmo com essa redução, ultrapassaríamos o valor previsto. Poderíamos analisar outra opção?"],["Claire","Je vous écoute. Il faudrait cependant que la solution reste viable pour le centre. Nous ne pouvons pas supprimer tous les frais.","Estou ouvindo. Porém, seria necessário que a solução continuasse viável para o centro. Não podemos eliminar todas as despesas."],["Lucas","Et si nos bénévoles s'occupaient de disposer les chaises et de remettre la salle en ordre ? Nous pourrions réduire le travail de votre équipe.","E se nossos voluntários organizassem as cadeiras e deixassem a sala em ordem? Poderíamos reduzir o trabalho da sua equipe."],["Claire","Ce serait envisageable. En revanche, nous devrions conserver un agent pour la fermeture et les questions de sécurité.","Isso seria possível. Em compensação, precisaríamos manter um funcionário para o fechamento e as questões de segurança."],["Lucas","Bien entendu. Dans ce cas, accepteriez-vous deux cent quarante euros par soirée ? En contrepartie, nous confirmerions les trois dates immédiatement.","Claro. Nesse caso, aceitaria duzentos e quarenta euros por noite? Em contrapartida, confirmaríamos as três datas imediatamente."],["Claire","Deux cent quarante euros, c'est inférieur à notre tarif réduit habituel. Pourtant, votre projet présente un intérêt pour les habitants du quartier.","Duzentos e quarenta euros é menos que nosso preço reduzido habitual. No entanto, o projeto de vocês é interessante para os moradores do bairro."],["Lucas","C'est précisément notre objectif. D'ailleurs, nous pourrions mentionner le centre culturel sur les supports de communication des ateliers.","Esse é exatamente nosso objetivo. Aliás, poderíamos mencionar o centro cultural nos materiais de divulgação das oficinas."],["Claire","Cette visibilité serait appréciable. Je pourrais accepter votre proposition, à condition que les activités se terminent au plus tard à vingt et une heures trente.","Essa divulgação seria interessante. Eu poderia aceitar a proposta, desde que as atividades terminassem até as nove e meia da noite."],["Lucas","Cela nous conviendrait. J'aurais néanmoins une dernière demande : serait-il possible d'utiliser le vidéoprojecteur sans supplément ?","Isso funcionaria para nós. Mas eu teria um último pedido: seria possível utilizar o projetor sem custo adicional?"],["Claire","Oui, pourvu que vous effectuiez un test technique avant la première séance. Nous ne pourrons pas assurer une assistance pendant les ateliers.","Sim, desde que façam um teste técnico antes da primeira sessão. Não poderemos oferecer suporte durante as oficinas."],["Lucas","C'est entendu. Si je résume, nous convenons de trois jeudis à deux cent quarante euros chacun, avec le vidéoprojecteur et les conditions évoquées.","Combinado. Resumindo, fechamos três quintas-feiras por duzentos e quarenta euros cada, com o projetor e as condições que discutimos."],["Claire","Exactement. Je vous enverrai une proposition écrite cet après-midi. Vous pourrez vérifier les horaires et les responsabilités avant de la signer.","Exatamente. Enviarei uma proposta por escrito hoje à tarde. Você poderá conferir os horários e as responsabilidades antes de assinar."],["Lucas","Parfait. Je vous remercie d'avoir cherché un terrain d'entente. Nous avons trouvé une solution qui tient compte des contraintes de chacun.","Perfeito. Agradeço por ter buscado um meio-termo. Encontramos uma solução que leva em consideração as limitações de cada lado."]],"grammar":[{"h":"Conditionnel de politesse: propor sem impor","p":["O <b>conditionnel présent</b> torna propostas e pedidos mais diplomáticos. Seriez-vous prêt(e) à + infinitif pergunta se a pessoa estaria disposta a fazer algo, com prêt/prête concordando com ela."],"ex":[["Seriez-vous prêt à revoir votre proposition ?","O senhor estaria disposto a rever sua proposta?"],["Pourriez-vous envisager une réduction ?","Poderia considerar um desconto?"],["Nous souhaiterions discuter des conditions.","Gostaríamos de discutir as condições."],["Cela vous conviendrait-il ?","Isso seria adequado para o senhor?"]],"tip":"Entonação e respeito às necessidades do interlocutor continuam fundamentais."},{"h":"Propostas e contrapartidas","p":["<b>Et si + imparfait</b> propõe uma alternativa de maneira natural, sem impor uma resposta. <b>En contrepartie</b> apresenta o que se oferece em troca de concessão. <b>À condition que</b> explicita uma exigência."],"ex":[["Et si nous partagions les frais ?","E se dividíssemos as despesas?"],["Nous pourrions avancer la date.","Poderíamos antecipar a data."],["En contrepartie, nous confirmerions immédiatement.","Em contrapartida, confirmaríamos imediatamente."],["J'accepterais à condition que les délais soient respectés.","Eu aceitaria desde que os prazos fossem respeitados."]],"tip":"Uma boa proposta apresenta benefícios para ambos os lados."},{"h":"Contra-argumentar sem romper a negociação","p":["<b>Je comprends votre point de vue</b>, <b>j’apprécie votre effort</b> e <b>je reconnais que</b> reconhecem argumentos antes da ressalva. Toutefois, néanmoins e cela dit introduzem objeções de maneira profissional."],"ex":[["Je comprends votre position. Toutefois, notre budget est limité.","Entendo sua posição. Contudo, nosso orçamento é limitado."],["J'apprécie votre proposition. Cela dit, le délai reste trop court.","Agradeço sua proposta. Dito isso, o prazo continua curto demais."],["Votre solution est intéressante. Néanmoins, elle pose un problème technique.","Sua solução é interessante. Mesmo assim, apresenta um problema técnico."]],"tip":"Explique o obstáculo concreto e proponha alternativas, em vez de apenas dizer non."},{"h":"Chegar a acordo e confirmar condições","p":["<b>Convenir de</b> significa combinar; <b>trouver un terrain d’entente</b>, chegar a uma solução aceitável. Si je résume e nous sommes donc d’accord sur permettent conferir termos. Detalhes relevantes devem ser confirmados por escrito."],"ex":[["Nous avons convenu d'un nouveau calendrier.","Chegamos a um acordo sobre um novo cronograma."],["Nous sommes parvenus à un accord satisfaisant.","Chegamos a um acordo satisfatório."],["Si je résume, le prix comprend le matériel.","Resumindo, o preço inclui os equipamentos."],["L'accord reste soumis à une confirmation écrite.","O acordo continua sujeito a uma confirmação por escrito."]],"tip":"Confirme preço, prazo, responsabilidades e condições antes de encerrar."}],"vocab":[{"h":"Negociações e propostas","items":[["une contreproposition","uma contraproposta"],["une concession","uma concessão"],["une contrepartie","uma contrapartida"],["un terrain d'entente","um meio-termo"],["un tarif réduit","um preço reduzido"],["une marge de négociation","uma margem de negociação"],["un accord","um acordo"],["une condition préalable","uma condição prévia"]]},{"h":"Argumentar e negociar","items":[["être prêt à","estar disposto a"],["envisager une possibilité","considerar uma possibilidade"],["revoir une proposition","rever uma proposta"],["faire un geste commercial","conceder uma vantagem comercial"],["tenir compte de","levar em consideração"],["parvenir à un accord","chegar a um acordo"],["convenir de","combinar"],["mettre par écrit","formalizar por escrito"]]}],"pron":[{"h":"seriez-vous","p":"Soa aproximadamente “sə-riê-vu”, com z ligado a vous.","w":["seriez-vous","seriez-vous prêt","seriez-vous prête à envisager"]},{"h":"pourriez-vous","p":"Soa aproximadamente “pu-riê-vu”, com ligação z ao pronome vous.","w":["pourriez-vous","pourriez-vous accepter","pourriez-vous envisager"]},{"h":"un terrain d’entente","p":"Terrain termina com vogal nasal. D'entente também tem en nasal; pronuncie o conjunto sem inserir vogais entre consoantes.","w":["un terrain d'entente","trouver un terrain d'entente","chercher un terrain d'entente"]}],"mc":[{"q":"Qual o preço habitual por noite?","o":["Duzentos e quarenta euros","Duzentos e cinquenta euros","Trezentos euros"],"a":2,"e":"Le tarif habituel est de trois cents euros par soirée."},{"q":"Qual limite financeiro informado?","o":["Duzentos e cinquenta euros","Duzentos euros","Trezentos euros"],"a":0,"e":"Notre budget ne nous permet pas de dépasser deux cent cinquante euros."},{"q":"Qual contrapartida Lucas oferece?","o":["Empresa de limpeza","Voluntários organizam e arrumam a sala","Desistir do projetor"],"a":1,"e":"Et si nos bénévoles s'occupaient de disposer les chaises et de remettre la salle en ordre ?"},{"q":"Qual acordo foi alcançado?","o":["Três noites a 300 euros","Uma noite a 260 euros","Três quintas a 240 euros, sob condições"],"a":2,"e":"Nous convenons de trois jeudis à deux cent quarante euros chacun, avec le vidéoprojecteur et les conditions évoquées."}],"gaps":[{"s":"___-vous (être, conditionnel présent) prêt à revoir votre tarif ?","a":["Seriez"],"h":"O senhor estaria disposto a rever seu preço?"},{"s":"___-vous (pouvoir, conditionnel présent) envisager une réduction ?","a":["Pourriez"],"h":"Poderia considerar um desconto?"},{"s":"Et si nous ___ (partager, imparfait) les frais ?","a":["partagions"],"h":"E se dividíssemos as despesas?"},{"s":"Nous ___ (accepter, conditionnel présent) votre offre sous certaines conditions.","a":["accepterions"],"h":"Aceitaríamos sua oferta sob certas condições."},{"s":"En ___, nous confirmerions les dates immédiatement.","a":["contrepartie"],"h":"Em contrapartida, confirmaríamos as datas imediatamente."},{"s":"Nous avons trouvé un terrain d'___ satisfaisant.","a":["entente"],"h":"Encontramos um meio-termo satisfatório."}],"order":[{"t":["Seriez-vous","prête","à","revoir","votre","proposition ?"],"h":"A senhora estaria disposta a rever sua proposta?"},{"t":["Et","si","nous","partagions","les","frais ?"],"h":"E se dividíssemos as despesas?"},{"t":["Nous","avons","finalement","trouvé","un","terrain","d'entente."],"h":"Finalmente encontramos um meio-termo."}],"dict":[{"t":"Bonjour Lucas. J'ai examiné votre demande de réservation. La salle est disponible les jeudis, mais le tarif habituel est de trois cents euros par soirée."},{"t":"Seriez-vous prête à envisager un tarif réduit si nous réservions trois soirées consécutives ? Cela vous garantirait une occupation régulière."},{"t":"Et si nos bénévoles s'occupaient de disposer les chaises et de remettre la salle en ordre ? Nous pourrions réduire le travail de votre équipe."},{"t":"Cette visibilité serait appréciable. Je pourrais accepter votre proposition, à condition que les activités se terminent au plus tard à vingt et une heures trente."},{"t":"Exactement. Je vous enverrai une proposition écrite cet après-midi. Vous pourrez vérifier les horaires et les responsabilités avant de la signer."}],"shadow":["Merci de nous recevoir. Votre espace répond parfaitement à nos besoins. Toutefois, notre budget ne nous permet pas de dépasser deux cent cinquante euros.","C'est une proposition intéressante. Je pourrais descendre à deux cent soixante euros par soirée, à condition que les dates soient fixées dès aujourd'hui.","Bien entendu. Dans ce cas, accepteriez-vous deux cent quarante euros par soirée ? En contrepartie, nous confirmerions les trois dates immédiatement.","C'est entendu. Si je résume, nous convenons de trois jeudis à deux cent quarante euros chacun, avec le vidéoprojecteur et les conditions évoquées."],"write":{"task":"Redija um e-mail de negociação de oito a dez frases, com contraproposta, justificativa, contrapartida e confirmação por escrito.","ph":"Bonjour, je vous remercie pour votre proposition. Seriez-vous prêt à envisager … ? En contrepartie, nous pourrions …"},"cards":[["O senhor estaria disposto a negociar?","Seriez-vous prêt à négocier ?"],["Poderíamos rever essas condições?","Pourrions-nous revoir ces conditions ?"],["Gostaríamos de propor uma alternativa.","Nous souhaiterions proposer une alternative."],["Entendo seu ponto de vista.","Je comprends votre point de vue."],["Contudo, nosso orçamento é limitado.","Toutefois, notre budget est limité."],["E se antecipássemos a entrega?","Et si nous avancions la livraison ?"],["Em contrapartida, confirmaríamos hoje.","En contrepartie, nous confirmerions aujourd'hui."],["Essa solução seria aceitável para nós.","Cette solution serait acceptable pour nous."],["Finalmente chegamos a um acordo.","Nous sommes finalement parvenus à un accord."],["Vamos confirmar tudo por escrito.","Confirmons tous les détails par écrit."]]},{"title":"Pour conclure","goal":"Preparar uma exposição oral estruturada e sintetizar documentos no estilo do DALF C1, introduzindo uma problemática, organizando argumentos, comparando perspectivas, apresentando nuances e concluindo com clareza.","speakers":{"Inès":"f","Lucas":"m"},"setting":"Na biblioteca de Bordeaux, Inès e Lucas treinam uma exposição oral para o DALF C1 a partir de dois textos sobre os benefícios e os limites do teletrabalho.","lines":[["Lucas","J'ai lu les deux documents sur le télétravail, mais je ne sais pas comment commencer mon exposé. J'ai peur de simplement répéter les textes.","Li os dois documentos sobre trabalho remoto, mas não sei como começar minha apresentação. Tenho medo de apenas repetir os textos."],["Inès","Commence par présenter le thème commun, puis formule une problématique. Par exemple : Le télétravail améliore-t-il réellement les conditions de travail ?","Comece apresentando o tema comum e depois formule uma questão central. Por exemplo: O trabalho remoto realmente melhora as condições de trabalho?"],["Lucas","D'accord. Le premier document insiste sur la flexibilité et les déplacements évités. Le second met davantage l'accent sur l'isolement et les inégalités.","Certo. O primeiro documento destaca a flexibilidade e os deslocamentos evitados. O segundo enfatiza mais o isolamento e as desigualdades."],["Inès","Voilà une bonne base. Mais au lieu de résumer les documents l'un après l'autre, essaie de faire ressortir leurs points de convergence et de divergence.","Esse é um bom começo. Mas, em vez de resumir os documentos um depois do outro, tente destacar seus pontos de convergência e divergência."],["Lucas","Je pourrais annoncer deux axes : d'abord les avantages du travail à distance, puis les conditions nécessaires pour éviter ses effets négatifs.","Poderia anunciar dois eixos: primeiro, as vantagens do trabalho a distância; depois, as condições necessárias para evitar seus efeitos negativos."],["Inès","C'est cohérent. Pour introduire le plan, dis simplement : Dans un premier temps, j'examinerai les bénéfices ; ensuite, j'aborderai les limites du dispositif.","É coerente. Para apresentar o plano, diga simplesmente: Primeiro, examinarei os benefícios; em seguida, abordarei os limites desse modelo."],["Lucas","Dans la première partie, je soulignerai que les deux auteurs reconnaissent un gain de souplesse, même s'ils n'en tirent pas les mêmes conclusions.","Na primeira parte, destacarei que os dois autores reconhecem um ganho de flexibilidade, embora não tirem as mesmas conclusões disso."],["Inès","Très bien. Tu peux ajouter : Ce qui ressort de ces documents, c'est que la liberté d'organisation ne profite pas également à tous les salariés.","Muito bem. Pode acrescentar: O que se destaca nesses documentos é que a liberdade de organização não beneficia igualmente todos os funcionários."],["Lucas","Ensuite, je nuancerai : certes, le télétravail réduit certains trajets ; néanmoins, il peut accroître l'isolement et brouiller la frontière entre travail et vie privée.","Depois, vou ponderar: é verdade que o trabalho remoto reduz alguns deslocamentos; entretanto, pode aumentar o isolamento e confundir os limites entre trabalho e vida pessoal."],["Inès","Excellent. Pense aussi à attribuer les idées à leurs sources : selon le premier auteur, tandis que le second souligne que... Cela évite les généralisations.","Excelente. Lembre-se também de atribuir as ideias às fontes: segundo o primeiro autor, enquanto o segundo destaca que... Isso evita generalizações."],["Lucas","Et si les documents présentent des chiffres différents ? Je ne voudrais pas donner l'impression qu'ils se contredisent forcément.","E se os documentos apresentarem números diferentes? Não gostaria de dar a impressão de que necessariamente se contradizem."],["Inès","Précise leur contexte : la période étudiée, le public concerné et la méthode utilisée. Deux résultats différents peuvent porter sur des réalités distinctes.","Esclareça o contexto: o período estudado, o público envolvido e o método utilizado. Dois resultados diferentes podem tratar de realidades distintas."],["Lucas","Pour la transition, je pourrais dire : Après avoir examiné les avantages, intéressons-nous maintenant aux conditions d'un télétravail équilibré.","Para a transição, eu poderia dizer: Depois de examinar as vantagens, vamos agora analisar as condições de um trabalho remoto equilibrado."],["Inès","Parfait. Pour conclure, réponds explicitement à la problématique. Ne te contente pas de dire que le sujet est complexe ou qu'il présente des avantages et des inconvénients.","Perfeito. Para concluir, responda explicitamente à questão central. Não se limite a dizer que o tema é complexo ou que apresenta vantagens e desvantagens."],["Lucas","Je dirais : En définitive, le télétravail peut améliorer les conditions de travail, à condition d'être accompagné de règles claires et adaptées.","Eu diria: Em última análise, o trabalho remoto pode melhorar as condições de trabalho, desde que seja acompanhado de regras claras e adequadas."],["Inès","Bonne conclusion. Si tu présentes une synthèse neutre des documents, évite d'y introduire ton opinion personnelle sans la distinguer clairement.","Boa conclusão. Se estiver apresentando uma síntese neutra dos documentos, evite inserir sua opinião pessoal sem diferenciá-la claramente."],["Lucas","Et pendant l'entretien, si l'examinateur me demande mon avis, je pourrai défendre une position, reconnaître ses limites et répondre aux objections.","E durante a entrevista, se o examinador pedir minha opinião, poderei defender uma posição, reconhecer seus limites e responder às objeções."],["Inès","Exactement. L'essentiel est de montrer que tu sais sélectionner les idées, les relier et construire un raisonnement clair, sans réciter un texte par cœur.","Exatamente. O essencial é mostrar que você sabe selecionar as ideias, relacioná-las e construir um raciocínio claro, sem recitar um texto decorado."]],"grammar":[{"h":"Introduzir o tema e formular a problemática","p":["Uma exposição C1 precisa apresentar o tema e uma <b>problématique</b>: questão central que exige análise. Use les documents portent sur, la question qui se pose est de savoir si e dans quelle mesure para orientar os argumentos."],"ex":[["Les documents portent sur les transformations du travail.","Os documentos tratam das transformações do trabalho."],["La question qui se pose est de savoir si cette évolution profite à tous.","A questão que se coloca é saber se essa evolução beneficia a todos."],["Nous pouvons nous demander dans quelle mesure ce modèle est durable.","Podemos nos perguntar em que medida esse modelo é sustentável."]],"tip":"A pergunta deve orientar o plano, sem apenas repetir o título."},{"h":"Estruturar a exposição e anunciar o plano","p":["Use <b>dans un premier temps</b>, ensuite, dans un second temps e enfin para orientar a progressão do raciocínio. Transições claras explicam a relação entre as partes."],"ex":[["Dans un premier temps, j'examinerai les principaux avantages.","Primeiro, examinarei as principais vantagens."],["J'aborderai ensuite les limites de cette approche.","Em seguida, abordarei os limites dessa abordagem."],["Passons maintenant aux conséquences sociales.","Passemos agora às consequências sociais."],["Après avoir présenté les causes, intéressons-nous aux solutions.","Depois de apresentar as causas, vamos analisar as soluções."]],"tip":"Prefira duas ou três partes bem articuladas a uma lista longa."},{"h":"Sintetizar documentos e comparar perspectivas","p":["Uma <b>synthèse de documents</b> organiza as informações por eixos comuns, identifica convergências e divergências e atribui ideias às fontes. Não reproduza textos um depois do outro nem misture opinião pessoal com síntese neutra."],"ex":[["Les deux documents s'accordent sur la nécessité d'une réforme.","Os dois documentos concordam sobre a necessidade de uma reforma."],["Le premier auteur insiste sur les bénéfices, tandis que le second souligne les risques.","O primeiro autor enfatiza os benefícios, enquanto o segundo destaca os riscos."],["Ces analyses divergent sur les conséquences à long terme.","Essas análises divergem quanto às consequências de longo prazo."]],"tip":"Agrupe os argumentos pelo tema e contextualize números e fontes."},{"h":"Nuancer, concluir e defender uma posição","p":["No C1, é preciso reconhecer limites e evitar afirmações absolutas: <b>certes... néanmoins</b>, <b>il convient de</b> e <b>cela ne signifie pas pour autant que</b>. A conclusão deve responder à problemática e distinguir opinião de interpretação."],"ex":[["Certes, cette mesure est utile ; néanmoins, elle présente des limites.","É verdade que essa medida é útil; entretanto, ela apresenta limitações."],["Cela ne signifie pas pour autant que toutes les difficultés soient résolues.","Isso não significa, porém, que todas as dificuldades estejam resolvidas."],["En définitive, une approche équilibrée semble préférable.","Em última análise, uma abordagem equilibrada parece preferível."],["Je reconnais cet argument, mais il convient de nuancer cette conclusion.","Reconheço esse argumento, mas é necessário ponderar essa conclusão."]],"tip":"Conclua com resposta à questão inicial, não um resumo genérico."}],"vocab":[{"h":"Estruturar uma apresentação","items":[["une problématique","uma questão central de análise"],["un axe d'analyse","um eixo de análise"],["une introduction","uma introdução"],["une transition","uma transição"],["une conclusion","uma conclusão"],["dans un premier temps","num primeiro momento"],["dans un second temps","num segundo momento"],["en définitive","em última análise"]]},{"h":"Sintetizar e argumentar","items":[["une synthèse","uma síntese"],["un point de convergence","um point de convergência"],["un point de divergence","um ponto de divergência"],["une nuance","uma ressalva"],["une objection","uma objeção"],["faire ressortir","destacar, evidenciar"],["étayer un argument","fundamentar um argumento"],["nuancer une affirmation","ponderar uma afirmação"]]},{"h":"Descrever documentos e perspectivas","items":[["selon l'auteur","segundo o autor"],["le document souligne que","o documento destaca que"],["les textes s'accordent sur","os textos concordam sobre"],["en revanche","em compensação"],["tandis que","enquanto"],["dans quelle mesure","em que medida"],["il convient de","convém, é necessário"],["pour conclure","para concluir"]]}],"pron":[{"h":"tout d’abord","p":"Soa aproximadamente “tu-da-bôr”, com o r final francês audível.","w":["tout d'abord","tout d'abord, je présenterai","je voudrais tout d'abord"]},{"h":"en revanche","p":"En inicial nasal, aproximadamente “ã-rə-vãch”, com ch como em chuva.","w":["en revanche","en revanche, le second auteur","le premier document ; en revanche, le second"]},{"h":"en définitive","p":"Soa aproximadamente “ã-dê-fi-ni-tiv”, com en inicial nasal e e final mudo.","w":["en définitive","en définitive, il semble","pour conclure, en définitive"]}],"mc":[{"q":"Qual a dificuldade inicial de Lucas?","o":["Não sabe ler","Não entende teletrabalho","Teme apenas repetir os textos"],"a":2,"e":"J'ai peur de simplement répéter les textes."},{"q":"O que Inès recomenda sobre os documentos?","o":["Identificar convergências e divergências","Traduzir integralmente","Ignorar o segundo"],"a":0,"e":"Essaie de faire ressortir leurs points de convergence et de divergence."},{"q":"Como Lucas organiza a apresentação?","o":["Conclusão antes da introdução","Vantagens e condições para evitar problemas","Apenas por autor"],"a":1,"e":"D'abord les avantages du travail à distance, puis les conditions nécessaires pour éviter ses effets négatifs."},{"q":"O que deve haver na conclusão?","o":["Novo assunto","Introdução repetida","Resposta à problemática"],"a":2,"e":"Pour conclure, réponds explicitement à la problématique."}],"gaps":[{"s":"Dans un premier ___, j'examinerai les avantages.","a":["temps"],"h":"Num primeiro momento, examinarei as vantagens."},{"s":"La question qui se ___ est de savoir si ce modèle est durable.","a":["pose"],"h":"A questão que se coloca é saber se esse modelo é sustentável."},{"s":"Les deux documents s'___ sur la nécessité d'une réforme.","a":["accordent"],"h":"Os dois documentos concordam sobre a necessidade de uma reforma."},{"s":"Le premier auteur souligne les avantages, ___ que le second insiste sur les risques.","a":["tandis"],"h":"O primeiro autor destaca as vantagens, enquanto o segundo enfatiza os riscos."},{"s":"Certes, cette mesure présente des avantages ; ___ (connecteur commençant par N), elle reste coûteuse.","a":["néanmoins"],"h":"É verdade que essa medida apresenta vantagens; entretanto, continua cara."},{"s":"En ___, une approche équilibrée semble préférable.","a":["définitive"],"h":"Em última análise, uma abordagem equilibrada parece preferível."}],"order":[{"t":["Les","documents","portent","sur","le","télétravail."],"h":"Os documentos tratam do trabalho remoto."},{"t":["Passons","maintenant","aux","limites","de","cette","approche."],"h":"Passemos agora aos limites dessa abordagem."},{"t":["En","définitive,","une","solution","équilibrée","semble","préférable."],"h":"Em última análise, uma solução equilibrada parece preferível."}],"dict":[{"t":"Commence par présenter le thème commun, puis formule une problématique."},{"t":"Essaie de faire ressortir leurs points de convergence et de divergence."},{"t":"Dans un premier temps, j'examinerai les bénéfices ; ensuite, j'aborderai les limites du dispositif."},{"t":"Pour conclure, réponds à la problématique."},{"t":"En définitive, le télétravail peut améliorer les conditions de travail, à condition d'être accompagné de règles claires et adaptées."}],"shadow":["Je pourrais annoncer deux axes : d'abord les avantages du travail à distance, puis les conditions nécessaires pour éviter ses effets négatifs.","Ce qui ressort de ces documents, c'est que la liberté d'organisation ne profite pas également à tous les salariés.","Après avoir examiné les avantages, intéressons-nous maintenant aux conditions d'un télétravail équilibré.","L'essentiel est de montrer que tu sais sélectionner les idées, les relier et construire un raisonnement clair, sans réciter un texte par cœur."],"write":{"task":"Prepare um roteiro de oito a dez frases para uma síntese de dois textos, com problemática, duas partes, comparação, nuance e conclusão.","ph":"Les deux documents portent sur … . Nous pouvons nous demander dans quelle mesure … . Dans un premier temps, j'examinerai …"},"cards":[["Os documentos abordam um tema atual.","Les documents abordent un sujet d'actualité."],["A questão central é saber se essa medida funciona.","La question centrale est de savoir si cette mesure fonctionne."],["Primeiro, examinarei os principais argumentos.","Dans un premier temps, j'examinerai les principaux arguments."],["Em seguida, analisarei suas limitações.","J'analyserai ensuite ses limites."],["Os dois autores concordam nesse ponto.","Les deux auteurs s'accordent sur ce point."],["Em contrapartida, suas conclusões são diferentes.","En revanche, leurs conclusions sont différentes."],["É necessário ponderar essa afirmação.","Il convient de nuancer cette affirmation."],["Passemos agora à segunda parte.","Passons maintenant à la deuxième partie."],["Para concluir, retomarei a questão inicial.","Pour conclure, je reviendrai sur la question initiale."],["Essa análise permite uma conclusão equilibrada.","Cette analyse permet de parvenir à une conclusion nuancée."]]}]}};
